(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("lysias-speeches-e", [{"sp": "HDR", "t": "Λόγοι"}, {"sp": "HDR", "t": "Αʹ. Ὑπὲρ τοῦ Ἐρατοσθένους φόνου ἀπολογία", "st": "1"}, {"sp": "N", "t": "περὶ πολλοῦ ἂν ποιησαίμην, ὦ ἄνδρες, τὸ τοιούτους ὑμᾶς ἐμοὶ δικαστὰς περὶ τούτου τοῦ πράγματος γενέσθαι, οἷοίπερ ἂν ὑμῖν αὐτοῖς εἴητε τοιαῦτα πεπονθότες· εὖ γὰρ οἶδ’ ὅτι, εἰ τὴν αὐτὴν γνώμην περὶ τῶν ἄλλων ἔχοιτε, ἥνπερ περὶ ὑμῶν αὐτῶν, οὐκ ἂν εἴη ὅστις οὐκ ἐπὶ τοῖς γεγενημένοις ἀγανακτοίη, ἀλλὰ πάντες ἂν περὶ τῶν τὰ τοιαῦτα ἐπιτηδευόντων τὰς ζημίας μικρὰς ἡγοῖσθε.", "st": "1.1"}, {"sp": "N", "t": "καὶ ταῦτα οὐκ ἂν εἴη μόνον παρ’ ὑμῖν οὕτως ἐγνωσμένα, ἀλλ’ ἐν ἁπάσῃ τῇ Ἑλλάδι· περὶ τούτου γὰρ μόνου τοῦ ἀδικήματος καὶ ἐν δημοκρατίᾳ καὶ ὀλιγαρχίᾳ ἡ αὐτὴ τιμωρία τοῖς ἀσθενεστάτοις πρὸς τοὺς τὰ μέγιστα δυναμένους ἀποδέδοται, ὥστε τὸν χείριστον τῶν αὐτῶν τυγχάνειν τῷ βελτίστῳ· οὕτως, ὦ ἄνδρες, ταύτην τὴν ὕβριν ἅπαντες ἄνθρωποι δεινοτάτην ἡγοῦνται.", "st": "1.2"}, {"sp": "N", "t": "περὶ μὲν οὖν τοῦ μεγέθους τῆς ζημίας ἅπαντας ὑμᾶς νομίζω τὴν αὐτὴν διάνοιαν ἔχειν, καὶ οὐδένα οὕτως ὀλιγώρως διακεῖσθαι, ὅστις οἴεται δεῖν συγγνώμης τυγχάνειν ἢ μικρᾶς ζημίας ἀξίους ἡγεῖται τοὺς τῶν τοιούτων ἔργων αἰτίους· ἡγοῦμαι δέ,", "st": "1.3"}, {"sp": "N", "t": "ὦ ἄνδρες, τοῦτό με δεῖν ἐπιδεῖξαι, ὡς ἐμοίχευεν Ἐρατοσθένης τὴν γυναῖκα τὴν ἐμὴν καὶ ἐκείνην τε διέφθειρε καὶ τοὺς παῖδας τοὺς ἐμοὺς ᾔσχυνε καὶ ἐμὲ αὐτὸν ὕβρισεν εἰς τὴν οἰκίαν τὴν ἐμὴν εἰσιών, καὶ οὔτε ἔχθρα ἐμοὶ καὶ ἐκείνῳ οὐδεμία ἦν πλὴν ταύτης, οὔτε χρημάτων ἕνεκα ἔπραξα ταῦτα, ἵνα πλούσιος ἐκ πένητος γένωμαι, οὔτε ἄλλου κέρδους οὐδενὸς πλὴν τῆς κατὰ τοὺς νόμους τιμωρίας.", "st": "1.4"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἐξ ἀρχῆς ὑμῖν ἅπαντα ἐπιδείξω τὰ ἐμαυτοῦ πράγματα, οὐδὲν παραλείπων, ἀλλὰ λέγων τἀληθῆ· ταύτην γὰρ ἐμαυτῷ μόνην ἡγοῦμαι σωτηρίαν, ἐὰν ὑμῖν εἰπεῖν ἅπαντα δυνηθῶ τὰ πεπραγμένα.", "st": "1.5"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ Ἀθηναῖοι, ἐπειδὴ ἔδοξέ μοι γῆμαι καὶ γυναῖκα ἠγαγόμην εἰς τὴν οἰκίαν, τὸν μὲν ἄλλον χρόνον οὕτω διεκείμην ὥστε μήτε λυπεῖν μήτε λίαν ἐπ’ ἐκείνῃ εἶναι ὅ τι ἂν ἐθέλῃ ποιεῖν, ἐφύλαττόν τε ὡς οἷόν τε ἦν, καὶ προσεῖχον τὸν νοῦν ὥσπερ εἰκὸς ἦν. ἐπειδὴ δέ μοι παιδίον γίγνεται, ἐπίστευον ἤδη καὶ πάντα τὰ ἐμαυτοῦ ἐκείνῃ παρέδωκα, ἡγούμενος ταύτην οἰκειότητα μεγίστην εἶναι· ἐν μὲν οὖν τῷ πρώτῳ χρόνῳ,", "st": "1.6"}, {"sp": "N", "t": "ὦ Ἀθηναῖοι, πασῶν ἦν βελτίστη· καὶ γὰρ οἰκονόμος δεινὴ καὶ φειδωλὸς [ἀγαθὴ] καὶ ἀκριβῶς πάντα διοικοῦσα· ἐπειδὴ δέ μοι ἡ μήτηρ ἐτελεύτησε, πάντων τῶν κακῶν ἀποθανοῦσα αἰτία μοι γεγένηται.", "st": "1.7"}, {"sp": "N", "t": "ἐπ’ ἐκφορὰν γὰρ αὐτῇ ἀκολουθήσασα ἡ ἐμὴ γυνὴ ὑπὸ τούτου τοῦ ἀνθρώπου ὀφθεῖσα, χρόνῳ διαφθείρεται· ἐπιτηρῶν γὰρ τὴν θεράπαιναν τὴν εἰς τὴν ἀγορὰν βαδίζουσαν καὶ λόγους προσφέρων ἀπώλεσεν αὐτήν.", "st": "1.8"}, {"sp": "N", "t": "πρῶτον μὲν οὖν, ὦ ἄνδρες, (δεῖ γὰρ καὶ ταῦθ’ ὑμῖν διηγήσασθαι) οἰκίδιον ἔστι μοι διπλοῦν, ἴσα ἔχον τὰ ἄνω τοῖς κάτω κατὰ τὴν γυναικωνῖτιν καὶ κατὰ τὴν ἀνδρωνῖτιν. ἐπειδὴ δὲ τὸ παιδίον ἐγένετο ἡμῖν, ἡ μήτηρ αὐτὸ ἐθήλαζεν· ἵνα δὲ μή, ὁπότε λοῦσθαι δέοι, κινδυνεύῃ κατὰ τῆς κλίμακος καταβαίνουσα, ἐγὼ μὲν ἄνω διῃτώμην, αἱ δὲ γυναῖκες κάτω.", "st": "1.9"}, {"sp": "N", "t": "καὶ οὕτως ἤδη συνειθισμένον ἦν, ὥστε πολλάκις ἡ γυνὴ ἀπῄει κάτω καθευδήσουσα ὡς τὸ παιδίον, ἵνα τὸν τιτθὸν αὐτῷ διδῷ καὶ μὴ βοᾷ. καὶ ταῦτα πολὺν χρόνον οὕτως ἐγίγνετο, καὶ ἐγὼ οὐδέποτε ὑπώπτευσα, ἀλλ’ οὕτως ἠλιθίως διεκείμην, ὥστε ᾤμην τὴν ἐμαυτοῦ γυναῖκα πασῶν σωφρονεστάτην εἶναι τῶν ἐν τῇ πόλει.", "st": "1.10"}, {"sp": "N", "t": "προϊόντος δὲ τοῦ χρόνου, ὦ ἄνδρες, ἧκον μὲν ἀπροσδοκήτως ἐξ ἀγροῦ, μετὰ δὲ τὸ δεῖπνον τὸ παιδίον ἐβόα καὶ ἐδυσκόλαινεν ὑπὸ τῆς θεραπαίνης ἐπίτηδες λυπούμενον, ἵνα ταῦτα ποιῇ· ὁ γὰρ ἄνθρωπος ἔνδον ἦν·", "st": "1.11"}, {"sp": "N", "t": "ὕστερον γὰρ ἅπαντα ἐπυθόμην. καὶ ἐγὼ τὴν γυναῖκα ἀπιέναι ἐκέλευον καὶ δοῦναι τῷ παιδίῳ τὸν τιτθόν, ἵνα παύσηται κλᾶον. ἡ δὲ τὸ μὲν πρῶτον οὐκ ἤθελεν, ὡς ἂν ἀσμένη με ἑωρακυῖα ἥκοντα διὰ χρόνου· ἐπειδὴ δὲ ἐγὼ ὠργιζόμην καὶ ἐκέλευον αὐτὴν ἀπιέναι, “ἵνα σύ γε” ἔφη “πειρᾷς ἐνταῦθα τὴν παιδίσκην· καὶ πρότερον δὲ μεθύων εἷλκες αὐτήν.” κἀγὼ μὲν ἐγέλων,", "st": "1.12"}, {"sp": "N", "t": "ἐκείνη δὲ ἀναστᾶσα καὶ ἀπιοῦσα προστίθησι τὴν θύραν, προσποιουμένη παίζειν, καὶ τὴν κλεῖν ἐφέλκεται. κἀγὼ τούτων οὐδὲν ἐνθυμούμενος οὐδ’ ὑπονοῶν ἐκάθευδον ἄσμενος, ἥκων ἐξ ἀγροῦ.", "st": "1.13"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἦν πρὸς ἡμέραν, ἧκεν ἐκείνη καὶ τὴν θύραν ἀνέῳξεν. ἐρομένου δέ μου τί αἱ θύραι νύκτωρ ψοφοῖεν, ἔφασκε τὸν λύχνον ἀποσβεσθῆναι τὸν παρὰ τῷ παιδίῳ, εἶτα ἐκ τῶν γειτόνων ἐνάψασθαι. ἐσιώπων ἐγὼ καὶ ταῦτα οὕτως ἔχειν ἡγούμην. ἔδοξε δέ μοι, ὦ ἄνδρες, τὸ πρόσωπον ἐψιμυθιῶσθαι, τοῦ ἀδελφοῦ τεθνεῶτος οὔπω τριάκονθ’ ἡμέρας· ὅμως δ’ οὐδ’ οὕτως οὐδὲν εἰπὼν περὶ τοῦ πράγματος ἐξελθὼν ᾠχόμην ἔξω σιωπῇ.", "st": "1.14"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα, ὦ ἄνδρες, χρόνου μεταξὺ διαγενομένου καὶ ἐμοῦ πολὺ ἀπολελειμμένου τῶν ἐμαυτοῦ κακῶν, προσέρχεταί μοί τις πρεσβῦτις ἄνθρωπος, ὑπὸ γυναικὸς ὑποπεμφθεῖσα ἣν ἐκεῖνος ἐμοίχευεν, ὡς ἐγὼ ὕστερον ἤκουον· αὕτη δὲ ὀργιζομένη καὶ ἀδικεῖσθαι νομίζουσα, ὅτι οὐκέτι ὁμοίως ἐφοίτα παρ’ αὐτήν, ἐφύλαττεν ἕως ἐξηῦρεν ὅ τι εἴη τὸ αἴτιον. προσελθοῦσα οὖν μοι ἐγγὺς ἡ ἄνθρωπος τῆς οἰκίας τῆς ἐμῆς ἐπιτηροῦσα, “εὐφίλητε” ἔφη “μηδεμιᾷ πολυπραγμοσύνῃ προσεληλυθέναι με νόμιζε πρὸς σέ·”", "st": "1.15"}, {"sp": "N", "t": "“ὁ γὰρ ἀνὴρ ὁ ὑβρίζων εἰς σὲ καὶ τὴν σὴν γυναῖκα ἐχθρὸς ὢν ἡμῖν τυγχάνει. ἐὰν οὖν λάβῃς τὴν θεράπαιναν τὴν εἰς ἀγορὰν βαδίζουσαν καὶ διακονοῦσαν ὑμῖν καὶ βασανίσῃς, ἅπαντα πεύσῃ. ἔστι δ’” ἔφη “Ἐρατοσθένης Ὀῆθεν ὁ ταῦτα πράττων, ὃς οὐ μόνον τὴν σὴν γυναῖκα διέφθαρκεν ἀλλὰ καὶ ἄλλας πολλάς· ταύτην γὰρ [τὴν] τέχνην ἔχει.”", "st": "1.16"}, {"sp": "N", "t": "ταῦτα εἰποῦσα, ὦ ἄνδρες, ἐκείνη μὲν ἀπηλλάγη, ἐγὼ δ’ εὐθέως ἐταραττόμην, καὶ πάντα μου εἰς τὴν γνώμην εἰσῄει, καὶ μεστὸς ἦ ὑποψίας, ἐνθυμούμενος μὲν ὡς ἀπεκλῄσθην ἐν τῷ δωματίῳ, ἀναμιμνῃσκόμενος δὲ ὅτι ἐν ἐκείνῃ τῇ νυκτὶ ἐψόφει ἡ μέταυλος θύρα καὶ ἡ αὔλειος, ὃ οὐδέποτε ἐγένετο, ἔδοξέ τέ μοι ἡ γυνὴ ἐψιμυθιῶσθαι. ταῦτά μου πάντα εἰς τὴν γνώμην εἰσῄει, καὶ μεστὸς ἦ ὑποψίας.", "st": "1.17"}, {"sp": "N", "t": "ἐλθὼν δὲ οἴκαδε ἐκέλευον ἀκολουθεῖν μοι τὴν θεράπαιναν εἰς τὴν ἀγοράν, ἀγαγὼν δ’ αὐτὴν ὡς τῶν ἐπιτηδείων τινὰ ἔλεγον ὅτι ἐγὼ πάντα εἴην πεπυσμένος τὰ γιγνόμενα ἐν τῇ οἰκίᾳ· “σοὶ οὖν” ἔφην “ἔξεστι δυοῖν ὁπότερον βούλει ἑλέσθαι, ἢ μαστιγωθεῖσαν εἰς μύλωνα ἐμπεσεῖν καὶ μηδέποτε παύσασθαι κακοῖς τοιούτοις συνεχομένην, ἢ κατειποῦσαν ἅπαντα τἀληθῆ μηδὲν παθεῖν κακόν, ἀλλὰ συγγνώμης παρ’ ἐμοῦ τυχεῖν τῶν ἡμαρτημένων. ψεύσῃ δὲ μηδέν, ἀλλὰ πάντα τἀληθῆ λέγε.”", "st": "1.18"}, {"sp": "N", "t": "κἀκείνη τὸ μὲν πρῶτον ἔξαρνος ἦν, καὶ ποιεῖν ἐκέλευεν ὅ τι βούλομαι· οὐδὲν γὰρ εἰδέναι· ἐπειδὴ δὲ ἐγὼ ἐμνήσθην Ἐρατοσθένους πρὸς αὐτήν, καὶ εἶπον ὅτι οὗτος ὁ φοιτῶν εἴη πρὸς τὴν γυναῖκα, ἐξεπλάγη ἡγησαμένη με πάντα ἀκριβῶς ἐγνωκέναι. καὶ τότε ἤδη πρὸς τὰ γόνατά μου πεσοῦσα,", "st": "1.19"}, {"sp": "N", "t": "καὶ πίστιν παρ’ ἐμοῦ λαβοῦσα μηδὲν πείσεσθαι κακόν, κατηγόρει πρῶτον μὲν ὡς μετὰ τὴν ἐκφορὰν αὐτῇ προσίοι, ἔπειτα ὡς αὐτὴ τελευτῶσα εἰσαγγείλειε καὶ ὡς ἐκείνη τῷ χρόνῳ πεισθείη, καὶ τὰς εἰσόδους οἷς τρόποις προσίοιτο, καὶ ὡς Θεσμοφορίοις ἐμοῦ ἐν ἀγρῷ ὄντος ᾤχετο εἰς τὸ ἱερὸν μετὰ τῆς μητρὸς τῆς ἐκείνου· καὶ τἆλλα τὰ γενόμενα πάντα ἀκριβῶς διηγήσατο. ἐπειδὴ δὲ πάντα εἴρητο αὐτῇ,", "st": "1.20"}, {"sp": "N", "t": "εἶπον ἐγώ, “ὅπως τοίνυν ταῦτα μηδεὶς ἀνθρώπων πεύσεται· εἰ δέ μή, οὐδέν σοι κύριον ἔσται τῶν πρὸς ἔμ’ ὡμολογημένων. ἀξιῶ δέ σε ἐπ’ αὐτοφώρῳ ταῦτά μοι ἐπιδεῖξαι· ἐγὼ γὰρ οὐδὲν δέομαι λόγων, ἀλλὰ τὸ ἔργον φανερὸν γενέσθαι, εἴπερ οὕτως ἔχει.”", "st": "1.21"}, {"sp": "N", "t": "ὡμολόγει ταῦτα ποιήσειν. καὶ μετὰ ταῦτα διεγένοντο ἡμέραι τέσσαρες ἢ πέντε, … ὡς ἐγὼ μεγάλοις ὑμῖν τεκμηρίοις ἐπιδείξω. πρῶτον δὲ διηγήσασθαι βούλομαι τὰ πραχθέντα τῇ τελευταίᾳ ἡμέρᾳ. Σώστρατος ἦν μοι ἐπιτήδειος καὶ φίλος. τούτῳ ἡλίου δεδυκότος ἰόντι ἐξ ἀγροῦ ἀπήντησα.", "st": "1.22"}, {"sp": "N", "t": "εἰδὼς δ’ ἐγὼ ὅτι τηνικαῦτα ἀφιγμένος οὐδένα καταλήψοιτο οἴκοι τῶν ἐπιτηδείων, ἐκέλευον, συνδειπνεῖν· καὶ ἐλθόντες οἴκαδε ὡς ἐμέ, ἀναβάντες εἰς τὸ ὑπερῷον ἐδειπνοῦμεν. ἐπειδὴ δὲ καλῶς αὐτῷ εἶχεν, ἐκεῖνος μὲν ἀπιὼν ᾤχετο, ἐγὼ δ’ ἐκάθευδον. ὁ δ’ Ἐρατοσθένης, ὦ ἄνδρες, εἰσέρχεται, καὶ ἡ θεράπαινα ἐπεγείρασά με εὐθὺς φράζει ὅτι ἔνδον ἐστί. κἀγὼ εἰπὼν ἐκείνῃ ἐπιμελεῖσθαι τῆς θύρας, καταβὰς σιωπῇ ἐξέρχομαι, καὶ ἀφικνοῦμαι ὡς τὸν καὶ τόν, καὶ τοὺς μὲν ἔνδον κατέλαβον, τοὺς δὲ οὐκ ἐπιδημοῦντας ηὗρον.", "st": "1.23"}, {"sp": "N", "t": "παραλαβὼν δ’ ὡς οἷόν τε ἦν πλείστους ἐκ τῶν παρόντων ἐβάδιζον. καὶ δᾷδας λαβόντες ἐκ τοῦ ἐγγύτατα καπηλείου εἰσερχόμεθα, ἀνεῳγμένης τῆς θύρας καὶ ὑπὸ τῆς ἀνθρώπου παρεσκευασμένης. ὤσαντες δὲ τὴν θύραν τοῦ δωματίου οἱ μὲν πρῶτοι εἰσιόντες ἔτι εἴδομεν αὐτὸν κατακείμενον παρὰ τῇ γυναικί, οἱ δ’ ὕστερον ἐν τῇ κλίνῃ γυμνὸν ἑστηκότα.", "st": "1.24"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες, πατάξας καταβάλλω αὐτόν, καὶ τὼ χεῖρε περιαγαγὼν εἰς τοὔπισθεν καὶ δήσας ἠρώτων διὰ τί ὑβρίζει εἰς τὴν οἰκίαν τὴν ἐμὴν εἰσιών. κἀκεῖνος ἀδικεῖν μὲν ὡμολόγει, ἠντεβόλει δὲ καὶ ἱκέτευε μὴ ἀποκτεῖναι ἀλλ’ ἀργύριον πράξασθαι. ἐγὼ δ’ εἶπον ὅτι “οὐκ ἐγώ σε ἀποκτενῶ,”", "st": "1.25"}, {"sp": "N", "t": "“ἀλλ’ ὁ τῆς πόλεως νόμος, ὃν σὺ παραβαίνων περὶ ἐλάττονος τῶν ἡδονῶν ἐποιήσω, καὶ μᾶλλον εἵλου τοιοῦτον ἁμάρτημα ἐξαμαρτάνειν εἰς τὴν γυναῖκα τὴν ἐμὴν καὶ εἰς τοὺς παῖδας τοὺς ἐμοὺς ἢ τοῖς νόμοις πείθεσθαι καὶ κόσμιος εἶναι.”", "st": "1.26"}, {"sp": "N", "t": "οὕτως, ὦ ἄνδρες, ἐκεῖνος τούτων ἔτυχεν ὧνπερ οἱ νόμοι κελεύουσι τοὺς τὰ τοιαῦτα πράττοντας, οὐκ εἰσαρπασθεὶς ἐκ τῆς ὁδοῦ, οὐδ’ ἐπὶ τὴν ἑστίαν καταφυγών, ὥσπερ οὗτοι λέγουσι· πῶς γὰρ ἄν, ὅστις ἐν τῷ δωματίῳ πληγεὶς κατέπεσεν εὐθύς, περιέστρεψα δ’ αὐτοῦ τὼ χεῖρε, ἔνδον δὲ ἦσαν ἄνθρωποι τοσοῦτοι, οὓς διαφυγεῖν οὐκ ἐδύνατο, οὔτε σίδηρον οὔτε ξύλον οὔτε ἄλλο οὐδὲν ἔχων, ᾧ τοὺς εἰσελθόντας ἂν ἠμύνατο.", "st": "1.27"}, {"sp": "N", "t": "ἀλλ’, ὦ ἄνδρες, οἶμαι καὶ ὑμᾶς εἰδέναι ὅτι οἱ μὴ τὰ δίκαια πράττοντες οὐχ ὁμολογοῦσι τοὺς ἐχθροὺς λέγειν ἀληθῆ, ἀλλ’ αὐτοὶ ψευδόμενοι καὶ τὰ τοιαῦτα μηχανώμενοι ὀργὰς τοῖς ἀκούουσι κατὰ τῶν τὰ δίκαια πραττόντων παρασκευάζουσι. πρῶτον μὲν οὖν ἀνάγνωθι τὸν νόμον.", "st": "1.28"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "1.29"}, {"sp": "N", "t": "οὐκ ἠμφεσβήτει, ὦ ἄνδρες, ἀλλ’ ὡμολόγει ἀδικεῖν, καὶ ὅπως μὲν μὴ ἀποθάνῃ ἠντεβόλει καὶ ἱκέτευεν, ἀποτίνειν δ’ ἕτοιμος ἦν χρήματα. ἐγὼ δὲ τῷ μὲν ἐκείνου τιμήματι οὐ συνεχώρουν, τὸν δὲ τῆς πόλεως νόμον ἠξίουν εἶναι κυριώτερον, καὶ ταύτην ἔλαβον τὴν δίκην, ἣν ὑμεῖς δικαιοτάτην εἶναι ἡγησάμενοι τοῖς τὰ τοιαῦτα ἐπιτηδεύουσιν ἐτάξατε. καί μοι ἀνάβητε τούτων μάρτυρες.", "st": "1.29"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "1.30"}, {"sp": "N", "t": "ἀνάγνωθι δέ μοι καὶ τοῦτον τὸν νόμον ⟨τὸν⟩ ἐκ τῆς στήλης τῆς ἐξ Ἀρείου πάγου.", "st": "1.30"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "1.30"}, {"sp": "N", "t": "ἀκούετε, ὦ ἄνδρες, ὅτι αὐτῷ τῷ δικαστηρίῳ τῷ ἐξ Ἀρείου πάγου, ᾧ καὶ πάτριόν ἐστι καὶ ἐφ’ ἡμῶν ἀποδέδοται τοῦ φόνου τὰς δίκας δικάζειν, διαρρήδην εἴρηται τούτου μὴ καταγιγνώσκειν φόνον, ὃς ἂν ἐπὶ δάμαρτι τῇ ἑαυτοῦ μοιχὸν λαβὼν ταύτην τὴν τιμωρίαν ποιήσηται.", "st": "1.30"}, {"sp": "N", "t": "καὶ οὕτω σφόδρα ὁ νομοθέτης ἐπὶ ταῖς γαμεταῖς γυναιξὶ δίκαια ταῦτα ἡγήσατο εἶναι, ὥστε καὶ ἐπὶ ταῖς παλλακαῖς ταῖς ἐλάττονος ἀξίαις τὴν αὐτὴν δίκην ἐπέθηκε. καίτοι δῆλον ὅτι, εἴ τινα εἶχε ταύτης μείζω τιμωρίαν ἐπὶ ταῖς γαμεταῖς, ἐποίησεν ἄν. νῦν δὲ οὐχ οἷός τε ὢν ταύτης ἰσχυροτέραν ἐπ’ ἐκείναις ἐξευρεῖν, τὴν αὐτὴν καὶ ἐπὶ ταῖς παλλακαῖς ἠξίωσε γίγνεσθαι. ἀνάγνωθι δέ μοι καὶ τοῦτον τὸν νόμον.", "st": "1.31"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "1.32"}, {"sp": "N", "t": "ἀκούετε, ἄνδρες, ὅτι κελεύει, ἐάν τις ἄνθρωπον ἐλεύθερον ἢ παῖδα αἰσχύνῃ βίᾳ, διπλῆν τὴν βλάβην ὀφείλειν· ἐὰν δὲ γυναῖκα, ἐφ’ αἷσπερ ἀποκτείνειν ἔξεστιν, ἐν τοῖς αὐτοῖς ἐνέχεσθαι· οὕτως, ὦ ἄνδρες, τοὺς βιαζομένους ἐλάττονος ζημίας ἀξίους ἡγήσατο εἶναι ἢ τοὺς πείθοντας· τῶν μὲν γὰρ θάνατον κατέγνω, τοῖς δὲ διπλῆν ἐποίησε τὴν βλάβην, ἡγούμενος τοὺς μὲν διαπραττομένους βίᾳ ὑπὸ τῶν βιασθέντων μισεῖσθαι,", "st": "1.32"}, {"sp": "N", "t": "τοὺς δὲ πείσαντας οὕτως αὐτῶν τὰς ψυχὰς διαφθείρειν, ὥστ’ οἰκειοτέρας αὑτοῖς ποιεῖν τὰς ἀλλοτρίας γυναῖκας ἢ τοῖς ἀνδράσι, καὶ πᾶσαν ἐπ’ ἐκείνοις τὴν οἰκίαν γεγονέναι, καὶ τοὺς παῖδας ἀδήλους εἶναι ὁποτέρων τυγχάνουσιν ὄντες, τῶν ἀνδρῶν ἢ τῶν μοιχῶν. ἀνθ’ ὧν ὁ τὸν νόμον τιθεὶς θάνατον αὐτοῖς ἐποίησε τὴν ζημίαν.", "st": "1.33"}, {"sp": "N", "t": "ἐμοῦ τοίνυν, ὦ ἄνδρες, οἱ μὲν νόμοι οὐ μόνον ἀπεγνωκότες εἰσὶ μὴ ἀδικεῖν, ἀλλὰ καὶ κεκελευκότες ταύτην τὴν δίκην λαμβάνειν· ἐν ὑμῖν δ’ ἐστὶ πότερον χρὴ τούτους ἰσχυροὺς ἢ μηδενὸς ἀξίους εἶναι.", "st": "1.34"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ οἶμαι πάσας τὰς πόλεις διὰ τοῦτο τοὺς νόμους τίθεσθαι, ἵνα περὶ ὧν ἂν πραγμάτων ἀπορῶμεν, παρὰ τούτους ἐλθόντες σκεψώμεθα ὅ τι ἡμῖν ποιητέον ἐστίν. οὗτοι τοίνυν περὶ τῶν τοιούτων τοῖς ἀδικουμένοις τοιαύτην δίκην λαμβάνειν παρακελεύονται.", "st": "1.35"}, {"sp": "N", "t": "οἷς ὑμᾶς ἀξιῶ τὴν αὐτὴν γνώμην ἔχειν· εἰ δὲ μή, τοιαύτην ἄδειαν τοῖς μοιχοῖς ποιήσετε, ὥστε καὶ τοὺς κλέπτας ἐπαρεῖτε φάσκειν μοιχοὺς εἶναι, εὖ εἰδότας ὅτι, ἐὰν ταύτην τὴν αἰτίαν περὶ ἑαυτῶν λέγωσι καὶ ἐπὶ τούτῳ φάσκωσιν εἰς τὰς ἀλλοτρίας οἰκίας εἰσιέναι, οὐδεὶς αὐτῶν ἅψεται. πάντες γὰρ εἴσονται ὅτι τοὺς μὲν νόμους τῆς μοιχείας χαίρειν ἐᾶν δεῖ, τὴν δὲ ψῆφον τὴν ὑμετέραν δεδιέναι· αὕτη γάρ ἐστι πάντων τῶν ἐν τῇ πόλει κυριωτάτη.", "st": "1.36"}, {"sp": "N", "t": "σκέψασθε δέ, ὦ ἄνδρες· κατηγοροῦσι γάρ μου ὡς ἐγὼ τὴν θεράπαιναν ἐν ἐκείνῃ τῇ ἡμέρᾳ μετελθεῖν ἐκέλευσα τὸν νεανίσκον. ἐγὼ δέ, ὦ ἄνδρες, δίκαιον μὲν ἂν ποιεῖν ἡγούμην ᾡτινιοῦν τρόπῳ τὸν τὴν γυναῖκα τὴν ἐμὴν διαφθείραντα", "st": "1.37"}, {"sp": "N", "t": "λαμβάνων· εἰ μὲν γὰρ λόγων εἰρημένων ἔργου δὲ μηδενὸς γεγενημένου μετελθεῖν ἐκέλευον ἐκεῖνον, ἠδίκουν ἄν· εἰ δὲ ἤδη πάντων διαπεπραγμένων καὶ πολλάκις εἰσεληλυθότος εἰς τὴν οἰκίαν τὴν ἐμὴν ᾡτινιοῦν τρόπῳ ἐλάμβανον αὐτόν, σωφρονεῖν ⟨ἂν⟩ ἐμαυτὸν ἡγούμην·", "st": "1.38"}, {"sp": "N", "t": "σκέψασθε δὲ ὅτι καὶ ταῦτα ψεύδονται· ῥᾳδίως δὲ ἐκ τῶνδε γνώσεσθε. ἐμοὶ γάρ, ὦ ἄνδρες, ὅπερ καὶ πρότερον εἶπον, φίλος ὢν Σώστρατος καὶ οἰκείως διακείμενος ἀπαντήσας ἐξ ἀγροῦ περὶ ἡλίου δυσμὰς συνεδείπνει, καὶ ἐπειδὴ καλῶς εἶχεν αὐτῷ, ἀπιὼν ᾤχετο.", "st": "1.39"}, {"sp": "N", "t": "καίτοι πρῶτον μέν, ὦ ἄνδρες, ἐνθυμήθητε· [ὅτι] εἰ ἐν ἐκείνῃ τῇ νυκτὶ ἐγὼ ἐπεβούλευον Ἐρατοσθένει, πότερον ἦν μοι κρεῖττον αὐτῷ ἑτέρωθι δειπνεῖν ἢ τὸν συνδειπνήσοντά μοι εἰσαγαγεῖν; οὕτω γὰρ ἂν ἧττον ἐτόλμησεν ἐκεῖνος εἰσελθεῖν εἰς τὴν οἰκίαν. εἶτα δοκῶ ἂν ὑμῖν τὸν συνδειπνοῦντα ἀφεὶς μόνος καταλειφθῆναι καὶ ἔρημος γενέσθαι, ἢ κελεύειν ἐκεῖνον μεῖναι, ἵνα μετ’ ἐμοῦ τὸν μοιχὸν ἐτιμωρεῖτο;", "st": "1.40"}, {"sp": "N", "t": "ἔπειτα, ὦ ἄνδρες, οὐκ ἂν δοκῶ ὑμῖν τοῖς ἐπιτηδείοις μεθ’ ἡμέραν παραγγεῖλαι, καὶ κελεῦσαι αὐτοὺς συλλεγῆναι εἰς οἰκίαν ⟨του⟩ τῶν φίλων ἐγγυτάτω, μᾶλλον ἢ ἐπειδὴ τάχιστα ᾐσθόμην τῆς νυκτὸς περιτρέχειν, οὐκ εἰδὼς ὅντινα οἴκοι καταλήψομαι καὶ ὅντινα ἔξω; καὶ ὡς Ἁρμόδιον μὲν καὶ τὸν δεῖνα ἦλθον οὐκ ἐπιδημοῦντας (οὐ γὰρ ᾔδη), ἑτέρους δὲ οὐκ ἔνδον ὄντας κατέλαβον, οὓς δ’ οἷός τε ἦ λαβὼν ἐβάδιζον.", "st": "1.41"}, {"sp": "N", "t": "καίτοιγε εἰ προῄδη, οὐκ ἂν δοκῶ ὑμῖν καὶ θεράποντας παρασκευάσασθαι καὶ τοῖς φίλοις παραγγεῖλαι, ἵν’ ὡς ἀσφαλέστατα μὲν αὐτὸς εἰσῄα (τί γὰρ ᾔδη εἴ τι κἀκεῖνος εἶχε σιδήριον;), ὡς μετὰ πλείστων δὲ μαρτύρων τὴν τιμωρίαν ἐποιούμην; νῦν δ’ οὐδὲν εἰδὼς τῶν ἐσομένων ἐκείνῃ τῇ νυκτί, οὓς οἷός τε ἦ παρέλαβον. καί μοι ἀνάβητε τούτων μάρτυρες.", "st": "1.42"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "1.43"}, {"sp": "N", "t": "τῶν μὲν μαρτύρων ἀκηκόατε, ὦ ἄνδρες· σκέψασθε δὲ παρ’ ὑμῖν αὐτοῖς οὕτως περὶ τούτου τοῦ πράγματος, ζητοῦντες εἴ τις ἐμοὶ καὶ Ἐρατοσθένει ἔχθρα πώποτε γεγένηται πλὴν ταύτης. οὐδεμίαν γὰρ εὑρήσετε.", "st": "1.43"}, {"sp": "N", "t": "οὔτε γὰρ συκοφαντῶν γραφάς με ἐγράψατο, οὔτε ἐκβάλλειν ἐκ τῆς πόλεως ἐπεχείρησεν, οὕτε ἰδίας δίκας ἐδικάζετο, οὔτε συνῄδει κακὸν οὐδὲν ὃ ἐγὼ δεδιὼς μή τις πύθηται ἐπεθύμουν αὐτὸν ἀπολέσαι, οὔτε εἰ ταῦτα διαπραξαίμην, ἤλπιζόν ποθεν χρήματα λήψεσθαι· ἔνιοι γὰρ τοιούτων πραγμάτων ἕνεκα θάνατον ἀλλήλοις ἐπιβουλεύουσι.", "st": "1.44"}, {"sp": "N", "t": "τοσούτου τοίνυν δεῖ ἢ λοιδορία ἢ παροινία ἢ ἄλλη τις διαφορὰ ἡμῖν γεγονέναι, ὥστε οὐδὲ ἑωρακὼς ἦ τὸν ἄνθρωπον πώποτε πλὴν ἐν ἐκείνῃ τῇ νυκτί. τί ἄν οὖν βουλόμενος ἐγὼ τοιοῦτον κίνδυνον ἐκινδύνευον, εἰ μὴ τὸ μέγιστον τῶν ἀδικημάτων ἦ ὑπ’ αὐτοῦ ἠδικημένος;", "st": "1.45"}, {"sp": "N", "t": "ἔπειτα παρακαλέσας αὐτὸς μάρτυρας ἠσέβουν, ἐξόν μοι, εἴπερ ἀδίκως ἐπεθύμουν αὐτὸν ἀπολέσαι, μηδένα μοι τούτων συνειδέναι;", "st": "1.46"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν, ὦ ἄνδρες, οὐκ ἰδίαν ὑπὲρ ἐμαυτοῦ νομίζω ταύτην γενέσθαι τὴν τιμωρίαν, ἀλλ’ ὑπὲρ τῆς πόλεως ἁπάσης· οἱ γὰρ τοιαῦτα πράττοντες, ὁρῶντες οἷα τὰ ἆθλα πρόκειται τῶν τοιούτων ἁμαρτημάτων, ἧττον εἰς τοὺς ἄλλους ἐξαμαρτήσονται, ἐὰν καὶ ὑμᾶς ὁρῶσι τὴν αὐτὴν γνώμην ἔχοντας.", "st": "1.47"}, {"sp": "N", "t": "εἰ δὲ μή, πολὺ κάλλιον τοὺς μὲν κειμένους νόμους ἐξαλεῖψαι, ἑτέρους δὲ θεῖναι, οἵτινες τοὺς μὲν φυλάττοντας τὰς ἑαυτῶν γυναῖκας ταῖς ζημίαις ζημιώσουσι, τοῖς δὲ βουλομένοις εἰς αὐτὰς ἁμαρτάνειν πολλὴν ἄδειαν ποιήσουσι.", "st": "1.48"}, {"sp": "N", "t": "πολὺ γὰρ οὕτω δικαιότερον ἢ ὑπὸ τῶν νόμων τοὺς πολίτας ἐνεδρεύεσθαι, οἳ κελεύουσι μέν, ἐάν τις μοιχὸν λάβῃ, ὅ τι ἂν οὖν βούληται χρῆσθαι, οἱ δ’ ἀγῶνες δεινότεροι τοῖς ἀδικουμένοις καθεστήκασιν ἢ τοῖς παρὰ τοὺς νόμους τὰς ἀλλοτρίας καταισχύνουσι γυναῖκας.", "st": "1.49"}, {"sp": "N", "t": "ἐγὼ γὰρ νῦν καὶ περὶ τοῦ σώματος καὶ περὶ τῶν χρημάτων καὶ περὶ τῶν ἄλλων ἁπάντων κινδυνεύω, ὅτι τοῖς τῆς πόλεως νόμοις ἐπειθόμην.", "st": "1.50"}, {"sp": "HDR", "t": "Βʹ. Ἐπιτάφιος τοῖς Κορινθίων βοηθοῖς", "st": "2"}, {"sp": "N", "t": "εἰ μὲν ἡγούμην οἷόν τε εἶναι, ὦ παρόντες ἐπὶ τῷδε τῷ τάφῳ, λόγῳ δηλῶσαι τὴν τῶν ἐνθάδε κειμένων ἀνδρῶν ἀρετήν, ἐμεμψάμην ἂν τοῖς ἐπαγγείλασιν ἐπ’ αὐτοῖς ἐξ ὀλίγων ἡμερῶν λέγειν· ἐπειδὴ δὲ πᾶσιν ἀνθρώποις ὁ πᾶς χρόνος οὐχ ἱκανὸς λόγον ἴσον παρασκευάσαι τοῖς τούτων ἔργοις, διὰ τοῦτο καὶ ἡ πόλις μοι δοκεῖ, προνοουμένη τῶν ἐνθάδε λεγόντων, ἐξ ὀλίγου τὴν πρόσταξιν ποιεῖσθαι, ἡγουμένη οὕτως ἂν μάλιστα συγγνώμης αὐτοὺς παρὰ τῶν ἀκουσάντων τυγχάνειν.", "st": "2.1"}, {"sp": "N", "t": "ὅμως δὲ ὁ μὲν λόγος μοι περὶ τούτων, ὁ δ’ ἀγὼν οὐ πρὸς τὰ τούτων ἔργα ἀλλὰ πρὸς τοὺς πρότερον ἐπ’ αὐτοῖς εἰρηκότας. τοσαύτην γὰρ ἀφθονίαν παρεσκεύασεν ἡ τούτων ἀρετὴ καὶ τοῖς ποιεῖν δυναμένοις καὶ τοῖς εἰπεῖν βουληθεῖσιν, ὥστε καλὰ μὲν πολλὰ τοῖς προτέροις περὶ αὐτῶν εἰρῆσθαι, πολλὰ δὲ καὶ ἐκείνοις παραλελεῖφθαι, ἱκανὰ δὲ καὶ τοῖς ἐπιγιγνομένοις ἐξεῖναι εἰπεῖν· οὔτε γὰρ γῆς ἄπειροι οὔτε θαλάττης οὐδεμιᾶς, πανταχῇ δὲ καὶ παρὰ πᾶσιν ἀνθρώποις οἱ τὰ αὑτῶν πενθοῦντες κακὰ τὰς τούτων ἀρετὰς ὑμνοῦσι.", "st": "2.2"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τοὺς παλαιοὺς κινδύνους τῶν προγόνων δίειμι, μνήμην παρὰ τῆς φήμης λαβών· ἄξιον γὰρ πᾶσιν ἀνθρώποις κἀκείνων μεμνῆσθαι, ὑμνοῦντας μὲν ἐν ταῖς ᾠδαῖς, λέγοντας δ’ ἐν ταῖς τῶν ἀγαθῶν γνώμαις, τιμῶντας δ’ ἐν τοῖς καιροῖς τοῖς τοιούτοις, παιδεύοντας δ’ ἐν τοῖς τῶν τεθνεώτων ἔργοις τοὺς ζῶντας.", "st": "2.3"}, {"sp": "N", "t": "Ἀμαζόνες γὰρ Ἄρεως μὲν τὸ παλαιὸν ἦσαν θυγατέρες, οἰκοῦσαι [δὲ] παρὰ τὸν Θερμώδοντα ποταμόν, μόναι μὲν ὡπλισμέναι σιδήρῳ τῶν περὶ αὐτάς, πρῶται δὲ τῶν πάντων ἐφ’ ἵππους ἀναβᾶσαι, οἷς ἀνελπίστως δι’ ἀπειρίαν τῶν ἐναντίων ᾕρουν μὲν τοὺς φεύγοντας, ἀπέλειπον δὲ διώκοντας· ἐνομίζοντο δὲ διὰ τὴν εὐψυχίαν μᾶλλον ἄνδρες ἢ διὰ τὴν φύσιν γυναῖκες· πλέον γὰρ ἐδόκουν τῶν ἀνδρῶν ταῖς ψυχαῖς διαφέρειν ἢ ταῖς ἰδέαις ἐλλείπειν.", "st": "2.4"}, {"sp": "N", "t": "ἄρχουσαι δὲ πολλῶν ἐθνῶν, καὶ ἔργῳ μὲν τοὺς περὶ αὐτὰς καταδεδουλωμέναι, λόγῳ δὲ περὶ τῆσδε τῆς χώρας ἀκούουσαι κλέος μέγα, πολλῆς δόξης καὶ μεγάλης ἐλπίδος χάριν παραλαβοῦσαι τὰ μαχιμώτατα τῶν ἐθνῶν ἐστράτευσαν ἐπὶ τήνδε τὴν πόλιν. τυχοῦσαι δ’ ἀγαθῶν ἀνδρῶν ὁμοίας ἐκτήσαντο τὰς ψυχὰς τῇ φύσει, καὶ ἐναντίαν τὴν δόξαν τῆς προτέρας λαβοῦσαι μᾶλλον ἐκ τῶν κινδύνων ἢ ἐκ τῶν σωμάτων ἔδοξαν εἶναι γυναῖκες.", "st": "2.5"}, {"sp": "N", "t": "μόναις δ’ αὐταῖς οὐκ ἐξεγένετο ἐκ τῶν ἡμαρτημένων μαθούσαις περὶ τῶν λοιπῶν ἄμεινον βουλεύσασθαι, οὐδ’ οἴκαδε ἀπελθούσαις ἀπαγγεῖλαι τήν τε σφετέραν αὐτῶν δυστυχίαν καὶ τὴν τῶν ἡμετέρων προγόνων ἀρετήν· αὐτοῦ γὰρ ἀποθανοῦσαι, καὶ δοῦσαι δίκην τῆς ἀνοίας, τῆσδε μὲν τῆς πόλεως διὰ τὴν ἀρετὴν ἀθάνατον ⟨τὴν⟩ μνήμην ἐποίησαν, τὴν δὲ ἑαυτῶν πατρίδα διὰ τὴν ἐνθάδε συμφορὰν ἀνώνυμον κατέστησαν. ἐκεῖναι μὲν οὖν τῆς ἀλλοτρίας ἀδίκως ἐπιθυμήσασαι τὴν ἑαυτῶν δικαίως ἀπώλεσαν.", "st": "2.6"}, {"sp": "N", "t": "Ἀδράστου δὲ καὶ Πολυνείκους ἐπὶ Θήβας στρατευσάντων καὶ ἡττηθέντων μάχῃ, οὐκ ἐώντων Καδμείων θάπτειν τοὺς νεκρούς, Ἀθηναῖοι ἡγησάμενοι ἐκείνους μέν, εἴ τι ἠδίκουν, ἀποθανόντας δίκην ἔχειν τὴν μεγίστην, τοὺς δὲ κάτω τὰ αὑτῶν οὐ κομίζεσθαι, ἱερῶν δὲ μιαινομένων τοὺς ἄνω θεοὺς ἀσεβεῖσθαι, τὸ μὲν πρῶτον πέμψαντες κήρυκας ἐδέοντο αὐτῶν δοῦναι τῶν νεκρῶν ἀναίρεσιν,", "st": "2.7"}, {"sp": "N", "t": "νομίζοντες ἀνδρῶν μὲν ἀγαθῶν εἶναι ζῶντας τοὺς ἐχθροὺς τιμωρήσασθαι, ἀπιστούντων δὲ σφίσιν αὐτοῖς ἐν τοῖς τῶν τεθνεώτων σώμασι τὴν εὐψυχίαν ἐπιδείκνυσθαι· οὐ δυνάμενοι δὲ τούτων τυχεῖν ἐστράτευσαν ἐπ’ αὐτούς, οὐδεμιᾶς διαφορᾶς πρότερον πρὸς Καδμείους ὑπαρχούσης, οὐδὲ τοῖς ζῶσιν Ἀργείων χαριζόμενοι,", "st": "2.8"}, {"sp": "N", "t": "ἀλλὰ τοὺς τεθνεῶτας ἐν τῷ πολέμῳ ἀξιοῦντες τῶν νομιζομένων τυγχάνειν πρὸς τοὺς ἑτέρους ὑπὲρ ἀμφοτέρων ἐκινδύνευσαν, ὑπὲρ μὲν τῶν, ἵνα μηκέτι εἰς τοὺς τεθνεῶτας ἐξαμαρτάνοντες πλείω περὶ τοὺς θεοὺς ἐξυβρίσωσιν, ὑπὲρ δὲ τῶν ἑτέρων, ἵνα μὴ πρότερον εἰς τὴν αὑτῶν ἀπέλθωσι πατρίου τιμῆς ἀτυχήσαντες καὶ Ἑλληνικοῦ νόμου στερηθέντες καὶ κοινῆς ἐλπίδος ἡμαρτηκότες.", "st": "2.9"}, {"sp": "N", "t": "ταῦτα διανοηθέντες, καὶ τὰς ἐν τῷ πολέμῳ τύχας κοινὰς ἁπάντων ἀνθρώπων νομίζοντες, πολλοὺς μὲν πολεμίους κτώμενοι, τὸ δὲ δίκαιον ἔχοντες σύμμαχον ἐνίκων μαχόμενοι. καὶ οὐχ ὑπὸ τῆς τύχης ἐπαρθέντες μείζονος παρὰ Καδμείων τιμωρίας ἐπεθύμησαν, ἀλλ’ ἐκείνοις μὲν ἀντὶ τῆς ἀσεβείας τὴν ἑαυτῶν ἀρετὴν ἐπεδείξαντο, αὐτοὶ δὲ λαβόντες τὰ ἆθλα ὧνπερ ἕνεκα ἀφίκοντο, τοὺς Ἀργείων νεκρούς, ἔθαψαν ἐν τῇ αὑτῶν Ἐλευσῖνι. περὶ μὲν οὖν τοὺς ἀποθανόντας τῶν ἑπτὰ ἐπὶ Θήβας τοιοῦτοι γεγόνασιν.", "st": "2.10"}, {"sp": "N", "t": "ὑστέρῳ δὲ χρόνῳ, ἐπειδὴ Ἡρακλῆς μὲν ἐξ ἀνθρώπων ἠφανίσθη, οἱ δὲ παῖδες αὐτοῦ ἔφευγον μὲν Εὐρυσθέα, ἐξηλαύνοντο δὲ ὑπὸ πάντων τῶν Ἑλλήνων, αἰσχυνομένων μὲν τοῖς ἔργοις, φοβουμένων δὲ τὴν Εὐρυσθέως δύναμιν, ἀφικόμενοι εἰς τήνδε τὴν πόλιν ἱκέται ἐπὶ τῶν βωμῶν ἐκαθέζοντο·", "st": "2.11"}, {"sp": "N", "t": "ἐξαιτουμένου δὲ αὐτοὺς Εὐρυσθέως Ἀθηναῖοι οὐκ ἠθέλησαν ἐκδοῦναι, ἀλλὰ τὴν Ἡρακλέους ἀρετὴν μᾶλλον ᾐδοῦντο ἢ τὸν κίνδυνον τὸν ἑαυτῶν ἐφοβοῦντο, καὶ ἠξίουν ὑπὲρ τῶν ἀσθενεστέρων μετὰ τοῦ δικαίου διαμάχεσθαι μᾶλλον ἢ τοῖς δυναμένοις χαριζόμενοι τοὺς ὑπ’ ἐκείνων ἀδικουμένους ἐκδοῦναι.", "st": "2.12"}, {"sp": "N", "t": "ἐπιστρατεύσαντος δ’ Εὐρυσθέως μετὰ τῶν ἐν ἐκείνῳ τῷ χρόνῳ Πελοπόννησον ἐχόντων, οὐκ ἐγγὺς τῶν δεινῶν γενόμενοι μετέγνωσαν, ἀλλὰ τὴν αὐτὴν εἶχον γνώμην ἥνπερ πρότερον, ἀγαθὸν μὲν οὐδὲν ἰδίᾳ ὑπὸ τοῦ πατρὸς αὐτῶν πεπονθότες, ἐκείνους τ’ οὐκ εἰδότες ὁποῖοί τινες ἄνδρες ἔσονται γενόμενοι· δίκαιον δὲ νομίζοντες εἶναι,", "st": "2.13"}, {"sp": "N", "t": "οὐ προτέρας ἔχθρας ὑπαρχούσης πρὸς Εὐρυσθέα, οὐδὲ κέρδους προκειμένου πλὴν δόξης ἀγαθῆς, τοσοῦτον κίνδυνον ὑπὲρ αὐτῶν ἤραντο, τοὺς μὲν ἀδικουμένους ἐλεοῦντες, τοὺς δ’ ὑβρίζοντας μισοῦντες, καὶ τοὺς μὲν κωλύειν ἐπιχειροῦντες, τοῖς δ’ ἐπικουρεῖν ἀξιοῦντες, ἡγούμενοι ἐλευθερίας μὲν σημεῖον εἶναι μηδὲν ποιεῖν ἄκοντας, δικαιοσύνης δὲ τοῖς ἀδικουμένοις βοηθεῖν, εὐψυχίας δ’ ὑπὲρ τούτων ἀμφοτέρων, εἰ δέοι,", "st": "2.14"}, {"sp": "N", "t": "μαχομένους ἀποθνῄσκειν. τοσοῦτον δ’ ἐφρόνουν ἀμφότεροι, ὥσθ’ οἱ μὲν μετ’ Εὐρυσθέως οὐδὲν παρ’ ἑκόντων ἐζήτουν εὑρίσκεσθαι, Ἀθηναῖοι δὲ οὐκ ἠξίουν Εὐρυσθέα αὐτὸν ἱκετεύοντα τοὺς ἱκέτας αὐτῶν ἐξελεῖν. παραταξάμενοι δ’ ἰδίᾳ δυνάμει τὴν ἐξ ἁπάσης Πελοποννήσου στρατιὰν ἐλθοῦσαν ἐνίκων μαχόμενοι, καὶ τῶν Ἡρακλέους παίδων τὰ μὲν σώματα εἰς ἄδειαν κατέστησαν, ἀπαλλάξαντες δὲ τοῦ δέους καὶ τὰς ψυχὰς ἠλευθέρωσαν, διὰ δὲ τὴν τοῦ πατρὸς ἀρετὴν ἐκείνους τοῖς αὑτῶν κινδύνοις ἐστεφάνωσαν.", "st": "2.15"}, {"sp": "N", "t": "τοσοῦτον δὲ εὐτυχέστεροι παῖδες ὄντες ἐγένοντο τοῦ πατρός· ὁ μὲν γάρ, καίπερ ὢν ἀγαθῶν πολλῶν αἴτιος ἅπασιν ἀνθρώποις, ἐπίπονον καὶ φιλόνικον καὶ φιλότιμον αὑτῷ καταστήσας τὸν βίον τοὺς μὲν ἄλλους ἀδικοῦντας ἐκόλασεν, Εὐρυσθέα δὲ καὶ ἐχθρὸν ὄντα καὶ εἰς αὐτὸν ἐξαμαρτάνοντα οὐχ οἷός τε ἦν τιμωρήσασθαι οἱ δὲ παῖδες αὐτοῦ διὰ τήνδε τὴν πόλιν τῇ αὐτῇ εἶδον ἡμέρᾳ τήν θ’ ἑαυτῶν σωτηρίαν καὶ τὴν· τῶν ἐχθρῶν τιμωρίαν.", "st": "2.16"}, {"sp": "N", "t": "πολλὰ μὲν ὑπῆρχε τοῖς ἡμετέροις προγόνοις μιᾷ γνώμῃ χρωμένοις περὶ τοῦ δικαίου διαμάχεσθαι· ἥ τε γὰρ ἀρχὴ τοῦ βίου δικαία· οὐ γάρ, ὥσπερ οἱ πολλοί, πανταχόθεν συνειλεγμένοι καὶ ἑτέρους ἐκβαλόντες τὴν ἀλλοτρίαν ᾤκησαν, ἀλλ’ αὐτόχθονες ὄντες τὴν αὐτὴν ἐκέκτηντο μητέρα καὶ πατρίδα.", "st": "2.17"}, {"sp": "N", "t": "πρῶτοι δὲ καὶ μόνοι ἐν ἐκείνῳ τῷ χρόνῳ ἐκβαλόντες τὰς παρὰ σφίσιν αὐτοῖς δυναστείας δημοκρατίαν κατεστήσαντο, ἡγούμενοι τὴν πάντων ἐλευθερίαν ὁμόνοιαν εἶναι μεγίστην, κοινὰς δ’ ἀλλήλοις τὰς ἐκ τῶν κινδύνων ἐλπίδας ποιήσαντες ἐλευθέραις ταῖς ψυχαῖς ἐπολιτεύοντο,", "st": "2.18"}, {"sp": "N", "t": "νόμῳ τοὺς ἀγαθοὺς τιμῶντες καὶ τοὺς κακοὺς κολάζοντες, ἡγησάμενοι θηρίων μὲν ἔργον εἶναι ὑπ’ ἀλλήλων βίᾳ κρατεῖσθαι, ἀνθρώποις δὲ προσήκειν νόμῳ μὲν ὁρίσαι τὸ δίκαιον, λόγῳ δὲ πεῖσαι, ἔργῳ δὲ τούτοις ὑπηρετεῖν, ὑπὸ νόμου μὲν βασιλευομένους, ὑπὸ λόγου δὲ διδασκομένους.", "st": "2.19"}, {"sp": "N", "t": "καὶ γάρ τοι καὶ φύντες καλῶς καὶ γνόντες ὅμοια, πολλὰ μὲν καλὰ καὶ θαυμαστὰ οἱ πρόγονοι τῶν ἐνθάδε κειμένων εἰργάσαντο, ἀείμνηστα δὲ καὶ μεγάλα καὶ πανταχοῦ οἱ ἐξ ἐκείνων γεγονότες τρόπαια διὰ τὴν αὑτῶν ἀρετὴν κατέλιπον. μόνοι γὰρ ὑπὲρ ἁπάσης τῆς Ἑλλάδος πρὸς πολλὰς μυριάδας τῶν βαρβάρων διεκινδύνευσαν.", "st": "2.20"}, {"sp": "N", "t": "ὁ γὰρ τῆς Ἀσίας βασιλεὺς οὐκ ἀγαπῶν τοῖς ὑπάρχουσιν ἀγαθοῖς, ἀλλ’ ἐλπίζων καὶ τὴν Εὐρώπην δουλώσεσθαι, ἔστειλε πεντήκοντα μυριάδας στρατιάν. ἡγησάμενοι δέ, εἰ τήνδε τὴν πόλιν ἢ ἑκοῦσαν φίλην ποιήσαιντο ἢ ἄκουσαν καταστρέψαιντο, ῥαδίως τῶν πολλῶν Ἑλλήνων ἄρξειν, ἀπέβησαν εἰς Μαραθῶνα, νομίσαντες οὕτως ἂν ἐρημοτάτους εἶναι συμμάχων [τοὺς Ἕλληνας], εἰ ἔτι στασιαζούσης τῆς Ἑλλάδος ᾧ τινι χρὴ τρόπῳ τοὺς ἐπιόντας ἀμύνασθαι, τὸν κίνδυνον ποιήσαιντο.", "st": "2.21"}, {"sp": "N", "t": "ἔτι δ’ αὐτοῖς ἐκ τῶν προτέρων ἔργων περὶ τῆς πόλεως τοιαύτη δόξα παρειστήκει, ὡς εἰ μὲν πρότερον ἐπ’ ἄλλην πόλιν ἴασιν, ἐκείνοις καὶ Ἀθηναίοις πολεμήσουσι· προθύμως γὰρ τοῖς ἀδικουμένοις ἥξουσι βοηθήσοντες· εἰ δ’ ἐνθάδε πρῶτον ἀφίξονται, οὐδένας ἄλλους τῶν Ἑλλήνων τολμήσειν ἑτέρους σῴζοντας φανερὰν ἔχθραν πρὸς ἐκείνους ὑπὲρ αὐτῶν καταθέσθαι.", "st": "2.22"}, {"sp": "N", "t": "οἱ μὲν τοίνυν ταῦτα διενοοῦντο· οἱ δ’ ἡμέτεροι πρόγονοι οὐ λογισμῷ εἰδότες τοὺς ἐν τῷ πολέμῳ κινδύνους, ἀλλὰ νομίζοντες τὸν εὐκλεᾶ θάνατον ἀθάνατον περὶ τῶν ἀγαθῶν καταλείπειν λόγον, οὐκ ἐφοβήθησαν τὸ πλῆθος τῶν ἐναντίων, ἀλλὰ τῇ αὑτῶν ἀρετῇ μᾶλλον ἐπίστευσαν. καὶ αἰσχυνόμενοι ὅτι ἦσαν οἱ βάρβαροι αὐτῶν ἐν τῇ χώρᾳ, οὐκ ἀνέμειναν πυθέσθαι οὐδὲ βοηθῆσαι τοὺς συμμάχους, οὐδ’ ᾠήθησαν δεῖν ἑτέροις τῆς σωτηρίας χάριν εἰδέναι, ἀλλὰ σφίσιν αὐτοῖς τοὺς ἄλλους Ἕλληνας.", "st": "2.23"}, {"sp": "N", "t": "ταῦτα μιᾷ γνώμῃ πάντες γνόντες ἀπήντων ὀλίγοι πρὸς πολλούς· ἐνόμιζον γὰρ ἀποθανεῖν μὲν αὐτοῖς μετὰ πάντων προσήκειν, ἀγαθοὺς δ’ εἶναι μετ’ ὀλίγων, καὶ τὰς μὲν ψυχὰς ἀλλοτρίας διὰ τὸν θάνατον κεκτῆσθαι, τὴν δ’ ἐκ τῶν κινδύνων μνήμην ἰδίαν καταλείψειν. ἠξίουν δέ, οὓς μὴ μόνοι νικῷεν, οὐδ’ ἂν μετὰ τῶν συμμάχων δύνασθαι· καὶ ἡττηθέντες μὲν ὀλίγῳ τῶν ἄλλων προαπολεῖσθαι, νικήσαντες δὲ καὶ τοὺς ἄλλους ἐλευθερώσειν.", "st": "2.24"}, {"sp": "N", "t": "ἄνδρες δ’ ἀγαθοὶ γενόμενοι, καὶ τῶν μὲν σωμάτων ἀφειδήσαντες, ὑπὲρ δὲ τῆς ἀρετῆς οὐ φιλοψυχήσαντες, καὶ μᾶλλον τοὺς παρ’ αὑτοῖς νόμους αἰσχυνόμενοι ἢ τὸν πρὸς τοὺς πολεμίους κίνδυνον φοβούμενοι, ἔστησαν μὲν τρόπαιον ὑπὲρ τῆς Ἑλλάδος τῶν βαρβάρων ἐν τῇ αὑτῶν, ὑπὲρ χρημάτων εἰς τὴν ἀλλοτρίαν ἐμβαλόντων,", "st": "2.25"}, {"sp": "N", "t": "παρὰ τοὺς ὅρους τῆς χώρας, οὕτω δὲ διὰ ταχέων τὸν κίνδυνον ἐποιήσαντο, ὥστε οἱ αὐτοὶ τοῖς ἄλλοις ἀπήγγειλαν τήν τ’ ἐνθάδε ἄφιξιν τῶν βαρβάρων καὶ τὴν νίκην τῶν προγόνων. καὶ γάρ τοι οὐδεὶς τῶν ἄλλων ἔδεισεν ὑπὲρ τοῦ μέλλοντος κινδύνου, ἀλλ’ ἀκούσαντες ὑπὲρ τῆς αὑτῶν ἐλευθερίας ἥσθησαν. ὥστε οὐδὲν θαυμαστόν, πάλαι τῶν ἔργων γεγενημένων, ὥσπερ καινῶν ὄντων ἔτι καὶ νῦν τὴν ἀρετὴν αὐτῶν ὑπὸ πάντων ἀνθρώπων ζηλοῦσθαι.", "st": "2.26"}, {"sp": "N", "t": "μετὰ ταῦτα δὲ Ξέρξης ὁ τῆς Ἀσίας βασιλεύς, καταφρονήσας μὲν τῆς Ἑλλάδος, ἐψευσμένος δὲ τῆς ἐλπίδος, ἀτιμαζόμενος δὲ τῷ γεγενημένῳ, ἀχθόμενος δὲ τῇ συμφορᾷ, ὀργιζόμενος δὲ τοῖς αἰτίοις, ἀπαθὴς δ’ ὢν κακῶν καὶ ἄπειρος ἀνδρῶν ἀγαθῶν, δεκάτῳ ἔτει παρασκευασάμενος διακοσίαις μὲν καὶ χιλίαις ναυσὶν ἀφίκετο, τῆς δὲ πεζῆς στρατιᾶς οὕτως ἄπειρον τὸ πλῆθος ἦγεν, ὥστε καὶ τὰ ἔθνη τὰ μετ’ αὐτοῦ ἀκολουθήσαντα πολὺ", "st": "2.27"}, {"sp": "N", "t": "ἂν ἔργον εἴη καταλέξαι· ὃ δὲ μέγιστον σημεῖον τοῦ πλήθους· ἐξὸν γὰρ αὐτῷ χιλίαις ναυσὶ διαβιβάσαι κατὰ τὸ στενότατον τοῦ Ἑλλησπόντου τὴν πεζὴν στρατιὰν ἐκ τῆς Ἀσίας εἰς τὴν Εὐρώπην, οὐκ ἠθέλησεν, ἡγούμενος τὴν διατριβὴν αὑτῷ", "st": "2.28"}, {"sp": "N", "t": "πολλὴν ἔσεσθαι· ἀλλ’ ὑπεριδὼν καὶ τὰ φύσει πεφυκότα καὶ τὰ θεῖα πράγματα καὶ τὰς ἀνθρωπίνας διανοίας ὁδὸν μὲν διὰ τῆς θαλάττης ἐποιήσατο, πλοῦν δὲ διὰ τῆς γῆς ἠνάγκασε γενέσθαι, ζεύξας μὲν τὸν Ἑλλήσποντον, διορύξας δὲ τὸν Ἄθω, ὑφισταμένου οὐδενός, ἀλλὰ τῶν μὲν ἀκόντων ὑπακουόντων, τῶν δὲ ἑκόντων προδιδόντων. οἱ μὲν γὰρ οὐχ ἱκανοὶ ἦσαν ἀμύνασθαι, οἱ δ’ ὑπὸ χρημάτων διεφθαρμένοι· ἀμφότερα δ’ ἦν αὐτοὺς τὰ πείθοντα,", "st": "2.29"}, {"sp": "N", "t": "κέρδος καὶ δέος. Ἀθηναῖοι δ’ οὕτω διακειμένης τῆς Ἑλλάδος αὐτοὶ μὲν εἰς τὰς ναῦς ἐμβάντες ἐπ’ Ἀρτεμίσιον ἐβοήθησαν, Λακεδαιμόνιοι δὲ καὶ τῶν συμμάχων ἔνιοι εἰς Θερμοπύλας ἀπήντησαν, ἡγούμενοι διὰ τὴν στενότητα τῶν χωρίων τὴν πάροδον οἷοί τ’ ἔσεσθαι διαφυλάξαι.", "st": "2.30"}, {"sp": "N", "t": "γενομένου δὲ τοῦ κινδύνου κατὰ τὸν αὐτὸν χρόνον Ἀθηναῖοι μὲν ἐνίκων τῇ ναυμαχίᾳ, Λακεδαιμόνιοι δέ, οὐ ταῖς ψυχαῖς ἐνδεεῖς γενόμενοι, ἀλλὰ τοῦ πλήθους ψευσθέντες καὶ οὓς φυλάξειν ᾤοντο καὶ πρὸς οὓς κινδυνεύσειν ἔμελλον, ⟨διεφθάρησαν⟩ οὐχ ἡττηθέντες τῶν ἐναντίων, ἀλλ’ ἀποθανόντες", "st": "2.31"}, {"sp": "N", "t": "οὗπερ ἐτάχθησαν μάχεσθαι· τούτῳ δὲ τῷ τρόπῳ τῶν μὲν δυστυχησάντων, τῶν δὲ τῆς παρόδου κρατησάντων, οἱ μὲν ἐπορεύοντο ἐπὶ τήνδε τὴν πόλιν, οἱ δ’ ἡμέτεροι πρόγονοι πυθόμενοι μὲν τὴν γεγενημένην Λακεδαιμονίοις συμφοράν, ἀποροῦντες δὲ τοῖς περιεστηκόσι πράγμασιν, εἰδότες δ’ ὅτι, εἰ μὲν κατὰ γῆν τοῖς βαρβάροις ἀπαντήσονται, ἐπιπλεύσαντες χιλίαις ναυσὶν ἐρήμην τὴν πόλιν λήψονται, εἰ δὲ εἰς τὰς τριήρεις ἐμβήσονται, ὑπὸ τῆς πεζῆς στρατιᾶς ἁλώσονται, ἀμφότερα δὲ οὐ δυνήσονται, ἀμύνασθαί τε καὶ φυλακὴν ἱκανὴν καταλιπεῖν,", "st": "2.32"}, {"sp": "N", "t": "δυοῖν δὲ προκειμένοιν, πότερον χρὴ τὴν πατρίδα ἐκλιπεῖν ἢ μετὰ τῶν βαρβάρων γενομένους καταδουλώσασθαι τοὺς Ἕλληνας, ἡγησάμενοι κρεῖττον εἶναι μετ’ ἀρετῆς καὶ πενίας καὶ φυγῆς ἐλευθερίαν ἢ μετ’ ὀνείδους καὶ πλούτου δουλείαν τῆς πατρίδος, ἐξέλιπον ὑπὲρ τῆς Ἑλλάδος τὴν πόλιν, ἵν’ ἐν μέρει πρὸς ἑκατέραν ἀλλὰ μὴ πρὸς ἀμφοτέρας ἅμα τὰς δυνάμεις κινδυνεύσωσιν·", "st": "2.33"}, {"sp": "N", "t": "ὑπεκθέμενοι δὲ παῖδας καὶ γυναῖκας καὶ μητέρας εἰς Σαλαμῖνα, συνήθροιζον καὶ τὸ τῶν ἄλλων συμμάχων ναυτικόν. οὐ πολλαῖς δ’ ὕστερον ἡμέραις ἦλθε καὶ ἡ πεζὴ στρατιὰ καὶ τὸ ναυτικὸν τὸ τῶν βαρβάρων, ὃ τίς οὐκ ἂν ἰδὼν ἐφοβήθη, ὡς μέγας καὶ δεινὸς τῇδε τῇ πόλει κίνδυνος ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας ἠγωνίσθη;", "st": "2.34"}, {"sp": "N", "t": "ποίαν δὲ γνώμην εἶχον ἢ οἱ θεώμενοι τοὺς ἐν ταῖς ναυσὶν ἐκείναις, οὔσης καὶ τῆς αὑτῶν σωτηρίας ἀπίστου καὶ τοῦ προσιόντος κινδύνου, ἢ οἱ μέλλοντες ναυμαχήσειν ὑπὲρ τῆς φιλότητος, ὑπὲρ τῶν ἄθλων τῶν ἐν Σαλαμῖνι;", "st": "2.35"}, {"sp": "N", "t": "οἷς τοσοῦτον πανταχόθεν περιειστήκει πλῆθος πολεμίων, ὥστε ἐλάχιστον μὲν αὐτοῖς εἶναι τῶν παρόντων κακῶν τὸ θάνατον τὸν αὑτῶν προειδέναι, μεγίστην δὲ συμφοράν, ⟨ἃ⟩ ὑπὸ τῶν βαρβάρων εὐτυχησάντων τοὺς ὑπεκτεθέντας ἤλπιζον πείσεσθαι.", "st": "2.36"}, {"sp": "N", "t": "ἦ που διὰ τὴν ὑπάρχουσαν ἀπορίαν πολλάκις μὲν ἐδεξιώσαντο ἀλλήλους, εἰκότως δὲ σφᾶς αὐτοὺς ὠλοφύραντο, εἰδότες μὲν τὰς σφετέρας ναῦς ὀλίγας οὔσας, ὁρῶντες δὲ πολλὰς τὰς τῶν πολεμίων, ἐπιστάμενοι δὲ τὴν μὲν πόλιν ἠρημωμένην, τὴν δὲ χώραν πορθουμένην καὶ μεστὴν τῶν βαρβάρων, ἱερῶν δὲ καιομένων, ἁπάντων δ’ ἐγγὺς ὄντων τῶν δεινῶν,", "st": "2.37"}, {"sp": "N", "t": "ἀκούοντες δ’ ἐν ταὐτῷ συμμεμειγμένου Ἑλληνικοῦ καὶ βαρβαρικοῦ παιῶνος, παρακελευσμοῦ δ’ ἀμφοτέρων καὶ κραυγῆς τῶν διαφθειρομένων, καὶ τῆς θαλάττης μεστῆς τῶν νεκρῶν, καὶ πολλῶν μὲν συμπιπτόντων καὶ φιλίων καὶ πολεμίων ναυαγίων, ἀντιπάλου δὲ πολὺν χρόνον οὔσης τῆς ναυμαχίας δοκοῦντες τοτὲ μὲν νενικηκέναι καὶ σεσῶσθαι, τοτὲ δ’ ἡττῆσθαι καὶ ἀπολωλέναι.", "st": "2.38"}, {"sp": "N", "t": "ἦ που διὰ τὸν παρόντα φόβον πολλὰ μὲν ᾠήθησαν ἰδεῖν ὧν οὐκ εἶδον, πολλὰ δ’ ἀκοῦσαι ὧν οὐκ ἤκουσαν. ποῖαι δ’ οὐχ ἱκετεῖαι θεῶν ἐγένοντο ἢ θυσιῶν ἀναμνήσεις, ἔλεός τε παίδων καὶ γυναικῶν πόθος οἶκτός τε πατέρων καὶ μητέρων, λογισμὸς δ’, εἰ δυστυχήσειαν, τῶν μελλόντων ἔσεσθαι κακῶν;", "st": "2.39"}, {"sp": "N", "t": "τίς οὐκ ἂν θεῶν ἠλέησεν αὐτοὺς ὑπὲρ τοῦ μεγέθους τοῦ κινδύνου; ἢ τίς ἀνθρώπων οὐκ ἂν ἐδάκρυσεν; ἢ τίς τῆς τόλμης αὐτοὺς οὐκ ἂν ἠγάσθη; ἦ πολὺ πλεῖστον ἐκεῖνοι κατὰ τὴν ἀρετὴν ἁπάντων ἀνθρώπων διήνεγκαν καὶ ἐν τοῖς βουλεύμασι καὶ ἐν τοῖς τοῦ πολέμου κινδύνοις, ἐκλιπόντες μὲν τὴν πόλιν, εἰς τὰς ναῦς δ’ ἐμβάντες, τὰς δ’ αὑτῶν ψυχὰς ὀλίγας οὔσας ἀντιτάξαντες τῷ πλήθει τῷ τῆς Ἀσίας ἐπέδειξαν δὲ πᾶσιν ἀνθρώποις,", "st": "2.40"}, {"sp": "N", "t": "νικήσαντες τῇ ναυμαχίᾳ, ὅτι κρεῖττον μετ’ ὀλίγων ὑπὲρ τῆς ἐλευθερίας κινδυνεύειν ἢ μετὰ πολλῶν βασιλευομένων ὑπὲρ τῆς αὑτῶν δουλείας.", "st": "2.41"}, {"sp": "N", "t": "πλεῖστα δὲ καὶ κάλλιστα ἐκεῖνοι ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας συνεβάλοντο, στρατηγὸν μὲν Θεμιστοκλέα, ἱκανώτατον εἰπεῖν καὶ γνῶναι καὶ πρᾶξαι, ναῦς δὲ πλείους τῶν ἄλλων συμμάχων, ἄνδρας δ’ ἐμπειροτάτους. καὶ γὰρ τίνες ἂν τούτοις τῶν ἄλλων Ἑλλήνων ἤρισαν γνώμῃ καὶ πλήθει καὶ ἀρετῇ;", "st": "2.42"}, {"sp": "N", "t": "ὥστε δικαίως μὲν ἀναμφισβήτητα τἀριστεῖα τῆς ναυμαχίας ἔλαβον παρὰ τῆς Ἑλλάδος, εἰκότως δὲ τὴν εὐτυχίαν ὁμονοοῦσαν τοῖς κινδύνοις ἐκτήσαντο, γνησίαν δὲ καὶ αὐτόχθονα τοῖς ἐκ τῆς Ἀσίας βαρβάροις τὴν αὑτῶν ἀρετὴν ἐπεδείξαντο.", "st": "2.43"}, {"sp": "N", "t": "ἐν μὲν οὖν τῇ ναυμαχίᾳ τοιούτους αὑτοὺς παρασχόντες καὶ πολὺ πλεῖστον τῶν κινδύνων μετασχόντες τῇ ἰδίᾳ ἀρετῇ κοινὴν τὴν ἐλευθερίαν καὶ τοῖς ἄλλοις ἐκτήσαντο· ὕστερον δὲ Πελοποννησίων διατειχιζόντων τὸν Ἰσθμόν, καὶ ἀγαπώντων μὲν τῇ σωτηρίᾳ, νομιζόντων δ’ ἀπηλλάχθαι τοῦ κατὰ θάλατταν κινδύνου, καὶ διανοουμένων τοὺς ἄλλους Ἕλληνας περιιδεῖν ὑπὸ τοῖς βαρβάροις γενομένους,", "st": "2.44"}, {"sp": "N", "t": "ὀργισθέντες Ἀθηναῖοι συνεβούλευον αὐτοῖς, εἰ ταύτην τὴν γνώμην ἕξουσι, περὶ ἅπασαν τὴν Πελοπόννησον τεῖχος περιβαλεῖν· εἰ γὰρ αὐτοὶ ὑπὸ ⟨τῶν⟩ Ἑλλήνων προδιδόμενοι μετὰ τῶν βαρβάρων ἔσονται, οὔτ’ ἐκείνοις δεήσειν χιλίων νεῶν οὔτε τούτους ὠφελήσειν τὸ ἐν Ἰσθμῷ τεῖχος· ἀκινδύνως γὰρ ἔσεσθαι τὴν τῆς θαλάττης ἀρχὴν βασιλέως.", "st": "2.45"}, {"sp": "N", "t": "διδασκόμενοι δὲ καὶ νομίζοντες αὐτοὶ μὲν ἄδικά τε ποιεῖν καὶ κακῶς βουλεύεσθαι, Ἀθηναίους δὲ δίκαιά τε λέγειν καὶ τὰ βέλτιστα αὐτοῖς παραινεῖν, ἐβοήθησαν εἰς Πλαταιάς· ἀποδράντων δὲ ὑπὸ νύκτα τῶν πλείστων συμμάχων ἐκ τῶν τάξεων διὰ τὸ πλῆθος τῶν πολεμίων, Λακεδαιμόνιοι μὲν καὶ Τεγεᾶται τοὺς βαρβάρους ἐτρέψαντο, Ἀθηναῖοι δὲ καὶ Πλαταιεῖς πάντας τοὺς Ἕλληνας ἐνίκων μαχόμενοι τοὺς ἀπογνόντας τῆς ἐλευθερίας καὶ ὑπομείναντας τὴν δουλείαν.", "st": "2.46"}, {"sp": "N", "t": "ἐν ἐκείνῃ δὲ τῇ ἡμέρᾳ καλλίστην τελευτὴν τοῖς προτέροις κινδύνοις ἐπιθέντες, βέβαιον μὲν τὴν ἐλευθερίαν τῇ Εὐρώπῃ κατειργάσαντο, ἐν ἅπασι δὲ τοῖς κινδύνοις δόντες ἔλεγχον τῆς ἑαυτῶν ἀρετῆς, καὶ μόνοι καὶ μεθ’ ἑτέρων, καὶ πεζομαχοῦντες καὶ ναυμαχοῦντες, καὶ πρὸς ⟨τοὺς⟩ βαρβάρους καὶ πρὸς τοὺς Ἕλληνας, ὑπὸ πάντων ἠξιώθησαν, καὶ μεθ’ ὧν ἐκινδύνευον καὶ πρὸς οὓς ἐπολέμουν, ἡγεμόνες γενέσθαι τῆς Ἑλλάδος.", "st": "2.47"}, {"sp": "N", "t": "ὑστέρῳ δὲ χρόνῳ Ἑλληνικοῦ πολέμου καταστάντος διὰ ζῆλον τῶν γεγενημένων καὶ φθόνον τῶν πεπραγμένων, μέγα μὲν ἅπαντες φρονοῦντες, μικρῶν δ’ ἐγκλημάτων ἕκαστοι δεόμενοι, ναυμαχίας Ἀθηναίοις πρὸς Αἰγινήτας καὶ τοὺς ἐκείνων συμμάχους γενομένης ἑβδομήκοντα τριήρεις αὐτῶν ἐλάμβανον.", "st": "2.48"}, {"sp": "N", "t": "πολιορκούντων δὲ κατὰ τὸν αὐτὸν χρόνον Αἴγυπτόν τε καὶ Αἴγιναν, καὶ τῆς ἡλικίας ἀπούσης ἔν τε ταῖς ναυσὶ καὶ ἐν τῷ πεζῷ στρατεύματι, Κορίνθιοι καὶ οἱ ἐκείνων σύμμαχοι, ἡγούμενοι ἢ εἰς ἔρημον τὴν χώραν ἐμβαλεῖν ἢ ἐξ Αἰγίνης ἄξειν τὸ στρατόπεδον, ἐξελθόντες πανδημεὶ Γεράνειαν κατέλαβον·", "st": "2.49"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ τῶν μὲν ἀπόντων, τῶν δ’ ἐγγὺς ὄντων, οὐδένα ἐτόλμησαν μεταπέμψασθαι· ταῖς δ’ αὑτῶν ψυχαῖς πιστεύσαντες καὶ τῶν ἐπιόντων καταφρονήσαντες οἱ γεραίτεροι καὶ οἱ τῆς ἡλικίας ἐντὸς γεγονότες ἠξίουν αὐτοὶ μόνοι τὸν κίνδυνον ποιήσασθαι, οἱ μὲν ἐμπειρία τὴν ἀρετήν,", "st": "2.50"}, {"sp": "N", "t": "οἱ δὲ φύσει κεκτημένοι· καὶ οἱ μὲν αὐτοὶ πολλαχοῦ ἀγαθοὶ γεγενημένοι, οἱ δ’ ἐκείνους μιμούμενοι, τῶν μὲν πρεσβυτέρων ἄρχειν ἐπισταμένων, τῶν δὲ νεωτέρων τὸ ἐπιταττόμενον ποιεῖν δυναμένων,", "st": "2.51"}, {"sp": "N", "t": "Μυρωνίδου στρατηγοῦντος ἀπαντήσαντες αὐτοὶ εἰς τὴν Μεγαρικὴν ἐνίκων μαχόμενοι ἅπασαν τὴν δύναμιν τὴν ἐκείνων τοῖς ἤδη ἀπειρηκόσι καὶ τοῖς οὔπω δυναμένοις, τοὺς εἰς τὴν σφετέραν ἐμβαλεῖν ἀξιώσαντας, εἰς τὴν ἀλλοτρίαν ἀπαντήσαντες,", "st": "2.52"}, {"sp": "N", "t": "τρόπαιον δὲ στήσαντες καλλίστου μὲν αὐτοῖς ἔργου, αἰσχίστου δὲ τοῖς πολεμίοις, οἱ μὲν οὐκέτι τοῖς σώμασιν, οἱ δ’ οὔπω δυνάμενοι, ταῖς δὲ ψυχαῖς ἀμφότεροι κρείττους γενόμενοι, μετὰ καλλίστης δόξης εἰς τὴν αὑτῶν ἀπελθόντες οἱ μὲν πάλιν ἐπαιδεύοντο, οἱ δὲ περὶ τῶν λοιπῶν ἐβουλεύοντο.", "st": "2.53"}, {"sp": "N", "t": "καθ’ ἕκαστον μὲν οὖν οὐ ῥᾴδιον τὰ ὑπὸ πολλῶν κινδυνευθέντα ὑφ’ ἑνὸς ῥηθῆναι, οὐδὲ τὰ ἐν ἅπαντι τῷ χρόνῳ πραχθέντα ἐν μιᾷ ἡμέρᾳ δηλωθῆναι. τίς γὰρ ἂν ἢ λόγος ἢ χρόνος ἢ ῥήτωρ ἱκανὸς γένοιτο μηνῦσαι τὴν τῶν ἐνθάδε κειμένων ἀνδρῶν ἀρετήν;", "st": "2.54"}, {"sp": "N", "t": "μετὰ πλείστων γὰρ πόνων καὶ φανερωτάτων ἀγώνων καὶ καλλίστων κινδύνων ἐλευθέραν μὲν ἐποίησαν τὴν Ἑλλάδα, μεγίστην δ’ ἀπέδειξαν τὴν ἑαυτῶν πατρίδα, ἑβδομήκοντα μὲν ἔτη τῆς θαλάττης ἄρξαντες, ἀστασιάστους δὲ παρασχόντες τοὺς συμμάχους,", "st": "2.55"}, {"sp": "N", "t": "οὐ τοῖς ὀλίγοις τοὺς πολλοὺς δουλεύειν ἀξιώσαντες, ἀλλὰ τὸ ἴσον ἔχειν ἅπαντας ἀναγκάσαντες, οὐδὲ τοὺς συμμάχους ἀσθενεῖς ποιοῦντες, ἀλλὰ κἀκείνους ἰσχυροὺς καθιστάντες, καὶ τὴν αὑτῶν δύναμιν τοσαύτην ἐπιδείξαντες, ὥσθ’ ὁ μέγας βασιλεὺς οὐκέτι τῶν ἀλλοτρίων ἐπεθύμει, ἀλλ’ ἐδίδου τῶν ἑαυτοῦ καὶ περὶ τῶν λοιπῶν ἐφοβεῖτο,", "st": "2.56"}, {"sp": "N", "t": "καὶ οὔτε τριήρεις ἐν ἐκείνῳ τῷ χρόνῳ ἐκ τῆς Ἀσίας ἔπλευσαν, οὔτε τύραννος ἐν τοῖς Ἕλλησι κατέστη, οὔτε Ἑλληνὶς πόλις ὑπὸ τῶν βαρβάρων ἠνδραποδίσθη· τοσαύτην σωφροσύνην καὶ δέος ἡ τούτων ἀρετὴ πᾶσιν ἀνθρώποις παρεῖχεν. ὧν ἕνεκα δεῖ μόνους καὶ προστάτας τῶν Ἑλλήνων καὶ ἡγεμόνας τῶν πόλεων γίγνεσθαι.", "st": "2.57"}, {"sp": "N", "t": "ἐπέδειξαν δὲ καὶ ἐν ταῖς δυστυχίαις τὴν ἑαυτῶν ἀρετήν. ἀπολομένων γὰρ τῶν νεῶν ἐν Ἑλλησπόντῳ εἴτε ἡγεμόνος κακίᾳ εἴτε θεῶν διανοίᾳ, καὶ συμφορᾶς ἐκείνης μεγίστης γενομένης καὶ ἡμῖν τοῖς δυστυχήσασι καὶ τοῖς ἄλλοις Ἕλλησιν, ἐδήλωσεν οὐ πολλῷ χρόνῳ ὕστερον ὅτι ἡ τῆς πόλεως δύναμις τῆς Ἑλλάδος ἦν σωτηρία.", "st": "2.58"}, {"sp": "N", "t": "ἑτέρων γὰρ ἡγεμόνων γενομένων ἐνίκησαν μὲν ναυμαχοῦντες τοὺς Ἕλληνας οἱ πρότερον εἰς τὴν θάλατταν οὐκ ἐμβαίνοντες, ἔπλευσαν δ’ εἰς τὴν Εὐρώπην, δουλεύουσι δὲ πόλεις τῶν Ἑλλήνων, τύραννοι δ’ ἐγκαθεστᾶσιν, οἱ μὲν μετὰ τὴν ἡμετέραν συμφοράν, οἱ δὲ μετὰ τὴν νίκην τῶν βαρβάρων.", "st": "2.59"}, {"sp": "N", "t": "ὥστ’ ἄξιον ἦν ἐπὶ τῷδε τῷ τάφῳ τότε κείρασθαι τῇ Ἑλλάδι καὶ πενθῆσαι τοὺς ἐνθάδε κειμένους, ὡς συγκαταθαπτομένης τῆς αὑτῶν ἐλευθερίας τῇ τούτων ἀρετῇ· ὡς δυστυχὴς μὲν ἡ Ἑλλὰς τοιούτων ἀνδρῶν ὀρφανὴ γενομένη, εὐτυχὴς δ’ ὁ τῆς Ἀσίας βασιλεὺς ἑτέρων ἡγεμόνων λαβόμενος· τῇ μὲν γὰρ τούτων στερηθείσῃ δουλεία περιέστηκε, τῷ δ’ ἄλλων ἀρξάντων ζῆλος ἐγγίγνεται τῆς τῶν προγόνων διανοίας.", "st": "2.60"}, {"sp": "N", "t": "ἀλλὰ ταῦτα μὲν ἐξήχθην ὑπὲρ πάσης ὀλοφύρασθαι τῆς Ἑλλάδος· ἐκείνων δὲ τῶν ἀνδρῶν ἄξιον καὶ ἰδίᾳ καὶ δημοσίᾳ μεμνῆσθαι, οἳ φεύγοντες τὴν δουλείαν καὶ περὶ τοῦ δικαίου μαχόμενοι καὶ ὑπὲρ τῆς δημοκρατίας στασιάσαντες πάντας πολεμίους κεκτημένοι εἰς τὸν Πειραιᾶ κατῆλθον, οὐχ ὑπὸ νόμου ἀναγκασθέντες, ἀλλ’ ὑπὸ τῆς φύσεως πεισθέντες, καινοῖς κινδύνοις τὴν παλαιὰν ἀρετὴν τῶν προγόνων μιμησάμενοι,", "st": "2.61"}, {"sp": "N", "t": "ταῖς αὑτῶν ψυχαῖς κοινὴν τὴν πόλιν καὶ τοῖς ἄλλοις κτησόμενοι, θάνατον μετ’ ἐλευθερίας αἱρούμενοι ἢ βίον μετὰ δουλείας, οὐχ ἧττον ταῖς συμφοραῖς αἰσχυνόμενοι ἢ τοῖς ἐχθροῖς ὀργιζόμενοι, μᾶλλον βουληθέντες ἐν τῇ αὑτῶν ἀποθνῄσκειν ἢ ζῆν τὴν ἀλλοτρίαν οἰκοῦντες, συμμάχους μὲν ὅρκους καὶ συνθήκας ἔχοντες, πολεμίους δὲ τοὺς πρότερον ὑπάρχοντας καὶ τοὺς πολίτας τοὺς ἑαυτῶν.", "st": "2.62"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὐ τὸ πλῆθος τῶν ἐναντίων φοβηθέντες, ἀλλ’ ἐν τοῖς σώμασι τοῖς ἑαυτῶν κινδυνεύσαντες, τρόπαιον μὲν τῶν πολεμίων ἔστησαν, μάρτυρας δὲ τῆς αὑτῶν ἀρετῆς ἐγγὺς ὄντας τοῦδε τοῦ μνήματος τοὺς Λακεδαιμονίων τάφους παρέχονται. καὶ γάρ τοι μεγάλην μὲν ἀντὶ μικρᾶς ἀπέδειξαν τὴν πόλιν, ὁμονοοῦσαν δὲ ἀντὶ στασιαζούσης ἀπέφηναν, τείχη δὲ ἀντὶ τῶν καθῃρημένων ἀνέστησαν.", "st": "2.63"}, {"sp": "N", "t": "οἱ δὲ κατελθόντες αὐτῶν, ἀδελφὰ τὰ βουλεύματα τοῖς ἔργοις τῶν ἐνθάδε κειμένων ἐπιδεικνύντες, οὐκ ἐπὶ τιμωρίαν τῶν ἐχθρῶν ἀλλ’ ἐπὶ σωτηρίαν τῆς πόλεως ἐτράποντο, καὶ οὔτε ἐλαττοῦσθαι δυνάμενοι οὔτ’ αὐτοὶ πλέον ἔχειν δεόμενοι τῆς μὲν αὑτῶν ἐλευθερίας καὶ τοῖς βουλομένοις δουλεύειν μετέδοσαν, τῆς δ’ ἐκείνων δουλείας αὐτοὶ μετέχειν οὐκ ἠξίωσαν. ἔργοις δὲ μεγίστοις καὶ καλλίστοις ἀπελογήσαντο,", "st": "2.64"}, {"sp": "N", "t": "ὅτι οὐ κακίᾳ τῇ αὑτῶν οὐδ’ ἀρετῇ ⟨τῇ⟩ τῶν πολεμίων πρότερον ἐδυστύχησεν ἡ πόλις· εἰ γὰρ στασιάσαντες πρὸς ἀλλήλους βίᾳ παρόντων Πελοποννησίων καὶ τῶν ἄλλων ἐχθρῶν εἰς τὴν αὑτῶν οἷοί τε ἐγένοντο κατελθεῖν, δῆλον ὅτι ῥαδίως ἂν ὁμονοοῦντες πολεμεῖν αὐτοῖς ἐδύναντο.", "st": "2.65"}, {"sp": "N", "t": "ἐκεῖνοι μὲν οὖν διὰ τοὺς ἐν Πειραιεῖ κινδύνους ὑπὸ πάντων ἀνθρώπων ζηλοῦνται· ἄξιον δὲ καὶ τοὺς ξένους τοὺς ἐνθάδε κειμένους ἐπαινέσαι, οἳ τῷ πλήθει βοηθήσαντες καὶ περὶ τῆς ἡμετέρας σωτηρίας μαχόμενοι, πατρίδα τὴν ἀρετὴν ἡγησάμενοι, τοιαύτην τοῦ βίου τελευτὴν ἐποιήσαντο· ἀνθ’ ὧν ἡ πόλις αὐτοὺς καὶ ἐπένθησε καὶ ἔθαψε δημοσίᾳ, καὶ ἔδωκεν ἔχειν αὐτοῖς τὸν ἅπαντα χρόνον τὰς αὐτὰς τιμὰς τοῖς ἀστοῖς.", "st": "2.66"}, {"sp": "N", "t": "οἱ δὲ νῦν θαπτόμενοι, βοηθήσαντες Κορινθίοις ὑπὸ παλαιῶν φίλων ἀδικουμένοις καινοὶ σύμμαχοι γενόμενοι, οὐ τὴν αὐτὴν γνώμην Λακεδαιμονίοις ἔχοντες (οἱ μὲν γὰρ τῶν ἀγαθῶν αὐτοῖς ἐφθόνουν, οἱ δὲ ἀδικουμένους αὐτοὺς ἠλέουν, οὐ τῆς προτέρας ἔχθρας μεμνημένοι, ἀλλὰ τὴν παροῦσαν φιλίαν περὶ πολλοῦ ποιούμενοι) πᾶσιν ἀνθρώποις φανερὰν τὴν αὑτῶν ἀρετὴν ἐπεδείξαντο.", "st": "2.67"}, {"sp": "N", "t": "ἐτόλμησαν γὰρ μεγάλην ποιοῦντες τὴν Ἑλλάδα οὐ μόνον ὑπὲρ τῆς αὑτῶν σωτηρίας κινδυνεύειν, ἀλλὰ καὶ ὑπὲρ τῆς τῶν πολεμίων ἐλευθερίας ἀποθνῄσκειν· τοῖς γὰρ Λακεδαιμονίων συμμάχοις περὶ τῆς ἐκείνων ἐλευθερίας ἐμάχοντο. νικήσαντες μὲν γὰρ ἐκείνους τῶν αὐτῶν ἠξίουν, δυστυχήσαντες δὲ βέβαιον τὴν δουλείαν τοῖς ἐν τῇ Πελοποννήσῳ κατέλιπον.", "st": "2.68"}, {"sp": "N", "t": "ἐκείνοις μὲν οὖν οὕτω διακειμένοις ὁ βίος οἰκτρὸς καὶ ὁ θάνατος εὐκτός· οὗτοι δὲ καὶ ζῶντες καὶ ἀποθανόντες ζηλωτοί, παιδευθέντες μὲν ἐν τοῖς τῶν προγόνων ἀγαθοῖς, ἄνδρες δὲ γενόμενοι τήν τε ἐκείνων δόξαν διασώσαντες καὶ τὴν αὑτῶν ἀρετὴν ἐπιδείξαντες.", "st": "2.69"}, {"sp": "N", "t": "πολλῶν μὲν γὰρ καὶ καλῶν αἴτιοι γεγένηνται τῇ ἑαυτῶν πατρίδι, ἐπηνώρθωσαν δὲ τὰ ὑφ’ ἑτέρων δυστυχηθέντα, πόρρω δ’ ἀπὸ τῆς αὑτῶν τὸν πόλεμον κατέστησαν. ἐτελεύτησαν δὲ τὸν βίον, ὥσπερ χρὴ τοὺς ἀγαθοὺς ἀποθνῄσκειν, τῇ μὲν πατρίδι τὰ τροφεῖα ἀποδόντες, τοῖς δὲ θρέψασι λύπας καταλιπόντες.", "st": "2.70"}, {"sp": "N", "t": "ὥστε ἄξιον τοῖς ζῶσι τούτους ποθεῖν καὶ σφᾶς αὐτοὺς ὀλοφύρεσθαι καὶ τοὺς προσήκοντας αὐτῶν ἐλεεῖν τοῦ ἐπιλοίπου βίου. τίς γὰρ αὐτοῖς ἔτι ἡδονὴ καταλείπεται τοιούτων ἀνδρῶν θαπτομένων, οἳ πάντα περὶ ἐλάττονος τῆς ἀρετῆς ἡγούμενοι αὑτοὺς μὲν ἀπεστέρησαν βίου, χήρας δὲ γυναῖκας ἐποίησαν, ὀρφανοὺς δὲ τοὺς αὑτῶν παῖδας ἀπέλιπον, ἐρήμους δ’ ἀδελφοὺς καὶ πατέρας καὶ μητέρας κατέστησαν;", "st": "2.71"}, {"sp": "N", "t": "πολλῶν δὲ καὶ δεινῶν ὑπαρχόντων τοὺς μὲν παῖδας αὐτῶν ζηλῶ, ὅτι νεώτεροί εἰσιν ἢ ὥστε εἰδέναι οἵων πατέρων ἐστέρηνται, ἐξ ὧν δ’ οὗτοι γεγόνασιν, οἰκτείρω, ὅτι πρεσβύτεροι ἢ ὥστε ἐπιλαθέσθαι τῆς δυστυχίας τῆς ἑαυτῶν.", "st": "2.72"}, {"sp": "N", "t": "τί γὰρ ἂν τούτων ἀνιαρότερον γένοιτο, ἢ τεκεῖν μὲν καὶ θρέψαι καὶ θάψαι τοὺς αὑτῶν, ἐν δὲ τῷ γήρᾳ ἀδυνάτους μὲν εἶναι τῷ σώματι, πασῶν δ’ ἀπεστερημένους τῶν ἐλπίδων ἀφίλους καὶ ἀπόρους γεγονέναι, ὑπὲρ δὲ τῶν αὐτῶν πρότερον ζηλοῦσθαι καὶ νῦν ἐλεεῖσθαι, ποθεινότερον δ’ αὐτοῖς εἶναι τὸν θάνατον τοῦ βίου; ὅσῳ γὰρ ἄνδρες ἀμείνους ἦσαν, τοσούτῳ τοῖς καταλειπομένοις τὸ πένθος μεῖζον.", "st": "2.73"}, {"sp": "N", "t": "πῶς δ’ αὐτοὺς χρὴ λῆξαι τῆς λύπης; πότερον ἐν ταῖς τῆς πόλεως συμφοραῖς; ἀλλὰ τότε αὐτῶν εἰκὸς καὶ τοὺς ἄλλους μεμνῆσθαι. ἀλλ’ ἐν ταῖς εὐτυχίαις ταῖς κοιναῖς; ἀλλ’ ἱκανὸν λυπῆσαι, τῶν μὲν σφετέρων τέκνων τετελευτηκότων, τῶν δὲ ζώντων ἀπολαυόντων τῆς τούτων ἀρετῆς. ἀλλ’ ἐν τοῖς ἰδίοις κινδύνοις, ὅταν ὁρῶσι τοὺς μὲν πρότερον ὄντας φίλους φεύγοντας τὴν αὑτῶν ἀπορίαν, τοὺς δ’ ἐχθροὺς μέγα φρονοῦντας ἐπὶ ταῖς δυστυχίαις ταῖς τούτων;", "st": "2.74"}, {"sp": "N", "t": "μόνην δ’ ἄν μοι δοκοῦμεν ταύτην τοῖς ἐνθάδε κειμένοις ἀποδοῦναι χάριν, εἰ τοὺς μὲν τοκέας αὐτῶν ὁμοίως ὥσπερ ἐκεῖνοι περὶ πολλοῦ ποιοίμεθα, τοὺς δὲ παῖδας οὕτως ἀσπαζοίμεθα ὥσπερ αὐτοὶ πατέρες ὄντες, ταῖς δὲ γυναιξὶν εἰ τοιούτους βοηθοὺς ἡμᾶς αὐτοὺς παρέχοιμεν, οἷοίπερ ἐκεῖνοι ζῶντες ἦσαν. τίνας γὰρ ἂν εἰκότως μᾶλλον τιμῷμεν τῶν ἐνθάδε κειμένων;", "st": "2.75"}, {"sp": "N", "t": "τίνας δ’ ἂν τῶν ζώντων δικαιότερον περὶ πολλοῦ ποιοίμεθα ἢ τοὺς τούτοις προσήκοντας, οἳ τῆς μὲν τούτων ἀρετῆς τὸ ἴσον τοῖς ἄλλοις ἀπέλαυσαν, ἀποθανόντων δὲ μόνοι γνησίως τῆς δυστυχίας μετέχουσιν;", "st": "2.76"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ οἶδ’ ὅ τι δεῖ τοιαῦτα ὀλοφύρεσθαι· οὐ γὰρ ἐλανθάνομεν ἡμᾶς αὐτοὺς ὄντες θνητοί· ὥστε τί δεῖ, ἃ πάλαι προσεδοκῶμεν πείσεσθαι, ὑπὲρ τούτων νῦν ἄχθεσθαι, ἢ λίαν οὕτω βαρέως φέρειν ἐπὶ ταῖς τῆς φύσεως συμφοραῖς, ἐπισταμένους ὅτι ὁ θάνατος κοινὸς καὶ τοῖς χειρίστοις καὶ τοῖς βελτίστοις; οὔτε γὰρ τοὺς πονηροὺς ὑπερορᾷ οὔτε τοὺς ἀγαθοὺς θαυμάζει,", "st": "2.77"}, {"sp": "N", "t": "ἀλλ’ ἴσον ἑαυτὸν παρέχει πᾶσιν. εἰ μὲν γὰρ οἷόν τε ἦν τοῖς τοὺς ἐν τῷ πολέμῳ κινδύνους διαφυγοῦσιν ἀθανάτους εἶναι τὸν λοιπὸν χρόνον, ἄξιον τοῖς ζῶσι τὸν ἅπαντα χρόνον πενθεῖν τοὺς τεθνεῶτας· νῦν δὲ ἥ τε φύσις καὶ νόσων ἥττων καὶ γήρως, ὅ τε δαίμων ὁ τὴν ἡμετέραν μοῖραν εἰληχὼς ἀπαραίτητος.", "st": "2.78"}, {"sp": "N", "t": "ὥστε προσήκει τούτους εὐδαιμονεστάτους ἡγεῖσθαι, οἵτινες ὑπὲρ μεγίστων καὶ καλλίστων κινδυνεύσαντες οὕτω τὸν βίον ἐτελεύτησαν, οὐκ ἐπιτρέψαντες περὶ αὑτῶν τῇ τύχῃ, οὐδ’ ἀναμείναντες τὸν αὐτόματον θάνατον, ἀλλ’ ἐκλεξάμενοι τὸν κάλλιστον. καὶ γάρ τοι ἀγήρατοι μὲν αὐτῶν αἱ μνῆμαι, ζηλωταὶ δὲ ὑπὸ πάντων ἀνθρώπων αἱ τιμαί· οἳ πενθοῦνται μὲν διὰ τὴν φύσιν ὡς θνητοί,", "st": "2.79"}, {"sp": "N", "t": "ὑμνοῦνται δὲ ὡς ἀθάνατοι διὰ τὴν ἀρετήν. καὶ γάρ τοι θάπτονται δημοσία, καὶ ἀγῶνες τίθενται ἐπ’ αὐτοῖς ῥώμης καὶ σοφίας καὶ πλούτου, ὡς ἀξίους ὄντας τοὺς ἐν τῷ τετελευτηκότας ταῖς αὐταῖς τιμαῖς καὶ τοὺς ἀθανάτους τιμᾶσθαι.", "st": "2.80"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν αὐτοὺς καὶ μακαρίζω τοῦ θανάτου καὶ ζηλῶ, καὶ μόνοις τούτοις ἀνθρώπων οἶμαι κρεῖττον εἶναι γενέσθαι, οἵτινες, ἐπειδὴ θνητῶν σωμάτων ἔτυχον, ἀθάνατον μνήμην διὰ τὴν ἀρετὴν ⟨τὴν⟩ αὑτῶν κατέλιπον· ὅμως δ’ ἀνάγκη τοῖς ἀρχαίοις ἔθεσι χρῆσθαι, καὶ θεραπεύοντας τὸν πάτριον νόμον ὀλοφύρεσθαι τοὺς θαπτομένους.", "st": "2.81"}, {"sp": "HDR", "t": "Γʹ. Πρὸς Σίμωνα ἀπολογία", "st": "3"}, {"sp": "N", "t": "πολλὰ καὶ δεινὰ συνειδὼς Σίμωνι, ὦ βουλή, οὐκ ἄν ποτ’ αὐτὸν εἰς τοσοῦτον τόλμης ἡγησάμην ἀφικέσθαι, ὥστε ὑπὲρ ὧν αὐτὸν ἔδει δοῦναι δίκην, ὑπὲρ τούτων ὡς ἀδικούμενον ἔγκλημα ποιήσασθαι καὶ οὕτω μέγαν καὶ σεμνὸν ὅρκον διομοσάμενον εἰς ὑμᾶς ἐλθεῖν.", "st": "3.1"}, {"sp": "N", "t": "εἰ μὲν οὖν ἄλλοι τινὲς ἔμελλον περὶ ἐμοῦ διαγνώσεσθαι, σφόδρα ἂν ἐφοβούμην τὸν κίνδυνον, ὁρῶν ὅτι καὶ παρασκευαὶ καὶ τύχαι ἐνίοτε τοιαῦται γίγνονται, ὥστε πολλὰ καὶ παρὰ γνώμην ἀποβαίνειν τοῖς κινδυνεύουσιν· εἰς ὑμᾶς δ’ εἰσελθὼν ἐλπίζω τῶν δικαίων τεύξεσθαι.", "st": "3.2"}, {"sp": "N", "t": "μάλιστα δ’ ἀγανακτῶ, ὦ βουλή, ὅτι περὶ τῶν πραγμάτων εἰπεῖν ἀναγκασθήσομαι πρὸς ὑμᾶς, ὑπὲρ ὧν ἐγὼ αἰσχυνόμενος, εἰ μέλλοιεν πολλοί μοι συνείσεσθαι, ἠνεσχόμην ἀδικούμενος. ἐπειδὴ δὲ Σίμων με εἰς τοιαύτην ἀνάγκην κατέστησεν, οὐδὲν ἀποκρυψάμενος ἅπαντα διηγήσομαι πρὸς ὑμᾶς τὰ πεπραγμένα. ἀξιῶ δέ,", "st": "3.3"}, {"sp": "N", "t": "ὦ βουλή, εἰ μὲν ἀδικῶ, μηδεμιᾶς συγγνώμης τυγχάνειν· ἐὰν δὲ περὶ τούτων ἀποδείξω ὡς οὐκ ἔνοχός εἰμι οἷς Σίμων διωμόσατο, ἄλλως δὲ ὑμῖν φαίνωμαι παρὰ τὴν ἡλικίαν τὴν ἐμαυτοῦ ἀνοητότερον πρὸς τὸ μειράκιον διατεθείς, αἰτοῦμαι ὑμᾶς μηδέν με χείρω νομίζειν, εἰδότας ὅτι ἐπιθυμῆσαι μὲν ἅπασιν ἀνθρώποις ἔνεστιν, οὗτος δὲ βέλτιστος ἂν εἴη καὶ σωφρονέστατος, ὅστις κοσμιώτατα τὰς συμφορὰς φέρειν δύναται. οἷς ἅπασιν ἐμποδὼν ἐμοὶ γεγένηται Σίμων οὑτοσί, ὡς ἐγὼ ὑμῖν ἐπιδείξω.", "st": "3.4"}, {"sp": "N", "t": "ἡμεῖς γὰρ ἐπεθυμήσαμεν, ὦ βουλή, Θεοδότου, Πλαταϊκοῦ μειρακίου, καὶ ἐγὼ μὲν εὖ ποιῶν αὐτὸν ἠξίουν εἶναί μοι φίλον, οὗτος δὲ ὑβρίζων καὶ παρανομῶν ᾤετο ἀναγκάσειν αὐτὸν ποιεῖν ὅ τι βούλοιτο. ὅσα μὲν οὖν ἐκεῖνος κακὰ ὑπ’ αὐτοῦ πέπονθε, πολὺ ἂν ἔργον εἴη λέγειν· ὅσα δὲ εἰς ἐμὲ αὐτὸν ἐξημάρτηκεν,", "st": "3.5"}, {"sp": "N", "t": "ἡγοῦμαι ταῦθ’ ὑμῖν προσήκειν ἀκοῦσαι. πυθόμενος γὰρ ὅτι τὸ μειράκιον ἦν παρ’ ἐμοί, ἐλθὼν ἐπὶ τὴν οἰκίαν τὴν ἐμὴν νύκτωρ μεθύων, ἐκκόψας τὰς θύρας εἰσῆλθεν εἰς τὴν γυναικωνῖτιν, ἔνδον οὐσῶν τῆς τε ἀδελφῆς τῆς ἐμῆς καὶ τῶν ἀδελφιδῶν, αἳ οὕτω κοσμίως βεβιώκασιν ὥστε καὶ ὑπὸ τῶν οἰκείων ὁρώμεναι αἰσχύνεσθαι.", "st": "3.6"}, {"sp": "N", "t": "οὗτος τοίνυν εἰς τοῦτο ἦλθεν ὕβρεως ὥστ’ οὐ πρότερον ἠθέλησεν ἀπελθεῖν, πρὶν αὐτὸν ἡγούμενοι δεινὰ ποιεῖν οἱ παραγενόμενοι καὶ οἱ μετ’ αὐτοῦ ἐλθόντες, ἐπὶ παῖδας κόρας καὶ ὀρφανὰς εἰσιόντα, ἐξήλασαν βίᾳ. καὶ τοσούτου ἐδέησεν αὐτῷ μεταμελῆσαι τῶν ὑβρισμένων, ὥστε ἐξευρὼν οὗ ἐδειπνοῦμεν ἀτοπώτατον πρᾶγμα καὶ ἀπιστότατον ἐποίησεν, εἰ μή τις εἰδείη τὴν τούτου μανίαν.", "st": "3.7"}, {"sp": "N", "t": "ἐκκαλέσας γάρ με ἔνδοθεν, ἐπειδὴ τάχιστα ἐξῆλθον, εὐθύς με τύπτειν ἐπεχείρησεν· ἐπειδὴ δὲ αὐτὸν ἠμυνάμην, ἐκστὰς ἔβαλλέ με λίθοις. καὶ ἐμοῦ μὲν ἁμαρτάνει, Ἀριστοκρίτου δέ, ὃς παρ’ ἐμὲ ἦλθε μετ’ αὐτοῦ, βαλὼν λίθῳ συντρίβει τὸ μέτωπον.", "st": "3.8"}, {"sp": "N", "t": "ἐγὼ τοίνυν, ὦ βουλή, ἡγούμενος μὲν δεινὰ πάσχειν, αἰσχυνόμενος δέ, ὅπερ ἤδη καὶ πρότερον εἶπον, τῇ συμφορᾷ, ἠνειχόμην, καὶ μᾶλλον ᾑρούμην μὴ λαβεῖν τούτων τῶν ἁμαρτημάτων δίκην ἢ δόξαι τοῖς πολίταις ἀνόητος εἶναι, εἰδὼς ὅτι τῇ μὲν τούτου πονηρίᾳ πρέποντα ἔσται τὰ πεπραγμένα, ἐμοῦ δὲ πολλοὶ καταγελάσονται τοιαῦτα πάσχοντος τῶν φθονεῖν εἰθισμένων, ἐάν τις ἐν τῇ πόλει προθυμῆται χρηστὸς εἶναι.", "st": "3.9"}, {"sp": "N", "t": "οὕτω δὲ σφόδρα ἠπορούμην ὅ τι χρησαίμην, ὦ βουλή, τῇ τούτου παρανομίᾳ, ὥστε ἔδοξέ μοι κράτιστον εἶναι ἀποδημῆσαι [ἐκ τῆς πόλεως]. λαβὼν δὴ τὸ μειράκιον (ἅπαντα γὰρ δεῖ τἀληθῆ λέγειν) ᾠχόμην ἐκ τῆς πόλεως. ἐπειδὴ δὲ ᾤμην ἱκανὸν εἶναι τὸν χρόνον Σίμωνι ἐπιλαθέσθαι μὲν τοῦ νεανίσκου, μεταμελῆσαι δὲ τῶν πρότερον ἡμαρτημένων,", "st": "3.10"}, {"sp": "N", "t": "ἀφικνοῦμαι πάλιν. κἀγὼ μὲν ᾠχόμην εἰς Πειραιᾶ, οὗτος δ’ αἰσθόμενος εὐθέως ἥκοντα τὸν Θεόδοτον καὶ διατρίβοντα παρὰ Λυσιμάχῳ, ὃς ᾤκει πλησίον τῆς οἰκίας ἧς οὗτος ἐμεμίσθωτο, παρεκάλεσέ τινας τῶν τούτου ἐπιτηδείων. καὶ οὗτοι μὲν ἠρίστων καὶ ἔπινον, φύλακας δὲ κατέστησαν ἐπὶ τοῦ τέγους, ἵν’, ὁπότε ἐξέλθοι τὸ μειράκιον,", "st": "3.11"}, {"sp": "N", "t": "εἰσαρπάσειαν αὐτόν. ἐν δὲ τούτῳ τῷ καιρῷ ἀφικνοῦμαι ἐγὼ ἐκ Πειραιῶς, καὶ τρέπομαι παριὼν ὡς τὸν Λυσίμαχον· ὀλίγον δὲ χρόνον διατρίψαντες ἐξερχόμεθα. οὗτοι δ’ ἤδη μεθύοντες ἐκπηδῶσιν ἐφ’ ἡμᾶς καὶ οἱ μέν τινες αὐτῷ τῶν παραγενομένων οὐκ ἠθέλησαν συνεξαμαρτεῖν, Σίμων δὲ οὑτοσὶ καὶ Θεόφιλος καὶ Πρώταρχος καὶ Αὐτοκλῆς εἷλκον τὸ μειράκιον. ὁ δὲ ῥίψας τὸ ἱμάτιον ᾤχετο φεύγων.", "st": "3.12"}, {"sp": "N", "t": "ἐγὼ δὲ ἡγούμενος ἐκεῖνον μὲν ἐκφεύξεσθαι, τούτους δ’, ἐπειδὴ τάχιστα ἐντύχοιεν ἀνθρώποις, αἰσχυνομένους ἀποτρέψεσθαι — ταῦτα διανοηθεὶς ἑτέραν ὁδὸν ᾠχόμην ἀπιών· οὕτω σφόδρ’ αὐτοὺς ἐφυλαττόμην, καὶ πάντα τὰ ὑπὸ τούτων γιγνόμενα μεγάλην ἐμαυτῷ συμφορὰν ἐνόμιζον.", "st": "3.13"}, {"sp": "N", "t": "κἀνταῦθα μέν, ἵνα φησὶ Σίμων τὴν μάχην γενέσθαι, οὔτε τούτων οὔτε ἡμῶν οὐδεὶς οὔτε κατεάγη τὴν κεφαλὴν οὔτε ἄλλο κακὸν οὐδὲν ἔλαβεν, ὧν ἐγὼ τοὺς παραγενομένους ὑμῖν παρέξομαι μάρτυρας.", "st": "3.14"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "3.15"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὗτος ἦν ὁ ἀδικήσας, ὦ βουλή, καὶ ἐπιβουλεύσας ἡμῖν, καὶ οὐκ ἐγὼ τούτῳ, ὑπὸ τῶν παραγενομένων μεμαρτύρηται ὑμῖν. μετὰ δὲ ταῦτα τὸ μὲν μειράκιον εἰς γναφεῖον κατέφυγεν, οὗτοι δὲ συνεισπεσόντες ἦγον αὐτὸν βίᾳ, βοῶντα καὶ κεκραγότα καὶ μαρτυρόμενον.", "st": "3.15"}, {"sp": "N", "t": "συνδραμόντων δὲ ἀνθρώπων πολλῶν καὶ ἀγανακτούντων τῷ πράγματι καὶ δεινὰ φασκόντων εἶναι τὰ γιγνόμενα, τῶν μὲν λεγομένων οὐδὲν ἐφρόντιζον, Μόλωνα δὲ τὸν γναφέα καὶ ἄλλους τινὰς ἐπαμύνειν ἐπιχειροῦντας συνέκοψαν.", "st": "3.16"}, {"sp": "N", "t": "ἤδη δὲ αὐτοῖς οὖσι παρὰ τὴν Λάμπωνος οἰκίαν ἐγὼ μόνος βαδίζων ἐντυγχάνω, δεινὸν δὲ ἡγησάμενος εἶναι καὶ αἰσχρὸν περιιδεῖν οὕτως ἀνόμως καὶ βιαίως ὑβρισθέντα τὸν νεανίσκον, ἐπιλαμβάνομαι αὐτοῦ. οὗτοι δέ, διότι μὲν τοιαῦτα παρενόμουν εἰς ἐκεῖνον, οὐκ ἠθέλησαν εἰπεῖν ἐρωτηθέντες, ἀφέμενοι δὲ τοῦ νεανίσκου ἔτυπτον ἐμέ. μάχης δὲ γενομένης,", "st": "3.17"}, {"sp": "N", "t": "ὦ βουλή, καὶ τοῦ μειρακίου βάλλοντος αὐτοὺς καὶ περὶ τοῦ σώματος ἀμυνομένου καὶ τούτων ἡμᾶς βαλλόντων, ἔτι δὲ τυπτόντων αὐτὸν ὑπὸ τῆς μέθης καὶ ἐμοῦ ἀμυνομένου, καὶ τῶν παραγενομένων ὡς ἀδικουμένοις ἡμῖν ἁπάντων ἐπικουρούντων, ἐν τούτῳ τῷ θορύβῳ συντριβόμεθα τὰς κεφαλὰς ἅπαντες.", "st": "3.18"}, {"sp": "N", "t": "καὶ οἱ μὲν ἄλλοι οἱ μετὰ τούτου παροινήσαντες, ἐπειδὴ τάχιστά με εἶδον μετὰ ταῦτα, ἐδέοντό μου συγγνώμην ἔχειν, οὐχ ὡς ἀδικούμενοι ἀλλ’ ὡς δεινὰ πεποιηκότες· καὶ ἐξ ἐκείνου τοῦ χρόνου τεττάρων ἐτῶν παρεληλυθότων οὐδέν μοι πώποτε ἐνεκάλεσεν οὐδείς.", "st": "3.19"}, {"sp": "N", "t": "Σίμων δ’ οὑτοσί, πάντων τῶν κακῶν αἴτιος γενόμενος, τὸν μὲν ἄλλον χρόνον ἡσυχίαν ἦγε δεδιὼς περὶ αὑτοῦ, ἐπειδὴ δὲ δίκας ἰδίας ᾔσθετο κακῶς ἀγωνισάμενον ἐξ ἀντιδόσεως, καταφρονήσας μου οὑτωσὶ τολμηρῶς εἰς τοιοῦτον ἀγῶνά με κατέστησεν. ὡς οὖν καὶ ταῦτ’ ἀληθῆ λέγω, τούτων ὑμῖν τοὺς παραγενομένους μάρτυρας παρέξομαι.", "st": "3.20"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "3.21"}, {"sp": "N", "t": "τὰ μὲν οὖν γεγενημένα καὶ ἐμοῦ καὶ τῶν μαρτύρων ἀκηκόατε· ἐβουλόμην δ’ ἄν, ὦ βουλή, Σίμωνα τὴν αὐτὴν γνώμην ἐμοὶ ἔχειν, ἵν’ ἀμφοτέρων ἡμῶν ἀκούσαντες τἀληθῆ ῥᾳδίως ἔγνωτε τὰ δίκαια. ἐπειδὴ δὲ αὐτῷ οὐδὲν μέλει τῶν ὅρκων ὧν ὠμόσατο, πειράσομαι καὶ περὶ ὧν οὗτος ἔψευσται διδάσκειν ὑμᾶς.", "st": "3.21"}, {"sp": "N", "t": "ἐτόλμησε γὰρ εἰπεῖν ὡς αὐτὸς μὲν τριακοσίας δραχμὰς ἔδωκε Θεοδότῳ, συνθήκας πρὸς αὐτὸν ποιησάμενος, ἐγὼ δ’ ἐπιβουλεύσας ἀπέστησα αὐτοῦ τὸ μειράκιον. καίτοι ἐχρῆν αὐτόν, εἴπερ ἦν ταῦτ’ ἀληθῆ, παρακαλέσαντα μάρτυρας ὡς πλείστους κατὰ τοὺς νόμους διαπράττεσθαι περὶ αὐτῶν.", "st": "3.22"}, {"sp": "N", "t": "οὗτος δὲ τοιοῦτον οὐδὲν πώποτε φαίνεται ποιήσας, ὑβρίζων δὲ καὶ τύπτων [ἅμ’] ἀμφοτέρους ἡμᾶς καὶ κωμάζων καὶ τὰς θύρας ἐκβάλλων καὶ νύκτωρ εἰσιὼν ἐπὶ γυναῖκας ἐλευθέρας. ἃ χρὴ μάλιστα, ὦ βουλή, τεκμήρια νομίζειν ὅτι ψεύδεται πρὸς ὑμᾶς.", "st": "3.23"}, {"sp": "N", "t": "σκέψασθε δὲ ὡς ἄπιστα εἴρηκε. τὴν γὰρ οὐσίαν τὴν ἑαυτοῦ ἅπασαν πεντήκοντα καὶ διακοσίων δραχμῶν ἐτιμήσατο. καίτοι θαυμαστὸν εἰ τὸν ἑταιρήσοντα πλειόνων ἐμισθώσατο ὧν αὐτὸς τυγχάνει κεκτημένος.", "st": "3.24"}, {"sp": "N", "t": "εἰς τοῦτο δ’ ἥκει τόλμης ὥστε οὐκ ἐξαρκεῖ περὶ τούτου μόνον αὐτῷ ψεύσασθαι, περὶ τοῦ δεδωκέναι τὸ ἀργύριον, ἀλλὰ καὶ κεκομίσθαι φησί· καίτοι πῶς εἰκός ἐστι τότε μὲν ἡμᾶς τοιαῦτα ἐξαμαρτάνειν οἷα κατηγόρηκεν οὗτος, ἀποστερῆσαι βουλομένους τὰς τριακοσίας δραχμάς, ἐπειδὴ δὲ ἀπεμαχεσάμεθα, τηνικαῦτα ἀποδοῦναι τὸ ἀργύριον αὐτῷ, μήτε ἀφειμένους τῶν ἐγκλημάτων μήτε ἀνάγκης ἡμῖν μηδεμιᾶς γενομένης;", "st": "3.25"}, {"sp": "N", "t": "ἀλλὰ γάρ, ὦ βουλή, πάντα αὐτῷ ταῦτα σύγκειται καὶ μεμηχάνηται, καὶ δοῦναι μέν φησιν, ἵνα μὴ δοκῇ δεινὰ ποιεῖν, εἰ μηδενὸς αὐτῷ συμβολαίου γεγενημένου τοιαῦτα ἐτόλμα ὑβρίζειν τὸ μειράκιον, ἀπειληφέναι δὲ προσποιεῖται, διότι φανερός ἐστιν ἐγκαλέσας οὐδέποτ’ ἀργύριον οὐδὲ μνείαν περὶ τούτου οὐδεμίαν ποιησάμενος.", "st": "3.26"}, {"sp": "N", "t": "φησὶ δ’ ἐπὶ ταῖς αὑτοῦ θύραις ὑπ’ ἐμοῦ δεινῶς διατεθῆναι τυπτόμενος. φαίνεται δὲ πλεῖν ἢ τέτταρα στάδια ἀπὸ τῆς οἰκίας διώξας τὸ μειράκιον οὐδὲν κακὸν ἔχων, καὶ ταῦτα πλεῖν ἢ διακοσίων ἰδόντων ἀνθρώπων ἔξαρνός ἐστι.", "st": "3.27"}, {"sp": "N", "t": "λέγει δ’ ὡς ἡμεῖς ἤλθομεν ἐπὶ τὴν οἰκίαν τὴν τούτου ὄστρακον ἔχοντες, καὶ ὡς ἠπείλουν αὐτῷ ἐγὼ ἀποκτενεῖν, καὶ ὡς τοῦτό ἐστιν ἡ πρόνοια. ἐγὼ δ’ ἡγοῦμαι, ὦ βουλή, ῥᾴδιον εἶναι γνῶναι ὅτι ψεύδεται, οὐ μόνον ὑμῖν τοῖς εἰωθόσι σκοπεῖσθαι περὶ τῶν τοιούτων, ἀλλὰ καὶ τοῖς ἄλλοις ἅπασι.", "st": "3.28"}, {"sp": "N", "t": "τῷ γὰρ ἂν δόξειε πιστὸν ὡς ἐγὼ προνοηθεὶς καὶ ἐπιβουλεύων ἦλθον ἐπὶ τὴν Σίμωνος οἰκίαν μεθ’ ἡμέραν, μετὰ τοῦ μειρακίου, τοσούτων ἀνθρώπων παρ’ αὐτῷ συνειλεγμένων, εἰ μὴ εἰς τοῦτο μανίας ἀφικόμην ὥστε ἐπιθυμεῖν εἷς ὢν πολλοῖς μάχεσθαι, ἄλλως τε καὶ εἰδὼς ὅτι ἀσμένως ἄν με εἶδεν ἐπὶ ταῖς θύραις ταῖς αὑτοῦ, ὃς καὶ ἐπὶ τὴν ἐμὴν οἰκίαν φοιτῶν εἰσῄει βίᾳ, καὶ οὔτε τῆς ἀδελφῆς οὔτε τῶν ἀδελφιδῶν φροντίσας ζητεῖν με ἐτόλμα, καὶ ἐξευρὼν οὗ δειπνῶν ἐτύγχανον,", "st": "3.29"}, {"sp": "N", "t": "ἐκκαλέσας ἔτυπτέ με; καὶ τότε μὲν ἄρα, ἵνα μὴ περιβόητος εἴην, ἡσυχίαν ἦγον, συμφορὰν ἐμαυτοῦ νομίζων τὴν τούτου πονηρίαν· ἐπειδὴ δὲ χρόνος διεγένετο, πάλιν, ὡς οὗτός φησιν,", "st": "3.30"}, {"sp": "N", "t": "ἐπεθύμησα περιβόητος γενέσθαι; καὶ εἰ μὲν ἦν παρὰ τούτῳ τὸ μειράκιον, εἶχεν ἄν τινα λόγον τὸ ψεῦδος αὐτῷ ὡς ἐγὼ διὰ τὴν ἐπιθυμίαν ἠναγκαζόμην ἀνοητότερόν τι ποιεῖν τῶν εἰκότων· νῦν δὲ τούτῳ μὲν οὐδὲ διελέγετο, ἀλλ’ ἐμίσει πάντων ἀνθρώπων μάλιστα, παρ’ ἐμοὶ δ’ ἐτύγχανε διαιτώμενον.", "st": "3.31"}, {"sp": "N", "t": "ὥστε τῷ ὑμῶν πιστὸν ὡς ἐγὼ πρότερον μὲν ἐξέπλευσα ἐκ τῆς πόλεως ἔχων τὸ μειράκιον, ἵνα μὴ τούτῳ μαχοίμην, ἐπειδὴ δὲ ἀφικόμην πάλιν, ἦγον αὐτὸν ἐπὶ τὴν οἰκίαν τὴν Σίμωνος, οὗ πλεῖστα ἔμελλον πράγματα ἕξειν; καὶ ἐπεβούλευον μὲν αὐτῷ,", "st": "3.32"}, {"sp": "N", "t": "οὕτω δὲ ἦλθον ἀπαράσκευος, ὥστε μήτε φίλους μήτε οἰκέτας μήτε ἄλλον ἄνθρωπον παρακαλέσαι μηδένα, εἰ μὴ τοῦτό γε τὸ παιδίον, ὃ ἐπικουρῆσαι μέν μοι οὐκ ἂν ἐδύνατο, μηνῦσαι δὲ ἱκανὸν ἦν βασανιζόμενον, εἴ τι ἐγὼ ἐξημάρτανον;", "st": "3.33"}, {"sp": "N", "t": "ἀλλ’ εἰς τοσοῦτον ἀμαθίας ἀφικόμην, ὥστε ἐπιβουλεύων Σίμωνι οὐκ ἐτήρησα αὐτὸν οὗ μόνον οἷόν τ’ ἦν λαβεῖν, ἢ νύκτωρ ἢ μεθ’ ἡμέραν, ἀλλ’ ἐνταῦθα ἦλθον οὗ αὐτὸς ἔμελλον ὑπὸ πλείστων ὀφθήσεσθαί τε καὶ συγκοπήσεσθαι, ὥσπερ κατ’ ἐμαυτοῦ τὴν πρόνοιαν ἐξευρίσκων, ἵν’ ὡς μάλιστα ὑπὸ τῶν ἐχθρῶν ὑβρισθείην;", "st": "3.34"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ βουλή, καὶ ἐκ τῆς μάχης τῆς γενομένης ῥᾴδιον γνῶναι ὅτι ψεύδεται. τὸ γὰρ μειράκιον ὡς ἔγνω, ῥῖψαν θοἰμάτιον, φεῦγον ᾤχετο, οὗτοι δὲ αὐτὸν ἐπεδίωκον, ἐγὼ δὲ ἑτέραν ἀπελθὼν ὁδὸν ᾠχόμην.", "st": "3.35"}, {"sp": "N", "t": "καίτοι ποτέρους χρὴ αἰτίους τῶν γεγενημένων εἶναι νομίζειν, τοὺς φεύγοντας ἢ τοὺς ζητοῦντας καταλαβεῖν; ἐγὼ μὲν γὰρ ἡγοῦμαι πᾶσιν εἶναι δῆλον ὅτι φεύγουσι μὲν οἱ περὶ αὑτῶν δεδιότες, διώκουσι δὲ οἱ βουλόμενοί τι ποιῆσαι κακόν.", "st": "3.36"}, {"sp": "N", "t": "οὐ τοίνυν ταῦτα εἰκότα ⟨μέν⟩, ἄλλως δὲ περὶ αὐτῶν πέπρακται, ἀλλὰ καταλαβόντες τὸ μειράκιον ἐκ τῆς ὁδοῦ ἦγον βίᾳ, ἐντυχὼν δ’ ἐγὼ τούτων μὲν οὐχ ἡπτόμην, τοῦ μειρακίου δ’ ἐπελαμβανόμην· οὗτοι δὲ ἐκεῖνόν τε ἦγον βίᾳ καὶ ἐμὲ ἔτυπτον. καὶ ταῦθ’ ὑμῖν ὑπὸ τῶν παραγενομένων μεμαρτύρηται. ὥστε δεινὸν εἰ περὶ τούτων ἐγὼ δόξω προνοηθῆναι, περὶ ὧν οὗτοι τυγχάνουσιν οὕτω δεινὰ καὶ παράνομα πεποιηκότες.", "st": "3.37"}, {"sp": "N", "t": "τί δ’ ἄν ποτε ἔπαθον, εἰ τἀναντία τῶν νῦν γεγενημένων ἦν, εἰ πολλοὺς ἔχων τῶν ἐπιτηδείων ἐγώ, ἀπαντήσας Σίμωνι, ἐμαχόμην αὐτῷ καὶ ἔτυπτον αὐτὸν καὶ ἐδίωκον καὶ καταλαβὼν ἄγειν βία ἐζήτουν, ὅπου νῦν τούτου ταῦτα πεποιηκότος ἐγὼ εἰς τοιοῦτον ἀγῶνα καθέστηκα, ἐν ᾧ καὶ περὶ τῆς πατρίδος καὶ τῆς οὐσίας τῆς ἐμαυτοῦ ἁπάσης κινδυνεύω;", "st": "3.38"}, {"sp": "N", "t": "τὸ δὲ μέγιστον καὶ περιφανέστατον πάντων· ὁ γὰρ ἀδικηθείς καὶ ἐπιβουλευθεὶς ὑπ’ ἐμοῦ, ὥς φησιν, οὐκ ἐτόλμησε τεττάρων ἐτῶν ἐπισκήψασθαι εἰς ὑμᾶς. καὶ οἱ μέν ἄλλοι, ὅταν ἐρῶσι καὶ ἀποστερῶνται ὧν ἐπιθυμοῦσι καὶ συγκοπῶσιν, ὀργιζόμενοι παραχρῆμα τιμωρεῖσθαι ζητοῦσιν, οὗτος δὲ χρόνοις ὕστερον.", "st": "3.39"}, {"sp": "N", "t": "ὅτι μὲν οὖν, ὦ βουλή, οὐδενὸς αἴτιός εἰμι τῶν γεγενημένων, ἱκανῶς ἀποδεδεῖχθαι νομίζω· οὕτω δὲ διάκειμαι πρὸς τὰς ἐκ τῶν τοιούτων πραγμάτων διαφοράς, ὥστε ἄλλα πολλὰ ὑβρισμένος ὑπὸ Σίμωνος καὶ καταγεὶς τὴν κεφαλὴν ὑπ’ αὐτοῦ οὐκ ἐτόλμησα αὐτῷ ἐπισκήψασθαι, ἡγούμενος δεινὸν εἶναι, εἰ ἄρα περὶ παίδων ἐφιλονικήσαμεν ἡμεῖς πρὸς ἀλλήλους, τούτου ἕνεκα ἐξελάσαι τινὰς ζητῆσαι ἐκ τῆς πατρίδος.", "st": "3.40"}, {"sp": "N", "t": "ἔπειτα δὲ καὶ οὐδεμίαν ἡγούμην πρόνοιαν εἶναι τραύματος ὅστις μὴ ἀποκτεῖναι βουλόμενος ἔτρωσε. τίς γὰρ οὕτως ἐστὶν εὐήθης,", "st": "3.41"}, {"sp": "N", "t": "ὅστις ἐκ πολλοῦ προνοεῖται ὅπως ἕλκος τις αὐτοῦ τῶν ἐχθρῶν λήψεται; ἀλλὰ δῆλον ὅτι καὶ οἱ τοὺς νόμους ἐνθάδε θέντες, οὐκ εἴ τινες μαχεσάμενοι ἔτυχον ἀλλήλων κατάξαντες τὰς κεφαλάς, ἐπὶ τούτοις ἠξίωσαν τῆς πατρίδος φυγὴν ποιήσασθαι· ἢ πολλούς γ’ ἂν ἐξήλασαν· ἀλλ’ ὅσοι ἐπιβουλεύσαντες ἀποκτεῖναί τινας ἔτρωσαν, ἀποκτεῖναι δὲ οὐκ ἐδυνήθησαν, περὶ τῶν τοιούτων τὰς τιμωρίας οὕτω μεγάλας κατεστήσαντο, ἡγούμενοι, ὑπὲρ ὧν ἐβούλευσαν καὶ προὐνοήθησαν, ὑπὲρ τούτων προσήκειν αὐτοῖς δίκην δοῦναι· εἰ δὲ μὴ κατέσχον, οὐδὲν ἧττον τό γ’ ἐκείνων πεποιῆσθαι.", "st": "3.42"}, {"sp": "N", "t": "καὶ ταῦτα ἤδη καὶ πρότερον πολλάκις ὑμεῖς οὕτω διέγνωτε περὶ τῆς προνοίας. καὶ γὰρ δεινὸν ἂν εἴη, εἰ ὅσοι ἐκ μέθης καὶ φιλονικίας ἢ ἐκ παιδιῶν ἢ ἐκ λοιδορίας ἢ περὶ ἑταίρας μαχόμενοι ἕλκος ἔλαβον, εἰ ὑπὲρ τούτων ὧν, ἐπειδὰν βέλτιον φρονήσωσιν, ἅπασι μεταμέλει, οὕτως καὶ ὑμεῖς μεγάλας καὶ δεινὰς τὰς τιμωρίας ποιήσεσθε, ὥστε ἐξελαύνειν τινὰς τῶν πολιτῶν ἐκ τῆς πατρίδος.", "st": "3.43"}, {"sp": "N", "t": "θαυμάζω δὲ μάλιστα τούτου τῆς διανοίας. οὐ γὰρ τοῦ αὐτοῦ μοι δοκεῖ εἶναι ἐρᾶν τε καὶ συκοφαντεῖν, ἀλλὰ τὸ μὲν τῶν εὐηθεστέρων, τὸ δὲ τῶν πανουργοτάτων. ἐβουλόμην δ’ ἂν ἐξεῖναί μοι παρ’ ὑμῖν καὶ ἐκ τῶν ἄλλων ἐπιδεῖξαι τὴν τούτου πονηρίαν, ἵνα ἠπίστασθε ὅτι πολὺ ἂν δικαιότερον αὐτὸς περὶ θανάτου ἠγωνίζετο ἢ ἑτέρους ὑπὲρ τῆς πατρίδος εἰς κίνδυνον καθίστη. τὰ μὲν οὖν ἄλλα ἐάσω·", "st": "3.44"}, {"sp": "N", "t": "ὃ δ’ ἡγοῦμαι ὑμῖν προσήκειν ἀκοῦσαι καὶ τεκμήριον ἔσεσθαι τῆς τούτου θρασύτητος καὶ τόλμης, περὶ τούτου μνησθήσομαι. ἐν Κορίνθῳ γάρ, ἐπειδὴ ὕστερον ἦλθε τῆς πρὸς τοὺς πολεμίους μάχης καὶ τῆς εἰς Κορώνειαν στρατείας, ἐμάχετο τῷ ταξιάρχῳ Λάχητι καὶ ἔτυπτεν αὐτόν, καὶ πανστρατιᾷ τῶν πολιτῶν ἐξελθόντων, δόξας ἀκοσμότατος εἶναι καὶ πονηρότατος, μόνος Ἀθηναίων ὑπὸ τῶν στρατηγῶν ἐξεκηρύχθη.", "st": "3.45"}, {"sp": "N", "t": "ἔχοιμι δ’ ἂν καὶ ἄλλα πολλὰ εἰπεῖν περὶ τούτου, ἀλλ’ ἐπειδὴ παρ’ ὑμῖν οὐ νόμιμόν ἐστιν ἔξω τοῦ πράγματος λέγειν, ἐκεῖνο ἐνθυμεῖσθε· οὗτοί εἰσιν οἱ βίᾳ εἰς τὴν ἡμετέραν οἰκίαν εἰσιόντες, οὗτοι οἱ διώκοντες, οὗτοι οἱ βίᾳ ἐκ τῆς ὁδοῦ συναρπάζοντες ἡμᾶς.", "st": "3.46"}, {"sp": "N", "t": "ὧν ὑμεῖς μεμνημένοι τὰ δίκαια ψηφίζεσθε, καὶ μὴ περιίδητε ἐκ τῆς πατρίδος ἀδίκως ἐκπεσόντα, ὑπὲρ ἧς ἐγὼ πολλοὺς κινδύνους κεκινδύνευκα καὶ πολλὰς λῃτουργίας λελῃτούργηκα, καὶ κακοῦ μὲν αὐτῇ οὐδενὸς αἴτιος γεγένημαι, οὐδὲ τῶν ἐμῶν προγόνων οὐδείς, ἀγαθῶν δὲ πολλῶν·", "st": "3.47"}, {"sp": "N", "t": "ὥστε δικαίως ἂν ὑφ’ ὑμῶν καὶ ὑπὸ τῶν ἄλλων ἐλεηθείην, οὐ μόνον εἴ τι πάθοιμι ὧν Σίμων βούλεται, ἀλλὰ καὶ ὅτι ἠναγκάσθην ἐκ τοιούτων πραγμάτων εἰς τοιούτους ἀγῶνας καταστῆναι.", "st": "3.48"}, {"sp": "HDR", "t": "Δʹ. Περὶ τραύματος ἐκ προνοίας, ὑπὲρ οὗ καὶ πρὸς ὃν ἄδηλον", "st": "4"}, {"sp": "N", "t": "θαυμαστόν γε, ὦ βουλή, τὸ διαμάχεσθαι περὶ τούτου, ὡς οὐκ ἐγένοντο ἡμῖν διαλλαγαί, καὶ τὸ μὲν ζεῦγος καὶ τὰ ἀνδράποδα, καὶ ὅσα ἐξ ἀγροῦ κατὰ τὴν ἀντίδοσιν ἔλαβε, μὴ ἂν δύνασθαι ἀρνηθῆναι ὡς οὐκ ἀπέδωκε, φανερῶς δὲ περὶ πάντων διαλελυμένον ἀρνεῖσθαι τὰ περὶ τῆς ἀνθρώπου, μὴ κοινῇ ἡμᾶς χρῆσθαι συγχωρῆσαι.", "st": "4.1"}, {"sp": "N", "t": "καὶ τὴν μὲν ἀντίδοσιν δι’ ἐκείνην φανερός ἐστι ποιησάμενος, τὴν δ’ αἰτίαν δι’ ἣν ἀπέδωκεν ἃ ἔλαβεν, οὐκ ἂν ἄλλην ἔχοι εἰπεῖν (βουλόμενος τἀληθῆ λέγειν) ἢ ὅτι οἱ φίλοι περὶ πάντων ἡμᾶς τούτων συνήλλαξαν.", "st": "4.2"}, {"sp": "N", "t": "ἐβουλόμην δ’ ἂν μὴ ἀπολαχεῖν αὐτὸν κριτὴν Διονυσίοις, ἵν’ ὑμῖν φανερὸς ἐγένετο ἐμοὶ διηλλαγμένος, κρίνας τὴν τιμὴν φυλὴν νικᾶν· νῦν δὲ ἔγραψε μὲν ταῦτα εἰς τὸ γραμματεῖον, ἀπέλαχε δέ.", "st": "4.3"}, {"sp": "N", "t": "καὶ ὅτι ἀληθῆ ταῦτα λέγω, Φιλῖνος καὶ Διοκλῆς ἴσασιν· ἀλλ’ οὐκ ἔστ’ αὐτοῖς μαρτυρῆσαι μὴ διομοσαμένοις περὶ τῆς αἰτίας ἧς ἐγὼ φεύγω, ἐπεὶ σαφῶς ἔγνωτ’ ἂν ὅτι ἡμεῖς ἦμεν αὐτὸν οἱ κριτὴν ἐμβαλόντες καὶ ἡμῶν ἕνεκα ἐκαθίζετο. ἀλλ’ ἦν, εἰ βούλεται, ἐχθρός·", "st": "4.4"}, {"sp": "N", "t": "δίδωμι γὰρ αὐτῷ τοῦτο· οὐδὲν γὰρ διαφέρει. οὐκοῦν ἦλθον αὐτὸς αὐτὸν ἀποκτενῶν, ὡς οὗτός φησι, καὶ βία εἰς τὴν οἰκίαν εἰσῆλθον. δὶα τί οὖν οὐκ ἀπέκτεινα, ὑποχείριον λαβὼν τὸ σῶμα, καὶ τοσοῦτον κρατήσας ὥστε καὶ τὴν ἄνθρωπον λαβεῖν; φρασάτω πρὸς ὑμᾶς. ἀλλ’ οὐκ ἔχει εἰπεῖν.", "st": "4.5"}, {"sp": "N", "t": "καὶ μὴν οὐδείς γε ὑμῶν ἀγνοεῖ ὅτι θᾶττον ἂν ἐγχειριδίῳ πληγεὶς ἀπέθανεν ἢ πὺξ παιόμενος. φαίνεται τοίνυν οὐδ’ αὐτὸς αἰτιώμενος τοιοῦτόν τι ἔχοντας ἡμᾶς ἐλθεῖν, ἀλλ’ ὀστράκῳ φησὶ πληγῆναι. καίτοι φανερὸν ἤδη ἐξ ὧν εἴρηκεν, ὅτι οὐ πρόνοια γεγένηται.", "st": "4.6"}, {"sp": "N", "t": "οὐ γὰρ ἂν οὕτως ἤλθομεν, ἀδήλου ὄντος εἰ παρὰ τούτῳ εὑρήσομεν ὄστρακον ἢ ὅτῳ αὐτὸν ἀποκτενοῦμεν, ἀλλ’ οἴκοθεν ἔχοντες ἂν ἐβαδίζομεν. νῦν δὲ ὁμολογούμεθα πρὸς παῖδας καὶ αὐλητρίδας καὶ μετ’ οἴνου ἐλθόντες. ὥστε πῶς ταῦτ’ ἐστὶ πρόνοια; ἐγὼ μὲν γὰρ οἶμαι οὐδαμῶς.", "st": "4.7"}, {"sp": "N", "t": "ἀλλ’ οὗτος ἐναντίως τοῖς ἄλλοις δύσερώς ἐστι, καὶ ἀμφότερα βούλεται, τό τε ἀργύριον μὴ ἀποδοῦναι καὶ τὴν ἄνθρωπον ἔχειν. εἶτα ὑπὸ τῆς ἀνθρώπου παρωξυμμένος ὀξύχειρ λίαν καὶ πάροινός ἐστιν, ἀνάγκη δὲ ἀμύνασθαι. ἡ δὲ τοτὲ μὲν ἐμὲ περὶ πολλοῦ τοτὲ δὲ τοῦτόν φησι ποιεῖσθαι, βουλομένη ὑπ’ ἀμφοτέρων ἐρᾶσθαι.", "st": "4.8"}, {"sp": "N", "t": "καὶ ἐγὼ μὲν καὶ ἐξ ἀρχῆς εὐκόλως εἶχον καὶ νῦν ἔτι ἔχω· ὁ δ’ εἰς τοῦτο βαρυδαιμονίας ἥκει, ὥστε οὐκ αἰσχύνεται τραύματ’ ὀνομάζων τὰ ὑπώπια καὶ ἐν κλίνῃ περιφερόμενος καὶ δεινῶς προσποιούμενος διακεῖσθαι ἕνεκα πόρνης ἀνθρώπου, ἣν ἔξεστιν αὐτῷ ἀναμφισβητήτως ἔχειν ἐμοὶ ἀποδόντι τἀργύριον.", "st": "4.9"}, {"sp": "N", "t": "καὶ φησὶ μὲν δεινῶς ἐπιβουλευθῆναι καὶ πρὸς ἅπανθ’ ἡμῖν ἀμφισβητεῖ, ἐξὸν δ’ ἐκ τῆς ἀνθρώπου βασανισθείσης τὸν ἔλεγχον ποιήσασθαι οὐκ ἠθέλησεν· ἣ πρῶτον μὲν τοῦτ’ ἂν κατεῖπεν, πότερα κοινὴ ἡμῖν ἦν ἢ ἰδία τούτου, καὶ πότερα τὸ ἥμισυ τοῦ ἀργυρίου ἐγὼ συνεβαλόμην ἢ οὗτος ἅπαν ἔδωκε, καὶ εἰ διηλλαγμένοι ἢ ἔτι ἐχθροὶ ἦμεν,", "st": "4.10"}, {"sp": "N", "t": "ἔτι δὲ εἰ μεταπεμφθέντες ἤλθομεν ἢ οὐδενὸς καλέσαντος, καὶ εἰ οὗτος ἦρχε χειρῶν ἀδίκων ἢ ἐγὼ πρότερος τοῦτον ἐπάταξα. τούτων καθ’ ἓν ἕκαστον καὶ τῶν ἄλλων οὐδὲν ἦν ὅ τι οὐ ῥᾴδιον τοῖς τε ἄλλοις ἐμφανὲς καὶ τούτοις ποιῆσαι.", "st": "4.11"}, {"sp": "N", "t": "ὅτι μὲν οὖν οὔτε πρόνοια ἐγένετο οὔτε ἀδικῶ τοῦτον, ὦ βουλή, ἐκ τοσούτων τεκμηρίων καὶ μαρτυριῶν ὑμῖν ἐπιδέδεικται· ἀξιῶ δ’ ὅσον ἂν ἐγένετο σημεῖον τούτῳ πρὸς τὸ δοκεῖν ἀληθῆ λέγειν φυγόντος ἐμοῦ τὴν βάσανον, τοσοῦτον ἐμοὶ τεκμήριον γενέσθαι ὅτι οὐ ψεύδομαι, διότι οὗτος οὐκ ἠθέλησεν ἐκ τῆς ἀνθρώπου ποιήσασθαι τὸν ἔλεγχον, καὶ μὴ τοσοῦτον ἰσχῦσαι τοὺς τούτου λόγους, ὅτι φησὶν αὐτὴν ἐλευθέραν εἶναι. ὁμοίως γὰρ προσήκει κἀμοὶ τῆς ἐλευθερίας, τὸ ἴσον καταθέντι ἀργύριον.", "st": "4.12"}, {"sp": "N", "t": "ἀλλὰ ψεύδεται καὶ οὐκ ἀληθῆ λέγει. ἢ δεινόν γε, εἰ εἰς μὲν λύσιν τοῦ σώματος [ἔδωκα τὸ ἀργύριον] ἐκ τῶν πολεμίων ἐξῆν ἄν μοι χρῆσθαι αὐτῇ ὅ τι ἐβουλόμην, κινδυνεύοντι δέ μοι περὶ τῆς πατρίδος οὐδὲ πυθέσθαι παρ’ αὐτῆς τἀληθῆ ἐκγενήσεται περὶ ὧν εἰς τὴν κρίσιν καθέστηκα· καὶ μὲν δὴ πολὺ ἂν δικαιότερον ἐπὶ ταύτῃ τῇ αἰτίᾳ βασανισθείη ἢ ἐπὶ τῇ ἐκ τῶν πολεμίων λύσει πραθείη, ὅσῳ παρὰ μὲν ἐκείνων βουλομένων ἀπολῦσαι ἔστι καὶ ἄλλοθεν εὐπορήσαντι κομισθῆναι, ἐπὶ δὲ τοῖς ἐχθροῖς γενόμενον οὐ δυνατόν· οὐ γὰρ ἀργύριον λαβεῖν προθυμοῦνται, ἀλλ’ ἐκ τῆς πατρίδος ἐκβαλεῖν ἔργον ποιοῦνται.", "st": "4.13"}, {"sp": "N", "t": "ὥσθ’ ὑμῖν προσήκει μὴ ἀποδέχεσθαι αὐτοῦ διὰ τοῦτο οὐκ ἀξιοῦντος βασανισθῆναι τὴν ἄνθρωπον, ὅτι αὐτὴν ἐλευθέραν ἐσκήπτετο εἶναι, ἀλλὰ πολὺ μᾶλλον συκοφαντίαν καταγιγνώσκειν, ὅτι παραλιπὼν ἔλεγχον οὕτως ἀκριβῆ ἐξαπατήσειν ὑμᾶς ῥᾳδίως ᾠήθη.", "st": "4.14"}, {"sp": "N", "t": "οὐ γὰρ δήπου τήν γε τούτου πρόκλησιν πιστοτέραν ὑμᾶς νομίζειν δεῖ τῆς ἡμετέρας, ἐφ’ οἷς αὑτοῦ οἰκέτας ἠξίου βασανίζεσθαι. ἃ μὲν γὰρ ἐκεῖνοι ᾔδεσαν, ἐλθόντας ἡμᾶς ὡς τοῦτον, καὶ ἡμεῖς ὁμολογοῦμεν. εἰ δὲ μεταπεμφθέντες ἢ μή, καὶ πότερον πρότερος ἐπλήγην ἢ ἐπάταξα,", "st": "4.15"}, {"sp": "N", "t": "ἐκείνη μᾶλλον ἂν ᾔδει. ἔτι δὲ τοὺς μὲν τούτου οἰκέτας ἰδίους ὄντας τούτου εἰ ἐβασανίζομεν, ἀνοήτως ἄν τι τούτῳ χαριζόμενοι καὶ παρὰ τὴν ἀλήθειαν ἐμοῦ κατεψεύσαντο· αὕτη δὲ ὑπῆρχε κοινή, ὁμοίως ἀμφοτέρων ἀργύριον κατατεθηκότων, καὶ μάλιστα ᾔδει· διὰ ταύτην ἅπαντα τὰ πραχθέντα ἡμῖν γεγένηται·", "st": "4.16"}, {"sp": "N", "t": "καὶ οὐ λήσει οὐδέν’ ὅτι ταύτης ἔγωγ’ ἄνισον εἶχον βασανισθείσης, ἀλλ’ ἀπεκινδύνευον τοῦτο· πολὺ γὰρ περὶ πλείονος τοῦτον ἢ ἐμὲ φαίνεται ποιησαμένη, καὶ μετὰ μὲν τούτου ἐμὲ ἠδικηκυῖα, μετ’ ἐμοῦ δ’ οὐδεπώποτε εἰς τοῦτον ἐξαμαρτοῦσα. ἀλλ’ ὅμως ἐγὼ μὲν εἰς ταύτην κατέφυγον, οὗτος δὲ οὐκ ἐπίστευσεν αὐτῇ.", "st": "4.17"}, {"sp": "N", "t": "οὔκουν δεῖ ὑμᾶς, ὦ βουλή, τηλικούτου ὄντος τοῦ κινδύνου, ῥᾳδίως ἀποδέχεσθαι τοὺς τούτου λόγους, ἀλλ’ ἐνθυμουμένους ὅτι περὶ τῆς πατρίδος μοι καὶ τοῦ βίου ὁ ἀγών ἐστιν, ἐν ὑπολόγῳ ταύτας τὰς προκλήσεις ποιεῖσθαι. καὶ μὴ ζητεῖτε τούτων ἔτι μείζους πίστεις· οὐ γὰρ ἂν ἔχοιμι εἰπεῖν ἀλλ’ ἢ ταύτας, ὡς οὐδὲν εἰς τοῦτον προὐνοήθην.", "st": "4.18"}, {"sp": "N", "t": "ἀγανακτῶ δ’, ὦ βουλή, εἰ διὰ πόρνην καὶ δούλην ἄνθρωπον περὶ τῶν μεγίστων εἰς κίνδυνον καθέστηκα, τί κακὸν πώποτε τὴν πόλιν ἢ αὐτὸν τοῦτον εἰργασμένος, ἢ εἰς τίνα τῶν πολιτῶν ὁτιοῦν ἐξαμαρτών; οὐδὲν γὰρ ἔμοιγέ ἐστι τοιοῦτον πεπραγμένον, ἀλλ’ ἀλογώτατον πάντων κινδυνεύω πολὺ μείζω συμφορὰν ἐμαυτῷ διὰ τούτους ἐπαγαγέσθαι.", "st": "4.19"}, {"sp": "N", "t": "πρὸς οὖν παίδων καὶ γυναικῶν καὶ θεῶν τῶν τόδε τὸ χωρίον ἐχόντων ἱκετεύω ὑμᾶς καὶ ἀντιβολῶ, ἐλεήσατέ με, καὶ μὴ περιίδητε ἐπὶ τούτῷ γενόμενον, μηδὲ ἀνηκέστῳ συμφορᾷ περιβάλητε· οὐ γὰρ ἄξιος οὔτ’ ἐγὼ φεύγειν τὴν ἐμαυτοῦ, οὔτε οὗτος τοσαύτην δίκην παρ’ ἐμοῦ λαβεῖν ὑπὲρ ὧν φησιν ἠδικῆσθαι, οὐκ ἠδικημένος.", "st": "4.20"}, {"sp": "HDR", "t": "Εʹ. Ὑπὲρ Καλλίου ἱεροσυλίας ἀπολογία", "st": "5"}, {"sp": "N", "t": "εἰ μὲν περὶ ἄλλου τινὸς ἢ τοῦ σώματος, ὦ ἄνδρες δικασταί, Καλλίας ἠγωνίζετο, ἐξήρκει ἄν μοι καὶ τὰ παρὰ τῶν ἄλλων εἰρημένα· νῦν δέ μοι δοκεῖ αἰσχρὸν εἶναι, κελεύοντος καὶ δεομένου, καὶ φίλου ὄντος καὶ ἐμοὶ καὶ ἕως ἔζη τῷ πατρί, καὶ πολλῶν συμβολαίων ἡμῖν πρὸς ἀλλήλους γεγενημένων, μὴ βοηθῆσαι Καλλία τὰ δίκαια, ὅπως ἂν δύνωμαι.", "st": "5.1"}, {"sp": "N", "t": "ἐνόμιζον μὲν οὖν οὕτως μετοικεῖν αὐτὸν ἐν ταύτῃ τῇ πόλει, ὥστε πολὺ πρότερον ἀγαθοῦ τινος τεύξεσθαι παρ’ ὑμῶν ἢ ἐπὶ τοιαύταις αἰτίαις εἰς τοσοῦτον κίνδυνον καταστήσεσθαι· νῦν δὲ οἱ ἐπιβουλεύοντες οὐχ ἧττον ἐπικίνδυνον ποιοῦσι τὸν βίον τοῖς μηδὲν ἀδικοῦσιν ἢ τοῖς πολλῶν κακῶν αἰτίοις οὖσιν.", "st": "5.2"}, {"sp": "N", "t": "ὑμᾶς δὲ ἄξιον μὴ τοὺς μὲν τῶν θεραπόντων λόγους πιστοὺς νομίζειν, τοὺς δὲ τούτων ἀπίστους, ἐνθυμουμένους ὅτι Καλλίᾳ μὲν οὐδεὶς πώποτε οὔτ’ ἰδιώτης ἐνεκάλεσεν οὔτε ἄρχων, οἰκῶν δ’ ἐν ταύτῃ τῇ πόλει πολλὰ μὲν ἀγαθὰ ὑμᾶς ἐποίησεν, οὐδεμίαν δὲ σχὼν αἰτίαν εἰς τοῦτο τῆς ἡλικίας ἀφῖκται, οὗτοι δὲ ἐν ἅπαντι τῷ βίῳ μεγάλα ἡμαρτηκότες καὶ πολλῶν κακῶν πεπειραμένοι, ὥσπερ ἀγαθοῦ τινος αἴτιοι γεγενημένοι περὶ ἐλευθερίας νυνὶ ποιοῦνται τοὺς λόγους. καὶ οὐ θαυμάζω·", "st": "5.3"}, {"sp": "N", "t": "ἴσασι γὰρ ὅτι, ἐὰν ⟨μὲν⟩ ψευδόμενοι ἐλεγχθῶσιν, οὐδὲν μεῖζον τῶν ὑπαρχόντων πείσονται, ἐὰν δὲ ἐξαπατήσωσι, τῶν παρόντων κακῶν ἔσονται ἀπηλλαγμένοι. καίτοι τοὺς τοιούτους οὔτε κατηγόρους οὔτε μάρτυρας πιστοὺς χρὴ νομίζειν εἶναι, οἵτινες αὐτοὶ μεγάλα κερδαίνοντες περὶ ἑτέρων ποιοῦνται τοὺς λόγους, ἀλλὰ πολὺ μᾶλλον ὅσοι τῷ δημοσίῳ βοηθοῦντες εἰς κινδύνους σφᾶς αὐτοὺς καθιστᾶσιν.", "st": "5.4"}, {"sp": "N", "t": "ἄξιον δέ μοι δοκεῖ εἶναι οὐ τούτων ἴδιον ἡγεῖσθαι τὸν ἀγῶνα, ἀλλὰ κοινὸν ἁπάντων τῶν ἐν τῇ πόλει· οὐ γὰρ τούτοις μόνοις εἰσὶ θεράποντες, ἀλλὰ καὶ τοῖς ἄλλοις ἅπασιν, οἳ πρὸς τὴν τούτων τύχην ἀποβλέποντες οὐκέτι σκέψονται ὅ τι ⟨ἂν⟩ ἀγαθὸν εἰργασμένοι τοὺς δεσπότας ἐλεύθεροι γένοιντο, ἀλλ’ ὅ τι ψεῦδος περὶ αὐτῶν μηνύσαντες …", "st": "5.5"}, {"sp": "HDR", "t": "Ϛʹ. Κατ’ Ἀνδοκίδου ἀσεβείας", "st": "6"}, {"sp": "N", "t": "… ἔδησε τὸν ἵππον ἐκ τοῦ ῥόπτρου τοῦ ἱεροῦ ὡς ἀποδιδούς, τῇ δ’ ἐπιούσῃ ὑφείλετο. οὗτος οὖν ὁ ταῦτα ποιήσας θανάτῳ τῷ ἀλγίστῳ ἀπώλετο, λιμῷ· πολλῶν γὰρ καὶ ἀγαθῶν αὐτῷ ἐπὶ τὴν τράπεζαν παρατιθεμένων ὄζειν ἐδόκει τοῦ ἄρτου καὶ τῆς μάζης κάκιστον, καὶ οὐκ ἐδύνατο ἐσθίειν.", "st": "6.1"}, {"sp": "N", "t": "καὶ ταῦτα πολλοὶ ἡμῶν ἤκουον τοῦ ἱεροφάντου λέγοντος.", "st": "6.2"}, {"sp": "N", "t": "δίκαιον οὖν μοι δοκεῖ εἶναι νῦν ἐπὶ τούτῳ τὰ τότε λεχθέντα ἀναμνῆσαι, καὶ μὴ μόνον τοὺς τούτου φίλους ὑπὸ τούτου καὶ τῶν τούτου λόγων ἀπόλλυσθαι, ἀλλὰ καὶ αὐτὸν τοῦτον ὑφ’ ἑτέρου.", "st": "6.3"}, {"sp": "N", "t": "ἀδύνατον δὲ καὶ ὑμῖν ἐστι, περὶ τοιούτου πράγματος φέρουσι τὴν ψῆφον, ἢ κατελεῆσαι ἢ καταχαρίσασθαι Ἀνδοκίδῃ, ἐπισταμένοις ὅτι ἐναργῶς τὼ θεὼ τούτω τιμωρεῖτον τοὺς ἀδικοῦντας· ἐλπίσαι οὖν χρὴ πάντα ἄνθρωπον ταὐτὰ καὶ ἑαυτῷ καὶ ἑτέρῳ ἔσεσθαι.", "st": "6.3"}, {"sp": "N", "t": "φέρε γάρ, ἐὰν νυνὶ Ἀνδοκίδης ἀθῷος ἀπαλλαγῇ ⟨δι’⟩ ὑμᾶς ἐκ τοῦδε τοῦ ἀγῶνος καὶ ἔλθῃ κληρωσόμενος τῶν ἐννέα ἀρχόντων καὶ λάχῃ βασιλεύς, ἄλλο τι ἢ ὑπὲρ ὑμῶν καὶ θυσίας θύσει καὶ εὐχὰς εὔξεται κατὰ τὰ πάτρια, τὰ μὲν ἐν τῷ ἐνθάδε Ἐλευσινίω, τὰ δὲ ἐν τῷ Ἐλευσῖνι ἱερῷ, καὶ τῆς ἑορτῆς ἐπιμελήσεται μυστηρίοις, ὅπως ἂν μηδεὶς ἀδικῇ μηδὲ ἀσεβῇ τὰ ἱερά;", "st": "6.4"}, {"sp": "N", "t": "καὶ τίνα γνώμην οἴεσθε ἕξειν τοὺς μύστας τοὺς ἀφικνουμένους, ἐπειδὰν ἴδωσι τὸν βασιλέα ὅστις ἐστὶ καὶ ἀναμνησθῶσι πάντα τὰ ἠσεβημένα αὐτῷ, ἢ τοὺς ἄλλους Ἕλληνας, οἳ ἕνεκα ταύτης τῆς ἑορτῆς ⟨ἔρχονται⟩ ἢ θύειν εἰς ταύτην τὴν πανήγυριν βουλόμενοι ἢ θεωρεῖν;", "st": "6.5"}, {"sp": "N", "t": "οὐδὲ γὰρ ἀγνὼς ὁ Ἀνδοκίδης οὔτε τοῖς ἔξω οὔτε τοῖς ἐνθάδε διὰ τὰ ἠσεβημένα. ἀναγκαίως γὰρ ἔχει ἀπὸ τῶν πολὺ διαφερόντων ἢ κακῶν ἢ ἀγαθῶν ἔργων τοὺς ποιήσαντας γιγνώσκεσθαι. ἔπειτα δὲ καὶ διώχληκε πόλεις πολλὰς ἐν τῇ ἀποδημίᾳ, Σικελίαν, Ἰταλίαν, Πελοπόννησον, Θετταλίαν, Ἑλλήσποντον, Ἰωνίαν, Κύπρον· βασιλέας πολλοὺς κεκολάκευκεν, ᾧ ἂν συγγένηται, πλὴν τοῦ Συρακοσίου Διονυσίου.", "st": "6.6"}, {"sp": "N", "t": "οὗτος δὲ ἢ πάντων εὐτυχέστατός ἐστιν ἢ πλεῖστον γνώμῃ διαφέρει τῶν ἄλλων, ὃς μόνος τῶν συγγενομένων Ἀνδοκίδῃ οὐκ ἐξηπατήθη ὑπ’ ἀνδρὸς τοιούτου, ὃς τέχνην ταύτην ἔχει, τοὺς μὲν ἐχθροὺς μηδὲν ποιεῖν κακόν, τοὺς δὲ φίλους ὅ τι ἂν δύνηται κακόν. ὥστε μὰ τὸν Δία οὐ ῥᾴδιόν ἐστιν ὑμῖν αὐτῷ οὐδὲν χαρισαμένοις παρὰ τὸ δίκαιον λαθεῖν τοὺς Ἕλληνας.", "st": "6.7"}, {"sp": "N", "t": "νῦν οὖν ὑμῖν ἐν ἀνάγκῃ ἐστὶ βουλεύσασθαι περὶ αὐτοῦ· εὖ γὰρ ἐπίστασθε, ὦ ἄνδρες Ἀθηναῖοι, ὅτι οὐχ οἷόν τε ὑμῖν ἐστιν ἅμα τοῖς τε νόμοις τοῖς πατρίοις καὶ Ἀνδοκίδῃ χρῆσθαι, ἀλλὰ δυοῖν θάτερον, ἢ τοὺς νόμους ἐξαλειπτέον ἐστὶν ἢ ἀπαλλακτέον τοῦ ἀνδρός.", "st": "6.8"}, {"sp": "N", "t": "εἰς τοσοῦτον δὲ τόλμης ἀφῖκται, ὥστε καὶ λέγει περὶ τοῦ νόμου, ὡς καθῄρηται ὁ περὶ αὐτοῦ κείμενος καὶ ἔξεστιν αὐτῷ ἤδη εἰσιέναι εἰς τὴν ἀγορὰν καὶ εἰς τὰ ἱερά … ἂν ἔτι καὶ νῦν Ἀθηναίων ἐν τῷ βουλευτηρίῳ.", "st": "6.9"}, {"sp": "N", "t": "καίτοι Περικλέα ποτέ φασι παραινέσαι ὑμῖν περὶ τῶν ἀσεβούντων, μὴ μόνον χρῆσθαι τοῖς γεγραμμένοις νόμοις περὶ αὐτῶν, ἀλλὰ καὶ τοῖς ἀγράφοις, καθ’ οὓς Εὐμολπίδαι ἐξηγοῦνται, οὓς οὐδείς πω κύριος ἐγένετο καθελεῖν οὐδὲ ἐτόλμησεν ἀντειπεῖν, οὐδὲ αὐτὸν τὸν θέντα ἴσασιν· ἡγεῖσθαι γὰρ ἂν αὐτοὺς οὕτως οὐ μόνον τοῖς ἀνθρώποις ἀλλὰ καὶ τοῖς θεοῖς διδόναι δίκην.", "st": "6.10"}, {"sp": "N", "t": "Ἀνδοκίδης δὲ τοσοῦτον καταπεφρόνηκε τῶν θεῶν καὶ ὧν ἐκείνοις δεῖ τιμωρεῖν, ὥστε πρὶν [μᾶλλον ἢ ἧττον] ἢ ἐπιδεδημηκέναι δέκα ἡμέρας ἐν τῇ πόλει προσεκαλέσατο δίκην ἀσεβείας πρὸς τὸν βασιλέα, καὶ ἔλαχεν Ἀνδοκίδης ⟨ὢν⟩ καὶ πεποιηκὼς ἃ οὗτος πεποίηκε περὶ τοὺς θεοὺς καὶ (ἵνα μᾶλλον πρόσσχητε τὸν νοῦν) φάσκων τὸν Ἄρχιππον ἀσεβεῖν περὶ τὸν Ἑρμῆν τὸν αὑτοῦ πατρῷον. ὁ δὲ Ἄρχιππος ἠντεδίκει ἦ μὴν τὸν Ἑρμῆν ὑγιᾶ τε καὶ ὅλον εἶναι, καὶ μηδὲν παθεῖν ὧνπερ οἱ ἄλλοι Ἑρμαῖ·", "st": "6.11"}, {"sp": "N", "t": "ὅμως μέντοι ἵνα μὴ ὑπὸ τούτου τοιούτου ὄντος πράγματ’ ἔχοι, δοὺς ἀργύριον ἀπηλλάγη. καίτοι ὁπότε οὗτος παρ’ ἑτέρου ἠξίωσε δίκην ἀσεβείας λαβεῖν, ἦ που ἑτέρους γε παρὰ τούτου λαβεῖν δίκαιον καὶ εὐσεβές ἐστιν.", "st": "6.12"}, {"sp": "N", "t": "ἀλλὰ λέξει δεινὸν εἶναι, εἰ ὁ μὲν μηνυτὴς τὰ ἔσχατα πείσεται, οἱ δὲ μηνυθέντες τῶν αὐτῶν ὑμῖν ἐπίτιμοι ὄντες μεθέξουσι. καίτοι οὐχ ὑπὲρ αὑτοῦ ἀπολογήσεται, ἀλλὰ καὶ τῶν ἄλλων κατηγορήσει. τοὺς μὲν οὖν ἄλλους οἱ ἐπιτάξαντες καταδέξασθαι ἀδικοῦσι καὶ τοῦ αὐτοῦ ἀσεβήματος αἴτιοί εἰσιν· εἰ δ’ ὑμεῖς αὐτοκράτορες ὄντες αὐτοί ἐστε οἱ ἀφελόντες τὰς τιμωρίας τῶν θεῶν, ἀλλ’ ⟨οὐχ⟩ οὗτοι αἴτιοι ἔσονται. ὑμεῖς οὖν μὴ βούλεσθε εἰς ὑμᾶς τὴν αἰτίαν ταύτην περιτρέψαι, ἐξὸν τὸν ἀδικοῦντα κολάσασιν ἀπηλλάχθαι.", "st": "6.13"}, {"sp": "N", "t": "ἔπειτα δ’ ἐκεῖνοι μὲν ἀρνοῦνται τὰ μεμηνυμένα, οὗτος δὲ ὁμολογεῖ ποιῆσαι. καίτοι καὶ ἐν Ἀρείῳ πάγῳ, ἐν τῷ σεμνοτάτῳ καὶ δικαιοτάτῳ δικαστηρίῳ, ὁμολογῶν μὲν ἀδικεῖν ἀποθνῄσκει, ἐὰν δὲ ἀμφισβητῇ, ἐλέγχεται, καὶ πολλοὶ οὐδὲν ἔδοξαν ἀδικεῖν. οὔκουν ὁμοίαν χρὴ γνώμην ἔχειν περί τε τῶν ἀρνουμένων καὶ περὶ τῶν ὁμολογούντων.", "st": "6.14"}, {"sp": "N", "t": "δεινὸν δέ μοι δοκεῖ εἶναι· ἐὰν μέν τις ἀνδρὸς σῶμα τρώσῃ, κεφαλὴν ἢ πρόσωπον ἢ χεῖρας ἢ πόδας, οὗτος μὲν κατὰ τοὺς νόμους τοὺς ἐξ Ἀρείου πάγου φεύξεται τὴν τοῦ ἀδικηθέντος πόλιν, καὶ ἐὰν κατίῃ, ἐνδειχθεὶς θανάτῳ ζημιωθήσεται· ἐὰν δέ τις τὰ αὐτὰ ταῦτα ἀδικήσῃ τὰ ἀγάλματα τῶν θεῶν, οὐδ’ αὐτῶν κωλύσετε τῶν ἱερῶν ἐπιβαίνειν ἢ εἰσιόντα ⟨οὐ⟩ τιμωρήσεσθε; καὶ μὲν δὴ τούτων καὶ δίκαιον καὶ ἀγαθόν ἐστιν ἐπιμελεῖσθαι, ὑφ’ ὧν καὶ εὖ καὶ κακῶς δυνήσεσθε πάσχειν.", "st": "6.15"}, {"sp": "N", "t": "φασὶ δὲ καὶ τῶν Ἑλλήνων πολλοὺς διὰ τὰ ἐνθάδε ἀσεβήματα ἐκ τῶν παρ’ αὐτοῖς ἱερῶν ἐξείργειν. ὑμεῖς δὲ αὐτοὶ οἱ ἀδικηθέντες περὶ ἐλάττονος ποιεῖσθε τὰ παρ’ ὑμῖν νόμιμα ἢ ἕτεροι τὰ ὑμέτερα.", "st": "6.16"}, {"sp": "N", "t": "τοσοῦτον δ’ οὗτος Διαγόρου τοῦ Μηλίου ἀσεβέστερος γεγένηται· ἐκεῖνος μὲν γὰρ λόγῳ περὶ τὰ ἀλλότρια ἱερὰ καὶ ἑορτὰς ἠσέβει, οὗτος δὲ ἔργῳ περὶ τὰ ἐν τῇ αὑτοῦ πόλει. ὀργίζεσθαι οὖν χρή, ὦ ἄνδρες Ἀθηναῖοι, τοῖς ἀστοῖς ἀδικοῦσι μᾶλλον ἢ τοῖς ξένοις περὶ ταῦτα τὰ ἱερά· τὸ μὲν γὰρ ὥσπερ ἀλλότριόν ἐστιν ἁμάρτημα, τὸ δ’ οἰκεῖον.", "st": "6.17"}, {"sp": "N", "t": "καὶ μὴ οὓς μὲν ἔχετε ἀδικοῦντας ἀφίετε, τοὺς δὲ φεύγοντας ζητεῖτε συλλαμβάνειν, ἐπικηρύττοντες τάλαντον ἀργυρίου δώσειν τῷ ἀπάγοντι ἢ ἀποκτείναντι. εἰ δὲ μή, δόξετε τοῖς Ἕλλησι κομπάζειν μᾶλλον ἢ τιμωρεῖσθαι βούλεσθαι.", "st": "6.18"}, {"sp": "N", "t": "ἐπεδείξατο δὲ καὶ τοῖς Ἕλλησιν ὅτι θεοὺς οὐ νομίζει. οὐ γὰρ ὡς δεδιὼς τὰ πεποιημένα, ἀλλ’ ὡς θαρρῶν, ναυκληρίᾳ ἐπιθέμενος τὴν θάλατταν ἔπλει. ὁ δὲ θεὸς ὑπῆγεν αὐτόν, ἵνα ἀφικόμενος εἰς τὰ ἁμαρτήματα ἐπὶ τῇ ἐμῇ προφάσει δοίη δίκην.", "st": "6.19"}, {"sp": "N", "t": "ἐλπίζω μὲν οὖν αὐτὸν καὶ δώσειν δίκην, θαυμάσιον δὲ οὐδὲν ἄν μοι γένοιτο, οὔτε γὰρ ὁ θεὸς παραχρῆμα κολάζει [ἀλλ’ αὕτη μέν ἐστιν ἀνθρωπίνη δίκη]· πολλαχόθεν δὲ ἔχω τεκμαιρόμενος εἰκάζειν, ὁρῶν καὶ ἑτέρους ἠσεβηκότας χρόνω δεδωκότας δίκην, καὶ τοὺς ἐξ ἐκείνων διὰ τὰ τῶν προγόνων ἁμαρτήματα· ἐν δὲ τούτω τῷ χρόνῳ δέῃ πολλὰ καὶ κινδύνους ὁ θεὸς ἐπιπέμπει τοῖς ἀδικοῦσιν, ὥστε πολλοὺς ἤδη ἐπιθυμῆσαι τελευτήσαντας τῶν κακῶν ἀπηλλάχθαι. ὁ δὲ θεὸς τέλος τούτῳ λυμηνάμενος τῷ βίῳ θάνατον ἐπέθηκε.", "st": "6.20"}, {"sp": "N", "t": "σκέψασθε δὲ καὶ αὐτοῦ Ἀνδοκίδου τὸν βίον, ἀφ’ οὗ ἠσέβηκε, καὶ εἴ τις τοιοῦτος ἕτερός ἐστιν. Ἀνδοκίδης γὰρ ἐπειδὴ ἥμαρτεν, ἐξ ἐπιβολῆς εἰσαχθεὶς εἰς τὸ δικαστήριον, ἔδησεν ἑαυτὸν τιμησάμενος δεσμοῦ, εἰ μὴ παραδοίη τὸν ἀκόλουθον· εὖ δ’ ἤδει οὐ δυνησόμενος παραδοῦναι,", "st": "6.21"}, {"sp": "N", "t": "ὃς διὰ τοῦτον καὶ τὰ τούτου ἁμαρτήματα ἀπέθανεν, ἵνα ⟨μὴ⟩ μηνυτὴς γένοιτο. καίτοι πῶς οὐ θεῶν τις τὴν τούτου γνώμην διέφθειρεν, ὃς ῥᾷον ἡγήσατο δεσμοῦ τιμήσασθαι ἢ ἀργυρίου ἐπ’ ἐλπίδι τῇ αὐτῇ;", "st": "6.22"}, {"sp": "N", "t": "ἐκ δ’ οὖν τούτου τοῦ τιμήματος ἐδέδετο ἐγγὺς ἐνιαυτόν, καὶ ἐμήνυσε δεδεμένος κατὰ τῶν αὑτοῦ συγγενῶν καὶ φίλων, ἀδείας δοθείσης αὐτῷ, εἰ δόξειε τἀληθῆ μηνῦσαι. καὶ τίνα αὐτὸν δοκεῖτε ψυχὴν ἔχειν, ὁπότε τὰ μὲν ἔσχατα καὶ τὰ αἴσχιστα ἐποίει μηνύων κατὰ τῶν ἑαυτοῦ φίλων, ἡ δὲ σωτηρία ἀφανὴς αὐτῷ;", "st": "6.23"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα, ἐπειδὴ ἀπεκτονὼς ἦν οὓς αὐτὸς ἔφη περὶ πλείστου ποιεῖσθαι, ἔδοξε τἀληθῆ μηνῦσαι καὶ ἐλύθη, καὶ προσεψηφίσασθε ὑμεῖς αὐτὸν εἴργεσθαι τῆς ἀγορᾶς καὶ τῶν ἱερῶν, ὥστε μηδ’ ἀδικούμενον ὑπὸ τῶν ἐχθρῶν δύνασθαι δίκην λαβεῖν.", "st": "6.24"}, {"sp": "N", "t": "οὐδεὶς γάρ πω, ἐξ ὅσου Ἀθῆναι ἀείμνηστοί εἰσιν, ἐπὶ τοιαύτῃ αἰτίᾳ ἠτιμώθη. δικαίως· οὐδὲ γὰρ ἔργα τοιαῦτα οὐδείς πω εἰργάσατο. καὶ τούτων πότερα τοὺς θεοὺς χρὴ ἢ τὸ αὐτόματον αἰτιᾶσθαι;", "st": "6.25"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἔπλευσεν ὡς τὸν Κιτιῶν βασιλέα, καὶ προδιδοὺς ληφθεὶς ὑπ’ αὐτοῦ ἐδέθη, καὶ οὐ μόνον τὸν θάνατον ἐφοβεῖτο ἀλλὰ καὶ τὰ καθ’ ἡμέραν αἰκίσματα, οἰόμενος τὰ ἀκρωτήρια ζῶντος ἀποτμηθήσεσθαι.", "st": "6.26"}, {"sp": "N", "t": "ἀποδρὰς δὲ ἐκ τούτου τοῦ κινδύνου κατέπλευσεν εἰς τὴν ἑαυτοῦ πόλιν ἐπὶ τῶν τετρακοσίων· ⟨τοσαύτην γὰρ ὁ⟩ θεὸς λήθην ἔδωκεν, ὥστε εἰς τοὺς ἠδικημένους αὐτοὺς ἐπεθύμησεν ἀφικέσθαι. ἀφικόμενος δὲ ἐδέθη καὶ ᾐκίσθη, ἀπώλετο δὲ οὐχί, ἀλλ’ ἐλύθη.", "st": "6.27"}, {"sp": "N", "t": "ἔνθεν δὲ ἔπλευσεν ὡς Εὐαγόραν τὸν Κύπρου βασιλεύοντα, καὶ ἀδικήσας εἵρχθη. ἀποδρὰς δὲ καὶ τοῦτον ἔφευγε μὲν τοὺς ἐνθάδε θεούς, ἔφευγε δὲ τὴν ἑαυτοῦ πόλιν, ἔφευγε δὲ εἰς οὓς τὸ πρῶτον ἀφίκοιτο τόπους. καίτοι τίς χάρις τῷ βίω, κακοπαθεῖν μὲν πολλάκις, ἀναπαύσασθαι δὲ μηδέποτε;", "st": "6.28"}, {"sp": "N", "t": "καταπλεύσας δὲ ἐκεῖθεν δεῦρο εἰς δημοκρατίαν [εἰς τὴν αὑτοῦ πόλιν] τοῖς μὲν πρυτάνεσιν ἔδωκε χρήματα, ἵνα αὐτὸν προσαγάγοιεν ἐνθάδε, ὑμεῖς δ’ αὐτὸν ἐξηλάσατε ἐκ τῆς πόλεως, τοῖς θεοῖς βεβαιοῦντες τοὺς νόμους οὓς ἐψηφίσασθε.", "st": "6.29"}, {"sp": "N", "t": "καὶ τὸν ἄνδρα οὐ δῆμος, οὐκ ὀλιγαρχία, οὐ τύραννος, οὐ πόλις ἐθέλει δέξασθαι διὰ τέλους, ἀλλὰ πάντα τὸν χρόνον, ἐξ ὅσου ἠσέβησεν, ἀλώμενος διάγει, πιστεύων ἀεὶ μᾶλλον τοῖς ἀγνῶσι τῶν γνωρίμων διὰ τὸ ἠδικηκέναι οὓς γιγνώσκει. τὸ δὲ τελευταῖον νῦν ἀφικόμενος εἰς τὴν πόλιν δὶς ἐν τῷ αὐτῷ ἐνδέδεικται.", "st": "6.30"}, {"sp": "N", "t": "καὶ τὸ μὲν σῶμα ἀεὶ ἐν δεσμοῖς ἔχει, ἡ δὲ οὐσία αὐτοῦ ἐλάττων ἐκ τῶν κινδύνων γίγνεται. καίτοι ὅταν τις τὸν αὑτοῦ βίον τοῖς ἐχθροῖς καὶ τοῖς συκοφάνταις διανέμῃ, τοῦτ’ ἔστι τὸ ζῆν βίον ἀβίωτον. ἃ τούτῳ ὁ θεὸς οὐκ ἐπὶ σωτηρία ἐπινοεῖν δίδωσιν, ἀλλὰ τιμωρούμενος τῶν γεγενημένων ἀσεβημάτων.", "st": "6.31"}, {"sp": "N", "t": "τὸ δὲ τελευταῖον νυνὶ παραδέδωκεν αὑτὸν ὑμῖν χρῆσθαι ὅ τι ἂν βούλησθε, οὐ τῷ μὴ ἀδικεῖν πιστεύων, ἀλλ’ ὑπὸ δαιμονίου τινὸς ἀγόμενος ἀνάγκης. οὔκουν χρὴ μὰ τὸν Δία οὔτε πρεσβύτερον ὄντα οὔτε νεώτερον, ὁρῶντας Ἀνδοκίδην ἐκ τῶν κινδύνων σῳζόμενον, συνειδότας αὐτῷ ἔργα ἀνόσια εἰργασμένῳ, ἀθεωτέρους γίγνεσθαι, ἐνθυμουμένους ὅτι ἥμισυς ὁ βίος βιῶναι κρείττων ἀλύπως ἐστὶν ἢ διπλάσιος λυπουμένῳ, ὥσπερ οὗτος.", "st": "6.32"}, {"sp": "N", "t": "εἰς τοσοῦτον δὲ ἀναισχυντίας ἀφῖκται, ὥστε καὶ παρασκευάζεται τὰ πολιτικὰ πράττειν καὶ ἤδη δημηγορεῖ καὶ ἐπιτιμᾷ καὶ ἀποδοκιμάζει τῶν ἀρχόντων τισί. καὶ συμβουλεύει τὴν βουλὴν εἰσιὼν περὶ θυσιῶν καὶ προσόδων καὶ εὐχῶν καὶ μαντειῶν. καίτοι τούτῳ πειθόμενοι ποίοις θεοῖς ἡγήσεσθε κεχαρισμένα ποιεῖν; μὴ γὰρ οἴεσθε, ὦ ἄνδρες δικασταί, εἰ ὑμεῖς βούλεσθε τὰ τούτῳ πεποιημένα ἐπιλαθέσθαι, καὶ τοὺς θεοὺς ἐπιλήσεσθαι.", "st": "6.33"}, {"sp": "N", "t": "ἀξιοῖ δὲ οὐχ ὡς ἠδικηκὼς ἡσυχίαν ἔχων πολιτεύεσθαι, ἀλλ’ ὥσπερ αὐτὸς ἐξευρὼν τοὺς τὴν πόλιν ἀδικήσαντας, οὕτω διανοεῖται, καὶ παρασκευάζεται ὅπως ἑτέρων μεῖζον δυνήσεται, ὥσπερ οὐ διὰ πρᾳότητα καὶ ἀσχολίαν τὴν ὑμετέραν οὐ δεδωκὼς ὑμῖν δίκην, εἰς οὓς νῦν ἁμαρτάνων οὐ λανθάνει, ἀλλ’ ἅμα ἐξελεγχθήσεταί τε καὶ δώσει δίκην.", "st": "6.34"}, {"sp": "N", "t": "ἰσχυριεῖται δὲ καὶ τούτῳ τῷ λόγῳ. ἀναγκαίως γὰρ ἔχει ὑμᾶς διδάσκειν ἃ οὗτος ἀπολογήσεται, ἵν’ ἀκούσαντες παρ’ ἀμφοτέρων ἄμεινον διαγνῶτε. φησὶ γὰρ ἀγαθὰ μεγάλα ποιῆσαι τὴν πόλιν μηνύσας καὶ ἀπαλλάξας δέους καὶ ταραχῆς τῆς τότε. τίς δὲ τῶν μεγάλων κακῶν αἴτιος ἐγένετο;", "st": "6.35"}, {"sp": "N", "t": "οὐκ αὐτὸς οὗτος, ποιήσας ἃ ἐποίησεν; εἶτα τῶν μὲν ἀγαθῶν δεῖ τούτῳ χάριν εἰδέναι, ὅτι ἐμήνυσε, μισθὸν ὑμῶν αὐτῷ διδόντων τὴν ἄδειαν, τῆς δὲ ταραχῆς καὶ τῶν κακῶν ὑμεῖς αἴτιοί ἐστε, ὅτι ἐζητεῖτε τοὺς ἠσεβηκότας; οὐ δήπουθεν, ἀλλ’ αὐτὸ τούτου τοὐναντίον ἐτάραξε μὲν οὗτος τὴν πόλιν, κατεστήσατε δ’ ὑμεῖς.", "st": "6.36"}, {"sp": "N", "t": "πυνθάνομαι δ’ αὐτὸν μέλλειν ἀπολογήσεσθαι ὡς αἱ συνθῆκαι καὶ αὐτῷ εἰσι, καθάπερ καὶ τοῖς ἄλλοις Ἀθηναίοις. καὶ τοῦτο πρόσχημα ποιούμενος οἴεται πολλοὺς ὑμῶν, δεδιότας μὴ λύσητε τὰς συνθήκας, αὐτοῦ ἀποψηφιεῖσθαι.", "st": "6.37"}, {"sp": "N", "t": "ὡς οὖν οὐδὲν προσήκει Ἀνδοκίδῃ τῶν συνθηκῶν, περὶ τούτου λέξω, οὔτε μὰ τὸν Δία τῶν πρὸς Λακεδαιμονίους, ἃς ὑμεῖς συνέθεσθε, οὔτε ὧν πρὸς τοὺς ἐν [τῷ] ἄστει οἱ ἐκ Πειραιῶς. οὐδενὶ γὰρ ἡμῶν τοσούτων ὄντων τὰ αὐτὰ ἁμαρτήματα οὐδ’ ὅμοια ἦν τοῖς Ἀνδοκίδου, ὥστε καὶ τοῦτον ἡμῶν ἀπολαῦσαι.", "st": "6.38"}, {"sp": "N", "t": "ἀλλ’ οὐ μὲν δὴ ἕνεκά γε τούτου διαφερόμενοι, ἐπειδὴ καὶ τούτῳ μετέδομεν τῶν συνθηκῶν, τότε διηλλάγημεν. οὐ γὰρ ἕνεκα ἑνὸς ἀνδρὸς ἀλλ’ ἕνεκα ἡμῶν τῶν ἐξ ἄστεως καὶ ἐκ Πειραιῶς αἱ συνθῆκαι ἐγένοντο καὶ οἱ ὅρκοι, ἐπεί τοι δεινὸν ἂν εἴη, εἰ περὶ Ἀνδοκίδου ἀποδημοῦντος αὐτοὶ ἐνδεεῖς ὄντες ἐπεμελήθημεν, ὅπως ἐξαλειφθείη αὐτῷ τὰ ἁμαρτήματα.", "st": "6.39"}, {"sp": "N", "t": "ἀλλὰ Λακεδαιμονίοι γὰρ ἐν ταῖς πρὸς αὐτοὺς συνθήκαις ἐπεμελήθησαν Ἀνδοκίδου, ὅτι ἔπαθον ἀγαθόν τι ὑπ’ αὐτοῦ· ἀλλ’ ὑμεῖς ἐπεμελήθητέ γε αὐτοῦ; ἀντὶ ποίας εὐεργεσίας; ὅτι πολλάκις δι’ ὑμᾶς ὑπὲρ τῆς πόλεως ἐκινδύνευσεν;", "st": "6.40"}, {"sp": "N", "t": "οὐκ ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, τούτῳ ἀληθὴς αὕτη ἡ ἀπολογία, μηδ’ ὑμεῖς ἐξαπατᾶσθε. οὐ γὰρ τοῦτο λύειν ἐστὶ τὰ συγκείμενα, εἰ Ἀνδοκίδης ἕνεκα τῶν ἰδίων ἁμαρτημάτων δίδωσι δίκην, ἀλλ’ ἐάν τις ἕνεκα τῶν δημοσίων συμφορῶν ἰδία τινὰ τιμωρῆται.", "st": "6.41"}, {"sp": "N", "t": "ἴσως οὖν καὶ Κηφισίου ἀντικατηγορήσει, καὶ ἕξει ὅ τι λέγῃ· τὰ γὰρ ἀληθῆ χρὴ λέγειν. ἀλλ’ ὑμεῖς οὐκ ἂν δύναισθε τῇ αὐτῇ ψήφῳ τόν τε ἀπολογούμενον καὶ τὸν κατηγοροῦντα κολάσαι. ἀλλὰ νῦν μὲν περὶ τούτου καιρός ἐστι γνῶναι τὰ δίκαια, ἕτερος δὲ ἥξει Κηφισίῳ καὶ ἡμῶν ἑκάστῳ, ὧν οὗτος νῦν μεμνήσεται. μὴ οὖν καὶ δι’ ἑτέραν ὀργὴν τούτου ἀδικοῦντος νῦν ἀποψηφίσησθε.", "st": "6.42"}, {"sp": "N", "t": "ἀλλὰ λέξει ὅτι μηνυτὴς ἐγένετο καὶ ἕτερος οὐδεὶς ὑμῖν ἐθελήσει μηνύειν, ἐὰν κολάζητε. Ἀνδοκίδης δὲ ἔχει τὰ μήνυτρα παρ’ ὑμῶν, σώσας τὴν αὑτοῦ ψυχὴν ἑτέρων διὰ ταῦτα ἀποθανόντων. τῆς μὲν οὖν σωτηρίας ὑμεῖς τούτῳ αἴτιοί ἐστε, τῶν δὲ κακῶν τῶνδε καὶ τῶν κινδύνων αὐτὸς ἑαυτῷ, παραβὰς τὰ δόγματα καὶ τὴν ἄδειαν ἐφ’ ᾗ μηνυτὴς ἐγένετο.", "st": "6.43"}, {"sp": "N", "t": "οὔκουν ἐξουσίαν χρὴ ποιεῖν τοῖς μηνυταῖς ἀδικεῖν (ἀρκεῖ γὰρ τὰ πεποιημένα), ἀλλὰ παραβαίνοντας κολάζειν. καὶ οἱ μὲν ἄλλοι μηνυταί, ὁπόσοι ἐπ’ αἰσχραῖς αἰτίαις ἐξεληλεγμένοι σφᾶς αὐτοὺς ἐμήνυσαν, ἓν γοῦν ἐπίστανται, μὴ ἐνοχλεῖν τοῖς ἠδικημένοις, ἡγούμενοι ἀποδημοῦντες μὲν Ἀθηναῖοι καὶ ἐπίτιμοι δόξειν εἶναι, ἐπιδημοῦντες δὲ παρὰ τοῖς πολίταις τοῖς ἠδικημένοις πονηροὶ δόξειν καὶ ἀσεβεῖς εἶναι.", "st": "6.44"}, {"sp": "N", "t": "ὁ γοῦν πάντων πονηρότατος Βάτραχος πλὴν τούτου, γενόμενος ἐπὶ τῶν τριάκοντα μηνυτὴς καὶ οὐσῶν αὐτῷ συνθηκῶν καὶ ὅρκων καθάπερ τοῖς Ἐλευσινόθεν, δείσας ὑμῶν οὓς ἠδίκησεν, ἐν ἑτέρᾳ πόλει ᾤκει. Ἀνδοκίδης δὲ καὶ αὐτοὺς τοὺς θεοὺς ἀδικήσας περὶ ἐλάττονος αὐτοὺς ἔθετο, εἰσιὼν εἰς τὰ ἱερά, ἢ Βάτραχος τοὺς ἀνθρώπους. ὅστις οὖν καὶ πονηρότερος καὶ ἀμαθέστερος Βατράχου ἐστί, πάνυ δεῖ ἀγαπητῶς ὑφ’ ὑμῶν αὐτὸν σωθῆναι.", "st": "6.45"}, {"sp": "N", "t": "φέρε δή, εἰς τί σκεψαμένους χρὴ ὑμᾶς Ἀνδοκίδου ἀποψηφίσασθαι; πότερον ὡς στρατιώτης ἀγαθός; ἀλλ’ οὐδεπώποτ’ ἐκ τῆς πόλεως ἐστρατεύσατο, οὔτε ἱππεὺς οὔτε ὁπλίτης, οὔτε τριήραρχος οὔτ’ ἐπιβάτης, οὔτε πρὸ τῆς συμφορᾶς οὔτε μετὰ τὴν συμφοράν, πλέον ἢ τετταράκοντα ἔτη γεγονώς.", "st": "6.46"}, {"sp": "N", "t": "καίτοι ἕτεροι φεύγοντες ἐν Ἑλλησπόντῳ συνετριηράρχουν ὑμῖν. ἀναμνήσθητε δὲ καὶ αὐτοὶ ἐξ ὅσων κακῶν καὶ πολέμου ὑμᾶς αὐτοὺς περιεποιήσατε καὶ τὴν πόλιν, πολλὰ μὲν τοῖς σώμασι πονήσαντες, πολλὰ δὲ ἀναλώσαντες χρήματα καὶ ἰδίᾳ καὶ δημοσίᾳ, πολλοὺς δὲ καὶ ἀγαθοὺς τῶν πολιτῶν καταθάψαντες διὰ τὸν γενόμενον πόλεμον.", "st": "6.47"}, {"sp": "N", "t": "Ἀνδοκίδης δὲ ἀπαθὴς τούτων τῶν κακῶν γενόμενος … εἰς τὴν σωτηρίαν τῇ πατρίδι, ἀξιοῖ νυνὶ μετέχειν τῆς πόλεως, ἀσεβῶν ἐν αὐτῇ. ἀλλὰ πλουτῶν γὰρ καὶ δυνάμενος τοῖς χρήμασι καὶ βασιλεῦσιν ἐξενωμένος καὶ τυράννοις — ἃ νυνὶ κομπάσει, ἐπιστάμενος τοὺς ὑμετέρους τρόπους — ποίαν εἰσφορὰν … τούτῳ ἀγαθὸν γένοιντο,", "st": "6.48"}, {"sp": "N", "t": "καὶ ἐπιστάμενος ἐν πολλῷ σάλῳ καὶ κινδύνῳ τὴν πόλιν γενομένην, ναυκληρῶν οὐκ ἐτόλμησεν ἐπαρθεὶς σῖτον εἰσάγων ὠφελῆσαι τὴν πατρίδα. ἀλλὰ μέτοικοι μὲν καὶ ξένοι ἕνεκα τῆς μετοικίας ὠφέλουν τὴν πόλιν εἰσάγοντες· σὺ δὲ τί καὶ ἀγαθὸν ποιήσας, ὦ Ἀνδοκίδη, ποῖα ἁμαρτήματα ἀνακαλεσάμενος, ποῖα τροφεῖα ἀνταποδούς …", "st": "6.49"}, {"sp": "N", "t": "Ἀθηναῖοι, μνήσθητε τὰ πεποιημένα Ἀνδοκίδῃ, ἐνθυμήθητε δὲ καὶ τῆς ἑορτῆς, δι’ ἣν ὑπὸ τῶν πολλῶν προὐτιμήθητε. ἀλλ’ ἐστὲ γὰρ ὑπὸ τῶν τούτου ἁμαρτημάτων ἤδη καταπλῆγες διὰ τὸ πολλάκις ἰδεῖν καὶ ἀκοῦσαι, ὥστε οὐδὲ τὰ δεινὰ ἔτι δεινὰ δοκεῖ ὑμῖν εἶναι. ἀλλὰ προσέχετε τὸν νοῦν, δοκείτω δ’ ὑμῖν ἡ γνώμη ὁρᾶν ἃ οὗτος ἐποίει,", "st": "6.50"}, {"sp": "N", "t": "καὶ διαγνώσεσθε ἄμεινον. οὗτος γὰρ ἐνδὺς στολήν, μιμούμενος τὰ ἱερὰ ἐπεδείκνυε τοῖς ἀμυήτοις καὶ εἶπε τῇ φωνῇ τὰ ἀπόρρητα, τῶν δὲ θεῶν, οὓς ἡμεῖς [θεοὺς] νομίζομεν καὶ θεραπεύοντες καὶ ἁγνεύοντες θύομεν καὶ προσευχόμεθα, τούτους περιέκοψε. καὶ ἐπὶ τούτοις ἱέρειαι καὶ ἱερεῖς στάντες κατηράσαντο πρὸς ἑσπέραν καὶ φοινικίδας ἀνέσεισαν, κατὰ τὸ νόμιμον τὸ παλαιὸν καὶ ἀρχαῖον.", "st": "6.51"}, {"sp": "N", "t": "ὡμολόγησε δὲ οὗτος ποιῆσαι. ἔτι δὲ παρελθὼν τὸν νόμον ὃν ὑμεῖς ἔθεσθε, εἴργεσθαι τῶν ἱερῶν αὐτὸν ὡς ἀλιτήριον ὄντα, ταῦτα πάντα βιασάμενος εἰσελήλυθεν ἡμῶν εἰς τὴν πόλιν, καὶ ἔθυσεν ἐπὶ τῶν βωμῶν ὧν οὐκ ἐξῆν αὐτῷ καὶ ἀπήντα τοῖς ἱεροῖς περὶ ἃ ἠσέβησεν, εἰσῆλθεν εἰς τὸ Ἐλευσίνιον, ἐχερνίψατο ἐκ τῆς ἱερᾶς χέρνιβος. τίνα χρὴ ταῦτα ἀνασχέσθαι;", "st": "6.52"}, {"sp": "N", "t": "ποῖον φίλον, ποῖον συγγενῆ, ποῖον δημότην χρὴ τούτῳ χαρισάμενον κρύβδην φανερῶς τοῖς θεοῖς ἀπεχθέσθαι; νῦν οὖν χρὴ νομίζειν τιμωρουμένους καὶ ἀπαλλαττομένους Ἀνδοκίδου τὴν πόλιν καθαίρειν καὶ ἀποδιοπομπεῖσθαι καὶ φαρμακὸν ἀποπέμπειν καὶ ἀλιτηρίου ἀπαλλάττεσθαι, ὡς ἓν τούτων οὗτός ἐστι.", "st": "6.53"}, {"sp": "N", "t": "βούλομαι τοίνυν εἰπεῖν ἃ Διοκλῆς ὁ Ζακόρου τοῦ ἱεροφάντου, πάππος δὲ ἡμέτερος, συνεβούλευσε βουλευομένοις ὑμῖν ὅ τι δεῖ χρῆσθαι Μεγαρεῖ ἀνδρὶ ἠσεβηκότι. κελευόντων γὰρ ἑτέρων ἄκριτον παραχρῆμα ἀποκτεῖναι, παρῄνεσε κρῖναι τῶν ἀνθρώπων ἕνεκα, ἵνα ἀκούσαντες καὶ ἰδόντες σωφρονέστεροι οἱ ἄλλοι ὦσι, τῶν δὲ θεῶν ἕνεκα οἴκοθεν ἕκαστον, ἃ δεῖ τὸν ἀσεβοῦντα παθεῖν, αὐτὸν παρ’ ἑαυτῷ κεκρικότα εἰς τὸ δικαστήριον εἰσιέναι.", "st": "6.54"}, {"sp": "N", "t": "καὶ ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι (ἐπίστασθε γὰρ ἃ δεῖ ποιῆσαι), μὴ ἀναπεισθῆτε ὑπὸ τούτου, φανερῶς ἔχετε αὐτὸν ἀσεβοῦντα· εἴδετε, ἠκούσατε τὰ τούτου ἁμαρτήματα. ἀντιβολήσει καὶ ἱκετεύσει ὑμᾶς· μὴ ἐλεεῖτε. οὐ γὰρ οἱ δικαίως ἀποθνῄσκοντες ἀλλ’ οἱ ἀδίκως ἄξιοί εἰσιν ἐλεεῖσθαι.", "st": "6.55"}, {"sp": "HDR", "t": "Ζʹ. Ἀρεοπαγιτικὸς περὶ τοῦ σηκοῦ ἀπολογία", "st": "7"}, {"sp": "N", "t": "πρότερον μέν, ὦ βουλή, ἐνόμιζον ἐξεῖναι τῷ βουλομένῳ, ἡσυχίαν ἄγοντι, μήτε δίκας ἔχειν μήτε πράγματα· νυνὶ δὲ οὕτως ἀπροσδοκήτως αἰτίαις καὶ πονηροῖς συκοφάνταις περιπέπτωκα, ὥστ’ εἴ πως οἷόν τε, δοκεῖ μοι δεῖν καὶ τοὺς μὴ γεγονότας ἤδη δεδιέναι περὶ τῶν μελλόντων ἔσεσθαι· διὰ γὰρ τοὺς τοιούτους οἱ κίνδυνοι [οἱ] κοινοὶ γίγνονται καὶ τοῖς μηδὲν ἀδικοῦσι καὶ τοῖς πολλὰ ἡμαρτηκόσιν.", "st": "7.1"}, {"sp": "N", "t": "οὕτω δ’ ἄπορος ὁ ἀγών μοι καθέστηκεν, ὥστε ἀπεγράφην τὸ μὲν πρῶτον ἐλάαν ἐκ τῆς γῆς ἀφανίζειν, καὶ πρὸς τοὺς ἐωνημένους τοὺς καρποὺς τῶν μορίων πυνθανόμενοι προσῇσαν· ἐπειδὴ δ’ ἐκ τούτου τοῦ τρόπου ἀδικοῦντά με οὐδὲν εὑρεῖν ἐδυνήθησαν, νυνί με σηκόν ⟨φασιν⟩ ἀφανίζειν, ἡγούμενοι ἐμοὶ μὲν ταύτην τὴν αἰτίαν ἀπορωτάτην εἶναι ἀπελέγξαι, αὐτοῖς δὲ ἐξεῖναι μᾶλλον ὅ τι ἂν βούλωνται λέγειν.", "st": "7.2"}, {"sp": "N", "t": "καὶ δεῖ με, περὶ ὧν οὗτος ἐπιβεβουλευκὼς ἥκει, ἅμ’ ὑμῖν τοῖς διαγνωσομένοις περὶ τοῦ πράγματος ἀκούσαντα καὶ περὶ τῆς πατρίδος καὶ περὶ τῆς οὐσίας ἀγωνίσασθαι. ὅμως δὲ πειράσομαι ἐξ ἀρχῆς ὑμᾶς διδάξαι.", "st": "7.3"}, {"sp": "N", "t": "ἦν μὲν γὰρ τοῦτο Πεισάνδρου τὸ χωρίον, δημευθέντων δὲ τῶν ὄντων ἐκείνου Ἀπολλόδωρος ὁ Μεγαρεὺς δωρειὰν παρὰ τοῦ δήμου λαβὼν τὸν μὲν ἄλλον χρόνον ἐγεώργει, ὀλίγῳ δὲ πρὸ τῶν τριάκοντα Ἀντικλῆς παρ’ αὐτοῦ πριάμενος ἐξεμίσθωσεν· ἐγὼ δὲ παρ’ Ἀντικλέους εἰρήνης οὔσης ὠνοῦμαι.", "st": "7.4"}, {"sp": "N", "t": "ἡγοῦμαι τοίνυν, ὦ βουλή, ἐμὸν ἔργον ἀποδεῖξαι ὡς ἐπειδὴ τὸ χωρίον ἐκτησάμην, οὔτ’ ἐλάα οὔτε σηκὸς ἐνῆν ἐν αὐτῷ. νομίζω γὰρ τοῦ μὲν προτέρου χρόνου, οὐδ’ εἰ πάλαι ἐνῆσαν μορίαι, οὐκ ἂν δικαίως ζημιοῦσθαι· εἰ γὰρ μὴ δι’ ἡμᾶς εἰσιν ἠφανισμέναι, οὐδὲν προσήκει περὶ τῶν ἀλλοτρίων ἁμαρτημάτων ὡς ἀδικοῦντας κινδυνεύειν.", "st": "7.5"}, {"sp": "N", "t": "πάντες γὰρ ἐπίστασθε ὅτι ⟨ὁ⟩ πόλεμος καὶ ἄλλων πολλῶν αἴτιος κακῶν γεγένηται, καὶ τὰ μὲν πόρρω ὑπὸ Λακεδαιμονίων ἐτέμνετο, τὰ δ’ ἐγγὺς ὑπὸ τῶν φίλων διηρπάζετο· ὥστε πῶς ἂν δικαίως ὑπὲρ τῶν ⟨τότε⟩ τῇ πόλει γεγενημένων συμφορῶν ἐγὼ νυνὶ δίκην διδοίην;", "st": "7.6"}, {"sp": "N", "t": "ἄλλως τε καὶ τοῦτο τὸ χωρίον ἐν τῷ πολέμῳ δημευθὲν ἄπρατον ἦν πλεῖν ἢ τρία ἔτη. οὐ θαυμαστὸν δ’ εἰ τότε τὰς μορίας ἐξέκοπτον, ἐν ᾧ οὐδὲ τὰ ἡμέτερ’ αὐτῶν φυλάττειν ἐδυνάμεθα. ἐπίστασθε δέ, ὦ βουλή, ὅσοι μάλιστα τῶν τοιούτων ἐπιμελεῖσθε, πολλὰ ἐν ἐκείνῳ τῷ χρόνῳ δασέα ὄντα ἰδίαις καὶ μορίαις ἐλάαις, ὧν νῦν τὰ πολλὰ ἐκκέκοπται καὶ ἡ γῆ ψιλὴ γεγένηται· καὶ τῶν αὐτῶν καὶ ἐν τῇ εἰρήνῃ καὶ ἐν τῷ πολέμῳ κεκτημένων οὐκ ἀξιοῦτε παρ’ αὐτῶν, ἑτέρων ἐκκοψάντων, δίκην λαμβάνειν.", "st": "7.7"}, {"sp": "N", "t": "καίτοι εἰ τοὺς διὰ παντὸς τοῦ χρόνου γεωργοῦντας τῆς αἰτίας ἀφίετε, ἦ που χρὴ τούς γ’ ἐν τῇ εἰρήνῃ πριαμένους ἀφ’ ὑμῶν ἀζημίους γενέσθαι.", "st": "7.8"}, {"sp": "N", "t": "ἀλλὰ γάρ, ὦ βουλή, περὶ μὲν τῶν πρότερον γεγενημένων πολλὰ ἔχων εἰπεῖν ἱκανὰ νομίζω τὰ εἰρημένα· ἐπειδὴ δ’ ἐγὼ παρέλαβον τὸ χωρίον, πρὶν ἡμέρας πέντε γενέσθαι, ἀπεμίσθωσα Καλλιστράτῳ, ἐπὶ Πυθοδώρου ἄρχοντος·", "st": "7.9"}, {"sp": "N", "t": "ὃς δύο ἔτη ἐγεώργησεν, οὔτε ἰδίαν ἐλάαν οὔτε μορίαν οὔτε σηκὸν παραλαβών. τρίτῳ δὲ ἔτει Δημήτριος οὑτοσὶ εἰργάσατο ἐνιαυτόν· τῷ δὲ τετάρτῳ Ἀλκίᾳ Ἀντισθένους ἀπελευθέρῳ ἐμίσθωσα, ὃς τέθνηκε· κᾆτα τρία ἔτη ὁμοίως καὶ Πρωτέας ἐμισθώσατο. καί μοι δεῦρ’ ἴτε, μάρτυρες.", "st": "7.10"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "7.11"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ὁ χρόνος οὗτος ἐξήκει, αὐτὸς γεωργῶ. φησὶ δὲ ὁ κατήγορος ἐπὶ Σουνιάδου ἄρχοντος σηκὸν ὑπ’ ἐμοῦ ἐκκεκόφθαι. ὑμῖν δὲ μεμαρτυρήκασιν οἱ πρότερον ἐργαζόμενοι καὶ πολλὰ ἔτη παρ’ ἐμοῦ μεμισθωμένοι μὴ εἶναι σηκὸν ἐν τῷ χωρίῳ. καίτοι πῶς ἄν τις φανερώτερον ἐξελέγξειε ψευδόμενον τὸν κατήγορον; οὐ γὰρ οἷόν τε, ἃ πρότερον μὴ ἦν, ταῦτα τὸν ὕστερον ἐργαζόμενον ἀφανίζειν.", "st": "7.11"}, {"sp": "N", "t": "ἐγὼ τοίνυν, ὦ βουλή, ἐν μὲν τῷ τέως χρόνῳ, ὅσοι με φάσκοιεν δεινὸν εἶναι καὶ ἀκριβῆ καὶ οὐδὲν ἂν εἰκῇ καὶ ἀλογίστως ποιῆσαι, ἠγανάκτουν ἄν, ἡγούμενος μᾶλλον λέγεσθαι ⟨ἢ⟩ ὥς μοι προσῆκε· νῦν δὲ πάντας ἂν ὑμᾶς βουλοίμην περὶ ἐμοῦ ταύτην τὴν γνώμην ἔχειν, ἵνα ἡγῆσθέ με σκοπεῖν ⟨ἄν⟩, εἴπερ τοιούτοις ἔργοις ἐπεχείρουν, καὶ ὅ τι κέρδος ἐγίγνετο ⟨τῷ⟩ ἀφανίσαντι καὶ ἥτις ζημία περιποιήσαντι, καὶ τί ἂν λαθὼν διεπραξάμην καὶ τί ἂν φανερὸς γενόμενος ὑφ’ ὑμῶν ἔπασχον.", "st": "7.12"}, {"sp": "N", "t": "πάντες γὰρ ἄνθρωποι τὰ τοιαῦτα οὐχ ὕβρεως ἀλλὰ κέρδους ἕνεκα ποιοῦσι, καὶ ὑμᾶς εἰκὸς οὕτω σκοπεῖν, καὶ τοὺς ἀντιδίκους ἐκ τούτων τὰς κατηγορίας ποιεῖσθαι, ἀποφαίνοντας ἥτις ὠφέλεια τοῖς ἀδικήσασιν ἐγίγνετο.", "st": "7.13"}, {"sp": "N", "t": "οὗτος μέντοι οὐκ ἂν ἔχοι ἀποδεῖξαι οὔθ’ ὡς ὑπὸ πενίας ἠναγκάσθην τοιούτοις ἔργοις ἐπιχειρεῖν, οὔθ’ ὡς τὸ χωρίον μοι διεφθείρετο τοῦ σηκοῦ ὄντος, οὔθ’ ὡς ἀμπέλοις ἐμποδὼν ἦν, οὔθ’ ὡς οἰκίας ἐγγύς, οὔθ’ ὡς ἐγὼ ἄπειρος τῶν παρ’ ὑμῖν κινδύνων.", "st": "7.14"}, {"sp": "N", "t": "⟨ἐγὼ δ’⟩ εἴ τι τοιοῦτον ἔπραττον, πολλὰς ἂν καὶ μεγάλας ἐμαυτῷ ζημίας γενομένας ἀποφήναιμι· ὃς πρῶτον μὲν μεθ’ ἡμέραν ἐξέκοπτον τὸν σηκόν, ὥσπερ οὐ πάντας λαθεῖν δέον, ἀλλὰ πάντας Ἀθηναίους εἰδέναι. καὶ εἰ μὲν αἰσχρὸν ἦν μόνον τὸ πρᾶγμα, ἴσως ἄν τις τῶν παριόντων ἠμέλησε· νῦν δ’ οὐ περὶ αἰσχύνης ἀλλὰ τῆς μεγίστης ζημίας ἐκινδύνευον.", "st": "7.15"}, {"sp": "N", "t": "πῶς δ’ οὐκ ἂν ἦ ἀθλιώτατος ἀνθρώπων ἁπάντων, εἰ τοὺς ἐμαυτοῦ θεράποντας μηκέτι δούλους ἔμελλον ἕξειν ἀλλὰ δεσπότας τὸν λοιπὸν βίον, τοιοῦτον ἔργον συνειδότας; ὥστε εἰ καὶ τὰ μέγιστα εἰς ἐμὲ ἐξημάρτανον, οὐκ ἂν οἷόν τε ἦν δίκην με παρ’ αὐτῶν λαμβάνειν· εὖ γὰρ ἂν ᾔδη ὅτι ἐπ’ ἐκείνοις ἦν καὶ ἐμὲ τιμωρήσασθαι καὶ αὐτοῖς μηνύσασιν ἐλευθέροις γενέσθαι.", "st": "7.16"}, {"sp": "N", "t": "ἔτι τοίνυν, εἰ τῶν οἰκετῶν παρέστη μοι μηδὲν φροντίζειν, πῶς ἂν ἐτόλμησα τοσούτων μεμισθωμένων καὶ ἁπάντων συνειδότων ἀφανίσαι τὸν σηκὸν βραχέος μὲν κέρδους ἕνεκα, προθεσμίας δὲ οὐδεμιᾶς οὔσης τῷ κινδύνῳ τοῖς εἰργασμένοις ἅπασι τὸ χωρίον ὁμοίως προσῆκον εἶναι σῶν τὸν σηκόν ἵν’, εἴ τις αὐτοὺς ᾐτιᾶτο, εἶχον ἀνενεγκεῖν ὅτῳ παρέδοσαν; νῦν δὲ καὶ ἐμὲ ἀπολύσαντες φαίνονται, καὶ σφᾶς αὐτούς, εἴπερ ψεύδονται, μετόχους τῆς αἰτίας καθιστάντες.", "st": "7.17"}, {"sp": "N", "t": "εἰ τοίνυν καὶ ταῦτα παρεσκευασάμην, πῶς ἂν οἷός τ’ ἦ πάντας πεῖσαι τοὺς παριόντας, ἢ τοὺς γείτονας, οἳ οὐ μόνον ἀλλήλων ταῦτ’ ἴσασιν ἃ πᾶσιν ὁρᾶν ἔξεστιν, ἀλλὰ καὶ περὶ ὧν ἀποκρυπτόμεθα μηδένα εἰδέναι, καὶ περὶ ἐκείνων πυνθάνονται; ἐμοὶ τοίνυν τούτων οἱ μὲν φίλοι οἱ δὲ διάφοροι περὶ τῶν ἐμῶν τυγχάνουσιν ὄντες·", "st": "7.18"}, {"sp": "N", "t": "οὓς ἐχρῆν τοῦτον παρασχέσθαι μάρτυρας, καὶ μὴ μόνον οὕτως τολμηρὰς κατηγορίας ποιεῖσθαι· ὅς φησιν ὡς ἐγὼ μὲν παρειστήκη, οἱ δ’ οἰκέται ἐξέτεμνον τὰ πρέμνα, ἀναθέμενος δὲ ὁ βοηλάτης ὤχετο ἀπάγων τὰ ξύλα.", "st": "7.19"}, {"sp": "N", "t": "καίτοι, ὦ Νικόμαχε, χρῆν σε τότε καὶ παρακαλεῖν τοὺς παρόντας μάρτυρας, καὶ φανερὸν ποιεῖν τὸ πρᾶγμα· καὶ ἐμοὶ μὲν οὐδεμίαν ἂν ἀπολογίαν ὑπέλιπες, αὐτὸς δέ, εἰ μέν σοι ἐχθρὸς ἦ, ἐν τούτῳ τῷ τρόπῳ ἦσθα ἄν με τετιμωρημένος, εἰ δὲ τῆς πόλεως ἕνεκα ἔραττες, οὕτως ἐξελέγξας οὐκ ἂν ἐδόκεις εἶναι συκοφάντης, εἰ δὲ κερδαίνειν ἐβούλου,", "st": "7.20"}, {"sp": "N", "t": "τότ’ ἂν πλεῖστον ἔλαβες· φανεροῦ γὰρ ὄντος τοῦ πράγματος οὐδεμίαν ἄλλην ἡγούμην ἂν εἶναί μοι σωτηρίαν ἢ σὲ πεῖσαι. τούτων τοίνυν οὐδὲν ποιήσας διὰ τοὺς σοὺς λόγους ἀξιοῖς με ἀπολέσθαι, καὶ κατηγορεῖς ὡς ὑπὸ τῆς ἐμῆς δυνάμεως καὶ τῶν ἐμῶν χρημάτων οὐδεὶς ἐθέλει σοι μαρτυρεῖν.", "st": "7.21"}, {"sp": "N", "t": "καίτοι εἰ ⟨ὅτε⟩ φῄς μ’ ἰδεῖν τὴν μορίαν ἀφανίζοντα τοὺς ἐννέα ἄρχοντας ἐπήγαγες ἢ ἄλλους τινὰς τῶν ἐξ Ἀρείου πάγου, οὐκ ἂν ἑτέρων ἔδει σοι μαρτύρων· οὕτω γὰρ ἄν σοι συνῄδεσαν ἀληθῆ λέγοντι, οἵπερ καὶ διαγιγνώσκειν ἔμελλον περὶ τοῦ πράγματος.", "st": "7.22"}, {"sp": "N", "t": "δεινότατα οὖν πάσχω· ὃς εἰ μὲν παρέσχετο μάρτυρας, τούτοις ἂν ἠξίου πιστεύειν, ἐπειδὴ δὲ οὐκ εἰσὶν αὐτῷ ἐμοὶ καὶ ταύτην [τὴν] ζημίαν οἴεται χρῆναι γενέσθαι. καὶ τούτου μὲν οὐ θαυμάζω· οὐ γὰρ δήπου συκοφαντῶν ἅμα τοιούτων τε λόγων ἀπορήσει καὶ μαρτύρων· ὑμᾶς δ’ οὐκ ἀξιῶ τὴν αὐτὴν τούτῳ γνώμην ἔχειν.", "st": "7.23"}, {"sp": "N", "t": "ἐπίστασθε γὰρ ἐν τῷ πεδίῳ πολλὰς μορίας οὔσας καὶ πυρκαϊὰς ἐν τοῖς ἄλλοις τοῖς ἐμοῖς χωρίοις, ἅς, εἴπερ ἐπεθύμουν, πολὺ ἦν ἀσφαλέστερον καὶ ἀφανίσαι καὶ ἐκκόψαι καὶ ἐπεργάσασθαι, ὅσῳπερ ἧττον τὸ ἀδίκημα πολλῶν οὐσῶν ἔμελλε δῆλον ἔσεσθαι.", "st": "7.24"}, {"sp": "N", "t": "νῦν δ’ οὕτως αὐτὰς περὶ πολλοῦ ποιοῦμαι ὥσπερ ⟨καὶ τὴν πατρίδα⟩ καὶ τὴν ἄλλην οὐσίαν, ἡγούμενος περὶ ἀμφοτέρων τούτων εἶναί μοι τὸν κίνδυνον. αὐτοὺς τοίνυν ὑμᾶς τούτων μάρτυρας παρέξομαι, ἐπιμελουμένους μὲν ἑκάστου μηνός, ἐπιγνώμονας δὲ πέμποντας καθ’ ἕκαστον ἐνιαυτόν· ὧν οὐδεὶς πώποτ’ ἐζημίωσέ μ’ ὡς ἐργαζόμενον τὰ περὶ τὰς μορίας χωρία.", "st": "7.25"}, {"sp": "N", "t": "καίτοι οὐ δήπου τὰς μὲν μικρὰς ζημίας οὕτω περὶ πολλοῦ ποιοῦμαι, τοὺς δὲ περὶ τοῦ σώματος κινδύνους οὕτω περὶ οὐδενὸς ἡγοῦμαι· καὶ τὰς μὲν πολλὰς ἐλάας, εἰς ἃς ἐξῆν μᾶλλον ἐξαμαρτάνειν, οὕτω θεραπεύων φαίνομαι, τὴν δὲ μορίαν, ἣν οὐχ οἷόν τ’ ἦν λαθεῖν ἐξορύξαντα, ὡς ἀφανίζων νυνὶ κρίνομαι.", "st": "7.26"}, {"sp": "N", "t": "πότερον δέ μοι κρεῖττον ἦν, ὦ βουλή, δημοκρατίας οὔσης παρανομεῖν ἢ ἐπὶ τῶν τριάκοντα; καὶ οὐ λέγω ὡς τότε δυνάμενος ἢ ὡς νῦν διαβεβλημένος, ἀλλ’ ὡς τῷ βουλομένῳ τότε μᾶλλον ἐξὸν ἀδικεῖν ἢ νυνί. ἐγὼ τοίνυν οὐδ’ ἐν ἐκείνῳ τῷ χρόνῳ οὔτε τοιοῦτον οὔτε ἄλλο οὐδὲν κακὸν ποιήσας φανήσομαι.", "st": "7.27"}, {"sp": "N", "t": "πῶς δ’ ἄν, εἰ μὴ πάντων ἀνθρώπων ἐμαυτῷ κακονούστατος ἦ, ὑμῶν οὕτως ἐπιμελουμένων ἐκ τούτου τὴν μορίαν ἀφανίζειν ἐπεχείρησα τοῦ χωρίου, ἐν ᾧ δένδρον μὲν οὐδὲ ἕν ἐστι, μιᾶς δὲ ἐλάας σηκός, ὡς οὗτός φησιν, ἦν, κυκλόθεν δὲ ὁδὸς περιέχει, ἀμφοτέρωθεν δὲ γείτονες περιοικοῦσιν, ἄερκτον δὲ καὶ πανταχόθεν κάτοπτόν ἐστιν; ὥστε τίς ἂν ἀπετόλμησε, τούτων οὕτως ἐχόντων, ἐπιχειρῆσαι τοιούτῳ πράγματι; δεινὸν δέ μοι δοκεῖ εἶναι ὑμᾶς μέν,", "st": "7.28"}, {"sp": "N", "t": "οἷς ὑπὸ τῆς πόλεως τὸν ἅπαντα χρόνον προστέτακται τῶν μορίων ἐλαῶν ἐπιμελεῖσθαι, μήθ’ ὡς ἐπεργαζόμενον πώποτε ζημιῶσαί ⟨με⟩ μήθ’ ὡς ἀφανίσαντα εἰς κίνδυνον καταστῆσαι, τοῦτον δ’ ὃς οὔτε γεωργῶν ἐγγὺς τυγχάνει οὔτ’ ἐπιμελητὴς ᾑρημένος οὔθ’ ἡλικίαν ἔχων εἰδέναι περὶ τῶν τοιούτων, ἀπογράψαι με ἐκ γῆς μορίαν ἀφανίζειν.", "st": "7.29"}, {"sp": "N", "t": "ἐγὼ τοίνυν δέομαι ὑμῶν μὴ τοὺς τοιούτους λόγους πιστοτέρους ἡγήσασθαι τῶν ἔργων, μηδὲ περὶ ὧν αὐτοὶ σύνιστε, τοιαῦτ’ ἀνασχέσθαι τῶν ἐμῶν ἐχθρῶν λεγόντων, ἐνθυμουμένους καὶ ἐκ τῶν εἰρημένων καὶ ἐκ τῆς ἄλλης πολιτείας.", "st": "7.30"}, {"sp": "N", "t": "ἐγὼ γὰρ τὰ ἐμοὶ προστεταγμένα ἅπαντα προθυμότερον πεποίηκα ⟨ἢ⟩ ὡς ὑπὸ τῆς πόλεως ἠναγκαζόμην, καὶ τριηραρχῶν καὶ εἰσφορὰς εἰσφέρων καὶ χορηγῶν καὶ τἆλλα λῃτουργῶν οὐδενὸς ἧττον πολυτελῶς τῶν πολιτῶν.", "st": "7.31"}, {"sp": "N", "t": "καίτοι ταῦτα μὲν μετρίως ποιῶν ἀλλὰ μὴ προθύμως οὔτ’ ἂν περὶ φυγῆς οὔτ’ ἂν περὶ τῆς ἄλλης οὐσίας ἠγωνιζόμην, πλείω δ’ ἂν ἐκεκτήμην, οὐδὲν ἀδικῶν οὐδ’ ἐπικίνδυνον ἐμαυτῷ καταστήσας τὸν βίον· ταῦτα δὲ πράξας, ἃ οὗτός μου κατηγορεῖ, ἐκέρδαινον μὲν οὐδέν, ἐμαυτὸν δ’ εἰς κίνδυνον καθίστην.", "st": "7.32"}, {"sp": "N", "t": "καίτοι πάντες ἂν ὁμολογήσαιτε δικαιότερον εἶναι τοῖς μεγάλοις χρῆσθαι τεκμηρίοις περὶ τῶν μεγάλων, καὶ πιστότερα ἡγεῖσθαι περὶ ὧν ἅπασα ἡ πόλις μαρτυρεῖ, μᾶλλον ἢ περὶ ὧν μόνος οὗτος κατηγορεῖ.", "st": "7.33"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ βουλή, ἐκ τῶν ἄλλων σκέψασθε. μάρτυρας γὰρ ἔχων αὐτῷ προσῆλθον, λέγων ὅτι μοι πάντες ⟨ἔτι⟩ εἰσὶν οἱ θεράποντες, οὓς ἐκεκτήμην ἐπειδὴ παρέλαβον τὸ χωρίον, καὶ ἕτοιμός εἰμι, εἴ τινα βούλοιτο, παραδοῦναι βασανίζειν, ἡγούμενος οὕτως ἂν τὸν ἔλεγχον ἰσχυρότερον γενέσθαι τῶν τούτου λόγων καὶ τῶν ἔργων τῶν ἐμῶν. οὗτος δ’ οὐκ ἤθελεν,", "st": "7.34"}, {"sp": "N", "t": "οὐδὲν φάσκων πιστὸν εἶναι τοῖς θεράπουσιν. ἐμοὶ δὲ δοκεῖ ⟨θαυμαστὸν⟩ εἶναι, εἰ περὶ αὑτῶν μὲν οἱ βασανιζόμενοι κατηγοροῦσιν, εὖ εἰδότες ὅτι ἀποθανοῦνται, περὶ δὲ τῶν δεσποτῶν, οἷς πεφύκασι κακονούστατοι, μᾶλλον ἂν ἕλοιντο ἀνέχεσθαι βασανιζόμενοι ἢ κατειπόντες ἀπηλλάχθαι τῶν παρόντων κακῶν.", "st": "7.35"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ βουλή, φανερὸν οἶμαι εἶναι πᾶσιν ὅτι, εἰ Νικομάχου ἐξαιτοῦντος τοὺς ἀνθρώπους μὴ παρεδίδουν, ἐδόκουν ἂν ἐμαυτῷ συνειδέναι· ἐπειδὴ τοίνυν ἐμοῦ παραδιδόντος οὗτος παραλαβεῖν οὐκ ἤθελε, δίκαιον καὶ περὶ τούτου τὴν αὐτὴν γνώμην σχεῖν, ἄλλως τε καὶ τοῦ κινδύνου οὐκ ἴσου ἀμφοτέροις ὄντος.", "st": "7.36"}, {"sp": "N", "t": "περὶ ἐμοῦ μὲν γὰρ εἰ ἔλεγον ἃ οὗτος ἐβούλετο, οὐδ’ ἂν ἀπολογήσασθαί μοι ἐξεγένετο· τούτῳ δ’ εἰ μὴ ὡμολόγουν, οὐδεμιᾷ ζημίᾳ ἔνοχος ἦν. ὥστε πολὺ μᾶλλον τοῦτον παραλαμβάνειν ἐχρῆν ἢ ἐμὲ παραδοῦναι προσῆκεν. ἐγὼ τοίνυν εἰς τοῦτο προθυμίας ἀφικόμην, ἡγούμενος μετ’ ἐμοῦ εἶναι καὶ ἐκ βασάνων καὶ ἐκ μαρτύρων καὶ ἐκ τεκμηρίων ὑμᾶς περὶ τοῦ πράγματος τἀληθῆ πυθέσθαι.", "st": "7.37"}, {"sp": "N", "t": "ἐνθυμεῖσθαι δὲ χρή, ὦ βουλή, ποτέροις χρὴ πιστεύειν μᾶλλον, οἷς πολλοὶ μεμαρτυρήκασιν ἢ ᾧ μηδεὶς τετόλμηκε, καὶ πότερον εἰκὸς μᾶλλον τοῦτον ἀκινδύνως ψεύδεσθαι ἢ μετὰ τοσούτου κινδύνου τοιοῦτον ἐμὲ ἔργον ἐργάσασθαι, καὶ πότερον οἴεσθε αὐτὸν ὑπὲρ τῆς πόλεως βοηθεῖν ἢ συκοφαντοῦντα αἰτιάσασθαι.", "st": "7.38"}, {"sp": "N", "t": "ἐγὼ μὲν ⟨γὰρ⟩ ὑμᾶς ἡγοῦμαι νομίζειν ὅτι Νικόμαχος ὑπὸ τῶν ἐχθρῶν πεισθεὶς τῶν ἐμῶν τοῦτον τὸν ἀγῶνα ἀγωνίζεται, οὐχ ὡς ἀδικοῦντα ἐλπίζων ἀποδείξειν, ἀλλ’ ὡς ἀργύριον παρ’ ἐμοῦ λήψεσθαι προσδοκῶν. ὅσῳ γὰρ ⟨οἱ⟩ τοιοῦτοί εἰσιν ἐπαιτιώτατοι καὶ ἀπορώτατοι τῶν κινδύνων, τοσούτῳ πάντες αὐτοὺς φεύγουσι μάλιστα.", "st": "7.39"}, {"sp": "N", "t": "ἐγὼ δέ, ὦ βουλή, οὐκ ἠξίουν, ἀλλ’ ἐπειδήπερ με ᾐτιάσατο, παρέσχον ἐμαυτὸν ὅ τι βούλεσθε χρῆσθαι, καὶ τούτου ἕνεκα τοῦ κινδύνου οὐδενὶ ἐγὼ τῶν ἐχθρῶν διηλλάγην, οἳ ἐμὲ ἥδιον κακῶς λέγουσιν ἢ σφᾶς αὐτοὺς ἐπαινοῦσι. καὶ φανερῶς μὲν οὐδεὶς πώποτε ἐμὲ αὐτὸς ἐπεχείρησε ποιῆσαι κακὸν οὐδέν, τοιούτους δὲ ἐπιπέμπουσί μοι, οἷς ὑμεῖς οὐκ ἂν δικαίως πιστεύοιτε. πάντων γὰρ ἀθλιώτατος ἂν γενοίμην,", "st": "7.40"}, {"sp": "N", "t": "εἰ φυγὰς ἀδίκως καταστήσομαι, ἄπαις μὲν ὢν καὶ μόνος, ἐρήμου δὲ τοῦ οἴκου γενομένου, μητρὸς δὲ πάντων ἐνδεοῦς ⟨οὔσης⟩, πατρίδος δὲ τοιαύτης ἐπ’ αἰσχίσταις στερηθεὶς αἰτίαις, πολλὰς μὲν ναυμαχίας ὑπὲρ αὐτῆς νεναυμαχηκώς, πολλὰς δὲ μάχας μεμαχημένος, κόσμιον δ’ ἐμαυτὸν καὶ ἐν δημοκρατίᾳ καὶ ἐν ὀλιγαρχίᾳ παρασχών.", "st": "7.41"}, {"sp": "N", "t": "ἀλλὰ γάρ, ὦ βουλή, ταῦτα μὲν ἐνθάδε οὐκ οἶδ’ ὅ τι δεῖ λέγειν· ἀπέδειξα δ’ ὑμῖν ὡς οὐκ ἐνῆν σηκὸς ἐν τῷ χωρίῳ, καὶ μάρτυρας παρεσχόμην καὶ τεκμήρια. ἃ χρὴ μεμνημένους διαγιγνώσκειν περὶ τοῦ πράγματος, καὶ ἀξιοῦν παρὰ τούτου πυθέσθαι ὅτου ἕνεκα, ἐξὸν ἐπ’ αὐτοφώρῳ ἐλέγξαι, τοσούτῳ χρόνῳ ὕστερον εἰς τοσοῦτόν με κατέστησεν ἀγῶνα,", "st": "7.42"}, {"sp": "N", "t": "καὶ μάρτυρα οὐδένα παρασχόμενος ἐκ τῶν λόγων ζητεῖ πιστὸς γενέσθαι, ἐξὸν αὐτοῖς ἔργοις ἀδικοῦντα ἀποδεῖξαι, καὶ ἐμοῦ ἅπαντας διδόντος τοὺς θεράποντας, οὕς φησι παραγενέσθαι, παραλαβεῖν οὐκ ἤθελεν.", "st": "7.43"}, {"sp": "HDR", "t": "Ηʹ. Κατηγορία πρὸς τοὺς συνουσιαστὰς κακολογιῶν", "st": "8"}, {"sp": "N", "t": "ἐπιτήδειόν μοι δοκῶ καιρὸν εἰληφέναι περὶ ὧν εἰπεῖν ἐβουλόμην πάλαι· πάρεισι μὲν γὰρ οἷς ἐπεγκαλῶ, πάρεισι δὲ ὧν ἐναντίον ἐπιθυμῶ μέμψασθαι τοῖς ἀδικοῦσιν ἐμέ. καίτοι πολλῷ πλείων ἐστὶ σπουδὴ πρὸς τοὺς παρόντας· τοὺς μὲν γὰρ ⟨παρ’⟩ οὐδὲν οἶμαι τιμήσειν, εἰ τοῖς ἐπιτηδείοις ἀνεπιτήδειοι δόξουσιν εἶναι (τὴν γὰρ ἀρχὴν οὐδ’ ἂν ἐπεχείρουν ἐξαμαρτάνειν εἰς ἐμὲ),", "st": "8.1"}, {"sp": "N", "t": "τοῖς δὲ βουλοίμην ἂν δόξαι μηδὲν ἀδικῶν τούτους ὑπὸ τούτων ἀδικεῖσθαι πρότερον. ἀνιαρὸν μὲν οὖν ἀναγκάζεσθαι λέγειν περὶ τούτων, ἀδύνατον δὲ μὴ λέγειν, ὅταν ἐναντίον τῆς ἐλπίδος κακῶς πάσχω καὶ τοὺς δοκοῦντας εἶναι φίλους ἀδικοῦντας εὑρίσκω.", "st": "8.2"}, {"sp": "N", "t": "πρῶτον μὲν οὖν, ἵνα μή τις ὑμῶν τάχα δὴ βοηθῶν οἷς ἐξημάρτηκε πρόφασιν πορίσηται τῆς ἁμαρτίας, εἰπάτω οὖν τίς ὑμῶν ὑπ’ ἐμοῦ κακῶς ἀκήκοεν ἢ πέπονθεν, ἢ τίς ἐμοῦ δεηθεὶς οὐκ ἔτυχεν ὧν ἐγώ τε δυνατὸς ἦ κἀκεῖνος ἐπήγγειλε. — τί δῆτά με κακῶς τὰ μὲν λέγειν τὰ δὲ ποιεῖν χειρεῖτε,", "st": "8.3"}, {"sp": "N", "t": "καὶ ταῦτα πρὸς τούτους ἡμᾶς διαβάλλειν, οὓς πρὸς ἡμᾶς αὐτοὺς διεβάλλετε; καίτοι οὕτως ἠνωχλεῖτε, ὥστε περὶ πλείονος ἐποιήσατό ⟨τις⟩ δοκεῖν ἐμοῦ κήδεσθαι, ἢ ἄλλον ἐμοὶ κατειπεῖν. ἃ δ’ ἔλεγε, πάντα μὲν οὐκ ἂν εἴποιμι (καὶ γὰρ ἀκούων ἠχθόμην) οὐδ’ ἂν ὑμῖν ἐπικαλῶν, ὅτι ἐλέγετε κατ’ ἐμοῦ, ταὐτὰ λέξαιμι. καὶ γὰρ ἂν ἀπολύοιμι τῆς αἰτίας ὑμᾶς, εἴπερ ὑμῖν ταὐτὰ λέγοιμι περὶ ἐμαυτοῦ·", "st": "8.4"}, {"sp": "N", "t": "ἃ δὲ ὑβρίζειν οἰόμενοι ἐμὲ καταγελάστους ὑμᾶς αὐτοὺς ἐποιεῖτε, ταῦτα λέξω. βίᾳ γὰρ ὑμῖν ἐφάσκετέ με ξυνεῖναι καὶ διαλέγεσθαι, καὶ πάντα ποιοῦντες οὐκ ἔχειν ὅπως ἀπαλλαγῆτέ μου, καὶ τὸ τελευταῖον ἀκόντων ὑμῶν Ἐλευσῖνάδε ξυνθεωρεῖν. καὶ ταῦτα λέγοντες οἴεσθε μὲν ἐμὲ κακολογεῖν, ἀποφαίνετε δὲ σκαιοτάτους ἑαυτούς, οἵτινες [μὲν] ὑπὸ τὸν αὐτὸν χρόνον τὸν αὐτὸν ἄνδρα λάθρᾳ μὲν ἐλοιδορεῖτε, φανερῶς δὲ φίλον ἐνομίζετε.", "st": "8.5"}, {"sp": "N", "t": "χρῆν γὰρ ὑμᾶς ἢ μὴ κακῶς λέγειν ἢ μὴ ξυνεῖναι, καὶ ταῦτα φανερῶς ἀπειπόντας ὁμιλίαν. εἰ δὲ αἰσχρὸν ἡγεῖσθε τοῦτο, πῶς αἰσχρὸν ἦν ὑμῖν ξυνεῖναι, πρὸς οὓ οὐδὲ ἀπειπεῖν καλὸν ἡγεῖσθε;", "st": "8.6"}, {"sp": "N", "t": "καὶ μὴν οὐδὲν αὐτὸς ἐξηῦρον ὁπόθεν ἂν εἰκότως ὑπερείδετε τὴν ἐμὴν ὁμιλίαν. οὔτε γὰρ ὑμᾶς σοφωτάτους ἑώρων ὄντας, ἐμαυτὸν δ’ ἀμαθέστατον, οὐ μὴν οὐδὲ πολυφίλους ὑμᾶς, ἐμαυτὸν δ’ ἔρημον φίλων, οὐδ’ αὖ πλουτοῦντας, ἐμὲ δὲ πενόμενον, οὐδ’ αὖ ὑμᾶς μὲν ὑπερευδοκιμοῦντας, ἐμαυτὸν δὲ διαβεβλημένον, οὐδὲ τὰ μὲν ἐμὰ πράγματα κινδυνεύοντα, τὰ δ’ ὑμέτερα ἀσφαλῶς ἔχοντα. πόθεν ἂν οὖν εἰκότως ὑπώπτευον ἄχθεσθαί μοι συνόντι;", "st": "8.7"}, {"sp": "N", "t": "καὶ ταῦτα δ’ ὅτε πρὸς τοὺς τελευταίους ἐλέγετ’ οὐκ ᾤεσθε ἀπαγγελεῖν ἡμῖν, κἀνταῦθα σόφισμα καλὸν ἡγούμενοι περιήλθετε πάντας ὑμῶν αὐτῶν κατηγοροῦντες ὅτι πονηροῖς ἑκόντες ὁμιλεῖτε.", "st": "8.8"}, {"sp": "N", "t": "περὶ μὲν οὖν τοῦ λέγοντος οὐδὲν ἂν περαίνοιτε πυνθανόμενοι. πρῶτον μὲν γὰρ εἰδότες ἐρήσεσθε τὸν εἰπόντα μοι· πῶς γὰρ οὐκ ἴστε πρὸς ὃν ἐλέγετε τὸν λόγον;", "st": "8.8"}, {"sp": "N", "t": "ἔπειτα κακὸς ἂν εἴην, εἰ ταὐτὰ ποιήσαιμι αὐτὸν ἅπερ ἐκεῖνος ὑμᾶς. οὐ γὰρ ἐπὶ τοῖς αὐτοῖς ἐκεῖνος ἡμῖν ἀπήγγελλεν, ἐφ’ οἷσπερ ὑμεῖς ἐλέγετε πρὸς ἐκεῖνον. ἐκεῖνος μὲν γὰρ ἐμοὶ χαριζόμενος ἀπήγγειλε τοῖς ἐμοῖς ἀναγκαίοις, ὑμεῖς δὲ βλάπτειν ἐμὲ βουλόμενοι πρὸς ἐκεῖνον ἐλέγετε. καὶ ταῦτα εἰ μὲν ἠπίστουν, ἐξελέγχειν ἂν ἐζήτουν· νῦν δὲ (ξυμβαίνει γὰρ καὶ ταῦτα τοῖς πρὸ τοῦ, καὶ ἐμοὶ σημεῖα ταῦτα μὲν ἐκείνων ἐστίν,", "st": "8.9"}, {"sp": "N", "t": "ἐκεῖνα δὲ τούτων ἱκανά) πρῶτον μὲν ἅπαντα δι’ ὑμῶν πράξαντά με περὶ τῆς θέσεως τοῦ ἵππου πρὸς Ἡγέμαχον, κάμνοντα τὸν ἵππον ἀνάγειν με βουλόμενον Διόδωρος οὑτοσὶ ἀποτρέπειν ἐπειρᾶτο, φάσκων οὐδὲν ἀντιλέξειν περὶ τῶν δώδεκα μνῶν Πολυκλέα, ἀλλ’ ἀποδώσειν. τότε λέγων ταῦτα, μετὰ τὸν θάνατον τοῦ ἵππου κατέστη τελευτῶν ἀντίδικος μετὰ τούτων, λέγων ὡς οὐ δίκαιόν με εἴη κομίσασθαι τὸ ἀργύριον.", "st": "8.10"}, {"sp": "N", "t": "καίτοιγε σφῶν γε αὐτῶν κατηγόρουν. εἰ γὰρ ἃ μετὰ τούτων ⟨ἔπραττον⟩ ἀδικουμένῳ μοι μηδὲν ἦν δίκαιον εἰπεῖν, ἦ που κακῶς συνέπραττον. καὶ ἐγὼ μὲν ᾤμην φιλοσοφοῦντας αὐτοὺς περὶ τοῦ πράγματος ἀντιλέγειν τὸν ἐναντίον λόγον· οἱ δ’ ἄρα οὐκ ἀντέλεγον ἀλλ’ ἀντέπραττον,", "st": "8.11"}, {"sp": "N", "t": "καὶ διὰ τοῦτο ἀντέλεγον, ἵνα τὸν ἐμὸν λόγον εἰδείη Πολυκλῆς· ἐδηλώθη γὰρ ταῦτα. παρόντων τῶν διαιτητῶν ὀργιζόμενος ὁ Πολυκλῆς εἶπεν ὅτι καὶ τοῖς ἐμοῖς ἐπιτηδείοις ἀδικεῖν δοκοίην, ὡς πρὸς ἐκεῖνον λέγοιεν. ἆρά γε ταῦτα ξυμβαίνει τοῖς ἀπαγγελλομένοις; ὁ γὰρ αὐτὸς ἀπήγγειλεν ὡς τοὺς ὑπὲρ ἐμοῦ μέλλοντας λέγειν ἀποτρέψειν φάσκοιτε, τοὺς δέ τινας ἤδη κωλύσαιτε. καὶ ταῦτα τί με δεῖ φανερώτερον ἐξελέγχειν ἔτι; φέρε γάρ, ᾔδει ποτ’ ἐκεῖνος ὅτι Κλειτοδίκου δεηθεὶς ἐπιλέγειν οὐκ ἔτυχον;", "st": "8.12"}, {"sp": "N", "t": "οὐ γὰρ δὴ παρῆν τούτοις· ἢ τί κέρδος ἦν αὐτῷ διαβάλλειν ἐμὲ πρὸς ὑμᾶς οὕτω προθύμως, ὥστε σπουδάσαι πρὸς τοὺς ἐμοὺς ἀναγκαίους πλάσασθαι ταῦτα;", "st": "8.13"}, {"sp": "N", "t": "γιγνώσκω δὲ νῦν ἤδη καὶ πάλαι ζητοῦντας πρόφασιν, ἡνίκα Θρασύμαχον ὑμᾶς ἐφάσκετε κακῶς λέγειν δι’ ἐμέ. καὶ ἐγὼ μὲν ἠρώτων αὐτὸν εἰ δι’ ἐμὲ κακῶς λέγοι Διόδωρον· ὁ δὲ τοσοῦτον ὑπερεῖδε τὸ δι’ ἐμέ· πολλοῦ γὰρ δεῖν ἔφη δι’ ὁντινοῦν εἰρηκέναι Διόδωρον κακῶς. καὶ ταῦτα προσάγοντος ἐμοῦ πρόθυμος ὁ Θρασύμαχος ἦν ἐξελέγχεσθαι,", "st": "8.14"}, {"sp": "N", "t": "περὶ ὧν οὗτος ἔλεγεν· οὗτος δὲ πάντ’ ἂν μᾶλλον διεπράττετο. μετὰ τοῦτο Αὐτοκράτης ἐμοῦ παρόντος Θρασυμάχω ἔλεγεν Εὐρυπτόλεμον αὐτῷ μέμφεσθαι, φάσκοντα κακῶς ἀκούειν ὑπ’ αὐτοῦ· τὸν ἀπαγγέλλοντα δὲ εἶναι Μηνόφιλον. εὐθὺς δ’ ἐκεῖνος ἐπὶ τὸν Μηνόφιλον ἐβάδιξε μετ’ ἐμοῦ· κἀκεῖνος οὔτε ἀκοῦσαι πώποτε ἔφασκεν οὔτε ἀπαγγεῖλαι πρὸς Εὐρυπτόλεμον, καὶ οὐ ταῦτα μόνον, ἀλλ’ οὐδὲ διειλέχθαι πολλοῦ χρόνου.", "st": "8.15"}, {"sp": "N", "t": "τοιαύτας προφάσεις προφασιζόμενοι τότε μὲν ἐκ τῆς ἐμῆς καὶ Θρασυμάχου συνουσίας ἐστὲ φανεροί, νῦν δὲ ἐπειδὴ ἐκλελοίπασιν ὑμᾶς αἱ προφάσεις, ἐλευθεριώτερόν με κακῶσαι λείπετε ἤδη οὐδέν. χρῆν μὲν οὖν τότε με γιγνώσκειν ὀφειλόμενόν μοι ταῦτα παθεῖν, ὅτε καὶ πρὸς ἐμὲ περὶ ὑμῶν αὐτῶν ἐλέγετε κακῶς· ἔπειτα καὶ περὶ Πολυκλέους, ᾧ νυνὶ βοηθεῖτε,", "st": "8.16"}, {"sp": "N", "t": "πάντ’ εἴρηκα πρὸς ὑμᾶς. κατὰ τί δὴ ταῦτα ⟨οὐκ⟩ ἐφυλαττόμην; εὔηθές τι ἔπαθον. ᾤμην γὰρ ἀπόθετος ὑμῖν εἶναι φίλος τοῦ μηδὲν ἀκοῦσαι κακὸν δι’ αὐτὸ τοῦτο, διότι πρὸς ἐμὲ τοὺς ἄλλους ἐλέγετε κακῶς, παρακαταθήκην ἔχων ὑμῶν παρ’ ἑκάστου λόγους πονηροὺς περὶ ἀλλήλων.", "st": "8.17"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἑκὼν ὑμῖν ἐξίσταμαι τῆς φιλίας, ἐπεί τοι μὰ τοὺς θεοὺς οὐκ οἶδ’ ὅ τι ζημιωθήσομαι μὴ ξυνὼν ὑμῖν· οὐδὲ γὰρ ὠφελούμην ξυνών. πότερον γάρ, ὅταν ᾖ τί μοι πρᾶγμα, τότε ποθέσομαι τὸν ἐροῦντα καὶ τοὺς μαρτυρήσοντας; καὶ νῦν ἀντὶ μὲν τοῦ λέγειν ὑπὲρ ἐμοῦ τὸν λέγοντα πειρᾶσθε ἀντὶ δὲ τοῦ βοηθεῖν ἐμοὶ καὶ μαρτυρεῖν τὰ δίκαια ξύνεστε τοῖς ἐμοῖς ἀντιδίκοις καὶ μαρτυρεῖτε.", "st": "8.18"}, {"sp": "N", "t": "ἀλλ’ ὡς εὖνοι ὄντες ἐμοὶ τὰ βέλτιστα ἐρεῖτε περὶ ἐμοῦ; ἀλλὰ καὶ νῦν ὑμεῖς με μόνοι κακῶς λέγετε. τὸ μὲν οὖν ἐμὸν οὐκ ἐμποδὼν ὑμῖν ἔσται. τοιοῦτον δ’ ἄρα πρὸς ὑμᾶς αὐτοὺς πείσεσθε, ἐπειδή περ ὑμῖν ἔθος ἐστὶν ἕνα τῶν ξυνόντων ἀεὶ κακῶς λέγειν καὶ ποιεῖν· ἐπειδὰν ὑμῖν ἐγὼ μὴ ξυνῶ, πρὸς ὑμᾶς αὐτοὺς τρέψεσθε, κἄπειτα καθ’ ἕνα ἕκαστον ὑμῖν αὐτοῖς ἀπεχθήσεσθε, τὸ δὲ τελευταῖον εἷς ὁ λειπόμενος αὐτὸς αὑτὸν κακῶς ἐρεῖ.", "st": "8.19"}, {"sp": "N", "t": "κερδανῶ δὲ τοσοῦτον, ὅτι πρῶτος νῦν ὑμῶν ἀπαλλαγεὶς ἐλάχιστα κακῶς ὑφ’ ὑμῶν πείσομαι· τοὺς μὲν γὰρ χρωμένους ὑμῖν κακῶς καὶ λέγετε καὶ ποιεῖτε, τῶν δὲ μὴ χρωμένων οὐδένα πώποτε.", "st": "8.20"}, {"sp": "HDR", "t": "Θʹ. Ὑπὲρ τοῦ στρατιωτοῦ", "st": "9"}, {"sp": "N", "t": "τί ποτε διανοηθέντες οἱ ἀντίδικοι τοῦ μὲν πράγματος παρημελήκασι, τὸν δὲ τρόπον μου ἐπεχείρησαν διαβάλλειν; πότερον ἀγνοοῦντες ὅτι περὶ τοῦ πράγματος προσήκει λέγειν; ἢ τόδε μὲν ἐπίστανται, ἡγούμενοι δὲ λήσειν περὶ [τοῦ] παντὸς πλείω λόγον ἢ τοῦ προσήκοντος ποιοῦνται;", "st": "9.1"}, {"sp": "N", "t": "ὅτι μὲν οὐκ ἐμοῦ καταφρονήσαντες ἀλλὰ τοῦ πράγματος τοὺς λόγους ποιοῦνται, σαφῶς ἐπίσταμαι· εἰ μέντοι ὑμᾶς οἴονται δι’ ἄγνοιαν ὑπὸ τῶν διαβολῶν πεισθέντας καταψηφιεῖσθαί μου, τοῦτ’ ἂν θαυμάσαιμι.", "st": "9.2"}, {"sp": "N", "t": "ᾤμην μὲν οὖν, ὦ ἄνδρες δικασταί, περὶ τοῦ ἐγκλήματος, οὐ περὶ τοῦ τρόπου τὸν ἀγῶνά μοι προκεῖσθαι· διαβαλλόντων δέ με τῶν ἀντιδίκων ἀναγκαῖόν ἐστι περὶ πάντων ⟨τὴν⟩ ἀπολογίαν ποιήσασθαι. πρῶτον μὲν οὖν περὶ τῆς ἀπογραφῆς ὑμᾶς διδάξω.", "st": "9.3"}, {"sp": "N", "t": "ἀφικόμενος προπέρυσιν εἰς τὴν πόλιν, οὔπω δύο μῆνας ἐπιδεδημηκὼς κατελέγην στρατιώτης. αἰσθόμενος δὲ τὸ πραχθὲν ὑπετοπούμην εὐθέως ἐπὶ μηδενὶ ὑγιεῖ κατειλέχθαι. προσελθὼν οὖν τῷ στρατηγῷ ἐδήλωσα ὅτι ἐστρατευμένος εἴην, ἔτυχον δὲ οὐδενὸς τῶν μετρίων. προπηλακιζόμενος δὲ ἠγανάκτουν μέν,", "st": "9.4"}, {"sp": "N", "t": "ἡσυχίαν δ’ εἶχον. ἀπορούμενος δὲ καὶ συμβουλευόμενός τινι τῶν πολιτῶν τί χρήσωμαι τῷ πράγματι, ἐπυθόμην ὡς καὶ δήσειν με ἀπειλοῖεν, λέγοντες ὅτι οὐδὲν ἐλάττω χρόνον Καλλικράτους Πολύαινος ἐνδημοίη.", "st": "9.5"}, {"sp": "N", "t": "κἀμοὶ μὲν τὰ προειρημένα διείλεκτο ἐπὶ τῇ Φιλίου τραπέζῃ· οἱ δὲ μετὰ Κτησικλέους τοῦ ἄρχοντος, ἀπαγγείλαντός τινος ὡς ἐγὼ λοιδοροῖμι, τοῦ νόμου ἀπαγορεύοντος ἐάν τις ἀρχὴν ἐν συνεδρίῳ λοιδορῇ, παρὰ τὸν νόμον ζημιῶσαι ἠξίωσαν. ἐπιβαλόντες δὲ τὸ ἀργύριον πράξασθαι μὲν οὐκ ἐπεχείρησαν, ἐξιούσης δὲ τῆς ἀρχῆς γράψαντες εἰς λεύκωμα τοῖς ταμίαις παρέδοσαν.", "st": "9.6"}, {"sp": "N", "t": "οἵδε μὲν τάδε διεπράξαντο. οἱ δὲ ταμίαι οὐδὲν ὅμοιον τοῖσδε διανοηθέντες, ἀνακαλεσάμενοι [δὲ] τοὺς παραδόντας [καὶ] τὴν γραφήν, ἐσκοποῦντο τῆς αἰτίας τὴν πρόφασιν. ἀκούσαντες δὲ τὸ γεγενημένον, ἐννοούμενοι οἷα πεπονθὼς ἦν, τὸ μὲν πρῶτον ἔπειθον αὐτοὺς ἀφεῖναι, διδάσκοντες ὡς οὐκ ἐπιεικὲς εἴη τῶν πολιτῶν τινας διὰ τὰς ἔχθρας ἀναγράφεσθαι, ἀποροῦντες δὲ μεταπεῖσαι αὐτούς, τὸν παρ’ ὑμῶν κίνδυνον ὑποστάντες ἄκυρον τὴν ζημίαν ἔκριναν …", "st": "9.7"}, {"sp": "N", "t": "ὅτι μὲν οὖν ἀφείθην ὑπὸ τῶν ταμιῶν, ἐπίστασθε· προσήκειν δὲ ἡγούμενος καὶ διὰ ταύτην τὴν ἀπόδειξιν ἀπηλλάχθαι τοῦ ἐγκλήματος, ἔτι πλείονας καὶ νόμους καὶ ἄλλας δικαιώσεις παρασχήσομαι. καὶ μοι λαβὲ τὸν νόμον.", "st": "9.8"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "9.9"}, {"sp": "N", "t": "τοῦ μὲν νόμου διαρρήδην ἀγορεύοντος τοὺς ἐν τῷ συνεδρίω λοιδοροῦντας ζημιοῦν ἀκηκόατε· ἐγὼ δ’ ὅτι μὲν οὐκ εἰσῆλθον εἰς τὸ ἀρχεῖον, μάρτυρας παρεσχόμην, ἀδίκως δὲ ζημιωθεὶς οὔτ’ ὀφείλω οὔτ’ ἐκτεῖσαι δίκαιός εἰμι.", "st": "9.9"}, {"sp": "N", "t": "εἰ γὰρ φανερός εἰμι μὴ ἐλθὼν εἰς τὸ συνέδριον, ὁ δὲ νόμος τοὺς ἐντὸς πλημμελοῦντας ἀγορεύει τὴν ζημίαν ὀφείλειν, ἠδικηκὼς μὲν οὐδὲν φαίνομαι, ἔχθρᾳ δὲ ἄνευ τούτου παραλόγως ζημιωθείς.", "st": "9.10"}, {"sp": "N", "t": "συνέγνωσαν δὲ καὶ αὐτοὶ σφίσιν ὡς ἠδικηκότες· οὔτε γὰρ εὐθύνας ὑπέσχον, οὔτε εἰς δικαστήριον εἰσελθόντες τὰ πραχθέντα ψήφῳ κύρια κατέστησαν. εἰ δ’ οὖν ἐζημίωσαν μὲν οἵδε προσηκόντως, ἐκύρωσαν δ’ ἐν ὑμῖν τὴν ἐπιβολήν, τῶν ταμιῶν ἀφέντων εἰκότως ἂν τοῦ ἐγκλήματος ἀπηλλαγμένος εἴην.", "st": "9.11"}, {"sp": "N", "t": "εἰ μὲν γὰρ ⟨μὴ⟩ κύριοι ἦσαν πράξασθαι ἢ ἀφεῖναι, ἐννόμως ζημιωθεὶς εὐλόγως ἂν ὤφειλον· εἰ δ’ ἔξεστι μὲν αὐτοῖς ἀφεῖναι, διδόασι δὲ λόγους ὑπὲρ ὧν ἂν διαχειρίζωσιν, εἴ τι ἠδικήκασι, τῆς προσηκούσης ῥᾳδίως δίκης τεύξονται.", "st": "9.12"}, {"sp": "N", "t": "ᾧ μὲν τρόπῳ παρεδόθην καὶ ἐζημιώθην, ἐπίστασθε· δεῖ δ’ ὑμᾶς μὴ μόνον τοῦ ἐγκλήματος τὴν αἰτίαν ἀλλὰ καὶ τῆς ἔχθρας τὴν πρόφασιν εἰδέναι. Σωστράτῳ γὰρ φίλος ἐγενόμην πρότερον μὲν τῆς τούτων ἔχθρας, εἰδὼς δὲ περὶ τὴν πόλιν ἄξιον λόγου γεγενημένον.", "st": "9.13"}, {"sp": "N", "t": "γνώριμος δὲ γενόμενος διὰ τῆς ἐκείνου δυναστείας οὔτ’ ἐχθρὸν ἐτιμωρησάμην οὔτε φίλον ηὐεργέτησα· ζῶντος μὲν γὰρ [διὰ τὴν] ἀνάγκῃ διὰ τὴν ἡλικίαν ἐσχόλαζον, ἐκλιπόντος δὲ τὸν βίον οὔτε λόγῳ οὔτε ἔργῳ ἔβλαψα οὐδένα τῶν κατηγορούντων, ἔχω δὲ καὶ τοιαῦτα εἰπεῖν, ἐξ ὧν ὠφελοίμην ἂν πολὺ δικαιότερον ὑπὸ τῶν ἀντιδίκων ἢ κακῶς πάσχοιμι.", "st": "9.14"}, {"sp": "N", "t": "τὴν μὲν οὖν ὀργὴν διὰ τὰ προειρημένα συνεστήσαντο, προφάσεως οὐδεμιᾶς πρὸς ἔχθραν ὑπαρχούσης. ὀμόσαντες μὲν οὖν τοὺς ἀστρατεύτους καταλέξειν παρέβησαν τοὺς ὅρκους, προὔθεσαν δὲ τῷ πλήθει βουλεύσασθαι περὶ τοῦ σώματος,", "st": "9.15"}, {"sp": "N", "t": "ζημιώσαντες μὲν ὡς τὴν ἀρχὴν λοιδοροῦντα, κατολιγωρήσαντες δὲ τοῦ δικαίου, βιαζόμενοι βλάπτειν ἐξ ἅπαντος [τοῦ] λόγου· πᾶν ⟨δ’⟩ ἂν ἔπραξαν μέλλοντες μεγάλα μὲν ἐμὲ βλάψειν, πολλὰ δ’ ἑαυτοὺς ὠφελήσειν, οἵτινες οὐδετέρου τούτων ὑπάρχοντος πάντα περὶ ἐλάττονος ποιοῦνται τοῦ ἀδικεῖν.", "st": "9.16"}, {"sp": "N", "t": "ἀλλὰ γὰρ οἳ κατεφρόνησαν τοῦ ὑμετέρου πλήθους, οὐδὲ φοβηθῆναι τοὺς θεοὺς ἠξίωσαν, ἀλλ’ οὕτως ὀλιγώρως καὶ παρανόμως προσηνέχθησαν, ὥστε ἀπολογήσασθαι μὲν περὶ τῶν πεπραγμένων οὐδ’ ἐπεχείρησαν, τὸ δὲ τελευταῖον, νομίζοντες οὐχ ἱκανῶς με τετιμωρῆσθαι, τὸ πέρας ἐκ τῆς πόλεως ἐξήλασαν.", "st": "9.17"}, {"sp": "N", "t": "διατεθέντες δὲ οὕτω παρανόμως καὶ βιαίως ἐπικρύψασθαι τὴν ἀδικίαν περὶ οὐδενὸς ἐποιήσαντο, παραγαγόντες δὲ πάλιν περὶ τῶν αὐτῶν ἠδικηκότα με οὐδὲν ἐπιδεικνύουσι καὶ λοιδοροῦσι, τοῖς μὲν ἐμοῖς ἐπιτηδεύμασιν οὐ προσηκούσας διαβολὰς ἐπιφέροντες, τοῖς δ’ αὑτῶν τρόποις τὰς οἰκείας καὶ συνήθεις.", "st": "9.18"}, {"sp": "N", "t": "οἵδε μὲν οὖν ἐκ παντὸς [τοῦ] τρόπου προθυμοῦνταί με τῇ δίκῃ ἁλῶναι· ὑμεῖς δὲ μήτε ταῖς τούτων διαβολαῖς ἐπαρθέντες ἐμοῦ καταψηφίσησθε, μήτε τοὺς βέλτιον καὶ δικαίως βουλευσαμένους ἀκύρους καταστήσητε. οἵδε μὲν γὰρ ἅπαντα καὶ κατὰ τοὺς νόμους καὶ κατὰ τὸ εἰκὸς ἔπραξαν, καὶ ἠδικηκότες μὲν οὐδὲν φαίνονται, λόγον δὲ πλεῖστον τοῦ δικαίου ποιησάμενοι.", "st": "9.19"}, {"sp": "N", "t": "τούτων μὲν οὖν ἀδικούντων μετρίως [ἂν] ἠγανάκτουν, ἡγούμενος τετάχθαι τοὺς μὲν ἐχθροὺς κακῶς ποιεῖν, τοὺς δὲ φίλους εὖ· παρ’ ὑμῶν δὲ τοῦ δικαίου στερηθεὶς πολὺ ἂν μᾶλλον λυπηθείην. δι’ ἔχθραν μὲν γὰρ οὐ δόξω κακῶς πεπονθέναι, διὰ κακίαν δὲ τῆς πόλεως.", "st": "9.20"}, {"sp": "N", "t": "λόγῳ μὲν οὖν περὶ τῆς ἀπογραφῆς ἀγωνίζομαι, ἔργῳ δὲ περὶ πολιτείας. τυχὼν μὲν γὰρ τῶν δικαίων (πιστεύω δὲ τῇ ὑμετέρα γνώμῃ) μείναιμι ἂν ⟨ἐν⟩ τῇ πόλει· παραχθεὶς δὲ ὑπὸ τῶνδε εἰ ἀδίκως ἁλοίην, ἀποδραίην ἄν. τίνι γὰρ ἐπαρθέντα ἐλπίδι δεῖ με συμπολιτεύεσθαι, ἢ τί με χρὴ διανοηθέντα, εἰδότα μὲν τῶν ἀντιδίκων τὴν προθυμίαν, ἀποροῦντα δ’ ὅθεν χρὴ τῶν δικαίων τινὸς τυχεῖν;", "st": "9.21"}, {"sp": "N", "t": "περὶ πλείστου οὖν ποιησάμενοι τὸ δίκαιον, καὶ ἐνθυμηθέντες ὅτι καὶ ὑπὲρ τῶν περιφανῶν ἀδικημάτων συγγνώμην ποιεῖσθε, τοὺς μηδὲν ἀδικήσαντας διὰ τὰς ἔχθρας μὴ περιίδητε ἀδίκως τοῖς μεγίστοις ἀτυχήμασι περιπεσόντας.", "st": "9.22"}, {"sp": "HDR", "t": "Ιʹ. Κατὰ Θεομνήστου Αʹ", "st": "10"}, {"sp": "N", "t": "μαρτύρων μὲν οὐκ ἀπορίαν μοι ἔσεσθαι δοκῶ, ὦ ἄνδρες δικασταί· πολλοὺς γὰρ ὑμῶν ὁρῶ δικάζοντας τῶν τότε παρόντων, ὅτε Λυσίθεος Θεόμνηστον εἰσήγγελλε τὰ ὅπλα ἀποβεβληκότα, οὐκ ἐξὸν αὐτῷ, δημηγορεῖν· ἐν ἐκείνῳ γὰρ τῷ ἀγῶνι τὸν πατέρα μ’ ἔφασκεν ἀπεκτονέναι τὸν ἐμαυτοῦ. ἐγὼ δ’,", "st": "10.1"}, {"sp": "N", "t": "εἰ μὲν τὸν ἑαυτοῦ με ἀπεκτονέναι ᾐτιᾶτο, συγγνώμην ἂν εἶχον αὐτῷ τῶν εἰρημένων (φαῦλον γὰρ αὐτὸν καὶ οὐδενὸς ἄξιον ἡγούμην)· οὐδ’ εἴ τι ἄλλο τῶν ἀπορρήτων ἤκουσα, οὐκ ἂν ἐπεξῆλθον αὐτῷ (ἀνελευθέρου γὰρ καὶ λίαν φιλοδίκου εἶναι νομίζω κακηγορίας δικάζεσθαι)·", "st": "10.2"}, {"sp": "N", "t": "νυνὶ δὲ αἰσχρόν μοι εἶναι δοκεῖ τοῦ πατρός, οὕτω πολλοῦ ἀξίου γεγενημένου καὶ ὑμῖν καὶ τῇ πόλει, μὴ τιμωρήσασθαι τὸν ταῦτ’ εἰρηκότα, καὶ παρ’ ὑμῶν εἰδέναι βούλομαι πότερον δώσει δίκην, ἢ τούτῳ μόνῳ Ἀθηναίων ἐξαίρετόν ἐστι καὶ ποιεῖν καὶ λέγειν παρὰ τοὺς νόμους ὅ τι ἂν βούληται.", "st": "10.3"}, {"sp": "N", "t": "ἐμοὶ γάρ, ὦ ἄνδρες δικασταί, ἔτη ἐστὶ ⟨δύο καὶ⟩ τριάκοντα, ἐξ ὅτου ⟨δ’⟩ ὑμεῖς κατεληλύθατε, εἰκοστὸν τουτί. φαίνομαι οὖν τρισκαιδεκέτης ὢν ὅτε ὁ πατὴρ ὑπὸ τῶν τριάκοντα ἀπέθνησκε. ταύτην δὲ ἔχων τὴν ἡλικίαν οὔτε τί ἔστιν ὀλιγαρχία ἠπιστάμην, οὔτε ἂν ἐκείνῳ ἀδικουμένῳ ἐδυνάμην βοηθῆσαι.", "st": "10.4"}, {"sp": "N", "t": "καὶ μὲν δὴ οὐκ ὀρθῶς τῶν χρημάτων ἕνεκα ἐπεβούλευσα ⟨ἂν⟩ αὐτῷ· ὁ γὰρ πρεσβύτερος ἀδελφὸς Πανταλέων ἅπαντα παρέλαβε, καὶ ἐπιτροπεύσας ἡμᾶς τῶν πατρῴων ἀπεστέρησεν, ὥστε πολλῶν ἕνεκα, ὦ ἄνδρες δικασταί, προσήκει μοι αὐτὸν βούλεσθαι ζῆν. ἀνάγκη μὲν οὖν περὶ αὐτῶν μνησθῆναι, οὐδὲν δὲ δεῖ πολλῶν λόγων· σχεδὸν ⟨γὰρ⟩ ἐπίστασθε ἅπαντες ὅτι ἀληθῆ λέγω. ὅμως δὲ μάρτυρας αὐτῶν παρέξομαι.", "st": "10.5"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "10.6"}, {"sp": "N", "t": "ἴσως τοίνυν, ὦ ἄνδρες δικασταί, περὶ τούτων μὲν οὐδὲν ἀπολογήσεται, ἐρεῖ δὲ πρὸς ὑμᾶς ἅπερ ἐτόλμα λέγειν καὶ πρὸς τὸν διαιτητήν, ὡς οὐκ ἔστι τῶν ἀπορρήτων, ἐάν τις εἴπῃ τὸν πατέρα ἀπεκτονέναι· τὸν γὰρ νόμον οὐ ταῦτ’ ἀπαγορεύειν, ἀλλ’ ἀνδροφόνον οὐκ ἐᾶν λέγειν.", "st": "10.6"}, {"sp": "N", "t": "ἐγὼ δὲ οἶμαι ὑμᾶς, ὦ ἄνδρες δικασταί, οὐ περὶ τῶν ὀνομάτων διαφέρεσθαι ἀλλὰ τῆς τούτων διανοίας, καὶ πάντας εἰδέναι, ὅτι ὅσοι ⟨ἀπεκτόνασί τινας, καὶ ἀνδροφόνοι εἰσί, καὶ ὅσοι⟩ ἀνδροφόνοι εἰσί, καὶ ἀπεκτόνασί τινας. πολὺ γὰρ ἔργον ἦν τῷ νομοθέτῃ ἅπαντα τὰ ὀνόματα γράφειν ὅσα τὴν αὐτὴν δύναμιν ἔχει· ἀλλὰ περὶ ἑνὸς εἰπὼν περὶ πάντων ἐδήλωσεν.", "st": "10.7"}, {"sp": "N", "t": "οὐ γὰρ δήπου, ὦ Θεόμνηστε, εἰ μέν τίς σε εἴποι πατραλοίαν ἢ μητραλοίαν, ἠξίους ἂν αὐτὸν ὀφλεῖν σοι δίκην, εἰ δέ τις εἴποι ὡς τὴν τεκοῦσαν ἢ τὸν φύσαντα ἔτυπτες, ᾤου ἂν αὐτὸν ἀζήμιον δεῖν εἶναι ὡς οὐδὲν τῶν ἀπορρήτων εἰρηκότα.", "st": "10.8"}, {"sp": "N", "t": "ἡδέως γὰρ ἄν σου πυθοίμην (περὶ τοῦτο γὰρ δεινὸς εἶ καὶ μεμελέτηκας καὶ ποιεῖν καὶ λέγειν)· εἴ τίς σε εἴποι ῥῖψαι τὴν ἀσπίδα (ἐν δὲ τῷ νόμῳ εἴρηται, “ἐάν τις φάσκῃ ἀποβεβληκέναι, ὑπόδικον εἶναι”), οὐκ ἂν ἐδικάζου αὐτῷ ἀλλ’ ἐξήρκει ἄν σοι ἐρριφέναι τὴν ἀσπίδα λέγοντι οὐδέν σοι μέλειν;", "st": "10.9"}, {"sp": "N", "t": "οὐδὲ γὰρ τὸ αὐτό ἐστι ῥῖψαι καὶ ἀποβεβληκέναι· ἀλλ’ οὐδ’ ἂν τῶν ἕνδεκα γενόμενος ἀποδέξαιο, εἴ τις ἀπάγοι τινὰ φάσκων θοἰμάτιον ἀποδεδύσθαι ἢ τὸν χιτωνίσκον ἐκδεδύσθαι, ἀλλ’ ἀφείης ἂν τὸν αὐτὸν τρόπον, ὅτι οὐ λωποδύτης ὀνομάζεται. οὐδ’ εἴ τις παῖδα ἐξαγαγὼν ληφθείη, οὐκ ἂν φάσκοις αὐτὸν ἀνδραποδιστὴν εἶναι, εἴπερ μαχεῖ τοῖς ὀνόμασιν, ἀλλὰ μὴ τοῖς ἔργοις τὸν νοῦν προσέξεις, ὧν ἕνεκα τὰ ὀνόματα πάντες τίθενται.", "st": "10.10"}, {"sp": "N", "t": "ἔτι τοίνυν σκέψασθε, ὦ ἄνδρες δικασταί· οὑτοσὶ γάρ μοι δοκεῖ ὑπὸ ῥᾳθυμίας καὶ μαλακίας οὐδ’ εἰς Ἄρειον πάγον ἀναβεβηκέναι. πάντες γὰρ ἐπίστασθε ὅτι ἐν ἐκείνῳ τῷ χωρίῳ, ὅταν τὰς τοῦ φόνου δίκας δικάζωνται, οὐ διὰ τούτου τοῦ ὀνόματος τὰς διωμοσίας ποιοῦνται, ἀλλὰ δι’ οὗπερ ἐγὼ κακῶς ἀκήκοα· ὁ μὲν γὰρ διώκων ὡς ἔκτεινε διόμνυται, ὁ δὲ φεύγων ὡς οὐκ ἔκτεινεν.", "st": "10.11"}, {"sp": "N", "t": "οὐκ οὖν ἄτοπον ἂν εἴη τὸν δράσαντ’ ἀφεῖναι φάσκοντα ἀνδροφόνον εἶναι, ὅτι ὁ διώκων, ὡς ἔκτεινε, τὸν φεύγοντα διωμόσατο; τί γὰρ ταῦτα, ὧν οὗτος ἐρεῖ, διαφέρει; καὶ αὐτὸς μὲν Λυσιθέῳ κακηγορίας ἐδικάσω εἰπόντι σε ἐρριφέναι τὴν ἀσπίδα. καίτοι περὶ μὲν τοῦ ῥῖψαι οὐδὲν ⟨ἐν⟩ τῷ νόμῳ εἴρηται, ἐὰν δέ τις εἴπῃ ἀποβεβληκέναι τὴν ἀσπίδα, πεντακοσίας δραχμὰς ὀφείλειν κελεύει.", "st": "10.12"}, {"sp": "N", "t": "οὐκ οὖν δεινόν, εἰ ὅταν μὲν δέῃ σὲ κακῶς ἀκούσαντα τοὺς ἐχθροὺς τιμωρεῖσθαι, οὕτω τοὺς νόμους ὥσπερ ἐγὼ νῦν λαμβάνεις, ὅταν δ’ ἕτερον παρὰ τοὺς νόμους εἴπῃς κακῶς, οὐκ ἀξιοῖς δοῦναι δίκην; πότερον οὕτως σὺ δεινὸς εἶ ὥστε, ὅπως ἂν βούλῃ, οἷός τ’ εἶ χρῆσθαι τοῖς νόμοις, ἢ τοσοῦτον δύνασαι ὥστε οὐδέποτε οἴει τοὺς ἀδικουμένους ὑπὸ σοῦ τιμωρίας τεύξεσθαι; εἶτ’ οὐκ αἰσχύνῃ οὕτως ἀνοήτως διακείμενος,", "st": "10.13"}, {"sp": "N", "t": "ὥστε οὐκ ἐξ ὧν εὖ πεποίηκας τὴν πόλιν, ἀλλ’ ἐξ ὧν ἀδικῶν οὐ δέδωκας δίκην, οἴει δεῖν πλεονεκτεῖν; καί μοι ἀνάγνωθι τὸν νόμον.", "st": "10.14"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "10.15"}, {"sp": "N", "t": "ἐγὼ τοίνυν, ὦ ἄνδρες δικασταί, ὑμᾶς μὲν πάντας εἰδέναι ἡγοῦμαι ὅτι ἐγὼ μὲν ὀρθῶς λέγω, τοῦτον δὲ οὕτω σκαιὸν εἶναι ὥστε οὐ δύνασθαι μαθεῖν τὰ λεγόμενα. βούλομαι οὖν αὐτὸν καὶ ἐξ ἑτέρων νόμων περὶ τούτων διδάξαι, ἐάν πως ἀλλὰ νῦν ἐπὶ τοῦ βήματος παιδευθῇ καὶ τὸ λοιπὸν ἡμῖν μὴ παρέχῃ πράγματα. καί μοι ἀνάγνωθι τούτους τοὺς νόμους τοὺς Σόλωνος τοὺς παλαιούς.", "st": "10.15"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "10.16"}, {"sp": "N", "t": "“δεδέσθαι δ’ ἐν τῇ ποδοκάκκῃ ἡμέρας πέντε τὸν πόδα, ἐὰν [μὴ]” προστιμήσῃ ἡ ἡλιαία.", "st": "10.16"}, {"sp": "N", "t": "ἡ ποδοκάκκη αὕτη ἐστίν, ὦ Θεόμνηστε, ὃ νῦν καλεῖται ἐν τῷ ξύλῳ δεδέσθαι. εἰ οὖν ὁ δεθεὶς ἐξελθὼν ἐν ταῖς εὐθύναις τῶν ἕνδεκα κατηγοροίη ὅτι οὐκ ἐν τῇ ποδοκάκκῃ ἐδέδετο ἀλλ’ ἐν τῷ ξύλῳ, οὐκ ἂν ἠλίθιον αὐτὸν νομίζοιεν; λέγε ἕτερον νόμον.", "st": "10.16"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "10.17"}, {"sp": "N", "t": "“ἐπεγγυᾶν δ’ ἐπιορκήσαντα τὸν Ἀπόλλω. δεδιότα δὲ δίκης ἕνεκα δρασκάζειν.”", "st": "10.17"}, {"sp": "N", "t": "τοῦτο τὸ ἐπιορκήσαντα ὀμόσαντά ἐστι, τό τε δρασκάζειν, ὃ νῦν ἀποδιδράσκειν ὀνομάζομεν.", "st": "10.17"}, {"sp": "N", "t": "“ὅστις δὲ ἀπίλλει τῇ θύρᾳ, ἔνδον τοῦ κλέπτου ὄντος.”", "st": "10.17"}, {"sp": "N", "t": "τὸ ἀπίλλειν τοῦτο ἀποκλείειν νομίζεται, καὶ μηδὲν διὰ τοῦτο διαφέρου.", "st": "10.17"}, {"sp": "N", "t": "“τὸ ἀργύριον στάσιμον εἶναι ἐφ’ ὁπόσῳ ἂν βούληται ὁ δανείζων.”", "st": "10.18"}, {"sp": "N", "t": "τὸ στάσιμον τοῦτό ἐστιν, ὦ βέλτιστε, οὐ ζυγῷ ἱστάναι ἀλλὰ τόκον πράττεσθαι ὁπόσον ἂν βούληται. ἔτι δ’ ἀνάγνωθι τουτουὶ τοῦ νόμου τὸ τελευταῖον.", "st": "10.18"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "10.19"}, {"sp": "N", "t": "“ὅσαι δὲ πεφασμένως πολοῦνται,” καὶ", "st": "10.19"}, {"sp": "N", "t": "“οἰκῆος [καὶ] βλάβης τὴν διπλὴν” εἶναι ὀφείλειν.", "st": "10.19"}, {"sp": "N", "t": "προσέχετε τὸν νοῦν. τὸ μὲν πεφασμένως ἐστὶ φανερῶς, πολεῖσθαι δὲ βαδίζειν, τὸ δὲ οἰκῆος θεράποντος.", "st": "10.19"}, {"sp": "N", "t": "πολλὰ δὲ τοιαῦτα καὶ ἄλλα ἐστίν, ὦ ἄνδρες δικασταί. ἀλλ’ εἰ μὴ σιδηροῦς ἐστιν, οἴομαι αὐτὸν ἔννουν γεγονέναι ὅτι τὰ μὲν πράγματα ταὐτά ἐστι νῦν τε καὶ πάλαι, τῶν δὲ ὀνομάτων ἐνίοις οὐ τοῖς αὐτοῖς χρώμεθα νῦν τε καὶ πρότερον. δηλώσει δέ· οἰχήσεται γὰρ ἀπιὼν ἀπὸ τοῦ βήματος σιωπῇ.", "st": "10.20"}, {"sp": "N", "t": "εἰ δὲ μή, δέομαι ὑμῶν, ὦ ἄνδρες δικασταί, τὰ δίκαια ψηφίσασθαι, ἐνθυμουμένους ὅτι πολὺ μεῖζον κακόν ἐστιν ἀκοῦσαί τινα τὸν πατέρα ἀπεκτονέναι ἢ τὴν ἀσπίδα ἀποβεβληκέναι. ἐγὼ γοῦν δεξαίμην ἂν πάσας τὰς ἀσπίδας ἐρριφέναι ἢ τοιαύτην γνώμην ἔχειν περὶ τὸν πατέρα.", "st": "10.21"}, {"sp": "N", "t": "οὗτος οὖν ἔνοχος μὲν ὢν τῇ αἰτίᾳ, ἐλάττονος δὲ οὔσης αὐτῷ τῆς συμφορᾶς, οὐ μόνον ὑφ’ ὑμῶν ἠλεήθη, ἀλλὰ καὶ τὸν μαρτυρήσαντα ἠτίμωσεν. ἐγὼ δὲ ἑωρακὼς μὲν ἐκεῖνο τοῦτον ποιήσαντα ὃ καὶ ὑμεῖς ἴστε, αὐτὸς δὲ σώσας τὴν ἀσπίδα, ἀκηκοὼς δὲ οὕτως ἀνόσιον καὶ δεινὸν πρᾶγμα, μεγίστης δὲ οὔσης μοι τῆς συμφορᾶς, εἰ ἀποφεύξεται, τούτῳ δ’ οὐδενὸς ἀξίας, εἰ κακηγορίας ἁλώσεται, οὐκ ἄρα δίκην παρ’ αὐτοῦ λήψομαι; τίνος ὄντος ἐμοὶ πρὸς ὑμᾶς ἐγκλήματος;", "st": "10.22"}, {"sp": "N", "t": "πότερον ὅτι δικαίως ἀκήκοα; ἀλλ’ οὐδ’ ἂν αὐτοὶ φήσαιτε. ἀλλ’ ὅτι βελτίων καὶ ἐκ βελτιόνων ὁ φεύγων ἐμοῦ; ἀλλ’ οὐδ’ ἂν αὐτὸς ἀξιώσειεν. ἀλλ’ ὅτι ἀποβεβληκὼς τὰ ὅπλα δικάζομαι κακηγορίας τῷ σώσαντι; ἀλλ’ οὐχ οὗτος ὁ λόγος ἐν τῇ πόλει κατεσκέδασται.", "st": "10.23"}, {"sp": "N", "t": "ἀναμνήσθητε δὲ ὅτι μεγάλην καὶ καλὴν ἐκείνην δωρεὰν αὐτῷ δεδώκατε· ἐν ᾗ τίς οὐκ ἂν ἐλεήσειε Διονύσιον, τοιαύτῃ μὲν συμφορᾷ περιπεπτωκότα, ἄνδρα δὲ ἄριστον ἐν τοῖς κινδύνοις γεγενημένον,", "st": "10.24"}, {"sp": "N", "t": "ἀπιόντα δὲ ἀπὸ τοῦ δικαστηρίου [καὶ] λέγοντα ὅτι δυστυχεστάτην ἐκείνην εἴημεν στρατείαν ἐστρατευμένοι, ἐν ᾗ πολλοὶ μὲν ἡμῶν ἀπέθανον, οἱ δὲ σώσαντες τὰ ὅπλα ὑπὸ τῶν ἀποβαλόντων ψευδομαρτυρίων ἑαλώκασι, κρεῖττον δὲ ἦν αὐτῷ τότε ἀποθανεῖν ἢ οἴκαδ’ ἐλθόντι τοιαύτῃ τύχῃ χρῆσθαι;", "st": "10.25"}, {"sp": "N", "t": "μὴ τοίνυν ἀκούσαντά ⟨τε⟩ Θεόμνηστον κακῶς τὰ προσήκοντα ἐλεεῖτε, καὶ ὑβρίζοντι καὶ λέγοντι παρὰ τοὺς νόμους συγγνώμην ἔχετε. τίς γὰρ ἂν ἐμοὶ μείζων ταύτης γένοιτο συμφορά, περὶ τοιούτου πατρὸς οὕτως αἰσχρὰς αἰτίας ἀκηκοότι;", "st": "10.26"}, {"sp": "N", "t": "ὃς πολλάκις μὲν ἐστρατήγησε, πολλοὺς δὲ καὶ ἄλλους κινδύνους μεθ’ ὑμῶν ἐκινδύνευσε· καὶ οὔτε τοῖς πολεμίοις τὸ ἐκείνου σῶμα ὑποχείριον ἐγένετο, οὔτε τοῖς πολίταις οὐδεμίαν πώποτε ὦφλεν εὐθύνην, ἔτη δὲ γεγονὼς ἑπτὰ καὶ ἑξήκοντα ἐν ὀλιγαρχίᾳ δι’ εὔνοιαν τοῦ ὑμετέρου πλήθους ἀπέθανεν.", "st": "10.27"}, {"sp": "N", "t": "ἆρ’ ἄξιον ὀργισθῆναι τῷ ⟨τοιαῦτ’⟩ εἰρηκότι καὶ βοηθῆσαι τῷ πατρί, ὡς καὶ ἐκείνου κακῶς ἀκηκοότος; τί γὰρ ἂν τούτου ἀνιαρότερον γένοιτο αὐτῷ, ἢ τεθνάναι μὲν ὑπὸ τῶν ἐχθρῶν, αἰτίαν δ’ ἔχειν ὑπὸ τῶν παίδων ⟨ἀνῃρῆσθαι⟩; οὗ ἔτι καὶ νῦν, ὦ ἄνδρες δικασταί, τῆς ἀρετῆς τὰ μνημεῖα πρὸς τοῖς ὑμετέροις ⟨ἱεροῖς⟩ ἀνάκειται, τὰ δὲ τούτου καὶ τοῦ τούτου πατρὸς τῆς κακίας πρὸς τοῖς τῶν πολεμίων· οὕτω σύμφυτος αὐτοῖς ἡ δειλία.", "st": "10.28"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, ὅσῳ μείζους εἰσὶ καὶ νεανίαι τὰς ὄψεις, τοσούτῳ μᾶλλον ὀργῆς ἄξιοί εἰσι. δῆλον γὰρ ὅτι τοῖς μὲν σώμασι δύνανται, τὰς δὲ ψυχὰς οὐκ ⟨εὖ⟩ ἔχουσιν.", "st": "10.29"}, {"sp": "N", "t": "ἀκούω δ’ αὐτόν, ὦ ἄνδρες δικασταί, ἐπὶ τοῦτον τὸν λόγον τρέπεσθαι, ὡς ὀργισθεὶς εἴρηκε ταῦτα ἐμοῦ μαρτυρήσαντος τὴν αὐτὴν μαρτυρίαν Διονυσίῳ. ὑμεῖς δ’ ἐνθυμεῖσθε, ὦ ἄνδρες δικασταί, ὅτι ὁ νομοθέτης οὐδεμίαν ὀργῇ συγγνώμην δίδωσιν, ἀλλὰ ζημιοῖ τὸν λέγοντα, ἐὰν μὴ ἀποφαίνῃ ὡς ἔστιν ἀληθῆ τὰ εἰρημένα. ἐγὼ δὲ δὶς ἤδη περὶ τούτου μεμαρτύρηκα· οὐ γὰρ πω ᾔδη ὅτι ὑμεῖς τοὺς μὲν ἰδόντας τιμωρεῖσθε, τοῖς δὲ ἀποβαλοῦσι συγγνώμην ἔχετε.", "st": "10.30"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· ἐγὼ δ’ ὑμῶν δέομαι καταψηφίσασθαι Θεομνήστου, ἐνθυμουμένους ὅτι οὐκ ἂν γένοιτο τούτου μείζων ἀγών μοι. νῦν γὰρ διώκω ⟨μὲν⟩ κακηγορίας, τῇ δ’ αὐτῇ ψήφῳ φόνου φεύγω τοῦ πατρός, ὃς μόνος, ἐπειδὴ τάχιστα ἐδοκιμάσθην, ἐπεξῆλθον τοῖς τριάκοντα ἐν Ἀρείῳ πάγῳ.", "st": "10.31"}, {"sp": "N", "t": "ὧν μεμνημένοι καὶ ἐμοὶ καὶ τῷ πατρὶ βοηθήσατε καὶ τοῖς νόμοις τοῖς κειμένοις καὶ τοῖς ὅρκοις οἷς ὀμωμόκατε.", "st": "10.32"}, {"sp": "HDR", "t": "ΙΑʹ. Κατὰ Θεομνήστου Βʹ", "st": "11"}, {"sp": "N", "t": "ὅτι μὲν τὸν πατέρα μ’ ἔφασκεν ἀπεκτονέναι, πολλοὶ συνοίδασιν ὑμῶν, καὶ μαρτυροῦσι δέ μοι· ὅτι δὲ οὐ πεποίηκα, δῆλον· ἔτη γὰρ ἐστί μοι δύο καὶ τριάκοντα, ἐξ οὗ δ’ ὑμεῖς κατήλθετε, εἰκοστὸν τουτί.", "st": "11.1"}, {"sp": "N", "t": "φαίνομαι οὖν δωδεκαέτης ὤν, ὅτε ὁ πατὴρ ὑπὸ τῶν τριάκοντα ἀπέθνῃσκεν, ὥστ’ οὐδ’ ὅ τι ὀλιγαρχία ἦν ᾔδη, οὐδὲ τῷ πατρὶ βοηθεῖν οἷός τ’ ἦ. ἀλλὰ μὴν οὐδὲ τῶν χρημάτων ἕνεκα ἐπεβούλευσα αὐτῷ· ὁ γὰρ πρεσβύτερος ἀδελφὸς πάντα λαβὼν ἀπεστέρησεν ἡμᾶς.", "st": "11.2"}, {"sp": "N", "t": "ἴσως δ’ ἐρεῖ ὡς οὐκ ἔστι τῶν ἀπορρήτων, ἐάν τις φῇ τὸν πατέρα ἀπεκτονέναι· τὸν γὰρ νόμον οὐ ταῦτ’ ἀπαγορεύειν, ἀλλ’ ἀνδροφόνον οὐκ ἐᾶν λέγειν. ἐγὼ δ’ οἶμαι δεῖν οὐ περὶ τῶν ὀνομάτων διαφέρεσθαι, ἀλλὰ περὶ τῆς τῶν ἔργων διανοίας, καὶ πάντας εἰδέναι ὅτι ὁπόσοι ἀπεκτόνασί τινας, καὶ ἀνδροφόνοι τῶν αὐτῶν εἰσι, καὶ ὅσοι ἀνδροφόνοι τινός, καὶ ἀπεκτόνασι τοῦτον.", "st": "11.3"}, {"sp": "N", "t": "πολὺ γὰρ ἂν ἔργον εἴη τῷ νομοθέτῃ πάντα γράφειν τὰ ὀνόματα, ὅσα τὴν αὐτὴν δύναμιν ἔχει· ἀλλὰ περὶ ἑνὸς εἰπὼν περὶ πάντων ἐδήλωσεν. οὐ γὰρ δήπου ἐὰν μέν τις πατραλοίαν ἢ μητραλοίαν καλῇ σε, ὑπόδικός ἐστιν, ἐὰν δέ τις τὴν τεκοῦσαν ἢ τὸν φυτεύσαντα τύπτειν ⟨φῇ⟩, ἀζήμιος ἔσται.", "st": "11.4"}, {"sp": "N", "t": "καὶ ἐάν τις εἴπῃ ῥίψασπιν, ἀθῷος ἔσται· τὸν γὰρ νόμον, ἐάν τις εἴπῃ ἀποβεβληκέναι τὴν ἀσπίδα, ζημίαν τάττειν, ἀλλ’ οὐκ ἄν τις ῥῖψαι φῇ αὐτήν. ὁμοίως δ’ ἂν καὶ τῶν ἕνδεκα γενόμενος οὐκ ἂν ἀπεδέχου τὸν ἀπαγόμενον, ὅτι θοἰμάτιον ἐξέδυέ τινος ἢ τὸν χιτωνίσκον,", "st": "11.5"}, {"sp": "N", "t": "εἰ μὴ λωποδύτην ὠνόμαζεν. οὐδ’ εἴ τις παῖδ’ ἐξῆγεν, ὡς ἀνδραποδιστήν· καὶ αὐτὸς μὲν ἐδικάσω κακηγορίας τῷ εἰπόντι σε ῥῖψαι τὴν ἀσπίδα. καίτοι ἐν τῷ νόμῳ οὐ γέγραπται, ἀλλ’ ἐάν τις φῇ ἀποβεβληκέναι. πῶς οὖν οὐ δεινόν, ἐὰν μέν τις σὲ ἔπῃ, τοὺς νόμους ἐκλαμβάνειν οὕτως ὥσπερ ἐγὼ νῦν, καὶ τιμωρεῖσθαι τοὺς ἐχθρούς, ἐὰν δ’ αὐτὸς εἴπῃς, οὐκ ἀξιοῦν δοῦναι δίκην;", "st": "11.6"}, {"sp": "N", "t": "βοηθήσατε οὖν μοι, ἐνθυμούμενοι ὅτι μεῖζόν ἐστι κακὸν ⟨ἀκοῦσαι⟩ τὸν πατέρα ἀπεκτονέναι ἢ τὴν ἀσπίδα ῥῖψαι. ἐγὼ γοῦν δεξαίμην ⟨ἂν⟩ πάσας ἀποβεβληκέναι ἢ τοιαύτην γνώμην περὶ τὸν πατέρα ἔχειν. καίτοι γε τοῦτον μὲν ἑώρακα ποιοῦντα, ὡς καὶ ὑμεῖς ἴστε, αὐτὸς δ’ ἔσωσα τὴν ἀσπίδα. ὥστε διὰ τί οὐκ ἂν λάβοιμι δίκην παρ’ αὐτοῦ;", "st": "11.7"}, {"sp": "N", "t": "τίνος ἐγκλήματός μοι ὄντος; πότερον ὡς δικαίως ἤκουσα; ἀλλ’ οὐδ’ ἂν αὐτοὶ φήσαιτε. ἀλλ’ ὡς βελτίων οὗτος; ἀλλ’ οὐδ’ ἂν αὐτὸς ἀξιώσειεν. ἀλλ’ ὅτι ἀποβεβληκὼς τὰ ὅπλα σώσαντι δικάζομαι; ἀλλ’ οὐχ οὗτος ὁ λόγος διέσπαρται κατὰ τὴν πόλιν. μὴ δὴ κακῶς ἀκούοντα τὰ προσήκοντα ἐλεεῖτε,", "st": "11.8"}, {"sp": "N", "t": "μηδ’ ὑβρίζοντί τε καὶ λέγοντι παρὰ τοὺς νόμους συγγνώμην ἔχετε, καὶ ταῦτα εἰς ἄνδρα ὃς πολλὰς μὲν στρατηγίας ἐστρατήγηκε, πολλοὺς δὲ μεθ’ ὑμῶν ⟨κινδύνους⟩ κεκινδύνευκε, καὶ οὔτε τοῖς πολεμίοις ὑποχείριος γέγονεν οὔθ’ ὑμῖν εὔθυναν ὦφλεν, ἑβδομήκοντα δ’ ἐτῶν ὢν ἐπ’ ὀλιγαρχίας ἐτελεύτησε διὰ τὴν ὑμετέραν εὔνοιαν.", "st": "11.9"}, {"sp": "N", "t": "ἄξιον δὲὀργισθῆναι ὑπὲρ αὐτοῦ· τί γὰρ ἂν τούτου ἀνιαρότερον ἀκούσειεν, εἰ τεθνηκὼς ὑπὸ τῶν ἐχθρῶν αἰτίαν ἔχοι ὑπὸ τῶν τέκνων ἀνῃρῆσθαι; οὗ τῆς ἀρετῆς τὰ μνημεῖα πρὸς τοῖς ὑμετέροις ἱεροῖς ἀνάκειται, τῆς δὲ τούτων κακίας πρὸς τοῖς τῶν πολεμίων.", "st": "11.10"}, {"sp": "N", "t": "ἐρεῖ δὲ ὡς ὀργισθεὶς εἴρηκεν. ὑμεῖς δ’ ἐνθυμεῖσθε ὅτι ὁ νομοθέτης οὐδεμίαν συγγνώμην ὀργῇ δίδωσιν, ἀλλὰ ζημιοῖ τὸν λέγοντα, ἐὰν μὴ ἀποδεικνύῃ ἀληθῆ. ἐγὼ δὲ δὶς περὶ τούτου μεμαρτύρηκα· οὐ γὰρ ᾔδη ὅτι ὑμεῖς τοὺς μὲν ἰδόντας τιμωρεῖσθε, τοῖς δὲ ἀποβαλοῦσι συγγνώμην ἔχετε. δέομαι οὖν καταψηφίσασθαι αὐτοῦ.", "st": "11.11"}, {"sp": "N", "t": "νυνὶ γὰρ διώκω μὲν κακηγορίας, τῇ δ’ αὐτῇ ψήφῳ φόνου φεύγω τοῦ πατρός, οὗ μείζων ἀγὼν οὐκ ἂν γένοιτό μοι, ὃς μόνος δοκιμασθεὶς τοῖς τριάκοντ’ ἐπεξῆλθον ἐν Ἀρείῳ πάγῳ. βοηθήσατ’ οὖν κἀκείνῳ κἀμοί.", "st": "11.12"}, {"sp": "HDR", "t": "ΙΒʹ. Κατὰ Ἐρατοσθένους τοῦ γενομένου τῶν τριάκοντα, ὃν αὐτὸς εἶπε Λυσίας", "st": "12"}, {"sp": "N", "t": "οὐκ ἄρξασθαί μοι δοκεῖ ἄπορον εἶναι, ὦ ἄνδρες δικασταί, τῆς κατηγορίας, ἀλλὰ παύσασθαι λέγοντι· τοιαῦτα αὐτοῖς τὸ μέγεθος καὶ τοσαῦτα τὸ πλῆθος εἴργασται, ὥστε μήτ’ ἂν ψευδόμενον δεινότερα τῶν ὑπαρχόντων κατηγορῆσαι, μήτε τἀληθῆ βουλόμενον εἰπεῖν ἅπαντα δύνασθαι, ἀλλ’ ἀνάγκη ἢ τὸν κατήγορον ἀπειπεῖν ἢ τὸν χρόνον ἐπιλιπεῖν.", "st": "12.1"}, {"sp": "N", "t": "τοὐναντίον δέ μοι δοκοῦμεν πείσεσθαι ἢ ἐν τῷ πρὸ τοῦ χρόνῳ. πρότερον μὲν γὰρ ἔδει τὴν ἔχθραν τοὺς κατηγοροῦντας ἐπιδεῖξαι, ἥτις εἴη πρὸς τοὺς φεύγοντας· νυνὶ δὲ παρὰ τῶν φευγόντων χρὴ πυνθάνεσθαι ἥτις ἦν αὐτοῖς πρὸς τὴν πόλιν ἔχθρα, ἀνθ’ ὅτου τοιαῦτα ἐτόλμησαν εἰς αὐτὴν ἐξαμαρτάνειν. οὐ μέντοι ὡς οὐκ ἔχων οἰκείας ἔχθρας καὶ συμφορὰς τοὺς λόγους ποιοῦμαι, ἀλλ’ ὡς ἅπασι πολλῆς ἀφθονίας οὔσης ὑπὲρ τῶν ἰδίων ἢ ὑπὲρ τῶν δημοσίων ὀργίζεσθαι.", "st": "12.2"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν, ὦ ἄνδρες δικασταί, οὔτ’ ἐμαυτοῦ πώποτε οὔτε ἀλλότρια πράγματα πράξας νῦν ἠνάγκασμαι ὑπὸ τῶν γεγενημένων τούτου κατηγορεῖν, ὥστε πολλάκις εἰς πολλὴν ἀθυμίαν κατέστην, μὴ διὰ τὴν ἀπειρίαν ἀναξίως καὶ ἀδυνάτως ὑπὲρ τοῦ ἀδελφοῦ καὶ ἐμαυτοῦ τὴν κατηγορίαν ποιήσομαι. ὅμως δὲ πειράσομαι ὑμᾶς ἐξ ἀρχῆς ὡς ἂν δύνωμαι δι’ ἐλαχίστων διδάξαι.", "st": "12.3"}, {"sp": "N", "t": "οὑμὸς πατὴρ Κέφαλος ἐπείσθη μὲν ὑπὸ Περικλέους εἰς ταύτην τὴν γῆν ἀφικέσθαι, ἔτη δὲ τριάκοντα ᾤκησε, καὶ οὐδενὶ πώποτε οὔτε ἡμεῖς οὔτε ἐκεῖνος δίκην οὔτε ἐδικασάμεθα οὔτε ἐφύγομεν, ἀλλ’ οὕτως ᾠκοῦμεν δημοκρατούμενοι ὥστε μήτε εἰς τοὺς ἄλλους ἐξαμαρτάνειν μήτε ὑπὸ τῶν ἄλλων ἀδικεῖσθαι.", "st": "12.4"}, {"sp": "N", "t": "ἐπειδὴ δ’ οἱ τριάκοντα πονηροὶ [μὲν] καὶ συκοφάνται ὄντες εἰς τὴν ἀρχὴν κατέστησαν, φάσκοντες χρῆναι τῶν ἀδίκων καθαρὰν ποιῆσαι τὴν πόλιν καὶ τοὺς λοιποὺς πολίτας ἐπ’ ἀρετὴν καὶ δικαιοσύνην τραπέσθαι, [καὶ] τοιαῦτα λέγοντες οὐ τοιαῦτα ποιεῖν ἐτόλμων, ὡς ἐγὼ περὶ τῶν ἐμαυτοῦ πρῶτον εἰπὼν καὶ περὶ τῶν ὑμετέρων ἀναμνῆσαι πειράσομαι.", "st": "12.5"}, {"sp": "N", "t": "Θέογνις γὰρ καὶ Πείσων ἔλεγον ἐν τοῖς τριάκοντα περὶ τῶν μετοίκων, ὡς εἶέν τινες τῇ πολιτείᾳ ἀχθόμενοι· καλλίστην οὖν εἶναι πρόφασιν τιμωρεῖσθαι μὲν δοκεῖν, τῷ δ’ ἔργω χρηματίζεσθαι· πάντως δὲ τὴν μὲν πόλιν πένεσθαι τὴν ⟨δ’⟩ ἀρχὴν δεῖσθαι χρημάτων.", "st": "12.6"}, {"sp": "N", "t": "καὶ τοὺς ἀκούοντας οὐ χαλεπῶς ἔπειθον· ἀποκτιννύναι μὲν γὰρ ἀνθρώπους περὶ οὐδενὸς ἡγοῦντο, λαμβάνειν δὲ χρήματα περὶ πολλοῦ ἐποιοῦντο. ἔδοξεν οὖν αὐτοῖς δέκα συλλαβεῖν, τούτων δὲ δύο πένητας, ἵνα αὐτοῖς ᾖ πρὸς τοὺς ἄλλους ἀπολογία, ὡς οὐ χρημάτων ἕνεκα ταῦτα πέπρακται, ἀλλὰ συμφέροντα τῇ πολιτεία γεγένηται, ὥσπερ τι τῶν ἄλλων εὐλόγως πεποιηκότες.", "st": "12.7"}, {"sp": "N", "t": "διαλαβόντες δὲ τὰς οἰκίας ἐβάδιζον· καὶ ἐμὲ μὲν ξένους ἑστιῶντα κατέλαβον, οὓς ἐξελάσαντες Πείσωνί με παραδιδόασιν· οἱ δὲ ἄλλοι εἰς τὸ ἐργαστήριον ἐλθόντες τὰ ἀνδράποδα ἀπεγράφοντο.", "st": "12.8"}, {"sp": "N", "t": "ἐγὼ δὲ Πείσωνα μὲν ἠρώτων εἰ βούλοιτό με σῶσαι χρήματα λαβών. ὁ δ’ ἔφασκεν, εἰ πολλὰ εἴη. εἶπον ὅτι τάλαντον ἀργυρίου ἕτοιμος εἴην δοῦναι· ὁ δ’ ὡμολόγησε ταῦτα ποιήσειν. ἠπιστάμην μὲν οὖν ὅτι οὔτε θεοὺς οὔτ’ ἀνθρώπους νομίζει, ὅμως δ’ ἐκ τῶν παρόντων ἐδόκει μοι ἀναγκαιότατον εἶναι πίστιν παρ’ αὐτοῦ λαβεῖν.", "st": "12.9"}, {"sp": "N", "t": "ἐπειδὴ δὲ ὤμοσεν, ἐξώλειαν ἑαυτῷ καὶ τοῖς παισὶν ἐπαρώμενος, λαβὼν τὸ τάλαντόν με σώσειν, εἰσελθὼν εἰς τὸ δωμάτιον τὴν κιβωτὸν ἀνοίγνυμι. Πείσων δ’ αἰσθόμενος εἰσέρχεται, καὶ ἰδὼν τὰ ἐνόντα καλεῖ τῶν ὑπηρετῶν δύο, καὶ τὰ ἐν τῇ κιβωτῷ λαβεῖν ἐκέλευσεν.", "st": "12.10"}, {"sp": "N", "t": "ἐπεὶ δὲ οὐχ ὅσον ὡμολόγητο εἶχεν, ὦ ἄνδρες δικασταί, ἀλλὰ τρία τάλαντα ἀργυρίου καὶ τετρακοσίους κυζικηνοὺς καὶ ἑκατὸν δαρεικοὺς καὶ φιάλας ἀργυρᾶς τέτταρας, ἐδεόμην αὐτοῦ ἐφόδιά μοι δοῦναι,", "st": "12.11"}, {"sp": "N", "t": "ὁ δ’ ἀγαπήσειν με ἔφασκεν, εἰ τὸ σῶμα σώσω. ἐξιοῦσι δ’ ἐμοὶ καὶ Πείσωνι ἐπιτυγχάνει Μηλόβιός τε καὶ Μνησιθείδης ἐκ τοῦ ἐργαστηρίου ἀπιόντες, καὶ καταλαμβάνουσι πρὸς αὐταῖς ταῖς θύραις, καὶ ἐρωτῶσιν ὅποι βαδίζοιμεν· ὁ δ’ ἔφασκεν εἰς ⟨τὰ⟩ τοῦ ἀδελφοῦ τοῦ ἐμοῦ, ἵνα καὶ τὰ ἐν ἐκείνῃ τῇ οἰκίᾳ σκέψηται. ἐκεῖνον μὲν οὖν ἐκέλευον βαδίζειν, ἐμὲ δὲ μεθ’ αὑτῶν ἀκολουθεῖν εἰς Δαμνίππου.", "st": "12.12"}, {"sp": "N", "t": "πείσων δὲ προσελθὼν σιγᾶν μοι παρεκελεύετο καὶ θαρρεῖν, ὡς ἥξων ἐκεῖσε. καταλαμβάνομεν δὲ αὐτόθι Θέογνιν ἑτέρους φυλάττοντα· ᾧ παραδόντες ἐμὲ πάλιν ᾤχοντο. ἐν τοιούτῳ δ’ ὄντι μοι κινδυνεύειν ἐδόκει, ὡς τοῦ γε ἀποθανεῖν ὑπάρχοντος ἤδη.", "st": "12.13"}, {"sp": "N", "t": "καλέσας δὲ Δάμνιππον λέγω πρὸς αὐτὸν τάδε, “ἐπιτήδειος μέν μοι τυγχάνεις ὤν, ἥκω δ’ εἰς τὴν σὴν οἰκίαν, ἀδικῶ δ’ οὐδέν, χρημάτων δ’ ἕνεκα ἀπόλλυμαι. σὺ οὖν ταῦτα πάσχοντί μοι πρόθυμον παράσχου τὴν σεαυτοῦ δύναμιν εἰς τὴν ἐμὴν σωτηρίαν.” ὁ δ’ ὑπέσχετο ταῦτα ποιήσειν. ἐδόκει δ’ αὐτῷ βέλτιον εἶναι πρὸς Θέογνιν μνησθῆναι· ἡγεῖτο γὰρ ἅπαν ποιήσειν αὐτόν,", "st": "12.14"}, {"sp": "N", "t": "εἴ τις ἀργύριον διδοίη. ἐκείνου δὲ διαλεγομένου Θεόγνιδι (ἔμπειρος γὰρ ὢν ἐτύγχανον τῆς οἰκίας, καὶ ᾔδη ὅτι ἀμφίθυρος εἴη) ἐδόκει μοι ταύτῃ πειρᾶσθαι σωθῆναι, ἐνθυμουμένῳ ὅτι, ἐὰν μὲν λάθω, σωθήσομαι, ἐὰν δὲ ληφθῶ, ἡγούμην μέν, εἰ Θέογνις εἴη πεπεισμένος ὑπὸ τοῦ Δαμνίππου χρήματα λαβεῖν, οὐδὲν ἧττον ἀφεθήσεσθαι, εἰ δὲ μή,", "st": "12.15"}, {"sp": "N", "t": "ὁμοίως ἀποθανεῖσθαι. ταῦτα διανοηθεὶς ἔφευγον, ἐκείνων ἐπὶ τῇ αὐλείῳ θύρᾳ τὴν φυλακὴν ποιουμένων· τριῶν δὲ θυρῶν οὐσῶν, ἃς ἔδει με διελθεῖν, ἅπασαι ἀνεῳγμέναι ἔτυχον. ἀφικόμενος δὲ εἰς Ἀρχένεω τοῦ ναυκλήρου ἐκεῖνον πέμπω εἰς ἄστυ, πευσόμενον περὶ τοῦ ἀδελφοῦ· ἥκων δὲ ἔλεγεν ὅτι Ἐρατοσθένης αὐτὸν ἐν τῇ ὁδῷ λαβὼν εἰς τὸ δεσμωτήριον ἀπαγάγοι.", "st": "12.16"}, {"sp": "N", "t": "καὶ ἐγὼ τοιαῦτα πεπυσμένος τῆς ἐπιούσης νυκτὸς διέπλευσα Μέγαράδε. πολεμάρχῳ δὲ παρήγγειλαν οἱ τριάκοντα τοὐπ’ ἐκείνων εἰθισμένον παράγγελμα, πίνειν κώνειον, πρὶν τὴν αἰτίαν εἰπεῖν δι’ ἥντινα ἔμελλεν ἀποθανεῖσθαι· οὕτω πολλοῦ ἐδέησε κριθῆναι καὶ ἀπολογήσασθαι.", "st": "12.17"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἀπεφέρετο ἐκ τοῦ δεσμωτηρίου τεθνεώς, τριῶν ἡμῖν οἰκιῶν οὐσῶν ⟨ἐξ⟩ οὐδεμιᾶς εἴασαν ἐξενεχθῆναι, ἀλλὰ κλεισίον μισθωσάμενοι προὔθεντο αὐτόν. καὶ πολλῶν ὄντων ἱματίων αἰτοῦσιν οὐδὲν ἔδοσαν εἰς τὴν ταφήν, ἀλλὰ τῶν φίλων ὁ μὲν ἱμάτιον, ὁ δὲ προσκεφάλαιον, ὁ δὲ ὅ τι ἕκαστος ἔτυχεν ἔδωκεν εἰς τὴν ἐκείνου ταφήν.", "st": "12.18"}, {"sp": "N", "t": "καὶ ἔχοντες μὲν ἑπτακοσίας ἀσπίδας τῶν ἡμετέρων, ἔχοντες δὲ ἀργύριον καὶ χρυσίον τοσοῦτον, χαλκὸν δὲ καὶ κόσμον καὶ ἔπιπλα καὶ ἱμάτια γυναικεῖα ὅσα οὐδεπώποτε ᾤοντο κτήσεσθαι, καὶ ἀνδράποδα εἴκοσι καὶ ἑκατόν, ὧν τὰ μὲν βέλτιστα ἔλαβον, τὰ δὲ λοιπὰ εἰς τὸ δημόσιον ἀπέδοσαν, εἰς τοσαύτην ἀπληστίαν καὶ αἰσχροκέρδειαν ἀφίκοντο καὶ τοῦ τρόπου τοῦ αὑτῶν ἀπόδειξιν ἐποιήσαντο· τῆς γὰρ Πολεμάρχου γυναικὸς χρυσοῦς ἑλικτῆρας, οὓς ἔχουσα ἐτύγχανεν,", "st": "12.19"}, {"sp": "N", "t": "ὅτε τὸ πρῶτον ἦλθεν εἰς τὴν οἰκίαν Μηλόβιος ἐκ τῶν ὤτων ἐξείλετο. καὶ οὐδὲ κατὰ τὸ ἐλάχιστον μέρος τῆς οὐσίας ἐλέου παρ’ αὐτῶν ἐτυγχάνομεν. ἀλλ’ οὕτως εἰς ἡμᾶς διὰ τὰ χρήματα ἐξημάρτανον, ὥσπερ ἂν ἕτεροι μεγάλων ἀδικημάτων ὀργὴν ἔχοντες, οὐ τούτων ἀξίους γε ὄντας τῇ πόλει, ἀλλὰ πάσας ⟨μὲν⟩ τὰς χορηγίας χορηγήσαντας, πολλὰς δ’ εἰσφορὰς εἰσενεγκόντας, κοσμίους δ’ ἡμᾶς αὐτοὺς παρέχοντας καὶ πᾶν τὸ προσταττόμενον ποιοῦντας, ἐχθρὸν δ’ οὐδένα κεκτημένους, πολλοὺς δ’ Ἀθηναίων ἐκ τῶν πολεμίων λυσαμένους· τοιούτων ἠξίωσαν οὐχ ὁμοίως μετοικοῦντας ὥσπερ αὐτοὶ ἐπολιτεύοντο.", "st": "12.20"}, {"sp": "N", "t": "οὗτοι γὰρ πολλοὺς μὲν τῶν πολιτῶν εἰς τοὺς πολεμίους ἐξήλασαν, πολλοὺς δ’ ἀδίκως ἀποκτείναντες ἀτάφους ἐποίησαν, πολλοὺς δ’ ἐπιτίμους ὄντας ἀτίμους [τῆς πόλεως] κατέστησαν, πολλῶν δὲ θυγατέρας μελλούσας ἐκδίδοσθαι ἐκώλυσαν.", "st": "12.21"}, {"sp": "N", "t": "καὶ εἰς τοσοῦτόν εἰσι τόλμης ἀφιγμένοι ὥσθ’ ἥκουσιν ἀπολογησόμενοι, καὶ λέγουσιν ὡς οὐδὲν κακὸν οὐδ’ αἰσχρὸν εἰργασμένοι εἰσίν. ἐγὼ δ’ ἐβουλόμην ἂν αὐτοὺς ἀληθῆ λέγειν· μετῆν γὰρ ἂν καὶ ἐμοὶ τούτου τἀγαθοῦ οὐκ ἐλάχιστον μέρος.", "st": "12.22"}, {"sp": "N", "t": "νῦν δὲ οὔτε πρὸς τὴν πόλιν αὐτοῖς τοιαῦτα ὑπάρχει οὔτε πρὸς ἐμέ· τὸν ἀδελφὸν γὰρ μου, ὥσπερ καὶ πρότερον εἶπον, Ἐρατοσθένης ἀπέκτεινεν, οὔτε αὐτὸς ἰδίᾳ ἀδικούμενος οὔτε εἰς τὴν πόλιν ὁρῶν ἐξαμαρτάνοντα, ἀλλὰ τῇ ἑαυτοῦ παρανομία προθύμως ἐξυπηρετῶν.", "st": "12.23"}, {"sp": "N", "t": "ἀναβιβασάμενος δ’ αὐτὸν βούλομαι ἐρέσθαι, ὦ ἄνδρες δικασταί. τοιαύτην γὰρ γνώμην ἔχω· ἐπὶ μὲν τῇ τούτου ὠφελείᾳ καὶ πρὸς ἕτερον περὶ τούτου διαλέγεσθαι ἀσεβὲς εἶναι νομίζω, ἐπὶ δὲ τῇ τούτου βλάβῃ καὶ πρὸς αὐτὸν τοῦτον ὅσιον καὶ εὐσεβές. ἀνάβηθι οὖν μοι καὶ ἀπόκριναι, ὅ τι ἄν σε ἐρωτῶ.", "st": "12.24"}, {"sp": "N", "t": "ἀπήγαγες Πολέμαρχον ἢ οὔ; “τὰ ὑπὸ τῶν ἀρχόντων προσταχθέντα δεδιὼς ἐποίουν.” ἦσθα δ’ ἐν τῷ βουλευτηρίῳ, ὅτε οἱ λόγοι ἐγίγνοντο περὶ ἡμῶν; “ἦ.” πότερον συνηγόρευες τοῖς κελεύουσιν ἀποκτεῖναι ἢ ἀντέλεγες; “ἀντέλεγον.” ἵνα μὴ ἀποθάνωμεν; “ἵνα μὴ ἀποθάνητε.” ἡγούμενος ἡμᾶς ἄδικα πάσχειν ἢ δίκαια; “ἄδικα.”", "st": "12.25"}, {"sp": "N", "t": "εἶτ’, ὦ σχετλιώτατε πάντων, ἀντέλεγες μὲν ἵνα σώσειας, συνελάμβανες δὲ ἵνα ἀποκτείνῃς; καὶ ὅτε μὲν τὸ πλῆθος ἦν ὑμῶν κύριον τῆς σωτηρίας τῆς ἡμετέρας, ἀντιλέγειν φῂς τοῖς βουλομένοις ἡμᾶς ἀπολέσαι, ἐπειδὴ δὲ ἐπὶ σοὶ μόνῳ ἐγένετο καὶ σῶσαι Πολέμαρχον καὶ μή, εἰς τὸ δεσμωτήριον ἀπήγαγες; εἶθ’ ὅ μέν, ὡς φῄς, ἀντειπὼν οὐδὲν ὠφέλησας, ἀξιοῖς χρηστὸς νομίζεσθαι, ὅτι δὲ συλλαβὼν ἀπέκτεινας, οὐκ [οἴει] ἐμοὶ καὶ τουτοισὶ δοῦναι δίκην;", "st": "12.26"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τοῦτο εἰκὸς αὐτῷ πιστεύειν, εἴπερ ἀληθῆ λέγει φάσκων ἀντειπεῖν, ὡς αὐτῷ προσετάχθη. οὐ γὰρ δήπου ἐν τοῖς μετοίκοις πίστιν παρ’ αὐτοῦ ἐλάμβανον. ἔπειτα τῷ ἧττον εἰκὸς ἦν προσταχθῆναι ἢ ὅστις ἀντειπών γε ἐτύγχανε καὶ γνώμην ἀποδεδειγμένος; τίνα γὰρ εἰκὸς ἦν ἧττον ταῦτα ὑπηρετῆσαι ἢ τὸν ἀντειπόντα οἷς ἐκεῖνοι ἐβούλοντο πραχθῆναι;", "st": "12.27"}, {"sp": "N", "t": "ἔτι δὲ τοῖς μὲν ἄλλοις Ἀθηναίοις ἱκανή μοι δοκεῖ πρόφασις εἶναι τῶν γεγενημένων εἰς τοὺς τριάκοντα ἀναφέρειν τὴν αἰτίαν· αὐτοὺς δὲ τοὺς τριάκοντα, ἐὰν εἰς σφᾶς αὐτοὺς ἀναφέρωσι, πῶς ὑμᾶς εἰκὸς ἀποδέχεσθαι;", "st": "12.28"}, {"sp": "N", "t": "εἰ μὲν γάρ τις ἦν ἐν τῇ πόλει ἀρχὴ ἰσχυροτέρα [αὐτῆς], ὑφ’ ἧς αὐτῷ προσετάττετο παρὰ τὸ δίκαιον ἀνθρώπους ἀπολλύναι, ἴσως ἂν εἰκότως αὐτῷ συγγνώμην εἴχετε· νῦν δὲ παρὰ τοῦ ποτε καὶ λήψεσθε δίκην, εἴπερ ἐξέσται τοῖς τριάκοντα λέγειν ὅτι τὰ ὑπὸ τῶν τριάκοντα προσταχθέντα ἐποίουν;", "st": "12.29"}, {"sp": "N", "t": "καὶ μὲν δὴ οὐκ ἐν τῇ οἰκία ἀλλ’ ἐν τῇ ὁδῷ, σῴζειν τε αὐτὸν καὶ τὰ τούτοις ἐψηφισμένα παρόν, συλλαβὼν ἀπήγαγεν. ὑμεῖς δὲ πᾶσιν ὀργίζεσθε, ὅσοι εἰς τὰς οἰκίας ἦλθον τὰς ὑμετέρας ζήτησιν ποιούμενοι ἢ ὑμῶν ἢ τῶν ὑμετέρων τινός.", "st": "12.30"}, {"sp": "N", "t": "καίτοι εἰ χρὴ τοῖς διὰ τὴν ἑαυτῶν σωτηρίαν ἑτέρους ἀπολέσασι συγγνώμην ἔχειν, ἐκείνοις ἂν δικαιότερον ἔχοιτε· κίνδυνος γὰρ ἦν πεμφθεῖσι μὴ ἐλθεῖν καὶ καταλαβοῦσιν ἐξάρνοις γενέσθαι. τῷ δὲ Ἐρατοσθένει ἐξῆν εἰπεῖν ὅτι οὐκ ἀπήντησεν, ἔπειτα ὅτι οὐκ εἶδεν· ταῦτα γὰρ οὔτ’ ἔλεγχον οὔτε βάσανον εἶχεν, ὥστε μηδ’ ὑπὸ τῶν ἐχθρῶν βουλομένων οἷόν τ’ εἶναι ἐξελεγχθῆναι.", "st": "12.31"}, {"sp": "N", "t": "χρῆν δέ σε, ὦ Ἐρατόσθενες, εἴπερ ἦσθα χρηστός, πολὺ μᾶλλον τοῖς μέλλουσιν ἀδίκως ἀποθανεῖσθαι μηνυτὴν γενέσθαι ἢ τοὺς ἀδίκως ἀπολουμένους συλλαμβάνειν. νῦν δέ σου τὰ ἔργα φανερὰ γεγένηται οὐχ ὡς ἀνιωμένου ἀλλ’ ὡς ἡδομένου τοῖς γιγνομένοις,", "st": "12.32"}, {"sp": "N", "t": "ὥστε τούσδε ἐκ τῶν ἔργων χρὴ μᾶλλον ἢ ἐκ τῶν λόγων τὴν ψῆφον φέρειν, ἃ ἴσασι γεγενημένα τῶν τότε λεγομένων τεκμήρια λαμβάνοντας, ἐπειδὴ μάρτυρας περὶ αὐτῶν οὐχ οἷόν τε παρασχέσθαι. οὐ γὰρ μόνον ἡμῖν παρεῖναι οὐκ ἐξῆν, ἀλλ’ οὐδὲ παρ’ αὑτοῖς εἶναι, ὥστ’ ἐπὶ τούτοις ἐστὶ πάντα τὰ κακὰ εἰργασμένοις τὴν πόλιν πάντα τἀγαθὰ περὶ αὑτῶν λέγειν.", "st": "12.33"}, {"sp": "N", "t": "τοῦτο μέντοι οὐ φεύγω, ἀλλ’ ὁμολογῶ σοι, εἰ βούλει, ἀντειπεῖν. θαυμάζω δὲ τί ἄν ποτ’ ἐποίησας συνειπών, ὁπότε ἀντειπεῖν φάσκων ἀπέκτεινας Πολέμαρχον.", "st": "12.34"}, {"sp": "N", "t": "φέρε δή, τί ἄν, εἰ καὶ ἀδελφοὶ ὄντες ἐτύχετε αὐτοῦ ἢ καὶ ὑεῖς; ἀπεψηφίσασθε; δεῖ γάρ, ὦ ἄνδρες δικασταί, Ἐρατοσθένην δυοῖν θάτερον ἀποδεῖξαι, ἢ ὡς οὐκ ἀπήγαγεν αὐτόν, ἢ ὡς δικαίως τοῦτ’ ἔπραξεν. οὗτος δὲ ὡμολόγηκεν ἀδίκως συλλαβεῖν, ὥστε ῥᾳδίαν ὑμῖν τὴν διαψήφισιν περὶ αὑτοῦ πεποίηκε.", "st": "12.34"}, {"sp": "N", "t": "καὶ μὲν δὴ πολλοὶ καὶ τῶν ἀστῶν καὶ τῶν ξένων ἥκουσιν εἰσόμενοι τίνα γνώμην περὶ τούτων ἕξετε. ὧν οἱ μὲν ὑμέτεροι ὄντες πολῖται μαθόντες ἀπίασιν ὅτι ἢ δίκην δώσουσιν ὧν ἂν ἐξαμάρτωσιν, ἢ πράξαντες μὲν ὧν ἐφίενται τύραννοι τῆς πόλεως ἔσονται, δυστυχήσαντες δὲ τὸ ἴσον ὑμῖν ἕξουσιν· ὅσοι δὲ ξένοι ἐπιδημοῦσιν, εἴσονται πότερον ἀδίκως τοὺς τριάκοντα ἐκκηρύττουσιν ἐκ τῶν πόλεων ἢ δικαίως. εἰ γὰρ δὴ αὐτοὶ οἱ κακῶς πεπονθότες λαβόντες ἀφήσουσιν, ἦ που σφᾶς ⟨γ’⟩ αὐτοὺς ἡγήσονται περιέργους ὑπὲρ ὑμῶν τηρουμένους.", "st": "12.35"}, {"sp": "N", "t": "οὐκ οὖν δεινὸν εἰ τοὺς μὲν στρατηγούς, οἳ ἐνίκων ναυμαχοῦντες, ὅτε διὰ χειμῶνα οὐχ οἷοί τ’ ἔφασαν εἶναι τοὺς ἐκ τῆς θαλάττης ἀνελέσθαι, θανάτῳ ἐζημιώσατε, ἡγούμενοι χρῆναι τῇ τῶν τεθνεώτων ἀρετῇ παρ’ ἐκείνων δίκην λαβεῖν, τούτους δέ, οἳ ἰδιῶται μὲν ὄντες καθ’ ὅσον ἐδύναντο ἐποίησαν ἡττηθῆναι ναυμαχοῦντας, ἐπειδὴ δὲ εἰς τὴν ἀρχὴν κατέστησαν, ὁμολογοῦσιν ἑκόντες πολλοὺς τῶν πολιτῶν ἀκρίτους ἀποκτιννύναι, οὐκ ἄρα χρὴ αὐτοὺς καὶ τοὺς παῖδας ὑφ’ ὑμῶν ταῖς ἐσχάταις ζημίαις κολάζεσθαι;", "st": "12.36"}, {"sp": "N", "t": "ἐγὼ τοίνυν, ὦ ἄνδρες δικασταί, ἠξίουν ἱκανὰ εἶναι τὰ κατηγορημένα· μέχρι γὰρ τούτου νομίζω χρῆναι κατηγορεῖν, ἕως ἂν θανάτου δόξῃ τῷ φεύγοντι ἄξια εἰργάσθαι. ταύτην γὰρ ἐσχάτην δίκην δυνάμεθα παρ’ αὐτῶν λαβεῖν. ὥστ’ οὐκ οἶδ’ ὅ τι δεῖ πολλὰ κατηγορεῖν τοιούτων ἀνδρῶν, οἳ οὐδ’ ὑπὲρ ἑνὸς ἑκάστου τῶν πεπραγμένων δὶς ἀποθανόντες δίκην δοῦναι δύναιντ’ ἂν ⟨ἀξίαν⟩. οὐ γὰρ δὴ οὐδὲ τοῦτο αὐτῷ προσήκει ποιῆσαι,", "st": "12.37"}, {"sp": "N", "t": "ὅπερ ἐν τῇδε τῇ πόλει εἰθισμένον ἐστί, πρὸς μὲν τὰ κατηγορημένα μηδὲν ἀπολογεῖσθαι, περὶ δὲ σφῶν αὐτῶν ἕτερα λέγοντες ἐνίοτε ἐξαπατῶσιν, ὑμῖν ἀποδεικνύντες ὡς στρατιῶται ἀγαθοί εἰσιν, ἢ ὡς πολλὰς τῶν πολεμίων ναῦς ἔλαβον τριηραρχήσαντες, ⟨ἢ⟩ πόλεις πολεμίας οὔσας φίλας", "st": "12.38"}, {"sp": "N", "t": "ἐποίησαν· ἐπεὶ κελεύετε αὐτὸν ἀποδεῖξαι ὅπου τοσούτους τῶν πολεμίων ἀπέκτειναν ὅσους τῶν πολιτῶν, ἢ ναῦς ὅπου τοσαύτας ἕσας αὐτοὶ παρέδοσαν, ἢ πόλιν ἥντινα τοιαύτην προσεκτήσαντο οἵαν τὴν ὑμετέραν κατεδουλώσαντο.", "st": "12.39"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὅπλα τῶν πολεμίων ⟨τοσαῦτα⟩ ἐσκύλευσαν ὅσα περ ὑμῶν ἀφείλοντο, ἀλλὰ τείχη τοιαῦτα εἷλον οἷα τῆς ἑαυτῶν πατρίδος κατέσκαψαν; οἵτινες καὶ τὰ περὶ τὴν Ἀττικὴν φρούρια καθεῖλον, καὶ ὑμῖν ἐδήλωσαν ὅτι οὐδὲ τὸν Πειραιᾶ Λακεδαιμονίων προσταττόντων περιεῖλον, ἀλλ’ ὅτι ἑαυτοῖς τὴν ἀρχὴν οὕτω βεβαιοτέραν ἐνόμιζον εἶναι.", "st": "12.40"}, {"sp": "N", "t": "πολλάκις οὖν ἐθαύμασα τῆς τόλμης τῶν λεγόντων ὑπὲρ αὐτοῦ, πλὴν ὅταν ἐνθυμηθῶ ὅτι τῶν αὐτῶν ἐστιν αὐτούς τε πάντα τὰ κακὰ ἐργάζεσθαι καὶ τοὺς τοιούτους ἐπαινεῖν.", "st": "12.41"}, {"sp": "N", "t": "οὐ γὰρ νῦν πρῶτον τῷ ὑμετέρῳ πλήθει τὰ ἐναντία ἔπραξεν, ἀλλὰ καὶ ἐπὶ τῶν τετρακοσίων ἐν τῷ στρατοπέδῳ ὀλιγαρχίαν καθιστὰς ἔφευγεν ἐξ Ἑλλησπόντου τριήραρχος καταλιπὼν τὴν ναῦν, μετὰ Ἰατροκλέους καὶ ἑτέρων, ὧν τὰ ὀνόματα οὐδὲν δέομαι λέγειν. ἀφικόμενος δὲ δεῦρο τἀναντία τοῖς βουλομένοις δημοκρατίαν εἶναι ἔπραττε. καὶ τούτων μάρτυρας ὑμῖν παρέξομαι.", "st": "12.42"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "12.43"}, {"sp": "N", "t": "τὸν μὲν τοίνυν μεταξὺ βίον αὐτοῦ παρήσω· ἐπειδὴ δὲ ἡ ναυμαχία καὶ ἡ συμφορὰ τῇ πόλει ἐγένετο, δημοκρατίας ἔτι οὔσης, ὅθεν τῆς στάσεως ἦρξαν, πέντε ἄνδρες ἔφοροι κατέστησαν ὑπὸ τῶν καλουμένων ἑταίρων, συναγωγεῖς μὲν τῶν πολιτῶν ἄρχοντες δὲ τῶν συνωμοτῶν, ἐναντία δὲ τῷ ὑμετέρῳ πλήθει πράττοντες· ὧν Ἐρατοσθένης καὶ Κριτίας ἦσαν.", "st": "12.43"}, {"sp": "N", "t": "οὗτοι δὲ φυλάρχους τε ἐπὶ τὰς φυλὰς κατέστησαν, καὶ ὅ τι δέοι χειροτονεῖσθαι καὶ οὕστινας χρείη ἄρχειν παρήγγελλον, καὶ εἴ τι ἄλλο πράττειν βούλοιντο, κύριοι ἦσαν· οὕτως οὐχ ὑπὸ τῶν πολεμίων μόνον ἀλλὰ καὶ ὑπὸ τούτων πολιτῶν ὄντων ἐπεβουλεύεσθε ὅπως μήτ’ ἀγαθὸν μηδὲν ψηφιεῖσθε πολλῶν τε ἐνδεεῖς ἔσεσθε.", "st": "12.44"}, {"sp": "N", "t": "τοῦτο γὰρ καλῶς ἠπίσταντο, ὅτι ἄλλως μὲν οὐχ οἷοί τε ἔσονται περιγενέσθαι, κακῶς δὲ πραττόντων δυνήσονται· καὶ ὑμᾶς ἡγοῦντο τῶν παρόντων κακῶν ἐπιθυμοῦντας ἀπαλλαγῆναι περὶ τῶν μελλόντων οὐκ ἐνθυμήσεσθαι.", "st": "12.45"}, {"sp": "N", "t": "ὡς τοίνυν τῶν ἐφόρων ἐγένετο, μάρτυρας ὑμῖν παρέξομαι, οὐ τοὺς τότε συμπράττοντας (οὐ γὰρ ἂν δυναίμην), ἀλλὰ τοὺς αὐτοῦ Ἐρατοσθένους ἀκούσαντας.", "st": "12.46"}, {"sp": "N", "t": "καίτοι εἰ ἐσωφρόνουν κατεμαρτύρουν ἂν αὐτῶν, καὶ τοὺς διδασκάλους τῶν σφετέρων ἁμαρτημάτων σφόδρ’ ἂν ἐκόλαζον, καὶ τοὺς ὅρκους, εἰ ἐσωφρόνουν, οὐκ ἂν ἐπὶ μὲν τοῖς τῶν πολιτῶν κακοῖς πιστοὺς ἐνόμιζον, ἐπὶ δὲ τοῖς τῆς πόλεως ἀγαθοῖς ῥᾳδίως παρέβαινον· πρὸς μὲν οὖν τούτους τοσαῦτα λέγω, τοὺς δὲ μάρτυράς μοι κάλει. καὶ ὑμεῖς ἀνάβητε.", "st": "12.47"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "12.48"}, {"sp": "N", "t": "τῶν μὲν μαρτύρων ἀκηκόατε. τὸ δὲ τελευταῖον εἰς τὴν ἀρχὴν καταστὰς ἀγαθοῦ μὲν οὐδενὸς μετέσχεν, ἄλλων δὲ πολλῶν. καίτοι εἴπερ ἦν ἀνὴρ ἀγαθός, ἐχρῆν αὐτὸν πρῶτον μὲν μὴ παρανόμως ἄρχειν, ἔπειτα τῇ βουλῇ μηνυτὴν γίγνεσθαι περὶ τῶν εἰσαγγελιῶν ἁπασῶν, ὅτι ψευδεῖς εἶεν, καὶ Βάτραχος καὶ Αἰσχυλίδης οὐ τἀληθῆ μηνύουσιν, ἀλλὰ τὰ ὑπὸ τῶν τριάκοντα πλασθέντα εἰσαγγέλλουσι, συγκείμενα ἐπὶ τῇ τῶν πολιτῶν βλάβῃ.", "st": "12.48"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, ὅσοι κακόνοι ἦσαν τῷ ὑμετέρῳ πλήθει, οὐδὲν ἔλαττον εἶχον σιωπῶντες· ἕτεροι γὰρ ἦσαν οἱ λέγοντες καὶ πράττοντες ὧν οὐχ οἷόν τ’ ἦν μείζω κακὰ γενέσθαι τῇ πόλει. ὁπόσοι δ’ εὖνοί φασιν εἶναι, πῶς οὐκ ἐνταῦθα ἔδειξαν, αὐτοί τε τὰ βέλτιστα λέγοντες καὶ τοὺς ἐξαμαρτάνοντας ἀποτρέποντες;", "st": "12.49"}, {"sp": "N", "t": "ἴσως δ’ ἂν ἔχοι εἰπεῖν ὅτι ἐδεδοίκει, καὶ ὑμῶν τοῦτο ἐνίοις ἱκανὸν ἔσται. ὅπως τοίνυν μὴ φανήσεται ἐν τῷ λόγῳ τοῖς τριάκοντα ἐναντιούμενος· εἰ δὲ μή, ἐνταυθοῖ δῆλος ἔσται ὅτι ἐκεῖνά τε αὐτῷ ἤρεσκε, καὶ τοσοῦτον ἐδύνατο ὥστε ἐναντιούμενος μηδὲν κακὸν παθεῖν ὑπ’ αὐτῶν. χρῆν δ’ αὐτὸν ὑπὲρ τῆς ὑμετέρας σωτηρίας ταύτην τὴν προθυμίαν ἔχειν, ἀλλὰ μὴ ὑπὲρ Θηραμένους, ὃς εἰς ὑμᾶς πολλὰ ἐξήμαρτεν.", "st": "12.50"}, {"sp": "N", "t": "ἀλλ’ οὗτος τὴν μὲν πόλιν ἐχθρὰν ἐνόμιζεν εἶναι, τοὺς δ’ ὑμετέρους ἐχθροὺς φίλους, ὡς ἀμφότερα ταῦτα ἐγὼ πολλοῖς τεκμηρίοις παραστήσω, καὶ τὰς πρὸς ἀλλήλους διαφορὰς οὐχ ὑπὲρ ὑμῶν ἀλλ’ ὑπὲρ ἑαυτῶν γιγνομένας, ὁπότεροι τὰ πράγματα πράξουσι καὶ τῆς πόλεως ἄρξουσιν.", "st": "12.51"}, {"sp": "N", "t": "εἰ γὰρ ὑπὲρ τῶν ἀδικουμένων ἐστασίαζον, ποῦ κάλλιον ἦν ἀνδρὶ ἄρχοντι, ἢ Θρασυβούλου Φυλὴν κατειληφότος, τότε ἐπιδείξασθαι τὴν αὑτοῦ εὔνοιαν; ὁ δ’ ἀντὶ τοῦ ἐπαγγείλασθαί τι ἢ πρᾶξαι ἀγαθὸν πρὸς τοὺς ἐπὶ Φυλῇ, ἐλθὼν μετὰ τῶν συναρχόντων εἰς Σαλαμῖνα καὶ Ἐλευσῖνάδε τριακοσίους τῶν πολιτῶν ἀπήγαγεν εἰς τὸ δεσμωτήριον, καὶ μιᾷ ψήφῳ αὐτῶν ἁπάντων θάνατον κατεψηφίσατο.", "st": "12.52"}, {"sp": "N", "t": "ἐπειδὴ δὲ εἰς τὸν Πειραιᾶ ἤλθομεν καὶ αἱ ταραχαὶ γεγενημέναι ἦσαν καὶ περὶ τῶν διαλλαγῶν οἱ λόγοι ἐγίγνοντο, πολλὰς ἑκάτεροι ἐλπίδας εἴχομεν πρὸς ἀλλήλους ἔσεσθαι, ὡς ἀμφότεροι ἔδειξαν. οἱ μὲν γὰρ ἐκ Πειραιῶς κρείττους ὄντες εἴασαν", "st": "12.53"}, {"sp": "N", "t": "αὐτοὺς ἀπελθεῖν· οἱ δὲ εἰς τὸ ἄστυ ἐλθόντες τοὺς μὲν τριάκοντα ἐξέβαλον πλὴν Φείδωνος καὶ Ἐρατοσθένους, ἄρχοντας δὲ τοὺς ἐκείνοις ἐχθίστους εἵλοντο, ἡγούμενοι δικαίως ἂν ὑπὸ τῶν αὐτῶν τούς τε τριάκοντα μισεῖσθαι καὶ τοὺς ἐν Πειραιεῖ φιλεῖσθαι.", "st": "12.54"}, {"sp": "N", "t": "τούτων τοίνυν Φείδων [ὁ τῶν τριάκοντα] γενόμενος καὶ Ἱπποκλῆς καὶ Ἐπιχάρης ὁ Λαμπτρεὺς καὶ ἕτεροι οἱ δοκοῦντες εἶναι ἐναντιώτατοι Χαρικλεῖ καὶ Κριτίᾳ καὶ τῇ ἐκείνων ἑταιρεία, ἐπειδή αὐτοὶ εἰς τὴν ἀρχὴν κατέστησαν, πολὺ μείζω στάσιν καὶ πόλεμον ἐπὶ τοὺς ἐν Πειραιεῖ [ἢ] τοῖς ἐξ ἄστεως ἐποίησαν.", "st": "12.55"}, {"sp": "N", "t": "ᾧ καὶ φανερῶς ἐπεδείξαντο ὅτι οὐχ ὑπὲρ τῶν ἐν Πειραιεῖ οὐδ’ ὑπὲρ τῶν ἀδίκως ἀπολλυμένων ἐστασίαζον, οὐδ’ οἱ τεθνεῶτες αὐτοὺς ἐλύπουν οὐδ’ οἱ μέλλοντες ἀποθανεῖσθαι, ἀλλ’ οἱ μεῖζον δυνάμενοι καὶ θᾶττον πλουτοῦντες.", "st": "12.56"}, {"sp": "N", "t": "λαβόντες γὰρ τὰς ἀρχὰς καὶ τὴν πόλιν ἀμφοτέροις ἐπολέμουν, τοῖς τε τριάκοντα πάντα κακὰ εἰργασμένοις καὶ ὑμῖν πάντα κακὰ πεπονθόσι. καίτοι τοῦτο πᾶσι δῆλον ἦν, ὅτι εἰ μὲν ἐκεῖνοι δικαίως ἔφευγον, ὑμεῖς ἀδίκως, εἰ δ’ ὑμεῖς δικαίως, οἱ τριάκοντα ἀδίκως· οὐ γὰρ δὴ ἑτέρων ἔργων αἰτίαν λαβόντες ἐκ τῆς πόλεως ἐξέπεσον,", "st": "12.57"}, {"sp": "N", "t": "ἀλλὰ τούτων. ὥστε σφόδρα χρὴ ὀργίζεσθαι, ὅτι Φείδων αἱρεθεὶς ὑμᾶς διαλλάξαι καὶ καταγαγεῖν τῶν αὐτῶν ἔργων Ἐρατοσθένει μετεῖχε καὶ τῇ αὐτῇ γνώμῃ τοὺς μὲν κρείττους αὑτῶν δι’ ὑμᾶς κακῶς ποιεῖν ἕτοιμος ἦν, ὑμῖν δὲ ἀδίκως φεύγουσιν οὐκ ἠθέλησεν ἀποδοῦναι τὴν πόλιν, ἀλλ’ ἐλθὼν εἰς Λακεδαίμονα ἔπειθεν αὐτοὺς στρατεύεσθαι, διαβάλλων ὅτι Βοιωτῶν ἡ πόλις ἔσται, καὶ ἄλλα λέγων οἷ ᾤετο πείσειν μάλιστα.", "st": "12.58"}, {"sp": "N", "t": "οὐ δυνάμενος δὲ τούτων τυχεῖν, εἴτε καὶ τῶν ἱερῶν ἐμποδὼν ὄντων εἴτε καὶ αὐτῶν οὐ βουλομένων, ἑκατὸν τάλαντα ἐδανείσατο, ἵνα ἔχοι ἐπικούρους μισθοῦσθαι, καὶ Λύσανδρον ἄρχοντα ᾐτήσατο, εὐνούστατον μὲν ὄντα τῇ ὀλιγαρχίᾳ, κακονούστατον δὲ τῇ πόλει, μισοῦντα δὲ μάλιστα τοὺς ἐν Πειραιεῖ.", "st": "12.59"}, {"sp": "N", "t": "μισθωσάμενοι δὲ πάντας ἀνθρώπους ἐπ’ ὀλέθρῳ τῆς πόλεως, καὶ πόλεις ἐπάγοντες, καὶ τελευτῶντες Λακεδαιμονίους καὶ τῶν συμμάχων ὁπόσους ἐδύναντο πεῖσαι, οὐ διαλλάξαι ἀλλ’ ἀπολέσαι παρεσκευάζοντο τὴν πόλιν εἰ μὴ δι’ ἄνδρας ἀγαθούς, οἷς ὑμεῖς δηλώσατε παρὰ τῶν ἐχθρῶν δίκην λαβόντες, ὅτι καὶ ἐκείνοις χάριν ἀποδώσετε.", "st": "12.60"}, {"sp": "N", "t": "ταῦτα δὲ ἐπίστασθε μὲν καὶ αὐτοί, καὶ ⟨οὐκ⟩ οἶδ’ ὅ τι δεῖ μάρτυρας παρασχέσθαι· ὅμως δέ· ἐγώ τε γὰρ δέομαι ἀναπαύσασθαι, ὑμῶν τ’ ἐνίοις ἥδιον ὡς πλείστων τοὺς αὐτοὺς λόγους ἀκούειν.", "st": "12.61"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "12.62"}, {"sp": "N", "t": "φέρε δὴ καὶ περὶ Θηραμένους ὡς ἂν δύνωμαι διὰ βραχυτάτων διδάξω. δέομαι δ’ ὑμῶν ἀκοῦσαι ὑπέρ τ’ ἐμαυτοῦ καὶ τῆς πόλεως, καὶ μηδενὶ τοῦτο παραστῇ, ὡς Ἐρατοσθένους κινδυνεύοντος Θηραμένους κατηγορῶ. πυνθάνομαι γὰρ ταῦτα ἀπολογήσεσθαι αὐτόν, ὅτι ἐκείνῳ φίλος ἦν καὶ τῶν αὐτῶν ἔργων μετεῖχε.", "st": "12.62"}, {"sp": "N", "t": "καίτοι σφόδρ’ ἂν αὐτὸν οἶμαι μετὰ Θεμιστοκλέους πολιτευόμενον προσποιεῖσθαι πράττειν ὅπως οἰκοδομηθήσεται τὰ τείχη, ὁπότε καὶ μετὰ Θηραμένους ὅπως καθαιρεθήσεται. οὐ γάρ μοι δοκοῦσιν ἴσου ἄξιοι γεγενῆσθαι· ὁ μὲν γὰρ Λακεδαιμονίων ἀκόντων ᾠκοδόμησεν αὐτά, οὗτος δὲ τοὺς πολίτας ἐξαπατήσας καθεῖλε.", "st": "12.63"}, {"sp": "N", "t": "περιέστηκεν οὖν τῇ πόλει τοὐναντίον ἢ ὡς εἰκὸς ἦν. ἄξιον μὲν γὰρ ⟨ἦν⟩ καὶ τοὺς φίλους τοὺς Θηραμένους προσαπολωλέναι, πλὴν εἴ τις ἐτύγχανεν ἐκείνῳ τἀναντία πράττων· νῦν δὲ ὁρῶ τάς τε ἀπολογίας εἰς ἐκεῖνον ἀναφερομένας, τούς τ’ ἐκείνῳ συνόντας τιμᾶσθαι πειρωμένους, ὥσπερ πολλῶν ἀγαθῶν αἰτίου ἀλλ’ οὐ μεγάλων κακῶν γεγενημένου.", "st": "12.64"}, {"sp": "N", "t": "ὃς πρῶτον μὲν τῆς προτέρας ὀλιγαρχίας αἰτιώτατος ἐγένετο, πείσας ὑμᾶς τὴν ἐπὶ τῶν τετρακοσίων πολιτείαν ἑλέσθαι. καὶ ὁ μὲν πατὴρ αὐτοῦ τῶν προβούλων ὢν ταὔτ’ ἔπραττεν, αὐτὸς δὲ δοκῶν εὐνούστατος εἶναι τοῖς πράγμασι στρατηγὸς ὑπ’ αὐτῶν ᾑρέθη.", "st": "12.65"}, {"sp": "N", "t": "καὶ ἕως μὲν ἐτιμᾶτο, πιστὸν ἑαυτὸν [τῇ πόλει] παρεῖχεν· ἐπειδὴ δὲ Πείσανδρον μὲν καὶ Κάλλαισχρον καὶ ἑτέρους ἑώρα προτέρους αὑτοῦ γιγνομένους, τὸ δὲ ὑμέτερον πλῆθος οὐκέτι βουλόμενον τούτων ἀκροᾶσθαι, τότ’ ἤδη διά τε τὸν πρὸς ἐκείνους φθόνον καὶ τὸ παρ’ ὑμῶν δέος μετέσχε τῶν Ἀριστοκράτους ἔργων.", "st": "12.66"}, {"sp": "N", "t": "βουλόμενος δὲ τῷ ὑμετέρῳ πλήθει δοκεῖν πιστὸς εἶναι Ἀντιφῶντα καὶ Ἀρχεπτόλεμον φιλτάτους ὄντας αὑτῷ κατηγορῶν ἀπέκτεινεν, εἰς τοσοῦτον δὲ κακίας ἦλθεν, ὥστε ἅμα μὲν διὰ τὴν πρὸς ἐκείνους πίστιν ὑμᾶς κατεδουλώσατο, διὰ δὲ τὴν πρὸς ὑμᾶς τοὺς φίλους ἀπώλεσε.", "st": "12.67"}, {"sp": "N", "t": "τιμώμενος δὲ καὶ τῶν μεγίστων ἀξιούμενος, αὐτὸς ἐπαγγειλάμενος σώσειν τὴν πόλιν αὐτὸς ἀπώλεσε, φάσκων πρᾶγμα ηὑρηκέναι μέγα καὶ πολλοῦ ἄξιον. ὑπέσχετο δὲ εἰρήνην ποιήσειν μήτε ὅμηρα δοὺς μήτε τὰ τείχη καθελὼν μήτε τὰς ναῦς παραδούς· ταῦτα δὲ εἰπεῖν μὲν οὐδενὶ ἠθέλησεν, ἐκέλευσε δὲ αὑτῷ πιστεύειν.", "st": "12.68"}, {"sp": "N", "t": "ὑμεῖς δέ, ὦ ἄνδρες Ἀθηναῖοι, πραττούσης μὲν τῆς ἐν Ἀρείπάγῳ βουλῆς σωτήρια, ἀντιλεγόντων δὲ πολλῶν Θηραμένει, εἰδότες δὲ ὅτι οἱ μὲν ἄλλοι ἄνθρωποι τῶν πολεμίων ἕνεκα τἀπόρρητα ποιοῦνται, ἐκεῖνος δ’ ἐν τοῖς αὑτοῦ πολίταις οὐκ ἠθέλησεν εἰπεῖν ταῦθ’ ἃ πρὸς τοὺς πολεμίους ἔμελλεν ἐρεῖν, ὅμως ἐπετρέψατε αὐτῷπατρίδα καὶ παῖδας καὶ γυναῖκας καὶ ὑμᾶς αὐτούς. ὁ δὲ ὧν μὲν ὑπέσχετο οὐδὲν ἔπραξεν,", "st": "12.69"}, {"sp": "N", "t": "οὕτως δὲ ἐνετεθύμητο ὡς χρὴ μικρὰν καὶ ἀσθενῆ γενέσθαι τὴν πόλιν, ὥστε περὶ ὧν οὐδεὶς πώποτε οὔτε τῶν πολεμίων ἐμνήσθη οὔτε τῶν πολιτῶν ἤλπισε, ταῦθ’ ὑμᾶς ἔπεισε πρᾶξαι, οὐχ ὑπὸ Λακεδαιμονίων ἀναγκαζόμενος, ἀλλ’ αὐτὸς ἐκείνοις ἐπαγγελλόμενος, τοῦ τε Πειραιῶς τὰ τείχη περιελεῖν καὶ τὴν ὑπάρχουσαν πολιτείαν καταλῦσαι, εὖ εἰδὼς ὅτι, εἰ μὴ πασῶν τῶν ἐλπίδων ἀποστερηθήσεσθε, ταχεῖαν παρ’ αὐτοῦ τὴν τιμωρίαν κομιεῖσθε.", "st": "12.70"}, {"sp": "N", "t": "καὶ τὸ τελευταῖον, ὦ ἄνδρες δικασταί, οὐ πρότερον εἴασε τὴν ἐκκλησίαν γενέσθαι, ἕως ὁ λεγόμενος ὑπ’ ἐκείνων καιρὸς ἐπιμελῶς ὑπ’ αὐτοῦ ἐτηρήθη, καὶ μετεπέμψατο μὲν τὰς μετὰ Λυσάνδρου ναῦς ἐκ Σάμου, ἐπεδήμησε δὲ τὸ τῶν πολεμίων στρατόπεδον.", "st": "12.71"}, {"sp": "N", "t": "τότε δὲ τούτων ὑπαρχόντων, καὶ παρόντος Λυσάνδρου καὶ Φιλοχάρους καὶ Μιλτιάδου, περὶ τῆς πολιτείας τὴν ἐκκλησίαν ἐποίουν, ἵνα μήτε ῥήτωρ αὐτοῖς μηδεὶς ἐναντιοῖτο μηδὲ διαπειλοῖτο ὑμεῖς τε μὴ τὰ τῆ πόλει συμφέροντα ἕλοισθε, ἀλλὰ τἀκείνοις δοκοῦντα ψηφίσαισθε.", "st": "12.72"}, {"sp": "N", "t": "ἀναστὰς δὲ Θηραμένης ἐκέλευσεν ὑμᾶς τριάκοντα ἀνδράσιν ἐπιτρέψαι τὴν πόλιν καὶ τῇ πολιτεία χρῆσθαι ἣν Δρακοντίδης ἀπέφαινεν. ὑμεῖς δ’ ὅμως καὶ οὕτω διακείμενοι ἐθορυβεῖτε ὡς οὐ ποιήσοντες ταῦτα· ἐγιγνώσκετε γὰρ ὅτι περὶ δουλείας καὶ ἐλευθερίας ἐν ἐκείνῃ τῇ ἡμέρα ἠκκλησιάζετε.", "st": "12.73"}, {"sp": "N", "t": "θηραμένης δέ, ὦ ἄνδρες δικασταί, (καὶ τούτων ὑμᾶς αὐτοὺς μάρτυρας παρέξομαι) εἶπεν ὅτι οὐδὲν αὐτῷ μέλοι τοῦ ὑμετέρου θορύβου, ἐπειδὴ πολλοὺς μὲν Ἀθηναίων εἰδείη τοὺς τὰ ὅμοια πράττοντας αὑτῷ, δοκοῦντα δὲ Λυσάνδρῳ καὶ Λακεδαιμονίοις λέγοι. μετ’ ἐκεῖνον δὲ Λύσανδρος ἀναστὰς ἄλλα τε πολλὰ εἶπε καὶ ὅτι παρασπόνδους ὑμᾶς ἔχοι, καὶ ὅτι οὐ περὶ πολιτείας ὑμῖν ἔσται ἀλλὰ περὶ σωτηρίας, εἰ μὴ ποιήσεθ’ ἃ Θηραμένης κελεύει.", "st": "12.74"}, {"sp": "N", "t": "τῶν δ’ ἐν τῇ ἐκκλησία ὅσοι ἄνδρες ἀγαθοὶ ἦσαν, γνόντες τὴν παρασκευὴν καὶ τὴν ἀνάγκην, οἱ μὲν αὐτοῦ μένοντες ἡσυχίαν ἦγον, οἱ δὲ ᾤχοντο ἀπιόντες, τοῦτο γοῦν σφίσιν αὐτοῖς συνειδότες, ὅτι οὐδὲν κακὸν τῇ πόλει ἐψηφίσαντο· ὀλίγοι δέ τινες καὶ πονηροὶ καὶ κακῶς βουλευόμενοι τὰ προσταχθέντα ἐχειροτόνησαν.", "st": "12.75"}, {"sp": "N", "t": "παρήγγελτο γὰρ αὐτοῖς δέκα μὲν οὓς Θηραμένης ἀπέδειξε χειροτονῆσαι, δέκα δὲ οὓς οἱ καθεστηκότες ἔφοροι κελεύοιεν, δέκα δ’ ἐκ τῶν παρόντων· οὕτω γὰρ τὴν ὑμετέραν ἀσθένειαν ἑώρων καὶ τὴν αὑτῶν δύναμιν ἠπίσταντο, ὥστε πρότερον ᾔδεσαν τὰ μέλλοντα ἐν τῇ ἐκκλησία πραχθήσεσθαι.", "st": "12.76"}, {"sp": "N", "t": "ταῦτα δὲ οὐκ ἐμοὶ δεῖ πιστεῦσαι, ἀλλὰ ἐκείνῳ· πάντα γὰρ τὰ ὑπ’ ἐμοῦ εἰρημένα ἐν τῇ βουλῇ ἀπολογούμενος ἔλεγεν, ὀνειδίζων μὲν τοῖς φεύγουσιν, ὅτι δι’ αὑτὸν κατέλθοιεν, οὐδὲν φροντιζόντων Λακεδαιμονίων, ὀνειδίζων δὲ τοῖς τῆς πολιτείας μετέχουσιν, ὅτι πάντων τῶν πεπραγμένων τοῖς εἰρημένοις τρόποις ὑπ’ ἐμοῦ αὐτὸς αἴτιος γεγενημένος τοιούτων τυγχάνοι, πολλὰς πίστεις αὐτοῖς ἔργῳ δεδωκὼς καὶ παρ’ ἐκείνων ὅρκους εἰληφώς.", "st": "12.77"}, {"sp": "N", "t": "καὶ τοσούτων καὶ ἑτέρων κακῶν καὶ αἰσχρῶν καὶ πάλαι καὶ νεωστὶ καὶ μικρῶν καὶ μεγάλων αἰτίου γεγενημένου τολμήσουσιν αὑτοὺς φίλους ὄντας ἀποφαίνειν, οὐχ ὑπὲρ ὑμῶν ἀποθανόντος Θηραμένους ἀλλ’ ὑπὲρ τῆς αὑτοῦ πονηρίας, καὶ δικαίως μὲν ἐν ὀλιγαρχίᾳ δίκην δόντος (ἤδη γὰρ αὐτὴν κατέλυσε), δικαίως δ’ ἂν ἐν δημοκρατίᾳ· δὶς γὰρ ὑμᾶς κατεδουλώσατο, τῶν μὲν παρόντων καταφρονῶν, τῶν δὲ ἀπόντων ἐπιθυμῶν, καὶ τῷ καλλίστῳ ὀνόματι χρώμενος δεινοτάτων ἔργων διδάσκαλος καταστάς.", "st": "12.78"}, {"sp": "N", "t": "περὶ μὲν τοίνυν Θηραμένους ἱκανά μοί ἐστι τὰ κατηγορημένα· ἥκει δ’ ὑμῖν ἐκεῖνος ὁ καιρός, ἐν ᾧ δεῖ συγγνώμην καὶ ἔλεον μὴ εἶναι ἐν ταῖς ὑμετέραις γνώμαις, ἀλλὰ παρὰ Ἐρατοσθένους καὶ τῶν τούτου συναρχόντων δίκην λαβεῖν, μηδὲ μαχομένους ⟨μὲν⟩ κρείττους εἶναι τῶν πολεμίων, ψηφιζομένους δὲ ἥττους τῶν ἐχθρῶν.", "st": "12.79"}, {"sp": "N", "t": "μηδ’ ὧν φασι μέλλειν πράξειν πλείω χάριν αὐτοῖς ἴστε, ἢ ὧν ἐποίησαν ὀργίζεσθε· μηδ’ ἀποῦσι μὲν τοῖς τριάκοντα ἐπιβουλεύετε, παρόντας δ’ ἀφῆτε· μηδὲ τῆς τύχης, ἣ τούτους παρέδωκε τῇ πόλει, κάκιον ὑμῖν αὐτοῖς βοηθήσητε.", "st": "12.80"}, {"sp": "N", "t": "κατηγόρηται δὴ Ἐρατοσθένους καὶ τῶν τούτου φίλων, οἷς τὰς ἀπολογίας ἀνοίσει καὶ μεθ’ ὧν αὐτῷ ταῦτα πέπρακται. ὁ μέντοι ἀγὼν οὐκ ἐξ ἴσου τῇ πόλει καὶ Ἐρατοσθένει· οὗτος μὲν γὰρ κατήγορος καὶ δικαστὴς αὑτὸς ἦν τῶν κρινομένων, ἡμεῖς δὲ νυνὶ εἰς κατηγορίαν καὶ ἀπολογίαν καθέσταμεν.", "st": "12.81"}, {"sp": "N", "t": "καὶ οὗτοι μὲν τοὺς οὐδὲν ἀδικοῦντας ἀκρίτους ἀπέκτειναν, ὑμεῖς δὲ τοὺς ἀπολέσαντας τὴν πόλιν κατὰ τὸν νόμον ἀξιοῦτε κρίνειν, παρ’ ὧν οὐδ’ ἂν παρανόμως βουλόμενοι δίκην λαμβάνειν ἀξίαν τῶν ἀδικημάτων ὧν τὴν πόλιν ἠδικήκασι λάβοιτε. τί γὰρ ἂν παθόντες δίκην τὴν ἀξίαν εἴησαν τῶν ἔργων δεδωκότες;", "st": "12.82"}, {"sp": "N", "t": "πότερον εἰ αὐτοὺς ἀποκτείναιτε καὶ τοὺς παῖδας αὐτῶν, ἱκανὴν ἂν τοῦ φόνου δίκην λάβοιμεν, ὧν οὗτοι πατέρας καὶ ὑεῖς καὶ ἀδελφοὺς ἀκρίτους ἀπέκτειναν; ἀλλὰ εἰ τὰ χρήματα τὰ φανερὰ δημεύσαιτε, καλῶς ἂν ἔχοι ἢ τῇ πόλει, ἧς οὗτοι πολλὰ εἰλήφασιν, ἢ τοῖς ἰδιώταις,", "st": "12.83"}, {"sp": "N", "t": "ὧν ⟨τὰς⟩ οἰκίας ἐξεπόρθησαν; ἐπειδὴ τοίνυν πάντα ποιοῦντες δίκην παρ’ αὐτῶν ⟨τὴν ἀξίαν⟩ οὐκ ἂν δύναισθε λαβεῖν, πῶς οὐκ αἰσχρὸν ὑμῖν καὶ ἡντινοῦν ἀπολιπεῖν, ἥντινά τις βούλοιτο παρὰ τούτων λαμβάνειν;", "st": "12.84"}, {"sp": "N", "t": "πᾶν δ’ ἄν μοι δοκεῖ τολμῆσαι, ὅστις νυνὶ οὐχ ἑτέρων ὄντων τῶν δικαστῶν ἀλλ’ αὐτῶν τῶν κακῶς πεπονθότων, ἥκει ἀπολογησόμενος πρὸς αὐτοὺς τοὺς μάρτυρας τῆς τούτου πονηρίας· τοσοῦτον ἢ ὑμῶν καταπεφρόνηκεν ἢ ἑτέροις πεπίστευκεν.", "st": "12.84"}, {"sp": "N", "t": "ὧν ἀμφοτέρων ἄξιον ἐπιμεληθῆναι, ἐνθυμουμένους ὅτι οὔτ’ ἂν ἐκεῖνα ἐδύναντο ποιεῖν μὴ ἑτέρων συμπραττόντων οὔτ’ ἂν νῦν ἐπεχείρησαν ἐλθεῖν μὴ ὑπὸ τῶν αὐτῶν οἰόμενοι σωθήσεσθαι, οἳ οὐ τούτοις ἥκουσι βοηθήσοντες, ἀλλὰ ἡγούμενοι πολλὴν ἄδειαν σφίσιν ἔσεσθαι τῶν ⟨τε⟩ πεπραγμένων καὶ τοῦ λοιποῦ ποιεῖν ὅ τι ἂν βούλωνται, εἰ τοὺς μεγίστων κακῶν αἰτίους λαβόντες ἀφήσετε.", "st": "12.85"}, {"sp": "N", "t": "ἀλλὰ καὶ τῶν συνερούντων αὐτοῖς ἄξιον θαυμάζειν, πότερον ὡς καλοὶ κἀγαθοὶ αἰτήσονται, τὴν αὑτῶν ἀρετὴν πλείονος ἀξίαν ἀποφαίνοντες τῆς ⟨τούτων⟩ πονηρίας· ἐβουλόμην μέντ’ ἂν αὐτοὺς οὕτω προθύμους εἶναι σῴζειν τὴν πόλιν, ὥσπερ οὗτοι ἀπολλύναι ἢ ὡς δεινοὶ λέγειν ἀπολογήσονται καὶ τὰ τούτων ἔργα πολλοῦ ἄξια ἀποφανοῦσιν. ἀλλ’ οὐχ ὑπὲρ ὑμῶν οὐδεὶς αὐτῶν οὐδὲ τὰ δίκαια πώποτε ἐπεχείρησεν εἰπεῖν.", "st": "12.86"}, {"sp": "N", "t": "ἀλλὰ τοὺς μάρτυρας ἄξιον ἰδεῖν, οἳ τούτοις μαρτυροῦντες αὑτῶν κατηγοροῦσι, σφόδρα ἐπιλήσμονας καὶ εὐήθεις νομίζοντες ὑμᾶς εἶναι, εἰ διὰ μὲν τοῦ ὑμετέρου πλήθους ἀδεῶς ἡγοῦνται τοὺς τριάκοντα σώσειν, διὰ δὲ Ἐρατοσθένην καὶ τοὺς συνάρχοντας αὐτοῦ δεινὸν ἦν καὶ τῶν τεθνεώτων ἐπ’ ἐκφορὰν ἐλθεῖν.", "st": "12.87"}, {"sp": "N", "t": "καίτοι οὗτοι μὲν σωθέντες πάλιν ἂν δύναιντο τὴν πόλιν ἀπολέσαι· ἐκεῖνοι δέ, οὓς οὗτοι ἀπώλεσαν, τελευτήσαντες τὸν βίον πέρας ἔχουσι τῆς παρὰ τῶν ἐχθρῶν τιμωρίας. οὐκ οὖν δεινὸν εἰ τῶν μὲν ἀδίκως τεθνεώτων οἱ φίλοι συναπώλλυντο, αὐτοῖς δὲ τοῖς τὴν πόλιν ἀπολέσασι δήπου ἐπ’ ἐκφορὰν πολλοὶ ἥξουσιν, ὁπότε βοηθεῖν τοσοῦτοι παρασκευάζονται;", "st": "12.88"}, {"sp": "N", "t": "καὶ μὲν δὴ πολλῷ ῥᾷον ἡγοῦμαι εἶναι ὑπὲρ ὧν ὑμεῖς ἐπάσχετε ἀντειπεῖν, ἢ ὑπὲρ ὧν οὗτοι πεποιήκασιν ἀπολογήσασθαι. καίτοι λέγουσιν ὡς Ἐρατοσθένει ἐλάχιστα τῶν τριάκοντα κακὰ εἴργασται, καὶ διὰ τοῦτο αὐτὸν ἀξιοῦσι σωθῆναι· ὅτι δὲ τῶν ἄλλων Ἑλλήνων πλεῖστα εἰς ὑμᾶς ἐξημάρτηκεν,", "st": "12.89"}, {"sp": "N", "t": "οὐκ οἴονται χρῆναι αὐτὸν ἀπολέσθαι; ὑμεῖς δὲ δείξατε ἥντινα γνώμην ἔχετε περὶ τῶν πραγμάτων. εἰ μὲν γὰρ τούτου καταψηφιεῖσθε, δῆλοι ἔσεσθε ὡς ὀργιζόμενοι τοῖς πεπραγμένοις· εἰ δὲ ἀποψηφιεῖσθε, ὀφθήσεσθε τῶν αὐτῶν ἔργων ἐπιθυμηταὶ τούτοις ὄντες, καὶ οὐχ ἕξετε λέγειν ὅτι τὰ ὑπὸ τῶν τριάκοντα", "st": "12.90"}, {"sp": "N", "t": "προσταχθέντα ἐποιεῖτε· νυνὶ μὲν γὰρ οὐδεὶς ὑμᾶς ἀναγκάζει παρὰ τὴν ὑμετέραν γνώμην ψηφίζεσθαι. ὥστε συμβουλεύω μὴ τούτων ἀποψηφισαμένους ὑμῶν αὐτῶν καταψηφίσασθαι. μηδ’ οἴεσθε κρύβδην τὴν ψῆφον εἶναι φανερὰν γὰρ τῇ πόλει τὴν ὑμετέραν γνώμην ποιήσετε.", "st": "12.91"}, {"sp": "N", "t": "βούλομαι δὲ ὀλίγα ἑκατέρους ἀναμνήσας καταβαίνειν, τούς τε ἐξ ἄστεως καὶ τοὺς ἐκ Πειραιῶς, ἵνα τὰς ὑμῖν τούτων γεγενημένας συμφορὰς παραδείγματα ἔχοντες τὴν ψῆφον φέρητε. καὶ πρῶτον μὲν ὅσοι ἐξ ἄστεώς ἐστε, σκέψασθε ὅτι ὑπὸ τούτων οὕτω σφόδρα ἤρχεσθε, ὥστε ἀδελφοῖς καὶ ὑέσι καὶ πολίταις ἠναγκάζεσθε πολεμεῖν τοιοῦτον πόλεμον, ἐν ᾧ ἡττηθέντες μὲν τοῖς νικήσασι τὸ ἴσον ἔχετε, νικήσαντες δ’ ἄν τούτοις ἐδουλεύετε.", "st": "12.92"}, {"sp": "N", "t": "καὶ τοὺς ἰδίους οἴκους οὗτοι μὲν [ἂν] ἐκ τῶν πραγμάτων μεγάλους ἐκτήσαντο, ὑμεῖς δὲ διὰ τὸν πρὸς ἀλλήλους πόλεμον ἐλάττους ἔχετε· συνωφελεῖσθαι μὲν γὰρ ὑμᾶς οὐκ ἠξίουν, συνδιαβάλλεσθαι δ’ ἠνάγκαζον, εἰς τοσοῦτον ὑπεροψίας ἐλθόντες ὥστε οὐ τῶν ἀγαθῶν κοινούμενοι πιστοὺς ὑμᾶς ἐκτῶντο, ἀλλὰ τῶν ὀνειδῶν μεταδιδόντες εὔνους ὤοντο εἶναι.", "st": "12.93"}, {"sp": "N", "t": "ἀνθ’ ὧν ὑμεῖς νῦν ἐν τῷ θαρραλέῳ ὄντες, καθ’ ὅσον δύνασθε, καὶ ὑπὲρ ὑμῶν αὐτῶν καὶ ὑπὲρ τῶν ἐκ Πειραιῶς τιμωρήσασθε, ἐνθυμηθέντες μὲν ὅτι ὑπὸ τούτων πονηροτάτων ὄντων ἤρχεσθε, ἐνθυμηθέντες δὲ ὅτι μετ’ ἀνδρῶν νῦν ἀρίστων πολιτεύεσθε καὶ τοῖς πολεμίοις μάχεσθε καὶ περὶ τῆς πόλεως βουλεύεσθε, ἀναμνησθέντες δὲ τῶν ἐπικούρων, οὓς οὗτοι φύλακας τῆς σφετέρας ἀρχῆς καὶ τῆς ὑμετέρας δουλείας εἰς τὴν ἀκρόπολιν κατέστησαν.", "st": "12.94"}, {"sp": "N", "t": "καὶ πρὸς ὑμᾶς μὲν ἔτι πολλῶν ὄντων εἰπεῖν τοσαῦτα λέγω. ὅσοι δ’ ἐκ Πειραιῶς ἐστε, πρῶτον μὲν τῶν ὅπλων ἀναμνήσθητε, ὅτι πολλὰς μάχας ἐν τῇ ἀλλοτρίᾳ μαχεσάμενοι οὐχ ὑπὸ τῶν πολεμίων ἀλλ’ ὑπὸ τούτων εἰρήνης οὔσης ἀφῃρέθητε τὰ ὅπλα, ἔπειθ’ ὅτι ἐξεκηρύχθητε μὲν ἐκ τῆς πόλεως, ἣν ὑμῖν οἱ πατέρες παρέδοσαν, φεύγοντας δὲ ὑμᾶς ἐκ τῶν πόλεων ἐξῃτοῦντο.", "st": "12.95"}, {"sp": "N", "t": "ἀνθ’ ὧν ὀργίσθητε μὲν ὥσπερ ὅτ’ ἐφεύγετε, ἀναμνήσθητε δὲ καὶ τῶν ἄλλων κακῶν ἃ πεπόνθατε ὑπ’ αὐτῶν, οἳ τοὺς μὲν ἐκ τῆς ἀγορᾶς τοὺς δ’ ἐκ τῶν ἱερῶν συναρπάζοντες βιαίως ἀπέκτειναν, τοὺς δὲ ἀπὸ τέκνων καὶ γονέων καὶ γυναικῶν ἀφέλκοντες φονέας αὑτῶν ἠνάγκασαν γενέσθαι καὶ οὐδὲ ταφῆς τῆς νομιζομένης εἴασαν τυχεῖν, ἡγούμενοι τὴν αὑτῶν ἀρχὴν βεβαιοτέραν εἶναι τῆς παρὰ τῶν θεῶν τιμωρίας. ὅσοι δὲ τὸν θάνατον διέφυγον,", "st": "12.96"}, {"sp": "N", "t": "πολλαχοῦ κινδυνεύσαντες καὶ εἰς πολλὰς πόλεις πλανηθέντες καὶ πανταχόθεν ἐκκηρυττόμενοι, ἐνδεεῖς ὄντες τῶν ἐπιτηδείων, οἱ μὲν ἐν πολεμίᾳ τῇ πατρίδι τοὺς παῖδας καταλιπόντες, οἱ δ’ ἐν ξένῃ γῇ, πολλῶν ἐναντιουμένων ἤλθετε εἰς τὸν Πειραιᾶ. πολλῶν δὲ καὶ μεγάλων κινδύνων ὑπαρξάντων ἄνδρες ἀγαθοὶ γενόμενοι τοὺς μὲν ἠλευθερώσατε, τοὺς δ’ εἰς τὴν πατρίδα κατηγάγετε.", "st": "12.97"}, {"sp": "N", "t": "εἰ δὲ ἐδυστυχήσατε καὶ τούτων ἡμάρτετε, αὐτοὶ μὲν ἂν δείσαντες ἐφεύγετε μὴ πάθητε τοιαῦτα οἷα καὶ πρότερον, καὶ οὔτ’ ἂν ἱερὰ οὔτε βωμοὶ ὑμᾶς ἀδικουμένους διὰ τοὺς τούτων τρόπους ὠφέλησαν, ἃ καὶ τοῖς ἀδικοῦσι σωτήρια γίγνεται· οἱ δὲ παῖδες ὑμῶν, ὅσοι μὲν ἐνθάδε ἦσαν, ὑπὸ τούτων ἂν ὑβρίζοντο, οἱ δ’ ἐπὶ ξένης μικρῶν ἂν ἕνεκα συμβολαίων ἐδούλευον ἐρημίᾳ τῶν ἐπικουρησόντων.", "st": "12.98"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐ τὰ μέλλοντα ἔσεσθαι βούλομαι λέγειν, τὰ πραχθέντα ὑπὸ τούτων οὐ δυνάμενος εἰπεῖν. οὐδὲ γὰρ ἑνὸς κατηγόρου οὐδὲ δυοῖν ἔργον ἐστίν, ἀλλὰ πολλῶν. ὅμως δὲ τῆς ἐμῆς προθυμίας ⟨οὐδὲν⟩ ἐλλέλειπται, ὑπέρ ⟨τε⟩ τῶν ἱερῶν, ἃ οὗτοι τὰ μὲν ἀπέδοντο τὰ δ’ εἰσιόντες ἐμίαινον, ὑπέρ τε τῆς πόλεως, ἣν μικρὰν ἐποίουν, ὑπέρ τε τῶν νεωρίων, ἃ καθεῖλον, καὶ ὑπὲρ τῶν τεθνεώτων, οἷς ὑμεῖς, ἐπειδὴ ζῶσιν ἐπαμῦναι οὐκ ἐδύνασθε, ἀποθανοῦσι βοηθήσατε.", "st": "12.99"}, {"sp": "N", "t": "οἶμαι δ’ αὐτοὺς ἡμῶν τε ἀκροᾶσθαι καὶ ὑμᾶς εἴσεσθαι τὴν ψῆφον φέροντας, ἡγουμένους, ὅσοι μὲν ἂν τούτων ἀποψηφίσησθε, αὐτῶν θάνατον κατεψηφισμένους ἔσεσθαι, ὅσοι δ’ ἂν παρὰ τούτων δίκην λάβωσιν, ὑπὲρ αὐτῶν τιμωρίας πεποιημένους.", "st": "12.100"}, {"sp": "N", "t": "παύσομαι κατηγορῶν. ἀκηκόατε, ἑωράκατε, πεπόνθατε, ἔχετε· δικάζετε.", "st": "12.100"}, {"sp": "HDR", "t": "ΙΓʹ. Κατὰ Ἀγοράτου ἐνδείξεως", "st": "13"}, {"sp": "N", "t": "προσήκει μέν, ὦ ἄνδρες δικασταί, πᾶσιν ὑμῖν τιμωρεῖν ὑπὲρ τῶν ἀνδρῶν οἳ ἀπέθανον εὖνοι ὄντες τῷ πλήθει τῷ ὑμετέρῳ, προσήκει δὲ κἀμοὶ οὐχ ἥκιστα· κηδεστὴς γάρ μοι ἦν Διονυσόδωρος καὶ ἀνεψιός. τυγχάνει οὖν ἐμοὶ ἡ αὐτὴ ἔχθρα πρὸς Ἀγόρατον τουτονὶ καὶ τῷ πλήθει τῷ ὑμετέρῳ ὑπάρχουσα· ἔπραξε γὰρ οὗτος τοιαῦτα, δι’ ἃ ὑπ’ ἐμοῦ νυνὶ εἰκότως μισεῖται, ὑπό τε ὑμῶν, ἐὰν θεὸς θέλῃ, δικαίως τιμωρηθήσεται.", "st": "13.1"}, {"sp": "N", "t": "Διονυσόδωρον γὰρ τὸν κηδεστὴν τὸν ἐμὸν καὶ ἑτέρους πολλούς, ὧν δὴ τὰ ὀνόματα ἀκούσεσθε, ἄνδρας ὄντας ἀγαθοὺς περὶ τὸ πλῆθος τὸ ὑμέτερον, ἐπὶ τῶν τριάκοντα ἀπέκτεινε, μηνυτὴς κατ’ ἐκείνων γενόμενος. ποιήσας δὲ ταῦτα ἐμὲ μὲν ἰδίᾳ καὶ ἕκαστον τῶν προσηκόντων μεγάλα ἐζημίωσε, τὴν δὲ πόλιν κοινῇ πᾶσαν τοιούτων ἀνδρῶν ἀποστερήσας οὐ μικρά,", "st": "13.2"}, {"sp": "N", "t": "ὡς ἐγὼ νομίζω, ἔβλαψεν. ἐγὼ οὖν, ⟨ὦ⟩ ἄνδρες δικασταί, δίκαιον καὶ ὅσιον ἡγοῦμαι εἶναι καὶ ἐμοὶ καὶ ὑμῖν ἅπασι τιμωρεῖσθαι καθ’ ὅσον ἕκαστος δύναται· καὶ ποιοῦσι ταῦτα νομίζω ἡμῖν καὶ παρὰ θεῶν καὶ παρ’ ἀνθρώπων ἄμεινον ἂν γίγνεσθαι. δεῖ δ’ ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, ἐξ ἀρχῆς τῶν πραγμάτων ἁπάντων ἀκοῦσαι,", "st": "13.3"}, {"sp": "N", "t": "ἵν’ εἰδῆτε πρῶτον μὲν ᾧ τρόπῳ ὑμῖν ἡ δημοκρατία κατελύθη καὶ ὑφ’ ὅτου, ἔπειτα ᾧ τρόπῳ οἱ ἄνδρες ὑπ’ Ἀγοράτου ἀπέθανον, καὶ δὴ ὅ τι ἀποθνῄσκειν μέλλοντες ἐπέσκηψαν· ἅπαντα γὰρ ταῦτα ἀκριβῶς ἂν μαθόντες ἥδιον καὶ ὁσιώτερον Ἀγοράτου τουτουὶ καταψηφίζοισθε. ὅθεν οὖν ἡμεῖς τε ῥᾷστα διδάξομεν καὶ ὑμεῖς μαθήσεσθε, ἐντεῦθεν ὑμῖν ἄρξομαι διηγεῖσθαι.", "st": "13.4"}, {"sp": "N", "t": "ἐπειδὴ γὰρ αἱ νῆες αἱ ὑμέτεραι διεφθάρησαν καὶ τὰ πράγματα ⟨τὰ⟩ ἐν τῇ πόλει ἀσθενέστερα ἐγεγένητο, οὐ πολλῷ χρόνῳ ὕστερον αἵ τε νῆες αἱ Λακεδαιμονίων ἐπὶ τὸν Πειραιᾶ ἀφικνοῦνται, καὶ ἅμα λόγοι πρὸς Λακεδαιμονίους περὶ τῆς εἰρήνης ἐγίγνοντο.", "st": "13.5"}, {"sp": "N", "t": "ἐν δὲ τῷ χρόνῳ τούτῳ οἱ βουλόμενοι νεώτερα πράγματα ἐν τῇ πόλει γίγνεσθαι ἐπεβούλευον, νομίζοντες κάλλιστον καιρὸν εἰληφέναι καὶ μάλιστ’ ⟨ἂν⟩ ἐν τῷ τότε χρόνῳ τὰ πράγματα, ὡς αὐτοὶ ἐβούλοντο, καταστήσασθαι.", "st": "13.6"}, {"sp": "N", "t": "ἡγοῦντο δὲ οὐδὲν ἄλλο σφίσιν ἐμποδὼν εἶναι ἢ τοὺς τοῦ δήμου προεστηκότας καὶ τοὺς στρατηγοῦντας καὶ ταξιαρχοῦντας. τούτους οὖν ἐβούλοντο ἁμῶς γέ πως ἐκποδὼν ποιήσασθαι, ἵνα ῥᾳδίως ἃ βούλοιντο διαπράττοιντο. πρῶτον μὲν οὖν Κλεοφῶντι ἐπέθεντο ἐκ τρόπου τοιούτου.", "st": "13.7"}, {"sp": "N", "t": "ὅτε γὰρ ἡ πρώτη ἐκκλησία περὶ τῆς εἰρήνης ἐγίγνετο καὶ οἱ παρὰ Λακεδαιμονίων ἥκοντες ἔλεγον ἐφ’ οἷς ἕτοιμοι εἶεν τὴν εἰρήνην ποιεῖσθαι Λακεδαιμόνιοι, εἰ κατασκαφείη τῶν τειχῶν τῶν μακρῶν ἐπὶ δέκα στάδια ἑκατέρου, τότε ὑμεῖς τε, ὦ ἄνδρες Ἀθηναῖοι, οὐκ ἠνέσχεσθε ἀκούσαντες περὶ τῶν τειχῶν τῆς κατασκαφῆς, Κλεοφῶν τε ὑπὲρ ὑμῶν πάντων ἀναστὰς ἀντεῖπεν ὡς οὐδενὶ τρόπῳ οἷόν τε εἴη ποιεῖν ταῦτα.", "st": "13.8"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Θηραμένης, ἐπιβουλεύων τῷ πλήθει τῷ ὑμετέρῳ, ἀναστὰς λέγει ὅτι, ἐὰν αὐτὸν ἕλησθε περὶ τῆς εἰρήνης πρεσβευτὴν αὐτοκράτορα, ποιήσει ὥστε μήτε τῶν τειχῶν διελεῖν μήτε ἄλλο τὴν πόλιν ἐλαττῶσαι μηδέν· οἴοιτο δὲ καὶ ἄλλο τι ἀγαθὸν παρὰ Λακεδαιμονίων τῇ πόλει εὑρήσεσθαι.", "st": "13.9"}, {"sp": "N", "t": "πεισθέντες δὲ ὑμεῖς εἵλεσθε ἐκεῖνον πρεσβευτὴν αὐτοκράτορα, ὃν τῷ προτέρῳ ἔτει στρατηγὸν χειροτονηθέντα ἀπεδοκιμάσατε, οὐ νομίζοντες εὔνουν εἶναι τῷ πλήθει τῷ ὑμετέρῳ.", "st": "13.10"}, {"sp": "N", "t": "ἐκεῖνος μὲν οὖν ἐλθὼν εἰς Λακεδαίμονα ἔμενεν ἐκεῖ πολὺν χρόνον, καταλιπὼν ὑμᾶς πολιορκουμένους, εἰδὼς τὸ ὑμέτερον πλῆθος ἐν ἀπορίᾳ ἐχόμενον καὶ διὰ τὸν πόλεμον καὶ τὰ κακὰ τοὺς πολλοὺς τῶν ἐπιτηδείων ἐνδεεῖς ὄντας, νομίζων, εἰ διαθείη ὑμᾶς [ἀπόρως] ὥσπερ διέθηκεν, ἀσμένως ὁποιαντινοῦν ἐθελῆσαι ἂν εἰρήνην ποιήσασθαι.", "st": "13.11"}, {"sp": "N", "t": "οἱ δ’ ἐνθάδε ὑπομένοντες καὶ ἐπιβουλεύοντες καταλῦσαι τὴν δημοκρατίαν εἰς ἀγῶνα Κλεοφῶντα καθιστᾶσι, πρόφασιν μὲν ὅτι οὐκ ἦλθεν εἰς τὰ ὅπλα ἀναπαυσόμενος, τὸ δ’ ἀληθὲς ὅτι ἀντεῖπεν ὑπὲρ ὑμῶν μὴ καθαιρεῖν τὰ τείχη. ἐκείνῳ μὲν οὖν δικαστήριον παρασκευάσαντες καὶ εἰσελθόντες οἱ βουλόμενοι ὀλιγαρχίαν καταστήσασθαι ἀπέκτειναν ἐν τῇ προφάσει ταύτῃ.", "st": "13.12"}, {"sp": "N", "t": "Θηραμένης δὲ ὕστερον ἀφικνεῖται ἐκ Λακεδαίμονος. προσιόντες δ’ αὐτῷ τῶν τε στρατηγῶν τινες καὶ τῶν ταξιάρχων, ὧν ἦν Στρομβιχίδης καὶ Διονυσόδωρος, καὶ ἄλλοι τινὲς τῶν πολιτῶν εὐνοοῦντες ὑμῖν, ὥς γ’ ἐδήλωσαν ὕστερον, ἠγανάκτουν σφόδρα. ἦλθε γὰρ φέρων εἰρήνην τοιαύτην, ἣν ἡμεῖς ἔργῳ μαθόντες ἔγνωμεν· πολλοὺς γὰρ τῶν πολιτῶν καὶ ἀγαθοὺς ἀπωλέσαμεν,", "st": "13.13"}, {"sp": "N", "t": "καὶ αὐτοὶ ὑπὸ τῶν τριάκοντα ἐξηλάθημεν. ἐνῆν γὰρ ἀντὶ μὲν τοῦ ἐπὶ δέκα στάδια τῶν μακρῶν τειχῶν διελεῖν ὅλα τὰ μακρὰ τείχη διασκάψαι, ἀντὶ δὲ τοῦ ἄλλο τι ἀγαθὸν τῇ πόλει εὑρέσθαι τάς τε ναῦς παραδοῦναι [τοῖς Λακεδαιμονίοις] καὶ τὸ περὶ τὸν Πειραιᾶ τεῖχος περιελεῖν.", "st": "13.14"}, {"sp": "N", "t": "ὁρῶντες δὲ οὗτοι οἱ ἄνδρες ὀνόματι μὲν εἰρήνην λεγομένην, τῷ δ’ ἔργῳ τὴν δημοκρατίαν καταλυομένην, οὐκ ἔφασαν ἐπιτρέψειν ταῦτα γενέσθαι, οὐκ ἐλεοῦντες, ὦ ἄνδρες Ἀθηναῖοι, τὰ τείχη, εἰ πεσεῖται, οὐδὲ κηδόμενοι τῶν νεῶν, εἰ Λακεδαιμονίοις παραδοθήσονται (οὐδὲν γὰρ αὐτοῖς τούτων πλέον ἤ ὑμῶν ἑκάστῳ προσῆκεν),", "st": "13.15"}, {"sp": "N", "t": "ἀλλ’ αἰσθόμενοι ἐκ τοῦ τρόπου τούτου τὸ ὑμέτερον πλῆθος καταλυθησόμενον, οὐδ’, ὥς φασί τινες, οὐκ ἐπιθυμοῦντες εἰρήνην γίγνεσθαι, ἀλλὰ βουλόμενοι βελτίω ταύτης εἰρήνην τῷ δήμῳ τῷ Ἀθηναίων ποιήσασθαι. ἐνόμιζον δὲ δυνήσεσθαι, καὶ ἔπραξαν ἂν ταῦτα, εἰ μὴ ὑπ’ Ἀγοράτου τουτουὶ ἀπώλοντο.", "st": "13.16"}, {"sp": "N", "t": "γνοὺς δὲ ταῦτα Θηραμένης καὶ οἱ ἄλλοι οἱ ἐπιβουλεύοντες ὑμῖν, ὅτι εἰσί τινες οἳ κωλύσουσι τὸν δῆμον καταλυθῆναι καὶ ἐναντιώσονται περὶ τῆς ἐλευθερίας, εἵλοντο, πρὶν τὴν ἐκκλησίαν τὴν περὶ τῆς εἰρήνης γενέσθαι, τούτους πρῶτον εἰς διαβολὰς καὶ κινδύνους καταστῆσαι, ἵνα μηδεὶς ἐκεῖ ὑπὲρ τοῦ ὑμετέρου πλήθους ἀντιλέγοι. ἐπιβουλὴν οὖν τοιαύτην ἐπιβουλεύουσι.", "st": "13.17"}, {"sp": "N", "t": "πείθουσι γὰρ Ἀγόρατον τουτονὶ μηνυτὴν κατὰ τῶν στρατηγῶν καὶ τῶν ταξιάρχων γενέσθαι, οὐ συνειδότα ἐκείνοις, ὦ ἄνδρες Ἀθηναῖοι, οὐδέν (οὐ γὰρ δήπου ἐκεῖνοι οὕτως ἀνόητοι ἦσαν καὶ ἄφιλοι, ὥστε περὶ τηλικούτων ἂν πραγμάτων πράττοντες Ἀγόρατον ὡς πιστὸν καὶ εὔνουν, δοῦλον καὶ ἐκ δούλων ὄντα, παρεκάλεσαν), ἀλλ’ ἐδόκει αὐτοῖς οὗτος ἐπιτήδειος εἶναι μηνυτής.", "st": "13.18"}, {"sp": "N", "t": "ἐβούλοντο οὖν ἄκοντα δοκεῖν αὐτὸν καὶ μὴ ἑκόντα μηνύειν, ὅπως πιστοτέρα ἡ μήνυσις φαίνοιτο. ὡς δὲ ἑκὼν ἐμήνυσε, καὶ ὑμᾶς οἶμαι ἐκ τῶν πεπραγμένων αἰσθήσεσθαι. εἰσπέμπουσι γὰρ εἰς τὴν βουλὴν [τὴν πρὸ τῶν τριάκοντα βουλεύουσαν] Θεόκριτον τὸν τοῦ Ἐλαφοστίκτου καλούμενον· ὁ δὲ Θεόκριτος οὗτος ἑταῖρος ἦν τῷ Ἀγοράτῳ καὶ ἐπιτήδειος.", "st": "13.19"}, {"sp": "N", "t": "ἡ δὲ βουλὴ ἡ πρὸ τῶν τριάκοντα βουλεύουσα διέφθαρτο καὶ ὀλιγαρχίας ἐπεθύμει, ὡς ἴστε, μάλιστα. τεκμήριον δέ· οἱ γὰρ πολλοὶ ⟨οἱ⟩ ἐξ ἐκείνης τῆς βουλῆς τὴν ὑστέραν βουλὴν ⟨τὴν⟩ ἐπὶ τῶν τριάκοντα ἐβούλευον. τοῦ δ’ ἕνεκα ταῦτα λέγω ὑμῖν; ἵν’ εἰδῆτε, ὅτι τὰ ψηφίσματα ⟨τὰ⟩ ἐξ ἐκείνης τῆς βουλῆς οὐκ ἐπ’ εὐνοίᾳ τῇ ὑμετέρᾳ ἀλλ’ ἐπὶ καταλύσει τοῦ δήμου τοῦ ὑμετέρου ἅπαντα ἐγένετο, καὶ ὡς τοιούτοις οὖσιν αὐτοῖς τὸν νοῦν προσέχητε.", "st": "13.20"}, {"sp": "N", "t": "εἰσελθὼν δὲ εἰς ταύτην τὴν βουλὴν ἐν ἀπορρήτῳ Θεόκριτος μηνύει ὅτι συλλέγονταί τινες ἐναντιωσόμενοι τοῖς τότε καθισταμένοις πράγμασι. τὰ μὲν οὖν ὀνόματα οὐκ ἔφη αὐτῶν ἐρεῖν καθ’ ἕκαστον· ὅρκους τε γὰρ ὀμωμοκέναι τοὺς αὐτοὺς ἐκείνοις, καὶ εἶναι ἑτέρους οἳ ἐροῦσι τὰ ὀνόματα, αὐτὸς δὲ οὐκ ἄν ποτε ποιῆσαι ταῦτα.", "st": "13.21"}, {"sp": "N", "t": "καίτοι εἰ μὴ ἐκ παρασκευῆς ἐμηνύετο, πῶς οὐκ ἂν ἠνάγκασεν ἡ βουλὴ εἰπεῖν τὰ ὀνόματα Θεόκριτον καὶ μὴ ἀνώνυμον τὴν μήνυσιν ποιήσασθαι; νυνὶ δὲ τοῦτο τὸ ψήφισμα ψηφίζεται.", "st": "13.22"}, {"sp": "N", "t": "<em>Ψήφισμα<\/em>", "st": "13.23"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν τοῦτο τὸ ψήφισμα ἐψηφίσθη, κατέρχονται ἐπὶ τὸν Ἀγόρατον εἰς τὸν Πειραιᾶ οἱ αἱρεθέντες τῶν βουλευτῶν, καὶ περιτυχόντες αὐτῷ ἐν ἀγορᾷ ἐζήτουν ἄγειν. παραγενόμενος δὲ Νικίας καὶ Νικομένης καὶ ἄλλοι τινές, ὁρῶντες τὰ πράγματα οὐχ οἷα βέλτιστα ἐν τῇ πόλει ὄντα, ἄγειν μὲν τὸν Ἀγόρατον οὐκ ἔφασαν προήσεσθαι, ἀφῃροῦντο δὲ καὶ ἠγγυῶντο καὶ ὡμολόγουν παρέξειν εἰς τὴν βουλήν.", "st": "13.23"}, {"sp": "N", "t": "γραψάμενοι δὲ οἱ βουλευταὶ τὰ ὀνόματα τῶν ἐγγυωμένων καὶ κωλυόντων, ἀπιόντες ᾤχοντο εἰς ἄστυ. ὁ δὲ Ἀγόρατος καὶ οἱ ἐγγυηταὶ καθίζουσιν ἐπὶ τὸν βωμὸν Μουνιχίασιν· ἐπειδὴ δὲ ἐκάθισαν, ἐβουλεύοντο τί χρὴ ποιεῖν. ἐδόκει οὖν τοῖς ἐγγυηταῖς καὶ τοῖς ἄλλοις ἅπασιν ἐκποδὼν ποιήσασθαι τὸν Ἀγόρατον ὡς τάχιστα,", "st": "13.24"}, {"sp": "N", "t": "καὶ παρορμίσαντες δύο πλοῖα [Μουνιχίασιν] ἐδέοντο αὐτοῦ παντὶ τρόπῳ ἀπελθεῖν Ἀθήνηθεν, καὶ αὐτοὶ ἔφασαν συνεκπλευσεῖσθαι, ἕως τὰ πράγματα κατασταίη, λέγοντες ὅτι, εἰ κομισθείη εἰς τὴν βουλήν, βασανιζόμενος ἴσως ἀναγκασθήσεται ὀνόματα εἰπεῖν Ἀθηναίων ὧν ἂν ὑποβάλωσιν οἱ βουλόμενοι κακόν τι ἐν τῇ πόλει ἐργάζεσθαι.", "st": "13.25"}, {"sp": "N", "t": "ταῦτα ἐκείνων δεομένων καὶ παρασκευασάντων πλοῖα καὶ αὐτῶν ἑτοίμων ὄντων συνεκπλεῖν, οὐκ ἠθέλησε πείθεσθαι αὐτοῖς Ἀγόρατος οὑτοσί. καίτοι, ὦ Ἀγόρατε, εἰ μή τί σοι ἦν παρεσκευασμένον καὶ ἐπίστευες μηδὲν κακὸν πείσεσθαι, πῶς οὐκ ἂν ᾤχου καὶ πλοίων παρεσκευασμένων καὶ τῶν ἐγγυητῶν ἑτοίμων ὄντων σοι συνεκπλεῖν; ἔτι γὰρ οἷόν τέ σοι ἦν, καὶ οὔπω ἡ βουλή σου ἐκράτει.", "st": "13.26"}, {"sp": "N", "t": "ἀλλὰ μὲν δὴ οὐχ ὅμοιά γε σοὶ καὶ ἐκείνοις ὑπῆρχε. πρῶτον μὲν γὰρ Ἀθηναῖοι ἦσαν ὥστε οὐκ ἐδέδισαν βασανισθῆναι· ἔπειτα πατρίδα σφετέραν αὐτῶν καταλιπόντες ἕτοιμοι ἦσαν συνεκπλεῖν μετὰ σοῦ, ἡγησάμενοι ταῦτα μᾶλλον λυσιτελεῖν ἢ τῶν πολιτῶν πολλοὺς καὶ ἀγαθοὺς ὑπὸ σοῦ ἀδίκως ἀπολέσθαι. σοὶ δὲ πρῶτον μὲν κίνδυνος ἦν βασανισθῆναι ὑπομείναντι, ἔπειτα οὐ πατρίδα ἂν σαυτοῦ ἀπέλιπες·", "st": "13.27"}, {"sp": "N", "t": "ὥστ’ ἐκ παντὸς τρόπου σοὶ μᾶλλον ἢ ἐκείνοις ἐκπλεῦσαι συνέφερεν, εἰ μή τι ἦν ᾧ ἐπίστευες. νῦν δὲ ἄκων μὲν προσποιεῖ, ἑκὼν δὲ πολλοὺς καὶ ἀγαθοὺς Ἀθηναίων ἀπέκτεινας. ὡς δὲ παρεσκευάσθη ἅπαντα ἃ ἐγὼ λέγω, καὶ μάρτυρές εἰσι καὶ αὐτὸ τὸ ψήφισμά σου τὸ τῆς βουλῆς καταμαρτυρήσει.", "st": "13.28"}, {"sp": "N", "t": "<em>⟨Μάρτυρες⟩ Ψήφισμα<\/em>", "st": "13.29"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν τοῦτο τὸ ψήφισμα ἐψηφίσθη καὶ ἦλθον οἱ ἐκ τῆς βουλῆς Μουνιχίαζε, ἑκὼν ἀνέστη Ἀγόρατος ἀπὸ τοῦ βωμοῦ· καίτοι νῦν γε βίᾳ φησὶν ἀφαιρεθῆναι.", "st": "13.29"}, {"sp": "N", "t": "ἐπειδὴ δὲ εἰς τὴν βουλὴν ἐκομίσθησαν, ἀπογράφει Ἀγόρατος πρῶτον μὲν τῶν αὑτοῦ ἐγγυητῶν τὰ ὀνόματα, ἔπειτα τῶν στρατηγῶν καὶ τῶν ταξιάρχων, ἔπειτα δὲ καὶ ἄλλων τινῶν πολιτῶν. ἡ δὲ ἀρχὴ αὕτη τοῦ παντὸς κακοῦ ἐγένετο. ὡς δὲ ἀπέγραψε τὰ ὀνόματα, οἶμαι μὲν καὶ αὐτὸν ὁμολογήσειν· εἰ δὲ μή, ἐπ’ αὐτοφώρῳ ἐγὼ αὐτὸν ἐξελέγξω. ἀπόκριναι δή μοι.", "st": "13.30"}, {"sp": "N", "t": "<em>Ἐρώτησις<\/em>", "st": "13.31"}, {"sp": "N", "t": "ἐβούλοντο τοίνυν, ὦ ἄνδρες δικασταί, ἔτι πλειόνων αὐτὸν τὰ ὀνόματα ἀπογράψαι· οὕτω ἔρρωτο ἡ βουλὴ κακόν τι ἐργάζεσθαι [αὐτὸν] ὥστ’ οὐκ ἐδόκει αὐτοῖς ἅπαντα τἀληθῆ πω κατηγορηκέναι. τούτους μὲν οὖν ἅπαντας ἑκὼν ἀπογράφει, οὐδεμιᾶς αὐτῶνἀνάγκης οὔσης. [μετὰ τοῦτο προσαπογράφει ἑτέρους τῶν πολιτῶν.]", "st": "13.31"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἡ ἐκκλησία Μουνιχίασιν ἐν τῷ θεάτρῳ ἐγίγνετο, οὕτω σφόδρα τινὲς ἐπεμελοῦντο ὅπως καὶ ἐν τῷ δήμῳ περὶ τῶν στρατηγῶν καὶ τῶν ταξιάρχων μήνυσις γένοιτο (περὶ δὲ τῶν ἄλλων ἀπέχρη ἐν τῇ βουλῇ [μήνυσις] μόνῃ γεγενημένη), ὥστε καὶ ἐκεῖ παράγουσιν ⟨αὐτὸν⟩ εἰς τὸν δῆμον. καί μοι ἀπόκριναι, ὦ Ἀγόρατε· οὐ γὰρ οἶμαί σε ἔξαρνον γενήσεσθαι ἃ ἐναντίον Ἀθηναίων ἁπάντων ἐποίησας.", "st": "13.32"}, {"sp": "N", "t": "<em>Ἐρώτησις<\/em>", "st": "13.33"}, {"sp": "N", "t": "ὁμολογεῖ μὲν καὶ αὐτός, ὅμως δὲ καὶ τὰ ψηφίσματα ὑμῖν τοῦ δήμου ἀναγνώσεται.", "st": "13.33"}, {"sp": "N", "t": "<em>Ψηφίσματα<\/em>", "st": "13.33"}, {"sp": "N", "t": "ὅτι μὲν ἀπέγραψεν Ἀγόρατος οὑτοσὶ τῶν ἀνδρῶν ἐκείνων τὰ ὀνόματα, καὶ τὰ ἐν τῇ βουλῇ καὶ τὰ ἐν τῷ δήμῳ, καὶ ἔστι φονεὺς ἐκείνων, σχεδόν τι οἶμαι ὑμᾶς ἐπίστασθαι· ὡς τοίνυν ἁπάντων τῶν κακῶν αἴτιος τῇ πόλει ἐγένετο καὶ οὐδ’ ὑφ’ ἑνὸς αὐτὸν προσήκει ἐλεεῖσθαι, ἐγὼ οἶμαι ὑμῖν ἐν κεφαλαίοις ἀποδείξειν.", "st": "13.33"}, {"sp": "N", "t": "ἐπειδὴ γὰρ ἐκεῖνοι συλληφθέντες ἐδέθησαν, τότε καὶ ὁ Λύσανδρος εἰς τοὺς λιμένας τοὺς ὑμετέρους εἰσέπλευσε, καὶ αἱ νῆες αἱ ὑμέτεραι Λακεδαιμονίοις παρεδόθησαν, καὶ τὰ τείχη κατεσκάφη, καὶ οἱ τριάκοντα κατέστησαν, καὶ τί οὐ τῶν δεινῶν τῇ πόλει ἐγένετο.", "st": "13.34"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν οἱ τριάκοντα κατεστάθησαν εὐθέως κρίσιν τοῖς ἀνδράσι τούτοις ἐποίουν ἐν τῇ βουλῇ, ὁ δὲ δῆμος “ἐν τῷ δικαστηρίῳ ἐν δισχιλίοις” ἐψήφιστο. καί μοι ἀνάγνωθι τὸ ψήφισμα.", "st": "13.35"}, {"sp": "N", "t": "<em>Ψήφισμα<\/em>", "st": "13.36"}, {"sp": "N", "t": "εἰ μὲν οὖν ἐν τῷ δικαστηρίῳ ἐκρίνοντο, ῥαδίως ἂν ἐσῴζοντο· ἅπαντες γὰρ ἤδη ἐγνωκότες ἦτε οὗ ἦν κακοῦ ἡ πόλις, ἐν ᾧ οὐδὲν ἔτι ὠφελεῖν ἐδύνασθε νῦν δ’ εἰς τὴν βουλὴν αὐτοὺς τὴν ἐπὶ τῶν τριάκοντα εἰσάγουσιν. ἡ δὲ κρίσις τοιαύτη ἐγίγνετο, οἵαν καὶ ὑμεῖς αὐτοὶ ἐπίστασθε.", "st": "13.36"}, {"sp": "N", "t": "οἱ μὲν γὰρ τριάκοντα ἐκάθηντο ἐπὶ τῶν βάθρων, οὗ νῖν οἱ πρυτάνεις καθέζονται· δύο δὲ τράπεζαι ἐν τῷ πρόσθεν τῶν τριάκοντα ἐκείσθην· τὴν δὲ ψῆφον οὐκ εἰς καδίσκους ἀλλὰ φανερὰν ἐπὶ τὰς τραπέζας ταύτας ἔδει τίθεσθαι, τὴν μὲν καθαιροῦσαν ἐπὶ τὴν ὑστέραν …, ὥστε ἐκ τίνος τρόπου ἔμελλέ τις αὐτῶν σωθήσεσθαι; ἑνὶ δὲ λόγῳ,", "st": "13.37"}, {"sp": "N", "t": "ὅσοι εἰς τὸ βουλευτήριον [ἐπὶ τῶν τριάκοντα] εἰσῆλθον κριθησόμενοι, ἁπάντων θάνατος κατεγιγνώσκετο καὶ οὐδενὸς ἀπεψηφίσαντο, πλὴν Ἀγοράτου τουτουί· τοῦτον δὲ ἀφεῖσαν ὡς εὐεργέτην ὄντα· ἵνα δὲ εἰδῆτε ὡς πολλοὶ ὑπὸ τούτου τεθνᾶσι, βούλομαι ὑμῖν τὰ ὀνόματα αὐτῶν ἀναγνῶναι.", "st": "13.38"}, {"sp": "N", "t": "<em>Ὀνόματα<\/em>", "st": "13.39"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν, ὦ ἄνδρες δικασταί, θάνατος αὐτῶν κατεγνώσθη καὶ ἔδει αὐτοὺς ἀποθνήσκειν, μεταπέμπονται εἰς τὸ δεσμωτήριον ὁ μὲν ἀδελφήν, ὁ δὲ μητέρα, ὁ δὲ γυναῖκα, ὁ δ’ ἥ τις ἦν ἑκάστῳ αὐτῶν προσήκουσα, ἵνα τὰ ὕστατα ἀσπασάμενοι τοὺς αὑτῶν οὕτω τὸν βίον τελευτήσειαν.", "st": "13.39"}, {"sp": "N", "t": "καὶ δὴ καὶ Διονυσόδωρος μεταπέμπεται τὴν ἀδελφὴν τὴν ἐμὴν εἰς τὸ δεσμωτήριον, γυναῖκα ἑαυτοῦ οὖσαν. πυθομένη δ’ ἐκείνη ἀφικνεῖται, μέλαν τε ἱμάτιον ἠμφιεσμένη …,", "st": "13.40"}, {"sp": "N", "t": "ὡς εἰκὸς ἦν ἐπὶ τῷ ἀνδρὶ αὐτῆς τοιαύτῃ συμφορᾷ κεχρημένῳ. ἐναντίον δὲ τῆς ἀδελφῆς τῆς ἐμῆς Διονυσόδωρος τά τε οἰκεῖα τὰ αὑτοῦ διέθετο ὅπως αὐτῷἐδόκει, καὶ περὶ Ἀγοράτου τουτουὶ ἔλεγεν ὅτι ⟨οἱ⟩ αἴτιος ἦν τοῦ θανάτου, καὶ ἐπέσκηπτεν ἐμοὶ καὶ Διονυσίῳ τουτῳί,", "st": "13.41"}, {"sp": "N", "t": "τῷ ἀδελφῷ τῷ αὑτοῦ, καὶ τοῖς φίλοις πᾶσι τιμωρεῖν ὑπὲρ αὑτοῦ Ἀγόρατον· καὶ τῇ γυναικὶ τῇ αὑτοῦ ἐπέσκηπτε, νομίζων αὐτὴν κυεῖν ἐξ αὑτοῦ, ἐὰν γένηται αὐτῇ παιδίον, φράζειν τῷ γενομένῳ ὅτι τὸν πατέρα αὐτοῦ Ἀγόρατος ἀπέκτεινε, καὶ κελεύειν τιμωρεῖν ὑπὲρ αὑτοῦ ὡς φονέα ὄντα. ὡς οὖν ἀληθῆ λέγω, μάρτυρας τούτων παρέξομαι.", "st": "13.42"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "13.43"}, {"sp": "N", "t": "οὗτοι μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ὑπ’ Ἀγοράτου ἀπογραφέντες ἀπέθανον· ἐπειδὴ δὲ τούτους ἐκποδὼν ἐποιήσαντο οἱ τριάκοντα, σχεδὸν οἶμαι ὑμᾶς ἐπίστασθαι ὡς πολλὰ καὶ δεινὰ μετὰ ταῦτα τῇ πόλει ἐγένετο· ὧν οὗτος ἁπάντων αἴτιός ἐστιν ἀποκτείνας ἐκείνους. ἀνιῶμαι μὲν οὖν ὑπομιμνῄσκων τὰς γεγενημένας συμφορὰς τῇ πόλει,", "st": "13.43"}, {"sp": "N", "t": "ἀνάγκη δ’ ἐστίν, ὦ ἄνδρες δικασταί, ἐν τῷ παρόντι καιρῷ, ἵν’ εἰδῆτε ὡς σφόδρα ὑμῖν ἐλεεῖν προσήκει Ἀγόρατον. ἴστε μὲν γὰρ τοὺς ἐκ Σαλαμῖνος τῶν πολιτῶν κομισθέντας, οἷοι ἦσαν καὶ ὅσοι, καὶ οἵῳ ὀλέθρῳ ὑπὸ τῶν τριάκοντα ἀπώλοντο· ἴστε δὲ τοὺς ἐξ Ἐλευσῖνος, ὡς πολλοὶ ταύτῃ τῇ συμφορᾷ ἐχρήσαντο· μέμνησθε δὲ καὶ τοὺς ἐνθάδε διὰ τὰς ἰδίας ἔχθρας ἀπαγομένους εἰς τὸ δεσμωτήριον·", "st": "13.44"}, {"sp": "N", "t": "οἵ οὐδὲν κακὸν τὴν πόλιν ποιήσαντες ἠναγκάζοντο αἰσχίστῳ καὶ ἀκλεεστάτῳ ὀλέθρῳ ἀπόλλυσθαι, οἱ μὲν γονέας [σφετέρους αὐτῶν] πρεσβύτας καταλιπόντες, οἳ ἤλπιζον ὑπὸ τῶν σφετέρων αὐτῶν παίδων γηροτροφηθέντες, ἐπειδὴ τελευτήσειαν τὸν βίον, ταφήσεσθαι, οἱ δὲ ἀδελφὰς ἀνεκδότους, οἱ δὲ παῖδας μικροὺς πολλῆς ἔτι θεραπείας δεομένους·", "st": "13.45"}, {"sp": "N", "t": "οὕς, ὦ ἄνδρες δικασταί, ποίαν τινὰ οἴεσθε γνώμην περὶ τούτου ἔχειν, ἢ ποίαν τινὰ ἂν ψῆφον θέσθαι, εἰ ἐπ’ ἐκείνοις γένοιτο, ἀποστερηθέντας διὰ τοῦτον τῶν ἡδίστων; ἔτι δὲ τὰ τείχη ὡς κατεσκάφη καὶ αἱ νῆες τοῖς πολεμίοις παρεδόθησαν καὶ ⟨τὰ⟩ νεώρια καθῃρέθη καὶ Λακεδαιμόνιοι τὴν ἀκρόπολιν ἡμῶν εἶχον καὶ ἡ δύναμις ἅπασα τῆς πόλεως παρελύθη, ὥστε μηδὲν διαφέρειν τῆς ἐλαχίστης πόλεως τὴν πόλιν.", "st": "13.46"}, {"sp": "N", "t": "πρὸς δὲ τούτοις τὰς ἰδίας ⟨οὐσίας⟩ ἀπωλέσατε, καὶ τὸ τελευταῖον συλλήβδην ἅπαντες ὑπὸ τῶν τριάκοντα ἐκ τῆς πατρίδος ἐξηλάθητε. ταῦτα ἐκεῖνοι οἱ ἀγαθοὶ ἄνδρες αἰσθόμενοι οὐκ ἔφασαν ἐπιτρέψειν τὴν εἰρήνην, ὦ ἄνδρες δικασταί, ποιήσασθαι·", "st": "13.47"}, {"sp": "N", "t": "οὓς σύ, Ἀγόρατε, βουλομένους ἀγαθόν τι πρᾶξαι τῇ πόλει ἀπέκτεινας, μηνύσας αὐτοὺς [τῇ πόλει] ἐπιβουλεύειν τῷ πλήθει τῷ ὑμετέρῳ, καὶ αἴτιος εἶ ἁπάντων τῇ πόλει τῶν κακῶν τῶν γεγενημένων. νῦν οὖν μνησθέντες καὶ τῶν ἰδίων ἕκαστος δυστυχημάτων καὶ τῶν κοινῶν τῆς πόλεως τιμωρεῖσθε τὸν αἴτιον τούτων.", "st": "13.48"}, {"sp": "N", "t": "θαυμάζω δ’ ἔγωγε, ὦ ἄνδρες δικασταί, ὅ τί ποτε τολμήσει πρὸς ὑμᾶς ἀπολογεῖσθαι· δεῖ γὰρ αὐτὸν ἀποδεῖξαι ὡς οὐ κατεμήνυσε τῶν ἀνδρῶν τούτων οὐδ’ αἴτιος αὐτοῖς ἐστι τοῦ θανάτου, ὃ οὐκ ἂν δύναιτο οὐδέποτε ἀποδεῖξαι.", "st": "13.49"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ τὰ ψηφίσματα αὐτοῦ τὰ ἐκ τῆς βουλῆς καὶ ⟨τὸ⟩ τοῦ δήμου καταμαρτυρεῖ, διαρρήδην ἀγορεύοντα “περὶ ὧν Ἀγόρατος κατείρηκεν.” ἔπειτα ἡ κρίσις, ἣν ἐκρίθη ἐπὶ τῶν τριάκοντα καὶ ἀφείθη, διαρρήδην λέγει, “διότι” φησίν “ἔδοξε τἀληθῆ εἰσαγγεῖλαι.” καί μοι ἀνάγνωθι.", "st": "13.50"}, {"sp": "N", "t": "<em>Ψηφίσματα. Γνῶσις. [Γραφαί]<\/em>", "st": "13.51"}, {"sp": "N", "t": "ὡς μὲν οὖν οὐκ ἀπέγραψεν, οὐδενὶ τρόπῳ δύναιτ’ ἂν ἀποδεῖξαι· δεῖ τοίνυν αὐτὸν ὡς δικαίως ἐμήνυσε ταῦτα ἀποφαίνειν, ὁρῶν αὐτοὺς πονηρὰ καὶ οὐκ ἐπιτήδεια τῷ δήμῳ τῷ ὑμετέρῳ πράττοντας. οἴομαι δ’ οὐδ’ ἂν τοῦτο αὐτὸν ἐπιχειρῆσαι ἀποδεικνύναι. οὐ γὰρ δήπου, εἴ τι κακὸν τὸν δῆμον τὸν Ἀθηναίων εἰργάσαντο, οἱ τριάκοντα, δεδιότες μὴ καταλυθείη ἂν ὁ δῆμος, τιμωροῦντες ὑπὲρ τοῦ δήμου ἂν αὐτοὺς ἀπέκτειναν, ἀλλ’ οἶμαι πολὺ τοὐναντίον τούτου.", "st": "13.51"}, {"sp": "N", "t": "ἀλλ’ ἴσως φήσει ἄκων τοσαῦτα κακὰ ἐργάσασθαι. ἐγὼ δ’ οὐκ οἶμαι, ὦ ἄνδρες δικασταί, οὐδ’ ἐάν τις ὑμᾶς ὡς μάλιστα ἄκων μεγάλα κακὰ ἐργάσηται, ὧν μὴ οἷόν τε γενέσθαι ἐστὶν ὑπερβολήν, οὐ τούτου ἕνεκα οὐ δεῖν ὑμᾶς ἀμύνεσθαι. εἶτα δὲ καὶ ἐκείνων μέμνησθε, ὅτι ἐξῆν Ἀγοράτῳ τουτῳί, πρὶν εἰς τὴν βουλὴν κομισθῆναι· καὶ γὰρ πλοῖα παρεσκεύαστο Μουνιχίασι, σωθῆναι· καὶ γὰρ πλοῖα παρεσκεύαστο καὶ ⟨οἱ⟩ ἐγγυηταὶ ἕτοιμοι ἦσαν συναπιέναι.", "st": "13.52"}, {"sp": "N", "t": "καίτοι εἰ ἐκείνοις ἐπίθου καὶ ἠθέλησας ἐκπλεῦσαι μετ’ ἐκείνων, οὔτ’ ἂν ἑκὼν οὔτε ἄκων τοσούτους Ἀθηναίων ἀπέκτεινας· νῦν δὲ πεισθεὶς ὑφ’ ὧν τότε ἐπείσθης, εἰ τῶν στρατηγῶν καὶ τῶν ταξιάρχων τὰ ὀνόματα μόνον εἴποις, μέγα τι ᾤου παρ’ αὐτῶν διαπράξεσθαι. οὔκουν τούτου ἕνεκα δεῖ σε παρ’ ἡμῶν συγγνώμης τινὸς τυχεῖν, ἐπεὶ οὐδὲ ἐκεῖνοι παρὰ σοῦ οὐδεμιᾶς ἔτυχον, οὓς σὺ ἀπέκτεινας.", "st": "13.53"}, {"sp": "N", "t": "καὶ Ἱππίας μὲν ὁ Θάσιος καὶ Ξενοφῶν ὁ Κουριεύς, οἳ ἐπὶ τῇ αὐτῇ αἰτία τούτῳ ὑπὸ τῆς βουλῆς μετεπέμφθησαν, οὗτοι μὲν ἀπέθανον, ὁ μὲν στρεβλωθείς, Ξενοφῶν, ὁ δὲ Ἱππίας οὕτω …, διότι οὐκ ἄξιοι ἐδόκουν τοῖς τριάκοντα σωτηρίας εἶναι (οὐδένα γὰρ Ἀθηναίων ἀπώλλυσαν)· Ἀγόρατος δὲ ἀφείθη, διότι ἐδόκει ἐκείνοις τὰ ἥδιστα πεποιηκέναι.", "st": "13.54"}, {"sp": "N", "t": "ἀκούω δ’ αὐτὸν καὶ εἰς Μενέστρατον ἀναφέρειν τι περὶ τῶν ἀπογραφῶν τούτων. τὸ δὲ τοῦ Μενεστράτου πρᾶγμα τοιοῦτον ἐγένετο. ὁ Μενέστρατος οὗτος ἀπεγράφη ὑπὸ τοῦ Ἀγοράτου καὶ συλληφθεὶς ἐδέδετο· Ἁγνόδωρος δ’ ἦν Ἀμφιτροπαιεύς, δημότης τοῦ Μενεστράτου, Κριτίου κηδεστὴς τοῦ τῶν τριάκοντα. οὗτος οὖν, ὅτε ἡ ἐκκλησία Μουνιχίασιν ἐν τῷ θεάτρῳ ἐγίγνετο, ἅμα μὲν βουλόμενος τὸν Μενέστρατον σωθῆναι, ἅμα δὲ ὡς πλείστους ἀπογραφέντας ἀπολέσθαι, παράγει αὐτὸν εἰς τὸν δῆμον, καὶ εὑρίσκονται αὐτῷ κατὰ τὸ ψήφισμα τουτὶ ἄδειαν.", "st": "13.55"}, {"sp": "N", "t": "<em>Ψήφισμα<\/em>", "st": "13.56"}, {"sp": "N", "t": "ἐπειδὴ δὲ τοῦτο τὸ ψήφισμα ἐγένετο, μηνύει ὁ Μενέστρατος καὶ προσαπογράφει ἑτέρους τῶν πολιτῶν. τοῦτον μέντοι οἱ μὲν τριάκοντα ἀφεῖσαν ὥσπερ Ἀγόρατον τουτονί, δόξαντα τἀληθῆ εἰσαγγεῖλαι, ὑμεῖς δὲ πολλῷ χρόνω ὕστερον λαβόντες ἐν δικαστηρίῳ ὡς ἀνδροφόνον ὄντα, θάνατον δικαίως καταψηφισάμενοι τῷ δημίῳ παρέδοτε καὶ ἀπετυμπανίσθη.", "st": "13.56"}, {"sp": "N", "t": "καίτοι εἰ ἐκεῖνος ἀπέθανεν, ἦ που Ἀγόρατός γε δικαίως ἀποθανεῖται, ὅς γε τόν τε Μενέστρατον ἀπογράψας αἴτιος ἐκείνῳ ἐστὶ τοῦ θανάτου, καὶ τοῖς ὑπὸ Μενεστράτου ἀπογραφεῖσι τίς αἰτιώτερος ἢ ὁ εἰς τοιαύτην ἀνάγκην ἐκεῖνον καταστήσας;", "st": "13.57"}, {"sp": "N", "t": "ἀνόμοιος δέ μοι δοκεῖ Ἀριστοφάνει γενέσθαι τῷ Χολλείδῃ, ὃς ἐγγυητὴς τότε τούτου ἐγένετο καὶ τὰ πλοῖα παρασκευάσας Μουνιχίασιν ἕτοιμος ἦν συνεκπλεῖν μετὰ τούτου. καὶ τό γε ἐπ’ ἐκεῖνον εἶναι ἐσώθης, καὶ οὔτ’ ἂν Ἀθηναίων οὐδένα ἀπώλεσας οὔτ’ ἂν αὐτὸς σὺ εἰς τοιούτους κινδύνους κατέστης·", "st": "13.58"}, {"sp": "N", "t": "νῦν δὲ καὶ τὸν σωτῆρα τὸν σαυτοῦ ἐτόλμησας ἀπογράψαι, καὶ ἀπογράψας ⟨ἀπέκτεινας⟩ καὶ ἐκεῖνον καὶ τοὺς ἄλλους ἐγγυητάς. τοῦτον μέντοι ὡς οὐ καθαρῶς Ἀθηναῖον ὄντα ἐβούλοντό τινες βασανισθῆναι, καὶ τουτὶ τὸ ψήφισμα τὸν δῆμον ἀναπείθουσι ψηφίζεσθαι.", "st": "13.59"}, {"sp": "N", "t": "<em>Ψήφισμα<\/em>", "st": "13.60"}, {"sp": "N", "t": "μετὰ τοῦτο τοίνυν προσιόντες τῷ Ἀριστοφάνει οἱ πράττοντες τότε τὰ πράγματα ἐδέοντο αὐτοῦ κατειπεῖν καὶ σῴζεσθαι, καὶ μὴ κινδυνεύειν ἀγωνισάμενον τῆς ξενίας τὰ ἔσχατα παθεῖν. ὁ δὲ οὐκ ἔφη οὐδέποτε· οὕτω χρηστὸς ἦν καὶ περὶ τοὺς δεδεμένους καὶ περὶ τὸν δῆμον τὸν Ἀθηναίων, ὥστε εἵλετο μᾶλλον ἀποθανεῖν ἢ κατειπεῖν καὶ ἀδίκως τινὰς ἀπολέσαι.", "st": "13.60"}, {"sp": "N", "t": "ἐκεῖνος μὲν τοίνυν καὶ ὑπὸ σοῦ ἀπολλύμενος τοιουτοσὶ ἐγένετο [καὶ Ξενοφῶν ὁ στρεβλωθεὶς καὶ Ἱππίας ὁ Θάσιος]. σὺ δ’ οὐδὲν τοῖς ἀνδράσιν ἐκείνοις συνειδώς, πεισθεὶς δὲ ὡς σύ γε, ἐὰν ἐκεῖνοι ἀπόλωνται, μεθέξεις τῆς τότε πολιτείας καθισταμένης, ἀπέγραψας καὶ ἀπέκτεινας Ἀθηναίων πολλοὺς καὶ ἀγαθούς.", "st": "13.61"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν, ὦ ἄνδρες δικασταί, ἐπιδεῖξαι οἵων ἀνδρῶν ὑπ’ Ἀγοράτου ἀπεστέρησθε. εἰ μὲν οὖν οὐ πολλοὶ ἦσαν, καθ’ ἕκαστον ἂν περὶ αὐτῶν ἠκούετε, νῦν δὲ συλλήβδην περὶ πάντων. οἱ μὲν γὰρ στρατηγήσαντες ὑμῖν πολλάκις μείζω τὴν πόλιν τοῖς διαδεχομένοις στρατηγοῖς παρεδίδοσαν·", "st": "13.62"}, {"sp": "N", "t": "οἱ δ’ ἑτέρας μεγάλας ἀρχὰς ἄρξαντες καὶ τριηραρχίας πολλὰς τριηραρχήσαντες οὐδεπώποτε ὑφ’ ὑμῶν οὐδεμίαν αἰτίαν αἰσχρὰν ἔσχον. οἱ δ’ αὐτῶν περιγενόμενοι καὶ σωθέντες, οὓς οὗτος μὲν ἀπέκτεινεν ὁμοίως καὶ θάνατος αὐτῶν κατεγνώσθη, ἡ δὲ τύχη καὶ ὁ δαίμων περιεποίησε, φυγόντες [γὰρ] ἐνθένδε καὶ οὐ συλληφθέντες οὐδὲ ὑπομείναντες μείναντες τὴν κρίσιν, κατελθόντες ἀπὸ Φυλῆς τιμῶνται ὑφ’ ὑμῶν ὡς ἄνδρες ἀγαθοὶ ὄντες.", "st": "13.63"}, {"sp": "N", "t": "τούτους μέντοι τοιούτους ὄντας Ἀγόρατος τοὺς μὲν ἀπέκτεινε, τοὺς δὲ φυγάδας ἐντεῦθεν ἐποίησε, τίς ὢν αὐτός; δεῖ γὰρ ὑμᾶς εἰδέναι ὅτι δοῦλος καὶ ἐκ δούλων ἐστίν, ἵν’ εἰδῆτε οἷος ὢν ὑμᾶς ἐλυμαίνετο. τουτῳὶ μὲν γὰρ πατὴρ ἦν Εὐμάρης, ἐγένετο δὲ ὁ Εὐμάρης οὗτος Νικοκλέους καὶ Ἀντικλέους. καί μοι ἀνάβητε μάρτυρες.", "st": "13.64"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "13.65"}, {"sp": "N", "t": "ἦσαν τοίνυν οὗτοι, ὦ ἄνδρες δικασταί, τέτταρες ἀδελφοί. τούτων εἷς μὲν ὁ πρεσβύτατος ἐν Σικελία παραφρυκτωρευόμενος τοῖς πολεμίοις ληφθεὶς ὑπὸ Λαμάχου ἀπετυμπανίσθη· ὁ δὲ ἕτερος εἰς Κόρινθον μὲν ἐντευθενὶ ἀνδράποδον ἐξήγαγεν, ἐκεῖθεν δὲ παιδίσκην αὖθις ἐξάγων ἁλίσκεται, καὶ ἐν τῷ δεσμωτηρίῳ δεδεμένος ἀπέθανε· τὸν δὲ τρίτον Φαινιππίδης ἐνθάδε λωποδύτην ἀπήγαγε,", "st": "13.65"}, {"sp": "N", "t": "καὶ ὑμεῖς κρίναντες αὐτὸν ἐν τῷ δικαστηρίῳ καὶ καταγνόντες αὐτοῦ θάνατον ἀποτυμπανίσαι παρέδοτε. ὡς δὲ ἀληθῆ λέγω, καὶ αὐτὸν οἶμαι ὁμολογήσειν τοῦτον καὶ μάρτυρας παρεξόμεθα.", "st": "13.66"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "13.67"}, {"sp": "N", "t": "τἆλλα τοίνυν, ὦ ἄνδρες δικασταί, ὅσα κακὰ καὶ αἰσχρὰ καὶ τούτῳ καὶ τοῖς τούτου ἀδελφοῖς ἐπιτετήδευται, πολὺ ἂν εἴη ἔργον λέγειν. περὶ δὲ συκοφαντίας, ὅσας οὗτος ἢ δίκας ἰδίας συκοφαντῶν ἐδικάζετο ἢ γραφὰς ὅσας ἐγράφετο ἢ ἀπογραφὰς ἀπέγραφεν, οὐδὲν με δεῖ καθ’ ἕκαστον λέγειν· συλλήβδην γὰρ ὑμεῖς ἅπαντες καὶ ἐν τῷ δήμῳ καὶ ἐν τῷ δικαστηρίῳ συκοφαντίας αὐτοῦ κατέγνωτε καὶ ὦφλεν ὑμῖν μυρίας δραχμάς,", "st": "13.67"}, {"sp": "N", "t": "ὥστε τοῦτο μὲν ἱκανῶς ὑπὸ ὑμῶν ἁπάντων μεμαρτύρηται. γυναῖκας τοίνυν τῶν πολιτῶν τοιοῦτος ὢν μοιχεύειν καὶ διαφθείρειν ἐλευθέρας ἐπεχείρησε, καὶ ἐλήφθη μοιχός· καὶ τούτου θάνατος ἡ ζημία ἐστίν. ὡς δὲ ἀληθῆ λέγω, μάρτυρας κάλει.", "st": "13.68"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "13.69"}, {"sp": "N", "t": "πῶς οὖν οὐχ ἅπασι προσήκει ὑμῖν τούτου καταψηφίζεσθαι; εἰ γὰρ τούτων ἕκαστος δι’ ἓν ἁμάρτημα θανάτου ἠξιώθη, ἦ που τοῦ γε πολλὰ ἐξημαρτηκότος καὶ δημοσίᾳ εἰς τὴν πόλιν καὶ ἰδίᾳ εἰς ἕκαστον ὑμῶν, ὧν ἑκάστου ἁμαρτήματος ἐν τοῖς νόμοις θάνατος ἡ ζημία ἐστί, δεῖ ὑμᾶς σφόδρα θάνατον αὐτοῦ καταψηφίσασθαι.", "st": "13.69"}, {"sp": "N", "t": "λέξει δέ, ὦ ἄνδρες δικασταί, καὶ ἐξαπατῆσαι ὑμᾶς πειράσεται, ὡς ἐπὶ τῶν τετρακοσίων Φρύνιχον ἀπέκτεινε, καὶ ἀντὶ τούτου φησιν αὐτὸν Ἀθηναῖον τὸν δῆμον ποιήσασθαι, ψευδόμενος, ὦ ἄνδρες δικασταί· οὔτε γὰρ Φρύνιχον ἀπέκτεινεν οὔτε Ἀθηναῖον αὐτὸν ὁ δῆμος ἐποιήσατο.", "st": "13.70"}, {"sp": "N", "t": "Φρυνίχῳ γάρ, ὦ ἄνδρες δικασταί, κοινῇ Θρασύβουλός τε ὁ Καλυδώνιος καὶ Ἀπολλόδωρος ὁ Μεγαρεὺς ἐπεβούλευσαν· ἐπειδὴ δὲ ἐπετυχέτην αὐτῷ βαδίζοντι, ὁ μὲν Θρασύβουλος τύπτει τὸν Φρύνιχον καὶ καταβάλλει πατάξας, ὁ δὲ Ἀπολλόδωρος οὐχ ἥψατο· ἀλλ’ ἐν τούτῳ κραυγὴ γίγνεται καὶ ᾤχοντο φεύγοντες. Ἀγόρατος δὲ οὑτοσὶ οὔτε παρεκλήθη οὔτε παρεγένετο οὔτε οἶδε τοῦ πράγματος οὐδέν. ὡς δὲ ἀληθῆ λέγω, αὐτὸ ὑμῖν τὸ ψήφισμα δηλώσει.", "st": "13.71"}, {"sp": "N", "t": "<em>Ψήφισμα<\/em>", "st": "13.72"}, {"sp": "N", "t": "ὅτι μὲν οὐκ ἀπέκτεινε Φρύνιχον, ἐξ αὐτοῦ τοῦ ψηφίσματος δῆλον· οὐδαμοῦ γάρ ἐστιν “Ἀγόρατον Ἀθηναῖον εἶναι” ὥσπερ Θρασύβουλον [καὶ Ἀπολλόδωρον]. καίτοι εἴπερ ἀπέκτεινε Φρύνιχον, ἔδει αὐτὸν ἐν τῇ αὐτῇ στήλῃ, ἵνα περ Θρασύβουλον [καὶ Ἀπολλόδωρον], Ἀθηναῖον πεποιημένον ⟨ἐγγεγράφθαι⟩· τὰ μέντοι ὀνόματα διαπράττονται σφῶν αὐτῶν, δόντες ἀργύριον τῷ ῥήτορι, προσγραφῆναι εἰς τὴν στήλην ὡς εὐεργέτας ὄντας. καὶ ὡς ἀληθῆ λέγω, τοῦτο τὸ ψήφισμα ἐλέγξει.", "st": "13.72"}, {"sp": "N", "t": "<em>Ψήφισμα<\/em>", "st": "13.73"}, {"sp": "N", "t": "οὕτω μέντοι οὑτοσὶ πολὺ ὑμῶν κατεφρόνει, ὥστε οὐκ ὢν Ἀθηναῖος καὶ ἐδίκαζε καὶ ἠκκλησίαζε καὶ γραφὰς τὰς ἐξ ἀνθρώπων ἐγράφετο, ἐπιγραφόμενος Ἀναγυράσιος, εἶναι. ἔπειτα δὲ καὶ ἕτερον μέγα τεκμήριον ὡς οὐκ [ἂν] ἀπέκτεινε Φρύνιχον, δι’ ὃ Ἀθηναῖός φησι γεγενῆσθαι. ὁ Φρύνιχος γὰρ οὗτος τοὺς τετρακοσίους κατέστησεν· ἐπειδὴ δ’ ἐκεῖνος ἀπέθανεν, οἱ πολλοὶ τῶν τετρακοσίων ἔφυγον.", "st": "13.73"}, {"sp": "N", "t": "πότερον οὖν δοκοῦσιν ὑμῖν οἱ τριάκοντα καὶ ἡ βουλὴ ἡ τότε βουλεύουσα, οἳ αὐτοὶ ἦσαν ἅπαντες τῶν τετρακοσίων τῶν φυγόντων, ἀφεῖναι ἂν λαβόντες τὸν Φρύνιχον ἀποκτείναντα, ἢ τιμωρήσασθαι ὑπὲρ Φρυνίχου καὶ τῆς φυγῆς ἧς αὐτοὶ ἔφυγον;", "st": "13.74"}, {"sp": "N", "t": "ἐγὼ μὲν οἶμαι τιμωρεῖσθαι ἄν. εἰ μὲν οὖν μὴ ἀποκτείνας προσποιεῖται, ὡς ἐγώ φημι, ἀδικεῖ· εἰ δὲ ἀμφισβητεῖς καὶ φῂς Φρύνιχον ἀποκτεῖναι, δῆλον ὅτι μείζω τὸν δῆμον τὸν Ἀθηναίων κακὰ ποιήσας τὴν ὑπὲρ Φρυνίχου αἰτίαν πρὸς τοὺς τριάκοντα ἀπελύσω· οὐδέποτε γὰρ πείσεις οὐδένα ἀνθρώπων ὡς Φρύνιχον ἀποκτείνας ἀφείθης ἂν ὑπὸ τῶν τριάκοντα, εἰ μὴ μεγάλα τὸν δῆμον τὸν Ἀθηναίων καὶ ἀνήκεστα κακὰ εἰργάσω.", "st": "13.75"}, {"sp": "N", "t": "ἐὰν μὲν οὖν φάσκῃ Φρύνιχον ἀποκτεῖναι, τούτων μέμνησθε καὶ τοῦτον τιμωρεῖσθε ἀνθ’ ὧν ἐποίησεν· ἐὰν δ’ οὐ φάσκῃ, ἔρεσθε αὐτὸν δι’ ὅ τι φησὶν Ἀθηναῖος ποιηθῆναι. ἐὰν δὲ μὴ ἔχῃ ἀποδεῖξαι, τιμωρεῖσθε αὐτὸν ὅτι καὶ ἐδίκαζε καὶ ἠκκλησίαζε καὶ ἐσυκοφάντει πολλοὺς ὡς Ἀθηναῖος τοὔνομα ἐπιγραφόμενος.", "st": "13.76"}, {"sp": "N", "t": "ἀκούω δὲ αὐτὸν παρασκευάζεσθαι ἀπολογεῖσθαι, ὡς ἐπὶ Φυλήν τε ᾤχετο καὶ συγκατῆλφεν ἀπὸ Φυλῆς, καὶ τοῦτο μέγιστον ἀγώνισμα εἶναι. ἐγένετο δὲ τοιοῦτον· ἦλθεν οὗτος ἐπὶ Φυλήν· καίτοι πῶς ἂν γένοιτο ἄνθρωπος μιαρώτερος; ὅστις εἰδὼς ὅτι εἰσί τινες ἐπὶ Φυλῇ τῶν ὑπὸ τούτου ἐκπεπτωκότων ἐτόλμησεν ἐλθεῖν ὡς τούτους. ἐπειδὴ δὲ εἶδον αὐτὸν τάχιστα,", "st": "13.77"}, {"sp": "N", "t": "συλλαβόντες ἄγουσιν ἄντικρυς ὡς ἀποκτενοῦντες, οὗπερ καὶ τοὺς ἄλλους ἀπέσφαττον, εἴ τινα λῃστὴν ἢ κακοῦργον συλλάβοιεν. στρατηγῶν δὲ Ἄνυτος [ἐπὶ Φυλὴν] οὐκ ἔφη χρῆναι ποιεῖν αὐτοὺς ταῦτα, λέγων ὅτι ⟨οὔπω⟩ οὕτω διακέοιντο, ὥστε τιμωρεῖσθαί τινας τῶν ἐχθρῶν, ἀλλὰ νῦν μὲν δεῖν αὐτοὺς ἡσυχίαν ἔχειν. εἰ δέ ποτε οἴκαδε κατέλθοιεν, τότε καὶ τιμωρήσοιντο τοὺς ἀδικοῦντας.", "st": "13.78"}, {"sp": "N", "t": "ταῦτα λέγων αἴτιος ἐγένετο τοῦ ἀποφυγεῖν τοῦτον ἐπὶ Φυλῇ· ἀνάγκη δὲ ἦν στρατηγοῦ ἀνδρὸς ἀκροᾶσθαι, εἴπερ ἔμελλον σωθήσεσθαι. ἀλλ’ ἕτερον· οὔτε γὰρ συσσιτήσας τούτῳ οὐδεὶς φανήσεται οὔτε σύσκηνος γενόμενος οὔτε ⟨ὁ⟩ ταξίαρχος εἰς τὴν φυλὴν κατατάξας, ἀλλ’ ὥσπερ ἀλιτηρίῳ οὐδεὶς ἀνθρώπων αὐτῷ διελέγετο. καί μοι κάλει τὸν ταξίαρχον.", "st": "13.79"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "13.80"}, {"sp": "N", "t": "ἐπειδὴ δὲ ⟨αἱ⟩ διαλλαγαὶ πρὸς ἀλλήλους ἐγένοντο καὶ ἔπεμψαν οἱ [πολῖται] ἐκ Πειραιῶς τὴν πομπὴν εἰς πόλιν, ἡγεῖτο μὲν Αἴσιμος [τῶν πολιτῶν], οὗτος δὲ οὕτω τολμηρὸς καὶ ἐκεῖ ἐγένετο· συνηκολούθει γὰρ λαβὼν τὰ ὅπλα καὶ συνέπεμπε τὴν πομπὴν μετὰ τῶν ὁπλιτῶν πρὸς τὸ ἄστυ.", "st": "13.80"}, {"sp": "N", "t": "ἐπειδὴ δὲ πρὸς ταῖς πύλαις ἦσαν καὶ ἔθεντο τὰ ὅπλα, πρὶν εἰσιέναι εἰς τὸ ἄστυ, ὁ μὲν Αἴσιμος αἰσθάνεται καὶ προσελθὼν τήν τε ἀσπίδα αὐτοῦ λαβὼν ἔρριψε, καὶ ἀπιέναι ἐκέλευσεν ἐς κόρακας [ἐκ τῶν πολιτῶν.] οὐ γὰρ ἔφη δεῖν ἀνδροφόνον αὐτὸν ὄντα συμπέμπειν τὴν πομπὴν τῇ Ἀθηνᾷ. τούτῳ τῷ τρόπῳ ὑπὸ Αἰσίμου ἀπηλάθη. ὡς δ’ ἀληθῆ λέγω, μάρτυρας παρέξομαι.", "st": "13.81"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "13.82"}, {"sp": "N", "t": "τούτῳ τῷ τρόπῳ, ὦ ἄνδρες δικασταί, καὶ ἐπὶ Φυλῇ καὶ ἐν Πειραιεῖ πρὸς τοὺς ὁπλίτας διέκειτο· οὐδεὶς γὰρ αὐτῷ διελέγετο ὡς ἀνδροφόνῳ ὄντι, τοῦ τε μὴ ἀποθανεῖν Ἄνυτος ἐγένετο αὐτῷ αἴτιος. ἐὰν οὖν τῇ ἐπὶ Φυλὴν ὁδῷ ἀπολογίᾳ χρῆται, ὑπολαμβάνειν χρὴ εἰ Ἄνυτος αὐτῷ ἐγένετο αἴτιος μὴ ἀποθανεῖν ἑτοίμων ὄντων τιμωρεῖσθαι, καὶ ἔρριψεν αὐτοῦ Αἴσιμος τὴν ἀσπίδα καὶ οὐκ εἴα [μετὰ τῶν πολιτῶν] συμπέμπειν τὴν πομπήν, [καὶ εἴ τις αὐτὸν ταξίαρχος εἰς τάξιν τινὰ κατέταξε].", "st": "13.82"}, {"sp": "N", "t": "μήτε οὖν ταῦτα αὐτοῦ ἀποδέχεσθε, μήτ’ ἐὰν λέγῃ ὅτι πολλῷ χρόνῳ ὕστερον τιμωρούμεθα. οὐ γὰρ οἶμαι οὐδεμίαν τῶν τοιούτων ἀδικημάτων προθεσμίαν εἶναι, ἀλλ’ ἐγὼ μὲν οἶμαι, εἴτ’ εὐθὺς εἴτε χρόνῳ τις τιμωρεῖται, τοῦτον δεῖν ἀποδεικνύναι ὡς οὐ πεποίηκε περὶ ὧν ἐστιν ἡ αἰτία.", "st": "13.83"}, {"sp": "N", "t": "οὗτος τοίνυν τοῦτο ἀποφαινέτω, ἢ ὡς οὐκ ἀπέκτεινεν ἐκείνους ἢ ὡς δικαίως, κακόν τι ποιοῦντας τὸν δῆμον τὸν Ἀθηναίων. εἰ δὲ πάλαι δέον τιμωρεῖσθαι ὕστερον ἡμεῖς τιμωρούμεθα, τὸν χρόνον κερδαίνει ὃν ἔζη οὐ προσῆκον αὐτῷ, οἱ δὲ ἄνδρες ὑπὸ τούτου οὐδὲν ἧττον τεθνήκασιν.", "st": "13.84"}, {"sp": "N", "t": "ἀκούω δ’ αὐτὸν καὶ ⟨τούτῳ⟩ διισχυρίζεσθαι, ὅτι “ἐπ’ αὐτοφώρῳ” τῇ ἀπαγωγῇ ἐπιγέγραπται, ὃ πάντων ἐγὼ οἶμαι εὐηθέστατον· ὡς εἰ μὲν τὸ ἐπ’ αὐτοφώρῳ μὴ προσεγέγραπτο, ἔνοχος ⟨ἂν⟩ ὢν τῇ ἀπαγωγῇ· διότι δὲ τοῦτο προσγέγραπται, [ἔνοχος ὢν] ῥᾳστώνην τινὰ οἴεται αὑτῷ εἶναι. τοῦτο δὲ οὐδὲν ἄλλο ἔοικεν ἢ ὁμολογεῖν ἀποκτεῖναι, μὴ ἐπ’ αὐτοφώρῳ δέ, καὶ περὶ τούτου διισχυρίζεσθαι, ὥσπερ, εἰ μὴ ἐπ’ αὐτοφώρῳ μέν, ἀπέκτεινε δέ, τούτου ἕνεκα δέον αὐτὸν σῴζεσθαι.", "st": "13.85"}, {"sp": "N", "t": "δοκοῦσι δ’ ἔμοιγε οἱ ἕνδεκα οἱ παραδεξάμενοι τὴν ἀπαγωγὴν ταύτην, ⟨οὐκ⟩ οἰόμενοι Ἀγοράτῳ συμπράττειν καὶ τότε διισχυριζομένῳ, σφόδρα ὀρθῶς ποιῆσαι Διονύσιον τὴν ἀπαγωγὴν ἀπάγοντ’ ἀναγκάζοντες τό γε προσγράψασθαι ἐπ’ αὐτοφώρῳ· ἢ πῶς οὐκ ἂν εἴη ⟨ὃς⟩ πρῶτον μὲν ἐναντίον πεντακοσίων ⟨ἐν τῇ βουλῇ⟩, εἶτα πάλιν ἐναντίον Ἀθηναίων ἁπάντων [ἐν τῷ δήμῳ] ἀπογράψας τινὰς ἀποκτείνειε καὶ αἴτιος γένοιτο τοῦ θανάτου;", "st": "13.86"}, {"sp": "N", "t": "οὐ γὰρ δήπου τοῦτο μόνον οἴει τὸ ἐπ’ αὐτοφώρῳ, ἐάν τις ξύλῳ ἢ μαχαίρᾳ πατάξας καταβάλῃ, ἐπεὶ ἔκ γε τοῦ σοῦ λόγου οὐδεὶς φανήσεται ἀποκτείνας τοὺς ἄνδρας οὓς σὺ ἀπέγραψας· οὔτε γὰρ ἐπάταξεν αὐτοὺς οὐδεὶς οὔτ’ ἀπέσφαξεν, ἀλλ’ ἀναγκασθέντες ὑπὸ τῆς σῆς ἀπογραφῆς ἀπέθανον. οὐκ οὖν ⟨ὁ⟩ αἴτιος τοῦ θανάτου, οὗτος ἐπ’ αὐτοφώρῳ ἐστί; τίς οὖν ἄλλος αἴτιος ἢ σὺ ἀπογράψας; ὥστε πῶς οὐκ ἐπ’ αὐτοφώρῳ σὺ εἶ ὁ ἀποκτείνας;", "st": "13.87"}, {"sp": "N", "t": "πυνθάνομαι δ’ αὐτὸν καὶ περὶ τῶν ὅρκων καὶ περὶ τῶν συνθηκῶν μέλλειν λέγειν, ὡς παρὰ τοὺς ὅρκους καὶ τὰς συνθήκας ἀγωνίζεται ἃς συνεθέμεθα πρὸς τοὺς ἐν ἄστει οἱ ἐν [τῷ] Πειραιεῖ. σχεδὸν μὲν οὖν τούτοις ἰσχυριζόμενος ὁμολογεῖ ἀνδροφόνος εἶναι· ἐμποδὼν γοῦν ἢ ὅρκους ἢ συνθήκας ἢ χρόνον ἢ ⟨τὸ⟩ ἐπ’ αὐτοφώρῳ [τι] ποιεῖται, αὐτῷ δὲ τῷ πράγματι οὔ τι πιστεύει καλῶς ἀγωνιεῖσθαι.", "st": "13.88"}, {"sp": "N", "t": "ὑμῖν δέ, ὦ ἄνδρες δικασταί, οὐ προσήκει περὶ τούτων ἀποδέχεσθαι· ἀλλ’ ὡς οὐκ ἀπέγραψεν οὐδὲ οἱ ἄνδρες τεθνᾶσι, περὶ τούτων κελεύετε αὐτὸν ἀπολογεῖσθαι. ἔπειτα τοὺς ὅρκους καὶ τὰς συνθήκας οὐδὲν ἡγοῦμαι προσήκειν ἡμῖν πρὸς τοῦτον. οἱ γὰρ ὅρκοι τοῖς ἐν ἄστει πρὸς τοὺς ἐν Πειραιεῖ γεγένηνται.", "st": "13.89"}, {"sp": "N", "t": "εἰ μὲν οὖν οὗτος μὲν ἐν ἄστει ἡμεῖς δ’ ἐν Πειραιεῖ ἦμεν, εἶχον ⟨ἄν⟩ τινα λόγον αὐτῷ αἱ συνθῆκαι· νῦν δὲ καὶ οὗτος ἐν Πειραιεῖ ἦν καὶ ἐγὼ καὶ Διονύσιος καὶ οὗτοι ἅπαντες οἱ τοῦτον τιμωρούμενοι, ὥστε οὔκ εἰσιν ἡμῖν ἐμποδὼν ⟨οὐδέν⟩· οὐδένα γὰρ ὅρκον οἱ ἐν Πειραιεῖ τοῖς ἐν Πειραιεῖ ὤμοσαν.", "st": "13.90"}, {"sp": "N", "t": "ἐκ παντὸς δὲ τρόπου ἔμοιγε δοκεῖ οὐχ ἑνὸς θανάτου ἄξιος εἶναι, ὅστις φησὶ μὲν ὑπὸ τοῦ δήμου ⟨πεποιῆσθαι⟩, τὸν δὲ δῆμον, ὃν αὐτός φησι πατέρα αὑτοῦ εἶναι, φαίνεται κακώσας, καθυφεὶς καὶ προδοὺς ἐξ ὧν ἐκεῖνος μείζων καὶ ἰσχυρότερος ἐγίγνετο. ὅστις οὖν τόν τε γόνῳ πατέρα τὸν αὑτοῦ ἔτυπτε καὶ οὐδὲν παρεῖχε τῶν ἐπιτηδείων, τόν τε ποιητὸν πατέρα ἀφείλετο ἃ ἦν ὑπάρχοντα ἐκείνῳ ἀγαθά, πῶς οὐ καὶ διὰ τοῦτο κατὰ τὸν τῆς κακώσεως νόμον ἄξιός ἐστι θανάτῳ ζημιωθῆναι;", "st": "13.91"}, {"sp": "N", "t": "προσήκει δ’ ὑμῖν, ὦ ἄνδρες δικασταί, ἅπασι τιμωρεῖν ὑπὲρ ἐκείνων τῶν ἀνδρῶν ὁμοίως ὥσπερ ἡμῶν ἑνὶ ἑκάστῳ. ἀποθνῄσκοντες γὰρ [ὑμῖν] ἐπέσκηψαν καὶ ἡμῖν καὶ τοῖς φίλοις ἅπασι τιμωρεῖν ὑπὲρ σφῶν αὐτῶν Ἀγόρατον τουτονὶ ὡς φονέα ὄντα, καὶ κακῶς ποιεῖν καθ’ ὅσον ἂν ἔμβραχυ ἕκαστος δύνηται. εἰ τοίνυν τι ἐκεῖνοι ἀγαθὸν τὴν πόλιν ἢ τὸ πλῆθος τὸ ὑμέτερον φανεροί εἰσι πεποιηκότες, ὃ καὶ αὐτοὶ ὑμεῖς ὁμολογεῖτε, ἀνάγκη ὑμᾶς ἐστι πάντας ἐκείνοις φίλους καὶ ἐπιτηδείους εἶναι, ὥστε οὐδὲν μᾶλλον ἡμῖν ἢ καὶ ὑμῶν ἑνὶ ἑκάστῳ ἐπέσκηψαν.", "st": "13.92"}, {"sp": "N", "t": "οὔκουν οὔτε ὅσιον οὔτε νόμιμον ὑμῖν ἐστιν ἀνεῖναι Ἀγόρατον τουτονί. ὑμεῖς τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, νυνὶ δή, ἐπεὶ ἐν τῷ τότε χρόνῳ, ἐν ᾧ ἐκεῖνοι ἀπέθνῃσκον, οὐχ οἷοί τε ἦστε ἐπαρκέσαι διὰ τὰ πράγματα τὰ περιεστηκότα, νυνί, ἐν ᾧ δύνασθε, τιμωρήσατε τὸν ἐκείνων φονέα. ἐνθυμεῖσθε δ’, ὦ ἄνδρες Ἀθηναῖοι, ὅπως μὴ πάντων ἔργον σχετλιώτατον ἐργάσησθε. εἰ γὰρ ἀποψηφιεῖσθε Ἀγοράτου τουτουί, οὐ μόνον τοῦτο διαπράττεσθε, ἀλλὰ καὶ ἐκείνων τῶν ἀνδρῶν, οὓς ὁμολογεῖτε ὑμῖν εὔνους εἶναι, τῇ αὐτῇ ψήφῳ ταύτῃ θάνατον καταψηφίζεσθε·", "st": "13.93"}, {"sp": "N", "t": "ἀπολύοντες γὰρ τὸν αἴτιον ὄντα ἐκείνοις τοῦ θανάτου οὐδὲν ἄλλο γιγνώσκετε ἢ ἐκείνους δικαίως ὑπὸ τούτου τεθνηκέναι. καὶ οὕτως ἂν δεινότατα πάντων πάθοιεν, εἰ οἷς ἐπέσκηπτον ἐκεῖνοι ὡς φίλοις οὖσι τιμωρεῖν ὑπὲρ αὑτῶν, οὗτοι ὁμόψηφοι κατ’ ἐκείνων τῶν ἀνδρῶν τοῖς τριάκοντα γενήσονται.", "st": "13.94"}, {"sp": "N", "t": "μηδαμῶς, ὦ ἄνδρες δικασταί, πρὸς θεῶν Ὀλυμπίων, μήτε τέχνῃ μήτε μηχανῇ μηδεμιᾷ θάνατον ἐκείνων τῶν ἀνδρῶν καταψηφίσησθε, οἳ πολλὰ κἀγαθὰ ὑμᾶς ποιήσαντες διὰ ταῦτα ὑπὸ τῶν τριάκοντα καὶ Ἀγοράτου τουτουὶ ἀπέθανον. ἀναμνησθέντες οὖν ἁπάντων τῶν δεινῶν, καὶ τῶν κοινῶν τῇ πόλει καὶ τῶν ἰδίων, ὅσα ἑκάστῳ ἐγένετο ἐπειδὴ ἐκεῖνοι οἱ ἄνδρες ἐτελεύτησαν, τιμωρήσατε τὸν αἴτιον τούτων. ἀποδέδεικται δ’ ὑμῖν [ἅπαντα] καὶ ἐκ τῶν ψηφισμάτων καὶ ἐκ τῶν ἀπογραφῶν καὶ ἐκ τῶν ἄλλων ἁπάντων Ἀγόρατος ὢν αὐτοῖς τοῦ θανάτου.", "st": "13.95"}, {"sp": "N", "t": "ἔτι δὲ καὶ προσήκει ὑμῖν ἐναντία τοῖς τριάκοντα ψηφίζεσθαι· ὧν μὲν τοίνυν ἐκεῖνοι θάνατον κατέγνωσαν, ὑμεῖς ἀποψηφίσασθε· ὧν δ’ ἐκεῖνοι θάνατον οὐ κατέγνωσαν, ὑμεῖς καταψηφίσασθε. οἱ τριάκοντα τοίνυν τῶν μὲν ἀνδρῶν τούτων, οἳ ἦσαν ὑμέτεροι φίλοι, θάνατον κατέγνωσαν, ὧν δεῖ ὑμᾶς ἀποψηφίζεσθαι· Ἀγοράτου δὲ ἀπεψηφίσαντο, διότι ἐδόκει προθύμως τούτους ἀπολλύναι· οὗ προσήκει καταψηφίζεσθαι.", "st": "13.96"}, {"sp": "N", "t": "ἐὰν οὖν τὰ ἐναντία τοῖς τριάκοντα ψηφίζησθε, πρῶτον μὲν οὐχ ὁμόψηφοι ⟨τοῖς ἐχθροῖς⟩ γίγνεσθε, ἔπειτα τοῖς ὑμετέροις αὐτῶν φίλοις τετιμωρηκότες ἔσεσθε, ἔπειτα τοῖς πᾶσιν ἀνθρώποις δόξετε δίκαια καὶ ὅσια ψηφίσασθαι.", "st": "13.97"}, {"sp": "HDR", "t": "ΙΔʹ. Κατὰ Ἀλκιβιάδου λιποταξίου", "st": "14"}, {"sp": "N", "t": "ἡγοῦμαι μέν, ὦ ἄνδρες δικασταί, οὐδεμίαν ὑμᾶς ποθεῖν ἀκοῦσαι πρόφασιν παρὰ τῶν βουλομένων Ἀλκιβιάδου κατηγορεῖν· τοιοῦτον γὰρ πολίτην ἑαυτὸν ἐξ ἀρχῆς παρέσχεν, ὥστε καὶ εἰ μή τις ἰδίᾳ ἀδικούμενος ὑπ’ αὐτοῦ τυγχάνει, οὐδὲν ἧττον προσήκει ἐκ τῶν ἄλλων ἐπιτηδευμάτων ἐχθρὸν αὐτὸν ἡγεῖσθαι.", "st": "14.1"}, {"sp": "N", "t": "οὐ γὰρ μικρὰ τὰ ἁμαρτήματα οὐδὲ συγγνώμης ἄξια, οὐδ’ ἐλπίδα παρέχοντα ὡς ἔσται τοῦ λοιποῦ βελτίων, ἀλλ’ οὕτω πεπραγμένα καὶ εἰς τοσοῦτον κακίας ἀφιγμένα, ὥστ’ ἐπ’ ἐνίοις ὧν οὗτος φιλοτιμεῖται ⟨καὶ⟩ τοὺς ἐχθροὺς αἰσχύνεσθαι. ἐγὼ μέντοι, ὦ ἄνδρες δικασταί, καὶ πρότερον πρὸς τοὺς πατέρας ἡμῖν διαφορᾶς ὑπαρχούσης, καὶ πάλαι τοῦτον πονηρὸν ἡγούμενος, καὶ νῦν ὑπ’ αὐτοῦ πεπονθὼς κακῶς, πειράσομαι ὑπὲρ πάντων τῶν πεπραγμένων μεθ’ ὑμῶν αὐτὸν τιμωρήσασθαι.", "st": "14.2"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν ἄλλων Ἀρχεστρατίδης ἱκανῶς κατηγόρησε· καὶ γὰρ τοὺς νόμους ἐπέδειξε καὶ μάρτυρας πάντων παρέσχετο· ὅσα δ’ οὗτος παραλέλοιπεν, ἐγὼ καθ’ ἕκαστον ὑμᾶς διδάξω. [ἀνάγνωθι δέ μοι τὸν νόμον.]", "st": "14.3"}, {"sp": "N", "t": "<em>[Νόμος]<\/em>", "st": "14.4"}, {"sp": "N", "t": "εἰκὸς τοίνυν ἐστίν, ὦ ἄνδρες δικασταί, ἐξ οὗ τὴν εἰρήνην ἐποιησάμεθα, πρῶτον περὶ τούτων νυνὶ δικάζοντας μὴ μόνον δικαστὰς ἀλλὰ καὶ νομοθέτας αὐτοὺς γενέσθαι, εὖ εἰδότας ὅτι, ὅπως ἂν ὑμεῖς νυνὶ περὶ αὐτῶν γνῶτε, οὕτω καὶ τὸν ἄλλον χρόνον ἡ πόλις αὐτοῖς χρήσεται. δοκεῖ δέ μοι καὶ πολίτου χρηστοῦ καὶ δικαστοῦ δικαίου ἔργον εἶναι ταύτῃ τοὺς νόμους διαλαμβάνειν, ὅπῃ εἰς τὸν λοιπὸν χρόνον μέλλει συνοίσειν τῇ πόλει.", "st": "14.4"}, {"sp": "N", "t": "τολμῶσι γάρ τινες λέγειν ὡς οὐδεὶς ἔνοχός ἐστι λιποταξίου οὐδὲ δειλίας· μάχην γὰρ οὐδεμίαν γεγονέναι, τὸν δὲ νόμον κελεύειν, ἐάν τις λίπῃ τὴν τάξιν εἰς τοὐπίσω δειλίας ἕνεκα, μαχομένων τῶν ἄλλων, περὶ τούτου τοὺς στρατιώτας δικάζειν. ὁ δὲ νόμος οὐ περὶ τούτων κελεύει μόνον, ἀλλὰ καὶ ὁπόσοι ἂν μὴ παρῶσιν ἐν τῇ πεζῇ στρατιᾷ. ἀνάγνωθί μοι τὸν νόμον.", "st": "14.5"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "14.6"}, {"sp": "N", "t": "ἀκούετε, ὦ ἄνδρες δικασταί, ὅτι περὶ ἀμφοτέρων κεῖται, καὶ ὅσοι ἂν μάχης οὔσης εἰς τοὐπίσω ἀναχωρήσωσι, καὶ ὅσοι ἂν ἐν τῇ πεζῇ στρατιᾷ μὴ παρῶσι. σκέψασθε δὲ τίνες εἰσὶν οὓς δεῖ παρεῖναι. οὐχ οἵτινες ἂν τὴν ἡλικίαν ταύτην ἔχωσιν; οὐχ οὓς ἂν οἱ στρατηγοὶ καταλέξωσιν; ἡγοῦμαι δ’,", "st": "14.6"}, {"sp": "N", "t": "ὦ ἄνδρες δικασταί, ὅλῳ τῷ νόμῳ μόνον αὐτὸν τῶν πολιτῶν ἔνοχον εἶναι· ἀστρατείας μὲν γὰρ δικαίως ἂν αὐτὸν ἁλῶναι, ὅτι καταλεγεὶς ὁπλίτης οὐκ ἐξῆθε μεθ’ ὑμῶν, ⟨λιποταξίου δέ, ὅτι ἐν τῷ⟩ στρατοπέδῳ μόνος οὐ παρέσχε μετὰ τῶν ἄλλων ἑαυτὸν τάξαι, δειλίας δέ, ὅτι δεῖν αὐτὸν μετὰ τῶν ὁπλιτῶν κινδυνεύειν ἱππεύειν εἵλετο.", "st": "14.7"}, {"sp": "N", "t": "καίτοι φασὶν αὐτὸν ταύτην τὴν ἀπολογίαν ποιήσεσθαι, ὡς ἐπειδήπερ ἵππευεν, οὐδὲν ἠδίκει τὴν πόλιν. ἐγὼ δ’ ἡγοῦμαι διὰ τοῦθ’ ὑμᾶς δικαίως ἂν αὐτῷ ὀργίζεσθαι, ὅτι τοῦ νόμου κελεύοντος, ἐάν τις ἀδοκίμαστος ἱππεύῃ, ἄτιμον εἶναι, ἐτόλμησεν ἀδοκίμαστος ἱππεύειν. καί μοι ἀνάγνωθι τὸν νόμον.", "st": "14.8"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "14.9"}, {"sp": "N", "t": "οὗτος τοίνυν εἰς τοῦτ’ ἦλθε πονηρίας, καὶ οὕτως ὑμῶν κατεφρόνησε καὶ τοὺς πολεμίους ἔδεισε καὶ ἱππεύειν ἐπεθύμησε καὶ τῶν νόμων οὐκ ἐφρόντισεν, ὥστε οὐδὲν αὐτῷ τούτων τῶν κινδύνων ἐμέλησεν, ἀλλ’ ἐβουλήθη καὶ ἄτιμος εἶναι καὶ τὰ χρήματ’ αὐτοῦ δημευθῆναι καὶ πάσαις ταῖς κειμέναις ζημίαις ἔνοχος γενέσθαι μᾶλλον ἢ μετὰ τῶν πολιτῶν εἶναι καὶ ὁπλίτης γενέσθαι.", "st": "14.9"}, {"sp": "N", "t": "καὶ ἕτεροι μὲν οὐδεπώποτε ὁπλιτεύσαντες, ἱππεύοντες δὲ τὸν ἄλλον χρόνον καὶ πολλὰ κακὰ τοὺς πολεμίους πεποιηκότες, οὐκ ἐτόλμησαν ἐπὶ τοὺς ἵππους ἀναβῆναι, δεδιότες ὑμᾶς καὶ τὸν νόμον· οὕτω γὰρ ἦσαν παρεσκευασμένοι, οὐχ ὡς ἀπολουμένης τῆς πόλεως, ἀλλ’ ὡς σωθησομένης καὶ μεγάλης ἐσομένης καὶ τιμωρησομένης τοὺς ἀδικοῦντας· Ἀλκιβιάδης δ’ ἐτόλμησεν ἀναβῆναι, βῆναι, οὔτε εὔνους ὢν τῷ πλήθει οὔτε πρότερον ἱππεύσας οὔτε νῦν ἐπιστάμενος οὔτε ὑφ’ ὑμῶν δοκιμασθείς, ὡς οὐκ ἐξεσόμενον τῇ πόλει δίκην παρὰ τῶν ἀδικούντων λαμβάνειν.", "st": "14.10"}, {"sp": "N", "t": "ἐνθυμηθῆναι δὲ χρὴ ὅτι, εἰ ἐξέσται ὅ τι ἄν τις βούληται ποιεῖν, οὐδὲν ὄφελος νόμους κεῖσθαι ἢ ὑμᾶς συλλέγεσθαι ἢ στρατηγοὺς αἱρεῖσθαι. θαυμάζω δέ, ὦ ἄνδρες δικασταί, εἴ τις ἀξιοῖ, ἐὰν μέν τις προσιόντων τῶν πολεμίων τῆς πρώτης τάξεως τεταγμένος τῆς δευτέρας γένηται, τούτου μὲν δειλίαν καταψηφίζεσθαι, ἐὰν δέ τις ἐν τοῖς ὁπλίταις τεταγμένος ἐν τοῖς ἱππεῦσιν ἀναφανῇ,", "st": "14.11"}, {"sp": "N", "t": "τούτῳ συγγνώμην ἔχειν. καὶ μὲν δή, ὦ ἄνδρες δικασταί, ἡγοῦμαι δικάζειν ὑμᾶς οὐ μόνον τῶν ἐξαμαρτανόντων ἕνεκα, ἀλλ’ ἵνα καὶ τοὺς ἄλλους τῶν ἀκοσμούντων σωφρονεστέρους ποιῆτε. ἐὰν μὲν τοίνυν τοὺς ἀγνῶτας κολάζητε, οὐδεὶς ἔσται τῶν ἄλλων βελτίων· οὐδεὶς γὰρ εἴσεται τὰ ὑφ’ ὑμῶν καταψηφισθέντα· ἐὰν δὲ τοὺς ἐπιφανεστάτους τῶν ἐξαμαρτανόντων τιμωρῆσθε, πάντες πεύσονται, ὥστε τούτῳ παραδείγματι χρώμενοι βελτίους ἔσονται οἱ πολῖται.", "st": "14.12"}, {"sp": "N", "t": "ἐὰν τοίνυν τούτου καταψηφίσησθε, οὐ μόνον οἱ ἐν τῇ πόλει εἴσονται, ἀλλὰ καὶ οἱ σύμμαχοι αἰσθήσονται καὶ οἱ πολέμιοι πεύσονται, καὶ ἡγήσονται πολὺ πλείονος ἀξίαν εἶναι τὴν πόλιν, ἐὰν ὁρῶσιν ἐπὶ τοῖς τοιούτοις τῶν ἁμαρτημάτων μάλισθ’ ὑμᾶς ὀργιζομένους καὶ μηδεμιᾶς συγγνώμης τοὺς ἀκοσμοῦντας ἐν τῷ πολέμῳ τυγχάνοντας.", "st": "14.13"}, {"sp": "N", "t": "ἐνθυμεῖσθε δ’, ὦ ἄνδρες δικασταί, ὅτι τῶν στρατιωτῶν οἱ μὲν κάμνοντες ἐτύγχανον, οἱ δὲ ἐνδεεῖς ὄντες τῶν ἐπιτηδείων, καὶ ἡδέως ἂν οἱ μὲν ταῖς πόλεσι καταμείναντες ἐθεραπεύοντο, οἱ δὲ οἴκαδ’ ἀπελθόντες τῶν οἰκείων ἐπεμέλοντο, οἱ δὲ ψιλοὶ ἐστρατεύοντο, οἱ δ’ ἐν τοῖς", "st": "14.14"}, {"sp": "N", "t": "ἱππεῦσιν ἐκινδύνευον· ἀλλ’ ὅμως οὐκ ἐτολμᾶτε ἀπολιπεῖν τὰς τάξεις οὐδὲ τἀρεστὰ ὑμῖν αὐτοῖς αἱρεῖσθαι ἀλλὰ πολὺ μᾶλλον ἐφοβεῖσθε τοὺς τῆς πόλεως νόμους ἢ τὸν πρὸς τοὺς πολεμίους κίνδυνον. ὧν χρὴ μεμνημένους ὑμᾶς νυνὶ τὴν ψῆφον φέρειν, καὶ πᾶσι φανερὸν ποιεῖν ὅτι Ἀθηναίων οἱ μὴ βουλόμενοι τοῖς πολεμίοις μάχεσθαι ὑφ’ ὑμῶν κακῶς πείσονται.", "st": "14.15"}, {"sp": "N", "t": "ἡγοῦμαι δέ, ὦ ἄνδρες δικασταί, περὶ μὲν τοῦ νόμου καὶ αὐτοῦ τοῦ πράγματος οὐχ ἕξειν αὐτοὺς ὅ τι λέξουσιν· ἀναβαίνοντες δ’ ὑμᾶς ἐξαιτήσονται καὶ ἀντιβολήσουσιν, οὐκ ἀξιοῦντες τοῦ Ἀλκιβιάδου ὑέος τοσαύτην δειλίαν καταγνῶναι, ὡς ἐκεῖνον πολλῶν ἀγαθῶν ἀλλ’ οὐχὶ πολλῶν κακῶν αἴτιον γεγενημένον· ὃν εἰ τηλικοῦτον ὄντα ἀπεκτείνατε, ὅτε πρῶτον εἰς ὑμᾶς ἐλάβετε ἐξαμαρτάνοντα, οὐκ ἂν ἐγένοντο συμφοραὶ τοσαῦται τῇ πόλει.", "st": "14.16"}, {"sp": "N", "t": "δεινὸν δέ μοι δοκεῖ, ὦ ἄνδρες δικασταί, εἶναι, εἰ αὐτοῦ μὲν ἐκείνου θάνατον κατέγνωτε, τοῦ δὲ ὑοῦ ἀδικοῦντος δι’ ἐκεῖνον ἀποψηφιεῖσθε, ὃς αὐτὸς μὲν οὐκ ἐτόλμα μεθ’ ὑμῶν μάχεσθαι, ὁ δὲ πατὴρ αὐτοῦ μετὰ τῶν πολεμίων ἠξίου στρατεύεσθαι. καὶ ὅτε μὲν παῖς ὢν οὔπω δῆλος ἦν ὁποῖός τις ἔσται, διὰ τὰ τοῦ πατρὸς ἁμαρτήματα ὀλίγου τοῖς ἕνδεκα παρεδόθη· ἐπειδὴ δὲ πρὸς τοῖς ἐκείνῳ πεπραγμένοις ἐπίστασθε καὶ τὴν τούτου πονηρίαν, διὰ τὸν πατέρα ἐλεεῖν αὐτὸν ἀξιώσετε;", "st": "14.17"}, {"sp": "N", "t": "οὐκ οὖν δεινόν, ὦ ἄνδρες δικασταί, τούτους μὲν οὕτως εὐτυχεῖς εἶναι ὥστ’, ἐπειδὰν ἐξαμαρτάνοντες ληφθῶσι, διὰ τὸ αὑτῶν γένος σῴζεσθαι, ἡμᾶς δέ, εἰ ἐδυστυχήσαμεν διὰ τοὺς οὕτως ἀτακτοῦντας, μηδένα ἂν δύνασθαι παρὰ τῶν πολεμίων ἐξαιτήσασθαι μηδὲ διὰ τὰς τῶν προγόνων ἀρετάς;", "st": "14.18"}, {"sp": "N", "t": "καίτοι πολλαὶ καὶ μεγάλαι καὶ ὑπὲρ ἁπάντων τῶν Ἑλλήνων γεγόνασι, καὶ οὐδὲν ὅμοιαι τοῖς ὑπὸ τούτων περὶ τὴν πόλιν πεπραγμένοις, ὦ ἄνδρες δικασταί. εἰ δ’ ἐκεῖνοι δοκοῦσι βελτίους εἶναι σῴζοντες τοὺς φίλους, δῆλον ὅτι καὶ ὑμεῖς ἀμείνους δόξετε εἶναι τιμωρούμενοι τοὺς ἐχθρούς.", "st": "14.19"}, {"sp": "N", "t": "ἀξιῶ δ’, ὦ ἄνδρες δικασταί, ἐὰν μέν τινες τῶν συγγενῶν αὐτὸν ἐξαιτῶνται, ὀργίζεσθαι ὅτι τούτου μὲν οὐκ ἐπεχείρησαν δεηθῆναι (ἢ δεηθέντες οὐκ ἐδύναντο εὑρέσθαι) ποιεῖν τὰ ὑπὸ τῆς πόλεως προσταττόμενα, ὑμᾶς δὲ πείθειν πειρῶνται ὡς οὐ", "st": "14.20"}, {"sp": "N", "t": "χρὴ παρὰ τῶν ἀδικούντων δίκην λαμβάνειν· ἐὰν δέ τινες τῶν ἀρχόντων βοηθῶσιν αὐτῷ ἐπίδειξιν μὲν τῆς ἑαυτῶν δυνάμεως ποιούμενοι, φιλοτιμούμενοι δὲ ὅτι καὶ τοὺς φανερῶς ἡμαρτηκότας σῴζειν δύνανται, ὑμᾶς [δὲ], χρὴ ὑπολαμβάνειν πρῶτον μὲν ὅτι, εἰ πάντες Ἀλκιβιάδῃ ὅμοιοι ἐγένοντο, οὐδὲν ἂν ἔδει τῶν στρατηγῶν (οὐδὲ γὰρ ⟨ἂν⟩ εἶχον ὅτου ἡγοῦντο), ἔπειθ’ ὅτι πολὺ μᾶλλον αὐτοὺς προσήκει τῶν λιπόντων τὴν τάξιν κατηγορεῖν ἢ ὑπὲρ τῶν τοιούτων ἀπολογεῖσθαι. τίς γὰρ ἔστιν ἐλπὶς τοὺς ἄλλους ἐθελήσειν ποιεῖν τὰ ὑπὸ τῶν στρατηγῶν προσταττόμενα, ὅταν αὐτοὶ οὗτοι τοὺς ἀκοσμοῦντας σῴζειν πειρῶνται;", "st": "14.21"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἀξιῶ, ἐὰν μὲν ἀποδείξωσιν οἱ λέγοντες καὶ αἰτούμενοι ὑπὲρ Ἀλκιβιάδου ὡς ἐστρατεύσατο ἐν τοῖς ὁπλίταις ἢ ὡς ἵππευε δεδοκιμασμένος, ἀποψηφίσασθαι· ἐὰν δὲ μηδὲν ἔχοντες δίκαιον κελεύωσιν αὑτοῖς χαρίζεσθαι, μεμνῆσθαι χρὴ ὅτι διδάσκουσιν ὑμᾶς ἐπιορκεῖν καὶ τοῖς νόμοις μὴ πείθεσθαι, καὶ ὅτι λίαν προθύμως τοῖς ἀδικοῦσι βοηθοῦντες πολλοὺς τῶν αὐτῶν ἔργων ἐπιθυμεῖν ποιήσουσι.", "st": "14.22"}, {"sp": "N", "t": "θαυμάζω δὲ μάλιστα, ὦ ἄνδρες δικασταί, εἴ τις ὑμῶν τὸν Ἀλκιβιάδην ἀξιώσει διὰ μὲν τοὺς βοηθοῦντας σῴζεσθαι, διὰ δὲ τὴν αὐτοῦ πονηρίαν μὴ ἀπολέσθαι. ἧς ἄξιον ὑμᾶς ἀκοῦσαι, ἵν’ ἐπίστησθε ὅτι οὐκ ἂν εἰκότως αὐτοῦ ἀποψηφίζοισθε, ὡς ταῦτα μὲν ἡμαρτηκότος, τὰ δ’ ἄλλα πολίτου χρηστοῦ γεγενημένου· ἐκ γὰρ τῶν ἄλλων τῶν τούτῳ πεπραγμένων δικαίως ἂν αὐτοῦ θάνατον καταψηφίζοισθε.", "st": "14.23"}, {"sp": "N", "t": "προσήκει δ’ ὑμῖν περὶ αὐτῶν εἰδέναι· ἐπειδὴ γὰρ καὶ τῶν ἀπολογουμένων ἀποδέχεσθε λεγόντων τὰς σφετέρας αὐτῶν ἀρετὰς καὶ τὰς τῶν προγόνων εὐεργεσίας, εἰκὸς ὑμᾶς καὶ τῶν κατηγόρων ἀκροᾶσθαι, ἐὰν ἀποφαίνωσι τοὺς φεύγοντας πολλὰ εἰς ὑμᾶς ἡμαρτηκότας καὶ τοὺς προγόνους αὐτῶν πολλῶν κακῶν αἰτίους γεγενημένους.", "st": "14.24"}, {"sp": "N", "t": "οὗτος γὰρ παῖς μὲν ὢν παρ’ Ἀρχεδήμῳ τῷ γλάμωνι, ⟨τῷ⟩ οὐκ ὀλίγα τῶν ὑμετέρων ὑφῃρημένῳ, πολλῶν ὁρώντων ἔπινεν ὑπὸ τῷ αὐτῷ ἱματίῳ κατακείμενος, ἐκώμαζε ⟨δὲ⟩ μεθ’ ἡμέραν, ἄνηβος ἑταίραν ἔχων, μιμούμενος τοὺς ἑαυτοῦ προγόνους, καὶ ἡγούμενος οὐκ ἂν δύνασθαι πρεσβύτερος ὢν λαμπρὸς γενέσθαι, εἰ μὴ νέος ὢν πονηρότατος δόξει εἶναι.", "st": "14.25"}, {"sp": "N", "t": "μετεπέμφθη δ’ ὑπὸ Ἀλκιβιάδου, ἐπειδὴ φανερῶς ἐξημάρτανε. καίτοι ποῖόν τινα χρὴ αὐτὸν ὑφ’ ὑμῶν νομίζεσθαι εἶναι, ὅστις κἀκείνῳ τοιαῦτ’ ἐπιτηδεύων διεβέβλητο ὃς τοὺς ἄλλους ταῦτ’ ἐδίδασκε; μετὰ Θεοτίμου δὲ ἐπιβουλεύσας τῷ πατρὶ Ὄρνους προὔδωκεν. ὁ δὲ παραλαβὼν τὸ χωρίον πρότερον μὲν ὕβριζεν αὐτὸν ὡραῖον ὄντα, τελευτῶν δὲ δήσας ἀργύριον εἰσεπράττετο.", "st": "14.26"}, {"sp": "N", "t": "ὁ δὲ πατὴρ αὐτὸν οὕτως ἐμίσει σφόδρα, ὥστ’ οὐδ’ ⟨ἂν⟩ ἀποθανόντος ἔφασκε τὰ ὀστᾶ κομίσασθαι. τελευτήσαντος δ’ ἐκείνου ἐραστὴς γενόμενος Ἀρχεβιάδης αὐτὸν ἐλύσατο. οὐ πολλῷ δὲ χρόνῳ ὕστερον κατακυβεύσας τὰ ὄντα, ἐκ Λευκῆς ἀκτῆς ὁρμώμενος τοὺς φίλους κατεπόντιζεν.", "st": "14.27"}, {"sp": "N", "t": "ὅσα μὲν οὖν, ὦ ἄνδρες δικασταί, ἢ εἰς τοὺς πολίτας ἢ εἰς τοὺς ξένους ἢ περὶ τοὺς αὑτοῦ οἰκείους ἢ περὶ τοὺς ἄλλους ἡμάρτηκε, μακρὸν ἂν εἴη λέγειν· Ἱππόνικος δὲ πολλοὺς παρακαλέσας ἐξέπεμψε τὴν αὑτοῦ γυναῖκα, φάσκων τοῦτον οὐχ ὡς ἀδελφὸν αὐτῆς ἀλλ’ ὡς ἄνδρα ἐκείνης εἰς τὴν οἰκίαν εἰσιέναι τὴν αὑτοῦ.", "st": "14.28"}, {"sp": "N", "t": "καὶ τοιαῦθ’ ἡμαρτηκότι καὶ οὕτω δεινὰ καὶ πολλὰ καὶ μεγάλα πεποιηκότι οὔτε τῶν γεγενημένων αὐτῷ μέλει οὔτε τῶν μελλόντων ἔσεσθαι, ἀλλ’ ὃν ἔδει κοσμιώτατον εἶναι τῶν πολιτῶν, ἀπολογίαν ποιούμενον τὸν ἑαυτοῦ βίον τῶν τοῦ πατρὸς ἁμαρτημάτων, οὗτος ἑτέρους ὑβρίζειν πειρᾶται, ὥσπερ δυνάμενος ἂν πολλοστὸν μέρος τῶν ὀνειδῶν τῶν ἑαυτῷ προσηκόντων τοῖς ἄλλοις μεταδοῦναι, καὶ ταῦθ’ ὑὸς ὢν Ἀλκιβιάδου,", "st": "14.29"}, {"sp": "N", "t": "ὃς ἔπεισε μὲν Δεκέλειαν Λακεδαιμονίους ἐπιτειχίσαι, ἐπὶ δὲ τὰς νήσους ἀποστήσων ἔπλευσε, διδάσκαλος δὲ τῶν τῆς πόλεως κακῶν ἐγένετο, πλεονάκις δὲ μετὰ τῶν ἐχθρῶν ἐπὶ τὴν πατρίδα ἐστρατεύσατο ἢ μετὰ τῶν πολιτῶν ἐπ’ ἐκείνους. ἀνθ’ ὧν καὶ ὑμῖν καὶ τοῖς μέλλουσιν ἔσεσθαι τιμωρεῖσθαι προσήκει ὅντινα λαμβάνετε τούτων.", "st": "14.30"}, {"sp": "N", "t": "καίτοι σφόδρα εἴθισται λέγειν ὡς οὐκ εἰκός ἐστι τὸν μὲν πατέρα αὐτοῦ κατελθόντα δωρεὰς παρὰ τοῦ δήμου λαβεῖν, τοῦτον δ’ ἀδίκως διὰ τὴν φυγὴν τὴν ἐκείνου διαβεβλῆσθαι. ἐμοὶ δὲ δοκεῖ δεινὸν εἶναι, εἰ τὰς μὲν δωρεὰς αὐτοῦ ἀφείλεσθε ὡς οὐ δικαίως δεδωκότες, τούτου δὲ ἀδικοῦντος ἀποψηφιεῖσθε ὡς τοῦ πατρὸς χρηστοῦ περὶ τὴν πόλιν γεγενημένου.", "st": "14.31"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, ἄλλων τε πολλῶν ἄξιον ἕνεκα αὐτοῦ καταψηφίσασθαι, καὶ ὅτι ταῖς ὑμετέραις ἀρεταῖς χρῆται παραδείγμασι περὶ τῆς ἑαυτοῦ πονηρίας. τολμᾷ γὰρ λέγειν ὡς Ἀλκιβιάδης οὐδὲν δεινὸν εἴργασται ἐπὶ τὴν πατρίδα", "st": "14.32"}, {"sp": "N", "t": "στρατεύσας· καὶ γὰρ ὑμᾶς φεύγοντας Φυλὴν καταλαβεῖν καὶ δένδρα τεμεῖν καὶ πρὸς τὰ τείχη προσβαλεῖν, καὶ ταῦτα ποιήσαντας οὐκ ὄνειδος τοῖς παισὶ καταλιπεῖν, ἀλλὰ τιμὴν παρὰ πᾶσιν ἀνθρώποις κτήσασθαι, ὡς τῶν αὐτῶν ὄντας ἀξίους ὅσοι φυγόντες μετὰ τῶν πολεμίων ἐπὶ τὴν χώραν ἐστράτευσαν, καὶ ὅσοι κατῄεσαν Λακεδαιμονίων ἐχόντων τὴν πόλιν.", "st": "14.33"}, {"sp": "N", "t": "καὶ μὲν δὴ πᾶσιν ἡγοῦμαι δῆλον εἶναι ὅτι οὗτοι μὲν ἐζήτουν κατιέναι ὡς τὴν μὲν τῆς θαλάττης ἀρχὴν Λακεδαιμονίοις παραδώσοντες, αὐτοὶ δ’ ὑμῶν ἄρξοντες. τὸ δ’ ὑμέτερον πλῆθος κατελθὸν τοὺς μὲν πολεμίους ἐξήλασε, τῶν δὲ πολιτῶν καὶ τοὺς βουλομένους δουλεύειν ἠλευθέρωσεν· ὥστ’ οὐχ ὁμοίων τῶν ἔργων ἀμφοτέροις γεγενημένων τοὺς λόγους ποιεῖται.", "st": "14.34"}, {"sp": "N", "t": "ἀλλ’ ὅμως τοσούτων συμφορῶν καὶ οὕτως αὐτῷ μεγάλων ὑπαρχουσῶν ἐπὶ τῇ τοῦ πατρὸς πονηρία φιλοτιμεῖται, καὶ λέγει ὡς οὕτως ἐκεῖνος μέγα ἐδύνατο, ὥστε τῇ πόλει πάντων ⟨τῶν⟩ κακῶν αἴτιος γεγένηται. καίτοι τίς οὕτως ἄπειρος τῆς ἑαυτοῦ πατρίδος, ὃς οὐκ ἂν βουλόμενος εἶναι πονηρὸς εἰσηγήσαιτο μὲν τοῖς πολεμίοις ἃ χρὴ καταλαβεῖν τῶν χωρίων, δηλώσειε δ’ ἂν ἃ κακῶς φυλάττεται τῶν φρουρίων, διδάξειε δ’ ἂν ἃ πονηρῶς ἔχει τῶν πραγμάτων, μηνύσειε δ’ ἂν τοὺς βουλομένους ἀφίστασθαι τῶν συμμάχων;", "st": "14.35"}, {"sp": "N", "t": "οὐ γὰρ δήπου, ὅτε μὲν ἔφευγε, διὰ τὴν δύναμιν κακῶς οἷός τ’ ἦν ποιεῖν τὴν πόλιν, ἐπειδὴ δὲ ὑμᾶς ἐξαπατήσας κατῆλθε καὶ πολλῶν ἦρξε τριήρων, οὔτε τοὺς πολεμίους ἐδύνατο ἐκ τῆς χώρας ἐκβαλεῖν, οὔτε Χίους οὓς ἀπέστησε πάλιν φίλους ποιῆσαι, οὔτε ἄλλο οὐδὲν ἀγαθὸν ὑμᾶς ἐργάσασθαι.", "st": "14.36"}, {"sp": "N", "t": "ὥστ’ οὐ χαλεπὸν γνῶναι ὅτι Ἀλκιβιάδης δυνάμει μὲν οὐδὲν τῶν ἄλλων διέφερε, πονηρία δὲ τῶν πολιτῶν πρῶτος ἦν. ἃ μὲν γὰρ ᾔδει τῶν ὑμετέρων κακῶς ἔχοντα, μηνυτὴς αὐτῶν Λακεδαιμονίοις ἐγένετο· ἐπειδὴ δ’ ἔδει αὐτὸν στρατηγεῖν, οὐδὲν κακὸν ποιεῖν ἐκείνους ἐδύνατο, ἀλλ’ ὑποσχόμενος δι’ ἑαυτὸν παρέξειν βασιλέα χρήματα, πλεῖν ἢ διακόσια τάλαντα τῆς πόλεως ὑφείλετο.", "st": "14.37"}, {"sp": "N", "t": "καὶ οὕτω πολλὰ ἐνόμιζεν εἰς ὑμᾶς ἡμαρτηκέναι, ὥστε λέγειν δυνάμενος καὶ φίλων ὄντων καὶ χρήματα κεκτημένος οὐδέποτ’ ἐλθὼν εὐθύνας ἐτόλμησε δοῦναι, ἀλλὰ φυγὴν αὑτοῦ καταγνοὺς καὶ Θράκης καὶ πάσης πόλεως ἐβούλετο πολίτης γενέσθαι μᾶλλον ἢ τῆς πατρίδος εἶναι τῆς ἑαυτοῦ. καὶ τὸ τελευταῖον, ὦ ἄνδρες δικασταί, ὑπερβολὴν ποιησάμενος τῆς προτέρας πονηρίας ἐτόλμησε τὰς ναῦς Λυσάνδρῳ μετὰ Ἀδειμάντου προδοῦναι.", "st": "14.38"}, {"sp": "N", "t": "ὥστε εἴ τις ὑμῶν ἢ τοὺς τεθνεῶτας ἐν ⟨τῇ⟩ ναυμαχίᾳ ἐλεεῖ, ἢ ὑπὲρ τῶν δουλευσάντων τοῖς πολεμίοις αἰσχύνεται, ἢ τῶν τειχῶν καθῃρημένων ἀγανακτεῖ, ἢ Λακεδαιμονίους μισεῖ, ἢ τοῖς τριάκοντα ὀργίζεται, τούτων ἁπάντων χρὴ τὸν τούτου πατέρα αἴτιον ἡγεῖσθαι, καὶ ἐνθυμηθῆναι ὅτι Ἀλκιβιάδην μὲν τὸν πρόπαππον αὐτοῦ καὶ τὸν πατρὸς πρὸς μητρὸς ⟨πάππον⟩ Μεγακλέα οἱ ὑμέτεροι πρόγονοι δὶς ἀμφοτέρους ἐξωστράκισαν, τοῦ δὲ πατρὸς αὐτοῦ οἱ πρεσβύτεροι ὑμῶν θάνατον κατέγνωσαν,", "st": "14.39"}, {"sp": "N", "t": "ὥστε νῦν χρὴ ἡγησαμένους πατρικὸν ἐχθρὸν τοῦτον εἶναι τῇ πόλει καταψηφίσασθαι, καὶ μήτε ἔλεον μήτε συγγνώμην μήτε χάριν μηδεμίαν περὶ πλείονος ποιήσασθαι τῶν νόμων τῶν κειμένων καὶ τῶν ὅρκων οὓς ὠμόσατε.", "st": "14.40"}, {"sp": "N", "t": "σκέψασθαι δὲ χρή, ὦ ἄνδρες δικασταί, διὰ τί ἄν τις τοιούτων ἀνδρῶν φείσαιτο; πότερον ὡς πρὸς μὲν τὴν πόλιν δεδυστυχήκασιν, ἄλλως δὲ κόσμοί εἰσι καὶ σωφρόνως βεβιώκασιν; οὐχ οἱ μὲν πολλοὶ αὐτῶν ἡταιρήκασιν, οἱ δ’ ἀδελφαῖς συγγεγόνασι, τοῖς δ’ ἐκ θυγατέρων παῖδες γεγόνασιν,", "st": "14.41"}, {"sp": "N", "t": "οἱ δὲ μυστήρια πεποιήκασι καὶ τοὺς Ἑρμᾶς περικεκόφασι καὶ περὶ πάντας τοὺς θεοὺς ἠσεβήκασι καὶ εἰς ἅπασαν τὴν πόλιν ἡμαρτήκασιν, ἀδίκως καὶ παρανόμως καὶ πρὸς τοὺς ἄλλους πολιτευόμενοι καὶ πρὸς σφᾶς αὐτοὺς διακείμενοι, οὐδεμιᾶς τόλμης ἀπεχόμενοι, οὐδὲ ἔργου δεινοῦ ἄπειροι γεγενημένοι; ἀλλὰ καὶ πεπόνθασιν καὶ πεποιήκασιν ἅπαντα. οὕτω γὰρ διάκεινται, ὥστ’ ἐπὶ μὲν τοῖς καλοῖς αἰσχύνεσθαι, ἐπὶ δὲ τοῖς κακοῖς φιλοτιμεῖσθαι.", "st": "14.42"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, ἤδη τινῶν ἀπεψηφίσασθε ἀδικεῖν μὲν νομίσαντες, οἰόμενοι δ’ εἰς τὸ λοιπὸν χρησίμους ὑμῖν ἔσεσθαι. τίς οὖν ἐλπὶς ὑπὸ τούτου τι ἀγαθὸν πείσεσθαι τὴν πόλιν, ὃν ὑμεῖς, ὅτι μὲν οὐδενὸς ἄξιός ἐστιν, ἐπειδὰν ἀπολογῆται, εἴσεσθε, ὅτι δὲ πονηρός ἐστιν ἐκ τῶν ἄλλων ἐπιτηδευμάτων ἤσθησθε;", "st": "14.43"}, {"sp": "N", "t": "ἀλλὰ μὲν δὴ οὐδ’ ἂν ἐξελθὼν ἐκ τῆς πόλεως οὐδὲν δύναιτο κακὸν ὑμᾶς ἐργάσασθαι, δειλὸς ὢν καὶ πένης καὶ πράττειν ἀδύνατος καὶ τοῖς οἰκείοις διάφορος καὶ ὑπὸ τῶν ἄλλων μισούμενος. ὥστ’ οὐδὲ τούτων ἕνεκα αὐτὸν ἄξιον φυλάττεσθαι,", "st": "14.44"}, {"sp": "N", "t": "ἀλλὰ πολὺ μᾶλλον παράδειγμα ποιῆσαι καὶ τοῖς ἄλλοις καὶ τοῖς τούτου φίλοις, οἳ τὰ μὲν προσταττόμενα ποιεῖν οὐκ ἐθέλουσι, τοιούτων δ’ ἔργων ἐπιθυμοῦσι, καὶ περὶ τῶν σφετέρων αὐτῶν κακῶς βουλευσάμενοι περὶ τῶν ὑμετέρων δημηγοροῦσιν.", "st": "14.45"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ὡς ἐδυνάμην ἄριστα κατηγόρηκα, ἐπίσταμαι δ’ ὅτι οἱ μὲν ἄλλοι τῶν ἀκροωμένων θαυμάζουσιν, ὅπως ποθ’ οὕτως ἀκριβῶς ἐδυνήθην ἐξευρεῖν τὰ τούτων ἁμαρτήματα, οὗτος δέ μου καταγελᾷ, ὅτι οὐδὲ πολλοστὸν μέρος εἴρηκα τῶν τούτοις ὑπαρχόντων κακῶν.", "st": "14.46"}, {"sp": "N", "t": "ὑμεῖς οὖν καὶ τὰ εἰρημένα καὶ τὰ παραλελειμμένα ἀναλογισάμενοι πολὺ μᾶλλον αὐτοῦ καταψηφίσασθε, ἐνθυμηθέντες ὅτι ἔνοχος μέν ἐστι τῇ γραφῇ, μεγάλη δ’ εὐτυχία τὸ τοιούτων πολιτῶν ἀπαλλαγῆναι ⟨τῇ⟩ πόλει. ἀνάγνωθι δ’ αὐτοῖς τοὺς νόμους καὶ τοὺς ὅρκους καὶ τὴν γραφήν· καὶ τούτων μεμνημένοι ψηφιοῦνται τὰ δίκαια.", "st": "14.47"}, {"sp": "N", "t": "<em>Νόμοι<\/em>", "st": "14.47"}, {"sp": "N", "t": "<em>Ὅρκοι<\/em>", "st": "14.47"}, {"sp": "N", "t": "<em>Γραφή<\/em>", "st": "14.47"}, {"sp": "HDR", "t": "ΙΕʹ. Κατὰ Ἀλκιβιάδου ἀστρατείας", "st": "15"}, {"sp": "N", "t": "ἐγὼ μέν, ὦ ἄνδρες δικασταί, καὶ ὑμᾶς αἰτοῦμαι τὰ δίκαια ψηφίσασθαι, καὶ τῶν στρατηγῶν δέομαι, ἐπεὶ καὶ ἐν τῇ ἄλλῃ ἀρχῇ πολλοῦ ἄξιοι τῇ πόλει γεγόνασι, καὶ τῶν τῆς ἀστρατείας γραφῶν κοινοὺς εἶναι τῷ τε διώκοντι καὶ τῷ φεύγοντι, καὶ μὴ βοηθοῦντας ᾧ ἂν βούλωνται πᾶσαν προθυμίαν ἔχειν παρὰ τὸ δίκαιον ὑμᾶς ψηφίσασθαι,", "st": "15.1"}, {"sp": "N", "t": "ἐνθυμουμένους ὅτι σφόδρ’ ἂν ἠγανακτεῖτε, εἰ ⟨ἐν⟩ τῇ ὑμετέρᾳ δοκιμασίᾳ οἱ θεσμοθέται ἀναβάντες ὑμῶν ἐδέοντο καταψηφίσασθαι, ἡγούμενοι δεινὸν εἶναι εἰ οἱ τιθέντες τὸν ἀγῶνα καὶ τὴν ψῆφον διδόντες παρακελεύσονται τῶν μὲν μὴ ⟨καταψηφίζεσθαι τῶν δὲ⟩ καταψηφίζεσθαι.", "st": "15.2"}, {"sp": "N", "t": "τί δ’ ἂν αἴσχιον ἔθος ἢ δεινότερον πρᾶγμα τούτου ⟨ἐν⟩ τῇ πόλει γένοιτο, εἰ τολμήσει ὁ μὲν ἄρχων ἐν ταῖς τῶν ἐπικλήρων δίκαις ἀντιβολεῖν καὶ ἱκετεύειν τοὺς δικαστὰς ὅ τι ἂν βούληται πραχθῆναι, ὁ δὲ πολέμαρχος καὶ οἱ ἕνδεκα δεήσονται ἐν ταῖς δίκαις ταῖς ὑφ’ ἑαυτῶν εἰσαγομέναις,", "st": "15.3"}, {"sp": "N", "t": "ὥσπερ καὶ νῦν; χρὴ τοίνυν καὶ ὑπὲρ ὑμῶν αὐτῶν τὴν γνώμην ἔχειν, ἐνθυμουμένους ὅτι οὐδὲν διοίσει ὑμᾶς ἰδίᾳ περὶ τῆς ἀστρατείας βοηθεῖν, ἢ τούτων τινὰς δεῖσθαι αὐτοὺς τὴν ψῆφον διδόντας.", "st": "15.4"}, {"sp": "N", "t": "σκέψασθε δέ, ὦ ἄνδρες δικασταί, ἐὰν ἱκανὸν γένηται τεκμήριον ὅτι οὐδείς πω τῶν ἀρχόντων ἐν τῷ στρατοπέδῳ Ἀλκιβιάδῃ ἦν παρεσκευασμένος. ἐχρῆν γὰρ αὐτούς, εἴπερ ἀληθῆ λέγουσιν, ἀνακαλεῖν μὲν Πάμφιλον, ὅτι ἀφαιρῶν τὸν ἵππον ἱππέως ἀπεστέρει τὴν πόλιν, ἐπιβάλλειν δὲ τῷ φυλάρχῳ, ὅτι ἐξελαύνων Ἀλκιβιάδην ἐκ τῆς φυλῆς ἄκυρον ἐποίει τὴν τούτων τάξιν, κελεύειν δὲ τὸν ταξίαρχον ἐξαλείφειν αὐτὸν ἐκ τοῦ τῶν ὁπλιτῶν καταλόγου.", "st": "15.5"}, {"sp": "N", "t": "νῦν δὲ τούτων οὐδὲν ἐποίησαν, ἀλλ’ ἐν μὲν τῷ στρατοπέδῳ περιεώρων αὐτὸν ὑπὸ πάντων προπηλακιζόμενον κἀν τοῖς ἱπποτοξόταις ἱππεύοντα, ἐπειδὴ δὲ ὑμᾶς δεῖ παρὰ τῶν ἀδικούντων δίκην λαμβάνειν, χαριζόμενοι μαρτυροῦσιν ὑφ’ ἑαυτῶν αὐτὸν τετάχθαι. καίτοι δεινόν, ὦ ἄνδρες δικασταί, αὐτοὺς μὲν τοὺς στρατηγοὺς ὑπὸ τοῦ δήμου χειροτονηθέντας μὴ ἂν τολμῆσαι πρότερον ἡμῶν ἡγήσασθαι, ἕως [ἂν] ἐδοκιμάσθησαν κατὰ τοὺς νόμους, Ἀλκιβιάδην δὲ τολμᾶν παρὰ τοὺς τῆς πόλεως νόμους ὑπ’ αὐτῶν ταχθῆναι.", "st": "15.6"}, {"sp": "N", "t": "δεινὸν δέ μοι δοκεῖ εἶναι, ὦ ἄνδρες δικασταί, εἰ τῶν μὲν δεδοκιμασμένων ἱππέων οὐκ ἐπὶ τούτοις ἐστὶν ὅντινα βούλονται αὐτοὶ εἰς τοὺς ὁπλίτας καταλέξαι, τῶν δὲ ὁπλιτῶν ἀδοκιμάστων ὄντων ἐπὶ τούτοις ἔσται ὅντιν’ ἂν βούλωνται ἱππεύειν.", "st": "15.7"}, {"sp": "N", "t": "εἰ μὲν τοίνυν, ὦ ἄνδρες δικασταί, ὄντες κύριοι πολλῶν βουλομένων μηδένα τῶν ἄλλων ἱππεύειν εἴασαν, οὐκ ἂν δικαίως χαρίζοισθε αὐτοῖς· εἰ δ’ ἄκυροι ὄντες ὁμολογήσουσι τάξαι, ἐνθυμεῖσθαι χρὴ ὅτι ὀμωμόκατε τὰ δίκαια γνώσεσθαι, ἀλλ’ οὐχ ὅ τι ἂν οὗτοι κελεύωσι ψηφιεῖσθαι, ὥστε οὐδένα χρὴ τῶν δεομένων περὶ πλείονος ὑμῶν αὐτῶν καὶ τῶν ὅρκων ποιεῖσθαι.", "st": "15.8"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, εἴ τῳ δοκεῖ μεγάλη ἡ ζημία εἶναι καὶ λίαν ἰσχυρὸς ὁ νόμος, μεμνῆσθαι χρὴ ὅτι οὐ νομοθετήσοντες περὶ αὐτῶν ἥκετε, ἀλλὰ κατὰ τοὺς κειμένους νόμους ψηφιούμενοι, οὐδὲ τοὺς ἀδικοῦντας ἐλεήσοντες, ἀλλὰ πολὺ μᾶλλον αὐτοῖς ὀργιούμενοι καὶ ὅλῃ τῇ πόλει βοηθήσοντες, εὖ εἰδότες ὅτι ὑπὲρ τῶν παρεληλυθότων ὀλίγους τιμωρησάμενοι πολλοὺς ποιήσετε κοσμιωτέρους ἐν τοῖς μέλλουσι κινδυνεύειν.", "st": "15.9"}, {"sp": "N", "t": "χρὴ δέ, ὦ ἄνδρες δικασταί, ὥσπερ οὗτος ἀμελήσας τῆς πόλεως τὴν αὑτοῦ σωτηρίαν ἐσκέψατο, οὕτως ὑμᾶς ἀμελήσαντας τούτου τῇ πόλει τὰ βέλτιστα ψηφίσασθαι, ἄλλως τε καὶ ὅρκους ὀμωμοκότας καὶ περὶ Ἀλκιβιάδου μέλλοντας ψηφίσασθαι, ὃς ἐὰν ὑμᾶς ἐξαπατήσῃ, καταγελῶν τῆς πόλεως ἄπεισιν· οὐ γὰρ δὴ χάριν γε ὑμῖν ἀποδώσει τῇ ψήφῳ κρύβδην εὖ παθών, ὃς τῶν φίλων τοὺς φανερῶς αὐτὸν εὖ ποιήσαντας κακῶς ποιεῖ.", "st": "15.10"}, {"sp": "N", "t": "ὑμεῖς οὖν, ὦ ἄνδρες δικασταί, τὰς τούτων δεήσεις περὶ ἐλάττονος ποιησάμενοι τὰ δίκαια ψηφίσασθε. ἀποδέδεικται δὲ καταλεγεὶς εἰς τοὺς ὁπλίτας καὶ λιπὼν τὴν τάξιν καὶ τῶν νόμων κωλυόντων ἀδοκίμαστος ἱππεύσας, καὶ περὶ ὧν οἱ νόμοι διαρρήδην οὔτε στρατηγὸν οὔτε ἵππαρχον οὔτε ἄλλον οὐδένα κυριώτερον ἐκείνων ἀποδεικνύουσι, περὶ τούτων ἰδιώτης ὢν τὴν ἐξουσίαν αὑτῷ δεδωκώς.", "st": "15.11"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν καὶ φίλῳ ὄντι Ἀρχεστρατίδῃ βοηθῶν, καὶ Ἀλκιβιάδην ἐχθρὸν ὄντα ἐμαυτοῦ τιμωρούμενος, δέομαι τὰ δίκαια ψηφίσασθαι· ὑμᾶς δὲ χρὴ τὴν αὐτὴν γνώμην ἔχοντας τὴν ψῆφον φέρειν, ἥνπερ ὅτε ᾤεσθε πρὸς τοὺς πολεμίους διακινδυνεύσειν.", "st": "15.12"}, {"sp": "HDR", "t": "ΙϚʹ. Ἐν βουλῇ Μαντιθέῳ δοκιμαζομένῳ ἀπολογία", "st": "16"}, {"sp": "N", "t": "εἰ μὴ συνῄδη, ὦ βουλή, τοῖς κατηγόροις βουλομένοις ἐκ παντὸς τρόπου κακῶς ἐμὲ ποιεῖν, πολλὴν ἂν αὐτοῖς χάριν εἶχον ταύτης τῆς κατηγορίας· ἡγοῦμαι γὰρ τοῖς ἀδίκως διαβεβλημένοις τούτους εἶναι μεγίστων ἀγαθῶν αἰτίους, οἵτινες ἂν αὐτοὺς ἀναγκάζωσιν εἰς ἔλεγχον τῶν αὐτοῖς βεβιωμένων καταστῆναι.", "st": "16.1"}, {"sp": "N", "t": "ἐγὼ γὰρ οὕτω σφόδρα ἐμαυτῷ πιστεύω, ὥστ’ ἐλπίζω καὶ εἴ τις πρός με τυγχάνει ἀηδῶς [ἢ κακῶς] διακείμενος, ἐπειδὰν ἐμοῦ λέγοντος ἀκούσῃ περὶ τῶν πεπραγμένων, μεταμελήσειν αὐτῷ καὶ πολὺ βελτίω με εἰς τὸν λοιπὸν χρόνον ἡγήσεσθαι.", "st": "16.2"}, {"sp": "N", "t": "ἀξιῶ δέ, ὦ βουλή, ἐὰν μὲν τοῦτο μόνον ὑμῖν ἐπιδείξω, ὡς εὔνους εἰμὶ τοῖς καθεστηκόσι πράγμασι καὶ ὡς ἠνάγκασμαι τῶν αὐτῶν κινδύνων μετέχειν ὑμῖν, μηδέν πώ μοι πλέον εἶναι· ἐὰν δὲ φαίνωμαι ⟨καὶ⟩ περὶ τὰ ἄλλα μετρίως βεβιωκὼς καὶ πολὺ παρὰ τὴν δόξαν καὶ παρὰ τοὺς λόγους τοὺς τῶν ἐχθρῶν, δέομαι ὑμῶν ἐμὲ μὲν δοκιμάζειν, τούτους δὲ ἡγεῖσθαι χείρους εἶναι. πρῶτον δὲ ἀποδείξω ὡς οὐχ ἵππευον οὐδ’ ἐπεδήμουν ἐπὶ τῶν τριάκοντα, οὐδὲ μετέσχον τῆς τότε πολιτείας.", "st": "16.3"}, {"sp": "N", "t": "ἡμᾶς γὰρ ὁ πατὴρ πρὸ τῆς ἐν Ἑλλησπόντῳ συμφορᾶς ὡς Σάτυρον τὸν ἐν τῷ Πόντῳ διαιτησομένους ἐξέπεμψε, καὶ οὔτε τῶν τειχῶν καθαιρουμένων ⟨ἐπεδημοῦμεν⟩ οὔτε μεθισταμένης τῆς πολιτείας, ἀλλ’ ἤλθομεν πρὶν τοὺς ἀπὸ Φυλῆς εἰς τὸν Πειραιᾶ κατελθεῖν πρότερον πένθ’ ἡμέραις.", "st": "16.4"}, {"sp": "N", "t": "καίτοι οὔτε ἡμᾶς εἰκὸς ἦν εἰς τοιοῦτον καιρὸν ἀφιγμένους ἐπιθυμεῖν μετέχειν τῶν ἀλλοτρίων κινδύνων, οὔτ’ ἐκεῖνοι φαίνονται τοιαύτην γνώμην ἔχοντες ὥστε καὶ τοῖς ἀποδημοῦσι καὶ τοῖς μηδὲν ἐξαμαρτάνουσι μεταδιδόναι τῆς πολιτείας, ἀλλὰ μᾶλλον ἠτίμαζον καὶ τοὺς συγκαταλύσαντας τὸν δῆμον.", "st": "16.5"}, {"sp": "N", "t": "ἔπειτα δὲ ἐκ μὲν τοῦ σανιδίου τοὺς ἱππεύσαντας σκοπεῖν εὔηθές ἐστιν. ἐν τούτῳ γὰρ πολλοὶ μὲν τῶν ὁμολογούντων ἱππεύειν οὐκ ἔνεισιν, ἔνιοι δὲ τῶν ἀποδημούντων ἐγγεγραμμένοι εἰσίν. ἐκεῖνος δ’ ἐστὶν ἔλεγχος μέγιστος· ἐπειδὴ γὰρ κατήλθετε, ἐψηφίσασθε τοὺς φυλάρχους ἀπενεγκεῖν τοὺς ἱππεύσαντας, ἵνα τὰς καταστάσεις ἀναπράξητε παρ’ αὐτῶν.", "st": "16.6"}, {"sp": "N", "t": "ἐμὲ τοίνυν οὐδεὶς ἂν ἀποδείξειεν οὔτ’ ἀπενεχθέντα ὑπὸ τῶν φυλάρχων οὔτε παραδοθέντα τοῖς συνδίκοις οὔτε κατάστασιν καταβαλόντα. καίτοι πᾶσι ῥᾴδιον τοῦτο γνῶναι, ὅτι ἀναγκαῖον ἦν τοῖς φυλάρχοις, εἰ μὴ ἀποδείξειαν τοὺς ἔχοντας τὰς καταστάσεις, αὐτοῖς ζημιοῦσθαι. ὥστε πολὺ ἂν δικαιότερον ἐκείνοις τοῖς γράμμασιν ἢ τούτοις πιστεύοιτε· ἐκ μὲν γὰρ τούτων ῥᾴδιον ἦν ἐξαλειφθῆναι τῷ βουλομένῳ, ἐν ἐκείνοις δὲ τοὺς ἱππεύσαντας ἀναγκαῖον ἦν ὑπὸ τῶν φυλάρχων ἀπενεχθῆναι.", "st": "16.7"}, {"sp": "N", "t": "ἔτι δέ, ὦ βουλή, εἴπερ ἵππευσα, οὐκ ἂν ἦ ἔξαρνος ὡς δεινόν τι πεποιηκώς, ἀλλ’ ἠξίουν, ἀποδείξας ὡς οὐδεὶς ὑπ’ ἐμοῦ τῶν πολιτῶν κακῶς πέπονθε, δοκιμάζεσθαι. ὁρῶ δὲ καὶ ὑμᾶς ταύτῃ τῇ γνώμῃ χρωμένους, καὶ πολλοὺς μὲν τῶν τότε ἱππευσάντων βουλεύοντας, πολλοὺς δ’ αὐτῶν στρατηγοὺς καὶ ἱππάρχους κεχειροτονημένους. ὥστε μηδὲν δι’ ἄλλο με ἡγεῖσθε ταύτην ποιεῖσθαι τὴν ἀπολογίαν, ἢ ὅτι περιφανῶς ἐτόλμησάν μου καταψεύσασθαι. ἀνάβηθι δέ μοι καὶ μαρτύρησον.", "st": "16.8"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "16.9"}, {"sp": "N", "t": "περὶ μὲν τοίνυν αὐτῆς τῆς αἰτίας οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· δοκεῖ δέ μοι, ὦ βουλή, ἐν μὲν τοῖς ἄλλοις ἀγῶσι περὶ αὐτῶν μόνων τῶν κατηγορημένων προσήκειν ἀπολογεῖσθαι, ἐν δὲ ταῖς δοκιμασίαις δίκαιον εἶναι παντὸς τοῦ βίου λόγον διδόναι. δέομαι οὖν ὑμῶν μετ’ εὐνοίας ἀκροάσασθαί μου. ποιήσομαι δὲ τὴν ἀπολογίαν ὡς ἂν δύνωμαι διὰ βραχυτάτων.", "st": "16.9"}, {"sp": "N", "t": "ἐγὼ γὰρ πρῶτον μὲν, οὐσίας μοι οὐ πολλῆς καταλειφθείσης διὰ τὰς συμφορὰς καὶ τὰς τοῦ πατρὸς καὶ τὰς τῆς πόλεως, δύο μὲν ἀδελφὰς ἐξέδωκα ἐπιδοὺς τριάκοντα μνᾶς ἑκατέρᾳ, πρὸς τὸν ἀδελφὸν δ’ οὕτως ἐνειμάμην ὥστ’ ἐκεῖνον πλέον ὁμολογεῖν ἔχειν ἐμοῦ τῶν πατρῴων, καὶ πρὸς τοὺς ἄλλους ἅπαντας οὕτως βεβίωκα ὥστε μηδεπώποτέ μοι μηδὲ πρὸς ἕνα μηδὲν ἔγκλημα γενέσθαι.", "st": "16.10"}, {"sp": "N", "t": "καὶ τὰ μὲν ἴδια οὕτως διῴκηκα· περὶ δὲ τῶν κοινῶν μοι μέγιστον ἡγοῦμαι τεκμήριον εἶναι τῆς ἐμῆς ἐπιεικείας, ὅτι τῶν νεωτέρων ὅσοι περὶ κύβους ἢ πότους ἢ [περὶ] τὰς τοιαύτας ἀκολασίας τυγχάνουσι τὰς διατριβὰς ποιούμενοι, πάντας αὐτοὺς ὄψεσθέ μοι διαφόρους ὄντας, καὶ πλεῖστα τούτους περὶ ἐμοῦ λογοποιοῦντας καὶ ψευδομένους. καίτοι δῆλον ὅτι, εἰ τῶν αὐτῶν ἐπεθυμοῦμεν, οὐκ ἂν τοιαύτην γνώμην εἶχον περὶ ἐμοῦ.", "st": "16.11"}, {"sp": "N", "t": "ἔτι δ’, ὦ βουλή, οὐδεὶς ἂν ἀποδεῖξαι περὶ ἐμοῦ δύναιτο οὔτε δίκην αἰσχρὰν οὔτε γραφὴν οὔτε εἰσαγγελίαν γεγενημένην· καίτοι ἑτέρους ὁρᾶτε πολλάκις εἰς τοιούτους ἀγῶνας καθεστηκότας. πρὸς τοίνυν τὰς στρατείας καὶ τοὺς κινδύνους τοὺς πρὸς τοὺς πολεμίους σκέψασθε οἷον ἐμαυτὸν παρέχω τῇ πόλει.", "st": "16.12"}, {"sp": "N", "t": "πρῶτον μὲν γάρ, ὅτε τὴν συμμαχίαν ἐποιήσασθε πρὸς [τοὺς] Βοιωτοὺς καὶ εἰς Ἁλίαρτον ἔδει βοηθεῖν, ὑπὸ Ὀρθοβούλου κατειλεγμένος ἱππεύειν, ἐπειδὴ πάντας ἑώρων τοῖς μὲν ἱππεύουσιν ἀσφάλειαν εἶναι δεῖν νομίζοντας, τοῖς δ’ ὁπλίταις κίνδυνον ἡγουμένους, ἑτέρων ἀναβάντων ἐπὶ τοὺς ἵππους ἀδοκιμάστων παρὰ τὸν νόμον ἐγὼ προσελθὼν ἔφην τῷ Ὀρθοβούλῳ ἐξαλεῖψαί με ἐκ τοῦ καταλόγου, ἡγούμενος αἰσχρὸν εἶναι τοῦ πλήθους μέλλοντος κινδυνεύειν ἄδειαν ἐμαυτῷ παρασκευάσαντα στρατεύεσθαι. καί μοι ἀνάβηθι, Ὀρθόβουλε.", "st": "16.13"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "16.14"}, {"sp": "N", "t": "συλλεγέντων τοίνυν τῶν δημοτῶν πρὸ τῆς ἐξόδου, εἰδὼς αὐτῶν ἐνίους πολίτας μὲν χρηστοὺς ὄντας καὶ προθύμους, ἐφοδίων δὲ ἀποροῦντας, εἶπον ὅτι χρὴ τοὺς ἔχοντας παρέχειν τὰ ἐπιτήδεια τοῖς ἀπόρως διακειμένοις. καὶ οὐ μόνον τοῦτο συνεβούλευον τοῖς ἄλλοις, ἀλλὰ καὶ αὐτὸς ἔδωκα δυοῖν ἀνδροῖν τριάκοντα δραχμὰς ἑκατέρῳ, οὐχ ὡς πολλὰ κεκτημένος, ἀλλ’ ἵνα παράδειγμα τοῦτο τοῖς ἄλλοις γένηται. καί μοι ἀνάβητε.", "st": "16.14"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "16.15"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν, ὦ βουλή, εἰς Κόρινθον ἐξόδου γενομένης καὶ πάντων προειδότων ὅτι δεήσει κινδυνεύειν, ἑτέρων ἀναδυομένων ἐγὼ διεπραξάμην ὥστε τῆς πρώτης τεταγμένος μάχεσθαι τοῖς πολεμίοις· καὶ μάλιστα τῆς ἡμετέρας φυλῆς δυστυχησάσης, καὶ πλείστων ἐναποθανόντων ὕστερος ἀνεχώρησα τοῦ σεμνοῦ Στειριῶς τοῦ πᾶσιν ἀνθρώποις δειλίαν ὠνειδικότος.", "st": "16.15"}, {"sp": "N", "t": "καὶ οὐ πολλαῖς ἡμέραις ὕστερον μετὰ ταῦτα ἐν Κορίνθῳ χωρίων ἰσχυρῶν κατειλημμένων, ὥστε τοὺς πολεμίους μὴ δύνασθαι παριέναι, Ἀγησιλάου δ’ εἰς τὴν Βοιωτίαν ἐμβαλόντος ψηφισαμένων τῶν ἀρχόντων ἀποχωρίσαι τάξεις αἵτινες βοηθήσουσι, φοβουμένων ἁπάντων (εἰκότως, ὦ βουλή· δεινὸν γὰρ ἦν ἀγαπητῶς ὀλίγῳ πρότερον σεσωσμένους ἐφ’ ἕτερον κίνδυνον ἰέναι) προσελθὼν ἐγὼ τὸν ταξίαρχον ἐκέλευον ἀκληρωτὶ τὴν ἡμετέραν τάξιν πέμπειν.", "st": "16.16"}, {"sp": "N", "t": "ὥστ’ εἴ τινες ὑμῶν ὀργίζονται τοῖς τὰ μὲν τῆς πόλεως ἀξιοῦσι πράττειν, ἐκ δὲ τῶν κινδύνων ἀποδιδράσκουσιν, οὐκ ἂν δικαίως περὶ ἐμοῦ τὴν γνώμην ταύτην ἔχοιεν· οὐ γὰρ μόνον τὰ προσταττόμενα ταττόμενα ἐποίουν προθύμως, ἀλλὰ καὶ κινδυνεύειν ἐτόλμων. καὶ ταῦτ’ ἐποίουν οὐχ ὡς οὐ δεινὸν ἡγούμενος εἶναι Λακεδαιμονίοις μάχεσθαι, ἀλλ’ ἵνα, εἴ ποτε ἀδίκως εἰς κίνδυνον καθισταίμην, διὰ ταῦτα βελτίων ὑφ’ ὑμῶν νομιζόμενος ἁπάντων τῶν δικαίων τυγχάνοιμι. καί μοι ἀνάβητε τούτων μάρτυρες.", "st": "16.17"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "16.18"}, {"sp": "N", "t": "τῶν τοίνυν ἄλλων στρατειῶν καὶ φρουρῶν οὐδεμιᾶς ἀπελείφθην πώποτε, ἀλλὰ πάντα τὸν χρόνον διατετέλεκα μετὰ τῶν πρώτων μὲν τὰς ἐξόδους ποιούμενος, μετὰ τῶν τελευταίων δὲ ἀναχωρῶν· καίτοι χρὴ τοὺς φιλοτίμως καὶ κοσμίως πολιτευομένους ἐκ τῶν τοιούτων σκοπεῖν, ἀλλ’ οὐκ εἴ τις κομᾷ, διὰ τοῦτο μισεῖν· τὰ μὲν γὰρ τοιαῦτα ἐπιτηδεύματα οὔτε τοὺς ἰδιώτας οὔτε τὸ κοινὸν τῆς πόλεως βλάπτει, ἐκ δὲ τῶν κινδυνεύειν ἐθελόντων πρὸς τοὺς πολεμίους ἅπαντες ὑμεῖς ὠφελεῖσθε.", "st": "16.18"}, {"sp": "N", "t": "ὥστε οὐκ ἄξιον ἀπ’ ὄψεως, ὦ βουλή, οὔτε φιλεῖν οὔτε μισεῖν οὐδένα, ἀλλ’ ἐκ τῶν ἔργων σκοπεῖν· πολλοὶ μὲν γὰρ μικρὸν διαλεγόμενοι καὶ κοσμίως ἀμπεχόμενοι μεγάλων κακῶν αἴτιοι γεγόνασιν, ἕτεροι δὲ τῶν τοιούτων ἀμελοῦντες πολλὰ κἀγαθὰ ὑμᾶς εἰσιν εἰργασμένοι.", "st": "16.19"}, {"sp": "N", "t": "ἤδη δέ τινων ᾐσθόμην, ὦ βουλή, καὶ διὰ ταῦτα ἀχθομένων μοι, ὅτι νεώτερος ὢν ἐπεχείρησα λέγειν ἐν τῷ δήμῳ. ἐγὼ δὲ τὸ μὲν πρῶτον ἠναγκάσθην ὑπὲρ τῶν ἐμαυτοῦ πραγμάτων δημηγορῆσαι, ἔπειτα μέντοι καὶ ἐμαυτῷ δοκῶ φιλοτιμότερον διατεθῆναι τοῦ δέοντος, ἅμα μὲν τῶν προγόνων ἐνθυμούμενος, ὅτι οὐδὲν πέπαυνται τὰ τῆς πόλεως πράττοντες,", "st": "16.20"}, {"sp": "N", "t": "ἅμα δὲ ὑμᾶς ὁρῶν (τὰ γὰρ ἀληθῆ χρὴ λέγειν) τοὺς τοιούτους μόνους ⟨τινὸς⟩ ἀξίους νομίζοντας εἶναι, ὥστε ὁρῶν ὑμᾶς ταύτην τὴν γνώμην ἔχοντας τίς οὐκ ἂν ἐπαρθείη πράττειν καὶ λέγειν ὑπὲρ τῆς πόλεως; ἔτι δὲ τί ἂν τοῖς τοιούτοις ἄχθοισθε; οὐ γὰρ ἕτεροι περὶ αὐτῶν κριταί εἰσιν, ἀλλ’ ὑμεῖς.", "st": "16.21"}, {"sp": "HDR", "t": "ΙΖʹ. Περὶ τῶν Ἐράτωνος χρημάτων: πρὸς τὸ δημόσιον", "st": "17"}, {"sp": "N", "t": "ἴσως τινὲς ὑμῶν, ὦ ἄνδρες δικασταί, διὰ τὸ βούλεσθαί με ἄξιον εἶναί τινος ἡγοῦνται καὶ εἰπεῖν ἂν μᾶλλον ἑτέρου δύνασθαι· ἐγὼ δὲ τοσούτου δέω περὶ τῶν μὴ, προσηκόντων ἱκανὸς εἶναι λέγειν, ὥστε δέδοικα μή, καὶ περὶ ὧν ἀναγκαῖόν μοί ἐστι λέγειν, ἀδύνατος ὦ τὰ δέοντα εἰπεῖν. οἴμαι μὲν οὖν, ἐάν πάντα διηγήσωμαι τὰ πεπραγμένα ἡμῖν πρὸς Ἐράτωνα καὶ τοὺς ἐκείνου παῖδας, ῥαδίως ἐξ αὐτῶν ὑμᾶς εὑρήσειν ἃ προσήκει σκέψασθαι περὶ ταύτης τῆς διαδικασίας. ἐξ ἀρχῆς οὖν ἀκούσατε.", "st": "17.1"}, {"sp": "N", "t": "ἐράτων ὁ Ἐρασιφῶντος πατὴρ ἐδανείσατο παρὰ τοῦ ἐμοῦ πάππου τάλαντα δύο. ὅτι μὲν οὖν ἔλαβε τἀργύριον καὶ ὡς τοσοῦτόν γε ἐδεήθη δανείσασθαι, [καὶ] ὧν ἐναντίον ἐδόθη, μάρτυρας ὑμῖν παρέξομαι· ἃ δ’ ἐχρήσατο αὐτῷ καὶ ὅσα ὠφελήθη, οἱ μᾶλλόν τε ἐμοῦ εἰδότες καὶ παραγεγενημένοι οἷς ἐκεῖνος ἔπραττε διηγήσονται ὑμῖν καὶ μαρτυρήσουσι. καί μοι κάλει μάρτυρας.", "st": "17.2"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.3"}, {"sp": "N", "t": "ἕως τοίνυν ὁ Ἐράτων ἔζη, τούς τε τόκους ἀπελαμβάνομεν καὶ τἆλλα τὰ συγκείμενα· ἐπειδὴ δὲ ἐτελεύτησε καταλιπὼν ὑοὺς τρεῖς, Ἐρασιφῶντα καὶ Ἐράτωνα καὶ Ἐρασίστρατον, οὗτοι οὐδὲν ἔτι ἡμῖν τῶν δικαίων ἐποίουν. ἐν μὲν οὖν τῷ πολέμῳ, διότι οὐκ ἦσαν δίκαι, οὐ δυνατοὶ ἦμεν παρ’ αὐτῶν ἃ ὤφειλον πράξασθαι· ἐπειδὴ δὲ εἰρήνη ἐγένετο, ὅτε περ πρῶτον αἱ ἀστικαὶ δίκαι ἐδικάζοντο, λαχὼν ὁ πατὴρ παντὸς τοῦ συμβολαίου Ἐρασιστράτῳ, ὅσπερ μόνος τῶν ἀδελφῶν ἐπεδήμει, κατεδικάσατο ἐπὶ Ξεναινέτου ἄρχοντος. μάρτυρας δὲ καὶ τούτων παρέξομαι ὑμῖν. καί μοι κάλει μάρτυρας.", "st": "17.3"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.4"}, {"sp": "N", "t": "ὅτι μὲν τὰ Ἐράτωνος δικαίως ἂν ἡμέτερα εἴη, ἐκ τούτων ῥᾴδιον εἰδέναι, ὅτι δὲ πάντα δημεύεται, ἐξ αὐτῶν ⟨τῶν⟩ ἀπογραφῶν· τρεῖς γὰρ καὶ τέτταρες ἕκαστα ἀπογεγράφασι. καίτοι τοῦτό γε παντὶ εὔγνωστον, ὅτι οὐκ ἂν παρέλιπον, εἴ τι ἄλλο τῶν Ἐράτωνος οἷόν τε ἦν δημεύειν, οἱ πάντα τὰ Ἐράτωνος ἀπογράφοντες καὶ ἃ ἐγὼ πολὺν ἤδη χρόνον κέκτημαι. ὡς μὲν οὖν ἡμῖν οὐδ’ ἑτέρωθεν εἰσπράξασθαι οἷόν τε, ἐὰν ὑμεῖς ταῦτα δημεύσητε,", "st": "17.4"}, {"sp": "N", "t": "εὔγνωστόν μοι δοκεῖ εἶναι· ὡς δὲ τὴν ἀμφισβήτησιν ἐποιησάμην πρός τε ὑμᾶς καὶ τοὺς ἰδιώτας, ἔτι ἀκούσατε. ἕως μὲν γὰρ ἡμῖν οἱ Ἐρασιφῶντος οἰκεῖοι τούτων τῶν χρημάτων ἠμφεσβήτουν, ἅπαντα ἠξίουν ἐμὰ εἶναι, διότι ὑπὲρ ἅπαντος τοῦ χρέως ἀντιδικῶν πρὸς τὸν πατέρα ὁ Ἐρασίστρατος ἡττήθη· καὶ τὰ μὲν Σφηττοῖ ἤδη τρία ἔτη μεμίσθωκα, τῶν δὲ Κικυννοῖ καὶ τῆς οἰκίας ἐδικαζόμην τοῖς ἔχουσι. πέρυσι μὲν οὖν διεγράψαντό μου τὰς δίκας, ἔμποροι φάσκοντες εἶναι· νυνὶ δὲ λαχόντος ἐν τῷ Γαμηλιῶνι μηνὶ οἱ ναυτοδίκαι οὐκ ἐξεδίκασαν.", "st": "17.5"}, {"sp": "N", "t": "ἐπειδὴ δ’ ὑμῖν τὰ Ἐρασιφῶντος δημεύειν ἔδοξεν, ἀφεὶς τῇ πόλει τὼ δύο μέρει τὰ Ἐρασιστράτου ἀξιῶ μοι ψηφισθῆναι, διότι ταῦτά γε ἤδη καὶ πρότερον ἐγνώκατε ἡμέτερα εἶναι. ὡρισάμην οὖν ἐμαυτῷ τὸ τρίτον μέρος τῆς ἐκείνων οὐσίας οὐ τὴν ἀκρίβειαν ἐπισκεψάμενος, ἀλλὰ πολλῷ πλέον ἢ τὼ δύο μέρει τῷ δημοσίῳ ὑπολιπών.", "st": "17.6"}, {"sp": "N", "t": "ῥᾴδιον δὲ γνῶναι ἐκ τοῦ τιμήματος τοῦ ἐπιγεγραμμένου τοῖς χρήμασιν. ἅπαντα μὲν γὰρ πλείονος ἢ ταλάντου τετίμηνται, ὧν δ’ ἐγὼ ἀμφισβητῶ τῷ μὲν πέντε μνᾶς τῷ δὲ χιλίας δραχμὰς ἐπεγραψάμην· καὶ εἰ πλείονος ἄξιά ἐστιν ἢ τοσούτου, ἀποκηρυχθέντων τὸ περιττὸν ἡ πόλις λήψεται.", "st": "17.7"}, {"sp": "N", "t": "ἵνα οὖν εἰδῆτε ὅτι ταῦτα ἀληθῆ ἐστι, μάρτυρας ὑμῖν παρέξομαι πρῶτον μὲν τοὺς μεμισθωμένους παρ’ ἐμοῦ τὸ Σφηττοῖ χωρίον, ἔπειτα τοῦ Κικυννοῖ τοὺς γείτονας, οἳ ἴσασιν ἡμᾶς ἤδη τρία ἔτη ἀμφισβητοῦντας, ἔτι δὲ τούς τε πέρυσιν ἄρξαντας, πρὸς οὓς αἱ δίκαι ἐλήχθησαν, καὶ τοὺς νῦν ναυτοδίκας.", "st": "17.8"}, {"sp": "N", "t": "ἀναγνωσθήσονται δὲ ὑμῖν καὶ αὗται αἱ ἀπογραφαί· ἐκ τούτων γὰρ μάλιστα γνώσεσθε ὅτι οὔτε νεωστὶ ταῦτα τὰ χρήματα ἀξιοῦμεν ἡμέτερα εἶναι, οὔτε νυνὶ τῷ δημοσίῳ πλειόνων ἀμφισβητοῦμεν ἢ τῷ ἔμπροσθεν χρόνῳ τοῖς ἰδιώταις. καί μοι κάλει μάρτυρας.", "st": "17.9"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.10"}, {"sp": "N", "t": "ὅτι μέν, ὦ ἄνδρες δικασταί, οὐ παρὰ τὸ δίκαιον ἀξιῶ μοι ψηφίσασθαι τὸ διαδίκασμα, ἀλλ’ αὐτὸς τῇ πόλει πολλὰ τῶν ἐμαυτοῦ ἀφεὶς τοῦτο ἀξιῶ μοι ἀποδοθῆναι, ἀποδέδεικται. ἤδη δέ μοι δοκεῖ δίκαιον εἶναι καὶ δεηθῆναι ὑμῶν τε καὶ τῶν συνδίκων ἐναντίον ὑμῶν.", "st": "17.10"}, {"sp": "HDR", "t": "ΙΗʹ. Περὶ τῆς δημεύσεως τῶν τοῦ Νικίου ἀδελφοῦ ἐπίλογος", "st": "18"}, {"sp": "N", "t": "ἐνθυμήθητε τοίνυν, ὦ ἄνδρες δικασταί, οἷοί τινες ὄντες πολῖται καὶ αὐτοὶ καὶ ὧν προσήκοντες ἀδικούμενοι ἀξιοῦμεν ἐλεεῖσθαι ὑφ’ ὑμῶν καὶ τῶν δικαίων τυγχάνειν· οὐ γὰρ μόνον περὶ τῆς οὐσίας ἀγωνιζόμεθα, ἀλλὰ καὶ περὶ τῆς πολιτείας, εἰ χρὴ δημοκρατουμένης τῆς πόλεως ἡμῖν μετεῖναι. πρῶτον μὲν οὖν περὶ Νικίου τοῦ ἡμετέρου θείου ἀναμνήσθητε.", "st": "18.1"}, {"sp": "N", "t": "ἐκεῖνος γὰρ ὅσα μὲν τῇ ἑαυτοῦ γνώμῃ χρώμενος ὑπὲρ τοῦ ὑμετέρου ἔπραξε, πανταχοῦ φανήσεται πολλῶν μὲν καὶ ἀγαθῶν αἴτιος τῇ πόλει γεγενημένος, πλεῖστα δὲ καὶ μέγιστα κακὰ τοὺς πολεμίους εἰργασμένος· ὅσα δὲ οὐ βουλόμενος ἀλλ’ ἄκων ἠναγκάσθη ποιῆσαι, τῶν μὲν κακῶν οὐκ ἐλάχιστον αὐτὸς μετέσχε μέρος, τὴν δ’ αἰτίαν τῆς συμφορᾶς οἱ πείσαντες ὑμᾶς δικαίως ἂν ἔχοιεν,", "st": "18.2"}, {"sp": "N", "t": "ἐπεὶ τήν γε πρὸς ὑμᾶς εὔνοιαν καὶ τὴν ἀρετὴν ⟨τὴν⟩ αὑτοῦ ἐν ταῖς εὐτυχίαις ταῖς ὑμετέραις καὶ ταῖς δυστυχίαις ταῖς τῶν ἐχθρῶν ἐπεδείξατο· στρατηγῶν γὰρ πολλὰς μὲν πόλεις εἷλε, πολλὰ δὲ καὶ καλὰ κατὰ τῶν πολεμίων ἔστησε τρόπαια, ὧν καθ’ ἓν ἕκατον πολὺ ἂν ἔργον εἴη λέγειν.", "st": "18.3"}, {"sp": "N", "t": "Εὐκράτης τοίνυν, ἀδελφὸς μὲν ὢν ἐκεῖνον, πατὴρ δ’ ἐμός, ἤδη τῆς τελευταίας ναυμαχίας γεγενημένης φανερὰν ἐπεδείξατο τὴν εὔνοιαν ἣν εἶχε περὶ τὸ πλῆθος τὸ ὑμέτερον· ἡττημένων γὰρ ἐν ⟨τῇ⟩ ναυμαχίᾳ στρατηγὸς ὑφ’ ὑμῶν ᾑρημένος καὶ παρακαλούμενος μετέχειν τῆς ὀλιγαρχίας ὑπὸ τῶν ἐπιβουλευόντων τῷ πλήθει,", "st": "18.4"}, {"sp": "N", "t": "οὐκ ἠθέλησεν αὐτοῖς πείθεσθαι, ἐν τοιούτῳ καιρῷ ληφθεὶς ἐν ᾧ οἱ πλεῖστοι τῶν ἀνθρώπων καὶ μεταβάλλονται πρὸς τὰ παρόντα καὶ ταῖς τύχαις ἐίκουσι, δυστυχοῦντος τοῦ δήμου, οὐκ ἀπελαυνόμενος τῆς πολιτείας οὐδ’ ἰδίας ἔχθρας ὑπαρχούσης πρὸς ἄρξειν μέλλοντας, ἀλλ’ ἐξὸν αὐτῷ καὶ τῶν τριάκοντα γενέσθαι καὶ μηδενὸς ἔλαττον δύνασθαι, μᾶλλον εἵλετο πράττων ὑπὲρ τῆς ὑμετέρας σωτηρίας ἀπολέσθαι ἢ ἐπιδεῖν ⟨τὰ⟩ τείχη καθαιρούμενα καὶ τὰς ναῦς τοῖς πολεμίοις παραδιδομένας καὶ τὸ ὑμέτερον πλῆθος καταδεδουλωμένον.", "st": "18.5"}, {"sp": "N", "t": "καὶ οὐ πολλῷ χρόνῳ ὕστερον Νικήρατος, ἀνεψιὸς ὢν ἐμὸς καὶ ὑὸς Νικίου, εὔνους ὢν τῷ ὑμετέρῳ πλήθει, συλληφθεὶς ὑπὸ τῶν τριάκοντα ἀπέθανεν, οὔτε γένει οὔτε οὐσίᾳ οὔθ’ ἡλικίᾳ δοκῶν ἀνάξιος εἶναι τῆς πολιτείας μετασχεῖν· ἀλλὰ τοιαῦτα ἐνομίζετο τὰ ὑπάρχοντα αὐτῷ πρὸς τὸ ὑμέτερον πλῆθος εἶναι καὶ διὰ τοὺς προγόνους καὶ αὐτόν, ὥστε οὐκ ἄν ποθ’ ἑτέρας ἐπιθυμῆσαι πολιτείας.", "st": "18.6"}, {"sp": "N", "t": "συνῄδεσαν γὰρ ἅπασιν αὐτοῖς ὑπὸ τῆς πόλεως τιμωμένοις, καὶ πολλαχοῦ μὲν ὑπὲρ ὑμῶν κεκινδυνευκόσι, μεγάλας δ’ εἰσφορὰς εἰσενηνοχόσι καὶ λελῃτουργηκόσι κάλλιστα, καὶ τῶν ἄλλων οὐδενὸς πώποτ’ ἀποστᾶσιν ὧν ἡ πόλις αὐτοῖς προσέταξεν, ἀλλὰ προθύμως λῃτουργοῦσι.", "st": "18.7"}, {"sp": "N", "t": "καίτοι τίνες ἂν ἡμῶν εἴησαν δυστυχέστεροι, εἰ ἐν μὲν τῇ ὀλιγαρχίᾳ ἀποθνῄσκοιμεν εὖνοι ὄντες τῷ πλήθει, ἐν δὲ τῇ δημοκρατίᾳ ὡς κακόνοι ὄντες τῷ πλήθει ἀποστεροίμεθα τῶν ὄντων;", "st": "18.8"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, καὶ Διόγνητος διαβληθεὶς μὲν ὑπὸ τῶν συκοφαντῶν φεύγων ὤχετο, μετ’ ὀλίγων δὲ τῶν ἐκπεπτωκότων οὔτ’ ἐπὶ τὴν πόλιν ἐστρατεύσατο οὔτ’ εἰς Δεκέλειαν ἀφίκετο· οὐδ’ ἔστιν ὅτου κακοῦ αἴτιος οὔτε φεύγων οὔτε κατελθὼν τῷ ὑμετέρῳ πλήθει γεγένηται, ἀλλ’ εἰς τοῦτ’ ἀρετῆς ἦλθεν ὥστε μᾶλλον ὠργίζετο τοῖς εἰς ὑμᾶς ἡμαρτηκόσιν ἢ τοῖς αὐτῷ τῆς καθόδου αἰτίοις γεγενημένοις ⟨χάριν ᾔδει⟩.", "st": "18.9"}, {"sp": "N", "t": "καὶ ἀρχὴν μὲν οὐδεμίαν ἦρξεν ἐν τῇ ὀλιγαρχίᾳ· ἐπειδὴ δὲ τάχιστα ἦλθον εἰς τὴν Ἀκαδήμειαν Λακεδαιμόνιοι καὶ Παυσανίας, λαβὼν τὸν Νικηράτου καὶ ἡμᾶς παῖδας ὄντας, ἐκεῖνον μὲν κατέθηκεν ἐπὶ τοῖς γόνασι τοῖς Παυσανίου, ἡμᾶς δὲ παραστησάμενος ἔλεγε πρὸς ἐκεῖνον καὶ τοὺς ἄλλους τοὺς παρόντας ὅσα εἴημεν πεπονθότες καὶ οἵαις τύχαις κεχρημένοι, καὶ ἠξίου Παυσανίαν βοηθῆσαι καὶ διὰ τὴν φιλίαν καὶ διὰ τὴν ξενίαν τὴν ὑπάρχουσαν, καὶ τιμωρὸν γενέσθαι τῶν εἰς ἡμᾶς ἡμαρτηκότων.", "st": "18.10"}, {"sp": "N", "t": "ὅθεν Παυσανίας ἤρξατο εὔνους εἶναι τῷ δήμῳ, παράδειγμα ποιούμενος πρὸς τοὺς ἄλλους Λακεδαιμονίους τὰς ἡμετέρας συμφορὰς τῆς τῶν τριάκοντα πονηρίας· δῆλον γὰρ ἅπασι τοῖς ἐλθοῦσι Πελοποννησίων ἐγεγένητο, ὅτι οὐ τοὺς πονηροτάτους τῶν πολιτῶν ἀπέκτεινον, ἀλλ’ οἷς μάλιστα προσῆκον καὶ διὰ γένος καὶ διὰ πλοῦτον καὶ διὰ τὴν ἄλλην ἀρετὴν τιμᾶσθαι.", "st": "18.11"}, {"sp": "N", "t": "οὕτω δ’ ἠλεούμεθα καὶ πᾶσι δεινὰ ἐδοκοῦμεν πεπονθέναι, ὥστε Παυσανίας τὰ μὲν παρὰ τῶν τριάκοντα ξένια οὐκ ἠθέλησε λαβεῖν, τὰ δὲ παρ’ ἡμῶν ἐδέξατο. καίτοι δεινόν, ὦ ἄνδρες δικασταί, ὑπὸ μὲν τῶν πολεμίων παῖδας ἡμᾶς ὄντας ἐλεεῖσθαι, οἳ τῇ ὀλιγαρχία βοηθήσοντες ἦλθον, ὑπὸ δ’ ὑμῶν, ὦ ἄνδρες δικασταί, τοιούτους γεγενημένους τῶν ὄντων ἀποστερεῖσθαι, ὧν οἱ πατέρες ὑπὲρ τῆς δημοκρατίας ἀπέθανον.", "st": "18.12"}, {"sp": "N", "t": "εὖ δ’ οἶδ’, ὦ ἄνδρες δικασταί, ὅτι περὶ πλείστου ἂν ποιήσαιτο Πολίοχος τοῦτον τὸν ἀγῶνα κατορθῶσαι, ἡγούμενος αὑτῷ καλὴν εἶναι τὴν ἐπίδειξιν καὶ πρὸς τοὺς πολίτας καὶ τοὺς ξένους, ὅτι Ἀθήνῃσι τοσοῦτον δύναται, ὥσθ’ ὑμᾶς τοὺς αὐτούς, περὶ ὧν ὅρκους ὀμωμόκατε, ὑμῖν αὐτοῖς τὰ ἐναντία ποιεῖν ψηφίζεσθαι.", "st": "18.13"}, {"sp": "N", "t": "πάντες γὰρ εἴσονται ὅτι τότε μὲν χιλίαις δραχμαῖς ἐζημιώσατε τὸν βουλόμενον τὴν ἡμετέραν γῆν δημοσίαν ποιῆσαι, νυνὶ δὲ κελεύων δημεῦσαι νενίκηκε, καὶ περὶ τούτων δὴ ἀμφοτέρων Ἀθηναῖοι, παρὰ νόμον φεύγοντος τοῦ αὐτοῦ ἀνδρός,", "st": "18.14"}, {"sp": "N", "t": "τἀναντία σφίσιν αὐτοῖς ἐψηφίσαντο. οὐκ οὖν αἰσχρόν, εἰ ἃ μὲν Λακεδαιμονίοις συνέθεσθε βεβαιώσετε, ἃ δὲ αὑτοῖς ἐψηφίσασθε οὕτω ῥᾳδίως διαλύσετε, καὶ τὰς μὲν πρὸς ἐκείνους συνθήκας κυρίας ποιήσετε, τὰς δὲ πρὸς αὑτοὺς ἀκύρους; καὶ τοῖς μὲν ἄλλοις Ἕλλησιν ὀργίζεσθε, εἴ τις Λακεδαιμονίους ὑμῶν περὶ πλείονος ποιεῖται, ὑμεῖς δ’ αὐτοὶ φανήσεσθε πιστότερον πρὸς ἐκείνους ἢ πρὸς ὑμᾶς αὐτοὺς διακείμενοι;", "st": "18.15"}, {"sp": "N", "t": "ἄξιον δὲ μάλιστ’ ἀγανακτῆσαι ὅτι οὕτως ἤδη οἱ τὰ τῆς πόλεως πράττοντες διάκεινται, ὥστ’ οὐχ ὅ τι ἂν τῇ πόλει βέλτιστον ᾖ, τοῦτο οἱ ῥήτορες λέγουσιν, ἀλλ’ ἀφ’ ὧν ἂν αὐτοὶ κερδαίνειν μέλλωσι, ταῦτα ὑμεῖς ψηφίζεσθε.", "st": "18.16"}, {"sp": "N", "t": "καὶ εἰ μὲν τῷ ὑμετέρῳ πλήθει συνέφερε τοὺς μὲν ἔχειν τὰ αὑτῶν, τῶν δὲ ἀδίκως δεδημεῦσθαι τὴν οὐσίαν, εἰκότως ἂν ἠμελεῖτε τῶν ὑφ’ ἡμῶν λεγομένων· νυνὶ δὲ πάντες ἂν ὁμολογήσαιτε ὁμόνοιαν ⟨μὲν⟩ μέγιστον ἀγαθὸν εἶναι πόλει, στάσιν δὲ πάντῶν κακῶν αἰτίαν, διαφέρεσθαι δὲ πρὸς ἀλλήλους ἐκ τῶν τοιούτων μάλιστ’, ἐὰν οἱ μὲν τῶν ἀλλοτρίων ἐπιθυμῶσιν, οἱ δ’ ἐκ τῶν ὄντων ἐκπίπτωσι.", "st": "18.17"}, {"sp": "N", "t": "καὶ ταῦθ’ ὑμεῖς ἔγνωτε νεωστὶ κατελθόντες, ὀρθῶς βουλευόμενοι· ἔτι γὰρ ἐμέμνησθε τῶν γεγενημένων συμφορῶν, καὶ τοῖς θεοῖς εἰς ὁμόνοιαν ηὔχεσθε καταστῆναι τὴν πόλιν μᾶλλον ἢ ἐπὶ τιμωρίαν τῶν παρεληλυθότων τραπομένων τὴν μὲν πόλιν στασιάσαι, τοὺς δὲ λέγοντας ταχέως πλουτῆσαι.", "st": "18.18"}, {"sp": "N", "t": "καίτοι πλείων συγγνώμη μνησικακεῖν νεωστὶ κατεληλυθόσιν, ἔτι τῆς ὀργῆς οὔσης προσφάτου, ἢ τοσούτῳ χρόνῳ ὕστερον ἐπὶ τιμωρίαν τῶν παρεληλυθότων τραπέσθαι, ὑπὸ τοιούτων πεισθέντας οἳ ἐν ἄστει μείναντες ταύτην ὑμῖν οἴονται διδόναι πίστιν τῆς αὑτῶν εὐνοίας, ἑτέρους κακοὺς ποιοῦντες, ἀλλ’ οὐ σφᾶς αὐτοὺς χρηστοὺς παρέχοντες, καὶ νυνὶ τῶν τῆς πόλεως εὐτυχιῶν ἀπολαύοντες, ἀλλ’ οὐ πρότερον τῶν ὑμετέρων κινδύνων μετέχοντες.", "st": "18.19"}, {"sp": "N", "t": "καὶ εἰ μὲν ἑωρᾶτε, ὦ ἄνδρες δικασταί, σῳζόμενα τῇ πόλει τὰ ὑπὸ τούτων δημευόμενα, συγγνώμην ἂν εἴχομεν· νῦν δ’ ἐπίστασθε ὅτι τὰ μὲν αὐτῶν ὑπὸ τούτων ἀφανίζεται, τὰ δὲ πολλοῦ ἄξια ὄντα ὀλίγου πιπράσκεται. ἐὰν δ’ ἐμοὶ πείθησθε, οὐκ ἐλάττω ἀπ’ αὐτῶν ὑμεῖς ὠφεληθήσεσθε ἢ ἡμεῖς οἱ κεκτημένοι,", "st": "18.20"}, {"sp": "N", "t": "ἐπεὶ καὶ νυνὶ Διόμνηστος καὶ ἐγὼ καὶ ὁ ἀδελφός ἐκ μιᾶς οἰκίας τρεῖς ὄντες τριηραρχοῦμεν, καὶ ὅταν ἡ πόλις δέηται χρημάτων, ἀπὸ τούτων ὑμῖν εἰσφέρομεν. ὡς οὖν ἡμῶν ταύτῃ τῇ γνώμῃ χρωμένων, καὶ τῶν προγόνων τῶν ἡμετέρων τοιούτων γεγενημένων,", "st": "18.21"}, {"sp": "N", "t": "φείδεσθε ἡμῶν. οὐδὲν γὰρ ἂν ἡμᾶς κωλύοι, ὦ ἄνδρες δικασταί, ἀθλιωτάτους εἶναι, ἐπὶ μὲν τῶν τριάκοντα ὀρφανοὺς καταλειφθέντας, ἐν δὲ τῇ δημοκρατίᾳ τῶν ὄντων ἐστερημένους, οἷς ἡ τύχη παρέδωκεν ὥστ’ ἔτι ἡμᾶς παῖδας ὄντας ἐπὶ τὴν Παυσανίου σκηνὴν ἐλθόντας βοηθῆσαι τῷ πλήθει. καὶ τοιούτων ἡμῖν ὑπαρχόντων εἰς τίνας ἂν ἐβουλήθημεν δικαστὰς καταφυγεῖν;", "st": "18.22"}, {"sp": "N", "t": "οὐκ εἰς τοὺς οὕτω πολιτευομένους, ὑπὲρ ἧς πολιτείας καὶ ὁ πατὴρ καὶ οἱ προσήκοντες ἡμῖν ἀπέθανον; νῦν τοίνυν ταύτην ἀνθ’ ἁπάντων ἀπαιτοῦμεν ὑμᾶς τὴν χάριν, μὴ περιιδεῖν ἡμᾶς ἀπόρως διατεθέντας μηδ’ ἐνδεεῖς τῶν ἐπιτηδείων γενομένους, μηδὲ τὴν τῶν προγόνων εὐδαιμονίαν καταλῦσαι, ἀλλὰ πολὺ μᾶλλον παράδειγμα ποιῆσαι τοῖς βουλομένοις τὴν πόλιν εὖ ποιεῖν, οἴων ὑμῶν ἐν τοῖς κινδύνοις τεύξονται.", "st": "18.23"}, {"sp": "N", "t": "οὐκ ἔχω, ὦ ἄνδρες δικασταί, οὕστινας δεησομένους ὑπὲρ ἡμῶν ἀναβιβάσομαι· τῶν γὰρ προσηκόντων οἱ μὲν ἄνδρας ἀγαθοὺς αὑτοὺς παρασχόντες καὶ μεγάλην τὴν πόλιν ποιοῦντες ἐν τῷ πολέμῳ τεθνᾶσιν, οἱ δ’ ὑπὲρ τῆς δημοκρατίας καὶ τῆς ὑμετέρας ἐλευθερίας ὑπὸ τῶν τριάκοντα κώνειον πιόντες,", "st": "18.24"}, {"sp": "N", "t": "ὥστε τῆς ἐρημίας ἡμετέρας αἴτιαι γεγόνασιν αἵ τε τῶν προσηκόντων ἀρεταὶ καὶ αἱ τῆς πόλεως συμφοραί. ὧν ἄξιον ὑμᾶς ἐνθυμηθέντας προθύμως ἡμῖν βοηθῆσαι, ἡγησαμένους τούτους ἂν ἐν δημοκρατία δικαίως εὖ πάσχειν ὑφ’ ὑμῶν, οἵπερ ἐν ὀλιγαρχίᾳ τῶν συμφορῶν μετέσχον τὸ μέρος.", "st": "18.25"}, {"sp": "N", "t": "ἀξιῶ δὲ καὶ τούτους τοὺς συνδίκους εὔνους ἡμῖν εἶναι, ἐκείνου τοῦ χρόνου μνησθέντας, ὅτ’ ἐκ τῆς πατρίδος ἐκπεπτωκότες καὶ τὰς οὐσίας ἀπολωλεκότες ἄνδρας ἀρίστους ἐνομίζετ’ εἶναι τοὺς ὑπὲρ ὑμῶν ἀποθνῄσκοντας, καὶ τοῖς θεοῖς ηὔχεσθε δυνηθῆναι χάριν τοῖς ἐξ ἐκείνων ἀποδοῦναι.", "st": "18.26"}, {"sp": "N", "t": "ἡμεῖς τοίνυν, ὑεῖς ὄντες καὶ συγγενεῖς τῶν ὑπὲρ τῆς ἐλευθερίας προκεκινδυνευκότων, ἀπαιτοῦμεν ὑμᾶς νυνὶ ταύτην τὴν χάριν, καὶ ἀξιοῦμεν μὴ ἀδίκως ἡμᾶς ἀπολέσαι, ἀλλὰ πολὺ μᾶλλον βοηθεῖν τοῖς τῶν αὐτῶν μετασχοῦσι συμφορῶν. ἐγὼ μὲν οὖν καὶ δέομαι καὶ ἀντιβολῶ καὶ ἱκετεύω, καὶ τούτων παρ’ ὑμῶν τυγχάνειν ἀξιῶ· οὐ γὰρ περὶ μικρῶν κινδυνεύομεν, ἀλλὰ περὶ τῶν ὄντων ἁπάντων.", "st": "18.27"}, {"sp": "HDR", "t": "ΙΘʹ. Ὑπὲρ τῶν Ἀριστοφάνους χρημάτων, πρὸς τὸ δημόσιον", "st": "19"}, {"sp": "N", "t": "πολλήν μοι ἀπορίαν παρέχει ὁ ἀγὼν οὑτοσί, ὦ ἄνδρες δικασταί, ὅταν ἐνθυμηθῶ ὅτι, ἐὰν ἐγὼ μὲν μὴ νῦν εὖ εἴπω, οὐ μόνον ἐγὼ ἀλλὰ καὶ ὁ πατὴρ δόξει ἄδικος εἶναι, καὶ τῶν ὄντων ἁπάντων στερήσομαι. ἀνάγκη οὖν, εἰ καὶ μὴ δεινὸς πρὸς ταῦτα πέφυκα, βοηθεῖν τῷ πατρὶ καὶ ἐμαυτῷ οὕτως ὅπως ἂν δύνωμαι.", "st": "19.1"}, {"sp": "N", "t": "τὴν μὲν οὖν παρασκευὴν καὶ ⟨τὴν⟩ προθυμίαν τῶν ἐχθρῶν ὁρᾶτε, καὶ οὐδὲν δεῖ περὶ τούτων λέγειν· τὴν δ’ ἐμὴν ἀπειρίαν πάντες ἴσασιν, ὅσοι ἐμὲ γιγνώσκουσιν. αἰτήσομαι οὖν ὑμᾶς δίκαια καὶ ῥᾴδια χαρίσασθαι, ἄνευ ὀργῆς καὶ ἡμῶν ἀκοῦσαι,", "st": "19.2"}, {"sp": "N", "t": "ὥσπερ ⟨καὶ⟩ τῶν κατηγόρων. ἀνάγκη γὰρ τὸν ἀπολογούμενον, κἂν ἐξ ἴσου ἀκροᾶσθε, ἔλαττον ἔχειν. οἱ μὲν γὰρ ἐκ πολλοῦ χρόνου ἐπιβουλεύοντες, αὐτοὶ ἄνευ κινδύνων ὄντες, τὴν κατηγορίαν ἐποιήσαντο, ἡμεῖς δὲ ἀγωνιζόμεθα μετὰ δέους καὶ διαβολῆς καὶ κινδύνου ⟨τοῦ⟩ μεγίστου. εἰκὸς οὖν ὑμᾶς εὔνοιαν πλείω ἔχειν τοῖς ἀπολογουμένοις.", "st": "19.3"}, {"sp": "N", "t": "οἶμαι γὰρ πάντας ὑμᾶς εἰδέναι ὅτι πολλοὶ ἤδη πολλὰ καὶ δεινὰ κατηγορήσαντες παραχρῆμα ἐξηλέγχθησαν ψευδόμενοι οὕτω φανερῶς, ὥστε ὑπὸ πάντων τῶν παραγενομένων μισηθέντες ἀπελθεῖν· οἱ δ’ αὖ μαρτυρήσαντες τὰ ψευδῆ καὶ ἀδίκως ἀπολέσαντες ἀνθρώπους ἑάλωσαν,", "st": "19.4"}, {"sp": "N", "t": "ἡνίκα οὐδὲν ἦν πλέον τοῖς πεπονθόσιν. ὅτ’ οὖν τοιαῦτα πολλὰ γεγένηται, ὡς ἐγὼ ἀκούω, εἰκὸς ὑμᾶς, ὦ ἄνδρες δικασταί, μήπω τοὺς τῶν κατηγόρων λόγους ἡγεῖσθαι πιστούς, πρὶν ἂν καὶ ἡμεῖς εἴπωμεν. ἀκούω γὰρ ἔγωγε, καὶ ὑμῶν δὲ τοὺς πολλοὺς οἶμαι εἰδέναι, ὅτι πάντων δεινότατόν ἐστι διαβολή.", "st": "19.5"}, {"sp": "N", "t": "μάλιστα δὲ τοῦτο ἔχοι ἄν τις ἰδεῖν, ὅταν πολλοὶ ἐπὶ τῇ αὐτῇ αἰτίᾳ εἰς ἀγῶνα καταστῶσιν. ὡς γὰρ ἐπὶ τὸ πολὺ οἱ τελευταῖοι κρινόμενοι σῴζονται· πεπαυμένοι γὰρ τῆς ὀργῆς αὐτῶν ἀκροᾶσθε, καὶ τοὺς ἐλέγχους ἤδη ἐθέλοντες ἀποδέχεσθε.", "st": "19.6"}, {"sp": "N", "t": "ἐνθυμεῖσθε οὖν ὅτι Νικόφημος καὶ Ἀριστοφάνης ἄκριτοι ἀπέθανον, πρὶν παραγενέσθαι τινὰ αὐτοῖς ἐλεγχομένοις ὡς ἠδίκουν. οὐδεὶς γὰρ οὐδ’ εἶδεν ἐκείνους μετὰ τὴν σύλληψιν· οὐδὲ γὰρ θάψαι τὰ σώματ’ αὐτῶν ἀπέδοσαν, ἀλλ’ οὕτω δεινὴ ⟨ἡ⟩ συμφορὰ γεγένηται ὥστε πρὸς τοῖς ἄλλοις καὶ τούτου ἐστέρηνται.", "st": "19.7"}, {"sp": "N", "t": "ἀλλὰ ταῦτα μὲν ἐάσω· οὐδὲν γὰρ ἂν περαίνοιμι· πολὺ δὲ ἀθλιώτεροι δοκοῦσί μοι οἱ παῖδες οἱ Ἀριστοφάνους· οὐδένα γὰρ οὔτ’ ἰδίᾳ οὔτε δημοσίᾳ ἠδικηκότες οὐ μόνον τὰ πατρῷα ἀπολωλέκασι παρὰ τοὺς νόμους τοὺς ὑμετέρους, ἀλλὰ καὶ ἣ ὑπόλοιπος ἐλπὶς ἦν, ἀπὸ ⟨τῶν⟩ τοῦ πάππου ἐκτραφῆναι, ἐν οὕτω δεινῶ καθέστηκεν. ἔτι δ’ ἡμεῖς ἐστερημένοι μὲν κηδεστῶν,", "st": "19.8"}, {"sp": "N", "t": "ἐστερημένοι δὲ τῆς προικός, παιδάρια δὲ τρία ἠναγκασμένοι τρέφειν, προσέτι συκοφαντούμεθα καὶ κινδυνεύομεν περὶ ὧν οἱ πρόγονοι ἡμῖν κατέλιπον κτησάμενοι ἐκ τοῦ δικαίου. καίτοι, ὦ ἄνδρες δικασταί, ὁ ἐμὸς πατὴρ ἐν ἅπαντι τῷ βίῳ πλείω εἰς τὴν πόλιν ἀνήλωσεν ἢ εἰς αὑτὸν καὶ τοὺς οἰκείους, διπλάσια δὲ ἢ νῦν ἔστιν ἡμῖν, ὡς ἐγὼ λογιζομένῳ αὐτῷ πολλάκις παρεγενόμην.", "st": "19.9"}, {"sp": "N", "t": "μὴ οὖν προκαταγιγνώσκετε ἀδικίαν τοῦ εἰς αὑτὸν μὲν μικρὰ δαπανῶντος, ὑμῖν δὲ πολλὰ καθ’ ἕκαστον τὸν ἐνιαυτόν, ἀλλ’ ὅσοι καὶ τὰ πατρῷα καὶ ἐάν τί ποθεν λάβωσιν, εἰς τὰς αἰσχίστας ἡδονὰς εἰθισμένοι εἰσὶν ἀναλίσκειν.", "st": "19.10"}, {"sp": "N", "t": "χαλεπὸν μὲν οὖν, ὦ ἄνδρες δικασταί, ἀπολογεῖσθαι πρὸς δόξαν ἣν ἔνιοι ἔχουσι περὶ τῆς Νικοφήμου οὐσίας, καὶ σπάνιν ἀργυρίου ἣ νῦν ἐστιν ἐν τῇ πόλει, καὶ τοῦ ἀγῶνος πρὸς τὸ δημόσιον ὄντος· ὅμως δὲ καὶ τούτων ὑπαρχόντων ῥᾳδίως γνώσεσθε ὅτι οὐκ ἀληθῆ ἐστι τὰ κατηγορημένα. δέομαι δ’ ὑμῶν πάσῃ τέχνῃ καὶ μηχανῇ μετ’ εὐνοίας ἀκροασαμένους ἡμῶν διὰ τέλους ὅ τι ἂν ὑμῖν ἄριστον καὶ εὐορκότατον νομίζητε εἶναι, τοῦτο ψηφίσασθαι.", "st": "19.11"}, {"sp": "N", "t": "πρῶτον μὲν οὖν, ᾧ τρόπῳ κηδεσταὶ ἡμῖν ἐγένοντο, διδάξω ὑμᾶς. στρατηγῶν γὰρ Κόνων περὶ Πελοπόννησον, τριηραρχήσαντι τῷ ἐμῷ πατρὶ πάλαι φίλος γεγενημένος, ἐδεήθη δοῦναι τὴν ⟨ἐμὴν⟩ ἀδελφὴν αἰτοῦντι τῷ ὑεῖ τῷ Νικοφήμου.", "st": "19.12"}, {"sp": "N", "t": "ὁ δὲ ὁρῶν αὐτοὺς ὑπ’ ἐκείνου τε πεπιστευμένους γεγονότας τε ἐπιεικεῖς τῇ ⟨τε⟩ πόλει ἔν γε τῷ τότε χρόνῳ ἀρέσκοντας, ἐπείσθη δοῦναι, οὐκ εἰδὼς τὴν ἐσομένην διαβολήν, ἀλλ’ ὅτε καὶ ὑμῶν ὁστισοῦν ἂν ἐκείνοις ἠξίωσε κηδεστὴς γενέσθαι, ἐπεὶ ὅτι γε οὐ χρημάτων ἕνεκα, ῥᾴδιον γνῶναι ἐκ τοῦ βίου παντὸς καὶ τῶν ἔργων τῶν τοῦ πατρός.", "st": "19.13"}, {"sp": "N", "t": "ἐκεῖνος γὰρ ὅτ’ ἦν ἐν τῇ ἡλικίᾳ, παρὸν μετὰ πολλῶν χρημάτων γῆμαι ἄλλην, τὴν ἐμὴν μητέρα ἔλαβεν οὐδὲν ἐπιφερομένην, ὅτι δὲ Ξενοφῶντος ἦν θυγάτηρ τοῦ Εὐριπίδου ὑέος, ὃς οὐ μόνον ἰδίᾳ χρηστὸς ἐδόκει εἶναι, ἀλλὰ καὶ στρατηγεῖν αὐτὸν ἠξιώσατε, ὡς ἐγὼ ἀκούω.", "st": "19.14"}, {"sp": "N", "t": "τὰς τοίνυν ἐμὰς ἀδελφὰς ἐθελόντων τινῶν λαβεῖν ἀπροίκους πάνυ πλουσίων οὐκ ἔδωκεν, ὅτι ἐδόκουν κάκιον γεγονέναι, ἀλλὰ τὴν μὲν Φιλομήλῳ τῷ Παιανιεῖ, ὃν οἱ πολλοὶ βελτίω ἡγοῦνται εἶναι ἢ πλουσιώτερον, τὴν δὲ πένητι γεγενημένῳ οὐ διὰ κακίαν, ἀδελφιδῷ δὲ ὄντι Φαίδρῳ ⟨τῷ⟩ Μυρρινουσίῳ, ἐπιδοὺς τετταράκοντα μνᾶς,", "st": "19.15"}, {"sp": "N", "t": "κᾆτ’ Ἀριστοφάνει τὸ ἴσον. πρὸς δὲ τούτοις ἐμοὶ πολλὴν ἐξὸν πάνυ προῖκα λαβεῖν ἐλάττω συνεβούλευσεν, ὥστε εὖ εἰδέναι ὅτι κηδεσταῖς χρησοίμην κοσμίοις καὶ σώφροσι. καὶ νῦν ἔχω γυναῖκα τὴν Κριτοδήμου θυγατέρα τοῦ Ἀλωπεκῆθεν, ὃς ὑπὸ Λακεδαιμονίων ἀπέθανεν, ὅτε ἡ ναυμαχία ἐγένετο ἐν Ἑλλησπόντῳ.", "st": "19.16"}, {"sp": "N", "t": "καίτοι, ὦ ἄνδρες δικασταί, ὅστις αὐτός τε ἄνευ χρημάτων ἔγημε τοῖν τε θυγατέροιν πολὺ ἀργύριον ἐπέδωκε τῷ τε ὑεῖ ὀλίγην προῖκα ἔλαβε, πῶς οὐκ εἰκὸς περὶ τούτου πιστεύειν ὡς οὐχ ἕνεκα χρημάτων τούτοις κηδεστὴς ἐγένετο;", "st": "19.17"}, {"sp": "N", "t": "ἀλλὰ μὴν ὅ γε Ἀριστοφάνης ἤδη ἔχων τὴν γυναῖκα ὅτι πολλοῖς ἂν μᾶλλον ἐχρῆτο ἢ τῷ ἐμῷ πατρί, ῥᾴδιον γνῶναι. ἥ τε γὰρ ἡλικία πολὺ διάφορος, ἥ τε φύσις ἔτι πλέον· ἐκείνου μὲν γὰρ ἦν τὰ ἑαυτοῦ πράττειν, Ἀριστοφάνης δὲ οὐ μόνον τῶν ἰδίων ἀλλὰ καὶ τῶν κοινῶν ἐβούλετο ἐπιμελεῖσθαι, καὶ εἴ τι ἦν αὐτῷ ἀργύριον, ἀνήλωσεν ἐπιθυμῶν τιμᾶσθαι.", "st": "19.18"}, {"sp": "N", "t": "γνώσεσθε δὲ ὅτι ἀληθῆ λέγω ἐξ αὐτῶν ὧν ἐκεῖνος ἔπραττε. πρῶτον μὲν γὰρ βουλομένου Κόνωνος πέμπειν τινὰ εἰς Σικελίαν, ᾤχετο ὑποστὰς μετὰ Εὐνόμου, Διονυσίου φίλου ὄντος καὶ ξένου, τὸ πλῆθος τὸ ὑμέτερον πλεῖστα ἀγαθὰ πεποιηκότος, ὡς ἐγὼ ἀκήκοα τῶν ἐν Πειραιεῖ παραγενομένων.", "st": "19.19"}, {"sp": "N", "t": "ἦσαν δ’ ἐλπίδες τοῦ πλοῦ πεῖσαι Διονύσιον κηδεστὴν μὲν γενέσθαι Εὐαγόρᾳ, πολέμιον δὲ Λακεδαιμονίοις, φίλον δὲ καὶ σύμμαχον τῇ πόλει τῇ ὑμετέρᾳ. καὶ ταῦτ’ ἔπραττον πολλῶν κινδύνων ὑπαρχόντων πρὸς τὴν θάλατταν καὶ τοὺς πολεμίους, καὶ ἔπεισαν Διονύσιον μὴ πέμψαι τριήρεις ἃς τότε παρεσκευάσατο Λακεδαιμονίοις.", "st": "19.20"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἐπειδὴ οἱ πρέσβεις ἧκον ἐκ Κύπρου ἐπὶ τὴν βοήθειαν, οὐδὲν ἐνέλιπε προθυμίας σπεύδων. ὑμεῖς δὲ ⟨δέκα⟩ τριήρεις αὐτοῖς ἔδοτε καὶ τἆλλα ἐψηφίσασθε, ἀργυρίου δ’ εἰς τὸν ἀπόστολον ἠπόρουν. ὀλίγα μὲν γὰρ ἦλθον ἔχοντες χρήματα, πολλῶν δὲ προσεδεήθησαν· οὐ γὰρ μόνον εἰς τὰς ναῦς, ἀλλὰ καὶ πελταστὰς ἐμισθώσαντο καὶ ὅπλα ἐπρίαντο.", "st": "19.21"}, {"sp": "N", "t": "Ἀριστοφάνης [δ’] οὖν τῶν χρημάτων τὰ μὲν πλεῖστα αὐτὸς παρέσχεν· ἐπειδὴ δὲ οὐχ ἱκανὰ ἦν, τοὺς φίλους ἔπειθε δεόμενος καὶ ἐγγυώμενος, καὶ τοῦ ἀδελφοῦ τοῦ ὁμοπατρίου ἀποκειμένας παρ’ αὐτῷ τετταράκοντα μνᾶς λαβὼν κατεχρήσατο. τῇ δὲ προτεραίᾳ ᾗ ἀνήγετο, εἰσελθὼν ὡς τὸν πατέρα τὸν ἐμὸν ἐκέλευσε χρῆσαι ὅ τι εἴη ἀργύριον. προσδεῖν γὰρ ἔφη πρὸς τὸν μισθὸν τοῖς πελτασταῖς. ἦσαν δ’ ἡμῖν ἔνδον ἑπτὰ μναῖ· ὁ δὲ καὶ ταύτας λαβὼν κατεχρήσατο.", "st": "19.22"}, {"sp": "N", "t": "τίνα γὰρ οἴεσθε, ὦ ἄνδρες δικασταί, φιλότιμον μὲν ὄντα, ἐπιστολῶν δ’ αὐτῷ ἡκουσῶν παρὰ τοῦ πατρὸς μηδενὸς ἀπορήσειν ἐν Κύπρῳ, ᾑρημένον δὲ πρεσβευτὴν καὶ μέλλοντα πλεῖν ὡς Εὐαγόραν, ὑπολιπέσθαι ἄν τι τῶν ὄντων, ἀλλ’ οὐχ ἃ ἦν δυνατὸς πάντα παρασχόντα χαρίσασθαι ἐκείνῳ τε καὶ κομίσασθαι μὴ ἐλάττω; ὡς τοίνυν ταῦτ’ ἐστὶν ἀληθῆ, κάλει μοι Εὔνομον.", "st": "19.23"}, {"sp": "N", "t": "<em>Μαρτυρία<\/em>", "st": "19.23"}, {"sp": "N", "t": "⟨κάλει μοι καὶ τοὺς ἄλλους μάρτυρας.⟩", "st": "19.23"}, {"sp": "N", "t": "<em>⟨Μάρτυρες⟩<\/em>", "st": "19.24"}, {"sp": "N", "t": "τῶν μὲν μαρτύρων ἀκούετε, οὐ μόνον ὅτι ἔχρησαν τὸ ⟨ἀργύριον⟩ ἐκείνου δεηθέντος, ἀλλὰ καὶ ὅτι ἀπειλήφασιν· ἐκομίσθη γὰρ αὐτοῖς ἐπὶ τῆς τριήρους.", "st": "19.24"}, {"sp": "N", "t": "ῥᾴδιον μὲν οὖν ἐκ τῶν εἰρημένων γνῶναι ὅτι τοιούτων καιρῶν συμπεσόντων οὐδενὸς ἂν ἐφείσατο τῶν ἑαυτοῦ·", "st": "19.24"}, {"sp": "N", "t": "ὃ δὲ μέγιστον τεκμήριον· δῆμος γὰρ ὁ Πυριλάμπους, τριηραρχῶν εἰς Κύπρον, ἐδεήθη μου προσελθεῖν αὐτῷ, λέγων ὅτι ἔλαβε ⟨μὲν⟩ σύμβολον παρὰ βασιλέως τοῦ μεγάλου φιάλην χρυσῆν, δώσει δ’ Ἀριστοφάνει, λαβὼν ἑκκαίδεκα μνᾶς ἐπ’ αὐτῇ, ἵν’ ἔχοι ἀναλίσκειν εἰς τὴν τριηραρχίαν· ἐπειδὴ δὲ εἰς Κύπρον ἀφίκοιτο, λύσεσθαι ἀποδοὺς εἴκοσι μνᾶς· πολλῶν γὰρ ἀγαθῶν καὶ ἄλλων χρημάτων εὐπορήσειν διὰ τὸ σύμβολον ἐν πάσῃ τῇ ἠπείρῳ.", "st": "19.25"}, {"sp": "N", "t": "Ἀριστοφάνης τοίνυν ἀκούων μὲν ταῦτα Δήμου, δεομένου δ’ ἐμοῦ, μέλλων δ’ ἄξειν ⟨τὸ⟩ χρυσίον, τέτταρας δὲ μνᾶς τόκον λήψεσθαι, οὐκ ἔφη εἶναι, ἀλλ’ ὤμνυε καὶ προσδεδανεῖσθαι τοῖς ξένοις ἄλλοθεν, ἐπειδὴ ἥδιστ’ ⟨ἂν⟩ ἀνθρώπων ἄγειν τε εὐθὺς ἐκεῖνο τὸ σύμβολον καὶ χαρίσασθαι ἡμῖν ἃ ἐδεόμεθα.", "st": "19.26"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "19.27"}, {"sp": "N", "t": "ὡς δὲ ταῦτ’ ἐστὶν ἀληθῆ, μάρτυρας ὑμῖν παρέξομαι.", "st": "19.27"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὐ κατέλιπεν Ἀριστοφάνης ἀργύριον οὐδὲ χρυσίον, ῥᾴδιον γνῶναι ἐκ τῶν εἰρημένων καὶ μεμαρτυρημένων· χαλκώματα δὲ σύμμεικτα οὐ πολλὰ ἐκέκτητο, ἀλλὰ καὶ ὅθ’ εἱστία τοὺς παρ’ Εὐαγόρου πρεσβεύοντας, αἰτησάμενος ἐχρήσατο. ἃ δὲ κατέλιπεν, ἀναγνώσεται ὑμῖν.", "st": "19.27"}, {"sp": "N", "t": "<em>Ἀπογραφὴ Χαλκωμάτων<\/em>", "st": "19.28"}, {"sp": "N", "t": "ἴσως ἐνίοις ὑμῶν, ὦ ἄνδρες δικασταί, δοκεῖ ὀλίγα εἶναι· ἀλλ’ ἐκεῖνο ἐνθυμεῖσθε, ὅτι ⟨αὐτῷ⟩ [πρὶν Νικοφήμῳ ἢ καὶ Ἀριστοφάνει] πρὶν τὴν ναυμαχίαν νικῆσαι ⟨Κόνωνα⟩ γῆ μὲν οὐκ ἦν ἀλλ’ ἢ χωρίδιον μικρὸν Ῥαμνοῦντι. ἐγένετο δ’ ⟨ἡ⟩ ναυμαχία ἐπ’ Εὐβουλίδου ἄρχοντος.", "st": "19.28"}, {"sp": "N", "t": "ἐν οὖν τέτταρσιν ἢ πέντε ἔτεσι, πρότερον μὴ ὑπαρχούσης οὐσίας, χαλεπόν, ὦ ἄνδρες δικασταί, τραγῳδοῖς τε δὶς χορηγῆσαι, ὑπὲρ τε καὶ τοῦ πατρός, καὶ τρία ἔτη συνεχῶς τριηραρχῆσαι, εἰσφοράς τε πολλάς εἰσενηνοχέναι, οἰκίαν τε πεντήκοντα μνῶν πρίασθαι, γῆς τε πλέον ἢ τριακόσια πλέθρα κτήσασθαι· ἔτι δὲ πρὸς τούτοις οἴεσθε χρῆναι ἔπιπλα πολλὰ καταλελοιπέναι;", "st": "19.29"}, {"sp": "N", "t": "ἀλλ’ οὐδ’ οἱ πάλαι πλούσιοι δοκοῦντες εἶναι ἄξια λόγου ἔχοιεν ἂν ἐξενεγκεῖν· ἐνίοτε γὰρ οὐκ ἔστιν, οὐδ’ ἐάν τις πάνυ ἐπιθυμῇ, πρίασθαι τοιαῦτα ⟨ἃ⟩ κτησαμένῳ εἰς τὸν λοιπὸν χρόνον ἡδονὴν ἂν παρέχοι.", "st": "19.30"}, {"sp": "N", "t": "ἀλλὰ τόδε σκοπεῖτε· τῶν ἄλλων, ὅσων ἐδημεύσατε ⟨τὰ⟩ χρήματα, οὐχ ὅπως σκεύη ἀπέδοσθε, ἀλλὰ καὶ αἱ θύραι ἀπὸ τῶν οἰκημάτων ἀφηρπάσθησαν· ἡμεῖς δὲ ἤδη δεδημευμένων καὶ ἐξεληλυθυίας τῆς ἐμῆς ἀδελφῆς φύλακα κατεστήσαμεν ⟨ἐν⟩ τῇ ἐρήμῃ οἰκίᾳ, ἵνα μήτε θυρώματα μήτε ἀγγεῖα μήτε ἄλλο μηδὲν ἀπόλοιτο. ἔπιπλα δὲ ἀπεφαίνετο πλεῖν ἢ χιλίων δραχμῶν,", "st": "19.31"}, {"sp": "N", "t": "ὅσα οὐδενὸς πώποτ’ ἐλάβετε. πρὸς δὲ τούτοις καὶ πρότερον πρὸς τοὺς συνδίκους καὶ νῦν ἐθέλομεν πίστιν δοῦναι, ἥτις ἐστὶ μεγίστη τοῖς ἀνθρώποις, μηδὲν ἔχειν τῶν Ἀριστοφάνους χρημάτων, ἐνοφείλεσθαι δὲ τὴν προῖκα τῆς ἀδελφῆς καὶ ἑπτὰ μνᾶς ἃς ᾤχετο λαβὼν παρὰ τοῦ πατρὸς τοῦ ἐμοῦ.", "st": "19.32"}, {"sp": "N", "t": "πῶς ἂν οὖν εἶεν ἄνθρωποι ἀθλιώτεροι, ἢ εἰ τὰ σφέτερ’ αὐτῶν ἀπολωλεκότες δοκοῖεν τἀκείνων ἔχειν; ὅ δὲ πάντων δεινότατον, τὴν ἀδελφὴν ὑποδέξασθαι παιδία ἔχουσαν πολλά, καὶ ταῦτα τρέφειν, μηδ’ αὐτοὺς ἔχοντας μηδέν, ἐὰν ὑμεῖς τὰ ὄντ’ ἀφέλησθε.", "st": "19.33"}, {"sp": "N", "t": "φέρε πρὸς θεῶν Ὀλυμπίων· οὕτω γὰρ σκοπεῖτε, ὦ ⟨ἄνδρες⟩ δικασταί. εἴ τις ὑμῶν ἔτυχε δοὺς Τιμοθέῳ τῷ Κόνωνος τὴν θυγατέρα ἢ τὴν ἀδελφήν, καὶ ἐκείνου ἀποδημήσαντος καὶ ἐν διαβολῇ γενομένου ἐδημεύθη ἡ οὐσία, καὶ μὴ ἐγένετο τῇ πόλει πραθέντων ἁπάντων τέτταρα τάλαντα ἀργυρίου, διὰ τοῦτο ἠξιοῦτε ἂν τοὺς ἐκείνου καὶ τοὺς προσήκοντας ἀπολέσθαι, ὅτι οὐδὲ πολλοστὸν μέρος τῆς δόξης τῆς παρ’ ὑμῖν ἐφάνη τὰ χρήματα;", "st": "19.34"}, {"sp": "N", "t": "ἀλλὰ μὴν τοῦτο πάντες ἐπίστασθε Κόνωνα μὲν ἄρχοντα, Νικόφημον δὲ ποιοῦντα ὅ τι ἐκεῖνος προστάττοι. τῶν οὖν ὠφελειῶν Κόνωνα εἰκὸς πολλοστὸν μέρος ἄλλῳ τινὶ μεταδιδόναι, ὥστ’ εἰ οἴονται πολλὰ γενέσθαι Νικοφήμῳ, ὁμολογήσειαν ⟨ἂν⟩ τὰ Κόνωνος εἶναι πλεῖν ἢ δεκαπλάσια.", "st": "19.35"}, {"sp": "N", "t": "ἔτι δὲ φαίνονται οὐδὲν πώποτε διενεχθέντες, ὥστ’ εἰκὸς καὶ περὶ τῶν χρημάτων ταὐτὰ γνῶναι, ἱκανὰ μὲν ἐνθάδε τῷ ὑεῖ ἑκάτερον καταλιπεῖν, τὰ δὲ ἄλλα παρ’ αὑτοῖς ἔχειν· ἦν γὰρ Κόνωνι μὲν ὑὸς ἐν Κύπρῳ καὶ γυνή, Νικοφήμῳ δὲ γυνὴ καὶ θυγάτηρ, ἡγοῦντο δὲ καὶ τὰ ἐκεῖ ὁμοίως σφίσιν εἶναι σᾶ ὥσπερ καὶ τὰ ἐνθάδε.", "st": "19.36"}, {"sp": "N", "t": "πρὸς δὲ τούτοις ἐνθυμεῖσθε ὅτι καὶ εἴ τις μὴ κτησάμενος ἀλλὰ παρὰ τοῦ πατρὸς παραλαβὼν τοῖς παισὶ διένειμεν, οὐκ ἐλάχιστα ἂν αὑτῷ ὑπέλιπε· βούλονται γὰρ πάντες ὑπὸ τῶν παίδων θεραπεύεσθαι ἔχοντες χρήματα μᾶλλον ἢ ἐκείνων δεῖσθαι ἀποροῦντες.", "st": "19.37"}, {"sp": "N", "t": "νῦν τοίνυν εἰ δημεύσαιτε τὰ τοῦ Τιμοθέου, —— ὃ μὴ γένοιτο, εἰ μή τι μέλλει μέγα ἀγαθὸν ἔσεσθαι τῇ πόλει, —— ἐλάττω δὲ ἐξ αὐτῶν λάβοιτ’ ἢ ἃ ἐκ τῶν Ἀριστοφάνους γεγένηται, τούτου ἕνεκα ἠξιοῦτε ἂν τοὺς ἀναγκαίους τοὺς ἐκείνου τὰ σφέτερ’ αὐτῶν ἀπολέσαι; ἀλλ’ οὐκ εἰκός, ὦ ἄνδρες δικασταί· ὁ γὰρ Κόνωνος θάνατος καὶ αἱ διαθῆκαι,", "st": "19.38"}, {"sp": "N", "t": "ἃς διέθετο ἐν Κύπρῳ, σαφῶς ἐδήλωσαν ὅτι πολλοστὸν μέρος ἦν τὰ χρήματα ὧν ὑμεῖς προσεδοκᾶτε· τῇ μὲν γὰρ Ἀθηναίᾳ καθιέρωσεν εἰς ἀναθήματα καὶ τῷ Ἀπόλλωνι εἰς Δελφοὺς πεντακισχιλίους στατῆρας· τῷ δὲ ἀδελφιδῷ τῷ ἑαυτοῦ,", "st": "19.39"}, {"sp": "N", "t": "ὃς ἐφύλαττεν αὐτῷ καὶ ἐταμίευε πάντα τὰ ἐν Κύπρῳ, ἔδωκεν ὡς μυρίας δραχμάς, τῷ δὲ ἀδελφῷ τρία τάλαντα· τὰ δὲ λοιπὰ τῷ ὑεῖ κατέλιπε, τάλαντα ἑπτακαίδεκα. τούτων δὲ κεφάλαιόν τι γίγνεται περὶ τετταράκοντα τάλαντα.", "st": "19.40"}, {"sp": "N", "t": "καὶ οὐδενὶ οἷόν τε εἰπεῖν ὅτι διηρπάσθη ἢ ὡς οὐ δικαίως ἀπεφάνθη· αὐτὸς γὰρ ἐν τῇ νόσῳ ὢν εὖ φρονῶν διέθετο. καί μοι κάλει τούτων μάρτυρας.", "st": "19.41"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "19.42"}, {"sp": "N", "t": "ἀλλὰ μὴν ὁστισοῦν, ὦ ἄνδρες δικασταί, πρὶν ἀμφότερα δῆλα γενέσθαι, πολλοστὸν μέρος τὰ Νικοφήμου τῶν Κόνωνος χρημάτων ᾠήθη ἂν εἶναι. Ἀριστοφάνης τοίνυν γῆν μὲν καὶ οἰκίαν ἐκτήσατο πλεῖν ἢ πέντε ταλάντων, κατεχορήγησε δὲ ὑπὲρ αὑτοῦ καὶ τοῦ πατρὸς πεντακισχιλίας δραχμάς, τριηραρχῶν δὲ ἀνήλωσεν ὀγδοήκοντα μνᾶς.", "st": "19.42"}, {"sp": "N", "t": "εἰσενήνεκται δὲ ὑπὲρ ἀμφοτέρων οὐκ ἔλαττον μνῶν τετταράκοντα. εἰς δὲ τὸν ἐπὶ Σικελίας πλοῦν ἀνήλωσεν ἑκατὸν μνᾶς. εἰς δὲ τὸν ἀπόστολον τῶν τριήρων, ὅτε οἱ Κύπριοι ἦλθον καὶ ἔδοτε αὐτοῖς τὰς δέκα ναῦς, καὶ τῶν πελταστῶν τὴν μίσθωσιν καὶ τῶν ὅπλων τὴν ὠνὴν παρέσχε τρισμυρίας δραχμάς. καὶ τούτων κεφάλαιον πάντων γίγνεται μικροῦ λείποντος πεντεκαίδεκα τάλαντα.", "st": "19.43"}, {"sp": "N", "t": "ὥστε οὐκ ἂν εἰκότως ἡμᾶς αἰτιῷσθε, ἐπεὶ τῶν Κόνωνος, τῶν ὁμολογουμένων δικαίως ἀποφανθῆναι ὑπ’ αὐτοῦ ἐκείνου, πολλαπλασίων δοκούντων πλεῖν ἢ τρίτον μέρος φαίνεται τὰ Ἀριστοφάνους. καὶ οὐ προσλογιζόμεθα ὅσα αὐτὸς ἐν Κύπρῳ ἔσχε Νικόφημος, οὔσης αὐτῷ ἐκεῖ γυναικὸς καὶ θυγατρός.", "st": "19.44"}, {"sp": "N", "t": "ἐγὼ μὲν ⟨οὖν⟩ οὐκ ἀξιῶ, ὦ ἄνδρες δικασταί, οὕτω πολλὰ καὶ μεγάλα τεκμήρια παρασχομένους ἡμᾶς ἀπολέσθαι ἀδίκως. ἀκήκοα γὰρ ἔγωγε καὶ τοῦ πατρὸς καὶ ἄλλων πρεσβυτέρων, ὅτι οὐ νῦν μόνον ἀλλὰ καὶ ἐν τῷ ἔμπροσθεν χρόνῳ πολλῶν ἐψεύσθητε τῆς οὐσίας, οἳ ζῶντες μὲν πλουτεῖν ἐδόκουν, ἀποθανόντες δὲ πολὺ παρὰ τὴν δόξαν τὴν ὑμετέραν ἐφάνησαν.", "st": "19.45"}, {"sp": "N", "t": "αὐτίκα Ἰσχομάχῳ, ἕως ἔζη, πάντες ᾤοντο εἶναι πλεῖν ἢ ἑβδομήκοντα τάλαντα, ὡς ἐγὼ ἀκούω. ἐνειμάσθην δὲ τὼ ὑεῖ οὐδὲ δέκα τάλαντα ἑκάτερος ἀποθανόντος. στεφάνῳ δὲ τῷ Θάλλου ἐλέγετο εἶναι πλεῖν ἢ πεντήκοντα τάλαντα, ἀποθανόντος δ’ ἡ οὐσία ἐφάνη περὶ ἕνδεκα τάλαντα.", "st": "19.46"}, {"sp": "N", "t": "ὁ τοίνυν Νικίου οἶκος προσεδοκᾶτο εἶναι οὐκ ἔλαττον ἢ ἑκατὸν ταλάντων, καὶ τούτων τὰ πολλὰ ἔνδον [ἦν]. Νικήρατος δὲ ὅτ’ ἀπέθνῃσκεν, ἀργύριον μὲν ἢ χρυσίον οὐδ’ αὐτὸς ἔφη καταλείπειν οὐδέν, ἀλλὰ τὴν οὐσίαν ἣν κατέλιπε τῷ ὑεῖ, οὐ πλείονος ἀξία ἐστὶν ἢ τεττάρων καὶ δέκα ταλάντων.", "st": "19.47"}, {"sp": "N", "t": "Καλλίας τοίνυν ὁ Ἱππονίκου, ὅτε νεωστὶ ἐτεθνήκει ὁ πατήρ, [ὃς] πλεῖστα τῶν Ἑλλήνων ἐδόκει κεκτῆσθαι, καὶ ὥς φασι, διακοσίων ταλάντων ἐτιμήσατο ⟨τὰ⟩ αὑτοῦ ὁ πάππος, τὸ δὲ τούτου νῦν τίμημα οὐδὲ δυοῖν ταλάντοιν ἐστί. Κλεοφῶντα δὲ πάντες ἴστε, ὅτε, ὅτι πολλὰ ἔτη διεχείρισε τὰ τῆς πόλεως πάντα καὶ προσεδοκᾶτο πάνυ πολλὰ ἐκ τῆς ἀρχῆς ἔχειν· ἀποθανόντος δ’ αὐτοῦ οὐδαμοῦ δῆλα τὰ χρήματα, ἀλλὰ καὶ οἱ προσήκοντες καὶ οἱ κηδεσταί,", "st": "19.48"}, {"sp": "N", "t": "παρ’ οἷς ⟨ἂν⟩ κατέλιπεν, ὁμολογουμένως πένητές εἰσι. φαινόμεθα δὴ καὶ τῶν ἀρχαιοπλούτων πολὺ ἐψευσμένοι καὶ τῶν νεωστὶ ἐν δόξῃ γεγενημένων. αἴτιον δέ μοι δοκεῖ εἶναι, ὅτι ῥαδίως τινὲς τολμῶσι λέγειν ὡς ὁ δεῖνα ἔχει τάλαντα πολλὰ ἐκ τῆς ἀρχῆς. καὶ ὅσα μὲν περὶ τεθνεώτων λέγουσιν, οὐ πάνυ θαυμάζω (οὐ γὰρ ὑπό γε ἐκείνων ἐξελεγχθεῖεν ἄν), ἀλλ’ ὅσα ζώντων ἐπιχειροῦσι καταψεύδεσθαι. αὐτοὶ γὰρ ἔναγχος ἠκούετε ἐν τῇ ἐκκλησίᾳ,", "st": "19.49"}, {"sp": "N", "t": "ὡς Διότιμος ἔχοι τάλαντα τετταράκοντα πλείω ἢ ὅσα αὐτὸς ὡμολόγει παρὰ τῶν ναυκλήρων καὶ ἐμπόρων· καὶ ταῦτα, ἐπειδὴ ἦλθεν, ἐκείνου ἀπογράφοντος καὶ χαλεπῶς φέροντος ὅτι ἀπὼν διεβάλλετο, οὐδεὶς ἐξήλεγξε, δεομένης μὲν τῆς πόλεως χρημάτων,", "st": "19.50"}, {"sp": "N", "t": "ἐθέλοντος δὲ ἐκείνου λογίσασθαι. ἐνθυμεῖσθε τοίνυν οἷον ἂν ἐγένετο, εἰ Ἀθηναίων ἁπάντων ἀκηκοότων ὅτι τετταράκοντα τάλαντα ἔχοι Διότιμος, εἶτα ἔπαθέ τι πρὶν καταπλεῦσαι δεῦρο. εἶτα οἱ προσήκοντες ἂν αὐτοῦ ἐν κινδύνῳ ἦσαν τῷ μεγίστῳ, εἰ ἔδει αὐτοὺς πρὸς τοσαύτην διαβολὴν ἀπολογεῖσθαι, μὴ εἰδότας μηδὲν τῶν πεπραγμένων. αἴτιοι οὖν εἰσι καὶ ὑμῖν πολλῶν ἤδη ψευσθῆναι καὶ δὴ ἀδίκως γέ τινας ἀπολέσθαι οἱ ῥαδίως τολμῶντες ψεύδεσθαι καὶ συκοφαντεῖν ἀνθρώπους ἐπιθυμοῦντες.", "st": "19.51"}, {"sp": "N", "t": "ἐπεὶ οἴομαι ὑμᾶς εἰδέναι ὅτι Ἀλκιβιάδης τέτταρα ἢ πέντε ἔτη ἐφεξῆς ἐστρατήγει ἐπικρατῶν καὶ νενικηκὼς Λακεδαιμονίους, καὶ διπλάσια ἐκείνῳ ἠξίουν αἱ πόλεις διδόναι ἢ ἄλλῳ τινὶ τῶν στρατηγῶν, ὥστ’ ᾤοντο εἶναί τινες αὐτῷ πλεῖν ἢ ἑκατὸν τάλαντα. ὁ δ’ ἀποθανὼν ἐδήλωσεν ὅτι οὐκ ἀληθῆ ταῦτα ἦν· ἐλάττω γὰρ οὐσίαν κατέλιπε τοῖς παισὶν ἢ αὐτὸς παρὰ τῶν ἐπιτροπευσάντων παρέλαβεν.", "st": "19.52"}, {"sp": "N", "t": "ὅτι μὲν οὖν καὶ ἐν τῷ ἔμπροσθεν χρόνῳ τοιαῦτα ἐγίγνετο, ῥᾴδιον γνῶναι· φασὶ δὲ καὶ τοὺς ἀρίστους καὶ σοφωτάτους μάλιστα ἐθέλειν μεταγιγνώσκειν. εἰ οὖν δοκοῦμεν εἰκότα λέγειν καὶ ἱκανὰ τεκμήρια παρέχεσθαι, ὦ ἄνδρες δικασταί, πάσῃ τέχνῃ καὶ μηχανῇ ἐλεήσατε· ὡς ἡμεῖς τῆς μὲν διαβολῆς οὕτω μεγάλης οὔσης ἀεὶ προσεδοκῶμεν κρατήσειν μετὰ τοῦ ἀληθοῦς· ὑμῶν δὲ μηδενὶ τρόπῳ ἐθελησάντων πεισθῆναι οὐδ’ ἐλπὶς οὐδεμία σωτηρίας ἐδόκει ἡμῖν εἶναι.", "st": "19.53"}, {"sp": "N", "t": "ἀλλὰ πρὸς θεῶν Ὀλυμπίων, ὦ ἄνδρες δικασταί, βούλεσθε ἡμᾶς δικαίως σῶσαι μᾶλλον ἢ ἀδίκως ἀπολέσαι, καὶ πιστεύετε τούτοις ἀληθῆ λέγειν, οἳ ἂν καὶ σιωπῶντες ἐν ἅπαντι τῷ βίῳ παρέχωσι σώφρονας σφᾶς αὐτοὺς καὶ δικαίους.", "st": "19.54"}, {"sp": "N", "t": "περὶ μὲν οὖν αὐτῆς τῆς γραφῆς, καὶ ᾧ τρόπῳ κηδεσταὶ ἡμῖν ἐγένοντο, καὶ ὅτι οὐκ ἐξήρκει τὰ ἐκείνου εἰς τὸν ἔκπλουν, ἀλλὰ καὶ ὡς ἄλλοθεν προσεδανείσατο ἀκηκόατε καὶ μεμαρτύρηται ὑμῖν· περὶ δ’ ἐμαυτοῦ βραχέα βούλομαι ὑμῖν εἰπεῖν. ἐγὼ γὰρ ἔτη γεγονὼς ἤδη τριάκοντα οὔτε τῷ πατρὶ οὐδὲν πώποτε ἀντεῖπον, οὔτε τῶν πολιτῶν οὐδείς μοι ἐνεκάλεσεν, ἐγγύς τε οἰκῶν τῆς ἀγορᾶς οὔτε πρὸς δικαστηρίῳ οὔτε πρὸς βουλευτηρίῳ ὤφθην οὐδεπώποτε, πρὶν ταύτην τὴν συμφορὰν γενέσθαι. περὶ μὲν οὖν ἐμαυτοῦ τοσαῦτα λέγω,", "st": "19.55"}, {"sp": "N", "t": "περὶ δὲ τοῦ πατρός, ἐπειδὴ ὥσπερ ἀδικοῦντος αἱ κατηγορίαι γεγένηνται, συγγνώμην ἔχετε, ἐὰν λέγω ἃ ἀνήλωσεν εἰς τὴν πόλιν καὶ εἰς τοὺς φίλους· οὐ γὰρ φιλοτιμίας ἕνεκα ἀλλὰ τεκμήριον ποιούμενος ὅτι οὐ τοῦ αὐτοῦ ἐστιν ἀνδρὸς ἄνευ ἀνάγκης τε πολλὰ ἀναλίσκειν καὶ μετὰ κινδύνου τοῦ μεγίστου ἐπιθυμῆσαι ἔχειν τι τῶν κοινῶν.", "st": "19.56"}, {"sp": "N", "t": "εἰσὶ δέ τινες οἱ προαναλίσκοντες οὐ μόνου τούτου ἕνεκα ἀλλ’ ἵνα ἄρχειν ὑφ’ ὑμῶν ἀξιωθέντες διπλάσια κομίσωνται. ὁ τοίνυν ἐμὸς πατὴρ ἄρχειν μὲν οὐδεπώποτε ἐπεθύμησε, τὰς δὲ χορηγίας ἁπάσας κεχορήγηκε, τετριηράρχηκε δὲ ἑπτάκις, εἰσφορὰς δὲ πολλὰς καὶ μεγάλας εἰσενήνοχεν. ἵνα δὲ εἰδῆτε καὶ ὑμεῖς, καθ’ ἑκάστην ἀναγνώσεται.", "st": "19.57"}, {"sp": "N", "t": "<em>Λειτουργίαι<\/em>", "st": "19.58"}, {"sp": "N", "t": "ἀκούετε, ὦ ἄνδρες δικασταί, τὸ πλῆθος. πεντήκοντα γὰρ ἔτη ἐστὶν ὅσα ὁ πατὴρ καὶ τοῖς χρήμασι καὶ τῷ σώματι τῇ πόλει ἐλῃτούργει. ἐν οὖν τοσούτῳ χρόνῳ δοκοῦντά τι ἐξ ἀρχῆς ἔχειν οὐδεμίαν εἰκὸς δαπάνην πεφευγέναι. ὅμως δὲ καὶ μάρτυρας ὑμῖν παρέξομαι.", "st": "19.58"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "19.59"}, {"sp": "N", "t": "τούτων συμπάντων κεφάλαιόν ἐστιν ἐννέα τάλαντα καὶ δισχίλιαι δραχμαί. ἔτι τοίνυν καὶ ἰδία τισὶ τῶν πολιτῶν ἀποροῦσι συνεξέδωκε θυγατέρας καὶ ἀδελφάς, τοὺς δ’ ἐλύσατο ἐκ τῶν πολεμίων, τοῖς δ’ εἰς ταφὴν παρεῖχεν ἀργύριον. καὶ ταῦτ’ ἐποίει ἡγούμενος εἶναι ἀνδρὸς ἀγαθοῦ ὠφελεῖν τοὺς φίλους, καὶ εἰ μηδεὶς μέλλοι εἴσεσθαι· νῦν δὲ πρέπον ἐστὶ καὶ ὑμᾶς ἀκοῦσαί μου. καί μοι κάλει τὸν καὶ τόν.", "st": "19.59"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "19.60"}, {"sp": "N", "t": "τῶν μὲν οὖν μαρτύρων ἀκηκόατε· ἐνθυμεῖσθε δὲ ὅτι ὀλίγον μὲν [οὖν] χρόνον δύναιτ’ ἄν τις πλάσασθαι τὸν τρόπον τὸν αὑτοῦ, ἐν ἑβδομήκοντα δὲ ἔτεσιν οὐδ’ ἂν εἶς λάθοι πονηρὸς ὤν. τῷ τοίνυν πατρὶ τῷ ἐμῷ ἄλλα μὲν ἄν τις ἔχοι ἐπικαλέσαι ἐτόλμησε πώποτε.", "st": "19.60"}, {"sp": "N", "t": "οὔκουν ἄξιον τοῖς τῶν κατηγόρων λόγοις πιστεῦσαι μᾶλλον ἢ τοῖς ἔργοις, ἃ ἐπράχθη ἐν ἅπαντι τῷ βίῳ, καὶ τῷ χρόνῳ, ὃν ὑμεῖς σαφέστατον ἔλεγχον τοῦ ἀληθοῦς νομίσατε. εἰ γὰρ μὴ ἦν τοιοῦτος, οὐκ ἂν ἐκ πολλῶν ὀλίγα κατέλιπεν, ἐπεὶ εἰ νῦν γε ἐξαπατηθείητε ὑπὸ τούτων καὶ δημεύσαιθ’ ἡμῶν τὴν οὐσίαν, οὐδὲ δύο τάλαντα λάβοιτ’ ἄν. ὥστε οὐ μόνον πρὸς δόξαν ἀλλὰ καὶ εἰς χρημάτων λόγον λυσιτελεῖ μᾶλλον ὑμῖν ἀποψηφίσασθαι· πολὺ γὰρ πλείω ὠφεληθήσεσθ’,", "st": "19.61"}, {"sp": "N", "t": "ἐὰν ἡμεῖς ἔχωμεν. σκοπεῖτε δὲ ἐκ τοῦ παρεληλυθότος χρόνου, ὅσα φαίνεται ἀνηλωμένα εἰς τὴν πόλιν· καὶ νῦν ἀπὸ τῶν ὑπολοίπων τριηραρχῶ μὲν ἐγώ, τριηραρχῶν δὲ ὁ πατὴρ ἀπέθανεν, πειράσομαι δ’, ὥσπερ καὶ ἐκεῖνον ἑώρων, ὀλίγα κατὰ μικρὸν παρασκευάσασθαι εἰς τὰς κοινὰς ὠφελείας· ὥστε τῷ γ’ ἔργῳ πάλαι ⟨τῆς πόλεως⟩ ταῦτ’ ἐστι, καὶ οὔτ’ ἐγὼ ἀφῃρημένος ἀδικεῖσθαι οἰήσομαι, ὑμῖν τε πλείους οὕτως αἱ ὠφέλειαι ἢ εἰ δημεύσαιτε.", "st": "19.62"}, {"sp": "N", "t": "πρὸς δὲ τούτοις ἄξιον ἐνθυμηθῆναι οἵαν φύσιν εἶχεν ὁ πατήρ. ὅσα γὰρ ἔξω τῶν ἀναγκαίων ἐπεθύμησεν ἀναλίσκειν, πάντα φανήσεται τοιαῦτα ὅθεν καὶ τῇ πόλει τιμὴ ἔμελλεν ἔσεσθαι. αὐτίκα ὅτε ἵππευεν, οὐ μόνον ἵππους ἐκτήσατο λαμπροὺς ἀλλὰ καὶ ἀθληταῖς ἐνίκησεν Ἰσθμοῖ καὶ Νεμέᾳ, ὥστε τὴν πόλιν κηρυχθῆναι καὶ αὐτὸν στεφανωθῆναι. δέομαι οὖν ὑμῶν,", "st": "19.63"}, {"sp": "N", "t": "ὦ ἄνδρες δικασταί, καὶ τούτων καὶ τῶν ἄλλων μεμνημένους ἁπάντων τῶν εἰρημένων βοηθεῖν ἡμῖν καὶ μὴ περιιδεῖν ὑπὸ τῶν ἐχθρῶν ἀναιρεθέντας. καὶ ταῦτα ποιοῦντες τά τε δίκαια ψηφιεῖσθε καὶ ὑμῖν αὐτοῖς τὰ συμφέροντα.", "st": "19.64"}, {"sp": "HDR", "t": "Κʹ. Ὑπὲρ Πολυστράτου", "st": "20"}, {"sp": "N", "t": "οὔ μοι δοκεῖ χρῆναι ὀργίζεσθαι ὑμᾶς τῷ ὀνόματι τῷ τῶν τετρακοσίων, ἀλλὰ τοῖς ἔργοις ἐνίων. οἱ μὲν γὰρ ἐπιβουλεύσαντες ἦσαν αὐτῶν, οἱ δ’ ἵνα μήτε τὴν πόλιν μηδὲν κακὸν ἐργάσαιντο μήθ’ ὑμῶν μηδένα, ἀλλ’ εὖνοι ὄντες εἰσῆλθον εἰς τὸ βουλευτήριον, ὧν εἷς ὢν οὑτοσὶ τυγχάνει Πολύστρατος.", "st": "20.1"}, {"sp": "N", "t": "οὗτος γὰρ ᾑρέθη μὲν ὑπὸ τῶν φυλετῶν ὡς χρηστὸς ὢν ἀνὴρ καὶ περὶ τοὺς δημότας καὶ περὶ τὸ πλῆθος τὸ ὑμέτερον· κατηγοροῦσι δὲ αὐτοῦ ὡς οὐκ εὔνους ἦν τῷ πλήθει τῷ ὑμετέρῳ, αἱρεθεὶς ὑπὸ τῶν φυλετῶν, οἳ ἄριστ’ ἂν διαγνοῖεν περὶ σφῶν αὐτῶν ὁποῖοί τινές εἰσιν.", "st": "20.2"}, {"sp": "N", "t": "οὗτος δὲ τίνος ἂν ἕνεκα ὀλιγαρχίας ἐπεθύμησε; πότερον ὡς ἡλικίαν εἶχε λέγων τι διαπράττεσθαι παρ’ ὑμῖν, ἢ τῷ σώματι πιστεύων, ἵνα ὑβρίζοι εἰς τῶν ὑμετέρων τινά; ἀλλ’ ὁρᾶτε αὐτοῦ τὴν ἡλικίαν, ᾗ καὶ τοὺς ἄλλους ἱκανός ἐστιν ἀποτρέπειν τούτων.", "st": "20.3"}, {"sp": "N", "t": "ὅστις μὲν οὖν ἄτιμος ὤν, κακόν τι ἐργασάμενος ἐν τῷ πρόσθεν χρόνῳ, ἑτέρας πολιτείας ἐπεθύμησε, διὰ τὰ πρόσθεν ἁμαρτήματα αὑτοῦ ἕνεκ’ ἂν ἔπραττε· τούτῳ δὲ τοιοῦτον οὐδὲν ἡμάρτητο, ὥστε αὑτοῦ ἕνεκα μισεῖν τὸ πλῆθος τὸ ὑμέτερον, ἢ τῶν παίδων. ὁ μὲν γὰρ ἐν Σικελίᾳ ἦν, οἱ δ’ ἐν Βοιωτοῖς· ὥστε μηδὲ τούτων ἕνεκα ἑτέρας πολιτείας ἐπιθυμῆσαι [διὰ τὰ πρόσθεν ἁμαρτήματα].", "st": "20.4"}, {"sp": "N", "t": "καὶ κατηγοροῦσι μὲν αὐτοῦ ὡς πολλὰς ἀρχὰς ἦρξεν, ἀποδεῖξαι δὲ οὐδεὶς οἷός τέ ἐστιν ὡς οὐ καλῶς ἦρξεν. ἐγὼ δ’ ἡγοῦμαι οὐ τούτους ἀδικεῖν ἐν τοῖς πράγμασιν ἐκείνοις, ἀλλ’ εἴ τις ὀλίγας ἄρξας ἀρχὰς μὴ τὰ ἄριστα ἦρξε τῇ πόλει. οὐ γὰρ οἱ καλῶς ἄρχοντες προὐδίδοσαν τὴν πόλιν,", "st": "20.5"}, {"sp": "N", "t": "ἀλλ’ οἱ μὴ δικαίως. οὗτος δὲ πρῶτον μὲν ἄρξας ἐν Ὠρωπῷ οὔτε προέδωκε οὔθ’ ἑτέραν πολιτείαν κατέστησε, τῶν ἄλλων ἁπάντων ὅσοι ἦρχον καταπροδόντων τὰ πράγματα. οἱ δ’ οὐχ ὑπέμειναν, καταγνόντες σφῶν αὐτῶν ἀδικεῖν· ὁ δὲ ἡγούμενος μηδὲν ἠδικηκέναι δίκην δίδωσι.", "st": "20.6"}, {"sp": "N", "t": "καὶ τοὺς μὲν ἀδικοῦντας οἱ κατήγοροι ἐκκλέπτουσιν, ἀργύριον λαμβάνοντες· παρ’ ὧν δ’ ἂν μὴ κερδαίνωσιν, ἀδικοῦντας ἀποφαίνουσι. καὶ ὁμοίας τὰς κατηγορίας ποιοῦνται τῶν τε εἰπόντων γνώμην τινὰ ἐν τῇ βουλῇ καὶ τῶν μή. οὗτος δὲ οὐδὲ γνώμην οὐδεμίαν εἶπε περὶ τοῦ ὑμετέρου πλήθους.", "st": "20.7"}, {"sp": "N", "t": "ἐγὼ δ’ ἡγοῦμαι ἀξίους εἶναι τούτους μηδὲν πάσχειν ὑφ’ ὑμῶν κακόν, εἰ ὑμῖν μὲν εὖνοι ἦσαν, ἐκείνοις δὲ ⟨οὐκ⟩ ἀπηχθάνοντο. τῶν γὰρ λεγόντων ἐναντία ἐκείνοις οἱ μὲν ἔφευγον οἱ δὲ ἀπέθνῃσκον, ὥστ’ εἴ τις καὶ ἐβούλετο ἐναντιοῦσθαι ὑπὲρ ὑμῶν, τὸ δέος καὶ ὁ φόνος τῶν πεπονθότων ἀπέτρεπε πάντας.", "st": "20.8"}, {"sp": "N", "t": "ὥστε οἱ πολλοὶ πάντα ἀπεγίγνωσκον αὐτῶν· τοὺς μὲν γὰρ ἐξήλαυνον αὐτῶν, τοὺς δὲ ἀπεκτίνυσαν. οἳ δὲ ἐκείνων ἔμελλον ἀκροᾶσθαι καὶ μηδὲν ἐπιβουλεύειν μηδὲ ἐξαγγέλλειν, τούτους ἂν καθίσταντο. ὥστε οὐκ ἂν ῥᾳδίως μετέστη ἂν ὑμῖν ἡ πολιτεία. οὔκουν δίκαιοί εἰσιν, ὧν ὑμῖν εὖνοι ἦσαν,", "st": "20.9"}, {"sp": "N", "t": "τούτων δίκην διδόναι. δεινὸν δέ μοι δοκεῖ εἶναι, εἰ τοῖς εἰποῦσι περὶ τὸ πλῆθος τὸ ὑμέτερον μὴ τὰ ἄριστα ὁ μηδὲν εἰπὼν ταὐτὰ πείσεται, καὶ ἐν μὲν ἑβδομήκοντα ἔτεσιν οὐδὲν ἐξήμαρτεν εἰς ὑμᾶς, ἐν ὀκτὼ δ’ ἡμέραις· καὶ οἱ μὲν τὸν βίον ἅπαντα πονηροὶ ὄντες χρηστοὶ ἐν τῷ λογιστηρίῳ γεγένηται, πείσαντες τοὺς κατηγόρους, οἳ δ’ ἀεὶ ὑμῖν χρηστοὶ ἦσαν, οὗτοι πονηροί.", "st": "20.10"}, {"sp": "N", "t": "καίτοι ἔν γε ταῖς πρότερον κατηγορίαις τά τε ἄλλα κατηγόρησαν ψευδῆ τοῦ πατρός, καὶ συγγενῆ Φρύνιχον αὐτοῦ εἶναι ἔφησαν. καίτοι εἴ τις βούλεται, ἐν τῷ λόγῳ τῷ ἐμῷ μαρτυρησάτω ὡς ἀναγκαῖον ὄντα Φρυνίχῳ. ἀλλὰ γὰρ ψευδῆ κατηγόρουν. ἀλλὰ μὴν οὐδ’ ἐκ παιδείας φίλος ἦν αὐτῷ· ὁ μὲν γὰρ ἐν ἀγρῷ πένης ὢν ἐποίμαινεν, ὁ δὲ πατὴρ ἐν τῷ ἄστει ἐπαιδεύετο.", "st": "20.11"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἀνὴρ ἐγένετο, ὁ μὲν ἐγεώργει, ὁ δ’ ἐλθὼν εἰς τὸ ἄστυ ἐσυκοφάντει, ὥστε μηδὲν ὁμολογεῖν τῷ τρόπῳ ἀλλήλων. καὶ ὅτ’ ἐξέτινε τῷ δημοσίῳ, οὐκ εἰσήνεγκεν αὐτῷ τὸ ἀργύριον· καίτοι ἐν τοῖς τοιούτοις μάλιστα δηλοῦσιν οἳ ἂν φίλοι ὦσιν. εἰ δ’ ἦν δημότης, οὐ δίκαιος διὰ τοῦτο βλάπτεσθαί ἐστιν ὁ πατήρ,", "st": "20.12"}, {"sp": "N", "t": "εἰ μὴ καὶ ὑμεῖς ἀδικεῖτε, ὅτι ὑμῶν ἐστι πολίτης. πῶς δ’ ἂν γένοιτο δημοτικώτερος, ἢ ὅστις ὑμῶν ψηφισαμένων πεντακισχιλίοις παραδοῦναι τὰ πράγματα καταλογεὺς ὢν ἐνακισχιλίους κατέλεξεν, ἵνα μηδεὶς αὐτῷ διάφορος εἴη τῶν δημοτῶν, ἀλλ’ ἵνα τὸν μὲν βουλόμενον ἐγγράφοι, εἰ δέ τῳ μὴ οἷόν τ’ εἴη, χαρίζοιτο. καίτοι οὐχ οἳ ἂν πλείους τοὺς πολίτας ποιῶσιν, οὗτοι καταλύουσι τὸν δῆμον, ἀλλ’ οἳ ἂν ἐκ πλειόνων ἐλάττους. οὗτος δὲ οὔτε ὀμόσαι ἤθελεν οὔτε καταλέγειν,", "st": "20.13"}, {"sp": "N", "t": "ἀλλ’ αὐτὸν ἠνάγκαζον, ἐπιβολὰς ἐπιβάλλοντες καὶ ζημιοῦντες· ἐπεὶ δὲ ἠναγκάσθη καὶ ὤμοσε τὸν ὅρκον, ὀκτὼ ἡμέρας εἰσελθὼν εἰς τὸ βουλευτήριον ἐξέπλει εἰς Ἐρέτριαν, καὶ ἐδόκει ἐκεῖ τὴν ψυχὴν οὐ πονηρὸς εἶναι ἐν ταῖς ναυμαχίαις, καὶ τετρωμένος δεῦρ’ ἦλθε, καὶ ἤδη μετεπεπτώκει τὰ πράγματα. καὶ οὗτος μὲν οὔτ’ εἰπὼν γνώμην οὐδεμίαν, οὔτε πλέον ὀκτὼ ἡμερῶν ἐλθὼν εἰς τὸ βουλευτήριον ὦφλε χρήματα τοσαῦτα· τῶν δ’ εἰπόντων ὑμῖν τἀναντία καὶ διὰ τέλους ἐν τῷ βουλευτηρίῳ ὄντων πολλοὶ ἀποπεφεύγασι.", "st": "20.14"}, {"sp": "N", "t": "καὶ οὐ φθονῶν τούτοις λέγω, ἀλλ’ ἡμᾶς ἐλεῶν· οἱ μὲν γὰρ δοκοῦντες ἀδικεῖν ἐξῃτημένοι εἰσὶν ὑπὸ τῶν ὑμῖν προθύμων ἐν τοῖς πράγμασι γενομένων, οἱ δ’ ἠδικηκότες ἐκπριάμενοι τοὺς κατηγόρους οὐδ’ ἔδοξαν ἀδικεῖν. πῶς [ἂν] οὖν οὐκ ἂν δεινὰ πάσχοιμεν;", "st": "20.15"}, {"sp": "N", "t": "καὶ κατηγοροῦσι μὲν τῶν τετρακοσίων, ὅτι ἦσαν κακοί· καίτοι ὑμεῖς αὐτοὶ πεισθέντες ὑπὸ τούτων παρέδοτε τοῖς πεντακισχιλίοις, καὶ εἰ αὐτοὶ τοσοῦτοι ὄντες ἐπείσθητε, ἕνα ἕκαστον τῶν τετρακοσίων οὐ χρῆν πεισθῆναι; ἀλλ’ οὐχ οὗτοι ἀδικοῦσιν, ἀλλ’ οἳ ὑμᾶς ἐξηπάτων καὶ κακῶς ἐποίουν. οὗτος δ’ ἐν πολλοῖς δηλοῖ ὑμῖν ⟨εὐνοῶν καὶ⟩ ὅτι, εἴ πέρ τι νεωτερίζειν ἐβούλετο εἰς τὸ ὑμέτερον πλῆθος, οὐκ ἄν ποτ’ ἐν ὀκτὼ ἡμέραις, εἰσελθὼν εἰς τὸ βουλευτήριον,", "st": "20.16"}, {"sp": "N", "t": "ᾤχετο ἐκπλέων. ἀλλ’ εἴποι ἄν τις κερδαίνειν ἐπιθυμῶν ἐξέπλευσεν, ὥσπερ ἔνιοι ἥρπαζον καὶ ἔφερον. οὐδεὶς τοίνυν ἂν εἴποι τι ὅπως τῶν ὑμετέρων ἔχει, ἀλλὰ πάντα μᾶλλον κατηγοροῦσιν ἢ εἰς τὴν ἀρχήν. καὶ οἱ κατήγοροι τότε μὲν οὐδαμῇ εὖνοι ὄντες ἐφαίνοντο τῷ δήμῳ οὐδὲ ἐβοήθουν· νῦν δὲ ἡνίκα αὐτὸς ἑαυτῷ εὐνούστατός ἐστιν ὁ δῆμος, βοηθοῦσι τῷ μὲν ὀνόματι ὑμῖν,", "st": "20.17"}, {"sp": "N", "t": "τῷ δὲ ἔργω σφίσιν αὐτοῖς. καὶ μὴ θαυμάζετε, ὦ ἄνδρες δικασταί, ὅτι τοσαῦτα ὦφλε χρήματα. ἔρημον γὰρ αὐτὸν λαβόντες αὐτοῦ τε καὶ ἡμῶν κατηγοροῦντες εἷλον. τῷ μὲν γὰρ οὐδ’ εἴ τις εἶχε μαρτυρίαν, εἶχε μαρτυρεῖν διὰ τὸ δέος τὸ τῶν κατηγόρων, τοῖς δὲ καὶ τὰ ψευδῆ δεδοικότες ἐμαρτύρουν. ἦ δεινά γ’ ἂν πάθοιμεν, ὦ ἄνδρες δικασταί,", "st": "20.18"}, {"sp": "N", "t": "εἰ τοὺς μὲν οὐχ οἵους τε ὄντας ἐξάρνους εἶναι μὴ οὐ χρήματα ἔχειν ὑμῶν, τούτους μὲν ἀφεῖτε ἀνδρὶ ἐξαιτουμένῳ, ἡμῖν δὲ αὐτοῖς τε προθύμοις γεγενημένοις περὶ τὸ πλῆθος τὸ ὑμέτερον, καὶ τοῦ πατρὸς οὐδὲν ὑμᾶς ἠδικηκότος, οὐ χαριεῖσθε. καὶ εἰ μὲν ξένος τις ἐλθὼν ὑμᾶς ἢ χρήματα ᾔτει ἢ εὐεργέτης ἀναγραφῆναι ἠξίου, ἔδοτε ἂν αὐτῷ· ἡμῖν δὲ οὐ δώσετε ἡμᾶς αὐτοὺς ἐπιτίμους ὑμῖν γενέσθαι;", "st": "20.19"}, {"sp": "N", "t": "εἰ δέ τινες κακόνοι ἐγένοντο εἰς τὰ ὑμέτερα πράγματα ἢ γνώμην μὴ ἐπιτηδείαν εἶπον, οὐχ οἱ ἀπόντες τούτων αἴτιοί εἰσιν, ἐπεὶ καὶ τοὺς παρόντας ὑμεῖς ἀπελύσατε. οὐδὲ γὰρ εἴ τις τῶν ἐνθάδε μὴ τὰ ἄριστα λέγων πείθει ὑμᾶς, οὐχ ὑμεῖς ἐστε αἴτιοι,", "st": "20.20"}, {"sp": "N", "t": "ἀλλ’ ὁ ἐξαπατῶν ὑμᾶς. ἐκεῖνοι δὲ σφῶν αὐτῶν προκαταγνόντες ἀδικεῖν οἴχονται, ἵνα μὴ δοῖεν δίκην· καὶ εἴ τινες ἄλλοι ἀδικοῦσιν, ἧττον μὲν ἐκείνων, ἀδικοῦσι δέ, τὸ δέος αὐτοὺς ποιεῖ τό τε ὑμέτερον καὶ τὸ τῶν κατηγόρων μὴ ἐπιδημεῖν ἀλλὰ στρατεύεσθαι, ἵνα ἢ ὑμᾶς πραοτέρους ποιῶσιν ἢ τούτους πείθωσιν.", "st": "20.21"}, {"sp": "N", "t": "οὗτος δὲ ὑμῖν δίκην δέδωκεν, οὐδὲν ὑμᾶς ἀδικῶν, εὐθὺς μετὰ τὰ πράγματα, ὅτε ὑμεῖς τε μάλιστα ἐμέμνησθε τῶν γενομένων καὶ οὗτος ἐλεγχθήσεσθαι ἔμελλε, πιστεύων αὑτῷ μηδὲν ἡμαρτῆσθαι ἀλλ’ ἀγωνιεῖσθαι εὖ μετὰ τοῦ δικαίου. ὡς δ’ ἦν δημοτικός, ἐγὼ ὑμῖν ἀποδείξω.", "st": "20.22"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ὅσων οὐδεμιᾶς στρατείας ἀπελείφθη, ἀλλ’ ἐστρατεύετο, ὡς συνειδότες ἂν εἴποιεν οἱ δημόται· καὶ ἐξὸν αὐτῷ τὴν οὐσίαν ἀφανῆ καταστήσαντι μηδὲν ὑμᾶς ὠφελεῖν, εἵλετο μᾶλλον συνειδέναι ὑμᾶς, ἵν’ εἰ καὶ βούλοιτο κακὸς εἶναι, μὴ ἐξείη αὐτῷ, ἀλλ’ εἰσφέροι τε τὰς εἰσφορὰς καὶ λῃτουργοίη. καὶ ἡμᾶς παρεσκεύασεν, ὡς ἂν τῇ πόλει ὠφελιμώτατοι εἴημεν.", "st": "20.23"}, {"sp": "N", "t": "καὶ ἐμὲ μὲν εἰς Σικελίαν ἐξέπεμψεν, ὑμῖν δ’ οὐκ ἦ …, ὥστ’ εἰδέναι τοὺς ἱππέας, οἷος ἦ τὴν ψυχήν, ἕως τὸ στρατόπεδον σῶν ἦν· ἐπειδὴ δὲ διεφθάρη καὶ ἀνεσώθην εἰς Κατάνην, ἐλῃζόμην ὁρμώμενος ἐντεῦθεν καὶ τοὺς πολεμίους κακῶς ἐποίουν, ὥστε τῇ θεῷ τε τὰς δεκάτας ἐξαιρεθῆναι πλέον ἢ τριάκοντα μνᾶς καὶ τοῖς στρατιώταις εἰς σωτηρίαν ὅσοι ἐν τοῖς πολεμίοις ἦσαν.", "st": "20.24"}, {"sp": "N", "t": "καὶ ἐπειδὴ Καταναῖοι ἠνάγκαζον ἱππεύειν, ἵππευον καὶ οὐδενὸς οὐδ’ ἐνταῦθα κινδύνου ἀπελειπόμην, ὥστ’ εἰδέναι ἅπαντας οἷος ἦν τὴν ψυχὴν ἱππεύων τε καὶ ὁπλιτεύων. ⟨ὧν⟩ ὑμῖν τοὺς μάρτυρας παρέξομαι.", "st": "20.25"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "20.26"}, {"sp": "N", "t": "ἀκηκόατε μὲν τῶν μαρτύρων, ὦ ἄνδρες δικασταί· οἷος δ’ εἰμὶ περὶ τὸ ὑμέτερον πλῆθος, ἐγὼ ὑμῖν ἀποδείξω. ἀφικομένου γὰρ ἐκεῖσε Συρακουσίου ὅρκιον ἔχοντος καὶ ἑτοίμου ὄντος ὁρκοῦν καὶ προσιόντος πρὸς ἕνα ἕκαστον τῶν ἐκεῖ ὄντων, ἀντεῖπον εὐθὺς αὐτῷ, καὶ ἐλθὼν ὡς Τυδέα διηγούμην ταῦτα, καὶ σύλλογον ἐποίει, καὶ λόγοι οὐκ ὀλίγοι ἦσαν. ὧν δ’ οὖν ἐγὼ εἶπον, καλῶ μάρτυρας.", "st": "20.26"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "20.27"}, {"sp": "N", "t": "σκέψασθε δὴ καὶ τοῦ πατρὸς τὴν ἐπιστολήν, ἣν ἔδωκεν ἀποδοῦναι ἐμοί, πότερα τῷ ὑμετέρῳ πλήθει ἀγαθὰ ἐνῆν ἢ οὔ. τά τε γὰρ οἰκεῖα ἐνεγέγραπτο, καὶ ἔτι, ὅτε καλῶς ἔχοι τὰ ἐν Σικελίᾳ, ἥκειν. καίτοι ταὐτὰ ὑμῖν συνέφερε καὶ τοῖς ἐκεῖ· ὥστ’ εἰ μὴ εὔνους ἦν τῇ πόλει καὶ ὑμῖν, οὐκ ἄν ποτε τοιαῦτα ἐπέστελλεν.", "st": "20.27"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ τὸν ἀδελφὸν τὸν νεώτατον, οἷος εἰς ὑμᾶς ἐστιν, ἐγὼ ἀποδείξω. καταδρομῆς γὰρ γενομένης τῶν φυγάδων, ⟨οἳ⟩ οὐ μόνον ἐνθάδε ὅ τι οἷοι τ’ ἦσαν κακὸν εἰργάζοντο, ἀλλὰ καὶ ἀπὸ τοῦ τείχους ἔφερον καὶ ἦγον ὑμᾶς, ἐξελάσας ἐκ τῶν ἄλλων ἱππέων ἕνα ἀπέκτεινεν. ὧν ὑμῖν αὐτοὺς μάρτυρας τοὺς παραγενομένους παρέξομαι.", "st": "20.28"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "20.29"}, {"sp": "N", "t": "τὸν δὲ πρεσβύτατον ἀδελφὸν αὐτοὶ οἱ συστρατευόμενοι ἴσασιν, οἵτινες μετὰ Λέοντος ἦτε ἐν Ἑλλησπόντῳ, ὥστε νομίζειν μηδενὸς ἥττον’ εἶναι ἀνθρώπων τὴν ψυχήν. καὶ μοι ἀνάβητε δεῦρο.", "st": "20.29"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "20.30"}, {"sp": "N", "t": "πῶς οὖν οὐ χρὴ χάριν παρ’ ὑμῶν ἀπολαμβάνειν, εἰ τοιοῦτοί ἐσμεν; ἀλλ’ ὧν μὲν ὁ πατὴρ διαβέβληται εἰς ὑμᾶς, δικαίως τούτων δεῖ ἡμᾶς ἕνεκα ἀπολέσθαι, [δι’] ὧν δὲ πρόθυμοι εἰς τὴν πόλιν γεγενήμεθα, μηδεμίαν ὠφέλειαν γενέσθαι; ἀλλ’ οὐ δίκαιον. ἀλλ’ εἰ διὰ τὴν τούτου διαβολὴν δεῖ ἡμᾶς ⟨τι⟩ πάσχειν, δίκαιοί ἐσμεν διὰ τὴν ἡμετέραν προθυμίαν τοῦτόν τε σῶσαι καὶ ἡμᾶς.", "st": "20.30"}, {"sp": "N", "t": "οὐ γὰρ δὴ ἡμεῖς χρημάτων γε ἕνεκα, ἵνα λάβοιμεν, εὖ ὑμᾶς ἐποιοῦμεν, ἀλλ’ ἵνα, εἴ ποτε κίνδυνος εἴη ἡμῖν, ἐξαιτούμενοι παρ’ ὑμῶν τὴν ἀξίαν χάριν ἀπολάβοιμεν. χρὴ δὲ ὑμᾶς καὶ τῶν ἄλλων ἕνεκα τοιούτους εἶναι, γιγνώσκοντας ὅτι, ἐάν τις πρόθυμος εἰς ὑμᾶς ᾖ, οὐ μόνον ἡμᾶς ὠφελήσετε· ἡμῶν μὲν γὰρ καὶ πρὶν δεηθῆναι πεπείρασθε, οἷοί ἐσμεν εἰς ὑμᾶς· τοὺς δὲ ἄλλους προθυμοτέρους ποιήσετε, κατ’ ἀξίαν χαριζόμενοι, ὅσ’ ἄν τις ὑμᾶς εὖ ποιῇ.", "st": "20.31"}, {"sp": "N", "t": "καὶ μηδαμῶς τοῖς λέγουσι βεβαιώσητε λόγον τὸν πάντων πονηρότατον· λέγεται γὰρ τοὺς κακῶς πεπονθότας μεμνῆσθαι μᾶλλον ἢ τοὺς εὖ. τίς γὰρ ἔτι ἐθελήσει χρηστὸς εἶναι, εἰ ἡττηθήσονται τῶν κακῶς ὑμᾶς ποιούντων οἱ εὖ ποιοῦντες; ἔχει δ’ ὑμῖν,", "st": "20.32"}, {"sp": "N", "t": "ὦ ἄνδρες δικασταί, οὕτως. περὶ ἡμῶν γάρ ἐστι ψῆφος ὑμῖν, καὶ οὐ περὶ χρημάτων. ἕως μὲν γὰρ εἰρήνη, ἦν ἡμῖν φανερὰ οὐσία, καὶ ἦν ὁ πατὴρ ἀγαθὸς γεωργός· ἐπειδὴ δὲ εἰσέβαλον οἱ πολέμιοι, πάντων τούτων ἐστερήθημεν. ὥστε αὐτῶν τούτων ἕνεκα πρόθυμοι ἦμεν εἰς ὑμᾶς, εἰδότες ὅτι χρήματα μὲν ἡμῖν οὐκ εἴη ὁπόθεν ἐκτίσομεν, αὐτοὶ δὲ πρόθυμοι ὄντες εἰς ὑμᾶς ἀξιοῦμεν εὑρίσκεσθαι χάριν.", "st": "20.33"}, {"sp": "N", "t": "καίτοι ὁρῶμέν γ’ ὑμᾶς, ὦ ἄνδρες δικασταί, ἐάν τις παῖδας αὑτοῦ ἀναβιβασάμενος κλαίῃ καὶ ὀλοφύρηται, τούς τε παῖδας δι’ αὐτὸν εἰ ἀτιμωθήσονται ἐλεοῦντας, καὶ ἀφιέντας τὰς τῶν πατέρων ἁμαρτίας διὰ τοὺς παῖδας, οὓς οὔπω ἴστε εἴτε ἀγαθοὶ εἴτε κακοὶ ἡβήσαντες γενήσονται· ἡμᾶς δ’ ἴστε ὅτι πρόθυμοι γεγενήμεθα εἰς ὑμᾶς, καὶ τὸν πατέρα οὐδὲν ἡμαρτηκότα. ὥστε πολλῷ δικαιότεροί ἐστε, ὧν πεπείρασθε, τούτοις χαρίσασθαι, ἢ οὓς οὐκ ἴστε ὁποῖοί τινες ἔσονται.", "st": "20.34"}, {"sp": "N", "t": "πεπόνθαμεν δὲ τοὐναντίον τοῖς ἄλλοις ἀνθρώποις. οἱ μὲν γὰρ ἄλλοι τοὺς παῖδας παραστησάμενοι ἐξαιτοῦνται ὑμᾶς, ἡμεῖς δὲ τὸν πατέρα τουτονὶ καὶ ἡμᾶς ἐξαιτούμεθα, μὴ ἡμᾶς ἀντὶ μὲν ἐπιτίμων ἀτίμους ποιήσητε, ἀντὶ δὲ πολιτῶν ἀπόλιδας· ἀλλὰ ἐλεήσατε καὶ τὸν πατέρα γέροντα ὄντα καὶ ἡμᾶς. εἰ δὲ ἡμᾶς ἀδίκως ἀπολεῖτε, πῶς ἢ οὗτος ἡμῖν ἡδέως συνέσται ἢ ἡμεῖς ἀλλήλοις ἐν τῷ αὐτῷ, ὄντες ὑμῶν τε ἀνάξιοι καὶ τῆς πόλεως; ἀλλ’ ὑμῶν δεόμεθα τρεῖς ὄντες ἐᾶσαι ἡμᾶς ἔτι προθυμοτέρους γενέσθαι.", "st": "20.35"}, {"sp": "N", "t": "δεόμεθα οὖν ὑμῶν πρὸς τῶν ὑπαρχόντων ἀγαθῶν ἑκάστῳ, ὅτῳ μὲν εἰσὶν ὑεῖς, τούτων ἕνεκα ἐλεῆσαι, ὅστις ⟨δ’⟩ ἡμῖν ἡλικιώτης τυγχάνει ἢ τῷ πατρί, ἐλεήσαντας ἀποψηφίσασθαι· καὶ μὴ ἡμᾶς βουλομένους εὖ ποιεῖν τὴν πόλιν ὑμεῖς κωλύσητε. δεινὰ δ’ ἂν πάθοιμεν, εἰ ὑπὸ τῶν πολεμίων μὲν ἐσώθημεν, οὓς εἰκὸς ἦν διακωλύειν μὴ σῴζεσθαι, παρ’ ὑμῶν δὲ μηδὲ εὑρησόμεθα τὸ σωθῆναι.", "st": "20.36"}, {"sp": "HDR", "t": "ΚΑʹ. Ἀπολογία δωροδοκίας ἀπαράσημος", "st": "21"}, {"sp": "N", "t": "περὶ μὲν τῶν κατηγορημένων, ὦ ἄνδρες δικασταί, ἱκανῶς ὑμῖν ἀποδέδεικται· ἀκοῦσαι δὲ καὶ περὶ τῶν ἄλλων ὑμᾶς ἀξιῶ, ἵν’ ἐπίστησθε περὶ οἵου τινὸς ὄντος ἐμοῦ ψηφιεῖσθε. ἐγὼ γὰρ ἐδοκιμάσθην μὲν ἐπὶ Θεοπόμπου ἄρχοντος, καταστὰς δὲ χορηγὸς τραγῳδοῖς ἀνήλωσα τριάκοντα μνᾶς καὶ τρίτῳ μηνὶ Θαργηλίοις νικήσας ἀνδρικῷ χορῷ δισχιλίας δραχμάς, ἐπὶ δὲ Γλαυκίππου ἄρχοντος εἰς πυρριχιστὰς Παναθηναίοις τοῖς μεγάλοις ὀκτακοσίας.", "st": "21.1"}, {"sp": "N", "t": "ἔτι δ’ ἀνδράσι χορηγῶν εἰς Διονύσια ἐπὶ τοῦ αὐτοῦ ἄρχοντος ἐνίκησα, καὶ ἀνήλωσα σὺν τῇ τοῦ τρίποδος ἀναθέσει πεντακισχιλίας δραχμάς, καὶ ἐπὶ Διοκλέους Παναθηναίοις τοῖς μικροῖς κυκλίῳ χορῷ τριακοσίας. τὸν δὲ μεταξὺ χρόνον ἐτριηράρχουν ἑπτὰ ἔπτὰ ἔτη,", "st": "21.2"}, {"sp": "N", "t": "καὶ ἓξ τάλαντα ἀνήλωσα. καὶ τοσαύτας δαπάνας δαπανώμενος καὶ καθ’ ἡμέραν ὑπὲρ ὑμῶν κινδυνεύων καὶ ἀποδημῶν, ὅμως εἰσφορὰς τὴν μὲν τριάκοντα μνᾶς τὴν δὲ τετρακισχιλίας δραχμὰς εἰσενήνοχα. ἐπειδὴ δὲ κατέπλευσα ἐπὶ Ἀλεξίου ἄρχοντος, εὐθὺς ἐγυμνασιάρχουν εἰς Προμήθεια, καὶ ἐνίκων ἀναλώσας δώδεκα μνᾶς.", "st": "21.3"}, {"sp": "N", "t": "καὶ ὕστερον κατέστην χορηγὸς παιδικῷ χορῷ καὶ ἀνήλωσα πλέον ἢ πεντεκαίδεκα μνᾶς. ἐπὶ δὲ Εὐκλείδου ἄρχοντος κωμῳδοῖς χορηγῶν Κηφισοδώρῳ ἐνίκων, καὶ ἀνήλωσα σὺν τῇ τῆς σκευῆς ἀναθέσει ἑκκαίδεκα μνᾶς, καὶ Παναθηναίοις τοῖς μικροῖς ἐχορήγουν πυρριχισταῖς ἀγενείοις, καὶ ἀνήλωσα ἑπτὰ μνᾶς.", "st": "21.4"}, {"sp": "N", "t": "νενίκηκα δὲ τριήρει μὲν ἁμιλλώμενος ἐπὶ Σουνίῳ, ἀναλώσας πεντεκαίδεκα μνᾶς· χωρὶς δὲ ἀρχιθεωρίας καὶ Ἐρρηφορίας καὶ ἄλλα τοιαῦτα, εἰς ἃ ἐμοὶ δεδαπάνηται πλέον ἢ τριάκοντα μναῖ. καὶ τούτων ὧν κατέλεξα, εἰ ἐβουλόμην κατὰ τὰ γεγραμμένα ἐν τῷ νόμῳ λῃτουργεῖν, οὐδ’ ἂν τὸ τέταρτον μέρος ἀνήλωσα. τὸν δὲ χρόνον ὃν ἐτριηράρχουν,", "st": "21.5"}, {"sp": "N", "t": "ἡ ναῦς ἄριστά μοι ἔπλει παντὸς τοῦ στρατοπέδου. τεκμήριον δὲ τούτου ὑμῖν μέγιστον ἐρῶ. πρῶτον μὲν γὰρ Ἀλκιβιάδης, ὃν ἐγὼ περὶ πολλοῦ ἂν ἐποιησάμην μὴ συμπλεῖν μοι, οὔτε φίλος ὢν οὔτε συγγενὴς οὔτε φυλέτης ἔπλει ἐπὶ τῆς ἐμῆς νεώς.", "st": "21.6"}, {"sp": "N", "t": "καίτοι ὑμᾶς οἶμαι εἰδέναι ὅτι στρατηγὸς ὤν, ᾧ ἐξῆν ποιεῖν ὅ τι ἐβούλετο, οὐκ ἄν ποτε ἀνέβη ἐπ’ ἄλλην ναῦν εἰ μὴ τὴν ἄριστα πλέουσαν, μέλλων αὐτὸς κινδυνεύσειν. ἐπειδὴ δὲ ἐκείνους μὲν ὑμεῖς ἐπαύσατε τῆς ἀρχῆς,", "st": "21.7"}, {"sp": "N", "t": "τοὺς δὲ μετὰ Θρασύλλου δέκα ἕλεσθε, οὗτοι πάντες ἐβούλοντο ἐπὶ τῆς ἐμῆς νεὼς πλεῖν, ἀνέβη μέντοι πολλῶν λοιδοριῶν αὐτοῖς γενομένων Ἀρχέστρατος ὁ Φρεάρριος· ἀποθανόντος δὲ τούτου ἐν Μυτιλήνῃ Ἐρασινίδης μετ’ ἐμοῦ συνέπλει. καίτοι οὕτω παρεσκευασμένην τριήρη πόσα οἴεσθε ἀνηλωκέναι χρήματα;", "st": "21.8"}, {"sp": "N", "t": "ἢ πόσα τοὺς πολεμίους εἰργάσθαι κακά; ἢ πόσα τὴν πόλιν εὖ πεποιηκέναι; τεκμήριον δὲ τούτου μέγιστον· ὅτε γὰρ ἐν τῇ τελευταίᾳ ναυμαχία αἱ νῆες διεφθάρησαν, οὐδενός μοι συμπλέοντος στρατηγοῦ (ἵνα καὶ τούτου μνησθῶ, ἐπειδὴ καὶ τοῖς τριηράρχοις ὠργίσθητε διὰ τὴν γενομένην συμφοράν) ἐγὼ τήν τε ἐμαυτοῦ ναῦν ἐκόμισα καὶ τὴν Ναυσιμάχου τοῦ Φαληρέως ἔσωσα.", "st": "21.9"}, {"sp": "N", "t": "καὶ ταῦτα οὐκ ἀπὸ τύχης ἐγίγνετο, ἀλλ’ ἀπὸ παρασκευῆς τῆς ἐμῆς· εἶχον γὰρ χρήμασι πείσας κυβερνήτην Φαντίαν ἅπαντα τὸν χρόνον, ὃς ἐδόκει τῶν Ἑλλήνων ἄριστος εἶναι, παρεσκευασάμην δὲ καὶ τὸ πλήρωμα πρὸς ἐκεῖνον καὶ τὴν ἄλλην ὑπηρεσίαν ἀκόλουθον. καὶ ταῦθ’ ὅτι ἀληθῆ λέγω, πάντες ἐπίστασθε, ὅσοι ἐτυγχάνετε ὄντες ἐκεῖ τῶν στρατιωτῶν. κάλεσον δὲ καὶ Ναυσίμαχον.", "st": "21.10"}, {"sp": "N", "t": "<em>Μαρτυρία<\/em>", "st": "21.11"}, {"sp": "N", "t": "αἱ μὲν τοίνυν σωθεῖσαι τῶν νεῶν δώδεκα ἦσαν· ἐγὼ δ’ ὑμῖν δύο ἐκόμισα, τὴν ἐμαυτοῦ καὶ τὴν Ναυσιμάχου τριήρη.", "st": "21.11"}, {"sp": "N", "t": "καὶ οὕτω πολλοὺς κινδύνους ὑπὲρ ὑμῶν κεκινδυνευκὼς καὶ τοσαῦτα ἀγαθὰ εἰργασμένος τὴν πόλιν, νυνὶ δέομαι οὐ δωρεὰν ὥσπερ ἕτεροι ἀντὶ τούτων παρ’ ὑμῶν λαβεῖν, ἀλλὰ μὴ στερηθῆναι τῶν ἐμαυτοῦ, ἡγούμενος καὶ ὑμῖν αἰσχρὸν εἶναι παρά τε ἑκόντος ἐμοῦ καὶ παρ’ ἄκοντος λαμβάνειν.", "st": "21.11"}, {"sp": "N", "t": "καὶ οὐ τοσοῦτόν μοι μέλει εἴ με δεῖ τὰ ὄντα ἀπολέσαι· ἀλλ’ οὐκ ἂν δεξαίμην ὑβρισθῆναι, οὐδὲ παραστῆναι τοῖς διαδυομένοις τὰς λῃτουργίας ἐμοὶ μὲν ἀχάριστα εἶναι τὰ εἰς ὑμᾶς ἀνηλωμένα, ἐκείνους δὲ δοκεῖν ὀρθῶς βεβουλεῦσθαι ὅτι ὑμῖν οὐδὲν προεῖνται τῶν σφετέρων αὐτῶν. ἐὰν οὖν ἐμοὶ πεισθῆτε, τά τε δίκαια ψηφιεῖσθε καὶ τὰ λυσιτελοῦντα ὑμῖν αὐτοῖς αἱρήσεσθε.", "st": "21.12"}, {"sp": "N", "t": "ὁρᾶτε γάρ, ὦ ἄνδρες δικασταί, τὰ προσιόντα τῇ πόλει ὡς ὀλίγα ἐστί, καὶ ταῦτα ὡς ὑπὸ τῶν ἐφεστηκότων ἁρπάζεται· ὥστ’ ἄξιον ταύτην ἡγεῖσθαι πρόσοδον βεβαιοτάτην τῇ πόλει, τὰς οὐσίας τῶν ἐθελόντων λῃτουργεῖν. ἐὰν οὖν εὖ βουλεύσησθε, οὐδὲν ἧττον ἐπιμελήσεσθε τῶν ἡμετέρων χρημάτων ἢ τῶν ἰδίων τῶν ὑμετέρων αὐτῶν,", "st": "21.13"}, {"sp": "N", "t": "εἰδότες ὅτι ἕξετε πᾶσι χρῆσθαι τοῖς ἡμετέροις ὥσπερ καὶ πρότερον· οἶμαι δὲ πάντας ὑμᾶς ἐπίστασθαι ὅτι τῶν ἐμῶν ἐγὼ πολὺ βελτίων ὑμῖν ἔσομαι ταμίας τῶν τὰ τῆς πόλεως ὑμῖν ταμιευόντων. ἐὰν δ’ ἐμὲ πένητα ποιήσητε, καὶ ὑμᾶς αὐτοὺς ἀδικήσετε· ἕτεροι δὲ καὶ ταῦτα διανεμοῦνται, ὥσπερ καὶ τἆλλα.", "st": "21.14"}, {"sp": "N", "t": "ἄξιον δέ ἐστιν ἐνθυμηθῆναι ὅτι πολὺ μᾶλλον ὑμῖν προσήκει τῶν ὑμετέρων ἐμοὶ διδόναι ἢ τῶν ἐμῶν ἐμοὶ ἀμφισβητῆσαι, καὶ πένητα γενόμενον ἐλεῆσαι μᾶλλον ἢ πλουτοῦντι φθονῆσαι, καὶ τοῖς θεοῖς εὔχεσθαι τοὺς ἄλλους εἶναι τοιούτους πολίτας, ἵνα τῶν μὲν ὑμετέρων ⟨μὴ⟩ ἐπιθυμήσωσι, τὰ δὲ σφέτερα αὐτῶν εἰς ὑμᾶς ἀναλίσκωσιν.", "st": "21.15"}, {"sp": "N", "t": "ἡγοῦμαι δ’, ὦ ἄνδρες δικασταί (καὶ μηδεὶς ὑμῶν ἀχθεσθῇ), πολὺ ἂν δικαιότερον ὑμᾶς ὑπὸ τῶν ζητητῶν ἀπογραφῆναι τὰ ἐμὰ ἔχειν, ἢ ἐμὲ νυνὶ κινδυνεύειν ὡς τοῦ δημοσίου χρήματα ἔχοντα. τοιοῦτον γὰρ ἐμαυτὸν τῇ πόλει παρέχω, ὥστε ἰδίᾳ μὲν τῶν ⟨ὄντων⟩ φείδομαι, δημοσίᾳ δὲ λῃτουργῶν ἥδομαι, καὶ οὐκ ἐπὶ τοῖς περιοῦσι μέγα φρονῶ, ἀλλ’ ἐπὶ τοῖς εἰς ὑμᾶς ἀνηλωμένοις,", "st": "21.16"}, {"sp": "N", "t": "ἡγούμενος τούτων μὲν αὐτὸς αἴτιος εἶναι, τὴν δ’ οὐσίαν ἑτέρους μοι καταλιπεῖν, καὶ διὰ ταύτην μὲν ὑπὸ τῶν ἐχθρῶν ἀδίκως συκοφαντεῖσθαι, δι’ ἐκεῖνα δὲ ὑφ’ ὑμῶν δικαίως σῴζεσθαι. ὥστ’ οὐκ ἂν εἰκότως ἕτεροί με ἐξῃτήσαντο παρ’ ὑμῶν, ἀλλὰ καὶ εἴ τις τῶν ἐμῶν φίλων τοιοῦτον ἀγῶνα ἠγωνίζετο, ὑμᾶς ἂν ἠξίουν ἐμοὶ δοῦναι τὴν χάριν, καὶ εἰ παρ’ ἄλλοις ἐκινδύνευον, ὑμᾶς εἶναι τοὺς δεομένους ὑπὲρ ἐμοῦ.", "st": "21.17"}, {"sp": "N", "t": "⟨οὐ γὰρ ἂν⟩ τοῦτό γε εἰπεῖν ἔχοι τις, ὡς πολλὰς ἀρχὰς ἄρξας ἐκ τῶν ὑμετέρων ὠφέλημαι, ἢ ὡς αἰσχρὰς δίκας δεδίκασμαι, ἢ ὡς αἰσχροῦ τινος αἴτιός εἰμι, ἢ ὡς τὰς τῆς πόλεως συμφορὰς ἀσμένως εἶδον· ὑπὲρ ἁπάντων δὲ καὶ ⟨τῶν⟩ ἰδίων καὶ τῶν δημοσίων οὕτως ἡγοῦμαί μοι πεπολιτεῦσθαι καὶ ὑμᾶς εἰδέναι, ὥστε οὐδὲν δεῖν με ἀπολογήσασθαι περὶ αὐτῶν.", "st": "21.18"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν, ὦ ἄνδρες δικασταί, τὴν αὐτὴν νῦν περὶ ἐμοῦ γνώμην ἔχειν ἥνπερ καὶ ἐν τῷ τέως χρόνῳ, καὶ μὴ μόνον τῶν δημοσίων λῃτουργιῶν μεμνῆσθαι, ἀλλὰ τῶν ἰδίων ἐπιτηδευμάτων ἐνθυμεῖσθαι, ἡγουμένους ταύτην εἶναι [τὴν] λῃτουργίαν ἐπιπονωτάτην, διὰ τέλους τὸν πάντα χρόνον κόσμιον εἶναι καὶ σώφρονα καὶ μήθ’ ὑφ’ ἡδονῆς ἡττηθῆναι μήθ’ ὑπὸ κέρδους ἐπαρθῆναι, ἀλλὰ τοιοῦτον παρασχεῖν ἑαυτὸν ὥστε μηδένα τῶν πολιτῶν μήτε μέμψασθαι μήτε δίκην τολμῆσαι προσκαλέσασθαι.", "st": "21.19"}, {"sp": "N", "t": "οὔκουν ἄξιον, ὦ ἄνδρες δικασταί, πειθομένους κατηγόροις τοιούτοις ἐμοῦ καταψηφίσασθαι, οἳ περὶ ἀσεβείας μὲν ἀγωνιζόμενοι τηλικοῦτοι γεγόνασιν, οὐκ ἂν δυνάμενοι δ’ ὑπὲρ τῶν σφετέρων ἁμαρτημάτων ἀπολογήσασθαι ἑτέρων κατηγορεῖν τολμῶσι. καὶ ὧν Κινησίας οὕτω διακείμενος πλείους στρατείας ἐστράτευται, οὗτοι περὶ τῶν τῆς πόλεως ἀγανακτοῦσι. καὶ ἐξ ὧν μὲν ἡ πόλις εὐδαίμων ἔσται, οὐ συμβάλλονται, πάντα δὲ ποιοῦσιν ὅπως ὑμεῖς τοῖς εὖ πεποιηκόσιν ὀργισθήσεσθε.", "st": "21.20"}, {"sp": "N", "t": "οὗτοι μὲν οὖν, ὦ ἄνδρες δικασταί, ἐν τῷ δήμῳ κατείποιεν ὑμῖν τὰ σφέτερ’ αὐτῶν ἐπιτηδεύματα· οὐ γὰρ ἂν ἔχοιμι ὅ τι τούτου μεῖζον αὐτοῖς εὐξαίμην κακόν· ἐγὼ δ’ ὑμῶν δέομαι καὶ ἱκετεύω καὶ ἀντιβολῶ μὴ καταγνῶναι δωροδοκίαν ἐμοῦ, μηδ’ ἡγήσασθαι τοσαῦτα χρήματα εἶναι, ⟨δι’⟩ ἃ ἐγὼ βουληθείην ἄν τι κακὸν τῇ πόλει γενέσθαι.", "st": "21.21"}, {"sp": "N", "t": "μαινοίμην γὰρ ⟨ἄν⟩, ὦ ἄνδρες δικασταί, εἰ τὴν μὲν πατρῴαν οὐσίαν φιλοτιμούμενος εἰς ὑμᾶς ἀναλίσκοιμι, ἐπὶ δὲ τῷ τῆς πόλεως κακῷ παρὰ τῶν ἄλλων δωροδοκοίην. ἐγὼ μὲν οὖν, ὦ ἄνδρες δικασταί, οὐκ οἶδ’ οὕστινας ἢ ὑμᾶς ἐβουλήθην περὶ ἐμοῦ δικαστὰς γενέσθαι, εἴπερ χρὴ τοὺς εὖ πεπονθότας περὶ τῶν εὖ πεποιηκότων εὔχεσθαι τὴν ψῆφον φέρειν.", "st": "21.22"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, (ἐπιθυμῶ γὰρ καὶ τούτων μνησθῆναι) οὐδεπώποτε λῃτουργεῖν ὑπὲρ ὑμῶν δέον ⟨δεινὸν ἡγούμην⟩, εἰ τοσούτῳ πενεστέρους τοὺς παῖδας καταλείψω, ἀλλὰ πολὺ μᾶλλον εἰ μὴ προθύμως ποιήσω τὰ προσταχθέντα·", "st": "21.23"}, {"sp": "N", "t": "οὐδ’ εἴ ποτε κινδυνεύσειν ἐν ταῖς ναυμαχίαις μέλλοιμι, οὐδεπώποτ’ ἠλέησα οὐδ’ ἐδάκρυσα οὐδ’ ἐμνήσθην γυναικὸς οὐδὲ παίδων τῶν ἐμαυτοῦ, οὐδ’ ἡγούμην δεινὸν εἶναι εἰ τελευτήσας ὑπὲρ τῆς πατρίδος τὸν βίον ὀρφανοὺς καὶ πατρὸς ἀπεστερημένους αὐτοὺς καταλείψω, ἀλλὰ πολὺ μᾶλλον εἰ σωθεὶς αἰσχρῶς ὀνείδη καὶ ἐμαυτῷ καὶ ἐκείνοις περιάψω.", "st": "21.24"}, {"sp": "N", "t": "ἀνθ’ ὧν ὑμᾶς ἀπαιτῶ νῦν τὴν χάριν, καὶ ἀξιῶ, ἐν τοῖς κινδύνοις ἐμοῦ τοιαύτην περὶ ὑμῶν γνώμην ἔχοντος, ὑμᾶς νυνὶ ἐν τῷ θαρραλέῳ ὄντας ἐμὲ καὶ τοὺς παῖδας τούτους περὶ πολλοῦ ποιήσασθαι, ἡγουμένους ἡμῖν μὲν δεινὸν ὑμῖν δὲ αἰσχρὸν εἶναι, εἰ ἀναγκασθησόμεθα ἐπὶ τοιαύταις αἰτίαις ἄτιμοι γενέσθαι, ἢ στερηθέντες τῶν ὑπαρχόντων πένητες εἶναι καὶ πολλῶν ἐνδεεῖς ὄντες περιιέναι, ἀνάξια μὲν ἡμῶν αὐτῶν πεπονθότες, ἀνάξια δὲ τῶν εἰς ὑμᾶς ὑπηργμένων. μηδαμῶς, ὦ ἄνδρες δικασταί· ἀλλ’ ἀποψηφισάμενοι τοιούτοις ἡμῖν χρῆσθε πολίταις οἵοισπερ ἐν τῷ πρόσθεν χρόνῳ.", "st": "21.25"}, {"sp": "HDR", "t": "ΚΒʹ. Κατὰ τῶν σιτοπωλῶν", "st": "22"}, {"sp": "N", "t": "πολλοί μοι προσεληλύθασιν, ὦ ἄνδρες δικασταί, θαυμάζοντες ὅτι ἐγὼ τῶν σιτοπωλῶν ἐν τῇ βουλῇ κατηγόρουν, καὶ λέγοντες ὅτι ὑμεῖς, εἰ ὡς μάλιστα αὐτοὺς ἀδικεῖν ἡγεῖσθε, οὐδὲν ἧττον καὶ τοὺς περὶ τούτων λόγους ποιουμένους συκοφαντεῖν νομίζετε. ὅθεν οὖν ἠνάγκασμαι κατηγορεῖν αὐτῶν, περὶ τούτων πρῶτον εἰπεῖν βούλομαι.", "st": "22.1"}, {"sp": "N", "t": "ἐπειδὴ γὰρ οἱ πρυτάνεις ἀπέδοσαν εἰς τὴν βουλὴν περὶ αὐτῶν, οὕτως ὠργίσθησαν αὐτοῖς, ὥστε ἔλεγόν τινες τῶν ῥητόρων ὡς ἀκρίτους αὐτοὺς χρὴ τοῖς ἕνδεκα παραδοῦναι θανάτῳ ζημιῶσαι. ἡγούμενος δὲ ἐγὼ δεινὸν εἶναι τοιαῦτα ἐθίζεσθαι ποιεῖν τὴν βουλήν, ἀναστὰς εἶπον ὅτι μοι δοκοίη κρίνειν τοὺς σιτοπώλας κατὰ τὸν νόμον, νομίζων, εἰ μέν εἰσιν ἄξια θανάτου εἰργασμένοι, ὑμᾶς οὐδὲν ἧττον ἡμῶν γνώσεσθαι τὰ δίκαια, εἰ δὲ μηδὲν ἀδικοῦσιν, οὐ δεῖν αὐτοὺς ἀκρίτους ἀπολωλέναι. πεισθείσης δὲ τῆς βουλῆς ταῦτα,", "st": "22.2"}, {"sp": "N", "t": "διαβάλλειν ἐπεχείρουν με λέγοντες ὡς ἐγὼ σωτηρίας ἕνεκα τῆς τῶν σιτοπωλῶν τοὺς λόγους τούτους ἐποιούμην. πρὸς μὲν οὖν βουλήν, ὅτ’ ἦν αὐτοῖς ἡ κρίσις, ἔργῳ ἀπελογησάμην· τῶν γὰρ ἄλλων ἡσυχίαν ἀγόντων ἀναστὰς αὐτῶν κατηγόρουν, καὶ πᾶσι φανερὸν ἐποίησα ὅτι οὐχ ὑπὲρ τούτων ἔλεγον, ἀλλὰ τοῖς νόμοις τοῖς κειμένοις ἐβοήθουν.", "st": "22.3"}, {"sp": "N", "t": "ἠρξάμην μὲν οὖν τούτων ἕνεκα, δεδιὼς τὰς αἰτίας· αἰσχρὸν δ’ ἡγοῦμαι πρότερον παύσασθαι, πρὶν ἂν ὑμεῖς περὶ αὐτῶν ὅ τι ἂν βούλησθε ψηφίσησθε.", "st": "22.4"}, {"sp": "N", "t": "καὶ πρῶτον μὲν ἀνάβητε. εἰπὲ σὺ ἐμοί, μέτοικος εἶ; “ναί.” μετοικεῖς δὲ πότερον ὡς πεισόμενος τοῖς νόμοις τοῖς τῆς πόλεως, ἢ ὡς ποιήσων ὅ τι ἂν βούλῃ; “ὡς πεισόμενος.” ἄλλο τι οὖν ἢ ἀξιοῖς ἀποθανεῖν, εἴ τι πεποίηκας παρὰ τοὺς νόμους, ἐφ’ οἷς θάνατος ἡ ζημία; “ἔγωγε·” ἀπόκριναι δή μοι, εἰ ὁμολογεῖς πλείω σῖτον συμπρίασθαι πεντήκοντα φορμῶν, ὧν ὁ νόμος ἐξεῖναι κελεύει. “ἐγὼ τῶν ἀρχόντων κελευόντων συνεπριάμην.”", "st": "22.5"}, {"sp": "N", "t": "ἐὰν μὲν τοίνυν ἀποδείξῃ, ὦ ἄνδρες δικασταί, ὡς ἔστι νόμος ὃς κελεύει τοὺς σιτοπώλας συνωνεῖσθαι τὸν σῖτον, ἐὰν οἱ ἄρχοντες κελεύωσιν, ἀποψηφίσασθε· εἰ δὲ μή, δίκαιον ὑμᾶς καταψηφίσασθαι. ἡμεῖς γὰρ ὑμῖν παρεσχόμεθα τὸν νόμον, ὃς ἀπαγορεύει μηδένα τῶν ἐν τῇ πόλει πλείω σῖτον πεντήκοντα φορμῶν συνωνεῖσθαι.", "st": "22.6"}, {"sp": "N", "t": "χρῆν μὲν τοίνυν, ὦ ἄνδρες δικασταί, ἱκανὴν εἶναι ταύτην τὴν κατηγορίαν, ἐπειδὴ οὗτος μὲν ὁμολογεῖ συμπρίασθαι, ὁ δὲ νόμος ἀπαγορεύων φαίνεται, ὑμεῖς δὲ κατὰ τοὺς νόμους ὀμωμόκατε ψηφιεῖσθαι· ὅμως δ’ ἵνα πεισθῆτε ὅτι καὶ κατὰ τῶν ἀρχόντων ψεύδονται, ἀνάγκη καὶ μακρότερον εἰπεῖν περὶ αὐτῶν.", "st": "22.7"}, {"sp": "N", "t": "ἐπειδὴ γὰρ οὗτοι τὴν αἰτίαν εἰς ἐκείνους ἀνέφερον, παρακαλέσαντες τοὺς ἄρχοντας ἠρωτῶμεν. καὶ οἱ μὲν δύο οὐδὲν ἔφασαν εἰδέναι τοῦ πράγματος, Ἄνυτος δ’ ἔλεγεν ὡς τοῦ προτέρου χειμῶνος, ἐπειδὴ τίμιος ἦν ὁ σῖτος, τούτων ὑπερβαλλόντων ἀλλήλους καὶ πρὸς σφᾶς αὐτοὺς μαχομένων συμβουλεύσειεν αὐτοῖς παύσασθαι φιλονικοῦσιν, ἡγούμενος συμφέρειν ὑμῖν τοῖς παρὰ τούτων ὠνουμένοις ὡς ἀξιώτατον τούτους πρίασθαι· δεῖν γὰρ αὐτοὺς ὀβολῷ μόνον πωλεῖν τιμιώτερον.", "st": "22.8"}, {"sp": "N", "t": "ὡς τοίνυν οὐ συμπριαμένους καταθέσθαι ἐκέλευεν αὐτούς, ἀλλὰ μὴ ἀλλήλοις ἀντωνεῖσθαι συνεβούλευεν, αὐτὸν ὑμῖν Ἄνυτον μάρτυρα παρέξομαι.", "st": "22.9"}, {"sp": "N", "t": "<em>Μαρτυρία<\/em>", "st": "22.9"}, {"sp": "N", "t": "καὶ [ὡς] οὗτος μὲν ἐπὶ τῆς προτέρας βουλῆς τούτους εἶπε τοὺς λόγους, οὗτοι δ’ ἐπὶ τῆσδε συνωνούμενοι φαίνονται.", "st": "22.9"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὐχ ὑπὸ τῶν ἀρχόντων κελευσθέντες συνεπρίαντο τὸν σῖτον, ἀκηκόατε· ἡγοῦμαι δ’, ἐὰν ὡς μάλιστα περὶ τούτων ἀληθῆ λέγωσιν, οὐχ ὑπὲρ αὑτῶν αὐτοὺς ἀπολογήσεσθαι, ἀλλὰ τούτων κατηγορήσειν· περὶ γὰρ ὧν εἰσι νόμοι διαρρήδην γεγραμμένοι, πῶς οὐ χρὴ διδόναι δίκην καὶ τοὺς μὴ πειθομένους καὶ τοὺς κελεύοντας τούτοις τἀναντία πράττειν;", "st": "22.10"}, {"sp": "N", "t": "ἀλλὰ γάρ, ὦ ἄνδρες δικασταί, οἴομαι αὐτοὺς ἐπὶ μὲν τοῦτον τὸν λόγον οὐκ ἐλεύσεσθαι· ἴσως δ’ ἐροῦσιν, ὥσπερ καὶ ἐν τῇ βουλῇ, ὡς ἐπ’ εὐνοίᾳ τῆς πόλεως συνεωνοῦντο τὸν σῖτον, ἵν’ ὡς ἀξιώτατον ὑμῖν πωλοῖεν. μέγιστον δ’ ὑμῖν ἐρῶ καὶ περιφανέστατον τεκμήριον ὅτι ψεύδονται·", "st": "22.11"}, {"sp": "N", "t": "ἐχρῆν γὰρ αὐτούς, εἴπερ ὑμῶν ἕνεκα ἔπραττον ταῦτα, φαίνεσθαι τῆς αὐτῆς τιμῆς πολλὰς ἡμέρας πωλοῦντας, ἕως ὁ συνεωνημένος αὐτοὺς ἐπέλιπε· νῦν δ’ ἐνίοτε τῆς αὐτῆς ἡμέρας ἐπώλουν δραχμῇ τιμιώτερον, ὥσπερ κατὰ μέδιμνον συνωνούμενοι. καὶ τούτων ὑμᾶς μάρτυρας παρέχομαι.", "st": "22.12"}, {"sp": "N", "t": "δεινὸν δέ μοι δοκεῖ εἶναι, εἰ ὅταν μὲν εἰσφορὰν εἰσενεγκεῖν δέη, ἣν πάντες εἴσεσθαι μέλλουσιν, οὐκ ἐθέλουσιν, ἀλλὰ πενίαν προφασίζονται, ἐφ’ οἷς δὲ θάνατός ἐστιν ἡ ζημία καὶ λαθεῖν αὐτοῖς συνέφερε, ταῦτα ἐπ’ εὐνοίᾳ φασὶ τῇ ὑμετέρα παρανομῆσαι. καίτοι πάντες ἐπίστασθε ὅτι τούτοις ἥκιστα προσήκει τοιούτους ποιεῖσθαι λόγους.", "st": "22.13"}, {"sp": "N", "t": "τἀναντία γὰρ αὐτοῖς καὶ τοῖς ἄλλοις συμφέρει· τότε γὰρ πλεῖστα κερδαίνουσιν, ὅταν κακοῦ τινος ἀπαγγελθέντος τῇ πόλει τίμιον τὸν σῖτον πωλῶσιν. οὕτω δ’ ἄσμενοι τὰς συμφορὰς τὰς ὑμετέρας ὁρῶσιν, ὥστε τὰς μὲν πρότεροι τῶν ἄλλων πυνθάνονται, τὰς δ’ αὐτοὶ λογοποιοῦσιν, ἢ τὰς ναῦς διεφθάρθαι τὰς ἐν τῷ Πόντῳ ἢ ὑπὸ Λακεδαιμονίων ἐκπλεούσας συνειλῆφθαι, ἢ τὰ ἐμπόρια κεκλῇσθαι, ἢ τὰς σπονδὰς μέλλειν ἀπορρηθήσεσθαι, καὶ εἰς τοῦτ’ ἔχθρας ἐληλύθασιν,", "st": "22.14"}, {"sp": "N", "t": "ὥστ’ ἐν τοῖς αὐτοῖς καιροῖς ἐπιβουλεύουσιν ὑμῖν, ἐν οἷσπερ οἱ πολέμιοι. ὅταν γὰρ μάλιστα σίτου τυγχάνητε δεόμενοι, ἀναρπάζουσιν οὗτοι καὶ οὐκ ἐθέλουσι πωλεῖν, ἵνα μὴ περὶ τῆς τιμῆς διαφερώμεθα, ἀλλ’ ἀγαπῶμεν ἐὰν ὁποσουτινοσοῦν πριάμενοι παρ’ αὐτῶν ἀπέλθωμεν. ὥστ’ ἐνίοτε εἰρήνης οὔσης ὑπὸ τούτων πολιορκούμεθα.", "st": "22.15"}, {"sp": "N", "t": "οὕτω δὲ πάλαι περὶ τῆς τούτων πανουργίας καὶ κακονοίας ἡ πόλις ἔγνωκεν, ὥστ’ ἐπὶ μὲν τοῖς ἄλλοις ὠνίοις ἅπασι τοὺς ἀγορανόμους φύλακας κατεστήσατε, ἐπὶ δὲ ταύτῃ μόνῃ τῇ τέχνῃ χωρὶς σιτοφύλακας ἀποκληροῦτε· καὶ πολλάκις ἤδη παρ’ ἐκείνων πολιτῶν ὄντων δίκην τὴν μεγίστην ἐλάβετε, ὅτι οὐχ οἷοί τ’ ἦσαν τῆς τούτων πονηρίας ἐπικρατῆσαι. καίτοι τί χρὴ αὐτοὺς τοὺς ἀδικοῦντας ὑφ’ ὑμῶν πάσχειν, ὁπότε καὶ τοὺς οὐ δυναμένους φυλάττειν ἀποκτείνετε;", "st": "22.16"}, {"sp": "N", "t": "ἐνθυμεῖσθαι δὲ χρὴ ὅτι ἀδύνατον ὑμῖν ἐστιν ἀποψηφίσασθαι. εἰ γὰρ ἀπογνώσεσθε ὁμολογούντων αὐτῶν ἐπὶ τοὺς ἐμπόρους συνίστασθαι, δόξεθ’ ὑμεῖς ἐπιβουλεύειν τοῖς εἰσπλέουσιν. εἰ μὲν γὰρ ἄλλην τινὰ ἀπολογίαν ἐποιοῦντο, οὐδεὶς ἂν εἶχε τοῖς ἀποψηφισαμένοις ἐπιτιμᾶν· ἐφ’ ὑμῖν γὰρ ὁποτέροις βούλεσθε πιστεύειν· νῦν δὲ πῶς οὐ δεινὰ ἂν δόξαιτε ποιεῖν, εἰ τοὺς ὁμολογοῦντας παρανομεῖν ἀζημίους ἀφήσετε;", "st": "22.17"}, {"sp": "N", "t": "ἀναμνήσθητε δέ, ὦ ἄνδρες δικασταί, ὅτι πολλῶν ἤδη ἐχόντων ταύτην τὴν αἰτίαν, ἀρνουμένων δὲ καὶ μάρτυρας παρεχομένων, θάνατον κατέγνωτε, πιστοτέρους ἡγησάμενοι τοὺς τῶν κατηγόρων λόγους. καίτοι πῶς ἂν οὐ θαυμαστὸν εἴη, εἰ περὶ τῶν αὐτῶν ἁμαρτημάτων δικάζοντες μᾶλλον ἐπιθυμεῖτε παρὰ τῶν ἀρνουμένων δίκην λαμβάνειν;", "st": "22.18"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, πᾶσιν ἡγοῦμαι φανερὸν εἶναι ὅτι οἱ περὶ τῶν τοιούτων ἀγῶνες κοινότατοι τυγχάνουσιν ὄντες τοῖς ἐν τῇ πόλει, ὥστε πεύσονται ἥντινα γνώμην περὶ αὐτῶν ἔχετε, ἡγούμενοι, ἐὰν μὲν θάνατον τούτων καταγνῶτε, κοσμιωτέρους ἔσεσθαι τοὺς λοιπούς· ἐὰν δ’ ἀζημίους ἀφῆτε, πολλὴν ἄδειαν αὐτοῖς ἐψηφισμένοι ἔσεσθε ποιεῖν ὅ τι ἂν βούλωνται.", "st": "22.19"}, {"sp": "N", "t": "χρὴ δέ, ὦ ἄνδρες δικασταί, μὴ μόνον τῶν παρεληλυθότων ἕνεκα αὐτοὺς κολάζειν, ἀλλὰ καὶ παραδείγματος ἕνεκα τῶν μελλόντων ἔσεσθαι· οὕτω γὰρ ἔσονται μόγις ἀνεκτοί. ἐνθυμεῖσθε δὲ ὅτι ἐκ ταύτης τῆς τέχνης πλεῖστοι περὶ τοῦ σώματός εἰσιν ἠγωνισμένοι· καὶ οὕτω μεγάλα ἐξ αὐτῆς ὠφελοῦνται, ὥστε μᾶλλον αἱροῦνται καθ’ ἑκάστην ἡμέραν περὶ τῆς ψυχῆς κινδυνεύειν ἢ παύεσθαι παρ’ ὑμῶν ἀδίκως κερδαίνοντες.", "st": "22.20"}, {"sp": "N", "t": "καὶ μὲν δὴ οὐδ’ ἐὰν ἀντιβολῶσιν ὑμᾶς καὶ ἱκετεύωσι, δικαίως ἂν αὐτοὺς ἐλεήσαιτε, ἀλλὰ μᾶλλον τῶν τε πολιτῶν οἳ διὰ τὴν τούτων πονηρίαν ἀπέθνῃσκον, καὶ τοὺς ἐμπόρους ἐφ’ οὓς οὗτοι συνέστησαν· οἷς ὑμεῖς χαριεῖσθε καὶ προθυμοτέρους ποιήσετε, δίκην παρὰ τούτων λαμβάνοντες. εἰ δὲ μή, τίν’ αὐτοὺς οἴεσθε γνώμην ἕξειν, ἐπειδὰν πύθωνται ὅτι τῶν καπήλων οἳ τοῖς εἰσπλέουσιν ὡμολόγησαν ἐπιβουλεύειν, ἀπεψηφίσασθε;", "st": "22.21"}, {"sp": "N", "t": "οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· περὶ μὲν γὰρ τῶν ἄλλων τῶν ἀδικούντων, ὅτε δικάζονται, δεῖ παρὰ τῶν κατηγόρων πυθέσθαι, τὴν δὲ τούτων πονηρίαν ἅπαντες ἐπίστασθε. ἐὰν οὖν τούτων καταψηφίσησθε, τά τε δίκαια ποιήσετε καὶ ἀξιώτερον τὸν σῖτον ὠνήσεσθε· εἰ δὲ μή, τιμιώτερον.", "st": "22.22"}, {"sp": "HDR", "t": "ΚΓʹ. Κατὰ Παγκλέωνος ὅτι οὐκ ἦν Πλαταιεύς", "st": "23"}, {"sp": "N", "t": "πολλὰ μὲν λέγειν, ὦ ἄνδρες δικασταί, περὶ τουτουὶ τοῦ πράγματος οὔτ’ ἂν δυναίμην οὔτε μοι δοκεῖ δεῖν· ὡς δὲ ὀρθῶς τὴν δίκην ἔλαχον τουτῳὶ Παγκλέωνι οὐκ ὄντι Πλαταιεῖ, τοῦτο ὑμῖν πειράσομαι ἀποδεῖξαι.", "st": "23.1"}, {"sp": "N", "t": "ὡς γὰρ ἀδικῶν με πολὺν χρόνον οὐκ ἐπαύετο, ἐλθὼν ἐπὶ τὸ γναφεῖον, ἐν ᾧ εἰργάζετο, προσεκαλεσάμην αὐτὸν πρὸς τὸν πολέμαρχον, νομίζων μέτοικον εἶναι. εἰπόντος δὲ τούτου ὅτι Πλαταιεὺς εἴη, ἠρόμην ὁπόθεν δημοτεύοιτο, παραινέσαντός τινος τῶν παρόντων προσκαλέσασθαι καὶ πρὸς τὴν φυλήν, ἧστινος εἶναι σκήπτοιτο. ἐπειδὴ δὲ ἀπεκρίνατο ὅτι Δεκελειόθεν, προσκαλεσάμενος αὐτὸν καὶ πρὸς τοὺς τῇ Ἱπποθωντίδι δικάζοντας,", "st": "23.2"}, {"sp": "N", "t": "ἐλθὼν ἐπὶ τὸ κουρεῖον τὸ παρὰ τοὺς Ἑρμᾶς, οἷ Δεκελειεῖς προσφοιτῶσιν, ἠρώτων, οὕς τε ἐξευρίσκοιμι Δεκελειέων ἐπυνθανόμην εἴ τινα γιγνώσκοιεν Δεκελειόθεν δημοτευόμενον Παγκλέωνα. ἐπειδὴ δὲ οὐδεὶς ἔφασκεν γιγνώσκειν αὐτόν, πυθόμενος ὅτι καὶ ἑτέρας δίκας τὰς μὲν φεύγοι τὰς δ’ ὠφλήκοι παρὰ τῷ πολεμάρχῳ ἔλαχον καὶ ἐγώ.", "st": "23.3"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ὑμῖν Δεκελειέων οὓς ἠρόμην μάρτυρας παρέξομαι, ἔπειτα δὲ καὶ τῶν ἄλλων τῶν λαχόντων τε δίκας αὐτῷ πρὸς τὸν πολέμαρχον καὶ καταδικασαμένων, ὅσοι τυγχάνουσι παρόντες. καί μοι ἐπίλαβε τὸ ὕδωρ.", "st": "23.4"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "23.5"}, {"sp": "N", "t": "ἐκ μὲν τούτων πεισθεὶς πρὸς τὸν πολέμαρχον αὐτῶ· τὴν δίκην ἔλαχον· ἐπειδὴ δέ μοι αὐτὴν ἀντεγράψατο μὴ εἰσαγώγιμον εἶναι, περὶ πολλοῦ ποιούμενος μηδενὶ δόξαι ὑβρίζειν βούλεσθαι μᾶλλον ἢ δίκην λαβεῖν ὧν ἠδικήθην, πρῶτον μὲν Εὐθύκριτον, ὃν πρεσβύτατόν τε Πλαταιέων ἐγίγνωσκον καὶ μάλιστα ὠόμην εἰδέναι, ἠρόμην εἴ τινα γιγνώσκοι Ἱππαρμοδώρου ὑὸν Παγκλέωνα Πλαταιέα·", "st": "23.5"}, {"sp": "N", "t": "ἔπειτα δέ, ἐπειδὴ ἐκεῖνος ἀπεκρίνατό μοι ὅτι τὸν Ἱππαρμόδωρον μὲν γιγνώσκοι, ὑὸν δὲ ἐκείνῳ οὐδένα οὔτε Παγκλέωνα οὔτε ἄλλον οὐδένα εἰδείη ὄντα, ἠρώτων δὴ καὶ τῶν ἄλλων ὅσους ᾔδη Πλαταιέας ὄντας. πάντες οὖν ἀγνοοῦντες τὸ ὄνομα αὐτοῦ, ἀκριβέστατα ἂν ἔφασάν με πυθέσθαι ἐλθόντα εἰς τὸν χλωρὸν τυρὸν τῇ ἕνῃ καὶ νέα· ταύτῃ γὰρ τῇ ἡμέρᾳ τοῦ μηνὸς ἑκάστου ἐκεῖσε συλλέγεσθαι τοὺς Πλαταιέας.", "st": "23.6"}, {"sp": "N", "t": "ἐλθὼν οὖν εἰς τὸν τυρὸν ταύτῃ τῇ ἡμέρᾳ ἐπυνθανόμην αὐτῶν, εἴ τινα γιγνώσκοιεν Παγκλέωνα πολίτην σφέτερον. καὶ οἱ μὲν ἄλλοι οὐκ ἔφασαν γιγνώσκειν, εἷς δέ τις εἶπεν ὅτι τῶν μὲν πολιτῶν οὐδενὶ εἰδείη τοῦτο ὂν τὸ ὄνομα, δοῦλον μέντοι ἔφη ἑαυτοῦ ἀφεστῶτα εἶναι Παγκλέωνα,", "st": "23.7"}, {"sp": "N", "t": "τήν τε ἡλικίαν λέγων τὴν τούτου καὶ τὴν τέχνην ᾗ οὗτος χρῆται. ταῦτ’ οὖν ὡς ἀληθῆ ἐστι, τόν τε Εὐθύκριτον, ὃν πρῶτον ἠρόμην, καὶ τῶν ἄλλων Πλαταιέων ὅσοις προσῆλθον, καὶ τὸν ὃς ἔφη δεσπότης τούτου εἶναι, μάρτυρας παρέξομαι. καί μοι ἐπίλαβε τὸ ὕδωρ.", "st": "23.8"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "23.9"}, {"sp": "N", "t": "ἡμέραις τοίνυν μετὰ ταῦτα οὐ πολλαῖς ὕστερον ἰδὼν ἀγόμενον τουτονὶ Παγκλέωνα ὑπὸ Νικομήδους, ὃς ἐμαρτύρησεν αὐτοῦ δεσπότης εἶναι, προσῆλθον βουλόμενος εἰδέναι ὁποῖόν τι περὶ αὐτοῦ πραχθήσοιτο. τότε μὲν οὖν ἐπειδὴ ἐπαύσαντο μαχόμενοι, εἶπόν τινες τῶν τούτων παρόντων ὅτι εἴη αὐτῷ ἀδελφὸς ὃς ἐξαιρήσοιτο αὐτὸν εἰς ἐλευθερίαν·", "st": "23.9"}, {"sp": "N", "t": "ἐπὶ τούτοις ἐγγυησάμενοι παρέξειν εἰς αὔριον ᾤχοντο ἀπιόντες. τῇ δ’ ὑστεραίᾳ τῆς τε ἀντιγραφῆς ἕνεκα ταυτησὶ καὶ αὐτῆς τῆς δίκης ἔδοξέ μοι χρῆναι μάρτυρας λαβόντι παραγενέσθαι, ἵν’ εἰδείην τόν τ’ ἐξαιρησόμενον αὐτὸν καὶ ὅ τι λέγων ἀφαιρήσοιτο. ἐφ’ οἷς μὲν οὖν ἐξηγγυήθη, οὔτε ἀδελφὸς οὔτε ἄλλος οὐδεὶς ἦλθε, γυνὴ δὲ φάσκουσα αὑτῆς αὐτὸν εἶναι δοῦλον, ἀμφισβητοῦσα τῷ Νικομήδει,", "st": "23.10"}, {"sp": "N", "t": "καὶ οὐκ ἔφη ἐάσειν αὐτὸν ἄγειν. ὅσα μὲν οὖν αὐτόθι ἐρρήθη, πολὺς ἂν εἴη μοι λόγος διηγεῖσθαι· εἰς τοῦτο δὲ βιαιότητος ἦλθον οἵ τε παρόντες τούτῳ καὶ αὐτὸς οὗτος, ὥστε ἐθέλοντος μὲν τοῦ Νικομήδους ἐθελούσης δὲ τῆς γυναικὸς ἀφιέναι, εἴ τις ἢ εἰς ἐλευθερίαν τοῦτον ⟨ἀφαιροῖτο⟩ ἢ ἄγοι φάσκων ἑαυτοῦ δοῦλον εἶναι, τούτων οὐδὲν ποιήσαντες ἀφελόμενοι ᾤχοντο. ὡς οὖν τῇ τε προτεραίᾳ ἐπὶ τούτοις ἐξηγγυήθη καὶ τότε βίᾳ ᾤχοντο ἀφελόμενοι αὐτόν, μάρτυρας παρέξομαι ὑμῖν. καί μοι ἐπίλαβε τὸ ὕδωρ.", "st": "23.11"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "23.12"}, {"sp": "N", "t": "ῥᾴδιον τοίνυν εἰδέναι ὅτι οὐδ’ αὐτὸς Παγκλέων νομίζει ἑαυτὸν μὴ ὅτι Πλαταιέα εἶναι, ἀλλ’ οὐδ’ ἐλεύθερον. ὅστις γὰρ ἐβουλήθη βίᾳ ἀφαιρεθεὶς ἐνόχους καταστῆσαι τοὺς ἑαυτοῦ ἐπιτηδείους τοῖς βιαίοις μᾶλλον ἢ κατὰ τοὺς νόμους εἰς τὴν ἐλευθερίαν ἐξαιρεθεὶς δίκην λαβεῖν παρὰ τῶν ἀγόντων αὐτόν, οὐδενὶ χαλεπὸν γνῶναι ὅτι εὖ εἰδὼς ἑαυτὸν ὄντα δοῦλον ἔδεισεν ἐγγυητὰς καταστήσας περὶ τοῦ σώματος ἀγωνίσασθαι.", "st": "23.12"}, {"sp": "N", "t": "ὅτι μὲν οὖν Πλαταιεὺς εἶναι πολλοῦ δεῖ, οἶμαι ὑμᾶς ἐκ τούτων σχεδόν τι γιγνώσκειν· ὅτι δὲ οὐδ’ ⟨αὐτὸς⟩ οὗτος, ὃς ἄριστα οἶδε τὰ αὑτοῦ, ἡγήσατο δόξαι ἂν ὑμῖν Πλαταιεὺς εἶναι, ἐξ ὧν ἔραξε ῥαδίως μαθήσεσθε. ἐν τῇ ἀντωμοσία γὰρ τῆς δίκης ἣν αὐτῷ ἔλαχεν Ἀριστόδικος οὑτοσί, ἀμφισβητῶν", "st": "23.13"}, {"sp": "N", "t": "μὴ πρὸς τὸν πολέμαρχον εἶναί οἱ τὰς δίκας διεμαρτυρήθη μὴ Πλαταιεὺς εἶναι. ἐπισκηψάμενος δὲ τῷ μάρτυρι οὐκ ἐπεξῆλθεν, ἀλλ’ εἴασε καταδικάσασθαι αὐτοῦ τὸν Ἀριστόδικον. ἐπεὶ δὲ ὑπερήμερος ἐγένετο, ἐξέτισε τὴν δίκην, καθ’ ὅτι ἔπειθε. καὶ τούτων, ὡς ἀληθῆ ἐστι, μάρτυρας ἐγὼ παρέξομαι ὑμῖν. καί μοι ἐπίλαβε τὸ ὕδωρ.", "st": "23.14"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "23.15"}, {"sp": "N", "t": "πρὶν τοίνυν ταῦτα ὁμολογηθῆναι αὐτῶ, δεδιὼς τὸν Ἀριστόδικον μεταστὰς ἐντεῦθεν Θήβησι μετῴκει. καίτοι οἶμαι εἰδέναι ὑμᾶς ὅτι εἴπερ ἦν Πλαταιεύς, πανταχοῦ μᾶλλον ἢ Θήβησιν εἰκὸς ἦν αὐτὸν μετοικῆσαι. ὡς οὖν ᾤκει ⟨ἐκεῖ⟩ πολὺν χρόνον, τούτων ὑμῖν μάρτυρας παρέξομαι. καί μοι ἐπίλαβε τὸ ὕδωρ.", "st": "23.15"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "23.16"}, {"sp": "N", "t": "ἐξαρκεῖν μοι νομίζω τὰ εἰρημένα, ὦ ἄνδρες δικασταί· ἐὰν γὰρ διαμνημονεύητε, οἶδ’ ὅτι τά τε δίκαια καὶ τἀληθῆ ψηφιεῖσθε, ἃ καὶ ἐγὼ ὑμῶν δέομαι.", "st": "23.16"}, {"sp": "HDR", "t": "ΚΔʹ. Πρὸς τὴν εἰσαγγελίαν περὶ τοῦ μὴ δίδοσθαι τῷ ἀδυνάτῳ ἀργύριον", "st": "24"}, {"sp": "N", "t": "οὐ πολλοῦ δέω χάριν ἔχειν, ὦ βουλή, τῷ κατηγόρῳ, ὅτι μοι παρεσκεύασε τὸν ἀγῶνα τουτονί. πρότερον γὰρ οὐκ ἔχων πρόφασιν ἐφ’ ἧς τοῦ βίου λόγον δοίην, νυνὶ διὰ τοῦτον εἴληφα. καὶ πειράσομαι τῷ λόγῳ τοῦτον μὲν ἐπιδεῖξαι ψευδόμενον, ἐμαυτὸν δὲ βεβιωκότα μέχρι τῆσδε τῆς ἡμέρας ἐπαίνου μᾶλλον ἄξιον ἤ φθόνου· διὰ γὰρ οὐδὲν ἄλλο μοι δοκεῖ παρασκευάσαι τόνδε μοι τὸν κίνδυνον οὗτος ἢ διὰ φθόνον.", "st": "24.1"}, {"sp": "N", "t": "καίτοι ὅστις τούτοις φθονεῖ οὓς οἱ ἄλλοι ἐλεοῦσι, τίνος ἂν ὑμῖν ὁ τοιοῦτος ἀποσχέσθαι δοκεῖ πονηρίας; εἰ μὲν γὰρ ἕνεκα χρημάτων με συκοφαντεῖ —· εἰ δ’ ὡς ἐχθρὸν ἑαυτοῦ με τιμωρεῖται, ψεύδεται· διὰ γὰρ τὴν πονηρίαν αὐτοῦ οὔτε φίλῳ οὔτε ἐχθρῷ πώποτε ἐχρησάμην αὐτῶ.", "st": "24.2"}, {"sp": "N", "t": "ἤδη τοίνυν, ὦ βουλή, δῆλός ἐστι φθονῶν, ὅτι τοιαύτῃ κεχρημένος συμφορᾷ τούτου βελτίων εἰμὶ πολίτης. καὶ γὰρ οἶμαι δεῖν, ὦ βουλή, τὰ τοῦ σώματος δυστυχήματα τοῖς τῆς ψυχῆς ἐπιτηδεύμασιν ἰᾶσθαι, [καλῶς]. εἰ γὰρ ἐξ ἴσου τῇ συμφορᾷ καὶ τὴν διάνοιαν ἕξω καὶ τὸν ἄλλον βίον διάξω, τί τούτου διοίσω;", "st": "24.3"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων τοσαῦτά μοι εἰρήσθω· ὑπὲρ ὧν δέ μοι προσήκει λέγειν, ὡς ἂν οἷόν τε διὰ βραχυτάτων ἐρῶ. φησὶ γὰρ ὁ κατήγορος οὐ δικαίως με λαμβάνειν τὸ παρὰ τῆς πόλεως ἀργύριον· καὶ γὰρ τῷ σώματι δύνασθαι καὶ οὐκ εἶναι τῶν ἀδυνάτων, καὶ τέχνην ἐπίστασθαι τοιαύτην ὥστε καὶ ἄνευ τοῦ διδομένου τούτου ζῆν.", "st": "24.4"}, {"sp": "N", "t": "καὶ τεκμηρίοις χρῆται τῆς μὲν τοῦ σώματος ῥώμης, ὅτι ἐπὶ τοὺς ἵππους ἀναβαίνω, τῆς δ’ ἐν τῇ τέχνῃ εὐπορίας, ὅτι δύναμαι συνεῖναι δυναμένοις ἀνθρώποις ἀναλίσκειν. τὴν μὲν οὖν ἐκ τῆς τέχνης εὐπορίαν καὶ τὸν ἄλλον τὸν ἐμὸν βίον, οἷος τυγχάνει, πάντας ὑμᾶς οἴμαι γιγνώσκειν· ὅμως δὲ κἀγὼ διὰ βραχέων ἐρῶ.", "st": "24.5"}, {"sp": "N", "t": "ἐμοὶ γὰρ ὁ μὲν πατὴρ κατέλιπεν οὐδέν, τὴν δὲ μητέρα τελευτήσασαν πέπαυμαι τρέφων τρίτον ἔτος τουτί, παῖδες δέ μοι οὔπω εἰσὶν οἵ με θεραπεύσουσι. τέχνην δὲ κέκτημαι βραχέα δυναμένην ὠφελεῖν, ἣν αὐτὸς μὲν ἤδη χαλεπῶς ἐργάζομαι, τὸν διαδεξόμενον δ’ αὐτὴν οὔπω δύναμαι κτήσασθαι. πρόσοδος δέ μοι οὐκ ἔστιν ἄλλη πλὴν ταύτης, ἣν ἂν ἀφέλησθέ με, κινδυνεύσαιμ’ ἂν ὑπὸ τῇ δυσχερεστάτῃ γενέσθαι τύχῃ. μὴ τοίνυν,", "st": "24.6"}, {"sp": "N", "t": "ἐπειδή γε ἔστιν, ὦ βουλή, σῶσαί με δικαίως, ἀπολέσητε ἀδίκως· μηδὲ ἃ νεωτέρῳ καὶ μᾶλλον ἐρρωμένῳ ὄντι ἔδοτε, πρεσβύτερον καὶ ἀσθενέστερον γιγνόμενον ἀφέλησθε· μηδὲ πρότερον καὶ περὶ τοὺς οὐδὲν ἔχοντας κακὸν ἐλεημονέστατοι δοκοῦντες εἶναι νυνὶ διὰ τοῦτον τοὺς καὶ τοῖς ἐχθροῖς ἐλεινοὺς ὄντας ἀγρίως ἀποδέξησθε· μηδ’ ἐμὲ τολμήσαντες ἀδικῆσαι καὶ τοὺς ἄλλους τοὺς ὁμοίως ἐμοὶ διακειμένους ἀθυμῆσαι ποιήσητε.", "st": "24.7"}, {"sp": "N", "t": "καὶ γὰρ ἂν ἄτοπον εἴη, ὦ βουλή, εἰ ὅτε μὲν ἁπλῆ μοι ἦν ἡ συμφορά, τότε μὲν φαινοίμην λαμβάνων τὸ ἀργύριον τοῦτο, νῦν δ’ ἐπειδὴ καὶ γῆρας καὶ νόσοι καὶ τὰ τούτοις ἑπόμενα κακὰ προσγίγνεταί μοι, τότε ἀφαιρεθείην.", "st": "24.8"}, {"sp": "N", "t": "δοκεῖ δέ μοι τῆς πενίας τῆς ἐμῆς τὸ μέγεθος ὁ κατήγορος ἂν ἐπιδεῖξαι σαφέστατα μόνος ἀνθρώπων. εἰ γὰρ ἐγὼ κατασταθεὶς χορηγὸς τραγῳδοῖς προκαλεσαίμην αὐτὸν εἰς ἀντίδοσιν, δεκάκις ἂν ἕλοιτο χορηγῆσαι μᾶλλον ἢ ἀντιδοῦναι ἅπαξ. καὶ πῶς οὐ δεινόν ἐστι νῦν μὲν κατηγορεῖν ὡς διὰ πολλὴν εὐπορίαν ἐξ ἴσου δύναμαι συνεῖναι τοῖς πλουσιωτάτοις, εἰ δὲ ὧν ἐγὼ λέγω τύχοι τι γενόμενον, τοιοῦτον εἶναι; καὶ τί πονηρότερον;", "st": "24.9"}, {"sp": "N", "t": "περὶ δὲ τῆς ἐμῆς ἱππικῆς, ἧς οὗτος ἐτόλμησε μνησθῆναι πρὸς ὑμᾶς, οὔτε τὴν τύχην δείσας οὔτε ὑμᾶς αἰσχυνθείς, οὐ πολὺς ὁ λόγος. ἐγὼ γὰρ, ὦ βουλή, πάντας οἶμαι τοὺς ἔχοντάς τι δυστύχημα τοῦτο ζητεῖν καὶ τοῦτο φιλοσοφεῖν, ὅπως ὡς ἀλυπότατα μεταχειριοῦνται τὸ συμβεβηκὸς πάθος. ὧν εἷς ἐγώ, καὶ περιπεπτωκὼς τοιαύτῃ συμφορᾷ ταύτην ἐμαυτῷ ῥᾳστώνην ἐξηῦρον εἰς τὰς ὁδοὺς τὰς μακροτέρας τῶν ἀναγκαίων.", "st": "24.10"}, {"sp": "N", "t": "ὃ δὲ μέγιστον, ὦ βουλή, τεκμήριον ὅτι διὰ τὴν συμφορὰν ἀλλ’ οὐ διὰ τὴν ὕβριν, ὡς οὗτός φησιν, ἐπὶ τοὺς ἵππους ἀναβαίνω [ῥᾴδιόν ἐστι μαθεῖν]· εἰ γὰρ ἐκεκτήμην οὐσίαν, ἐπ’ ἀστράβης ἂν ὠχούμην, ἀλλ’ οὐκ ἐπὶ τοὺς ἀλλοτρίους ἵππους ἀνέβαινον· νυνὶ δ’ ἐπειδὴ τοιοῦτον οὐ δύναμαι κτήσασθαι, τοῖς ἀλλοτρίοις ἵπποις ἀναγκάζομαι χρῆσθαι πολλάκις.", "st": "24.11"}, {"sp": "N", "t": "καίτοι πῶς οὐκ ἄτοπόν ἐστιν, ὦ βουλή, τοῦτον ἄν, εἰ μὲν ἐπ’ ἀστράβης ὀχούμενον ἑώρα με, σιωπᾶν (τί γὰρ ἂν καὶ ἔλεγεν;), ὅτι δ’ ἐπὶ τοὺς ᾐτημένους ἵππους ἀναβαίνω, πειρᾶσθαι πείθειν ὑμᾶς ὡς δυνατός εἰμι; καὶ ὅτι μὲν δυοῖν βακτηρίαιν χρῶμαι, τῶν ἄλλων μιᾷ χρωμένων, μὴ κατηγορεῖν ὡς καὶ τοῦτο τῶν δυναμένων ἐστιν· ὅτι δ’ ἐπὶ τοὺς ἵππους ἀναβαίνω, τεκμηρίῳ χρῆσθαι πρὸς ὑμᾶς ὡς εἰμὶ τῶν δυναμένων; οἷς ἐγώ διὰ τὴν αὐτὴν αἰτίαν ἀμφοτέροις χρῶμαι.", "st": "24.12"}, {"sp": "N", "t": "τοσοῦτον δὲ διενήνοχεν ἀναισχυντίᾳ τῶν ἁπάντων ἀνθρώπων, ὥστε ὑμᾶς πειρᾶται πείθειν, τοσούτους ὄντας εἵς ὤν, ὡς οὐκ εἰμὶ τῶν ἀδυνάτων ἐγώ. καίτοι εἰ τοῦτο πείσει τινὰς ὑμῶν, ὦ βουλή, τί με κωλύει κληροῦσθαι τῶν ἐννέα ἀρχόντων, καὶ ὑμᾶς ἐμοῦ μὲν ἀφελέσθαι τὸν ὀβολὸν ὡς ὑγιαίνοντος, τούτῳ δὲ ψηφίσασθαι πάντας ὡς ἀναπήρῳ; οὐ γὰρ δήπου τὸν αὐτὸν ὑμεῖς μὲν ὡς δυνάμενον ἀφαιρήσεσθε τὸ διδόμενον, οἱ δὲ ⟨θεσμοθέται⟩ ὡς ἀδύνατον ὄντα κληροῦσθαι κωλύσουσιν.", "st": "24.13"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὔτε ὑμεῖς τούτῳ τὴν αὐτὴν ἔχετε γνώμην, οὔθ’ οὗτος εὖ ποιῶν. ὁ μὲν γὰρ ὥσπερ ἐπικλήρου τῆς συμφορᾶς οὔσης ἀμφισβητήσων ἥκει καὶ πειρᾶται πείθειν ὑμᾶς ὡς οὐκ εἰμὶ τοιοῦτος οἷον ὑμεῖς ὁρᾶτε πάντες· ὑμεῖς δὲ (ὃ τῶν εὖ φρονούντων ἔργον ἐστί) μᾶλλον πιστεύετε τοῖς ὑμετέροις αὐτῶν ὀφθαλμοῖς ἢ τοῖς τούτου λόγοις.", "st": "24.14"}, {"sp": "N", "t": "λέγει δ’ ὡς ὑβριστής εἰμι καὶ βίαιος καὶ λίαν ἀσελγῶς διακείμενος, ὥσπερ εἰ φοβερῶς ὀνομάσειε, μέλλων ἀληθῆ λέγειν, ἀλλ’ οὐκ, ἐὰν πάνυ πραόνως [μηδὲ ψεύδηται], ταῦτα ποιήσων. ἐγὼ δ’ ὑμᾶς, ὦ βουλή, σαφῶς οἶμαι δεῖν διαγιγνώσκειν οἷς τ’ ἐγχωρεῖ τῶν ἀνθρώπων ὑβρισταῖς εἶναι καὶ οἷς οὐ προσήκει.", "st": "24.15"}, {"sp": "N", "t": "οὐ γὰρ ⟨τοὺς⟩ πενομένους καὶ λίαν ἀπόρως διακειμένους ὑβρίζειν εἰκός, ἀλλὰ τοὺς πολλῷ πλείω τῶν ἀναγκαίων κεκτημένους· οὐδὲ τοὺς ἀδυνάτους τοῖς σώμασιν ὄντας, ἀλλὰ τοὺς μάλιστα πιστεύοντας ταῖς αὑτῶν ῥώμαις· οὐδὲ τοὺς ἤδη προβεβηκότας τῇ ἡλικίᾳ, ἀλλὰ τοὺς ἔτι νέους καὶ νέαις ταῖς διανοίαις χρωμένους.", "st": "24.16"}, {"sp": "N", "t": "οἱ μὲν γὰρ πλούσιοι τοῖς χρήμασιν ἐξωνοῦνται τοὺς κινδύνους, οἱ δὲ πένητες ὑπὸ τῆς παρούσης ἀπορίας σωφρονεῖν ἀναγκάζονται· καὶ οἱ μὲν νέοι συγγνώμης ἀξιοῦνται τυγχάνειν παρὰ τῶν πρεσβυτέρων, τοῖς δὲ πρεσβυτέροις ἐξαμαρτάνουσιν ὁμοίως ἐπιτιμῶσιν ἀμφότεροι·", "st": "24.17"}, {"sp": "N", "t": "καὶ τοῖς μὲν ἰσχυροῖς ἐγχωρεῖ μηδὲν αὐτοῖς πάσχουσιν, οὓς ἂν βουληθῶσιν, ὑβρίζειν, τοῖς δὲ ἀσθενέσιν οὐκ ἔστιν οὔτε ὑβριζομένοις ἀμύνεσθαι τοὺς ὑπάρξαντας οὔτε ὑβρίζειν βουλομένοις περιγίγνεσθαι τῶν ἀδικουμένων. ὥστε μοι δοκεῖ ὁ κατήγορος εἰπεῖν περὶ τῆς ἐμῆς ὕβρεως οὐ σπουδάζων, ἀλλὰ παίζων, οὐδ’ ὑμᾶς πεῖσαι βουλόμενος ὡς εἰμὶ τοιοῦτος, ἀλλ’ ἐμὲ κωμῳδεῖν βουλόμενος, ὥσπερ τι καλὸν ποιῶν.", "st": "24.18"}, {"sp": "N", "t": "ἔτι δὲ καὶ συλλέγεσθαί φησιν ἀνθρώπους ὡς ἐμὲ πονηροὺς καὶ πολλούς, οἳ τὰ μὲν ἑαυτῶν ἀνηλώκασι, τοῖς δὲ τὰ σφέτερα σῴζειν βουλομένοις ἐπιβουλεύουσιν. ὑμεῖς δὲ ἐνθυμήθητε πάντες ὅτι ταῦτα λέγων οὐδὲν ἐμοῦ κατηγορεῖ μᾶλλον ἢ τῶν ἄλλων ὅσοι τέχνας ἔχουσιν οὐδὲ τῶν ὡς ἐμὲ εἰσιόντων μᾶλλον ἢ τῶν ὡς τοὺς ἄλλους δημιουργούς.", "st": "24.19"}, {"sp": "N", "t": "ἕκαστος γὰρ ὑμῶν εἴθισται προσφοιτᾶν ὁ μὲν πρὸς μυροπώλιον, ὁ δὲ πρὸς κουρεῖον, ὁ δὲ πρὸς σκυτοτομεῖον, ὁ δ’ ὅποι ἂν τύχῃ, καὶ πλεῖστοι μὲν ὡς τοὺς ἐγγυτάτω τῆς ἀγορᾶς κατεσκευασμένους, ἐλάχιστοι δὲ ὡς τοὺς πλεῖστον ἀπέχοντας αὐτῆς· ὥστ’ εἴ τις ὑμῶν πονηρίαν καταγνώσεται τῶν ὡς ἐμὲ εἰσιόντων, δῆλον ὅτι καὶ τῶν παρὰ τοῖς ἄλλοις διατριβόντων· εἰ δὲ κἀκείνων, ἁπάντων Ἀθηναίων· ἅπαντες γὰρ εἴθισθε προσφοιτᾶν καὶ διατρίβειν ἁμοῦ γέ που.", "st": "24.20"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ οἶδ’ ὅ τι δεῖ λίαν με ἀκριβῶς ἀπολογούμενον πρὸς ἓν ἕκαστον ὑμῖν τῶν εἰρημένων ἐνοχλεῖν πλείω χρόνον. εἰ γὰρ ὑπὲρ τῶν μεγίστων εἴρηκα, τί δεῖ περὶ τῶν φαύλων ὁμοίως τούτῳ σπουδάζειν; ἐγὼ δ’ ὑμῶν, ὦ βουλή, δέομαι πάντων τὴν αὐτὴν ἔχειν περὶ ἐμοῦ διάνοιαν, ἥνπερ καὶ πρότερον.", "st": "24.21"}, {"sp": "N", "t": "μηδ’ οὗ μόνου μεταλαβεῖν ἔδωκεν ἡ μοι τῶν ἐν τῇ πατρίδι, τούτου διὰ τουτονὶ ἀποστερήσητέ με· μηδ’ ἃ πάλαι κοινῇ πάντες ἔδοτέ μοι, νῦν οὗτος εἷς ὢν πείσῃ πάλιν ὑμᾶς ἀφελέσθαι. ἐπειδὴ γὰρ, ὦ βουλή, τῶν μεγίστων [ἀρχῶν] ὁ δαίμων ἀπεστέρησεν ἡμᾶς, ἡ πόλις ἡμῖν ἐψηφίσατο τοῦτο τὸ ἀργύριον, ἡγουμένη κοινὰς εἶναι τὰς τύχας τοῖς ἅπασι καὶ τῶν κακῶν καὶ τῶν ἀγαθῶν.", "st": "24.22"}, {"sp": "N", "t": "πῶς οὖν οὐκ ἂν δειλαιότατος εἴην, εἰ τῶν μὲν καλλίστων καὶ μεγίστων διὰ τὴν συμφορὰν ἀπεστερημένος εἴην, ἃ δ’ ἡ πόλις ἔδωκε προνοηθεῖσα τῶν οὕτως διακειμένων, διὰ τὸν κατήγορον ἀφαιρεθείην; μηδαμῶς, ὦ βουλή, ταύτῃ θῆσθε τὴν ψῆφον. διὰ τί γὰρ ἂν καὶ τύχοιμι τοιούτων ὑμῶν;", "st": "24.23"}, {"sp": "N", "t": "πότερον ὅτι δι’ ἐμέ τις εἰς ἀγῶνα πώποτε καταστὰς ἀπώλεσε τὴν οὐσίαν; ἀλλ’ οὐδ’ ἂν εἷς ἀποδείξειεν. ἀλλ’ ὅτι πολυπράγμων εἰμὶ καὶ θρασὺς καὶ φιλαπεχθήμων;", "st": "24.24"}, {"sp": "N", "t": "ἀλλ’ οὐ τοιαύταις ἀφορμαῖς τοῦ βίου πρὸς τὰ τοιαῦτα τυγχάνω χρώμενος. ἀλλ’ ὅτι λίαν ὑβριστὴς καὶ βίαιος; ἀλλ’ οὐδ’ ἂν αὐτὸς φήσειεν, εἰ μὴ βούλοιτο καὶ τοῦτο ψεύδεσθαι τοῖς ἄλλοις ὁμοίως. ἀλλ’ ὅτι ἐπὶ τῶν τριάκοντα γενόμενος ἐν δυνάμει κακῶς ἐποίησα πολλοὺς τῶν πολιτῶν; ἀλλὰ μετὰ τοῦ ὑμετέρου πλήθους ἔφυγον εἰς Χαλκίδα [τὴν ἐπ’ Εὐρίπῳ], καὶ ἐξόν μοι μετ’ ἐκείνων ἀδεῶς πολιτεύεσθαι, μεθ’ ὑμῶν εἱλόμην κινδυνεύειν ἀπελθών.", "st": "24.25"}, {"sp": "N", "t": "μὴ τοίνυν, ὦ βουλή, μηδὲν ἡμαρτηκὼς ὁμοίων ὑμῶν τύχοιμι τοῖς πολλὰ ἠδικηκόσιν, ἀλλὰ τὴν αὐτὴν ψῆφον θέσθε περὶ ἐμοῦ ταῖς ἄλλαις βουλαῖς, ἀναμνησθέντες ὅτι οὔτε χρήματα διαχειρίσας τῆς πόλεως δίδωμι λόγον αὐτῶν, οὔτε ἀρχὴν ἄρξας οὐδεμίαν εὐθύνας ὑπέχω νῦν αὐτῆς, ἀλλὰ περὶ ὀβολοῦ μόνον ποιοῦμαι τοὺς λόγους.", "st": "24.26"}, {"sp": "N", "t": "καὶ οὕτως ὑμεῖς μὲν τὰ δίκαια γνώσεσθε πάντες, ἐγὼ δὲ τούτων ὑμῖν τυχὼν ἕξω τὴν χάριν, οὗτος δὲ τοῦ λοιποῦ μαθήσεται μὴ τοῖς ἀσθενεστέροις ἐπιβουλεύειν ἀλλὰ τῶν ὁμοίων αὐτῷ περιγίγνεσθαι.", "st": "24.27"}, {"sp": "HDR", "t": "ΚΕʹ. Δήμου καταλύσεως ἀπολογία", "st": "25"}, {"sp": "N", "t": "ὑμῖν μὲν πολλὴν συγγνώμην ἔχω, ὦ ἄνδρες δικασταί, ἀκούουσι τοιούτων λόγων καὶ ἀναμιμνῃσκομένοις τῶν γεγενημένων, ὁμοίως ἅπασιν ὀργίζεσθαι τοῖς ἐν ἄστει μείνασι· τῶν δὲ κατηγόρων θαυμάζω, οἳ ἀμελοῦντες τῶν οἰκείων τῶν ἀλλοτρίων ἐπιμέλονται, εἰ σαφῶς εἰδότες τοὺς μηδὲ ἀδικοῦντας καὶ τοὺς πολλὰ ἐξημαρτηκότας ζητοῦσι [κερδαίνειν ἢ] ὑμᾶς πείθειν περὶ ἁπάντων ἡμῶν τὴν γνώμην ταύτην ἔχειν.", "st": "25.1"}, {"sp": "N", "t": "εἰ μὲν οὖν οἴονται, ὅσα ὑπὸ τῶν τριάκοντα γεγένηται τῇ πόλει, ἐμοῦ κατηγορηκέναι, ἀδυνάτους αὐτοὺς ἡγοῦμαι λέγειν· οὐδὲ γὰρ πολλοστὸν μέρος τῶν ἐκείνοις πεπραγμένων εἰρήκασιν· εἰ δὲ ὡς ἐμοί τι προσῆκον περὶ αὐτῶν ποιοῦνται τοὺς λόγους, ἀποδείξω τούτους μὲν ἅπαντα ψευδομένους, ἐμαυτὸν δὲ τοιοῦτον ὄντα οἷόσπερ ἂν τῶν ἐκ Πειραιῶς ⟨ὁ⟩ βέλτιστος ἐν ἄστει μείνας ἐγένετο.", "st": "25.2"}, {"sp": "N", "t": "δέομαι δ’ ὑμῶν, ὦ ἄνδρες δικασταί, μὴ τὴν αὐτὴν γνώμην ἔχειν τοῖς συκοφάνταις. τούτων μὲν γὰρ ἔργον ἐστὶ καὶ τοὺς μηδὲν ἡμαρτηκότας εἰς αἰτίαν καθιστάναι (ἐκ τούτων γὰρ ἂν μάλιστα χρηματίζοιντο), ὑμέτερον δὲ τοῖς μηδὲν ἀδικοῦσιν ἐξ ἴσου τῆς πολιτείας μεταδιδόναι· οὕτω γὰρ ἂν τοῖς καθεστηκόσι πράγμασι πλείστους συμμάχους ἔχοιτε.", "st": "25.3"}, {"sp": "N", "t": "ἀξιῶ δέ ὦ ἄνδρες δικασταί, ἐάνπερ φανῶ συμφορᾶς μὲν μηδεμιᾶς αἴτιος γεγενημένος, πολλὰ δὲ κἀγαθὰ εἰργασμένος τὴν πόλιν καὶ τῷ σώματι καὶ τοῖς χρήμασι, ταῦτα γοῦν μοι παρ’ ὑμῶν ὑπάρχειν, ὧν οὐ μόνον τοὺς εὖ πεποιηκότας ἀλλὰ καὶ τοὺς μηδὲν ἀδικοῦντας τυγχάνειν δίκαιόν ἐστι. μέγα μὲν οὗν ἡγοῦμαί ⟨μοι⟩ τεκμήριον εἶναι,", "st": "25.4"}, {"sp": "N", "t": "ὅτι, εἴπερ ἐδύναντο οἱ κατήγοροι ἰδίᾳ με ἀδικοῦντα ἐξελέγξαι, οὐκ ἂν τὰ τῶν τριάκοντα ἁμαρτήματα ἐμοῦ κατηγόρουν, οὐδ’ ἂν ᾤοντο χρῆναι ὑπὲρ τῶν ἐκείνοις πεπραγμένων ἑτέρους διαβάλλειν, ἀλλ’ αὐτοὺς τοὺς ἀδικοῦντας τιμωρεῖσθαι· νῦν δὲ νομίζουσι τὴν πρὸς ἐκείνους ὀργὴν ἱκανὴν εἶναι καὶ τοὺς μηδὲν κακὸν εἰργασμένους ἀπολέσαι.", "st": "25.5"}, {"sp": "N", "t": "ἐγὼ δὲ οὐχ ἡγοῦμαι δίκαιον εἶναι οὔτε εἴ τινες τῇ πόλει πολλῶν ἀγαθῶν αἴτιοι γεγένηνται, ἄλλους τινὰς ὑπὲρ τούτων τιμὴν ἢ χάριν κομίσασθαι παρ’ ὑμῶν, οὔτ’ εἴ τινες πολλὰ κακὰ εἰργασμένοι εἰσίν, εἰκότως ἂν δι’ ἐκείνους τοὺς μηδὲν ἀδικοῦντας ὀνείδους καὶ διαβολῆς τυγχάνειν· ἱκανοὶ γὰρ οἱ ὑπάρχοντες ἐχθροὶ τῇ πόλει καὶ μέγα κέρδος νομίζοντες εἶναι τοὺς ἀδίκως ἐν ταῖς διαβολαῖς καθεστηκότας.", "st": "25.6"}, {"sp": "N", "t": "πειράσομαι δ’ ὑμᾶς διδάξαι, οὓς ἡγοῦμαι τῶν πολιτῶν προσήκειν ὀλιγαρχίας ἐπιθυμεῖν καὶ ⟨οὓς⟩ δημοκρατίας. ἐκ τούτου γὰρ καὶ ὑμεῖς γνώσεσθε, κἀγὼ περὶ ἐμαυτοῦ τὴν ἀπολογίαν ποιήσομαι, ἀποφαίνων ὡς οὔτε ἐξ ὧν ἐν δημοκρατίᾳ οὔτε ἐξ ὧν ἐν ὀλιγαρχίᾳ πεποίηκα, οὐδέν μοι προσῆκον κακόνουν εἶναι τῷ πλήθει τῷ ὑμετέρῳ.", "st": "25.7"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἐνθυμηθῆναι χρὴ ὅτι οὐδείς ἐστιν ἀνθρώπων φύσει οὔτε ὀλιγαρχικὸς οὔτε δημοκρατικός, ἀλλ’ ἥτις ἄν ἑκάστῳ πολιτεία συμφέρῃ, ταύτην προθυμεῖται καθεστάναι· ὥστε οὐκ ἐλάχιστον ἐν ὑμῖν ἐστι μέρος ὡς πλείστους ἐπιθυμεῖν τῶν παρόντων νυνὶ πραγμάτων. καὶ ταῦτα ὅτι οὕτως ἔχει, οὐ χαλεπῶς ἐκ τῶν πρότερον γεγενημένων μαθήσεσθε.", "st": "25.8"}, {"sp": "N", "t": "σκέψασθε γάρ, ὦ ἄνδρες δικασταί, τοὺς προστάντας ἀμφοτέρων ⟨τῶν⟩ πολιτειῶν, ὁσάκις δὴ μετεβάλοντο. οὐ Φρύνιχος μὲν καὶ Πείσανδρος καὶ οἱ μετ’ ἐκείνων δημαγωγοί, ἐπειδὴ πολλὰ εἰς ὑμᾶς ἐξήμαρτον, τὰς περὶ τούτων δείσαντες τιμωρίας τὴν προτέραν ὀλιγαρχίαν κατέστησαν, πολλοὶ δὲ τῶν τετρακοσίων μετὰ τῶν ἐκ Πειραιῶς συγκατῆλθον, ἔνιοι δὲ τῶν ἐκείνους ἐκβαλόντων αὐτοὶ αὖθις τῶν τριάκοντα ἐγένοντο; εἰσὶ δὲ οἵτινες τῶν Ἐλευσῖνάδε ἀπογραψαμένων, ἐξελθόντες μεθ’ ὑμῶν, ἐπολιόρκουν τοὺς μεθ’ αὑτῶν.", "st": "25.9"}, {"sp": "N", "t": "οὔκουν χαλεπὸν γνῶναι, ὦ ἄνδρες δικασταί, ὅτι οὐ περὶ πολιτείας εἰσὶν αἱ πρὸς ἀλλήλους διαφοραί, ἀλλὰ περὶ τῶν ἰδίᾳ συμφερόντων ἑκάστῳ. ὑμᾶς οὖν χρὴ ἐκ τούτων δοκιμάζειν τοὺς πολίτας, σκοποῦντας μὲν ὅπως ἦσαν ἐν τῇ δημοκρατίᾳ πεπολιτευμένοι, ζητοῦντας δὲ εἴ τις αὐτοῖς ἐγίγνετο ὠφέλεια τῶν πραγμάτων μεταπεσόντων· οὕτως γὰρ ἂν δικαιοτάτην ⟨τὴν⟩ κρίσιν περὶ αὐτῶν ποιοῖσθε.", "st": "25.10"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἡγοῦμαι, ὅσοι μὲν ἐν τῇ δημοκρατίᾳ ἄτιμοι ἦσαν ⟨εὐθύνας δεδωκότες⟩ ἢ τῶν ὄντων ἀπεστερημένοι ἢ ἄλλῃ τινὶ συμφορᾷ τοιαύτῃ κεχρημένοι, προσήκειν αὐτοῖς ἑτέρας ἐπιθυμεῖν πολιτείας, ἐλπίζοντας τὴν μεταβολὴν ὠφέλειάν τινα αὑτοῖς ἔσεσθαι· ὅσοι δὲ τὸν δῆμον πολλὰ κἀγαθὰ εἰργασμένοι εἰσί, κακὸν δὲ μηδὲν πώποτε, ὀφείλεται δὲ αὐτοῖς χάριν κομίσασθαι παρ’ ὑμῶν μᾶλλον ἢ δοῦναι δίκην τῶν πεπραγμένων, οὐκ ἄξιον τὰς κατὰ τούτων ἀποδέχεσθαι διαβολάς, οὐδ’ ἐὰν πάντες οἱ τὰ τῆς πόλεως πράττοντες ὀλιγαρχικοὺς αὐτοὺς φάσκωσιν εἶναι.", "st": "25.11"}, {"sp": "N", "t": "ἐμοὶ τοίνυν, ὦ ἄνδρες δικασταί, οὔτ’ ἰδίᾳ οὔτε δημοσίᾳ συμφορὰ ἐν ἐκείνῳ τῷ χρόνῳ οὐδεμία πώποτε ἐγένετο, ἀνθ’ ἧστινος ἂν προθυμούμενος τῶν παρόντων κακῶν ἀπαλλαγῆναι ἑτέρων ἐπεθύμουν πραγμάτων. τετριηράρχηκά τε γὰρ πεντάκις, καὶ τετράκις νεναυμάχηκα, καὶ εἰσφορὰς ἐν τῷ πολέμῳ πολλὰς εἰσενήνοχα, καὶ τἆλλα λελῃτούργηκα οὐδενὸς χεῖρον τῶν πολιτῶν.", "st": "25.12"}, {"sp": "N", "t": "καίτοι διὰ τοῦτο πλείω τῶν ὑπὸ τῆς πόλεως προσταττομένων ἐδαπανώμην, ἵνα καὶ βελτίων ὑφ’ ὑμῶν νομιζοίμην, καὶ εἴ πού μοί τις συμφορὰ γένοιτο, ἄμεινον ἀγωνιζοίμην. ὧν ἐν τῇ ὀλιγαρχίᾳ ἁπάντων ἀπεστερούμην· οὐ γὰρ τοὺς τῷ πλήθει ἀγαθοῦ τινος αἰτίους γεγενημένους χάριτος παρ’ αὑτῶν ἠξίουν τυγχάνειν, ἀλλὰ τοὺς πλεῖστα κακὰ ὑμᾶς εἰργασμένους εἰς τὰς τιμὰς καθίστασαν, ὡς ταύτην παρ’ ἡμῶν πίστιν εἰληφότες. ἃ χρὴ πάντας ἐνθυμουμένους μὴ τοῖς τούτων λόγοις πιστεύειν, ἀλλὰ [καὶ] ἐκ τῶν ἔργων σκοπεῖν ἃ ἑκάστῳ τυγχάνει πεπραγμένα.", "st": "25.13"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, οὔτε [ἐπὶ] τῶν τετρακοσίων ἐγενόμην· ἢ τῶν κατηγόρων ὁ βουλόμενος παρελθὼν ἐλεγξάτω· οὐ τοίνυν οὐδ’ ἐπειδὴ οἱ τριάκοντα κατέστησαν, οὐδείς με ἀποδείξει οὔτε βουλεύσαντα οὔτε ἀρχὴν οὐδεμίαν ἄρξαντα. καίτοι εἰ μὲν ἐξόν μοι ἄρχειν μὴ ἐβουλόμην, ὑφ’ ὑμῶν νυνὶ τιμᾶσθαι δίκαιός εἰμι· εἰ δὲ οἱ τότε δυνάμενοι μὴ ἠξίουν μοι μεταδιδόναι τῶν πραγμάτων, πῶς ἂν φανερώτερον ἢ οὕτως ψευδομένους ἀποδείξαιμι τοὺς κατηγόρους;", "st": "25.14"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες δικασταί, καὶ ἐκ τῶν ἄλλων τῶν ἐμοὶ πεπραγμένων ἄξιον σκέψασθαι. ἐγὼ γὰρ τοιοῦτον ἐμαυτὸν ἐν ταῖς τῆς πόλεως συμφοραῖς παρέσχον ὥστε, εἰ πάντες τὴν αὐτὴν γνώμην ἔσχον ἐμοί, μηδένα ἂν ὑμῶν μηδεμιᾷ χρῆσθαι συμφορᾷ. ὑπ’ ἐμοῦ γὰρ ἐν τῇ ὀλιγαρχίᾳ οὔτε ἀπαχθεὶς οὐδεὶς φανήσεται, οὔτε τῶν ἐχθρῶν οὐδεὶς τετιμωρημένος, οὔτε τῶν φίλων εὖ πεπονθώς", "st": "25.15"}, {"sp": "N", "t": "(καὶ τοῦτο μὲν οὐκ ἄξιον θαυμάζειν· εὖ μὲν γὰρ ποιεῖν ἐν ἐκείνῳ τῷ χρόνῳ χαλεπὸν ἦν, ἐξαμαρτάνειν δὲ τῷ βουλομένῳ ῥᾴδιον). οὐ τοίνυν οὐδ’ εἰς τὸν κατάλογον Ἀθηναίων καταλέξας οὐδένα φανήσομαι, οὐδὲ δίαιταν καταδιαιτησάμενος οὐδενός, οὐδὲ πλουσιώτερος ἐκ τῶν ὑμετέρων γεγονὼς συμφορῶν. καίτοι εἰ τοῖς τῶν γεγενημένων κακῶν αἰτίοις ὀργίζεσθε, εἰκὸς καὶ τοὺς μηδὲν ἡμαρτηκότας βελτίους ὑφ’ ὑμῶν νομίζεσθαι. καὶ μὲν δή,", "st": "25.16"}, {"sp": "N", "t": "ὦ ἄνδρες δικασταί, μεγίστην ἡγοῦμαι περὶ ἐμαυτοῦ τῇ δημοκρατίᾳ πίστιν δεδωκέναι. ὅστις γὰρ τότε οὐδὲν ἐξήμαρτον οὕτω πολλῆς δεδομένης ἐξουσίας, ἦ που νῦν σφόδρα προθυμηθήσομαι χρηστὸς εἶναι, εὖ εἰδὼς ὅτι, ἐὰν ἀδικῶ, παραχρῆμα δώσω δίκην. ἀλλὰ γὰρ τοιαύτην διὰ τέλους γνώμην ἔχω, ὥστε ἐν ὀλιγαρχίᾳ μὲν μὴ ἐπιθυμεῖν τῶν ἀλλοτρίων, ἐν δημοκρατίᾳ δὲ τὰ ὄντα προθύμως εἰς ὑμᾶς ἀναλίσκειν.", "st": "25.17"}, {"sp": "N", "t": "ἡγοῦμαι δέ, ὦ ἄνδρες δικασταί, οὐκ ἂν δικαίως ὑμᾶς μισεῖν τοὺς ἐν τῇ ὀλιγαρχίᾳ μηδὲν πεπονθότας κακόν, ἐξὸν ὀργίζεσθαι τοῖς εἰς τὸ πλῆθος ἐξημαρτηκόσιν, οὐδὲ τοὺς μὴ φυγόντας ἐχθροὺς νομίζειν, ἀλλὰ τοὺς ὑμᾶς ἐκβαλόντας, οὐδὲ τοὺς προθυμουμένους τὰ ἑαυτῶν σῶσαι, ἀλλὰ τοὺς τὰ τῶν ἄλλων ἀφῃρημένους, οὐδὲ οἳ τῆς σφετέρας αὐτῶν σωτηρίας ἕνεκα ἔμειναν ἐν τῷ ἄστει, ἀλλ’ οἵτινες ἑτέρους ἀπολέσαι βουλόμενοι μετέσχον τῶν πραγμάτων. εἰ δὲ οἴεσθε χρῆναι, οὓς ἐκεῖνοι παρέλιπον ἀδικοῦντες, ὑμεῖς ἀπολέσαι, οὐδεὶς τῶν πολιτῶν ὑπολειφθήσεται.", "st": "25.18"}, {"sp": "N", "t": "σκοπεῖν δὲ χρὴ καὶ ἐκ τῶνδε, ὦ ἄνδρες δικασταί. πάντες γὰρ ἐπίστασθε ὅτι ἐν τῇ προτέρᾳ δημοκρατίᾳ τῶν τὰ τῆς πόλεως πραττόντων πολλοὶ μὲν τὰ δημόσια ἔκλεπτον, ἔνιοι δ’ ἐπὶ τοῖς ὑμετέροις ἐδωροδόκουν, οἱ δὲ συκοφαντοῦντες τοὺς συμμάχους ἀφίστασαν. καὶ εἰ μὲν οἱ τριάκοντα τούτους μόνους ἐτιμωροῦντο, ἄνδρας ἀγαθοὺς καὶ ὑμεῖς ἂν αὐτοὺς ἡγεῖσθε· νῦν δέ, ὅτε ὑπὲρ τῶν ἐκείνοις ἡμαρτημένων τὸ πλῆθος κακῶς ποιεῖν ἠξίουν, ἠγανακτεῖτε, ἡγούμενοι δεινὸν εἶναι τὰ τῶν ὀλίγων ἀδικήματα πάσῃ τῇ πόλει κοινὰ γίγνεσθαι.", "st": "25.19"}, {"sp": "N", "t": "οὐ τοίνυν ἄξιον χρῆσθαι τούτοις, οἷς ἐκείνους ἑωρᾶτε ἐξαμαρτάνοντας, οὐδὲ ἃ πάσχοντες ἄδικα ἐνομίζετε πάσχειν, ὅταν ἑτέρους ποιῆτε, δίκαια ἡγεῖσθαι, ἀλλὰ τὴν αὐτὴν κατελθόντες περὶ ἡμῶν γνώμην ἔχετε, ἥνπερ φεύγοντες περὶ ὑμῶν αὐτῶν εἴχετε· ἐκ τούτων γὰρ καὶ ὁμόνοιαν πλείστην ποιήσετε, καὶ ἡ πόλις ἔσται μεγίστη, καὶ τοῖς ἐχθροῖς ἀνιαρότατα ψηφιεῖσθε.", "st": "25.20"}, {"sp": "N", "t": "ἐνθυμηθῆναι δὲ χρή, ὦ ἄνδρες δικασταί, καὶ τῶν ἐπὶ τῶν τριάκοντα γεγενημένων, ἵνα τὰ τῶν ἐχθρῶν ἁμαρτήματα ἄμεινον ὑμᾶς ποιήσῃ περὶ τῶν ὑμετέρων αὐτῶν βουλεύσασθαι. ὅτε μὲν γὰρ ἀκούοιτε τοὺς ἐν ἄστει τὴν αὐτὴν γνώμην ἔχειν, μικρὰς ἐλπίδας εἴχετε τῆς καθόδου, ἡγούμενοι τὴν ἡμετέραν ὁμόνοιαν μέγιστον κακὸν εἶναι τῇ ὑμετέρᾳ φυγῇ·", "st": "25.21"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐπυνθάνεσθε τοὺς μὲν τρισχιλίους στασιάζοντας, τοὺς δὲ ἄλλους πολίτας ἐκ τοῦ ἄστεως ἐκκεκηρυγμένους, τοὺς δὲ τριάκοντα μὴ τὴν αὐτὴν γνώμην ἔχοντας, πλείους δ’ ὄντας τοὺς ὑπὲρ ὑμῶν δεδιότας ἢ τοὺς ὑμῖν πολεμοῦντας, τότ’ ἤδη καὶ κατιέναι προσεδοκᾶτε καὶ παρὰ τῶν ἐχθρῶν λήψεσθαι δίκην. ταῦτα γὰρ τοῖς θεοῖς ηὔχεσθε, ἅπερ ἐκείνους ἑωρᾶτε ποιοῦντας, ἡγούμενοι διὰ τὴν τῶν τριάκοντα πονηρίαν πολὺ μᾶλλον σωθήσεσθαι ἢ διὰ τὴν τῶν φευγόντων δύναμιν κατιέναι.", "st": "25.22"}, {"sp": "N", "t": "χρὴ τοίνυν, ὦ ἄνδρες δικασταί, τοῖς πρότερον γεγενημένοις παραδείγμασι χρωμένους βουλεύεσθαι περὶ τῶν μελλόντων ἔσεσθαι, καὶ τούτους ἡγεῖσθαι δημοτικωτάτους, οἵτινες ὁμονοεῖν ὑμᾶς βουλόμενοι τοῖς ὅρκοις καὶ ταῖς συνθήκαις ἐμμένουσι, νομίζοντες καὶ τῆς πόλεως ταύτην ἱκανωτάτην εἶναι σωτηρίαν καὶ τῶν ἐχθρῶν μεγίστην τιμωρίαν· οὐδὲν γὰρ ἂν εἴη αὐτοῖς χαλεπώτερον τούτων, ἢ πυνθάνεσθαι μὲν ἡμᾶς μετέχοντας τῶν πραγμάτων, αἰσθάνεσθαι δὲ οὕτως διακειμένους τοὺς πολίτας ὥσπερ μηδενὸς ἐγκλήματος πρὸς ἀλλήλους γεγενημένου.", "st": "25.23"}, {"sp": "N", "t": "χρὴ δὲ εἰδέναι, ὦ ἄνδρες δικασταί, ὅτι οἱ φεύγοντες τῶν ἄλλων πολιτῶν ὡς πλείστους καὶ διαβεβλῆσθαι καὶ ἠτιμῶσθαι βούλονται, ἐλπίζοντες τοὺς ὑφ’ ὑμῶν ἀδικουμένους ἑαυτοῖς ἔσεσθαι συμμάχους, τοὺς δὲ συκοφάντας εὐδοκιμεῖν δέξαιντ’ ἂν παρ’ ὑμῖν καὶ μέγα δύνασθαι ἐν τῇ πόλει· τὴν γὰρ τούτων πονηρίαν ἑαυτῶν ἡγοῦνται σωτηρίαν.", "st": "25.24"}, {"sp": "N", "t": "ἄξιον δὲ μνησθῆναι ⟨καὶ⟩ τῶν μετὰ τοὺς τετρακοσίους πραγμάτων· εὖ γὰρ εἴσεσθε ὅτι, ἃ μὲν οὗτοι συμβουλεύουσιν, οὐδεπώποτε ὑμῖν ἐλυσιτέλησεν, ἃ δ’ ἐγὼ παραινῶ, ἀμφοτέραις ἀεὶ ταῖς πολιτείαις συμφέρει. ἴστε γὰρ Ἐπιγένη καὶ Δημοφάνη καὶ Κλεισθένη ἰδίᾳ μὲν καρπωσαμένους τὰς τῆς πόλεως συμφοράς, δημοσίᾳ δὲ ὄντας μεγίστων κακῶν αἰτίους.", "st": "25.25"}, {"sp": "N", "t": "ἐνίων μὲν γὰρ ἔπεισαν ὑμᾶς ἀκρίτων θάνατον καταψηφίσασθαι, πολλῶν δὲ ἀδίκως δημεῦσαι τὰς οὐσίας, τοὺς δ’ ἐξελάσαι καὶ ἀτιμῶσαι τῶν πολιτῶν· τοιοῦτοι γὰρ ἦσαν ὥστε τοὺς μὲν ἡμαρτηκότας ἀργύριον λαμβάνοντες ἀφιέναι, τοὺς δὲ μηδὲν ἠδικηκότας εἰς ὑμᾶς εἰσιόντες ἀπολλύναι. καὶ οὐ πρότερον ἐπαύσαντο, ἕως τὴν μὲν πόλιν εἰς στάσεις καὶ τὰς μεγίστας συμφορὰς κατέστησαν, αὐτοὶ δ’ ἐκ πενήτων πλούσιοι ἐγένοντο.", "st": "25.26"}, {"sp": "N", "t": "ὑμεῖς δὲ οὕτως διετέθητε ὥστε τοὺς μὲν φεύγοντας κατεδέξασθε, τοὺς δ’ ἀτίμους ἐπιτίμους ἐποιήσατε, τοῖς δ’ ἄλλοις περὶ ὁμονοίας ὅρκους ὤμνυτε· τελευτῶντες δὲ ἥδιον ἂν τοὺς ἐν τῇ δημοκρατίᾳ συκοφαντοῦντας ἐτιμωρήσασθε ἢ τοὺς ἄρξαντας ἐν τῇ ὀλιγαρχίᾳ. καὶ εἰκότως, ὦ ἄνδρες δικασταί· πᾶσι γὰρ ἤδη φανερόν ἐστιν ὅτι διὰ τοὺς μὲν ἀδίκως πολιτευομένους ἐν τῇ ὀλιγαρχίᾳ δημοκρατία γίγνεται, διὰ δὲ τοὺς ἐν τῇ δημοκρατίᾳ συκοφαντοῦντας ὀλιγαρχία δὶς κατέστη. ὥστε οὐκ ἄξιον τούτοις πολλάκις χρῆσθαι συμβούλοις, οἷς οὐδὲ ἅπαξ ἐλυσιτέλησε πιθομένοις.", "st": "25.27"}, {"sp": "N", "t": "σκέψασθαι δὲ χρὴ ὅτι καὶ τῶν ἐκ Πειραιῶς οἱ μεγίστην δόξαν ἔχοντες καὶ μάλιστα κεκινδυνευκότες καὶ πλεῖστα ὑμᾶς ἀγαθὰ εἰργασμένοι πολλάκις ἤδη τῷ ὑμετέρῳ πλήθει διεκελεύσαντο τοῖς ὅρκοις καὶ ταῖς συνθήκαις ἐμμένειν, ἡγούμενοι ταύτην δημοκρατίας εἶναι φυλακήν· τοῖς μὲν γὰρ ἐξ ἄστεως ὑπὲρ τῶν παρεληλυθότων ἄδειαν ποιήσειν, τοῖς δ’ ἐκ Πειραιῶς οὕτως πλεῖστον ⟨ἂν⟩ χρόνον τὴν πολιτείαν παραμεῖναι.", "st": "25.28"}, {"sp": "N", "t": "οἷς ὑμεῖς πολὺ ἂν δικαιότερον πιστεύοιτε ἢ τούτοις, οἳ φεύγοντες μὲν δι’ ἑτέρους ἐσώθησαν, κατελθόντες δὲ συκοφαντεῖν ἐπιχειροῦσιν. ἡγοῦμαι δέ, ὦ ἄνδρες δικασταί, τοὺς μὲν τὴν αὐτὴν γνώμην ἔχοντας ἐμοὶ τῶν ἐν ἄστει μεινάντων φανεροὺς γεγενῆσθαι καὶ ἐν ὀλιγαρχίᾳ καὶ ἐν δημοκρατίᾳ,", "st": "25.29"}, {"sp": "N", "t": "ὁποῖοί τινές εἰσι πολῖται· τούτων δ’ ἄξιον θαυμάζειν, ὅ τι ἂν ἐποίησαν, εἴ τις αὐτοὺς εἴασε τῶν τριάκοντα γενέσθαι, οἳ νῦν δημοκρατίας οὔσης ταὐτὰ ἐκείνοις πράττουσι, καὶ ταχέως μὲν ἐκ πενήτων πλούσιοι γεγένηνται, πολλὰς δὲ ἀρχὰς ἄρχοντες οὐδεμιᾶς εὐθύνην διδόασιν, ἀλλ’ ἀντὶ μὲν ὁμονοίας ὑποψίαν πρὸς ἀλλήλους πεποιήκασιν, ἀντὶ δὲ εἰρήνης πόλεμον κατηγγέλκασι, διὰ τούτους δὲ ἄπιστοι τοῖς Ἕλλησι γεγενήμεθα.", "st": "25.30"}, {"sp": "N", "t": "καὶ τοσούτων κακῶν καὶ ἑτέρων πολλῶν ὄντες αἴτιοι, καὶ οὐδὲν διαφέροντες τῶν τριάκοντα πλὴν ὅτι ἐκεῖνοι μὲν ὀλιγαρχίας οὔσης ἐπεθύμουν ὧνπερ οὗτοι, οὗτοι δὲ καὶ δημοκρατίας τῶν αὐτῶν ὧνπερ ἐκεῖνοι, ὅμως οἴονται χρῆναι οὕτως ῥᾳδίως ὃν ἂν βούλωνται κακῶς ποιεῖν, ὥσπερ τῶν μὲν ἄλλων ἀδικούντων, ἄριστοι δὲ ἄνδρες αὐτοὶ γεγενημένοι (καὶ τούτων μὲν οὐκ ἄξιον θαυμάζειν,", "st": "25.31"}, {"sp": "N", "t": "ὑμῶν δέ, ὅτι οἴεσθε μὲν δημοκρατίαν εἶναι, γίγνεται δὲ ὅ τι ἂν οὗτοι βούλωνται, καὶ δίκην διδόασιν οὐχ οἱ τὸ ὑμέτερον πλῆθος ἀδικοῦντες, ἀλλ’ οἱ τὰ σφέτερα αὐτῶν μὴ διδόντες). καὶ δέξαιντ’ ἂν μικρὰν εἶναι τὴν πόλιν μᾶλλον ἢ δι’ ἄλλους μεγάλην καὶ ἐλευθέραν,", "st": "25.32"}, {"sp": "N", "t": "ἡγούμενοι νῦν μὲν διὰ τοὺς ἐκ Πειραιῶς κινδύνους αὑτοῖς ἐξεῖναι ποιεῖν ὅ τι ἂν βούλωνται, ἐὰν δ’ ὕστερον ὑμῖν δι’ ἑτέρων σωτήρια γένηται, αὐτοὶ μὲν καταλύσεσθαι, ἐκείνους δὲ μεῖζον δυνήσεσθαι· ὥστε τὸ αὐτὸ πάντες ἐμποδών εἰσιν, ἐάν τι δι’ ἄλλων ἀγαθὸν ὑμῖν φαίνηται.", "st": "25.33"}, {"sp": "N", "t": "τοῦτο μὲν οὖν οὐ χαλεπὸν τῷ βουλομένῳ κατανοῆσαι· αὐτοί τε γὰρ οὐκ ἐπιθυμοῦσι λανθάνειν, ἀλλ’ αἰσχύνονται μὴ δοκοῦντες εἶναι πονηροί, ὑμεῖς τε τὰ μὲν αὐτοὶ ὁρᾶτε τὰ δ’ ἑτέρων πολλῶν ἀκούετε. ἡμεῖς δέ, ὦ ἄνδρες δικασταί, δίκαιον μὲν ἡγούμεθ’ εἶναι πρὸς πάντας ὑμᾶς τοὺς πολίτας ταῖς συνθήκαις καὶ τοῖς ὅρκοις ἐμμένειν, ὅμως δέ,", "st": "25.34"}, {"sp": "N", "t": "ὅταν μὲν ἴδωμεν τοὺς τῶν κακῶν αἰτίους δίκην διδόντας, τῶν τότε περὶ ὑμᾶς γεγενημένων μεμνημένοι συγγνώμην ἔχομεν, ὅταν δὲ φανεροὶ γένησθε τοὺς μηδὲν αἰτίους ἐξ ἴσου τοῖς ἀδικοῦσι τιμωρούμενοι, τῇ αὐτῇ ψήφῳ ἡμᾶς εἰς ὑπο⟨ψίαν καταστήσετε⟩ …", "st": "25.35"}, {"sp": "HDR", "t": "ΚϚʹ. Περὶ τῆς Εὐάνδρου δοκιμασίας", "st": "26"}, {"sp": "N", "t": "… οὐδ’ ἡγούμενος ἀκριβῆ νῦν τὴν δοκιμασίαν αὐτοὺς διὰ τὸν χρόνον ποιήσεσθαι, ἐπεὶ σύνοισθα πολλὰ καὶ δεινὰ εἰς αὐτοὺς ἐξημαρτηκώς, ὧν ἐπιλελῆσθαι καὶ οὐδ’ ἀναμνησθήσεσθαι ἐνίους αὐτῶν νομίζεις. ὃ δὴ ἔγωγε καὶ ἀγανακτῶ, εἰ ταύτῃ τῇ ἐλπίδι εἰς ὑμᾶς ἥκει πιστεύων, ὥσπερ ἄλλων μέν τινων ὄντων τῶν ἠδικημένων, ἑτέρων δὲ τῶν ταῦτα διαψηφιουμένων, ἀλλ’ οὐκ ἀμφότερα τῶν αὐτῶν καὶ πεπονθότων καὶ ἀκουσομένων.", "st": "26.1"}, {"sp": "N", "t": "αἴτιοι δὲ τούτων ὑμεῖς ἐστε· οὐ γὰρ ἐνθυμεῖσθε ὅτι οὗτοι μέν, ὅτε ἡ πόλις ὑπὸ [τῶν] Λακεδαιμονίων ἤρχετο, οὐδὲ τῆς αὐτῆς δουλείας ὑμῖν μεταδοῦναι ἠξίωσαν, ἀλλὰ καὶ τῆς πόλεως ἐξήλασαν· ὑμεῖς δ’ ἐλευθέραν αὐτὴν ποιήσαντες οὐ μόνον τῆς ἐλευθερίας αὐτοῖς ἀλλὰ καὶ τοῦ δικάζειν καὶ τοῦ ἐκκλησιάζειν περὶ τῶν κοινῶν μετέδοτε, ὥστε εἰκότως ὑμῶν ταύτην τὴν εὐήθειαν καταγιγνώσκουσιν.", "st": "26.2"}, {"sp": "N", "t": "ὧν εἷς οὗτος ὢν οὐκ ἀγαπᾷ εἴ τις αὐτὸν ἐᾷ τούτων μετέχειν, ἀλλὰ καὶ πρὶν ἐκείνων δοῦναι δίκην πάλιν ἄρχειν ἀξιοῖ. καὶ νυνὶ αὐτὸν ἀκούω ὑπὲρ μὲν τῶν αὐτοῦ κατηγορουμένων διὰ βραχέων ἀπολογήσεσθαι, ἐπισύροντα τὰ πράγματα καὶ διακλέπτοντα τῇ ἀπολογίᾳ τὴν κατηγορίαν, λέξειν δὲ ὡς πολλὰ εἰς τὴν πόλιν ἀνηλώκασι καὶ φιλοτίμως λελῃτουργήκασι καὶ νίκας πολλὰς καὶ καλὰς ἐν δημοκρατίᾳ νενικήκασι, καὶ ὅτι αὐτὸς κόσμιός ἐστι καὶ οὐχ ὁρᾶται ποιῶν ἃ ἕτεροι ἐνταῦθα τολμῶσιν, ἀλλὰ τὰ ἑαυτοῦ πράττειν ἀξιοῖ.", "st": "26.3"}, {"sp": "N", "t": "ἐγὼ δὲ πρὸς τούτους τοὺς λόγους οὐ χαλεπὸν οἶμαι ἀντειπεῖν· πρὸς μὲν τὰς λῃτουργίας, ὅτι κρείττων ἦν ὁ πατὴρ αὐτοῦ μὴ λῃτουργήσας ἢ τοσαῦτα τῶν ἑαυτοῦ ἀναλώσας· διὰ γὰρ ταῦτα πιστευθεὶς ὑπὸ τοῦ δήμου κατέλυσε τὴν δημοκρατίαν, ὥστ’ εἶναι ταῦτα τὰ ἔργα ἀειμνηστότερα ἢ τὰ ἐκ τῶν λῃτουργιῶν αὐτῷ ἀναθήματα·", "st": "26.4"}, {"sp": "N", "t": "πρὸς δὲ τὴν ἡσυχιότητα τὴν τούτου, ὅτι οὐ νῦν δεῖ αὐτὸν ἐξετάζειν εἰ σώφρων ἐστίν, ὅτ’ αὐτὸν οὐκ ἔξεστιν ἀσελγαίνειν, ἀλλ’ ἐκεῖνον τὸν χρόνον σκοπεῖν, ἐν ᾧ ἐξὸν ὁποτέρως ἐβούλετο ζῆν εἵλετο παρανόμως πολιτευθῆναι. τοῦ μὲν γὰρ νῦν μηδὲν ἐξαμαρτάνειν οἱ κωλύσαντες αἴτιοι, τῶν δὲ τότε γενομένων ὁ τούτου τρόπος καὶ οἱ τούτῳ ἐπιτρέπειν ἀξιοῦντες. ὥστ’ ἐὰν ἐκ τούτων δοκιμάζεσθαι ἀξιοῖ, ταῦτα χρὴ ὑπολαμβάνειν, μὴ εὐήθεις αὐτῷ εἶναι δοκῆτε.", "st": "26.5"}, {"sp": "N", "t": "ἐὰν δὲ καὶ ἐπὶ τοιόνδε λόγον τράπωνται, ὡς ὁ χρόνος οὐκ ἐγχωρεῖ ἄλλον ἀποκληρῶσαι, ἀλλὰ ἀνάγκη, ἐὰν αὐτὸν ἀποδοκιμάσητε, ἄθυτα τὰ πάτρια ἱερὰ γίγνεσθαι, τάδ’ ἐνθυμήθητε, ὅτι πάλαι ὁ χρόνος ἤδη παρελήλυθεν. ἡ γὰρ αὔριον ἡμέρα μόνη λοιπὴ τοῦ ἐνιαυτοῦ ἐστιν, ἐν δὲ ταύτῃ τῷ Διὶ τῷ σωτῆρι θυσία γίγνεται, δικαστήριον δὲ παρὰ τοὺς νόμους ἀδύνατον πληρωθῆναι.", "st": "26.6"}, {"sp": "N", "t": "εἰ δὲ ταῦτα πάνθ’ οὗτος ὥστε γενέσθαι διαπέπρακται, τί προσδοκῆσαι ⟨δεῖ⟩ δοκιμασθέντ’ αὐτὸν ποιήσειν, εἰ τὴν ἐξιοῦσαν ἀρχὴν πέπεικεν αὐτοῦ ἕνεκα παρανομῆσαι; ἆρ’ ἂν ὀλίγα τοιαῦτα ἐν τῷ ἐνιαυτῷ διαπράξασθαι; ἐγὼ μὲν γὰρ οὐκ ἂν οἶμαι.", "st": "26.7"}, {"sp": "N", "t": "ἔστι δ’ ὑμῖν οὐ τοῦτο μόνον σκεπτέον, ἀλλὰ καὶ πότερον εὐσεβέστερον τὸν βασιλέα καὶ τοὺς συνάρχοντας τὰ ὑπὲρ τοῦ μέλλοντος ἄρξειν ἱερὰ θῦσαι, ὡς καὶ πρότερον ἤδη γεγένηται, ἢ καὶ τοῦτον, ὃν οὐδὲ καθαρὸν εἶναι τὰς χεῖρας οἱ εἰδότες μεμαρτυρήκασι, καὶ πότερον ὑμεῖς ὠμόσατε εἰς τὴν ἀρχὴν ἀδοκίμαστον καταστήσειν, ἢ δοκιμάσαντες τὸν ἄξιον τῆς ἀρχῆς στεφανώσειν. ταῦτα γὰρ σκοπεῖσθε· κἀκεῖνο ⟨δ’⟩ ἐνθυμεῖσθε,", "st": "26.8"}, {"sp": "N", "t": "ὅτι ὁ θεὶς τὸν περὶ τῶν δοκιμασιῶν νόμον οὐχ ἥκιστα [περὶ] τῶν ἐν ὀλιγαρχίᾳ ἀρξάντων ἕνεκα ἔθηκεν, ἡγούμενος δεινὸν εἶναι, εἰ δι’ οὓς ἡ δημοκρατία κατελύετο, οὗτοι ἐν αὐτῇ τῇ πολιτείᾳ πάλιν ἄρξουσι, καὶ κύριοι γενήσονται τῶν νόμων καὶ τῆς πόλεως, ἣν πρότερον παραλαβόντες οὕτως αἰσχρῶς καὶ δεινῶς ἐλωβήσαντο. ὥστ’ οὐκ ἄξιον τῆς δοκιμασίας ὀλιγώρως ἔχειν, οὐδὲ μικρὸν ἡγουμένους τὸ πρᾶγμα μὴ φροντίζειν αὐτῆς, ἀλλὰ φυλάττειν· ὡς ἐν τῷ ἕκαστον δικαίως ἄρχειν ἥ τε πολιτεία καὶ τὸ ἄλλο πλῆθος τὸ ὑμέτερον σῴζεται", "st": "26.9"}, {"sp": "N", "t": "⟨καὶ⟩ εἰ μὲν δὴ βουλεύσων νυνὶ ἐδοκιμάζετο καὶ ὡς ἱππευκότος αὐτοῦ ἐπὶ τῶν τριάκοντα τοὔνομα ἐν ταῖς σανίσιν ἐνεγέγραπτο, καὶ ἄνευ κατηγόρου ἂν αὐτὸν ἀπεδοκιμάζετε· νῦν δέ, ὅτε μὴ μόνον ἱππευκὼς μηδὲ βεβουλευκώς, ἀλλὰ καὶ εἰς τὸ πλῆθος ἐξημαρτηκὼς φαίνεται, οὐκ ἂν ἄτοπον ποιήσαιτε, εἰ μὴ τὴν αὐτὴν γνώμην ἔχοντες περὶ αὐτοῦ φανεῖσθε;", "st": "26.10"}, {"sp": "N", "t": "καὶ μὲν δὴ βουλεύειν γε δοκιμασθεὶς πεντακοσιοστὸς ὢν μετὰ τῶν ἄλλων ἐνιαυτὸν ἂν μόνον ἐβούλευσεν, ὥστε καὶ εἴ τι ἐν τούτῳ τῷ χρόνῳ ἐξαμαρτάνειν ἐβούλετο, ῥᾳδίως ἂν ὑπὸ τῶν ἄλλων ἐκωλύετο, ταύτης δὲ τῆς ἀρχῆς ἀξιούμενος αὐτὸς καθ’ αὑτὸν ἄρξει, καὶ μετὰ τῆς ἐν Ἀρείῳ πάγῳ βουλῆς τὸν ἅπαντα χρόνον τῶν μεγίστων κύριος γενήσεται.", "st": "26.11"}, {"sp": "N", "t": "ὥστε ὑμῖν καθήκειν περὶ ταύτης τῆς ἀρχῆς ἀκριβεστέραν τὴν δοκιμασίαν ἢ περὶ τῶν ἄλλων ἀρχῶν ποιεῖσθαι. εἰ δὲ μή, πῶς οἴεσθε τὸ ἄλλο πλῆθος τῶν πολιτῶν διακείσεσθαι, ὅταν αἴσθωνται, ὃν προσῆκε δίκας τῶν ἡμαρτημένων διδόναι, τοῦτον ὑφ’ ὑμῶν τοιαύτης ἀρχῆς ἠξιωμένον; καὶ φόνου δίκας δικάζοντα, ὃν ἔδει αὐτὸν ὑπὸ τῆς ἐν Ἀρείῳ πάγῳ βουλῆς κρίνεσθαι; καὶ πρὸς τούτοις ἴδωσιν ἐστεφανωμένον, καὶ ἐπικλήρων καὶ ὀρφανῶν κύριον γεγενημένον, ὧν ἐνίοις αὐτὸς τῆς ὀρφανίας αἴτιος γεγένηται;", "st": "26.12"}, {"sp": "N", "t": "ἆρ’ οὐκ οἴεσθε αὐτοὺς χαλεπῶς διακείσεσθαι καὶ ὑμᾶς αὐτῶν αἰτίους ἡγήσεσθαι, ὅταν γένωνται ἐν ἐκείνοις τοῖς χρόνοις, ἐν οἷς αὐτῶν πολλοὶ εἰς τὸ δεσμωτήριον ἀπήγοντο καὶ ἄκριτοι ὑπὸ τούτων ἀπώλλυντο καὶ φεύγειν τὴν σφετέραν αὐτῶν ἠναγκάζοντο; κἀκεῖνο πρὸς ἐνθυμηθῶσιν, ὅτι ὁ αὐτὸς οὗτος ἀνὴρ [Θρασύβουλος] αἴτιος γεγένηται Λεωδάμαντά τε ἀποδοκιμασθῆναι καὶ τοῦτον δοκιμασθῆναι, τοῦ μὲν κατήγορος γενόμενος, ὑπὲρ τούτου δὲ ἀπολογήσασθαι παρασκευασάμενος, ὃς πῶς πρὸς τὴν πόλιν διάκειται καὶ πόσων αἴτιος αὐτῇ κακῶν γεγένηται;", "st": "26.13"}, {"sp": "N", "t": "ἢ πιθόμενοι πῶς ἂν οἴεσθε διαβληθῆναι; τότε μὲν γὰρ ὑμᾶς ᾤοντο ὀργισθέντας Λεωδάμαντα ἀποδοκιμάσαι· ἐὰν δὲ τοῦτον δοκιμάσητε, εὖ εἴσονται ὅτι οὐ δικαίᾳ γνώμῃ περὶ αὐτοῦ κέχρησθε. ἔστι δὲ τούτοις μὲν πρὸς ὑμᾶς ἁγών, ὑμῖν δὲ πρὸς ἅπασαν τὴν πόλιν, ἣ σκοπεῖ νυνὶ τίνα ὑμεῖς γνώμην περὶ αὐτῆς ἕξετε.", "st": "26.14"}, {"sp": "N", "t": "καὶ μηδεὶς ὑμῶν ἡγείσθω με Λεωδάμαντι χαριζόμενον κατηγορεῖν Εὐάνδρου, ὅτι φίλος ὢν τυγχάνει, ἀλλ’ ὑπὲρ ὑμῶν καὶ τῆς πόλεως προνοούμενον. ῥᾴδιον δ’ ἐξ αὐτοῦ τοῦ πράγματος μαθεῖν. Λεωδάμαντι γὰρ συμφέρει τοῦτον δοκιμασθῆναι, οὕτω γὰρ ὑμεῖς μάλιστα διαβληθήσεσθε, καὶ δόξετε ἀντὶ δημοτικῶν ἀνθρώπων ὀλιγαρχικοὺς εἰς τὰς ἀρχὰς καθιστάναι· ὑμῖν δὲ τόνδε ἀποδοκιμάσαι, δόξετε γὰρ κἀκεῖνον δικαίως [ἂν] ἀποδοκιμάσαι· ἐὰν δὲ μηδὲ τόνδε, οὐδ’ ἐκεῖνον δικαίως.", "st": "26.15"}, {"sp": "N", "t": "καίτοιγε αὐτὸν ἀκούω λέξειν ὡς οὐ περὶ αὐτοῦ μόνον ἡ δοκιμασία ἐστίν, ἀλλὰ περὶ πάντων τῶν ἐν ἄστει μεινάντων, καὶ τοὺς ὅρκους καὶ τὰς συνθήκας ὑμᾶς ὑπομνήσειν, ὡς ἐκ τούτων προσληψόμενον αὐτὸν δοκιμαστὰς τοὺς ἐν ἄστει μείναντας. ἐγὼ δ’ ὑπὲρ τοῦ πλήθους βραχέα πρὸς αὐτὸν εἰπεῖν βούλομαι, ὅτι ὁ δῆμος οὐ τὴν αὐτὴν γνώμην ἔχει περὶ πάντων τῶν ἐν ἄστει μεινάντων, ἀλλὰ περὶ μὲν τῶν τοιαῦτα ἐξαμαρτανόντων οἵαν ἐγώ φημι δεῖν,", "st": "26.16"}, {"sp": "N", "t": "περὶ δὲ τῶν ἄλλων τὴν ἐναντίαν. τεκμήριον δέ· οὐ γὰρ ἔλαττον τούτους ἡ πόλις τετίμηκε τῶν ἐπὶ Φυλὴν ἐλθόντων καὶ τὸν Πειραιᾶ καταλαβόντων. εἰκότως· τοὺς μὲν γὰρ ἴσασιν ὁποῖοι τινες ἐν δημοκρατίᾳ μόνῃ γεγένηνται, ὁποῖοι δ’ ἄν τινες ἐν ὀλιγαρχίᾳ γένοιντο, οὔπω πεῖραν εἰλήφασι· παρὰ δὲ τούτων ἑκατέρας τῆς πολιτείας ἱκανὴν βάσανον ἔχουσιν, ὥστ’ εἰκότως πιστεύειν.", "st": "26.17"}, {"sp": "N", "t": "καὶ ἡγοῦνταί γε διὰ μὲν τοὺς τοιούτους συλληφθέντας τότε ἀποθανεῖν, διὰ δὲ τοὺς ἄλλους [τοὺς συλληφθέντας] ἐκφυγεῖν, ἐπεὶ εἴ γε τὴν αὐτὴν γνώμην ἅπαντες ἔσχον, οὔτ’ ἂν φυγὴ οὔτ’ ἂν κάθοδος οὔτ’ ἄλλο οὐδὲν ἂν τῶν γεγενημένων τῇ πόλει συνέβη.", "st": "26.18"}, {"sp": "N", "t": "ἀλλὰ καὶ ὃ ἄλογον δοκεῖ εἶναι παρά τισιν, ὅπως ποτὲ πολλοὶ ὄντες ὑπ’ ὀλίγων τῶν ἐν Πειραιεῖ ἡττήθησαν, οὐδαμόθεν ἄλλοθεν ἢ ἐκ τῆς τούτων προνοίας γεγένηται· οὗτοι γὰρ εἵλοντο μετὰ τῶν κατελθόντων πολιτεύεσθαι μᾶλλον ἢ μετὰ τῶν τριάκοντα Λακεδαιμονίοις δουλεύειν.", "st": "26.19"}, {"sp": "N", "t": "τοιγάρτοι ἀντὶ τούτων αὐτοὺς ὁ δῆμος ταῖς μεγίσταις τιμαῖς τετίμηκεν, ἱππαρχεῖν καὶ στρατηγεῖν καὶ πρεσβεύειν ὑπὲρ αὑτῶν αἱρούμενοι· καὶ οὐδέποτε αὐτοῖς μετεμέλησεν. καὶ διὰ μέν γε τοὺς πολλὰ ἐξαμαρτόντας τὰς δοκιμασίας εἶναι ἐψηφίσαντο, διὰ δὲ τοὺς μηδὲν τοιοῦτον πράξαντας τὰς συνθήκας ἐποιήσαντο. τοσαῦτά σοι ἐγὼ ὑπὲρ τοῦ δήμου ἀποκρίνομαι.", "st": "26.20"}, {"sp": "N", "t": "ὑμέτερον δὴ ἔργον ἐστίν, ὦ ἄνδρες βουλευταί, σκέψασθαι ποτέρῳ ἂν πιθόμενοι περὶ τῆς δοκιμασίας ταύτης ἄμεινον βουλεύσαισθε, πότερον ἐμοὶ ἢ Θρασυβούλῳ, ὃς αὐτῷ ἀπολογήσεται. περὶ μὲν οὖν ἐμοῦ ἢ τοῦ πατρὸς ἢ τῶν προγόνων οὐδὲν οὗτος εἰπεῖν ἕξει εἰς μισοδημίαν. οὔτε γὰρ ὡς ὀλιγαρχίας μετέσχον (ὕστερον γὰρ τῶν χρόνων τούτων ἀνὴρ εἶναι ἐδοκιμάσθην), οὔθ’ ὡς ὁ πατήρ (πρὸ γὰρ τῶν στάσεων πολὺ ἐν Σικελίᾳ ἄρχων ἐτελεύτησεν)·", "st": "26.21"}, {"sp": "N", "t": "οὐδ’ ὡς οἱ πρόγονοι ὑπὸ τοῖς τυράννοις ἐγένοντο· στασιάζοντες γὰρ πρὸς αὐτοὺς τὸν ἅπαντα χρόνον διετέλεσαν. ἀλλὰ μὲν δὴ οὐδὲ τὴν οὐσίαν ἡμᾶς ἐν τῷ πολέμῳ φήσει κτήσασθαι, εἰς δὲ τὴν πόλιν οὐδὲν ἀνηλωκέναι· πᾶν γὰρ τοὐναντίον, ἐν εἰρήνῃ μὲν ὀγδοηκοντατάλαντος ἡμῶν ὁ οἶκος ἐγένετο, εἰς δὲ τὴν τῆς πόλεως σωτηρίαν ἐν τῷ πολέμῳ ἅπας ἀνηλώθη.", "st": "26.22"}, {"sp": "N", "t": "ἐγὼ δὲ περὶ τούτου τρία ἕξω εἰπεῖν τηλικαῦτα τὸ μέγεθος, ὥστ’ ἄξιον εἶναι ἕκαστον ἔργον θανάτου· πρῶτον μὲν ὅτι τὴν ἐν Βοιωτοῖς πολιτείαν χρήματα λαβὼν μετέστησε καὶ τῆς συμμαχίας ἡμᾶς ταύτης ἀπεστέρησεν, ἔπειτα ὅτι τὰς ναῦς προὔδωκε καὶ τὴν πόλιν περὶ σωτηρίας βουλεύεσθαι πεποίηκεν,", "st": "26.23"}, {"sp": "N", "t": "ἔπειτα ὅτι παρὰ τῶν αἰχμαλώτων, οὓς αὐτὸς ἀπώλεσε, τριάκοντα μνᾶς ἐσυκοφάντησεν, οὐ φάσκων αὐτοὺς λύσεσθαι, εἰ μὴ τοῦτο αὐτῷ παρὰ σφῶν αὐτῶν παράσχοιεν. συνειδότες οὖν ἡμῶν ἑκατέρῳ τὸν βίον, πρὸς ταῦτα βουλεύεσθε ὁποτέρῳ χρὴ πιστεύειν περὶ τῆς Εὐάνδρου δοκιμασίας, καὶ οὕτως οὐκ ἐξαμαρτήσεσθε.", "st": "26.24"}, {"sp": "HDR", "t": "ΚΖʹ. Κατὰ Ἐπικράτους καὶ τῶν συμπρεσβευτῶν ἐπίλογος ὡς Θεόδωρος", "st": "27"}, {"sp": "N", "t": "κατηγόρηται μέν, ὦ ἄνδρες Ἀθηναῖοι, Ἐπικράτους ἱκανὰ καὶ τῶν συμπρεσβευτῶν· ἐνθυμεῖσθαι δὲ χρὴ ὅτι πολλάκις ἠκούσατε τούτων λεγόντων, ὁπότε βούλοιντό τινα ἀδίκως ἀπολέσαι, ὅτι, εἰ μὴ καταψηφιεῖσθε ὧν αὐτοὶ κελεύουσιν, ἐπιλείψει ὑμᾶς ἡ μισθοφορά.", "st": "27.1"}, {"sp": "N", "t": "καὶ νῦν οὐδὲν ἧττον ἐνδεῖ· ὥστε τὸ μὲν πάθος καὶ ἡ αἰσχύνη διὰ τούτων ὑμῖν γίγνεται, ἡ δ’ ὠφέλεια τούτοις· πεπείρανται γὰρ ὅτι, ὁπόταν οὗτοι καὶ οἱ τούτων λόγοι δοκῶσιν αἴτιοι εἶναι ψηφιεῖσθαι ὑμᾶς παρὰ τὸ δίκαιον, ῥᾳδίως παρὰ τῶν ἀδικούντων χρήματα λαμβάνουσι. καίτοι τίνα χρὴ ἐλπίδα ἔχειν σωτηρίας,", "st": "27.2"}, {"sp": "N", "t": "ὁπόταν ἐν χρήμασιν ᾖ καὶ σωθῆναι τῇ πόλει καὶ μή, ταῦτα δὲ οὗτοι, φύλακες ὑφ’ ὑμῶν καταστάντες, οἱ τῶν ἀδικούντων κολασταί, κλέπτωσί τε καὶ καταδωροδοκῶσι; καὶ οὐ νῦν πρῶτον ὤφθησαν ἀδικοῦντες, ἀλλὰ καὶ πρότερον ἤδη δώρων ἐκρίθησαν.", "st": "27.3"}, {"sp": "N", "t": "⟨ὃ⟩ καὶ ὑμῖν ἔχω ἐπικαλέσαι ὅτι τοῦ αὐτοῦ ἀδικήματος Ὀνομάσαντος μὲν κατεψηφίσασθε, τούτου δὲ ἀπεψηφίσασθε, τοῦ αὐτοῦ ἀνδρὸς ἁπάντων κατηγοροῦντος καὶ τῶν αὐτῶν καταμαρτυρούντων, οἳ οὐχ ἑτέρων ἤκουσαν, ἀλλ’ αὐτοὶ ἦσαν οἱ περὶ τῶν χρημάτων καὶ τῶν δώρων πρὸς τούτους πράττοντες.", "st": "27.4"}, {"sp": "N", "t": "καίτοι τοῦτο ἅπαντες ἐπίστασθε, ὅτι οὐχ ὅταν τοὺς μὴ δυναμένους λέγειν κολάζητε, τότε ἔσται παράδειγμα τοῦ μὴ ὑμᾶς ἀδικεῖν, ἀλλ’ ὁπόταν παρὰ τῶν δυναμένων δίκην λαμβάνητε, τότε πάντες παύσονται ἐπιχειροῦντες εἰς ὑμᾶς ἐξαμαρτάνειν.", "st": "27.5"}, {"sp": "N", "t": "νῦν δ’ ἀσφαλῶς αὐτοῖς ἔχει τὰ ὑμέτερα κλέπτειν. ἐὰν μὲν γὰρ λάθωσιν, ἀδεῶς αὐτοῖς ἕξουσι χρῆσθαι· ἐὰν δὲ ὀφθῶσιν, ἢ μέρει τῶν ἀδικημάτων τὸν κίνδυνον ἐξεπρίαντο, ἢ εἰς ἀγῶνα καταστάντες τῇ αὑτῶν δυνάμει ἐσώθησαν. νῦν τοίνυν, ὦ ἄνδρες δικασταί, παράδειγμα ποιήσατε τοῖς ἄλλοις δικαίοις εἶναι, παρὰ τούτων δίκην λαβόντες.", "st": "27.6"}, {"sp": "N", "t": "ἥκουσι δὲ πάντες οἱ τὰ τῆς πόλεως πράττοντες οὐχ ἡμῶν ἀκροασόμενοι, ἀλλ’ ὑμᾶς εἰσόμενοι ἥντινα γνώμην περὶ τῶν ἀδικούντων ἕξετε. ὥστ’ εἰ μὲν ἀποψηφιεῖσθε τούτων, οὐδὲν δεινὸν δόξει αὐτοῖς εἶναι ὑμᾶς ἐξαπατήσαντας ἐκ τῶν ὑμετέρων ὠφελεῖσθαι· ἐὰν δὲ καταψηφισάμενοι θανάτου τιμήσητε, τῇ αὐτῇ ψήφῳ τούς τε ἄλλους κοσμιωτέρους ποιήσετε ἢ νῦν εἰσι, καὶ παρὰ τούτων δίκην εἰληφότες ἔσεσθε.", "st": "27.7"}, {"sp": "N", "t": "ἡγοῦμαι δ’, ὦ ἄνδρες Ἀθηναῖοι, οὐδ’ εἰ μὴ προθέντες αὐτοῖς κρίσιν, ἢ ἀπολογουμένων μὴ ἐθελήσαντες ἀκοῦσαι, καταψηφισάμενοι τῶν ἐσχάτων τιμήσαιτε, οὐκ ἂν ἀκρίτους αὐτοὺς ἀπολωλέναι, ἀλλὰ τὴν προσήκουσαν δίκην δεδωκέναι. οὐ γὰρ οὗτοι ἄκριτοί εἰσι, περὶ ὧν ἂν ὑμεῖς εἰδότες τὰ πραχθέντα ψηφίσησθε, ἀλλ’ οἵτινες ἂν ὑπὸ τῶν ἐχθρῶν διαβληθέντες περὶ ὧν ὑμεῖς μὴ ἴστε, ἀκροάσεως μὴ τύχωσι. τούτων δὲ τὰ μὲν πράγματα κατηγορεῖ, ἡμεῖς δὲ καταμαρτυροῦμεν· καὶ οὐ τοῦτο δέδοικα,", "st": "27.8"}, {"sp": "N", "t": "ὡς ἐὰν ἀκροᾶσθε αὐτῶν ἀποψηφιεῖσθε· ἀλλ’ οὐκ ἂν ἡγοῦμαι αὐτοὺς δίκην ἀξίαν δεδωκέναι, εἰ ἀκροασάμενοι αὐτῶν καταψηφίσαισθε. πῶς γάρ, ὦ ἄνδρες δικασταί, οἷς οὐδὲ ταὐτὰ καὶ ὑμῖν συμφέρει; οὗτοι μὲν γὰρ ἐν τῷ πολέμῳ ἐκ πενήτων πλούσιοι γεγόνασιν ἐκ τῶν ὑμετέρων, ὑμεῖς δὲ διὰ τούτους πένητες.", "st": "27.9"}, {"sp": "N", "t": "καίτοι οὐ ταῦτα ἀγαθῶν δημαγωγῶν ἐστι, τὰ ὑμέτερα ἐν ταῖς ὑμετέραις συμφοραῖς λαμβάνειν, ἀλλὰ τὰ ἑαυτῶν ὑμῖν διδόναι. καὶ γάρ τοι εἰς τοσοῦτον ἥκομεν, ὥσθ’ οἳ πρότερον ἐν τῇ εἰρήνῃ οὐδὲ σφᾶς αὐτοὺς ἐδύναντο τρέφειν, νῦν ὑμῖν εἰσφορὰς εἰσφέρουσι καὶ χορηγοῦσι καὶ οἰκίας μεγάλας οἰκοῦσι.", "st": "27.10"}, {"sp": "N", "t": "καίτοι ἑτέροις ὑμεῖς ἔστιν ὅτε τὰ πατρῷα κεκτημένοις ταῦτα ποιοῦσιν ἐφθονεῖτε· νῦν δ’ οὕτως ἡ πόλις διάκειται, ὥστε οὐκέτι ὧν οὗτοι κλέπτουσιν ὀργίζεσθε, ἀλλ’ ὧν αὐτοὶ λαμβάνετε χάριν ἴστε, ὥσπερ ὑμεῖς τὰ τούτων μισθοφοροῦντες, ἀλλ’ οὐ τούτων τὰ ὑμέτερα κλεπτόντων.", "st": "27.11"}, {"sp": "N", "t": "τὸ δὲ πάντων ὑπερφυέστατον, ὅτι ἐν μὲν τοῖς ἰδίοις ⟨οἱ⟩ ἀδικούμενοι δακρύουσι καὶ ἐλεινοί εἰσιν, ἐν δὲ τοῖς δημοσίοις οἱ μὲν ἀδικοῦντες ἐλεινοί, ὑμεῖς δ’ οἱ ἀδικούμενοι ἐλεεῖτε. καὶ νῦν ἴσως ποιήσουσιν ἅπερ καὶ πρότερον ἦσαν εἰθισμένοι καὶ δημόται καὶ φίλοι, κλαίοντες ἐξαιτεῖσθαι αὐτοὺς παρ’ ὑμῶν.", "st": "27.12"}, {"sp": "N", "t": "ἐγὼ δ’ οὕτως ἀξιῶ γενέσθαι· εἰ μὲν ἀδικεῖν τούτους μηδὲν νομίζουσιν, ἀποδείξαντας ὡς ψευδῆ τὰ κατηγορημένα, οὕτως πείθειν ὑμᾶς ἀποψηφίσασθαι· εἰ δὲ νομίσαντες ἀδικεῖν αἰτήσονται, δῆλον ὅτι τοῖς ἀδικοῦσιν εὐνούστεροί εἰσιν ἢ ὑμῖν τοῖς ἀδικουμένοις, ὥστ’ οὐ χάριτος ἄξιοι τυχεῖν ἀλλὰ τιμωρίας,", "st": "27.13"}, {"sp": "N", "t": "ὁπόταν ὑμεῖς δύνησθε. ἔτι δὲ τοὺς αὐτοὺς ἡγεῖσθαι χρὴ καὶ τῶν κατηγόρων σφόδρα δεδεῆσθαι, νομίζοντας πολὺ ἂν θᾶττον παρ’ ἡμῶν ὀλίγων ὄντων ταύτην τὴν χάριν λαμβάνειν ἢ παρ’ ὑμῶν, ἔτι δὲ ῥᾷον ἄλλους τινὰς ⟨τὰ⟩ ὑμέτερα καταχαρίζεσθαι ἢ ὑμᾶς αὐτούς γε.", "st": "27.14"}, {"sp": "N", "t": "ἡμεῖς μὲν τοίνυν οὐκ ἠθελήσαμεν προδοῦναι, ἀξιοῦμεν δὲ μηδ’ ὑμᾶς, ἐνθυμουμένους ὅτι σφόδρ’ ἂν ἡμῖν ὠργίζεσθε καὶ ἐτιμωρεῖσθε, ὅπου παρεπίπτομεν, ὡς εἰκὸς τοὺς ἀδικοῦντας, εἰ ἡμεῖς παρὰ τούτων ἢ χρήματα λαβόντες ἢ ἄλλῳ τινὶ τρόπῳ διηλλάγημεν. καίτοι εἰ τοῖς μὴ δικαίως ἐπεξιοῦσιν ὀργίζεσθε, ἦ που σφόδρα χρὴ αὐτοὺς τοὺς ἀδικοῦντας τιμωρεῖσθαι.", "st": "27.15"}, {"sp": "N", "t": "νῦν τοίνυν, ὦ ἄνδρες δικασταί, καταψηφισάμενοι Ἐπικράτους τῶν ἐσχάτων τιμήσατε, καὶ μή, ὥσπερ ἐν τῷ τέως χρόνῳ εἰθισμένοι ἐστέ, ἐπειδὰν καταψηφισάμενοι ἐξελέγξητε τοὺς ἀδικοῦντας, ἐν τῷ τιμήματι ἀζημίους ἀφίετε, ἔχθραν, οὐ δίκην παρὰ τῶν ἀδικούντων λαμβάνοντες, ὥσπερ τοῦ ὀνείδους ἀλλ’ οὐ τῆς ζημίας αὐτοῖς μέλον, εὖ εἰδότες ὅτι ἐν μὲν τῇ ψήφῳ οὐδὲν ἄλλο ποιεῖτε ἢ ὀνειδίζετε τοῖς ἀδικοῦσιν, ἐν δὲ τῷ τιμήματι τιμωρεῖσθε τοὺς ἐξαμαρτάνοντας.", "st": "27.16"}, {"sp": "HDR", "t": "ΚΗʹ. Κατὰ Ἐργοκλέους ἐπίλογος", "st": "28"}, {"sp": "N", "t": "τὰ μὲν κατηγορημένα οὕτως ἐστὶ πολλὰ καὶ δεινά, ὦ ἄνδρες Ἀθηναῖοι, ὥστε οὐκ ἄν μοι δοκεῖ δύνασθαι Ἐργοκλῆς ὑπὲρ ἑνὸς ἑκάστου τῶν πεπραγμένων αὐτῷ πολλάκις ἀποθανὼν δοῦναι δίκην ἀξίαν τῷ ὑμετέρῳ πλήθει. καὶ γὰρ πόλεις προδεδωκὼς φαίνεται, καὶ προξένους καὶ πολίτας ὑμετέρους ἠδικηκώς, καὶ ἐκ πένητος ἐκ τῶν ὑμετέρων πλούσιος γεγενημένος.", "st": "28.1"}, {"sp": "N", "t": "καίτοι πῶς αὐτοῖς χρὴ συγγνώμην ἔχειν, ὅταν ὁρᾶτε τὰς μὲν ναῦς, ὧν ἦρχον οὗτοι, δι’ ἀπορίαν χρημάτων καταλυομένας καὶ ἐκ πολλῶν ὀλίγας γιγνομένας, τούτους δὲ πένητας καὶ ἀπόρους ἐκπλεύσαντας οὕτως ταχέως πλείστην τῶν πολιτῶν οὐσίαν κεκτημένους; ὑμέτερον τοίνυν ἔργον ἐστίν, ὦ ἄνδρες Ἀθηναῖοι,", "st": "28.2"}, {"sp": "N", "t": "ἐπὶ τοῖς τοιούτοις ὀργίζεσθαι· καὶ γὰρ δὴ δεινὸν ἂν εἴη, εἰ νῦν μὲν οὕτως αὐτοὶ πιεζόμενοι ταῖς εἰσφοραῖς συγγνώμην τοῖς κλέπτουσι καὶ τοῖς δωροδοκοῦσιν ἔχοιτε, ἐν δὲ τῷ τέως χρόνῳ, καὶ τῶν οἴκων τῶν ὑμετέρων μεγάλων ὄντων καὶ τῶν δημοσίων προσόδων μεγάλων οὐσῶν, θανάτῳ ἐκολάζετε τοὺς τῶν ὑμετέρων ἐπιθυμοῦντας.", "st": "28.3"}, {"sp": "N", "t": "οἶμαι δ’ ἔγωγε πάντας ⟨ἂν⟩ ὑμᾶς ὁμολογῆσαι, εἰ ὑμῖν Θρασύβουλος ἐπηγγέλλετο τριήρεις ἔχων ἐκπλεύσεσθαι καὶ ταύτας παλαιὰς ἀντὶ καινῶν παραδώσειν, καὶ τοὺς μὲν κινδύνους ὑμετέρους ἔσεσθαι, τὰς δ’ ὠφελείας τῶν αὑτοῦ φίλων, καὶ ὑμᾶς μὲν διὰ τὰς εἰσφορὰς πενεστέρους ἀποδείξειν, Ἐργοκλέα δὲ καὶ τοὺς κόλακας τοὺς αὑτοῦ πλουσιωτάτους τῶν πολιτῶν ποιήσειν, οὐδένα ἂν ὑμῶν ἐπιτρέψαι τὰς ναῦς ἐκεῖνον ἔχοντα ἐκπλεῦσαι,", "st": "28.4"}, {"sp": "N", "t": "ἄλλως τε ἐπειδή, ὡς τάχιστα ὑμεῖς ἐψηφίσασθε τὰ χρήματα ὑπογράψαι τὰ ἐκ τῶν πόλεων εἰλημμένα καὶ τοὺς ἄρχοντας τοὺς μετ’ ἐκείνου καταπλεῖν εὐθύνας δώσοντας, Ἐργοκλῆς ἔλεγεν ὡς ἤδη συκοφαντεῖτε καὶ τῶν ἀρχαίων νόμων ἐπιθυμεῖτε, καὶ Θρασυβούλῳ συνεβούλευε Βυζάντιον καταλαβεῖν καὶ τὰς ναῦς ἔχειν καὶ τὴν Σεύθου θυγατέρα γαμεῖν·", "st": "28.5"}, {"sp": "N", "t": "“ἵνα αὐτῶν ἐκκόψῃς” ἔφη “τὰς συκοφαντίας· ποιήσεις γὰρ αὐτοὺς οὐκ ἐπιβουλεύοντας σοὶ καθῆσθαι καὶ τοῖς σοῖς φίλοις, ἀλλὰ περὶ αὑτῶν δεδιέναι.” οὕτως, ὦ ἄνδρες Ἀθηναῖοι, ἐπειδὴ τάχιστα ἐνεπέπληντο καὶ ⟨τῶν⟩ ὑμετέρων ἀπέλαυσαν, ἀλλοτρίους τῆς πόλεως αὑτοὺς ἡγήσαντο.", "st": "28.6"}, {"sp": "N", "t": "ἅμα γὰρ πλουτοῦσι καὶ ὑμᾶς μισοῦσι, καὶ οὐκέτι ὡς ἀρξόμενοι παρασκευάζονται ἀλλ’ ὡς ὑμῶν ἄρξοντες, καὶ δεδιότες ὑπὲρ ὧν ἀφῄρηνται ἕτοιμοί εἰσι καὶ χωρία καταλαμβάνειν καὶ ὀλιγαρχίαν καθιστάναι καὶ πάντα πράττειν ὅπως ὑμεῖς ἐν τοῖς δεινοτάτοις κινδύνοις καθ’ ἑκάστην ἡμέραν ἔσεσθε· οὕτως γὰρ ἡγοῦνται οὐκέτι τοῖς σφετέροις αὐτῶν ἁμαρτήμασι τὸν νοῦν ὑμᾶς προσέξειν, ἀλλ’ ὑπὲρ ὑμῶν αὐτῶν καὶ τῆς πόλεως ὀρρωδοῦντας ἡσυχίαν πρὸς τούτους ἕξειν.", "st": "28.7"}, {"sp": "N", "t": "Θρασύβουλος μὲν οὖν ὦ ἄνδρες Ἀθηναῖοι, (οὐδὲν γὰρ δεῖ περὶ αὐτοῦ πλείω λέγειν) καλῶς ἐποίησεν οὕτως τελευτήσας τὸν βίον· οὐ γὰρ ἔδει αὐτὸν οὔτε ζῆν τοιούτοις ἔργοις ἐπιβουλεύοντα, οὔθ’ ὑφ’ ὑμῶν ἀποθανεῖν ἤδη τι δοκοῦντα ὑμᾶς ἀγαθὸν πεποιηκέναι, ἀλλὰ τοιούτῳ τρόπῳ τῆς πόλεως ἀπαλλαγῆναι.", "st": "28.8"}, {"sp": "N", "t": "ὁρῶ δ’ αὐτοὺς διὰ τὴν πρῴην ἐκκλησίαν οὐκέτι φειδομένους τῶν χρημάτων, ἀλλ’ ὠνουμένους τὰς αὑτῶν ψυχὰς καὶ παρὰ τῶν λεγόντων καὶ παρὰ τῶν ἐχθρῶν καὶ παρὰ τῶν πρυτάνεων, καὶ πολλοὺς Ἀθηναίων ἀργυρίῳ διαφθείροντας. ὑπὲρ ὧν ὑμῖν ἄξιόν ἀπολογήσασθαι παρὰ τούτου νῦν δίκην λαβοῦσι, καὶ πᾶσιν ἀνθρώποις ἐπιδεῖξαι ὅτι οὐκ ἔστι τοσαῦτα χρήματα, ὧν ὑμεῖς ἡττήσεσθε ὥστε μὴ τιμωρεῖσθαι τοὺς ἀδικοῦντας.", "st": "28.9"}, {"sp": "N", "t": "ἐνθυμεῖσθε γάρ, ὦ ἄνδρες Ἀθηναῖοι, ὅτι οὐκ Ἐργοκλῆς μόνος κρίνεται, ἀλλὰ καὶ ἡ πόλις ὅλη. νυνὶ γὰρ τοῖς ἄρχουσι τοῖς ὑμετέροις ἐπιδείξετε πότερον χρὴ δικαίους εἶναι, ἢ ὡς πλεῖστα τῶν ὑμετέρων ὑφελομένους τῷ αὐτῷ τρόπῳ τὴν σωτηρίαν παρασκευάζεσθαι, ᾧπερ οὗτοι νυνὶ πειρῶνται. καίτοι εὖ εἰδέναι χρή,", "st": "28.10"}, {"sp": "N", "t": "ὦ ἄνδρες Ἀθηναῖοι. ὅστις ἐν τοσαύτῃ ἀπορίᾳ τῶν ὑμετέρων πραγμάτων ἢ πόλεις προδίδωσιν ἢ χρήματα κλέπτειν ἢ δωροδοκεῖν ἀξιοῖ, οὗτος καὶ τὰ τείχη καὶ τὰς ναῦς τοῖς πολεμίοις παραδίδωσι καὶ ὀλιγαρχίαν ἐκ δημοκρατίας καθίστησιν· ὥστ’ οὐκ ἄξιον ὑμῖν τῆς τούτων παρασκευῆς ἡττᾶσθαι, ἀλλὰ παράδειγμα πᾶσιν ἀνθρώποις ποιῆσαι καὶ μήτε κέρδος μήτε ἔλεον μήτ’ ἄλλο μηδὲν περὶ πλείονος ποιήσασθαι τῆς τούτων τιμωρίας.", "st": "28.11"}, {"sp": "N", "t": "οἶμαι δ’ Ἐργοκλέα, ὦ ἄνδρες Ἀθηναῖοι, περὶ μὲν Ἁλικαρνασσοῦ καὶ περὶ τῆς ἀρχῆς καὶ περὶ τῶν αὑτῷ πεπραγμένων οὐκ ἐπιχειρήσειν ἀπολογεῖσθαι, ἐρεῖν δὲ ὡς ἀπὸ Φυλῆς κατῆλθε καὶ ὡς δημοτικός ἐστι καὶ ὡς τῶν κινδύνων τῶν ὑμετέρων μετέσχεν. ἐγὼ δέ, ὦ ἄνδρες Ἀθηναῖοι, ⟨οὐ⟩", "st": "28.12"}, {"sp": "N", "t": "τοιαύτην γνώμην ἔχω περὶ τῶν τοιούτων· ἀλλ’ ὅσοι μὲν ἐλευθερίας καὶ τοῦ δικαίου ἐπιθυμοῦντες καὶ τοὺς νόμους ἰσχύειν βουλόμενοι καὶ τοὺς ἀδικοῦντας μισοῦντες τῶν ὑμετέρων κινδύνων μετέσχον, οὐ πονηροὺς εἶναι πολίτας, οὐδὲ ἀδίκως τούτοις φημι ἂν εἶναι ὑπόλογον τὴν ἐκείνων φυγήν· ὅσοι δὲ κατελθόντες ἐν δημοκρατία τὸ μὲν ὑμέτερον πλῆθος ἀδικοῦσι, τοὺς δὲ ἰδίους οἴκους ἐκ τῶν ὑμετέρων μεγάλους ποιοῦσι, πολὺ μᾶλλον αὐτοῖς προσήκει ὀργίζεσθαι ἤ τοῖς τριάκοντα.", "st": "28.13"}, {"sp": "N", "t": "οἱ μὲν γὰρ ἐπὶ τοῦτ’ ἐχειροτονήθησαν, ἵνα κακῶς, εἴ πῃ δύναιντο, ὑμᾶς ποιήσειαν· τούτοις δ’ ὑμᾶς αὐτοὺς ἐπετρέψατε, ὡς μεγάλην καὶ ἐλευθέραν τὴν πόλιν ποιήσωσιν· ὧν ὑμῖν οὐδὲν ἀποβέβηκεν, ἀλλὰ τὸ ἐπὶ τούτοις εἶναι ἐν τοῖς δεινοτάτοις κινδύνοις καθεστήκατε, ὥστε πολὺ ἂν δικαιότερον ὑμᾶς αὐτοὺς ἢ τούτους ἐλεοῖτε, καὶ τοὺς ὑμετέρους παῖδας καὶ γυναῖκας, ὅτι ὑπὸ τοιούτων ἀνδρῶν λυμαίνεσθε.", "st": "28.14"}, {"sp": "N", "t": "ὅταν γὰρ ἡγησώμεθα σωτηρίας ἀντειλῆφθαι, δεινότερα ὑπὸ τῶν ἡμετέρων ἀρχόντων πάσχομεν ἢ ὑπὸ τῶν πολεμίων. καίτοι πάντες ἐπίστασθε ὅτι οὐδεμία ἐλπὶς σωτηρίας ὑμῖν δυστυχήσασιν. ὥστε ἄξιον ὑμᾶς παρακελευσαμένους ὑμῖν αὐτοῖς παρὰ τούτων νυνὶ τὴν μεγίστην δίκην λαβεῖν, καὶ τοῖς ἄλλοις Ἕλλησιν ἐπιδεῖξαι ὡς τοὺς ἀδικοῦντας τιμωρεῖσθε, καὶ τοὺς ὑμετέρους ἄρχοντας βελτίους ποιήσετε.", "st": "28.15"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ταῦθ’ ὑμῖν παρακελεύομαι· ὑμᾶς δὲ χρὴ εἰδέναι ὅτι, ἐὰν μὲν ἐμοὶ πεισθῆτε, εὖ περὶ αὑτῶν βουλεύσεσθε, εἰ δὲ μή, χείροσι τοῖς ἄλλοις πολίταις χρήσεσθε. ἔτι δέ, ὦ ἄνδρες Ἀθηναῖοι, ἐὰν αὐτῶν ἀποψηφίσησθε, οὐδεμίαν ὑμῖν εἴσονται χάριν, ἀλλὰ τοῖς ἀνηλωμένοις καὶ τοῖς χρήμασιν οἷς ὑφῄρηνται· ὥστε τὴν μὲν ἔχθραν ὑμῖν αὐτοῖς καταλείψετε, τῆς δὲ σωτηρίας ἐκείνοις εἴσονται χάριν.", "st": "28.16"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες Ἀθηναῖοι, καὶ Ἁλικαρνασσεῖς καὶ οἱ ἄλλοι οἱ ὑπὸ τούτων ἠδικημένοι, ἐὰν μὲν παρὰ τούτων τὴν μεγίστην δίκην λάβητε, νομιοῦσιν ὑπὸ τούτων μὲν ἀπολωλέναι, ὑμᾶς δὲ αὑτοῖς βεβοηθηκέναι· ἐὰν δὲ τούτους σώσητε, ἡγήσονται καὶ ὑμᾶς ὁμογνώμονας γεγονέναι τοῖς αὑτοὺς προδεδωκόσιν. ὥστ’ ἄξιον τούτων ἁπάντων ἐνθυμηθέντας ἅμα τοῖς τε φίλοις τοῖς ὑμετέροις ἀποδοῦναι χάριν καὶ παρὰ τῶν ἀδικούντων τὴν δίκην λαβεῖν.", "st": "28.17"}, {"sp": "HDR", "t": "ΚΘʹ. Κατὰ Φιλοκράτους ἐπίλογος", "st": "29"}, {"sp": "N", "t": "ὁ μὲν ἀγὼν οὗτος, ὦ ἄνδρες δικασταί, ἐρημότερος γεγένηται ἢ ἐγὼ προσεδόκων. πολλοὶ γὰρ ἦσαν οἱ ἀπειλοῦντες καὶ οἱ φάσκοντες Φιλοκράτους κατηγορήσειν· ὧν οὐδεὶς νυνὶ φαίνεται. ὃ κἀμοὶ δοκεῖ οὐδενὸς ἔλαττον εἶναι τεκμήριον τῆς ἀπογραφῆς ὅτι ἀληθὴς οὖσα τυγχάνει· εἰ γὰρ μὴ πολλὰ τῶν Ἐργοκλέους εἶχε χρημάτων, οὐκ ἂν οὕτως οἷός τ’ ἦν ἀπαλλάξαι τοὺς κατηγόρους.", "st": "29.1"}, {"sp": "N", "t": "ἐγὼ δέ, ὦ ἄνδρες δικασταί, πάντας ὑμᾶς ἡγοῦμαι εἰδέναι ὅτι Ἐργοκλέους διὰ τοῦτο ὑμεῖς θάνατον κατεχειροτονήσατε, ὅτι κακῶς διαθεὶς τὰ τῆς πόλεως πλέον ἢ τριάκοντα ταλάντων οὐσίαν ἐκτήσατο. καὶ τούτων τῶν χρημάτων οὐδὲν ἐν τῇ πόλει φαίνεται. καίτοι ποῖ χρὴ τραπέσθαι ἢ ποῦ ζητῆσαι τὰ χρήματα; εἰ γὰρ παρὰ τοῖς κηδεσταῖς καὶ οἷς ἐκεῖνος οἰκειότατ’ ἀνθρώπων ἐχρῆτο μὴ φανήσεται, χαλεπῶς παρὰ τοῖς ἐχθροῖς εὑρεθήσεται.", "st": "29.2"}, {"sp": "N", "t": "τίνα δὲ Ἐργοκλῆς περὶ πλείονος Φιλοκράτους ἐποιεῖτο, ἢ πρὸς τίν’ ἀνθρώπων διέκειτο οἰκειότερον; οὐ τῶν μὲν ὑμετέρων ὁπλιτῶν αὐτὸν ἐξήγαγε, τῶν δ’ αὑτοῦ χρημάτων ταμίαν ἐποίησε, καὶ τὸ τελευταῖον τριήραρχον αὐτὸν κατέστησε;", "st": "29.3"}, {"sp": "N", "t": "καίτοι δεινὸν εἰ οἱ μὲν τὰς οὐσίας ἔχοντες ὀλοφύρονται τριηραρχοῦντες, οὗτος δὲ οὐδὲν πρότερον κεκτημένος ἐν ἐκείνῳ τῷ χρόνῳ ἐθελοντὴς ὑπέστη ταύτην τὴν λῃτουργίαν. οὐκοῦν δὴ οὐχ ὡς ζημιωθησόμενον αὐτὸν τριήραρχον κατέστησεν, ἀλλ’ ὡς ὠφεληθησόμενον καὶ φυλάξοντα τὰ αὑτοῦ χρήματα, οὐκ ἔχων ὅτῳ χρὴ μᾶλλον τούτου πιστεῦσαι. ἡγοῦμαι δέ,", "st": "29.4"}, {"sp": "N", "t": "ὦ ἄνδρες δικασταί, Φιλοκράτει δύο εἶναι καὶ μόνας ἀπολογίας· προσήκειν γὰρ αὐτῷ ἀποδεῖξαι ἢ ἑτέρους ἔχοντας τὰ Ἐργοκλέους χρήματα, ἢ ἀδίκως ἀπολωλότα ἐκεῖνον καὶ οὐδὲν ὑφῃρημένον τῶν ὑμετέρων οὐδὲ δεδωροδοκηκότα· εἰ δὲ τούτων μηδέτερον ποιήσει, δεδόχθαι καταψηφίζεσθαι, καὶ μὴ τοῖς μὲν παρὰ τῶν ἄλλων λαμβάνουσιν ὀργίζεσθαι, τοῖς δὲ τὰ ὑμέτερ’ αὐτῶν ἔχουσι συγγνώμην ἔχειν.", "st": "29.5"}, {"sp": "N", "t": "τίς δ’ οὐκ οἶδεν Ἀθηναίων τρία τάλαντα περὶ Ἐργοκλέους μεσεγγυηθέντα τοῖς λέγουσιν, εἰ δύναιντο αὐτὸν σῶσαι [καὶ μὴ κατηγορεῖν]; οἳ ἐπειδὴ ἑώρων τὴν ὑμετέραν ὀργὴν τιμωρεῖσθαι βουλομένην, ἡσυχίαν ἦγον καὶ οὐκ ἐτόλμων σφᾶς αὐτοὺς φανεροὺς ποιῆσαι. καὶ τὸ μὲν πρῶτον οὗτος οὐ κομιζόμενος παρ’ αὐτῶν τὰ χρήματα μηνύσειν ἔφη τῇ πόλει·", "st": "29.6"}, {"sp": "N", "t": "ἐπειδὴ δὲ καὶ ταῦτα ἀπείληφε καὶ τῶν ἄλλων τῶν ἐκείνου κύριος γεγένηται, εἰς τοῦτο τόλμης ἐλήλυθεν, ὥστε μάρτυρας πεπόρισται οἳ μαρτυρήσουσιν αὐτῷ ὡς ἦν ἔχθιστος ἁπάντων ἀνθρώπων Ἐργοκλεῖ. καίτοι οἴεσθ’ ἂν αὐτόν, ὦ ἄνδρες δικασταί, εἰς τοῦτο μανίας ἀφικέσθαι, ὥστε Θρασυβούλου στρατηγοῦντος καὶ Ἐργοκλέους αὐτῷ διαφερομένου ἐθελοντὴν ὑποστῆναι τριήραρχον; πῶς γὰρ ἂν θᾶττον ἀπώλετο, ἢ πῶς ἂν μᾶλλον ἐπηρεάζετο;", "st": "29.7"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων ἱκανὰ τὰ εἰρημένα· ἐγὼ δ’ ὑμᾶς ἀξιῶ ὑμῖν αὐτοῖς βοηθῆσαι, καὶ πολὺ μᾶλλον τοὺς ἀδικοῦντας τιμωρεῖσθαι ἢ τοὺς τὰ τῆς πόλεως ἔχοντας ἐλεινοὺς ἡγεῖσθαι. οὐδὲν γὰρ τῶν αὑτοῦ καταθήσει, ἀλλὰ τὰ ὑμέτερα ὑμῖν αὐτοῖς ἀποδώσει, καὶ πολλῷ πλείω αὐτῷ τούτων περιέσται.", "st": "29.8"}, {"sp": "N", "t": "καὶ γὰρ ἂν καὶ δεινὸν εἴη, ὦ ἄνδρες δικασταί, εἰ τοῖς μὲν μὴ δυναμένοις τὰ σφέτερ’ αὐτῶν εἰσφέρειν ὀργίζοισθε καὶ τὰς οὐσίας αὐτῶν ὡς ἀδικούντων δημεύοιτε, τοὺς δὲ τὰ ὑμέτερα αὐτῶν ἔχοντας μὴ τιμωροῖσθε, ἀλλὰ τῶν τε χρημάτων ἀποστεροῖσθε καὶ τούτους χαλεπωτέρους ἐχθροὺς ἔχοιτε.", "st": "29.9"}, {"sp": "N", "t": "ἕως γὰρ ἂν τὰ ὑμέτερα ἔχοντες σφίσιν αὐτοῖς συνειδῶσιν, οὐδέποτε ὑμῖν παύσονται κακονοοῦντες, νομίζοντες τὰς τῆς πόλεως δυστυχίας μόνας ἀπαλλαγὴν εἶναι τῶν πρὸς αὐτοὺς πραγμάτων.", "st": "29.10"}, {"sp": "N", "t": "ἡγοῦμαι δ’, ὦ ἄνδρες δικασταί, οὐ μόνον περὶ χρημάτων αὐτῷ προσήκειν ἀγωνίζεσθαι, ἀλλὰ καὶ περὶ τοῦ σώματος κινδυνεύειν. καὶ γὰρ ἂν καὶ δεινὸν εἴη, εἰ οἱ μὲν τὰ τῶν ἰδιωτῶν ἀπολλύμενα τοῖς κλέπταις συνειδότες τοῖς αὐτοῖς ἐνέχοιντο, οὗτος δὲ τὰ τῆς πόλεως Ἐργοκλεῖ συνειδὼς κλέπτοντι καὶ ἐπὶ τοῖς ὑμετέροις δωροδοκοῦντι μὴ τῆς αὐτῆς τιμωρίας τυγχάνοι, ἀλλὰ ἆθλα λάβοι τὴν ὑπ’ ἐκείνου καταλειφθεῖσαν οὐσίαν ἀντὶ τῆς αὑτοῦ πονηρίας. ἄξιοι δ’ ὑμῖν εἰσιν ὀργῆς, ὦ ἄνδρες δικασταί.", "st": "29.11"}, {"sp": "N", "t": "οὗτοι γάρ, ὅτε Ἐργοκλῆς ἐκρίνετο, ἐν τῷ δήμῳ περιιόντες ἔλεγον ὡς πεντακόσιοι μὲν αὐτοῖς εἴησαν ἐκ τοῦ Πειραιῶς δεδεκασμένοι, ἑξακόσιοι δὲ καὶ χίλιοι ἐκ τοῦ ἄστεως· μᾶλλον δὲ προσεποιοῦντο πιστεύειν τοῖς χρήμασιν ἢ δεδιέναι τὰ αὑτῶν ἁμαρτήματα.", "st": "29.12"}, {"sp": "N", "t": "ἐκεῖ μὲν οὖν ἐπεδείξατε αὐτοῖς, ἐὰν δὲ εὖ φρονῆτε, καὶ νυνὶ τοῦτο φανερὸν πᾶσιν ἀνθρώποις ποιήσετε, ὅτι οὐκ ἔστι τοσαῦτα χρήματα ἃ ὑμᾶς, οὓς ἂν λαμβάνητε ἀδικοῦντας, ἀποτρέψει τιμωρεῖσθαι, καὶ μηδεμίαν αὐτοῖς ἄδειαν δώσετε τὰ ὑμέτερα αὐτῶν διαρπάζουσι καὶ κλέπτουσιν.", "st": "29.13"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ταῦτα ὑμῖν παραινῶ. πάντες γὰρ ἐπίστασθε ὅτι Ἐργοκλῆς χρηματιούμενος ἀλλ’ οὐ πρὸς ὑμᾶς φιλοτιμησόμενος ἐξέπλευσε, καὶ οὐδεὶς ἄλλος ἔχει τὰ χρήματα ἢ οὗτος. ἐὰν οὖν σωφρονῆτε, τὰ ὑμέτερ’ αὐτῶν κομιεῖσθε.", "st": "29.14"}, {"sp": "HDR", "t": "Λʹ. Κατὰ Νικομάχου γραμματέως εὐθυνῶν κατηγορία", "st": "30"}, {"sp": "N", "t": "ἤδη, ὦ ἄνδρες δικασταί, τινὲς εἰς κρίσιν καταστάντες ἀδικεῖν μὲν ἔδοξαν, ἀποφαίνοντες δὲ τὰς τῶν προγόνων ἀρετὰς καὶ τὰς σφετέρας αὐτῶν εὐεργεσίας συγγνώμης ἔτυχον παρ’ ὑμῶν. ἐπειδὴ τοίνυν καὶ τῶν ἀπολογουμένων ἀποδέχεσθε, ἐάν τι ἀγαθὸν φαίνωνται τὴν πόλιν πεποιηκότες, ἄξιον καὶ τῶν κατηγόρων ὑμᾶς ἀκροάσασθαι, ἐὰν ἀποφαίνωσι τοὺς φεύγοντας πάλαι πονηροὺς ὄντας. ὅτι μὲν τοίνυν ὁ πατὴρ ὁ Νικομάχου δημόσιος ἦν,", "st": "30.1"}, {"sp": "N", "t": "καὶ οἷα νέος ὢν οὗτος ἐπετήδευσε, καὶ ὅσα ἔτη γεγονὼς εἰς τοὺς φράτερας εἰσήχθη, πολὺ ἂν ἔργον εἴη, λέγειν· ἐπειδὴ δὲ τῶν νόμων ἀναγραφεὺς ἐγένετο, τίς οὐκ οἶδεν οἷα τὴν πόλιν ἐλυμήνατο; προσταχθὲν γὰρ αὐτῷ τεττάρων μηνῶν ἀναγράψαι τοὺς νόμους τοὺς Σόλωνος, ἀντὶ μὲν Σόλωνος αὑτὸν νομοθέτην κατέστησεν, ἀντὶ δὲ τεττάρων μηνῶν ἑξέτη τὴν ἀρχὴν ἐποιήσατο, καθ’ ἑκάστην δὲ ἡμέραν ἀργύριον λαμβάνων τοὺς μὲν ἐνέγραφε τοὺς δὲ ἐξήλειφεν.", "st": "30.2"}, {"sp": "N", "t": "εἰς τοῦτο δὲ κατέστημεν ὥστε ἐκ τῆς τούτου χειρὸς ἐταμιευόμεθα τοὺς νόμους καὶ οἱ ἀντίδικοι ἐπὶ τοῖς δικαστηρίοις ἐναντίους παρείχοντο, ἀμφότεροι παρὰ Νικομάχου φάσκοντες εἰληφέναι. ἐπιβαλλόντων δὲ τῶν ἀρχόντων ἐπιβολὰς καὶ εἰσαγόντων εἰς τὸ δικαστήριον οὐκ ἠθέλησε παραδοῦναι τοὺς νόμους· ἀλλὰ πρότερον ἡ πόλις εἰς τὰς μεγίστας συμφορὰς κατέστη, πρὶν τοῦτον ἀπαλλαγῆναι τῆς ἀρχῆς καὶ τῶν πεπραγμένων εὐθύνας ὑποσχεῖν.", "st": "30.3"}, {"sp": "N", "t": "καὶ γάρ τοι, ὦ ἄνδρες δικασταί, ἐπειδὴ ἐκείνων δίκην οὐ δέδωκεν, ὁμοίαν καὶ νῦν τὴν ἀρχὴν κατεστήσατο, ὅστις πρῶτον μὲν τέτταρα ἔτη ἀνέγραψεν, ἐξὸν αὐτῷ τριάκοντα ἡμερῶν ἀπαλλαγῆναι· ἔπειτα διωρισμένον ἐξ ὧν ἔδει ἀναγράφειν, αὑτὸν ἁπάντων κύριον ἐποιήσατο, καὶ ὅσα ⟨οὐδεὶς πώποτε⟩ διαχειρίσας μόνος οὗτος τῶν ἀρξάντων εὐθύνας οὐκ ἔδωκεν,", "st": "30.4"}, {"sp": "N", "t": "ἀλλ’ οἱ μὲν ἄλλοι τῆς αὑτῶν ἀρχῆς κατὰ πρυτανείαν λόγον ἀποφέρουσι, σὺ δέ, ὦ Νικόμαχε, οὐδὲ τεττάρων ἐτῶν ἠξίωσας ἐγγράψαι, ἀλλὰ μόνῳ σοὶ τῶν πολιτῶν ἐξεῖναι νομίζεις ἄρχειν πολὺν χρόνον, καὶ μήτε εὐθύνας διδόναι μήτε τοῖς ψηφίσμασι πείθεσθαι μήτε τῶν νόμων φροντίζειν, ἀλλὰ τὰ μὲν ἐγγράφεις τὰ δ’ ἐξαλείφεις, καὶ εἰς τοῦτο ὕβρεως ἥκεις ὥστε σαυτοῦ νομίζεις εἶναι τὰ τῆς πόλεως,", "st": "30.5"}, {"sp": "N", "t": "αὐτὸς δημόσιος ὤν. ὑμᾶς τοίνυν χρή, ὦ ἄνδρες δικασταί, ἀναμνησθέντας καὶ τῶν προγόνων τῶν Νικομάχου, οἵτινες ἦσαν, καὶ οὗτος ὡς ἀχαρίστως ὑμῖν προσενήνεκται παρανομήσας, κολάσαι αὐτόν, καὶ ἐπειδὴ ἑνὸς ἑκάστου δίκην οὐκ εἰλήφατε, νῦν ὑπὲρ ἁπάντων γοῦν τὴν τιμωρίαν ποιήσασθαι.", "st": "30.6"}, {"sp": "N", "t": "ἴσως δέ, ὦ ἄνδρες δικασταί, ἐπειδὰν περὶ αὑτοῦ μηδὲν δύνηται ἀπολογεῖσθαι, ἐμὲ διαβάλλειν πειράσεται. τότε δὲ περὶ τῶν ἐμῶν τούτῳ ἀξιῶ πιστεύειν ὑμᾶς, ὁπόταν ἀπολογίας ἐμοὶ δοθείσης μὴ δύνωμαι ψευδόμενον αὐτὸν ἐξελέγξαι. ἐὰν δ’ ἄρα ἐπιχειρῇ λέγειν ἅπερ ἐν τῇ βουλῇ, ὡς ἐγὼ τῶν τετρακοσίων ἐγενόμην, ἐνθυμεῖσθε ὅτι ἐκ τῶν τοιαῦτα λεγόντων τῶν τετρακοσίων πλεῖν ἢ χίλιοι γενήσονται· καὶ γὰρ τοὺς ἔτι παῖδας ὄντας ἐν ἐκείνῳ τῷ χρόνῳ καὶ τοὺς ἀποδημοῦντας οἱ διαβάλλειν βουλόμενοι ταῦτα λοιδοροῦσιν.", "st": "30.7"}, {"sp": "N", "t": "ἐγὼ δὲ οὕτω πολλοῦ ἐδέησα τῶν τετρακοσίων γενέσθαι, ὥστε οὐδὲ τῶν πεντακισχιλίων κατελέγην. δεινὸν δέ μοι δοκεῖ εἶναι ὅτι, εἰ μὲν περὶ ἰδίων συμβολαίων ἀγωνιζόμενος οὕτω φανερῶς ἐξήλεγχον αὐτὸν ἀδικοῦντα, οὐδ’ ἂν αὐτὸς ἠξίωσε τοιαῦτα ἀπολογούμενος ἀποφεύγειν, νυνὶ δὲ περὶ τῶν τῆς πόλεως κρινόμενος οἰήσεται χρῆναι ἐμοῦ κατηγορῶν ὑμῖν μὴ δοῦναι δίκην.", "st": "30.8"}, {"sp": "N", "t": "ἔτι δὲ εἶναι θαυμαστὸν νομίζω Νικόμαχον ἑτέροις ἀδίκως μνησικακεῖν ἀξιοῦν, ὃν ἐγὼ ἐπιβουλεύσαντα τῷ πλήθει ἀποδείξω. καί μου ἀκούσατε· δίκαιον γάρ, ὦ ἄνδρες δικασταί, περὶ τῶν τοιούτων ἀνθρώπων τὰς τοιαύτας κατηγορίας ἀποδέχεσθαι, οἵτινες τότε συγκαταλύσαντες τὸν δῆμον νυνὶ δημοτικοί φασιν εἶναι.", "st": "30.9"}, {"sp": "N", "t": "ἐπειδὴ γὰρ ἀπολομένων τῶν νεῶν ἡ μετάστασις ἐπράττετο, Κλεοφῶν τὴν βουλὴν ἐλοιδόρει, φάσκων συνεστάναι καὶ ⟨οὐ⟩ τὰ βέλτιστα βουλεύειν τῇ πόλει. Σάτυρος δ’ ὁ Κηφισιεὺς βουλεύων ἔπεισε τὴν βουλὴν δήσαντας αὐτὸν παραδοῦναι δικαστηρίῳ. οἱ δὲ βουλόμενοι αὐτὸν ἀπολέσαι,", "st": "30.10"}, {"sp": "N", "t": "δεδιότες μὴ οὐκ ἀποκτείνωσιν ἐν τῷ δικαστηρίῳ, πείθουσι Νικόμαχον νόμον ἀποδεῖξαι ὡς χρὴ καὶ τὴν βουλὴν συνδικάζειν. καὶ ὁ πάντων οὗτος πονηρότατος οὕτως φανερῶς συνεστασίασεν, ὥστε τῇ ἡμέρᾳ ᾗ ἡ κρίσις ἐγένετο ἀποδεῖξαι τὸν νόμον.", "st": "30.11"}, {"sp": "N", "t": "Κλεοφῶντος τοίνυν, ὦ ἄνδρες δικασταί, ἕτερα μὲν ἄν τις ἔχοι κατηγορῆσαι· τοῦτο δὲ παρὰ πάντων ὁμολογεῖται, ὅτι οἱ καταλύοντες τὸν δῆμον ἐκεῖνον ἐβούλοντο μάλιστα τῶν πολιτῶν ἐκποδὼν γενέσθαι, καὶ ὅτι Σάτυρος καὶ Χρέμων οἱ τῶν τριάκοντα γενόμενοι οὐχ ὑπὲρ ὑμῶν ὀργιζόμενοι Κλεοφῶντος κατηγόρουν, ἀλλ’ ἵνα ἐκεῖνον ἀποκτείναντες αὐτοὶ αὑτοὶ ὑμᾶς κακῶς ποιῶσι.", "st": "30.12"}, {"sp": "N", "t": "καὶ ταῦτα διεπράξαντο διὰ τὸν νόμον ὃν Νικόμαχος ἀπέδειξεν. εἰκὸς τοίνυν, ὦ ἄνδρες δικασταί, ἐνθυμεῖσθαι καὶ ὁπόσοι ὑμῶν ἐνόμιζον Κλεοφῶντα κακὸν πολίτην εἶναι, ὅτι καὶ τῶν ἐν τῇ ὀλιγαρχίᾳ ἀποθανόντων ἴσως τις ἦν πονηρός, ἀλλ’ ὅμως καὶ διὰ τοὺς τοιούτους ὠργίζεσθε τοῖς τριάκοντα, ὅτι οὐ τῶν ἀδικημάτων ἕνεκα ἀλλὰ κατὰ στάσιν αὐτοὺς ἀπέκτειναν.", "st": "30.13"}, {"sp": "N", "t": "ἐὰν οὖν πρὸς ταῦτα ἀπολογῆται, τοσοῦτον μέμνησθε, ὅτι ἐν τοιούτῳ καιρῷ τὸν νόμον ἀπέδειξεν ἐν ᾧ ἡ πολιτεία μεθίστατο, καὶ τούτοις χαριζόμενος οἳ τὸν δῆμον κατέλυσαν, καὶ ταύτην τὴν βουλὴν συνδικάζειν ἐποίησεν ἐν ᾗ Σάτυρος μὲν καὶ Χρέμων μέγιστον ἐδύναντο, Στρομβιχίδης δὲ καὶ Καλλιάδης καὶ ἕτεροι πολλοὶ καὶ καλοὶ κἀγαθοὶ τῶν πολιτῶν ἀπώλλυντο.", "st": "30.14"}, {"sp": "N", "t": "καὶ περὶ τούτων οὐδένα ἂν ἐποιησάμην λόγον, εἰ μὴ ᾐσθανόμην αὐτὸν ὡς δημοτικὸν ὄντα πειρασόμενον παρὰ τὸ δίκαιον σῴζεσθαι, καὶ τῆς εὐνοίας τῆς εἰς τὸ πλῆθος τεκμηρίῳ χρησόμενον ὅτι ἔφυγεν. ἐγὼ δὲ καὶ ἑτέρους ἂν ἔχοιμι ἐπιδεῖξαι τῶν συγκαταλυσάντων τὸν δῆμον τοὺς μὲν ἀποθανόντας, τοὺς δὲ φυγόντας τε καὶ οὐ μετασχόντας τῆς πολιτείας,", "st": "30.15"}, {"sp": "N", "t": "ὥστε οὐδένα εἰκὸς αὐτῷ τούτου ὑπόλογον γενέσθαι. τοῦ μὲν γὰρ ὑμᾶς φυγεῖν μέρος τι καὶ οὗτος συνεβάλετο, τοῦ δὲ τοῦτον κατελθεῖν τὸ πλῆθος τὸ ὑμέτερον αἴτιον ἐγένετο. ἔτι δὲ καὶ δεινόν, εἰ ὧν μὲν ἄκων ἔπαθε χάριν αὐτῷ εἴσεσθε, ὧν δ’ ἑκὼν ἐξήμαρτε μηδεμίαν τιμωρίαν ποιήσεσθε.", "st": "30.16"}, {"sp": "N", "t": "πυνθάνομαι δὲ αὐτὸν λέγειν ὡς ἀσεβῶ καταλύων τὰς θυσίας. ἐγὼ δ’ εἰ μὲν νόμους ἐτίθην περὶ τῆς ἀναγραφῆς, ἡγούμην ἂν ἐξεῖναι Νικομάχῳ τοιαῦτα εἰπεῖν περὶ ἐμοῦ· νῦν δὲ τοῖς κοινοῖς καὶ κειμένοις ἀξιῶ τοῦτον πείθεσθαι. θαυμάζω δὲ εἰ μὴ ἐνθυμεῖται, ὅταν ἐμὲ φάσκῃ ἀσεβεῖν λέγοντα ὡς χρὴ θύειν τὰς θυσίας τὰς ἐκ τῶν κύρβεων καὶ τῶν στηλῶν κατὰ τὰς συγγραφάς, ὅτι καὶ τῆς πόλεως κατηγορεῖ· ταῦτα γὰρ ὑμεῖς ἐψηφίσασθε. ἔπειτα εἰ ταῦτα νομίζεις δεινά, ἦ που σφόδρα ἐκείνους ἡγεῖ ἀδικεῖν,", "st": "30.17"}, {"sp": "N", "t": "οἳ τὰ ἐκ τῶν κύρβεων μόνον ἔθυον. καίτοι, ὦ ἄνδρες δικασταί, περὶ εὐσεβείας οὐ παρὰ Νικομάχου χρὴ μανθάνειν, ἀλλ’ ἐκ τῶν γεγενημένων σκοπεῖν. οἱ τοίνυν πρόγονοι τὰ ἐκ τῶν κύρβεων θύοντες μεγίστην καὶ εὐδαιμονεστάτην τῶν Ἑλληνίδων τὴν πόλιν παρέδοσαν, ὥστε ἄξιον ἡμῖν τὰς αὐτὰς ἐκείνοις θυσίας ποιεῖσθαι, καὶ εἰ μηδὲν δι’ ἄλλο, τῆς τύχης ἕνεκα τῆς ἐξ ἐκείνων τῶν ἱερῶν γεγενημένης.", "st": "30.18"}, {"sp": "N", "t": "πῶς δ’ ἄν τις εὐσεβέστερος γένοιτο ἐμοῦ, ὅστις ἀξιῶ πρῶτον μὲν κατὰ τὰ πάτρια θύειν, ἔπειτα ἃ μᾶλλον συμφέρει τῇ πόλει, ἔτι δὲ ἃ ὁ δῆμος ἐψηφίσατο καὶ δυνησόμεθα δαπανᾶν ἐκ τῶν προσιόντων χρημάτων; σὺ δέ, ὦ Νικόμαχε, τούτων τἀναντία πεποίηκας· ἀναγράψας γὰρ πλείω τῶν προσταχθέντων αἴτιος γεγένησαι τὰ προσιόντα χρήματα εἰς ταῦτα μὲν ἀναλίσκεσθαι, ἐν δὲ ταῖς πατρίοις θυσίαις ἐπιλείπειν.", "st": "30.19"}, {"sp": "N", "t": "αὐτίκα πέρυσιν ἱερὰ ἄθυτα τριῶν ταλάντων γεγένηται τῶν ἐν ταῖς κύρβεσι γεγραμμένων. καὶ οὐχ οἷόν τε εἰπεῖν ὡς οὐχ ἱκανὰ ἦν ἃ προσῆλθε τῇ πόλει· εἰ γὰρ οὗτος μὴ πλείω ἀνέγραψεν ἓξ ταλάντοις, εἴς τε τὰς θυσίας τὰς πατρίους ἂν ἐξήρκεσε καὶ τρία τάλαντα ἂν περιεγένετο τῇ πόλει. περὶ δὲ τῶν εἰρημένων καὶ μάρτυρας ὑμῖν παρέξομαι.", "st": "30.20"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "30.21"}, {"sp": "N", "t": "ἐνθυμεῖσθε τοίνυν, ὧ ἄνδρες δικασταί, ὅτι, ὅταν μὲν κατὰ τὰς συγγραφὰς ποιῶμεν, ἅπαντα τὰ πάτρια θύεται, ἐπειδὰν δὲ κατὰ τὰς στήλας ἃς οὗτος ἀνέγραψε, πολλὰ τῶν ἱερῶν καταλύεται. κἀν τούτοις ὁ ἱερόσυλος περιτρέχει, λέγων ὡς εὐσέβειαν ἀλλ’ οὐκ εὐτέλειαν ἀνέγραψε· καὶ εἰ μὴ ταῦτα ὑμῖν ἀρέσκει, ἐξαλείφειν κελεύει, καὶ ἐκ τούτων οἴεται πείθειν ὡς οὐδὲν ἀδικεῖ· ὃς ἐν δυοῖν μὲν ἐτοῖν πλείω ἤδη τοῦ δέοντος δώδεκα ταλάντοις ἀνήλωσε, παρ’ ἕκαστον δὲ τὸν ἐνιαυτὸν ἐπεχείρησεν ἓξ ταλάντοις τὴν πόλιν ζημιῶσαι,", "st": "30.21"}, {"sp": "N", "t": "καὶ ταῦτα ὁρῶν αὐτὴν ἀποροῦσαν χρημάτων καὶ Λακεδαιμονίους μὲν ἀπειλοῦντας, ὅταν μὴ ἀποπέμψωμεν αὐτοῖς τὰ χρήματα, Βοιωτοὺς δὲ σύλας ποιουμένους, ὅτι οὐ δυνάμεθα δύο τάλαντα ἀποδοῦναι, τοὺς δὲ νεωσοίκους ⟨καὶ⟩ τὰ τείχη περικαταρρέοντα, εἰδὼς δὲ ὅτι ἡ βουλὴ ἡ ⟨ἀεὶ⟩ βουλεύουσα, ὅταν μὲν ἔχῃ ἱκανὰ χρήματα εἰς διοίκησιν, οὐδὲν ἐξαμαρτάνει, ὅταν δὲ εἰς ἀπορίαν καταστῇ, ἀναγκάζεται εἰσαγγελίας δέχεσθαι καὶ δημεύειν τὰ τῶν πολιτῶν καὶ τῶν ῥητόρων τοῖς ⟨τὰ⟩ πονηρότατα λέγουσι πείθεσθαι.", "st": "30.22"}, {"sp": "N", "t": "χρὴ τοίνυν, ὦ ἄνδρες δικασταί, μὴ τοῖς βουλεύουσιν ἑκάστοτε ὀργίζεσθαι, ἀλλὰ τοῖς εἰς τοιαύτας ἀπορίας καθιστᾶσι τὴν πόλιν. προσέχουσι ⟨δὲ⟩ τὸν νοῦν οἱ βουλόμενοι τὰ κοινὰ κλέπτειν, ὅπως Νικόμαχος ἀγωνιεῖται· οἷς ὑμεῖς, ἐὰν μὴ τοῦτον τιμωρήσησθε, πολλὴν ἄδειαν ποιήσετε· ἐὰν δὲ καταψηφισάμενοι τῶν ἐσχάτων αὐτῶ τιμήσητε, τῇ αὐτῇ ψήφῳ τούς τε ἄλλους βελτίους ποιήσετε καὶ παρὰ τούτου δίκην εἰληφότες ἔσεσθε.", "st": "30.23"}, {"sp": "N", "t": "ἐπίστασθε δέ, ὦ ἄνδρες δικασταί, ὅτι παράδειγμα τοῖς ἄλλοις ἔσται μὴ τολμᾶν εἰς ὑμᾶς ἐξαμαρτάνειν οὐχ ὅταν τοὺς ἀδυνάτους εἰπεῖν κολάζητε, ἀλλ’ ὅταν παρὰ τῶν δυναμένων λέγειν δίκην λαμβάνητε. τίς οὖν τῶν ἐν τῇ πόλει ἐπιτηδειότερος Νικομάχου δοῦναι δίκην; τίς ἐλάττω τὴν πόλιν ἀγαθὰ πεποίηκεν ἢ πλείω ἠδίκηκεν;", "st": "30.24"}, {"sp": "N", "t": "ὃς καὶ τῶν ὁσίων καὶ τῶν ἱερῶν ἀναγραφεὺς γενόμενος εἰς ἀμφότερα ταῦτα ἡμάρτηκεν. ἀναμνήσθητε δὲ ὅτι πολλοὺς ἤδη τῶν πολιτῶν ἐπὶ κλοπῇ χρημάτων ἀπεκτείνατε. καίτοι ἐκεῖνοι μὲν τοσοῦτον μόνον ὑμᾶς ἔβλαψαν ὅσον ἐν τῷ παρόντι, οὗτοι δ’ ἐπὶ τῇ τῶν νόμων ἀναγραφῇ [καὶ τῶν ἱερῶν] δῶρα λαμβάνοντες εἰς ἅπαντα τὸν χρόνον τὴν πόλιν ζημιοῦσι.", "st": "30.25"}, {"sp": "N", "t": "διὰ τί δ’ ἄν τις ἀποψηφίσαιτο τούτου; πότερον ὡς ἀνδρὸς ἀγαθοῦ πρὸς τοὺς πολεμίους καὶ πολλαῖς μάχαις καὶ ναυμαχίαις παραγεγενημένου; ἀλλὰ ὅτε ὑμεῖς ἐκινδυνεύετε ἐκπλέοντες, οὗτος αὐτοῦ μένων τοὺς Σόλωνος νόμους ἐλυμαίνετο. ἀλλ’ ὅτι χρήματα δεδαπάνηκε καὶ πολλὰς εἰσφορὰς εἰσενήνοχεν; ἀλλ’ οὐχ ὅπως ὑμῖν τῶν αὑτοῦ τι ἐπέδωκεν, ἀλλὰ τῶν ὑμετέρων πολλὰ ὑφῄρηται. ἀλλὰ διὰ τοὺς προγόνους;", "st": "30.26"}, {"sp": "N", "t": "ἤδη γάρ τινες καὶ διὰ τοῦτο συγγνώμης ἔτυχον παρ’ ὑμῶν. ἀλλὰ τούτῳ γε προσήκει διὰ μὲν αὑτὸν τεθνάναι, διὰ δὲ τοὺς προγόνους πεπρᾶσθαι. ἀλλ’ ὡς, ἐὰν νῦν αὐτοῦ φείσησθε, αὖθις ἀποδώσει τὰς χάριτας; ὃς οὐδ’ ὧν πρότερον μετέλαβε παρ’ ὑμῶν ἀγαθῶν μέμνηται. καίτοι ἀντὶ μὲν δούλου πολίτης γεγένηται, ἀντὶ δὲ πτωχοῦ πλούσιος, ἀντὶ δὲ ὑπογραμματέως νομοθέτης.", "st": "30.27"}, {"sp": "N", "t": "ἃ καὶ ὑμῶν ἔχοι ἄν τις κατηγορῆσαι, ὅτι οἱ μὲν πρόγονοι νομοθέτας ᾑροῦντο Σόλωνα καὶ Θεμιστοκλέα καὶ Περικλέα, ἡγούμενοι τοιούτους ἔσεσθαι τοὺς νόμους οἷοίπερ ἂν ὦσιν οἱ τιθέντες, ὑμεῖς δὲ Τεισαμενὸν τὸν Μηχανίωνος καὶ Νικόμαχον καὶ ἑτέρους ἀνθρώπους ὑπογραμματέας· καὶ τὰς μὲν ἀρχὰς ὑπὸ τῶν τοιούτων ἡγεῖσθε διαφθείρεσθαι, αὐτοῖς δὲ τούτοις πιστεύετε.", "st": "30.28"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον· ὑπογραμματεῦσαι μὲν οὐκ ἔξεστι δὶς τὸν αὐτὸν τῇ ἀρχῇ τῇ αὐτῇ, περὶ δὲ τῶν μεγίστων τοὺς αὐτοὺς ἐᾶτε πολὺν χρόνον κυρίους εἶναι. καὶ τὸ τελευταῖον Νικόμαχον εἵλεσθε ἀναγράφειν τὰ πάτρια, ᾧ κατὰ πατέρα τῆς πόλεως οὐ προσήκει·", "st": "30.29"}, {"sp": "N", "t": "καὶ ὃν ἔδει ὑπὸ τοῦ δήμου κρίνεσθαι, οὗτος τὸν δῆμον συγκαταλύσας φαίνεται. νῦν τοίνυν ὑμῖν μεταμελησάτω τῶν πεπραγμένων, καὶ μὴ ὑπὸ τούτων ἀεὶ κακῶς πάσχοντες ἀνέχεσθε, μηδὲ ἰδίᾳ μὲν ὀνειδίζετε τοῖς ἀδικοῦσιν, ἐπειδὰν δ’ ἐξῇ δίκην παρ’ αὐτῶν λαμβάνειν, ἀποψηφίζεσθε.", "st": "30.30"}, {"sp": "N", "t": "καὶ περὶ μὲν τούτων ἱκανά μοι τὰ εἰρημένα· περὶ δὲ τῶν ἐξαιτησομένων βραχέα πρὸς ὑμᾶς εἰπεῖν βούλομαι. παρεσκευασμένοι ⟨γάρ⟩ τινές εἰσι καὶ τῶν φίλων καὶ τῶν τὰ τῆς πόλεως πραττόντων δεῖσθαι ὑπὲρ αὐτοῦ· ὧν ἐγὼ ἡγοῦμαι ἐνίοις προσήκειν ὑπὲρ τῶν ἑαυτοῖς πεπραγμένων ἀπολογεῖσθαι πολὺ μᾶλλον ἢ τοὺς ἀδικοῦντας σώζειν προαιρεῖσθαι.", "st": "30.31"}, {"sp": "N", "t": "δεινὸν δέ μοι δοκεῖ εἶναι, ὦ ἄνδρες δικασταί, εἰ τούτου μὲν ἑνὸς ὄντος καὶ οὐδὲν ὑπὸ τῆς πόλεως ἠδικημένου οὐκ ἐπεχείρησαν δεῖσθαι ⟨ὡς χρὴ⟩ παύσασθαι εἰς ὑμᾶς ἐξαμαρτάνοντα, ὑμᾶς δὲ τοσούτους ὄντας καὶ ἠδικημένους ὑπὸ τούτου ⟨πείθειν⟩ ζητήσουσιν ὡς οὐ χρὴ δίκην παρ’ αὐτοῦ λαμβάνειν.", "st": "30.32"}, {"sp": "N", "t": "χρὴ τοίνυν, ὥσπερ δὴ τούτους ὁρᾶτε προθύμως σῴζοντας τοὺς φίλους, οὕτως καὶ ὑμᾶς τοὺς ἐχθροὺς τιμωρεῖσθαι, εὖ εἰδότας ὅτι τούτοις πρώτοις ἄνδρες ἀμείνους δόξετε εἶναι, ἐὰν παρὰ τῶν ἀδικούντων δίκην λαμβάνητε. ἐνθυμεῖσθε δὲ ὅτι [οὔτε Νικόμαχος] οὐδὲ τῶν αἰτησομένων οὐδεὶς τοσαῦτα ἀγαθὰ πεποίηκε τὴν πόλιν, ὅσα οὗτος ἠδίκηκεν, ὥστε πολὺ μᾶλλον ὑμῖν προσήκει τιμωρεῖσθαι ἢ τούτοις βοηθεῖν.", "st": "30.33"}, {"sp": "N", "t": "εὖ δ’ εἰδέναι χρὴ τοὺς αὐτοὺς τούτους, ὅτι πολλὰ δεηθέντες τῶν κατηγόρων ἡμᾶς μὲν οὐδαμῶς ἔπεισαν, τὴν δὲ ὑμετέραν ψῆφον καταπειράσοντες εἰσεληλύθασιν εἰς τὸ δικαστήριον, καὶ ἐλπίζουσιν ὑμᾶς ἐξαπατήσαντες ἄδειαν εἰς τὸν λοιπὸν χρόνον λήψεσθαι τοῦ ποιεῖν ὅ τι ἂν βούλωνται.", "st": "30.34"}, {"sp": "N", "t": "ἡμεῖς μὲν τοίνυν οὐκ ἠθελήσαμεν ὑπὸ τούτων ἀξιούμενοι πεισθῆναι, τὸ δὲ αὐτὸ τοῦτο παρακαλοῦμεν ⟨ὑμᾶς⟩ μὴ πρὸ τῆς κρίσεως μισοπονηρεῖν, ἀλλ’ ἐν τῇ κρίσει τιμωρεῖσθαι τοὺς τὴν ὑμετέραν νομοθεσίαν ἀφανίζοντας· οὕτως γὰρ ἐννόμως διοικηθήσεται τὰ κατὰ τὴν πολιτείαν πάντα.", "st": "30.35"}, {"sp": "HDR", "t": "ΛΑʹ. Κατὰ Φίλωνος δοκιμασίας", "st": "31"}, {"sp": "N", "t": "ὤιμην μέν, ὦ βουλή, οὐκ ἄν ποτ’ εἰς τοῦτο τόλμης Φίλωνα ἀφικέσθαι, ὥστε ἐθελῆσαι εἰς ὑμᾶς ἐλθεῖν δοκιμασθησόμενον· ἐπειδὴ δὲ οὐχ ἕν τι μόνον ἀλλὰ πολλὰ τολμηρός ἐστιν,", "st": "31.1"}, {"sp": "N", "t": "ἐγὼ δὲ ὀμόσας εἰσῆλθον εἰς τὸ βουλευτήριον τὰ βέλτιστα βουλεύσειν τῇ πόλει, ἔνεστί τε ἐν τῷ ὅρκῳ ἀποφανεῖν εἴ τίς τινα οἶδε τῶν λαχόντων ἀνεπιτήδειον ὄντα βουλεύειν, ἐγὼ τὴν κατὰ τουτουὶ Φίλωνος ποιήσομαι κατηγορίαν, οὐ μέντοι γε ἰδίαν ἔχθραν οὐδεμίαν μεταπορευόμενος, οὐδὲ τῷ δύνασθαι καὶ εἰωθέναι λέγειν ἐν ὑμῖν ἐπαρθείς, ἀλλὰ τῷ πλήθει τῶν ἁμαρτημάτων αὐτοῦ πιστεύων, καὶ τοῖς ὅρκοις οἷς ὤμοσα ἐμμένειν ἀξιῶν.", "st": "31.2"}, {"sp": "N", "t": "γνώσεσθε μὲν οὖν ὅτι οὐκ ἀπὸ ἴσης παρασκευῆς ἐγώ τε τοῦτον ἐλέγξω οἷός ἐστι, καὶ οὗτος ἐπεχείρησε πονηρὸς εἶναι· ὅμως ⟨δ’⟩ εἴ τι ἐγὼ ἐλλείποιμι τῷ λόγῳ τῆς κατηγορίας, οὐκ ἂν δίκαιος εἴη οὗτος διὰ τοῦτο ὠφεληθῆναι, ἀλλὰ μᾶλλον, ὅ τι ἱκανῶς διδάξαιμι,", "st": "31.3"}, {"sp": "N", "t": "ἐκ τούτων ἀποδοκιμασθῆναι. ἐνδεῶς μὲν γὰρ διὰ τὴν ἀπειρίαν πάντων τῶν τούτῳ πεπραγμένων, ἱκανῶς δὲ διὰ τὴν περὶ αὐτὸν κακίαν εἰρηκὼς ἂν εἴην. ἀξιῶ δὲ καὶ ὑμῶν οἵτινες δυνατώτεροι ἐμοῦ εἰσι λέγειν, ἀποφῆναι μείζω ὄντα αὐτοῦ τὰ ἁμαρτήματα, καὶ ἐξ ἂν ἐγὼ ὑπολίπω, πάλιν αὐτοὺς περὶ ὧν ἴσασι κατηγορῆσαι Φίλωνος· οὐ γὰρ ἐκ τῶν ὑπ’ ἐμοῦ ⟨μόνου⟩ λεγομένων δεῖ ὑμᾶς περὶ αὐτοῦ ὁποῖός ἐστι σκέψασθαι.", "st": "31.4"}, {"sp": "N", "t": "ἐγὼ γὰρ οὐκ ἄλλους τινάς φημι δίκαιον εἶναι βουλεύειν περὶ ἡμῶν, ἢ τοὺς πρὸς τῷ εἶναι πολίτας καὶ ἐπιθυμοῦντας τούτου. τούτοις μὲν γὰρ μεγάλα τὰ διαφέροντά ἐστιν εὖ τε πράττειν τὴν πόλιν τήνδε καὶ ἀνεπιτηδείως διὰ τὸ ἀναγκαῖον σφίσιν αὐτοῖς ἡγεῖσθαι εἶναι μετέχειν τὸ μέρος τῶν δεινῶν,", "st": "31.5"}, {"sp": "N", "t": "ὥσπερ καὶ τῶν ἀγαθῶν μετέχουσι· ὅσοι δὲ φύσει μὲν πολῖταί εἰσι, γνώμῃ δὲ χρῶνται ὡς πᾶσα γῆ πατρὶς αὐτοῖς ἐστιν ἐν ᾗ ἂν τὰ ἐπιτήδεια ἔχωσιν, οὗτοι δῆλοί εἰσιν ὅτι κἂν παρέντες τὸ τῆς πόλεως κοινὸν ἀγαθὸν ἐπὶ τὸ ἑαυτῶν ἴδιον κέρδος ἔλθοιεν διὰ τὸ μὴ τὴν πόλιν ἀλλὰ τὴν οὐσίαν πατρίδα ἑαυτοῖς ἡγεῖσθαι.", "st": "31.6"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἀποφανῶ Φίλωνα τουτονὶ περὶ πλείονος ποιησάμενον τὴν ἰδίαν ἀσφάλειαν ἢ τὸν κοινὸν τῆς πόλεως κίνδυνον, καὶ ἡγησάμενον κρεῖττον εἶναι αὐτὸν ἀκινδύνως τὸν βίον διάγειν ἢ τὴν πόλιν σῴζειν ὁμοίως τοῖς ἄλλοις πολίταις κινδυνεύοντα.", "st": "31.7"}, {"sp": "N", "t": "οὗτος γάρ, ὦ βουλή, ὅτε ἡ συμφορὰ τῇ πόλει ἦν (ἧς ἐγώ, καθ’ ὅσον ἀναγκάζομαι, κατὰ τοσοῦτον μέμνημαι), ἐκκεκηρυγμένος ἐκ τοῦ ἄστεως ὑπὸ τῶν τριάκοντα μετὰ τοῦ ἄλλου πλήθους τῶν πολιτῶν τέως μὲν ᾤκει ἐν ἀγρῷ, ἐπειδὴ δὲ οἱ ἀπὸ Φυλῆς κατῆλθον εἰς τὸν Πειραιᾶ, καὶ οὐ μόνον οἱ ἐκ τῶν ἀγρῶν ἀλλὰ καὶ οἱ ἐκ τῆς ὑπερορίας οἱ μὲν εἰς τὸ ἄστυ οἱ δ’ εἰς τὸν Πειραιᾶ συνελέγοντο, καὶ καθ’ ὅσον ἕκαστος οἷός τ’ ἦν, κατὰ τοσοῦτον ἐβοήθει τῇ πατρίδι, τὰ ἐναντία ἅπασι τοῖς ἄλλοις πολίταις ἐποίησε·", "st": "31.8"}, {"sp": "N", "t": "συσκευασάμενος γὰρ τὰ ἑαυτοῦ ἐνθένδε εἰς τὴν ὑπερορίαν ἐξῴκησε, καὶ ἐν Ὠρωπῷ μετοίκιον κατατιθεὶς ἐπὶ προστάτου ᾤκει, βουληθεὶς παρ’ ἐκείνοις μετοικεῖν μᾶλλον ἢ μεθ’ ἡμῶν πολίτης εἶναι. οὐ τοίνυν οὐδ’ ὥσπερ ἔνιοί τινες τῶν πολιτῶν μετεβάλοντο, ἐπειδὴ ἑώρων τοὺς ἀπὸ Φυλῆς ἐν οἷς ἔπραττον εὐτυχοῦντας, οὐδὲ τούτων τι τῶν εὐτυχημάτων ἠξίωσε μετασχεῖν, ἐπὶ κατειργασμένοις μᾶλλον ἐλθεῖν βουλόμενος ἢ συγκατελθεῖν κατεργασάμενός τι τῶν τῇ κοινῇ πολιτείᾳ συμφερόντων· οὐ γὰρ ἦλθεν εἰς τὸν Πειραιᾶ, οὐδ’ ἔστιν ὅπου ἑαυτὸν ὑμῖν τάξαι παρέσχεν.", "st": "31.9"}, {"sp": "N", "t": "καίτοιγε ὅστις εὐτυχοῦντας ὁρῶν ἡμᾶς ἐτόλμα προδιδόναι, τί ποτε ὡς μὴ ἐβουλόμεθά γε πράττοντας ἐποίησεν ἄν; ὅσοι μὲν τοίνυν διὰ συμφορὰς ἰδίας οὐ μετέσχον τῶν τότε γενομένων τῇ πόλει κινδύνων, συγγνώμης τινὸς ἄξιοί εἰσι τυχεῖν· οὐδενὶ γὰρ οὐδὲν ἑκούσιον δυστύχημα γίγνεται·", "st": "31.10"}, {"sp": "N", "t": "ὅσοι δὲ γνώμῃ τοῦτο ἔπραξαν, οὐδεμιᾶς συγγνώμης ἄξιοί εἰσιν· οὐ γὰρ διὰ δυστυχίαν ἀλλὰ δι’ ἐπιβουλὴν ἐποίησαν αὐτό. καθέστηκε δέ τι ἔθος δίκαιον πᾶσιν ἀνθρώποις τῶν αὐτῶν ἀδικημάτων μάλιστα ὀργίζεσθαι τοῖς μάλιστα δυναμένοις μὴ ἀδικεῖν, τοῖς δὲ πένησιν ἢ ἀδυνάτοις τῷ σώματι συγγνώμην ἔχειν διὰ τὸ ἡγεῖσθαι ἄκοντας αὐτοὺς ἁμαρτάνειν.", "st": "31.11"}, {"sp": "N", "t": "οὗτος τοίνυν οὐδεμιᾶς συγγνώμης ἄξιός ἐστι τυχεῖν· οὔτε γὰρ τῷ σώματι ἀδύνατος ἦν ταλαιπωρεῖν, ὡς καὶ ὑμεῖς ὁρᾶτε, οὔτε τῇ οὐσίᾳ ἄπορος λῃτουργεῖν, ὡς ἐγὼ ἀποδείξω. ὅστις οὖν ὅσον δυνατὸς ἦν ὠφελεῖν, τοσοῦτον κακὸς ἦν, πῶς οὐκ ἂν εἰκότως ὑπὸ πάντων ὑμῶν μισοῖτο;", "st": "31.12"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδ’ ἀπεχθήσεσθέ γε τῶν πολιτῶν οὐδενὶ τοῦτον ἀποδοκιμάσαντες, ⟨ὃς⟩ οὔ τι τοὺς ἑτέρους ἀλλ’ ἀμφοτέρους φανερός ἐστι προδούς, ὥστε μήτε τοῖς ἐν τῷ ἄστει γενομένοις φίλον προσήκειν εἶναι τοῦτον (οὐ γὰρ ἠξίωσεν ὡς αὐτοὺς ἐλθεῖν κινδυνεύοντας), μήτε τοῖς τὸν Πειραιᾶ καταλαβοῦσιν· οὐδὲ γὰρ τούτοις ἠθέλησε συγκατελθεῖν, καὶ ταῦτα ὥς φησι καὶ ἀστὸς γενόμενος.", "st": "31.13"}, {"sp": "N", "t": "εἰ μέντοι τι μέρος περίεστι τῶν πολιτῶν ὅ τι τῶν αὐτῶν μετέσχε τούτῳ πραγμάτων, μετ’ ἐκείνων, ἐάν ποτε (ὃ μὴ γένοιτο) λάβωσι τὴν πόλιν, βουλεύειν ἀξιούτω.", "st": "31.14"}, {"sp": "N", "t": "ὡς οὖν ᾤκει τε ἐν Ὠρωπῷ ἐπὶ προστάτου καὶ ἐκέκτητο ἱκανὴν οὐσίαν καὶ οὔτ’ ἐν τῷ Πειραιεῖ οὔτ’ ἐν τῷ ἄστει ἔθετο τὰ ὅπλα, ἵνα εἰδῆτε ὅτι ταῦτα πρῶτον ἀληθῆ λέγω, ἀκούσατε τῶν μαρτύρων.", "st": "31.14"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "31.15"}, {"sp": "N", "t": "ὑπολείπεται τοίνυν αὐτῷ λέγειν ὡς τῷ μὲν σώματι δι’ ἀσθένειάν τινα γενομένην ἀδύνατος κατέστη βοηθῆσαι εἰς τὸν Πειραιᾶ, ἀπὸ δὲ τῶν ὑπαρχόντων ἐπαγγειλάμενος αὐτὸς ἢ χρήματ’ εἰσενεγκεῖν εἰς τὸ πλῆθος τὸ ὑμέτερον ἢ ὁπλίσαι τινὰς τῶν ἑαυτοῦ δημοτῶν, ὥσπερ καὶ ἄλλοι πολλοὶ τῶν πολιτῶν αὐτοὶ οὐ δυνάμενοι λῃτουργεῖν τοῖς σώμασιν.", "st": "31.15"}, {"sp": "N", "t": "ἵνα οὖν μὴ ἐγγένηται αὐτῷ ψευσαμένῳ ἐξαπατῆσαι, καὶ περὶ τούτων ἤδη σαφῶς ὑμῖν ἀποδείξω, ἐπειδὴ ὕστερον οὐκ ἐξέσται μοι παρελθόντι ἐνθάδ’ ἐλέγχειν αὐτόν. καί μοι κάλει Διότιμον τὸν Ἀχαρνέα καὶ τοὺς αἱρεθέντας μετ’ αὐτοῦ τοὺς δημότας ὁπλίσαι ἀπὸ τῶν εἰσενεχθέντων χρημάτων.", "st": "31.16"}, {"sp": "N", "t": "<em>Μαρτυρία τῶν Αἱρεθέντων μετὰ Διοτίμου<\/em>", "st": "31.17"}, {"sp": "N", "t": "οὗτος τοίνυν οὐχ ὅπως ὠφελήσει τὴν πόλιν ἐν τοιούτῳ καιρῷ καὶ τοιαύτῃ καταστάσει διενοήθη, ἀλλ’ ὅπως τι κερδανεῖ ἀπὸ τῶν ὑμετέρων συμφορῶν παρεσκευάσατο· ὁρμώμενος γὰρ ἐξ Ὠρωποῦ, τοτὲ μὲν αὐτὸς μόνος, τοτὲ δ’ ἑτέροις ἡγούμενος οἷς τὰ ὑμέτερα δυστυχήματα εὐτυχήματα ἐγεγόνει,", "st": "31.17"}, {"sp": "N", "t": "περιιὼν κατὰ τοὺς ἀγροὺς καὶ ἐντυγχάνων τῶν πολιτῶν τοῖς πρεσβυτάτοις, οἳ κατέμειναν ἐν τοῖς δήμοις ὀλίγα μὲν τῶν ἐπιτηδείων ἔχοντες, ἀναγκαῖα δέ, εὖνοι μὲν ὄντες τῷ πλήθει, ἀδύνατοι δὲ ὑπὸ τῆς ἡλικίας βοηθεῖν, τούτους ἀφῃρεῖτο τὰ ὑπάρχοντα, περὶ πλείονος ποιούμενος αὐτὸς μικρὰ κερδαίνειν ἢ ἐκείνους μηδὲν ἀδικεῖν· οἳ νῦν αὐτὸν δι’ αὐτὸ τοῦτο οὐχ οἷοί τέ εἰσιν ἐπεξελθεῖν ἅπαντες, δι’ ὅπερ καὶ τότε ἀδύνατοι τῇ πόλει βοηθεῖν ἦσαν.", "st": "31.18"}, {"sp": "N", "t": "οὐ μέντοι τοῦτόν γε χρὴ διὰ τὴν ἐκείνων ἀδυναμίαν δὶς ὠφεληθῆναι, τότε τ’ ἀφελόμενον ἃ εἶχον, νῦν τε δοκιμασθέντα ὑφ’ ὑμῶν· ἀλλὰ κἂν ὁστισοῦν παραγένηται τῶν ἀδικηθέντων, μέγα αὐτὸ ἡγήσασθε εἶναι, καὶ τοῦτον ὑπερμισήσατε, ὅστις ἐτόλμησεν, οἷς ἕτεροι διδόναι παρ’ ἑαυτῶν τι προῃροῦντο διὰ τὴν ἀπορίαν οἰκτίραντες αὐτούς, τούτων ἀφαιρεῖσθαι τὰ ὑπάρχοντα. κάλει μοι τοὺς μάρτυρας.", "st": "31.19"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "31.20"}, {"sp": "N", "t": "οὐ τοίνυν ἔγωγε οἶδα ὅ τι ὑμᾶς διαφερόντως δεῖ γιγνώσκειν περὶ αὐτοῦ ἢ οἱ οἰκεῖοι γιγνώσκουσι· τοιαῦτα γάρ ἐστιν, ὥστ’ εἰ καὶ μηδὲν αὐτῷ ἄλλο ἡμάρτητο, διὰ μόνα ταῦτα δίκαιον εἶναι ἀποδοκιμασθῆναι. οἷα μὲν οὖν ζῶσα ἡ μήτηρ αὐτοῦ κατηγόρει, παρήσω· ἐξ ὧν δὲ τελευτῶσα τὸν βίον διεπράξατο τεκμαιρομένοις ῥᾴδιόν ἐστιν ὑμῖν γνῶναι ὁποῖός τις ἦν περὶ αὐτήν.", "st": "31.20"}, {"sp": "N", "t": "ἐκείνη γὰρ τούτῳ μὲν ἠπίστησεν ἀποθανοῦσαν ἑαυτὴν ἐπιτρέψαι, Ἀντιφάνει δὲ οὐδὲν προσήκουσα πιστεύσασα ἔδωκεν εἰς τὴν ἑαυτῆς ταφὴν τρεῖς μνᾶς ἀργυρίου, παραλιποῦσα τοῦτον ὑὸν ὄντα ἑαυτῆς. ἆρα δῆλον ὅτι εὖ ᾔδει αὐτὸν οὐδὲ διὰ τὸ προσήκειν αὐτῇ τὰ δέοντα ἂν ποιήσαντα;", "st": "31.21"}, {"sp": "N", "t": "καίτοι εἰ μήτηρ, ἣ πέφυκε καὶ ἀδικουμένη ὑπὸ τῶν ἑαυτῆς παίδων μάλιστα ἀνέχεσθαι καὶ μίκρ’ ὠφελουμένη μεγάλα ἔχειν ἡγεῖσθαι διὰ τὸ εὐνοίᾳ μᾶλλον ἢ ἐλέγχῳ τὰ γιγνόμενα δοκιμάζειν, ἐνόμιζε τοῦτον κἂν ἀπὸ τεθνεώσης φέρειν ἑαυτῆς, τί χρὴ ὑμᾶς περὶ αὐτοῦ διανοηθῆναι;", "st": "31.22"}, {"sp": "N", "t": "ὅστις γὰρ περὶ τοὺς ἑαυτοῦ ἀναγκαίους τοιαῦτα ἁμαρτάνει ἁμαρτήματα, τί ἂν περί γε τοὺς ἀλλοτρίους ποιήσειεν; ὡς οὖν καὶ ταῦτ’ ἀληθῆ ἐστιν, ἀκούσατε αὐτοῦ τοῦ λαβόντος τὸ ἀργύριον καὶ θάψαντος αὐτήν.", "st": "31.23"}, {"sp": "N", "t": "<em>Μαρτυρία<\/em>", "st": "31.24"}, {"sp": "N", "t": "τί ⟨ἂν⟩ οὖν βουληθέντες ὑμεῖς τοῦτον δοκιμάσαιτε; πότερον ὡς οὐχ ἡμαρτηκότα; ἀλλὰ τὰ μέγιστα περὶ τὴν πατρίδα ἠδίκηκεν· ἀλλ’ ὡς ἔσται βελτίων; τοιγάρτοι πρότερον βελτίων γενόμενος περὶ τὴν πόλιν ὕστερον βουλεύειν ἀξιούτω, φανερόν τι ἀγαθὸν ὥσπερ τότε κακὸν ποιήσας. σωφρονέστερον γάρ ἐστιν ὕστερον πᾶσι τῶν ἔργων τὰς χάριτας ἀποδιδόναι· δεινὸν γὰρ ἔμοιγε δοκεῖ εἶναι, εἰ ἐξ ὧν μὲν ἤδη ἡμάρτηκε μηδέποτε τιμωρηθήσεται, ἐξ ὧν δὲ μέλλει εὖ ποιήσειν ἤδη τετιμήσεται.", "st": "31.24"}, {"sp": "N", "t": "ἀλλ’ ἄρα ἵνα βελτίους ὦσιν οἱ πολῖται ὁρῶντες ἅπαντας ὁμοίως τιμωμένους, διὰ τοῦτο δοκιμαστέος ἐστίν; ἀλλὰ κίνδυνος καὶ τοὺς χρηστούς ἐὰν αἰσθάνωνται ὁμοίως τοῖς πονηροῖς τιμώμενοι, παύσεσθαι τῶν χρηστῶν ἐπιτηδευμάτων, τῶν αὐτῶν ἡγουμένους εἶναι τούς τε κακοὺς τιμᾶν καὶ τῶν ἀγαθῶν ἀμνημονεῖν· ἄξιον δὲ καὶ τόδε ἐνθυμηθῆναι,", "st": "31.25"}, {"sp": "N", "t": "ὅτι εἰ μέν τις φρούριόν τι προὔδωκεν ἢ ναῦν ἢ στρατόπεδόν τι, ἐν ᾧ μέρος τι ἐτύγχανε τῶν πολιτῶν ὄν, ταῖς ἐσχάταις ἂν ζημίαις ἐζημιοῦτο, οὗτος δὲ προδοὺς ὅλην τὴν πόλιν οὐχ ὅπως ⟨μὴ⟩ τιμωρηθήσεται ⟨ἀλλὰ καὶ ὅπως τιμήσεται⟩ παρασκευάζεται. καίτοι δικαίως γ’ ἄν, ὅστις φανερῶς ὥσπερ οὗτος προὔδωκε τὴν ἐλευθερίαν, οὐ περὶ τοῦ βουλεύειν ἀλλὰ περὶ τοῦ δουλεύειν καὶ τῆς μεγίστης τιμωρίας ἀγωνίζοιτο.", "st": "31.26"}, {"sp": "N", "t": "ἀκούω δ’ αὐτὸν λέγειν ὡς, εἴ τι ἦν ἀδίκημα τὸ μὴ παραγενέσθαι ἐν ἐκείνῳ τῷ καιρῷ, νόμος ἂν ἔκειτο περὶ αὐτοῦ διαρρήδην, ὥσπερ καὶ περὶ τῶν ἄλλων ἀδικημάτων. οὐ γὰρ οἴεται ὑμᾶς γνώσεσθαι ὅτι διὰ τὸ μέγεθος τοῦ ἀδικήματος οὐδεὶς περὶ αὐτοῦ ἐγράφη νόμος. τίς γὰρ ἄν ποτε ῥήτωρ ἐνεθυμήθη ἢ νομοθέτης ἤλπισεν ἁμαρτήσεσθαί τινα τῶν πολιτῶν τοσαύτην ἁμαρτίαν;", "st": "31.27"}, {"sp": "N", "t": "οὐ γὰρ ἂν δήπου, εἰ μέν τις λίποι τὴν τάξιν μὴ αὐτῆς τῆς πόλεως ἐν κινδύνῳ οὔσης ἀλλ’ ἑτέρους εἰς τοῦτο καθιστάσης, ἐτέθη νόμος ὡς μεγάλα ἀδικοῦντος, εἰ δέ τις αὐτῆς τῆς πόλεως ἐν κινδύνῳ οὔσης λίποι τὴν πόλιν αὐτήν, οὐκ ἂν ἄρα ἐτέθη. σφόδρα γ’ ἄν, εἴ τις ᾠήθη τινὰ τῶν πολιτῶν ἁμαρτήσεσθαί τι τοιοῦτόν ποτε.", "st": "31.28"}, {"sp": "N", "t": "τίς δ’ οὐκ ἂν εἰκότως ἐπιτιμήσειεν ὑμῖν, εἰ τοὺς μετοίκους μέν, ὅτι οὐ κατὰ τὸ προσῆκον ἑαυτοῖς ἐβοήθησαν τῷ δήμῳ, ἐτιμήσατε ἀξίως τῆς πόλεως, τοῦτον δέ, ὅτι παρὰ τὸ προσῆκον ἑαυτῷ προὔδωκε τὴν πόλιν, μὴ κολάσετε, εἰ μή γε ἄλλῳ τινὶ μείζονι, τῇ γε παρούσῃ ἀτιμίᾳ;", "st": "31.29"}, {"sp": "N", "t": "ἀναμνήσθητε δὲ δι’ ὅ τι ποτὲ τοὺς ἀγαθοὺς ἄνδρας γενομένους περὶ τὴν πόλιν τιμᾶτε καὶ τοὺς κακοὺς ἀτιμάζετε. ἐδείχθη γὰρ ἀμφότερα ταῦτα οὐ τῶν γεγενημένων μᾶλλόν τι ἕνεκα ἢ τῶν γενησομένων, ἵν’ ἀγαθοὶ προθυμῶνται γίγνεσθαι ἐκ παρασκευῆς, κακοὶ δὲ μηδὲ ἐξ ἑνὸς τρόπου ἐπιχειρῶσιν.", "st": "31.30"}, {"sp": "N", "t": "ἔτι δὲ ἐνθυμήθητε· ποίων ἂν ὑμῖν δοκεῖ οὗτος ὅρκων φροντίσαι, ὃς ἔργω τοὺς πατρίους θεοὺς προὔδωκεν; ἢ πῶς ἂν χρηστόν τι βουλεῦσαι περὶ τῆς πολιτείας, ὅς οὐδὲ ἐλευθερῶσαι τὴν πατρίδα ἐβουλήθη; ἢ ποῖα ἂν ἀπόρρητα τηρῆσαι, ὃς οὐδὲ τὰ προειρημένα ποιῆσαι ἠξίωσε; πῶς δ’ εἰκός ἐστι τοῦτον, ὃς οὐδὲ τελευταῖος ἐπὶ τοὺς κινδύνους ἦλθε, πρότερον τῶν κατεργασαμένων καὶ οὕτω νῦν τιμηθῆναι; σχέτλιον δ’ ἂν εἴη, εἰ οὗτος μὲν ἅπαντας τοὺς πολίτας περὶ οὐδενὸς ἡγήσατο, ὑμεῖς δὲ τοῦτον ἕνα ὄντα μὴ ἀποδοκιμάσαιτε.", "st": "31.31"}, {"sp": "N", "t": "ὁρῶ δέ τινας οἳ νῦν μὲν τούτῳ παρασκευάζονται βοηθεῖν καὶ δεῖσθαι ὑμῶν, ἐπειδὴ ἐμὲ οὐκ ἐδύναντο πεῖσαι· τότε δέ, ὅτε οἱ κίνδυνοι μὲν ὑμῖν καὶ οἱ μέγιστοι ἀγῶνες ἦσαν, τὰ δὲ ἆθλα αὐτὴ ἡ πολιτεία ἔκειτο, καὶ ἔδει οὐ μόνον περὶ τοῦ βουλεύειν ἀλλὰ καὶ περὶ τῆς ἐλευθερίας ἀγωνίζεσθαι, τότε οὐκ ἐδέοντο αὐτοῦ βοηθῆσαι καὶ ὑμῖν καὶ κοινῇ τῇ πόλει, καὶ μὴ προδοῦναι μήτε τὴν πατρίδα μήτε τὴν βουλήν, ἧς νῦν ἀξιοῖ τυχεῖν οὐ μετὸν αὐτῷ, ἄλλων γε κατεργασαμένων.", "st": "31.32"}, {"sp": "N", "t": "μόνος δή, ὦ βουλή, δικαίως οὐδ’ ἂν ἀγανακτοίη μὴ τυχών· οὐ γὰρ ὑμεῖς νῦν αὐτὸν ἀτιμάζετε, ἀλλ’ αὐτὸς αὑτὸν τότε ἀπεστέρησεν, ὅτε οὐκ ἠξίωσεν, ὥσπερ νῦν προθύμως κληρωσόμενος ἦλθε, καὶ τότε διαμαχούμενος περὶ αὐτῆς καταστῆναι μεθ’ ὑμῶν.", "st": "31.33"}, {"sp": "N", "t": "ἱκανά μοι νομίζω εἰρῆσθαι, καίτοι πολλά γε παραλιπών· ἀλλὰ πιστεύω ὑμᾶς καὶ ἄνευ τούτων αὐτοὺς τὰ συμφέροντα τῇ πόλει γνώσεσθαι. οὐ γὰρ ἄλλοις τισὶν ὑμᾶς δεῖ περὶ τῶν ἀξίων ὄντων βουλεύειν τεκμηρίοις χρῆσθαι ἢ ὑμῖν αὐτοῖς, ὁποῖοί τινες ὄντες αὐτοὶ περὶ τὴν πόλιν ἐδοκιμάσθητε. ἔστι γὰρ τὰ τούτου ἐπιτηδεύματα καινὰ παραδείγματα καὶ πάσης δημοκρατίας ἀλλότρια.", "st": "31.34"}, {"sp": "HDR", "t": "ΛΒʹ. Κατὰ Διογείτονος", "st": "32"}, {"sp": "N", "t": "εἰ μὲν μὴ μεγάλα ἦν τὰ διαφέροντα, ὦ ἄνδρες δικασταί, οὐκ ἄν ποτε εἰς ὑμᾶς εἰσελθεῖν τούτους εἴασα, νομίζων αἴσχιστον εἶναι πρὸς τοὺς οἰκείους διαφέρεσθαι, εἰδώς τε ὅτι οὐ μόνον οἱ ἀδικοῦντες χείρους ὑμῖν εἶναι δοκοῦσιν, ἀλλὰ καὶ οἵτινες ἂν ἔλαττον ὑπὸ τῶν προσηκόντων ἔχοντες ἀνέχεσθαι μὴ δύνωνται· ἐπειδὴ μέντοι, ὦ ἄνδρες δικασταί, πολλῶν χρημάτων ἀπεστέρηνται καὶ πολλὰ καὶ δεινὰ πεπονθότες ὑφ’ ὧν ἥκιστα ἐχρῆν, ἐπ’ ἐμὲ κηδεστὴν ὄντα κατέφυγον, ἀνάγκη μοι γεγένηται εἰπεῖν ὑπὲρ αὐτῶν.", "st": "32.1"}, {"sp": "N", "t": "ἔχω δὲ τούτων μὲν ἀδελφήν, Διογείτονος δὲ θυγατριδῆν, καὶ πολλὰ δεηθεὶς ἀμφοτέρων τὸ μὲν πρῶτον ἔπεισα τοῖς φίλοις ἐπιτρέψαι δίαιταν, περὶ πολλοῦ ποιούμενος τὰ τούτων πράγματα μηδένα τῶν ἄλλων εἰδέναι· ἐπειδὴ δὲ Διογείτων ἃ φανερῶς ἔχων ἐξηλέγχετο, περὶ τούτων οὐδενὶ τῶν αὑτοῦ φίλων ἐτόλμα πείθεσθαι, ἀλλ’ ἐβουλήθη καὶ φεύγειν δίκας καὶ μὴ οὔσας διώκειν καὶ ὑπομεῖναι τοὺς ἐσχάτους κινδύνους μᾶλλον ἢ τὰ δίκαια ποιήσας ἀπηλλάχθαι τῶν πρὸς τούτους ἐγκλημάτων,", "st": "32.2"}, {"sp": "N", "t": "ὑμῶν δέομαι, ἐὰν μὲν ἀποδείξω οὕτως αἰσχρῶς αὐτοὺς ἐπιτετροπευμένους ὑπὸ τοῦ πάππου ὡς οὐδεὶς πώποτε ὑπὸ τῶν οὐδὲν προσηκόντων ἐν τῇ πόλει, βοηθεῖν αὐτοῖς τὰ δίκαια, εἰ δὲ μή, τούτῳ μὲν ἅπαντα πιστεύειν, ἡμᾶς δὲ εἰς τὸν λοιπὸν χρόνον ἡγεῖσθαι χείρους εἶναι. ἐξ ἀρχῆς δ’ ὑμᾶς περὶ αὐτῶν διδάξαι πειράσομαι.", "st": "32.3"}, {"sp": "N", "t": "ἀδελφοὶ ἦσαν, ὦ ἄνδρες δικασταί, Διόδοτος καὶ Διογείτων ὁμοπάτριοι καὶ ὁμομήτριοι, καὶ τὴν μὲν ἀφανῆ οὐσίαν ἐνείμαντο, τῆς δὲ φανερᾶς ἐκοινώνουν. ἐργασαμένου δὲ Διοδότου κατ’ ἐμπορίαν πολλὰ χρήματα πείθει αὐτὸν Διογείτων λαβεῖν τὴν ἑαυτοῦ θυγατέρα, ἥπερ ἦν αὐτῷ μόνη· καὶ γίγνονται αὐτῷ δύο καὶ θυγάτηρ.", "st": "32.4"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον καταλεγεὶς Διόδοτος [μετὰ Θρασύλλου] τῶν ὁπλιτῶν, καλέσας τὴν ἑαυτοῦ γυναῖκα, ἀδελφιδῆν οὖσαν, καὶ τὸν ἐκείνης μὲν πατέρα, αὑτοῦ δὲ κηδεστὴν καὶ ἀδελφὸν [ὁμοπάτριον], πάππον δὲ τῶν παιδίων καὶ θεῖον, ἡγούμενος διὰ ταύτας τὰς ἀναγκαιότητας οὐδενὶ μᾶλλον προσήκειν δικαίῳ περὶ τοὺς αὑτοῦ παῖδας γενέσθαι, διαθήκην αὐτῷ δίδωσι καὶ πέντε τάλαντα ἀργυρίου παρακαταθήκην·", "st": "32.5"}, {"sp": "N", "t": "ναυτικὰ δὲ ἀπέδειξεν ἐκδεδομένα ἑπτὰ τάλαντα καὶ τετταράκοντα μνᾶς …, δισχιλίας δὲ ὀφειλομένας ἐν Χερρονήσω. ἐπέσκηψε δέ, ἐάν τι πάθῃ, τάλαντον μὲν ἐπιδοῦναι τῇ γυναικὶ καὶ τὰ ἐν τῷ δωματίῳ δοῦναι, τάλαντον δὲ τῇ θυγατρί· κατέλιπε ⟨δὲ⟩ καὶ εἴκοσι μνᾶς τῇ γυναικὶ καὶ τριάκοντα στατῆρας Κυζικηνούς.", "st": "32.6"}, {"sp": "N", "t": "ταῦτα δὲ πράξας καὶ οἴκοι ἀντίγραφα καταλιπὼν ᾤχετο στρατευσόμενος μετὰ Θρασύλλου. ἀποθανόντος δὲ ἐκείνου ἐν Ἐφέσῳ Διογείτων ⟨τέως⟩ μὲν τὴν θυγατέρα ἔκρυπτε τὸν θάνατον τοῦ ἀνδρός, καὶ τὰ γράμματα λαμβάνει ἃ κατέλιπε σεσημασμένα, φάσκων τὰ ναυτικὰ χρήματα δεῖν ἐκ τούτων τῶν γραμματείων κομίσασθαι.", "st": "32.7"}, {"sp": "N", "t": "ἐπειδὴ δὲ χρόνῳ ἐδήλωσε τὸν θάνατον αὐτοῖς καὶ ἐποίησαν τὰ νομιζόμενα, τὸν μὲν πρῶτον ἐνιαυτὸν ἐν Πειραιεῖ διῃτῶντο· ἅπαντα γὰρ αὐτοῦ κατελέλειπτο τὰ ἐπιτήδεια· ἐκείνων δὲ ἐπιλειπόντων τοὺς μὲν παῖδας εἰς ἄστυ ἀναπέμπει, τὴν δὲ μητέρα αὐτῶν ἐκδίδωσιν ἐπιδοὺς πεντακισχιλίας δραχμάς, χιλίαις ἔλαττον ὧν ὁ ἀνὴρ αὐτῆς ἔδωκεν.", "st": "32.8"}, {"sp": "N", "t": "ὀγδόῳ ἔτει δοκιμασθέντος μετὰ ταῦτα τοῦ πρεσβυτέρου τοῖν μειρακίοιν, καλέσας αὐτοὺς εἶπε Διογείτων, ὅτι καταλίποι αὐτοῖς ὁ πατὴρ εἴκοσι μνᾶς ἀργυρίου καὶ τριάκοντα στατῆρας. “ἐγὼ οὖν πολλὰ τῶν ἐμαυτοῦ δεδαπάνηκα εἰς τὴν ὑμετέραν τροφήν. καὶ ἕως μὲν εἶχον, οὐδέν μοι διέφερεν· νυνὶ δὲ καὶ αὐτὸς ἀπόρως διάκειμαι. σὺ οὖν, ἐπειδὴ δεδοκίμασαι καὶ ἀνὴρ γεγένησαι, σκόπει αὐτὸς ἤδη πόθεν ἕξεις τὰ ἐπιτήδεια.”", "st": "32.9"}, {"sp": "N", "t": "ταῦτ’ ἀκούσαντες ἐκπεπληγμένοι καὶ δακρύοντες ὤχοντο πρὸς τὴν μητέρα, καὶ παραλαβόντες ἐκείνην ἧκον πρὸς ἐμέ, οἰκτρῶς ὑπὸ τοῦ πάθους διακείμενοι καὶ ἀθλίως ἐκπεπτωκότες, κλάοντες καὶ παρακαλοῦντες με μὴ περιιδεῖν αὐτοὺς ἀποστερηθέντας τῶν πατρῴων μηδ’ πτωχείαν καταστάντας, ὑβρισμένους ὑφ’ ὦν ἥκιστα ἐχρῆν, ἀλλὰ βοηθῆσαι καὶ τῆς ἀδελφῆς ἕνεκα καὶ σφῶν αὐτῶν.", "st": "32.10"}, {"sp": "N", "t": "πολλὰ ἂν εἴη λέγειν, ὅσον πένθος ἐν τῇ ἐμῇ οἰκίᾳ ἦν ἐν ἐκείνῳ τῷ χρόνῳ. τελευτῶσα δὲ ἡ μήτηρ αὐτῶν ἠντεβόλει με καὶ ἱκέτευε συναγαγεῖν αὐτῆς τὸν πατέρα καὶ τοὺς φίλους, εἰποῦσα ὅτι, εἰ καὶ μὴ πρότερον εἴθισται λέγειν ἐν ἀνδράσι, τὸ μέγεθος αὐτὴν ἀναγκάσει τῶν συμφορῶν περὶ τῶν σφετέρων κακῶν δηλῶσαι πάντα πρὸς ἡμᾶς.", "st": "32.11"}, {"sp": "N", "t": "ἐλθὼν δ’ ἐγὼ ἠγανάκτουν μὲν πρὸς Ἡγήμονα τὸν ἔχοντα τὴν τούτου θυγατέρα, λόγους δ’ ἐποιούμην πρὸς τοὺς ἄλλους ἐπιτηδείους, ἠξίουν δὲ τοῦτον εἰς ἔλεγχον ἰέναι περὶ τῶν χρημάτων. Διογείτων δὲ τὸ μὲν πρῶτον οὐκ ἤθελε, τελευτῶν δὲ ὑπὸ τῶν φίλων ἠναγκάσθη. ἐπειδὴ δὲ συνήλθομεν, ἤρετο αὐτὸν ἡ γυνή, τίνα ποτὲ ψυχὴν ἔχων ἀξιοῖ περὶ τῶν παίδων τοιαύτῃ γνώμῃ χρῆσθαι, “ἀδελφὸς μὲν ὢν τοῦ πατρὸς αὐτῶν, πατὴρ δ’ ἐμός, θεῖος δὲ αὐτοῖς καὶ πάππος.”", "st": "32.12"}, {"sp": "N", "t": "“καὶ εἰ μηδένα ἀνθρώπων ᾐσχύνου, τοὺς θεοὺς ἐχρῆν σε” φησί “δεδιέναι· ὃς ἔλαβες μέν, ὅτ’ ἐκεῖνος ἐξέπλει, πέντε τάλαντα παρ’ αὐτοῦ παρακαταθήκην. καὶ περὶ τούτων ἐγὼ ἐθέλω τοὺς παῖδας παραστησαμένη καὶ τούτους καὶ τοὺς ὕστερον ἐμαυτῇ γενομένους ὀμόσαι ὅπου ἂν αὐτὸς λέγῃς. καίτοι οὐχ οὕτως ἐγώ εἰμι ἀθλία, οὐδ’ οὕτω περὶ πολλοῦ ποιοῦμαι χρήματα, ὥστ’ ἐπιορκήσασα κατὰ τῶν παίδων τῶν ἐμαυτῆς τὸν βίον καταλιπεῖν, ἀδίκως δὲ ἀφελέσθαι τὴν τοῦ πατρὸς οὐσίαν.”", "st": "32.13"}, {"sp": "N", "t": "ἔτι τοίνυν ἐξήλεγχεν αὐτὸν ἑπτὰ τάλαντα κεκομισμένον ναυτικὰ καὶ τετρακισχιλίας δραχμάς, καὶ τούτων τὰ γράμματα ἀπέδειξεν· ἐν γὰρ τῇ διοικίσει, ὅτ’ ἐκ Κολλυτοῦ διῳκίζετο εἰς τὴν Φαίδρου οἰκίαν, τοὺς παῖδας ἐπιτυχόντας ἐκβεβλημένῳ τῷ βιβλίῳ ἐνεγκεῖν πρὸς αὐτήν.", "st": "32.14"}, {"sp": "N", "t": "ἀπέφηνε δ’ αὐτὸν ἑκατὸν μνᾶς κεκομισμένον ἐγγείῳ ἐπὶ τόκῳ δεδανεισμένας, καὶ ἑτέρας δισχιλίας δραχμὰς καὶ ἔπιπλα πολλοῦ ἄξια· φοιτᾶν δὲ καὶ σῖτον αὐτοῖς ἐκ Χερρονήσου καθ’ ἕκαστον ἐνιαυτόν. “ἔπειτα σὺ ἐτόλμησας” ἔφη “εἰπεῖν, ἔχων τοσαῦτα χρήματα, ὡς δισχιλίας δραχμὰς ὁ τούτων πατὴρ κατέλιπε καὶ τριάκοντα στατῆρας ἅπερ ἐμοὶ καταλειφθέντα ἐκείνου τελευτήσαντος ἐγώ σοι ἔδωκα;”", "st": "32.15"}, {"sp": "N", "t": "“καὶ ἐκβάλλειν τούτους ἠξίωσας θυγατριδοῦς ὄντας ἐκ τῆς οἰκίας τῆς αὑτῶν ἐν τριβωνίοις, ἀνυποδήτους, οὐ μετὰ ἀκολούθου, οὐ μετὰ στρωμάτων, οὐ μετὰ ἱματίων, οὐ μετὰ τῶν ἐπίπλων ἃ ὁ πατὴρ αὐτοῖς κατέλιπεν, οὐδὲ μετὰ τῶν παρακαταθηκῶν ἃς ἐκεῖνος παρὰ σοὶ κατέθετο.”", "st": "32.16"}, {"sp": "N", "t": "“καὶ νῦν τοὺς μὲν ἐκ τῆς μητρυιᾶς τῆς ἐμῆς παιδεύεις ἐν πολλοῖς χρήμασιν εὐδαίμονας ὄντας· καὶ ταῦτα μὲν καλῶς ποιεῖς· τοὺς δ’ ἐμοὺς ἀδικεῖς, οὓς ἀτίμους ἐκ τῆς οἰκίας ἐκβαλὼν ἀντὶ πλουσίων πτωχοὺς ἀποδεῖξαι προθυμεῖ. καὶ ἐπὶ τοιούτοις ἔργοις οὔτε τοὺς θεοὺς φοβεῖ, οὔτε ἐμὲ τὴν συνειδυῖαν αἰσχύνῃ, οὔτε τοῦ ἀδελφοῦ μέμνησαι, ἀλλὰ πάντας ἡμᾶς περὶ ἐλάττονος ποιεῖ χρημάτων.”", "st": "32.17"}, {"sp": "N", "t": "τότε μὲν οὖν, ὦ ἄνδρες δικασταί, πολλῶν καὶ δεινῶν ὑπὸ τῆς γυναικὸς ῥηθέντων οὕτω διετέθημεν πάντες οἱ παρόντες ὑπὸ τῶν τούτῳ πεπραγμένων καὶ τῶν λόγων τῶν ἐκείνης, ὁρῶντες μὲν τοὺς παῖδας, οἷα ἦσαν πεπονθότες, ἀναμιμνῃσκόμενοι δὲ τοῦ ἀποθανόντος, ὡς ἀνάξιον τῆς οὐσίας τὸν ἐπίτροπον κατέλιπεν, ἐνθυμούμενοι δὲ ὡς χαλεπὸν ἐξευρεῖν ὅτῳ χρὴ περὶ τῶν ἑαυτοῦ πιστεῦσαι, ὥστε, ὦ ἄνδρες δικασταί, μηδένα τῶν παρόντων δύνασθαι φθέγξασθαι, ἀλλὰ καὶ δακρύοντας μὴ ἧττον τῶν πεπονθότων ἀπιόντας οἴχεσθαι σιωπῇ.", "st": "32.18"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τούτων ἀνάβητέ μοι μάρτυρες.", "st": "32.18"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "32.19"}, {"sp": "N", "t": "ἀξιῶ τοίνυν, ὦ ἄνδρες δικασταί, τῷ λογισμῷ προσέχειν τὸν νοῦν, ἵνα τοὺς μὲν νεανίσκους διὰ τὸ μέγεθος τῶν συμφορῶν ἐλεήσητε, τοῦτον δ’ ἅπασι τοῖς πολίταις ἄξιον ὀργῆς ἡγήσησθε. εἰς τοσαύτην γὰρ ὑποψίαν Διογείτων πάντας ἀνθρώπους πρὸς ἀλλήλους καθίστησιν, ὥστε μήτε ζῶντας μήτε ἀποθνῄσκοντας μηδὲν μᾶλλον τοῖς οἰκειοτάτοις ἢ τοῖς ἐχθίστοις πιστεύειν·", "st": "32.19"}, {"sp": "N", "t": "ὃς ἐτόλμησε τὰ μὲν ἔξαρνος γενέσθαι, τὰ δὲ τελευτῶν ὁμολογήσας ἔχειν, εἰς δύο παῖδας καὶ ἀδελφὴν λῆμμα καὶ ἀνάλωμα ἐν ὀκτὼ ἔτεσιν ἑπτὰ τάλαντα ἀργυρίου καὶ ἑπτακισχιλίας δραχμὰς ἀποδεῖξαι. καὶ εἰς τοῦτο ἦλθεν ἀναισχυντίας, ὥστε οὐκ ἔχων ὅποι τρέψειε τὰ χρήματα, εἰς ὄψον μὲν δυοῖν παιδίοιν καὶ ἀδελφῇ πέντε ὀβολοὺς τῆς ἡμέρας ἐλογίζετο, εἰς ὑποδήματα δὲ καὶ εἰς γναφεῖον [ἱμάτια] καὶ εἰς κουρέως κατὰ μῆνα οὐκ ἦν αὐτῷ οὐδὲ κατ’ ἐνιαυτὸν γεγραμμένα, συλλήβδην δὲ παντὸς τοῦ χρόνου πλεῖν ἢ τάλαντον ἀργυρίου.", "st": "32.20"}, {"sp": "N", "t": "εἰς δὲ τὸ μνῆμα τοῦ πατρὸς οὐκ ἀναλώσας πέντε καὶ εἴκοσι μνᾶς ἐκ πεντακισχιλίων δραχμῶν, τὸ μὲν ἥμισυ αὑτῷ τίθησι, ⟨τὸ δὲ⟩ τούτοις λελόγισται. εἰς Διονύσια τοίνυν, ὦ ἄνδρες δικασταί, (οὐκ ἄτοπον γάρ μοι δοκεῖ καὶ περὶ τούτου μνησθῆναι) ἑκκαίδεκα δραχμῶν ἀπέφηνεν ἐωνημένον ἀρνίον, καὶ τούτων τὰς ὀκτὼ δραχμὰς ἐλογίζετο τοῖς παισίν· ἐφ’ ᾧ ἡμεῖς οὐχ ἥκιστα ὠργίσθημεν. οὕτως, ὦ ἄνδρες, ἐν ταῖς μεγάλαις ζημίαις ἐνίοτε οὐχ ἧττον τὰ μικρὰ λυπεῖ τοὺς ἀδικουμένους· λίαν γὰρ φανερὰν τὴν πονηρίαν τῶν ἀδικούντων ἐπιδείκνυσιν.", "st": "32.21"}, {"sp": "N", "t": "εἰς τοίνυν τὰς ἄλλας ἑορτὰς καὶ θυσίας ἐλογίσατο αὐτοῖς πλεῖν ἢ τετρακισχιλίας δραχμὰς ἀνηλωμένας, ἕτερά τε παμπληθῆ, ἃ πρὸς τὸ κεφάλαιον συνελογίζετο, ὥσπερ διὰ τοῦτο ἐπίτροπος τῶν παιδίων καταλειφθείς, ἵνα γράμματα αὐτοῖς ἀντὶ τῶν χρημάτων ἀποδείξειεν καὶ πενεστάτους ἀντὶ πλουσίων ἀποφήνειε, καὶ ἵνα, εἰ μέν τις αὐτοῖς πατρικὸς ἐχθρὸς ἦν, ἐκείνου μὲν ἐπιλάθωνται, τῷ δ’ ἐπιτρόπῳ τῶν πατρῴων ἀπεστερημένοι πολεμῶσι. καίτοι εἰ ἐβούλετο δίκαιος εἶναι περὶ τοὺς παῖδας,", "st": "32.22"}, {"sp": "N", "t": "ἐξῆν αὐτῷ κατὰ τοὺς νόμους, οἳ κεῖνται περὶ τῶν ὀρφανῶν καὶ τοῖς ἀδυνάτοις τῶν ἐπιτρόπων καὶ τοῖς δυναμένοις, μισθῶσαι τὸν οἶκον ἀπηλλαγμένον πολλῶν πραγμάτων, ἢ γῆν πριάμενον ἐκ τῶν προσιόντων τοὺς παῖδας τρέφειν· καὶ ὁπότερα τούτων ἐποίησεν, οὐδενὸς ἂν ἧττον Ἀθηναίων πλούσιοι ἦσαν. νῦν δέ μοι δοκεῖ οὐδεπώποτε διανοηθῆναι ὡς φανερὰν καταστήσων τὴν οὐσίαν, ἀλλ’ ὡς αὐτὸς ἕξων τὰ τούτων, ἡγούμενος δεῖν τὴν αὑτοῦ πονηρίαν κληρονόμον εἶναι τῶν τοῦ τεθνεῶτος χρημάτων.", "st": "32.23"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον, ὦ ⟨ἄνδρες⟩ δικασταί· οὗτος γὰρ συντριηραρχῶν Ἀλέξιδι τῷ Ἀριστοδίκου, φάσκων δυοῖν δεούσας πεντήκοντα μνᾶς ἐκείνῳ συμβαλέσθαι, τὸ ἥμισυ τούτοις ὀρφανοῖς οὖσι λελόγισται, οὓς ἡ πόλις οὐ μόνον παῖδας ὄντας ἀτελεῖς ἐποίησεν, ἀλλὰ καὶ ἐπειδὰν δοκιμασθῶσιν ἐνιαυτὸν ἀφῆκεν ἁπασῶν τῶν λῃτουργιῶν. οὗτος δὲ πάππος ὢν παρὰ τοὺς νόμους τῆς ἑαυτοῦ τριηραρχίας παρὰ τῶν θυγατριδῶν τὸ ἥμισυ πράττεται.", "st": "32.24"}, {"sp": "N", "t": "καὶ ἀποπέμψας εἰς τὸν Ἀδρίαν ὁλκάδα δυοῖν ταλάντοιν, ὅτε μὲν ἀπέστελλεν, ἔλεγε πρὸς τὴν μητέρα αὐτῶν ὅτι τῶν παίδων ὁ κίνδυνος εἴη, ἐπειδὴ δὲ ἐσώθη καὶ ἐδιπλασίασεν, αὑτοῦ τὴν ἐμπορίαν ἔφασκεν εἶναι. καίτοι εἰ μὲν τὰς ζημίας τούτων ἀποδείξει, τὰ δὲ σωθέντα τῶν χρημάτων αὐτὸς ἕξει, ὅποι μὲν ἀνήλωται τὰ χρήματα, οὐ χαλεπῶς εἰς τὸν λόγον ἐγγράψει, ῥᾳδίως δὲ ἐκ τῶν ἀλλοτρίων αὐτὸς πλουτήσει.", "st": "32.25"}, {"sp": "N", "t": "καθ’ ἕκαστον μὲν οὖν, ὦ ⟨ἄνδρες⟩ δικασταί, πολὺ ἂν ἔργον εἴη πρὸς ὑμᾶς λογίζεσθαι· ἐπειδὴ δὲ μόλις παρ’ αὐτοῦ παρέλαβον τὰ γράμματα, μάρτυρας ἔχων ἠρώτων Ἀριστόδικον τὸν ἀδελφὸν τὸν Ἀλέξιδος (αὐτὸς γὰρ ἐτύγχανε τετελευτηκώς), εἰ ὁ λόγος αὐτῷ εἴη ⟨ὁ⟩ τῆς τριηραρχίας· ὁ δὲ ἔφασκεν εἶναι, καὶ ἐλθόντες οἴκαδε ηὕρομεν Διογείτονα τέτταρας καὶ εἴκοσι μνᾶς ἐκείνῳ συμβεβλημένον εἰς τὴν τριηραρχίαν.", "st": "32.26"}, {"sp": "N", "t": "οὗτος δὲ ἀπέδειξε δυοῖν δεούσας πεντήκοντα μνᾶς ἀνηλωκέναι, ὥστε τούτοις λελογίσθαι ὅσονπερ ὅλον τὸ ἀνάλωμα αὐτῷ γεγένηται. καίτοι τί αὐτὸν οἴεσθε πεποιηκέναι περὶ ὧν οὐδεὶς αὐτῷ σύνοιδεν ἀλλ’ αὐτὸς μόνος διεχείριζεν, ὃς ἃ δι’ ἑτέρων ἐπράχθη καὶ οὐ χαλεπὸν ἦν περὶ τούτων πυθέσθαι, ἐτόλμησε ψευσάμενος τέτταρσι καὶ εἴκοσι μναῖς τοὺς αὑτοῦ θυγατριδοῦς ζημιῶσαι; καί μοι ἀνάβητε τούτων μάρτυρες.", "st": "32.27"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "32.28"}, {"sp": "N", "t": "τῶν μὲν μαρτύρων ἀκηκόατε, ὦ ⟨ἄνδρες⟩ δικασταί· ἐγὼ δ’ ὅσα τελευτῶν ὡμολόγησεν ἔχειν αὐτὸς χρήματα, ἑπτὰ τάλαντα καὶ τετταράκοντα μνᾶς, ἐκ τούτων αὐτῷ λογιοῦμαι, πρόσοδον μὲν οὐδεμίαν ἀποφαίνων, ἀπὸ δὲ τῶν ὑπαρχόντων ἀναλίσκων, καὶ θήσω ὅσον οὐδεὶς πώποτ’ ἐν τῇ πόλει, εἰς δύο παῖδας καὶ ἀδελφὴν καὶ παιδαγωγὸν καὶ θεράπαιναν χιλίας δραχμὰς ἑκάστου ἐνιαυτοῦ,", "st": "32.28"}, {"sp": "N", "t": "μικρῷ ἔλαττον ἢ τρεῖς δραχμὰς τῆς ἡμέρας· ἐν ὀκτὼ αὗται ἔτεσι γίγνονται ὀκτακισχίλιαι δραχμαί, καὶ ἀποδείκνυται ἓξ τάλαντα περιόντα [τῶν ἑπτὰ ταλάντων] καὶ εἴκοσι μναῖ. οὐ γὰρ ἂν δύναιτο ἀποδεῖξαι οὔθ’ ὑπὸ λῃστῶν ἀπολωλεκὼς οὔτε ζημίαν εἰληφὼς οὔτε χρήσταις ἀποδεδωκώς. …", "st": "32.29"}, {"sp": "HDR", "t": "ΛΓʹ. Ὀλυμπιακός", "st": "33"}, {"sp": "N", "t": "ἄλλων τε πολλῶν καὶ καλῶν ἔργων ἕνεκα, ὦ ἄνδρες, ἄξιον Ἡρακλέους μεμνῆσθαι, καὶ ὅτι τόνδε τὸν ἀγῶνα πρῶτος συνήγειρε δι’ εὔνοιαν τῆς Ἑλλάδος. ἐν μὲν γὰρ τῷ τέως χρόνῳ ἀλλοτρίως αἱ πόλεις πρὸς ἀλλήλας διέκειντο·", "st": "33.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐκεῖνος τοὺς τυράννους ἔπαυσε καὶ τοὺς ὑβρίζοντας ἐκώλυσεν, ἀγῶνα μὲν σωμάτων ἐποίησε, φιλοτιμίαν ⟨δὲ⟩ πλούτου, γνώμης δ’ ἐπίδειξιν ἐν τῷ καλλίστῳ τῆς Ἑλλάδος, ἵνα τούτων ἁπάντων ἕνεκα εἰς τὸ αὐτὸ συνέλθωμεν, τὰ μὲν ὀψόμενοι, τὰ δ’ ἀκουσόμενοι· ἡγήσατο γὰρ τὸν ἐνθάδε σύλλογον ἀρχὴν γενήσεσθαι τοῖς Ἕλλησι τῆς πρὸς ἀλλήλους φιλίας.", "st": "33.2"}, {"sp": "N", "t": "ἐκεῖνος μὲν οὖν ταῦθ’ ὑφηγήσατο, ἐγὼ δὲ ἥκω οὐ μικρολογησόμενος οὐδὲ περὶ τῶν ὀνομάτων μαχούμενος. ἡγοῦμαι γὰρ ταῦτα ἔργα μὲν εἶναι σοφιστῶν λίαν ἀχρήστων καὶ σφόδρα βίου δεομένων, ἀνδρὸς δὲ ἀγαθοῦ καὶ πολίτου πολλοῦ ἀξίου περὶ τῶν μεγίστων συμβουλεύειν, ὁρῶν οὕτως αἰσχρῶς διακειμένην τὴν Ἑλλάδα, καὶ πολλὰ μὲν αὐτῆς ὄντα ὑπὸ τῷ βαρβάρῳ, πολλὰς δὲ πόλεις ὑπὸ τυράννων ἀναστάτους γεγενημένας. καὶ ταῦτα εἰ μὲν δι’ ἀσθένειαν ἐπάσχομεν,", "st": "33.3"}, {"sp": "N", "t": "στέργειν ἂν ἦν ἀνάγκη τὴν τύχην· ἐπειδὴ δὲ διὰ στάσιν καὶ τὴν πρὸς ἀλλήλους φιλονικίαν, πῶς οὐκ ἄξιον τῶν μὲν παύσασθαι τὰ δὲ κωλῦσαι, εἰδότας ὅτι φιλονικεῖν μέν ἐστιν εὖ πραττόντων, γνῶναι δὲ τὰ βέλτιστα τῶν οἵων ἡμῶν;", "st": "33.4"}, {"sp": "N", "t": "ὁρῶμεν γὰρ τοὺς κινδύνους καὶ μεγάλους καὶ πανταχόθεν περιεστηκότας· ἐπίστασθε δὲ ὅτι ἡ μὲν ἀρχὴ τῶν κρατούντων τῆς θαλάττης, τῶν δὲ χρημάτων βασιλεὺς ταμίας, τὰ δὲ τῶν Ἑλλήνων σώματα τῶν δαπανᾶσθαι δυναμένων, ναῦς δὲ πολλὰς ⟨μὲν⟩ αὐτὸς κέκτηται, πολλὰς δ’ ὁ τύραννος τῆς Σικελίας.", "st": "33.5"}, {"sp": "N", "t": "ὥστε ἄξιον τὸν μὲν πρὸς ἀλλήλους πόλεμον καταθέσθαι, τῇ δ’ αὐτῇ γνώμῃ χρωμένους τῆς σωτηρίας ἀντέχεσθαι, καὶ περὶ μὲν τῶν παρεληλυθότων αἰσχύνεσθαι, περὶ δὲ τῶν μελλόντων ἔσεσθαι δεδιέναι, καὶ πρὸς τοὺς προγόνους, οἳ τοὺς μὲν βαρβάρους ἐποίησαν τῆς ἀλλοτρίας ἐπιθυμοῦντας τῆς σφετέρας αὐτῶν στερεῖσθαι, τοὺς δὲ τυράννους ἐξελάσαντες κοινὴν ἅπασι τὴν ἐλευθερίαν κατέστησαν.", "st": "33.6"}, {"sp": "N", "t": "θαυμάζω δὲ Λακεδαιμονίους πάντων μάλιστα, τίνι ποτὲ γνώμῃ χρώμενοι καομένην τὴν Ἑλλάδα περιορῶσιν, ἡγεμόνες ὄντες τῶν Ἑλλήνων οὐκ ἀδίκως, καὶ διὰ τὴν ἔμφυτον ἀρετὴν καὶ διὰ τὴν πρὸς τὸν πόλεμον ἐπιστήμην, μόνοι δὲ οἰκοῦντες ἀπόρθητοι καὶ ἀτείχιστοι καὶ ἀστασίαστοι καὶ ἀήττητοι καὶ τρόποις ἀεὶ τοῖς αὐτοῖς χρώμενοι· ὧν ἕνεκα ἐλπὶς ἀθάνατον τὴν ἐλευθερίαν αὐτοὺς κεκτῆσθαι, καὶ ἐν τοῖς παρεληλυθόσι κινδύνοις σωτῆρας γενομένους τῆς Ἑλλάδος περὶ τῶν μελλόντων προορᾶσθαι.", "st": "33.7"}, {"sp": "N", "t": "οὐ τοίνυν ὁ ἐπιὼν καιρὸς τοῦ παρόντος βελτίων· οὐ γὰρ ἀλλοτρίας δεῖ τὰς τῶν ἀπολωλότων συμφορὰς νομίζειν ἀλλ’ οἰκείας, οὐδ’ ἀναμεῖναι, ἕως ἂν ἐπ’ αὐτοὺς ἡμᾶς αἱ δυνάμεις ἀμφοτέρων ἔλθωσιν, ἀλλ’ ἕως ἔτι ἔξεστι, τὴν τούτων τούτων ὕβριν κωλῦσαι.", "st": "33.8"}, {"sp": "N", "t": "τίς γὰρ οὐκ ἂν ⟨ἀγανακτήσει⟩εν ὁρῶν ἐν τῷ πρὸς ἀλλήλους πολέμῳ μεγάλους αὐτοὺς γεγενημένους; ὧν οὐ μόνον αἰσχρῶν ὄντων ἀλλὰ καὶ δεινῶν, τοῖς μὲν μεγάλα ἡμαρτηκόσιν ἐξουσία γεγένηται τῶν πεπραγμένων, τοῖς δὲ Ἕλλησιν οὐδεμία αὐτῶν τιμωρία …", "st": "33.9"}, {"sp": "HDR", "t": "ΛΔʹ. Περὶ τοῦ μὴ καταλῦσαι τὴν πάτριον πολιτείαν Ἀθήνησι", "st": "34"}, {"sp": "N", "t": "ὅτε ἐνομίζομεν, ὦ Ἀθηναῖοι, τὰς γεγενημένας συμφορὰς ἱκανὰ μνημεῖα τῇ πόλει καταλελεῖφθαι, ὥστε μηδ’ ἂν τοὺς ἐπιγιγνομένους ἑτέρας πολιτείας ἐπιθυμεῖν, τότε δὴ οὗτοι τοὺς κακῶς πεπονθότας καὶ ἀμφοτέρων πεπειραμένους ἐξαπατῆσαι ζητοῦσι τοῖς αὐτοῖς ψηφίσμασιν, οἷσπερ καὶ πρότερον δὶς ἤδη.", "st": "34.1"}, {"sp": "N", "t": "καὶ τούτων μὲν οὐ θαυμάζω, ὑμῶν δὲ τῶν ἀκροωμένων, ὅτι πάντων ἐστὲ ἐπιλησμονέστατοι ἢ πάσχειν ἑτοιμότατοι κακῶς ὑπὸ τοιούτων ἀνδρῶν, οἳ τῇ μὲν τύχῃ τῶν Πειραιοῖ πραγμάτων μετέσχον, τῇ δὲ γνώμῃ τῶν ἐξ ἄστεως. καίτοι τί ἔδει φεύγοντας κατελθεῖν, εἰ χειροτονοῦντες ὑμᾶς αὐτοὺς καταδουλώσεσθε;", "st": "34.2"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν, ὦ Ἀθηναῖοι, ⟨οὔτε οὐσίᾳ⟩ οὔτε γένει ἀπελαυνόμενος, ἀλλ’ ἀμφότερα τῶν ἀντιλεγόντων πρότερος ὤν, ἡγοῦμαι ταύτην μόνην σωτηρίαν εἶναι τῇ πόλει, ἅπασιν Ἀθηναίοις τῆς πολιτείας μετεῖναι, ἐπεὶ καὶ ὅτε τὰ τείχη καὶ τὰς ναῦς καὶ [τὰ] χρήματα καὶ συμμάχους ἐκτησάμεθα, οὐχ ὅπως τινὰ Ἀθηναῖον ἀπώσομεν διενοούμεθα, ἀλλὰ καὶ Εὐβοεῦσιν ἐπιγαμίαν ἐποιούμεθα· ⟨νῦν δὲ⟩ καὶ τοὺς ὑπάρχοντας πολίτας ἀπελῶμεν;", "st": "34.3"}, {"sp": "N", "t": "οὔκ, ἐὰν ἔμοιγε πείθησθε, οὐδὲ μετὰ τῶν τειχῶν καὶ ταῦτα ἡμῶν αὐτῶν περιαιρησόμεθα, ὁπλίτας πολλοὺς καὶ ἱππέας καὶ τοξότας, ὧν ὑμεῖς ἀντεχόμενοι βεβαίως δημοκρατήσεσθε, τῶν δὲ ἐχθρῶν πλέον ἐπικρατήσετε, ὠφελιμώτεροι δὲ τοῖς συμμάχοις ἔσεσθε· ἐπίστασθε γὰρ ⟨ἐν⟩ ταῖς ἐφ’ ἡμῶν ὀλιγαρχίαις γεγενημέναις [καὶ] οὐ τοὺς γῆν κεκτημένους ἔχοντας τὴν πόλιν, ἀλλὰ πολλοὺς μὲν αὐτῶν ἀποθανόντας, πολλοὺς δ’ ἐκ τῆς πόλεως ἐκπεσόντας,", "st": "34.4"}, {"sp": "N", "t": "οὓς ὁ δῆμος καταγαγὼν ὑμῖν μὲν τὴν ὑμετέραν ἀπέδωκεν, αὐτὸς δὲ ταύτης οὐκ ἐτόλμησε μετασχεῖν. ὥστ’, ἐὰν ἔμοιγε πείθησθε, οὐ τοὺς εὐεργέτας, καθὸ δύνασθε, τῆς πατρίδος ἀποστερήσετε, οὐδὲ τοὺς λόγους πιστοτέρους τῶν ἔργων οὐδὲ τὰ μέλλοντα τῶν γεγενημένων νομιεῖτε, ἄλλως τε καὶ μεμνημένοι τῶν περὶ τῆς ὀλιγαρχίας μαχομένων, οἳ τῷ μὲν λόγῳ τῷ δήμῳ πολεμοῦσι, τῷ δὲ ἔργῳ τῶν ὑμετέρων ἐπιθυμοῦσιν· ἅπερ κτήσονται, ὅταν ὑμᾶς ἐρήμους συμμάχων λάβωσιν.", "st": "34.5"}, {"sp": "N", "t": "εἶτα τοιούτων ἡμῖν ὑπαρχόντων ἐρωτῶσι τίς ἔσται σωτηρία τῇ πόλει, εἰ μὴ ποιήσομεν ⟨ἃ⟩ Λακεδαιμόνιοι κελεύουσιν; ἐγὼ δὲ τούτους εἰπεῖν ἀξιῶ, τίς τῷ πλήθει περιγενήσεται, εἰ ποιήσομεν ἃ ἐκεῖνοι προστάττουσιν; εἰ δὲ μή, πολὺ κάλλιον μαχομένοις ἀποθνῄσκειν ἢ φανερῶς ἡμῶν αὐτῶν θάνατον καταψηφίσασθαι.", "st": "34.6"}, {"sp": "N", "t": "ἡγοῦμαι γάρ, ἐὰν μὲν πείσω, ἀμφοτέροις κοινὸν εἶναι ⟨τὸν⟩ κίνδυνον … ὁρῶ δὲ καὶ Ἀργείους καὶ Μαντινέας τὴν αὐτὴν ἔχοντας γνώμην τὴν αὑτῶν οἰκοῦντας, τοὺς μὲν ὁμόρους ὄντας Λακεδαιμονίοις, τοὺς δ’ ἐγγὺς οἰκοῦντας, καὶ τοὺς μὲν οὐδὲν ἡμῶν πλείους, τοὺς δὲ οὐδὲ τρισχιλίους ὄντας.", "st": "34.7"}, {"sp": "N", "t": "ἴσασι γὰρ ⟨ἐκεῖνοι⟩ ὅτι, κἂν πολλάκις εἰς τὴν τούτων ἐμβάλλωσι, πολλάκις αὐτοῖς ἀπαντήσονται ὅπλα λαβόντες, ὥστε οὐ καλὸς αὐτοῖς ὁ κίνδυνος δοκεῖ εἶναι, ἐὰν μὲν νικήσωσι, τούτους ⟨μὴ⟩ καταδουλώσασθαί γε, ἐὰν δὲ ἡττηθῶσι, σφᾶς αὐτοὺς τῶν ὑπαρχόντων ἀγαθῶν ἀποστερῆσαι. ὅσῳ δ’ ἂν ἄμεινον πράττωσι, τοσούτῳ ⟨ἧττον⟩ ἐπιθυμοῦσι κινδυνεύειν.", "st": "34.8"}, {"sp": "N", "t": "εἴχομεν δέ, ὦ Ἀθηναῖοι, καὶ ἡμεῖς ταύτην τὴν γνώμην, ὅτε τῶν Ἑλλήνων ἤρχομεν, καὶ ἐδοκοῦμεν καλῶς βουλεύεσθαι περιορῶντες μὲν τὴν χώραν τεμνομένην, οὐ νομίζοντες δὲ χρῆναι περὶ αὐτῆς διαμάχεσθαι· ἄξιον γὰρ ἦν ὀλίγων ἀμελοῦντας πολλῶν ἀγαθῶν φείσασθαι. νῦν δέ, ἐπεὶ ἐκείνων μὲν ἁπάντων μάχῃ ἐστερήμεθα, ἡ δὲ πατρὶς ἡμῖν λέλειπται, ἴσμεν ὅτι ὁ κίνδυνος οὗτος μόνος ἔχει τὰς ἐλπίδας τῆς σωτηρίας.", "st": "34.9"}, {"sp": "N", "t": "ἀλλὰ γὰρ χρὴ ἀναμνησθέντας ὅτι ἤδη καὶ ἑτέροις ἀδικουμένοις βοηθήσαντες ἐν τῇ ἀλλοτρίᾳ πολλὰ τρόπαια τῶν πολεμίων ἐστήσαμεν, ἄνδρας ἀγαθοὺς περὶ τῆς πατρίδος καὶ ἡμῶν αὐτῶν γίγνεσθαι, πιστεύοντας μὲν τοῖς θεοῖς, ἐλπίζοντας δὲ ἔτι τὸ δίκαιον μετὰ τῶν ἀδικουμένων ἔσεσθαι.", "st": "34.10"}, {"sp": "N", "t": "δεινὸν γὰρ ἂν εἴη, ὦ Ἀθηναῖοι, εἰ, ὅτε μὲν ἐφεύγομεν, ἐμαχόμεθα Λακεδαιμονίοις, ἵνα κατέλθωμεν, κατελθόντες δὲ φευξόμεθα, ἵνα μὴ μαχώμεθα. οὐκ οὖν αἰσχρὸν εἰ εἰς τοῦτο κακίας ἥξομεν, ὥστε οἱ μὲν πρόγονοι καὶ ὑπὲρ τῆς τῶν ἄλλων ἐλευθερίας διεκινδύνευον, ὑμεῖς δὲ οὐδὲ ὑπὲρ τῆς ὑμετέρας αὐτῶν τολμᾶτε πολεμεῖν; …", "st": "34.11"}], []);})();
